@dataclass
class FontPack:
    """Fonts used by the CJK typesetting engine.

    ``regular``/``bold``/``fallback`` are fitz.Font objects for measurement;
    the *_file paths are registered on each page under fixed aliases.
    """

    regular: object
    regular_file: Path
    bold: object
    bold_file: Path
    fallback: Optional[object] = None
    fallback_file: Optional[Path] = None
    math_fallback: Optional[object] = None
    math_fallback_file: Optional[Path] = None
    regular_alias: str = "zhbody"
    bold_alias: str = "zhbold"
    fallback_alias: str = "zhfall"
    math_fallback_alias: str = "zhmath"

    def fonts_for(self, bold: bool) -> List[Tuple[object, str]]:
        """Measurement font + alias, in fallback order."""
        primary = (self.bold, self.bold_alias) if bold else (self.regular, self.regular_alias)
        chain = [primary]
        if self.fallback is not None:
            chain.append((self.fallback, self.fallback_alias))
        # Last resort: the other weight often covers extra glyphs.
        chain.append((self.regular, self.regular_alias) if bold else (self.bold, self.bold_alias))
        if self.math_fallback is not None:
            chain.append((self.math_fallback, self.math_fallback_alias))
        return chain


def open_pdf_detached(pdf_path: Path) -> object:
    """Open a PDF without leaving mupdf mmapped onto the file.

    mupdf memory-maps documents opened by path. When the file lives in a
    sync-managed folder (iCloud Drive on this workspace) the provider can
    dematerialize it while the process runs: the next page fault on the
    mapping raises SIGBUS/SIGSEGV, which is how long benchmark sessions
    died mid-run (rc=138/139) and how golden fixtures turned into
    "no objects found" errors. Reading the bytes first both forces
    materialization and detaches the document from the file.
    """
    try:
        import fitz
    except ImportError as exc:
        raise RuntimeError("PyMuPDF is required. Install with: pip install -e .") from exc

    return fitz.open(stream=Path(pdf_path).read_bytes(), filetype="pdf")


def _redistribute_duplicated_cross_page_translations(
    document: object,
    units: Sequence[TranslationUnit],
    cleaned_results: Sequence[Tuple[str, List[int]]],
    *,
    font_pack: FontPack,
    min_font_size: float,
    font_scale: float,
    margin: float,
) -> Tuple[List[Tuple[str, List[int]]], int]:
    """Split one duplicated translation across a genuine page break.

    Providers sometimes complete an unfinished page-bottom sentence from
    context, then return either the same complete translation or its correct
    suffix for the continuation unit on the next page. Rendering both copies
    shrinks the first into a single source line and duplicates the paragraph.
    Exact duplication or strict long-suffix overlap is a strong ownership
    signal: retain one copy and distribute it according to the two source
    boxes' full-size capacity.
    """
    adjusted = list(cleaned_results)
    used_continuations: set[int] = set()
    redistributed = 0

    for index, ((block, _, _), (translated, missing)) in enumerate(
        zip(units, adjusted)
    ):
        source_plain = " ".join(strip_sentinels(block.text).split()).strip()
        page_height = float(document[block.page_index].rect.height)
        normalized_translation = "".join(translated.split())
        if (
            block.block_type not in {"body", "formula_prose"}
            or block.nowrap
            or block.preserve_position
            or block.formula_anchors
            or sentinel_char_count(block.text)
            or sentinel_char_count(translated)
            or sentence_final_text(source_plain)
            or page_height - block.bbox[3] > max(36.0, block.font_size * 4.0)
            or len(normalized_translation) < 50
            or not _CJK_DETECT_RE.search(translated)
        ):
            continue

        continuation_index: Optional[int] = None
        continuation_owned_suffix = False
        for candidate_index in range(index + 1, len(units)):
            if candidate_index in used_continuations:
                continue
            continuation = units[candidate_index][0]
            if continuation.page_index > block.page_index + 1:
                break
            if continuation.page_index != block.page_index + 1:
                continue
            continuation_plain = " ".join(
                strip_sentinels(continuation.text).split()
            ).strip()
            candidate_translation = adjusted[candidate_index][0]
            candidate_clean = candidate_translation.strip()
            candidate_normalized = "".join(candidate_clean.split())
            exact_duplicate = candidate_normalized == normalized_translation
            strict_suffix_overlap = bool(
                candidate_clean
                and translated.rstrip().endswith(candidate_clean)
                and len(candidate_normalized) >= 50
                and len(normalized_translation) - len(candidate_normalized) >= 4
                and len(candidate_normalized) / len(normalized_translation) >= 0.50
            )
            horizontal_overlap = min(block.bbox[2], continuation.bbox[2]) - max(
                block.bbox[0], continuation.bbox[0]
            )
            narrower_width = min(
                block.bbox[2] - block.bbox[0],
                continuation.bbox[2] - continuation.bbox[0],
            )
            if (
                continuation.block_type not in {"body", "formula_prose"}
                or continuation.nowrap
                or continuation.preserve_position
                or continuation.formula_anchors
                or sentinel_char_count(continuation.text)
                or sentinel_char_count(candidate_translation)
                or not re.match(r"^[a-z]", continuation_plain)
                or horizontal_overlap < max(1.0, narrower_width) * 0.65
                or not (exact_duplicate or strict_suffix_overlap)
            ):
                continue
            continuation_index = candidate_index
            continuation_owned_suffix = strict_suffix_overlap
            break
        if continuation_index is None:
            continue

        continuation = units[continuation_index][0]
        first_size = requested_translation_font_size(
            block,
            min_font_size,
            font_scale,
        )
        continuation_size = requested_translation_font_size(
            continuation,
            min_font_size,
            font_scale,
        )
        if translated_text_fits(
            block,
            translated,
            font_pack,
            first_size,
            first_size,
            margin,
        ):
            continue

        if continuation_owned_suffix:
            continuation_text = adjusted[continuation_index][0].strip()
            prefix = translated.rstrip()[: -len(continuation_text)].rstrip()
            if (
                prefix
                and translated_text_fits(
                    block,
                    prefix,
                    font_pack,
                    first_size,
                    first_size,
                    margin,
                )
                and translated_text_fits(
                    continuation,
                    continuation_text,
                    font_pack,
                    continuation_size,
                    continuation_size,
                    margin,
                )
            ):
                adjusted[index] = (prefix, missing)
                adjusted[continuation_index] = (
                    continuation_text,
                    adjusted[continuation_index][1],
                )
                used_continuations.add(continuation_index)
                redistributed += 1
            continue

        low = 1
        high = len(translated) - 1
        split_at = 0
        while low <= high:
            midpoint = (low + high) // 2
            prefix = translated[:midpoint].rstrip()
            if prefix and translated_text_fits(
                block,
                prefix,
                font_pack,
                first_size,
                first_size,
                margin,
            ):
                split_at = midpoint
                low = midpoint + 1
            else:
                high = midpoint - 1
        try:
            from pdf_zh_translator.corpus import get_relevant_terms

            trailing_terms = get_relevant_terms([source_plain[-160:]], max_terms=20)
        except Exception:
            trailing_terms = {}
        for english, chinese in sorted(
            trailing_terms.items(),
            key=lambda item: len(item[0]),
            reverse=True,
        ):
            if not re.search(
                rf"\b{re.escape(english.casefold())}[\s.,;:()]*$",
                source_plain.casefold(),
            ):
                continue
            term_start = translated.rfind(chinese, 0, split_at + 1)
            if term_start < 0:
                continue
            term_boundary = term_start + len(chinese)
            if translated_text_fits(
                block,
                translated[:term_boundary].rstrip(),
                font_pack,
                first_size,
                first_size,
                margin,
            ):
                split_at = term_boundary
                break
        while (
            1 < split_at < len(translated)
            and translated[split_at - 1].isascii()
            and translated[split_at - 1].isalnum()
            and translated[split_at].isascii()
            and translated[split_at].isalnum()
        ):
            split_at -= 1
        if split_at <= 0:
            continue

        prefix = translated[:split_at].rstrip()
        suffix = translated[split_at:].lstrip()
        if not prefix or not suffix or not translated_text_fits(
            continuation,
            suffix,
            font_pack,
            continuation_size,
            continuation_size,
            margin,
        ):
            continue

        adjusted[index] = (prefix, missing)
        adjusted[continuation_index] = (
            suffix,
            adjusted[continuation_index][1],
        )
        used_continuations.add(continuation_index)
        redistributed += 1

    return adjusted, redistributed


def _move_orphaned_cross_column_translation_connectors(
    units: Sequence[TranslationUnit],
    cleaned_results: Sequence[Tuple[str, List[int]]],
) -> Tuple[List[Tuple[str, List[int]]], int]:
    """Move a translated conjunction to its same-page continuation column.

    Two-column PDFs can split one sentence after an English conjunction at
    the bottom of the left column. Providers then translate the two source
    objects independently, leaving a one-word CJK conjunction as the final
    glyph in that column. Move only that conjunction to the front of the
    geometrically unambiguous lowercase continuation in the next column.
    """
    adjusted = list(cleaned_results)
    moved = 0
    connector_by_source = {
        "and": ("并且", "以及", "与", "和", "及", "且", "并"),
        "or": ("或者", "或"),
    }
    for index in range(len(units) - 1):
        previous = units[index][0]
        following = units[index + 1][0]
        previous_source = " ".join(
            strip_sentinels(previous.text).split()
        ).strip()
        following_source = " ".join(
            strip_sentinels(following.text).split()
        ).strip()
        source_connector = re.search(r"\b(and|or)\s*$", previous_source, re.I)
        if (
            source_connector is None
            or previous.page_index != following.page_index
            or previous.block_type not in {"body", "formula_prose"}
            or following.block_type not in {"body", "formula_prose"}
            or not re.match(r"^[a-z]", following_source)
            or following.bbox[0] < previous.bbox[2] + 12.0
            or previous.bbox[1] - following.bbox[1]
            < max(60.0, min(previous.font_size, following.font_size) * 6.0)
        ):
            continue

        previous_translation, previous_missing = adjusted[index]
        following_translation, following_missing = adjusted[index + 1]
        stripped_previous = previous_translation.rstrip()
        connector = next(
            (
                candidate
                for candidate in connector_by_source[
                    source_connector.group(1).casefold()
                ]
                if stripped_previous.endswith(candidate)
            ),
            None,
        )
        if (
            connector is None
            or len(stripped_previous) <= len(connector)
            or not following_translation.strip()
            or following_translation.lstrip().startswith(connector)
        ):
            continue
        prefix = stripped_previous[: -len(connector)].rstrip()
        continuation = f"{connector}{following_translation.lstrip()}"
        adjusted[index] = (prefix, previous_missing)
        adjusted[index + 1] = (continuation, following_missing)
        moved += 1

    return adjusted, moved


_COMPACT_FORMULA_CONNECTOR_TRANSLATIONS = {
    "and": "及",
    "for": "对",
    "if": "若",
    "or": "或",
    "when": "当",
    "with": "含",
}


def _fit_formula_connector_translation(
    block: TextBlock,
    translated_text: str,
) -> str:
    """Keep translated formula prose concise enough for its source slots."""
    source = " ".join(strip_sentinels(block.text).split()).casefold()
    compacted = translated_text
    if block.keepout_formula_atom_groups:
        if (
            "stochastic maximum entropy" in source
            and "learns to maximize" in source
        ):
            compacted = compacted.replace("是一个", "是").replace(
                "策略，学习最大化",
                "策略，以最大化",
            )
        if "covariance matrix" in source and "shared first part" in source:
            compacted = compacted.replace("由于", "因", 1)
            compacted = compacted.replace(
                "（及其梯度）是对称的",
                "及其梯度对称",
            )
            compacted = compacted.replace(
                "共享的第一部分可通过",
                "共享项可由",
            ).replace("紧凑地求得", "求得")

    compact = _COMPACT_FORMULA_CONNECTOR_TRANSLATIONS.get(source)
    if compact is None or block.source_lines != 1:
        return compacted
    formula_owned_slot = block.block_type == "formula_prose" or any(
        bbox_intersection_area(block.bbox, keepout)
        / max(1.0, bbox_area(block.bbox))
        >= 0.8
        for keepout in (block.keepout_bboxes or [])
    )
    if not formula_owned_slot:
        return translated_text
    cjk_glyphs = sum(1 for char in translated_text if is_cjk_char(char))
    available_width = max(1.0, block.bbox[2] - block.bbox[0] - 1.6)
    if cjk_glyphs * max(1.0, block.font_size) <= available_width:
        return compacted
    return compact


def translate_pdf(
    input_pdf: Path,
    output_pdf: Path,
    translator: object,
    font_name: str = "china-s",
    font_file: Optional[Path] = None,
    min_font_size: float = 5.0,
    font_scale: float = 0.92,
    margin: float = 0.8,
    preserve_graphics_text: bool = False,
    skip_overflow: bool = False,
) -> TranslationReport:
    try:
        import fitz
    except ImportError as exc:
        raise RuntimeError("PyMuPDF is required. Install with: pip install -e .") from exc

    warnings: List[str] = []
    font_pack = build_font_pack(font_file, warnings)

    document = open_pdf_detached(input_pdf)
    try:
        from .layout_profiles import detect_layout_profile

        profile = detect_layout_profile(document)
        warnings.append(
            "Detected layout profile: %s (confidence %.2f, %d column%s)"
            % (
                profile.name,
                profile.confidence,
                profile.columns,
                "" if profile.columns == 1 else "s",
            )
        )
    except Exception:
        pass
    preserved_regions: Dict[int, List[BBox]] = {}
    equation_rows: Dict[int, List[BBox]] = {}
    units, gutter_rects, skipped = prepare_translation_units(
        document,
        preserve_graphics_text=preserve_graphics_text,
        preserved_regions_out=(preserved_regions if preserve_graphics_text else None),
        equation_rows_out=equation_rows,
    )
    warnings.extend(fragmented_prose_warnings_from_units(units))

    if not units:
        warnings.append("No extractable English text was found. Scanned PDFs need OCR.")
        page_count = document.page_count
        save_pdf_for_fast_web_view(
            document,
            output_pdf,
            warnings,
            preserve_source_fonts=preserve_graphics_text,
        )
        document.close()
        return TranslationReport(input_pdf, output_pdf, page_count, 0, skipped, warnings)

    source_document = open_pdf_detached(input_pdf)

    block_types = [block.block_type for block, _, _ in units]
    acronym_expansions = _document_acronym_expansions(units)

    # Set block types for context-aware translation prompts
    if hasattr(translator, "block_types"):
        translator.block_types = block_types
    translations, request_count, response_count = _translate_units_with_source_style_runs(
        translator,
        units,
        acronym_expansions,
    )
    if response_count != request_count:
        warnings.append(
            "Translator returned %d block(s) for %d source block(s)"
            % (response_count, request_count)
        )

    cleaned_results = []
    for (block, _, mapping), translated_text in zip(units, translations):
        restored_text, missing = _restore_unit_translation(
            translated_text,
            mapping,
            block,
        )
        cleaned_results.append(
            (_fit_formula_connector_translation(block, restored_text), missing)
        )
    retry_indexes = [
        index
        for index, ((block, _, _), (translated_text, _)) in enumerate(zip(units, cleaned_results))
        if _translated_block_still_english(block, translated_text)
    ]
    if retry_indexes:
        quality_retry_supported = hasattr(translator, "quality_retry")
        if quality_retry_supported:
            translator.quality_retry = True
        try:
            if hasattr(translator, "block_types"):
                translator.block_types = [units[index][0].block_type for index in retry_indexes]
            retry_units = []
            for index in retry_indexes:
                block, protected_source, mapping = units[index]
                if (
                    block.block_type == "body"
                    or _source_looks_like_foreign_example(protected_source)
                ):
                    block = replace(block, block_type="foreign_example")
                retry_units.append((block, protected_source, mapping))
            invalidate = getattr(translator, "invalidate", None)
            if callable(invalidate):
                retry_sources, _, _ = _source_style_translation_plan(
                    translator,
                    retry_units,
                    acronym_expansions,
                )
                invalidate(retry_sources)
            retry_outputs, _, _ = _translate_units_with_source_style_runs(
                translator,
                retry_units,
                acronym_expansions,
            )
            for index, retry_text in zip(retry_indexes, retry_outputs):
                retry_cleaned, retry_missing = _restore_unit_translation(
                    retry_text,
                    units[index][2],
                    units[index][0],
                )
                retained_phrases = list(
                    dict.fromkeys(
                        [
                            *_retained_source_prose_phrases(
                                units[index][0],
                                retry_cleaned,
                            ),
                            *_retained_bracketed_natural_language(
                                _text_outside_sentinels(retry_cleaned)
                            ),
                        ]
                    )
                )
                if (
                    retained_phrases
                    and _translated_block_still_english(
                        units[index][0],
                        retry_cleaned,
                    )
                ):
                    if hasattr(translator, "block_types"):
                        translator.block_types = ["foreign_example"] * len(
                            retained_phrases
                        )
                    if callable(invalidate):
                        invalidate(retained_phrases)
                    phrase_translations = list(
                        translator.translate_batch(retained_phrases)
                    )
                    if len(phrase_translations) == len(retained_phrases):
                        for phrase, translated_phrase in zip(
                            retained_phrases,
                            phrase_translations,
                        ):
                            translated_phrase = _focused_foreign_phrase_translation(
                                phrase,
                                translated_phrase,
                            )
                            if translated_phrase:
                                retry_cleaned = retry_cleaned.replace(
                                    phrase,
                                    translated_phrase,
                                )
                if not _translated_block_still_english(units[index][0], retry_cleaned):
                    cleaned_results[index] = (retry_cleaned, retry_missing)
        finally:
            if quality_retry_supported:
                translator.quality_retry = False
            if hasattr(translator, "block_types"):
                translator.block_types = block_types

    cleaned_results, redistributed_cross_page = (
        _redistribute_duplicated_cross_page_translations(
            document,
            units,
            cleaned_results,
            font_pack=font_pack,
            min_font_size=min_font_size,
            font_scale=font_scale,
            margin=margin,
        )
    )
    if redistributed_cross_page:
        warnings.append(
            "Redistributed %d duplicated cross-page translation(s) at body size"
            % redistributed_cross_page
        )

    cleaned_results, moved_cross_column_connectors = (
        _move_orphaned_cross_column_translation_connectors(
            units,
            cleaned_results,
        )
    )
    if moved_cross_column_connectors:
        warnings.append(
            "Moved %d orphaned connector(s) to the continuation column"
            % moved_cross_column_connectors
        )

    by_page: Dict[int, List[Tuple[TextBlock, str]]] = {}
    kept_verbatim = 0
    for (block, _, _), (translated_text, missing) in zip(units, cleaned_results):
        if missing:
            warnings.append(
                "Page %d: translator dropped %d placeholder(s); fragments appended at block end"
                % (block.page_index + 1, len(missing))
            )
        if _translation_repeats_source(block, translated_text):
            # A name, a code token or a bare label came back unchanged. The
            # source glyphs are the best possible rendering of that text:
            # leave them alone instead of re-setting them from the CJK chain.
            kept_verbatim += 1
            continue
        if _translated_block_still_english(block, translated_text):
            warnings.append(
                "Page %d: translated %s block still looks like English after retry"
                % (block.page_index + 1, block.block_type)
            )
        by_page.setdefault(block.page_index, []).append((block, translated_text))
    if kept_verbatim:
        warnings.append(
            "Kept %d block(s) in their source typesetting: translation repeated the source"
            % kept_verbatim
        )

    for page_index in range(document.page_count):
        candidate_items = _combine_formula_continuation_translation_items(
            _combine_academic_formula_statement_translation_items(
                _combine_list_continuation_translation_items(
                    _combine_inline_style_translation_items(by_page.get(page_index, []))
                )
            )
        )
        page_gutter = gutter_rects.get(page_index, [])
        if not candidate_items and not page_gutter:
            continue
        page = document[page_index]
        page_width = page.rect.width
        page_columns = detect_columns([block for block, _ in candidate_items])
        centered_flags = detect_centered_blocks(
            [block for block, _ in candidate_items], page_width
        )
        # Float obstacles (figures/tables/captions) that reflowed CJK must avoid.
        page_floats = list(_visual_regions_for_page(page))
        page_floats.extend(preserved_regions.get(page_index, []))
        # Hairline frames (boxed prompts, framed notes): translated prose may
        # neither widen across their vertical rules nor grow across the
        # horizontal ones. Rules running through a candidate's own rows are
        # underlines, not frames.
        frame_horizontal, frame_vertical = _page_frame_rule_bboxes(page)
        candidate_bboxes = [candidate.bbox for candidate, _ in candidate_items]
        frame_horizontal = [
            rule
            for rule in frame_horizontal
            if not any(
                bbox[1] + 1.0 < rule[1] < bbox[3] - 1.0
                and min(bbox[2], rule[2]) - max(bbox[0], rule[0]) > 0.0
                for bbox in candidate_bboxes
            )
        ]
        page_frame_rules = (frame_horizontal, frame_vertical)
        relax_caption_boxes(page, candidate_items, obstacles=page_floats)
        page_floats.extend(
            block.bbox
            for block, _ in candidate_items
            if block.preserve_position
            or block.nowrap
            or block.block_type in ("caption", "figure_label", "table", "equation", "algorithm")
        )
        page_items: List[Tuple[TextBlock, str]] = []
        item_centered_flags: List[bool] = []
        for (block, translated_text), centered in zip(candidate_items, centered_flags):
            plain_block_text = " ".join(strip_sentinels(block.text).split()).strip()
            bullet_count = len(re.findall(r"(?:^|\s)[•◦▪●]\s+", plain_block_text))
            if (
                re.match(
                    r"^(?:[•◦▪●]|\(?[a-zA-Z0-9]{1,3}\)|[-–])\s+",
                    plain_block_text,
                )
                and bullet_count <= 1
                and "action skeleton" not in plain_block_text.lower()
                and not looks_like_action_skeleton_sequence(plain_block_text)
                and not _has_parallel_panel_sibling(
                    block,
                    [candidate for candidate, _ in candidate_items],
                )
            ):
                containing_columns = [
                    column
                    for column in page_columns
                    if column[0] - 4.0 <= block.bbox[0] <= column[0] + column[1] + 4.0
                ]
                if containing_columns:
                    column_left, column_width = min(
                        containing_columns,
                        key=lambda column: abs(block.bbox[0] - column[0]),
                    )
                    column_right = min(float(page_width), column_left + column_width)
                    if column_right > block.bbox[2] + 1.0:
                        block = replace(
                            block,
                            bbox=(
                                block.bbox[0],
                                block.bbox[1],
                                column_right,
                                block.bbox[3],
                            ),
                        )
            preserved_keepouts = _preserved_keepout_regions(
                block,
                preserved_regions.get(page_index, []),
            )
            if preserved_keepouts:
                block = replace(
                    block,
                    keepout_bboxes=list(
                        dict.fromkeys(
                            [*(block.keepout_bboxes or []), *preserved_keepouts]
                        )
                    ),
                )
            # Preserve anchored labels, but keep visually centered captions centered.
            if block.block_type == "caption" and caption_should_center(block, page_width):
                block = center_caption_bbox(block, page_width)
                centered = True
            elif block.preserve_position:
                centered = False
            block = expand_heading_bbox(block)
            block = _expand_header_bbox_upward(block)
            block = _expand_standalone_heading_to_column(
                block,
                page_columns,
                page_width,
                [candidate for candidate, _ in candidate_items],
            )
            requested_size = requested_translation_font_size(block, min_font_size, font_scale)
            block = _expand_single_line_list_bbox(
                block,
                translated_text,
                [candidate for candidate, _ in candidate_items],
                font_pack,
                requested_size,
                margin,
            )
            block = _expand_single_line_body_bbox(
                block,
                translated_text,
                [candidate for candidate, _ in candidate_items],
                font_pack,
                requested_size,
                margin,
                page_width,
                obstacles=equation_rows.get(page_index, ()),
                frame_rules=page_frame_rules,
                page_columns=page_columns,
            )
            block = _expand_multiline_block_bbox(
                block,
                translated_text,
                [candidate for candidate, _ in candidate_items],
                font_pack,
                requested_size,
                margin,
                page.rect.height,
                obstacles=[
                    *page_floats,
                    *equation_rows.get(page_index, ()),
                    *page_frame_rules[0],
                ],
            )
            block = _expand_caption_bbox_upward(
                block,
                translated_text,
                [candidate for candidate, _ in candidate_items],
                font_pack,
                requested_size,
                margin,
                obstacles=[
                    *page_floats,
                    *equation_rows.get(page_index, ()),
                    *preserved_regions.get(page_index, []),
                ],
            )
            # Float-aware clip: keep reflowed CJK body text out of a right-column
            # figure/table instead of painting over it. Accepted when the
            # clipped column still holds the text near the requested size;
            # otherwise body paragraphs keep their full box and flow around
            # the float through keepout slots (the source page wraps the
            # same way), instead of getting crushed into the side column.
            if not block.preserve_position and not block.nowrap:
                clipped = _clip_block_bbox_against_floats(block.bbox, page_floats, page_width)
                if clipped != block.bbox:
                    clipped_block = replace(block, bbox=clipped)
                    clip_fits = translated_text_fits(
                        block=clipped_block,
                        text=translated_text,
                        font_pack=font_pack,
                        font_size=requested_size,
                        min_font_size=_float_clip_min_font_size(
                            min_font_size,
                            requested_size,
                        ),
                        margin=margin,
                        centered=centered,
                    )
                    if clip_fits:
                        block = clipped_block
                    elif block.block_type == "body":
                        bx0, by0, bx1, by1 = block.bbox
                        wrap_keepouts = [
                            expand_bbox(region, 2.0)
                            for region in page_floats
                            if min(bx1, region[2]) - max(bx0, region[0]) > 0.0
                            and min(by1, region[3]) - max(by0, region[1]) > 0.0
                        ]
                        wrap_keepouts.extend(
                            expand_bbox(candidate.bbox, 2.0)
                            for candidate, _ in candidate_items
                            if candidate is not block
                            and candidate.block_type == "caption"
                            and min(bx1, candidate.bbox[2]) - max(bx0, candidate.bbox[0]) > 0.0
                            and min(by1, candidate.bbox[3]) - max(by0, candidate.bbox[1]) > 0.0
                        )
                        if wrap_keepouts:
                            block = replace(
                                block,
                                keepout_bboxes=list(
                                    dict.fromkeys(
                                        [*(block.keepout_bboxes or []), *wrap_keepouts]
                                    )
                                ),
                            )
            if skip_overflow and not translated_text_fits(
                block=block,
                text=translated_text,
                font_pack=font_pack,
                font_size=requested_size,
                min_font_size=min_font_size,
                margin=margin,
                centered=centered,
            ):
                warnings.append(
                    "Page %d: kept original text to avoid overlap in bbox %s"
                    % (page_index + 1, compact_bbox(block.bbox))
                )
                continue
            page_items.append((block, translated_text))
            item_centered_flags.append(centered)

        page_items = _harmonize_sibling_list_items(
            page_items,
            item_centered_flags,
            font_pack=font_pack,
            min_font_size=min_font_size,
            font_scale=font_scale,
            margin=margin,
            page_height=float(page.rect.height),
            obstacles=[
                *page_floats,
                *preserved_regions.get(page_index, []),
                *equation_rows.get(page_index, []),
            ],
        )
        _clear_table_caption_rules(
            page,
            page_items,
            font_pack=font_pack,
            min_font_size=min_font_size,
            font_scale=font_scale,
            margin=margin,
            centered_flags=item_centered_flags,
        )
        page_items = _clear_adjacent_formula_ink_overlaps(
            page_items,
            item_centered_flags,
            page_rect=page.rect,
            font_pack=font_pack,
            min_font_size=min_font_size,
            font_scale=font_scale,
            margin=margin,
            source_document=source_document,
            obstacles=[
                *preserved_regions.get(page_index, ()),
                *equation_rows.get(page_index, ()),
            ],
        )
        page_items = _demote_unanchorable_math_blocks(
            page_items,
            item_centered_flags,
            font_pack=font_pack,
            min_font_size=min_font_size,
            font_scale=font_scale,
            margin=margin,
        )
        page_items = _cascade_expand_page_items(
            page_items,
            font_pack=font_pack,
            min_font_size=min_font_size,
            font_scale=font_scale,
            margin=margin,
            page_height=float(page.rect.height),
            obstacles=[
                *page_floats,
                *preserved_regions.get(page_index, []),
                *equation_rows.get(page_index, []),
                *page_frame_rules[0],
            ],
            float_obstacles=page_floats,
        )
        source_links = _page_links_for_restore(page)
        redact_original_text(
            page,
            [block for block, _ in page_items],
            margin,
            page_gutter,
            protected_regions=preserved_regions.get(page_index, ()),
        )
        page = document.reload_page(page)
        _restore_removed_page_links(page, source_links)
        restored_regions = _restore_redaction_damaged_preserved_regions(
            page,
            source_document,
            page_index,
            preserved_regions.get(page_index, ()),
            [block for block, _ in page_items],
            margin,
        )
        if restored_regions:
            warnings.append(
                "Page %d: restored %d protected region(s) affected by PDF redaction"
                % (page_index + 1, restored_regions)
            )
        register_font_pack(page, font_pack)
        restored_formulas = _restore_redacted_formula_atoms(
            page,
            source_document,
            page_index,
            [block for block, _ in page_items],
            margin=margin,
            font_pack=font_pack,
        )
        if restored_formulas:
            warnings.append(
                "Page %d: restored %d formula atom group(s) after prose redaction"
                % (page_index + 1, restored_formulas)
            )
        _erase_reflowed_formula_vector_decorations(
            page,
            [block for block, _ in page_items],
        )
        for (block, translated_text), centered in zip(page_items, item_centered_flags):
            inserted = insert_translated_text(
                page=page,
                block=block,
                text=translated_text,
                font_pack=font_pack,
                font_size=(
                    block.fixed_translation_font_size
                    or requested_translation_font_size(block, min_font_size, font_scale)
                ),
                min_font_size=min_font_size,
                margin=margin,
                centered=centered,
                source_document=source_document,
            )
            if not inserted:
                warnings.append(
                    "Page %d: translated text did not fully fit in bbox %s"
                    % (page_index + 1, compact_bbox(block.bbox))
                )
        if (page_index + 1) % 6 == 0:
            # Rendering probes, redaction backgrounds and formula sprites
            # allocate tens of MB of transient pixel buffers per page; on
            # long documents the spikes between garbage collections stack
            # into >500MB peaks (mupdf then dies of heap pressure around
            # paper 34 of a 43-paper session). Collect on a page cadence
            # and shed mupdf's internal store alongside.
            import gc

            gc.collect()
            try:
                fitz.TOOLS.store_shrink(60)
            except Exception:
                pass
        if (
            preserve_graphics_text
            and page_index + 1 < document.page_count
            and (page_index + 1) % 12 == 0
        ):
            document = _checkpoint_modified_document(
                document,
                output_pdf,
                warnings,
                completed_pages=page_index + 1,
            )

    output_pdf.parent.mkdir(parents=True, exist_ok=True)
    if preserve_graphics_text:
        document = _checkpoint_modified_document(
            document,
            output_pdf,
            warnings,
            completed_pages=document.page_count,
        )
        _subset_embedded_cjk_fonts(
            document,
            warnings,
            font_resource_names={
                font_pack.regular_alias,
                font_pack.bold_alias,
                font_pack.fallback_alias,
                font_pack.math_fallback_alias,
            },
        )
    document = subset_fonts_safely(
        document,
        font_pack,
        warnings,
        preserve_source_fonts=preserve_graphics_text,
    )
    save_pdf_for_fast_web_view(
        document,
        output_pdf,
        warnings,
        preserve_source_fonts=preserve_graphics_text,
    )
    page_count = document.page_count
    checkpoint_path = getattr(document, "_translation_checkpoint_path", None)
    document.close()
    if checkpoint_path is not None:
        try:
            Path(checkpoint_path).unlink(missing_ok=True)
        except OSError as exc:
            warnings.append(f"Temporary PDF checkpoint cleanup failed: {exc}")
    source_document.close()
    # Inter-paper hygiene for long sessions: drop everything mupdf cached
    # for this document before the next paper starts.
    import gc

    gc.collect()
    try:
        fitz.TOOLS.store_shrink(100)
    except Exception:
        pass
    return TranslationReport(input_pdf, output_pdf, page_count, len(units), skipped, warnings)


def _translated_block_ink_bbox(
    block: TextBlock,
    text: str,
    *,
    page_rect: object,
    font_pack: FontPack,
    font_size: float,
    min_font_size: float,
    margin: float,
    centered: bool,
    source_document: object,
) -> Optional[BBox]:
    """Render one block off-page and return its actual painted ink envelope."""
    import fitz

    scratch = fitz.open()
    try:
        page = scratch.new_page(
            width=float(page_rect.width),
            height=float(page_rect.height),
        )
        register_font_pack(page, font_pack)
        insert_translated_text(
            page=page,
            block=block,
            text=text,
            font_pack=font_pack,
            font_size=font_size,
            min_font_size=min_font_size,
            margin=margin,
            centered=centered,
            source_document=source_document,
        )
        pad = max(12.0, font_size * 1.5)
        roi = fitz.Rect(
            max(0.0, block.bbox[0] - pad),
            max(0.0, block.bbox[1] - pad),
            min(float(page_rect.width), block.bbox[2] + pad),
            min(float(page_rect.height), block.bbox[3] + pad),
        )
        scale = 2.5  # 180 dpi
        pixmap = page.get_pixmap(
            matrix=fitz.Matrix(scale, scale),
            clip=roi,
            colorspace=fitz.csGRAY,
            alpha=False,
        )
        samples = pixmap.samples
        dark = [index for index, value in enumerate(samples) if value < 245]
        if not dark:
            return None
        min_x = min(index % pixmap.width for index in dark)
        max_x = max(index % pixmap.width for index in dark) + 1
        min_y = min(index // pixmap.width for index in dark)
        max_y = max(index // pixmap.width for index in dark) + 1
        return (
            roi.x0 + min_x / scale,
            roi.y0 + min_y / scale,
            roi.x0 + max_x / scale,
            roi.y0 + max_y / scale,
        )
    finally:
        scratch.close()


def _clear_adjacent_formula_ink_overlaps(
    page_items: Sequence[Tuple[TextBlock, str]],
    centered_flags: Sequence[bool],
    *,
    page_rect: object,
    font_pack: FontPack,
    min_font_size: float,
    font_scale: float,
    margin: float,
    source_document: object,
    obstacles: Sequence[BBox] = (),
) -> List[Tuple[TextBlock, str]]:
    """Clear formula descenders before a tightly adjacent flowing prose block.

    Source bboxes describe extraction hulls, not final painted ink. A formula-heavy
    paragraph can therefore paint below its hull while the following run-in paragraph
    starts above its own hull. Preflight only those tight same-column boundaries and
    move the following flow origin within its existing bottom edge. Redaction remains
    anchored to the source glyphs.
    """
    adjusted = list(page_items)
    ink_cache: Dict[int, Optional[BBox]] = {}

    def ink_bbox(index: int) -> Optional[BBox]:
        if index not in ink_cache:
            candidate, candidate_text = adjusted[index]
            ink_cache[index] = _translated_block_ink_bbox(
                candidate,
                candidate_text,
                page_rect=page_rect,
                font_pack=font_pack,
                font_size=requested_translation_font_size(
                    candidate,
                    min_font_size,
                    font_scale,
                ),
                min_font_size=min_font_size,
                margin=margin,
                centered=centered_flags[index],
                source_document=source_document,
            )
        return ink_cache[index]

    # A flowing paragraph can end inside the extraction hull of the next
    # academic statement.  When that statement keeps its formulas fixed, a
    # tall inline token in the preceding translation may push the final CJK
    # row down over those source glyphs.  Treat only the intersecting fixed
    # anchors as foreign keepouts.  Prefer the otherwise empty right margin
    # over shrinking body text, and accept the change only when the paragraph
    # fits completely at its requested size.
    for index, ((block, text), centered) in enumerate(
        zip(list(adjusted), centered_flags)
    ):
        if (
            centered
            or block.nowrap
            or block.preserve_position
            or block.block_type not in {"body", "formula_prose"}
            or not block.flow_inline_math
            or _uses_fixed_source_math(block)
        ):
            continue

        block_width = max(1.0, block.bbox[2] - block.bbox[0])
        fixed_followups: List[Tuple[float, TextBlock, Tuple[BBox, ...]]] = []
        for following, _following_text in adjusted[index + 1 :]:
            if not _uses_fixed_source_math(following):
                continue
            gap = following.bbox[1] - block.bbox[3]
            if not -max(8.0, block.font_size * 0.8) <= gap <= max(
                3.0,
                block.font_size * 0.35,
            ):
                continue
            overlap = min(block.bbox[2], following.bbox[2]) - max(
                block.bbox[0],
                following.bbox[0],
            )
            following_width = max(1.0, following.bbox[2] - following.bbox[0])
            if overlap / min(block_width, following_width) < 0.65:
                continue
            foreign_anchors = tuple(
                anchor
                for anchor in following.formula_anchors
                if anchor[1] < block.bbox[3] + 0.5
                and anchor[3] > block.bbox[1] - 0.5
            )
            if foreign_anchors:
                fixed_followups.append((abs(gap), following, foreign_anchors))
        if not fixed_followups:
            continue

        _distance, fixed_following, foreign_anchors = min(
            fixed_followups,
            key=lambda item: item[0],
        )
        x0, y0, x1, y1 = block.bbox
        right_limit = min(
            float(page_rect.width) - max(0.5, margin),
            x1 + max(64.0, block.font_size * 7.0),
        )
        for other_index, (other, _other_text) in enumerate(adjusted):
            if other_index == index or other is fixed_following:
                continue
            vertical_overlap = min(y1, other.bbox[3]) - max(y0, other.bbox[1])
            if vertical_overlap <= 0.0 or other.bbox[0] < x1 - 0.5:
                continue
            right_limit = min(right_limit, other.bbox[0] - 0.8)
        for obstacle in obstacles:
            vertical_overlap = min(y1, obstacle[3]) - max(y0, obstacle[1])
            if vertical_overlap <= 0.0 or obstacle[0] < x1 - 0.5:
                continue
            right_limit = min(right_limit, obstacle[0] - 0.8)
        if right_limit <= x1 + 0.1:
            continue

        requested_size = requested_translation_font_size(
            block,
            min_font_size,
            font_scale,
        )
        keepouts = list(
            dict.fromkeys([*(block.keepout_bboxes or []), *foreign_anchors])
        )
        trial_x1 = x1
        while trial_x1 <= right_limit + 1e-6:
            candidate = replace(
                block,
                bbox=(x0, y0, trial_x1, y1),
                redact_bboxes=list(block.redact_bboxes or [block.bbox]),
                keepout_bboxes=keepouts,
            )
            if translated_text_fits(
                candidate,
                text,
                font_pack,
                requested_size,
                requested_size,
                margin,
                centered,
            ):
                adjusted[index] = (candidate, text)
                ink_cache.pop(index, None)
                break
            trial_x1 += 1.0

    # A translated formula-bearing paragraph near the bottom of a column can
    # need one more line while a detached formula suffix prevents growth below.
    # Source bboxes are too conservative for the upper boundary: the preceding
    # Chinese paragraph often paints substantially less ink than its English
    # source hull. Borrow only that measured whitespace, and accept the move
    # only when the paragraph fits at its requested size and both ink envelopes
    # remain clear.
    for index, ((block, text), centered) in enumerate(
        zip(list(adjusted), centered_flags)
    ):
        if (
            index == 0
            or centered
            or block.nowrap
            or block.preserve_position
            or block.block_type not in {"body", "formula_prose"}
            or not block.formula_anchors
            or _uses_fixed_source_math(block)
            or block.bbox[1] < float(page_rect.height) * 0.55
        ):
            continue

        block_width = max(1.0, block.bbox[2] - block.bbox[0])
        detached_suffix = any(
            suffix.block_type == "formula_prose"
            and not suffix.formula_anchors
            and suffix.source_lines == 1
            and suffix.bbox[0] >= block.bbox[0] + block_width * 0.60
            and suffix.bbox[2] <= block.bbox[2] + 1.0
            and min(block.bbox[3], suffix.bbox[3])
            - max(block.bbox[1], suffix.bbox[1])
            > 0.0
            for suffix, _ in adjusted[index + 1 :]
        )
        block_height = max(1.0, block.bbox[3] - block.bbox[1])
        blocking_formula_below = any(
            keepout[1] >= block.bbox[1] + block_height * 0.62
            and keepout[1] < block.bbox[3]
            and min(block.bbox[2], keepout[2])
            - max(block.bbox[0], keepout[0])
            > 0.0
            for keepout in _unresolved_formula_keepouts(block)
        )
        if not (detached_suffix or blocking_formula_below):
            continue

        requested_size = requested_translation_font_size(
            block,
            min_font_size,
            font_scale,
        )
        # Once a detached formula suffix has been folded into this paragraph,
        # ``blocking_formula_below`` is the only remaining structural trace of
        # that source row. Preserve body scale in both forms; accepting the
        # generic 85% floor here made one formula token shrink an entire
        # paragraph even though measured whitespace above was available.
        target_size = max(min_font_size, requested_size * 0.98)
        if translated_text_fits(
            block,
            text,
            font_pack,
            requested_size,
            target_size,
            margin,
            centered,
        ):
            continue

        preceding_inks: List[BBox] = []
        for previous_index in range(index):
            previous = adjusted[previous_index][0]
            overlap = min(block.bbox[2], previous.bbox[2]) - max(
                block.bbox[0],
                previous.bbox[0],
            )
            previous_width = max(1.0, previous.bbox[2] - previous.bbox[0])
            if overlap / min(block_width, previous_width) < 0.65:
                continue
            previous_ink = ink_bbox(previous_index)
            if previous_ink is None or previous_ink[1] >= block.bbox[1]:
                continue
            preceding_inks.append(previous_ink)
        if not preceding_inks:
            continue

        previous_ink_bottom = max(candidate[3] for candidate in preceding_inks)
        max_shift = min(
            max(0.0, block.bbox[1] - previous_ink_bottom + requested_size),
            requested_size * 2.5,
        )
        preceding_obstacle_bottom = max(
            [
                obstacle[3] + 0.6
                for obstacle in obstacles
                if obstacle[1] < block.bbox[1]
                and min(block.bbox[2], obstacle[2])
                - max(block.bbox[0], obstacle[0])
                >= min(
                    block.bbox[2] - block.bbox[0],
                    obstacle[2] - obstacle[0],
                )
                * 0.35
            ]
            or [float("-inf")]
        )
        if preceding_obstacle_bottom != float("-inf"):
            max_shift = min(
                max_shift,
                max(0.0, block.bbox[1] - preceding_obstacle_bottom),
            )
        if max_shift < 0.25:
            continue

        x0, y0, x1, y1 = block.bbox
        shift = 0.25
        while shift <= max_shift + 1e-6:
            candidate = replace(
                block,
                bbox=(x0, y0 - shift, x1, y1),
                redact_bboxes=list(block.redact_bboxes or [block.bbox]),
            )
            if not translated_text_fits(
                candidate,
                text,
                font_pack,
                requested_size,
                target_size,
                margin,
                centered,
            ):
                shift += 0.25
                continue
            candidate_ink = _translated_block_ink_bbox(
                candidate,
                text,
                page_rect=page_rect,
                font_pack=font_pack,
                font_size=requested_size,
                min_font_size=target_size,
                margin=margin,
                centered=centered,
                source_document=source_document,
            )
            if (
                candidate_ink is not None
                and candidate_ink[1]
                >= previous_ink_bottom
                + max(0.5, min(1.0, requested_size * 0.06))
            ):
                adjusted[index] = (candidate, text)
                ink_cache.pop(index, None)
                break
            shift += 0.25

    for index, ((block, text), centered) in enumerate(
        zip(list(adjusted), centered_flags)
    ):
        if (
            index == 0
            or centered
            or block.nowrap
            or block.preserve_position
            or block.block_type not in {"body", "formula_prose"}
            or _uses_fixed_source_math(block)
        ):
            continue

        predecessors: List[Tuple[float, int]] = []
        block_width = max(1.0, block.bbox[2] - block.bbox[0])
        for previous_index in range(index):
            previous, _ = adjusted[previous_index]
            if not previous.formula_anchors:
                continue
            gap = block.bbox[1] - previous.bbox[3]
            if not -max(8.0, block.font_size * 0.75) <= gap <= max(
                3.0,
                block.font_size * 0.35,
            ):
                continue
            overlap = min(block.bbox[2], previous.bbox[2]) - max(
                block.bbox[0],
                previous.bbox[0],
            )
            previous_width = max(1.0, previous.bbox[2] - previous.bbox[0])
            if overlap / min(block_width, previous_width) < 0.65:
                continue
            predecessors.append((gap, previous_index))
        if not predecessors:
            continue

        _, previous_index = min(predecessors, key=lambda item: abs(item[0]))
        previous_ink = ink_bbox(previous_index)
        current_ink = ink_bbox(index)
        if previous_ink is None or current_ink is None:
            continue
        previous = adjusted[previous_index][0]
        conservative_previous_bottom = previous_ink[3]
        previous_text = adjusted[previous_index][1]
        previous_requested_size = requested_translation_font_size(
            previous,
            min_font_size,
            font_scale,
        )
        previous_layout_height = _sibling_group_item_height(
            previous,
            previous_text,
            font_pack,
            previous_requested_size,
            margin,
        )
        if previous_layout_height is not None:
            conservative_previous_bottom = max(
                conservative_previous_bottom,
                previous.bbox[1] + previous_layout_height + margin * 2.0,
            )
        if not previous.flow_inline_math:
            formula_descender_guard = max(2.0, previous.font_size * 0.55)
            anchor_bottom = max(anchor[3] for anchor in previous.formula_anchors)
            conservative_previous_bottom = max(
                conservative_previous_bottom,
                min(
                    previous.bbox[3] + formula_descender_guard,
                    anchor_bottom + formula_descender_guard,
                ),
            )
        clearance = max(1.0, min(2.0, block.font_size * 0.14))
        shift = conservative_previous_bottom + clearance - current_ink[1]
        if shift <= 0.0:
            continue

        x0, y0, x1, y1 = block.bbox
        shifted_y0 = y0 + shift
        page_bottom = float(page_rect.height) - max(0.5, margin)
        obstacle_floor = min(
            [
                obstacle[1] - 0.6
                for obstacle in obstacles
                if obstacle[1] >= y0 + 0.5
                and obstacle[3] > y0
                and min(x1, obstacle[2]) - max(x0, obstacle[0])
                >= min(x1 - x0, obstacle[2] - obstacle[0]) * 0.35
            ]
            or [page_bottom]
        )
        shifted_y1 = min(page_bottom, y1 + shift, obstacle_floor)
        if shifted_y0 >= shifted_y1 - max(4.0, min_font_size):
            continue
        shifted = replace(
            block,
            bbox=(x0, shifted_y0, x1, shifted_y1),
            redact_bboxes=list(block.redact_bboxes or [block.bbox]),
        )
        requested_size = requested_translation_font_size(
            shifted,
            min_font_size,
            font_scale,
        )
        shifted_min_size = min_font_size
        shifted_plain = " ".join(strip_sentinels(shifted.text).split()).strip()
        if (
            shifted.flow_inline_math
            and _ACADEMIC_FORMULA_STATEMENT_RE.match(shifted_plain)
        ):
            shifted_min_size = max(min_font_size, requested_size * 0.85)
        if not translated_text_fits(
            shifted,
            text,
            font_pack,
            requested_size,
            shifted_min_size,
            margin,
            centered,
        ):
            continue
        adjusted[index] = (shifted, text)
        ink_cache.pop(index, None)

    return adjusted


def _translate_unique_sources(
    translator: object,
    sources: Sequence[str],
    block_types: Sequence[str],
) -> Tuple[List[str], int, int]:
    """Translate identical source/role pairs once and reuse the result."""
    unique_sources: List[str] = []
    unique_types: List[str] = []
    indexes: Dict[Tuple[str, str], int] = {}
    source_indexes: List[int] = []
    for source, block_type in zip(sources, block_types):
        key = (source, block_type)
        if key not in indexes:
            indexes[key] = len(unique_sources)
            unique_sources.append(source)
            unique_types.append(block_type)
        source_indexes.append(indexes[key])

    if hasattr(translator, "block_types"):
        translator.block_types = unique_types
    raw_outputs = list(translator.translate_batch(unique_sources))
    response_count = len(raw_outputs)
    if len(raw_outputs) < len(unique_sources):
        raw_outputs.extend(unique_sources[len(raw_outputs) :])
    elif len(raw_outputs) > len(unique_sources):
        raw_outputs = raw_outputs[: len(unique_sources)]
    return (
        [raw_outputs[index] for index in source_indexes],
        len(unique_sources),
        response_count,
    )


def _source_bold_prefix_end(block: TextBlock, protected_source: str) -> Optional[int]:
    """Return the source span boundary for a body-leading bold label."""
    # Quality retries temporarily use the ``foreign_example`` prompt role to
    # force a fresh translation.  That role change must not collapse an
    # originally structured run-in heading back into a single cache request.
    if (
        block.bold
        or not block.bold_prefix
        or block.block_type not in ("body", "foreign_example")
    ):
        return None
    stripped = protected_source.lstrip()
    leading = len(protected_source) - len(stripped)
    for term in block.bold_terms:
        candidate = term.strip()
        if not candidate or sentinel_char_count(candidate):
            continue
        match = re.search(re.escape(candidate), stripped, re.IGNORECASE)
        if match is None or match.start() > 4:
            continue
        prefix_lead = stripped[: match.start()]
        if re.search(r"[A-Za-z]", prefix_lead):
            continue
        end = match.end()
        while end < len(stripped) and stripped[end] in ".:：":
            end += 1
        suffix = stripped[end:].strip()
        if substantial_prose_word_count(strip_sentinels(suffix)) < 2:
            continue
        return leading + end
    return None


_ACRONYM_DEFINITION_RE = re.compile(
    r"\b((?:[A-Z][A-Za-z0-9]*(?:[-\s]+)){1,7}[A-Z][A-Za-z0-9]*)"
    r"\s*\(([A-Z][A-Z0-9-]{1,11})\)"
)


def _document_acronym_expansions(
    units: Sequence[Tuple[TextBlock, str, Dict[str, str]]],
) -> Dict[str, str]:
    """Return unambiguous acronym definitions found in this source document."""
    candidates: Dict[str, set[str]] = {}
    for _block, protected_source, _mapping in units:
        plain = strip_sentinels(protected_source)
        for match in _ACRONYM_DEFINITION_RE.finditer(plain):
            phrase = " ".join(match.group(1).split())
            acronym = match.group(2)
            acronym_letters = acronym.replace("-", "")
            words = re.findall(r"[A-Z][A-Za-z0-9]*", phrase)
            expansion = None
            for start in range(len(words)):
                suffix = words[start:]
                if len(suffix) < 2:
                    continue
                if "".join(word[0] for word in suffix).upper() == acronym_letters:
                    expansion = " ".join(suffix)
                    break
            if expansion is not None:
                candidates.setdefault(acronym, set()).add(expansion)
    return {
        acronym: next(iter(expansions))
        for acronym, expansions in candidates.items()
        if len(expansions) == 1
    }


def _prefix_source_with_acronym_context(
    prefix_source: str,
    acronym_expansions: Dict[str, str],
) -> str:
    """Add source-document acronym context to an isolated run-in label."""
    contextual = prefix_source
    for acronym in sorted(acronym_expansions, key=len, reverse=True):
        expansion = acronym_expansions[acronym]
        already_expanded = re.compile(
            rf"\b{re.escape(expansion)}\s*\(\s*{re.escape(acronym)}\s*\)"
        )
        if already_expanded.search(contextual):
            continue
        pattern = re.compile(rf"\b{re.escape(acronym)}\b(?!\s*\()")
        if pattern.search(contextual):
            contextual = pattern.sub(
                f"{expansion} ({acronym})",
                contextual,
                count=1,
            )
    return contextual


def _translate_units_with_source_style_runs(
    translator: object,
    units: Sequence[Tuple[TextBlock, str, Dict[str, str]]],
    acronym_expansions: Optional[Dict[str, str]] = None,
) -> Tuple[List[str], int, int]:
    """Translate source-derived run-in prefix/body ranges independently."""
    if not getattr(translator, "supports_source_style_segments", True):
        return _translate_unique_sources(
            translator,
            [protected_source for _block, protected_source, _mapping in units],
            [block.block_type for block, _protected_source, _mapping in units],
        )
    sources, block_types, plans = _source_style_translation_plan(
        translator,
        units,
        acronym_expansions,
    )
    outputs, request_count, response_count = _translate_unique_sources(
        translator,
        sources,
        block_types,
    )
    translated_units: List[str] = []
    for (block, _protected_source, _mapping), (start, count) in zip(units, plans):
        if count == 1:
            translated_units.append(outputs[start])
            continue
        translated_prefix = outputs[start].strip()
        translated_body = outputs[start + 1].strip()
        block.translated_bold_prefix_chars = len(translated_prefix)
        translated_units.append(
            f"{translated_prefix} {translated_body}"
            if translated_body
            else translated_prefix
        )
    return translated_units, request_count, response_count


def _source_style_translation_plan(
    translator: object,
    units: Sequence[Tuple[TextBlock, str, Dict[str, str]]],
    acronym_expansions: Optional[Dict[str, str]] = None,
) -> Tuple[List[str], List[str], List[Tuple[int, int]]]:
    """Build the exact source requests used for translation and invalidation."""
    sources: List[str] = []
    block_types: List[str] = []
    plans: List[Tuple[int, int]] = []
    segment_source_styles = getattr(translator, "supports_source_style_segments", True)
    for block, protected_source, _mapping in units:
        prefix_end = (
            _source_bold_prefix_end(block, protected_source)
            if segment_source_styles
            else None
        )
        if prefix_end is None:
            plans.append((len(sources), 1))
            sources.append(protected_source)
            block_types.append(block.block_type)
            continue
        prefix_source = _prefix_source_with_acronym_context(
            protected_source[:prefix_end].strip(),
            acronym_expansions or {},
        )
        body_source = protected_source[prefix_end:].strip()
        if not prefix_source or not body_source:
            plans.append((len(sources), 1))
            sources.append(protected_source)
            block_types.append(block.block_type)
            continue
        plans.append((len(sources), 2))
        sources.extend((prefix_source, body_source))
        block_types.extend(("run_in_heading", block.block_type))
    return sources, block_types, plans


def _page_links_for_restore(page: object) -> List[dict]:
    """Snapshot interactive links before redaction removes overlapping annotations."""
    try:
        return [dict(link) for link in page.get_links()]
    except Exception:
        return []


def _link_identity(link: dict) -> Tuple[object, ...]:
    source_rect = link.get("from")
    source = (
        tuple(round(float(value), 2) for value in source_rect)
        if source_rect is not None
        else ()
    )
    target_point = link.get("to")
    target = (
        tuple(round(float(value), 2) for value in target_point)
        if target_point is not None
        else ()
    )
    return (
        int(link.get("kind", 0)),
        source,
        int(link.get("page", -1)),
        target,
        link.get("uri", ""),
        link.get("file", ""),
        link.get("nameddest", link.get("name", "")),
    )


def _restore_removed_page_links(page: object, source_links: Sequence[dict]) -> None:
    """Reinsert only link annotations deleted by text redaction."""
    try:
        current = {_link_identity(link) for link in page.get_links()}
    except Exception:
        current = set()
    for source_link in source_links:
        identity = _link_identity(source_link)
        if identity in current:
            continue
        link = {
            key: value
            for key, value in source_link.items()
            if key not in {"xref", "id"}
        }
        if link.get("kind") == 4:
            named_destination = link.pop("nameddest", "")
            if int(link.get("page", -1)) >= 0:
                link["kind"] = 1
            else:
                link["name"] = named_destination
                link.pop("page", None)
                link.pop("to", None)
                link.pop("zoom", None)
        try:
            page.insert_link(link)
            current.add(identity)
        except Exception:
            continue


_FONT_SUBSET_MIN_BYTES = 2_000_000


def _subset_embedded_cjk_fonts(
    document: object,
    warnings: Optional[List[str]] = None,
    *,
    font_resource_names: Optional[set[str]] = None,
) -> None:
    """Subset huge embedded fonts (CJK families) down to the used glyphs.

    The translation engine embeds the full CJK font file (~16MB); a typical
    paper uses under a thousand distinct characters (~1MB subset). Fonts use
    Identity-H encoding, so subsetting keeps glyph IDs stable
    (``retain_gids``) and page content streams need no rewriting.
    """
    try:
        import io
        import re as _re

        from fontTools import subset
        from fontTools.ttLib import TTFont
    except Exception:
        return

    def _referenced_xref(value: str) -> Optional[int]:
        match = _re.search(r"(\d+) 0 R", value)
        return int(match.group(1)) if match else None

    fontfile_xrefs: Dict[int, str] = {}
    for page_index in range(document.page_count):
        for font in document.get_page_fonts(page_index, full=True):
            font_xref, font_type = font[0], font[2]
            if font_type != "Type0":
                continue
            if font_resource_names is not None and font[4] not in font_resource_names:
                continue
            kind, descendants = document.xref_get_key(font_xref, "DescendantFonts")
            if kind != "array":
                continue
            descendant_xref = _referenced_xref(descendants)
            if descendant_xref is None:
                continue
            _, descriptor_value = document.xref_get_key(
                descendant_xref, "FontDescriptor"
            )
            descriptor_xref = _referenced_xref(descriptor_value or "")
            if descriptor_xref is None:
                continue
            for key in ("FontFile3", "FontFile2"):
                kind, value = document.xref_get_key(descriptor_xref, key)
                if kind != "null" and value:
                    stream_xref = _referenced_xref(value)
                    if stream_xref is not None:
                        fontfile_xrefs[stream_xref] = key
    if not fontfile_xrefs:
        return

    used_unicodes: Optional[List[int]] = None
    for stream_xref in sorted(fontfile_xrefs):
        try:
            font_bytes = document.xref_stream(stream_xref)
        except Exception:
            continue
        if font_bytes is None or len(font_bytes) < _FONT_SUBSET_MIN_BYTES:
            continue
        if used_unicodes is None:
            used_chars: set = set()
            for page_index in range(document.page_count):
                used_chars.update(document[page_index].get_text("text"))
            used_unicodes = sorted(
                ord(char) for char in used_chars if ord(char) >= 32
            )
        try:
            font = TTFont(io.BytesIO(font_bytes))
            options = subset.Options()
            options.retain_gids = True
            options.notdef_outline = True
            options.name_IDs = ["*"]
            subsetter = subset.Subsetter(options)
            subsetter.populate(unicodes=used_unicodes)
            subsetter.subset(font)
            buffer = io.BytesIO()
            font.save(buffer)
            new_bytes = buffer.getvalue()
            if new_bytes and len(new_bytes) < len(font_bytes):
                document.update_stream(stream_xref, new_bytes)
        except Exception as exc:
            if warnings is not None:
                warnings.append(f"Font subsetting skipped for one font: {exc}")


def dedupe_pdf_images(pdf: object) -> int:
    """Alias semantically identical image XObjects in a pikepdf document.

    Repeated ``show_pdf_page`` calls (one per preserved formula) copy the
    source page's images into the target document once per call, so a
    math-heavy paper can carry dozens of orphan copies of the same figure.
    Pixel streams alone are not a safe identity: two icons can share a solid
    RGB stream while using different soft masks. Include the image dictionary
    and dependent streams in the fingerprint, point references at the first
    equivalent copy, and turn only fully unreferenced copies into valid 1x1
    gray pixels. Returns the number of duplicate images neutralized.
    """
    import hashlib

    import pikepdf

    fingerprint_cache: dict[tuple[int, int], tuple] = {}
    fingerprint_stack: set[tuple[int, int]] = set()

    def _dictionary_fingerprint(value: object) -> tuple:
        return (
            "dict",
            tuple(
                sorted(
                    (str(key), _fingerprint(item))
                    for key, item in value.items()
                    if str(key) != "/Length"
                )
            ),
        )

    def _fingerprint(value: object) -> tuple:
        if isinstance(value, pikepdf.Stream):
            objgen = value.objgen if value.is_indirect else None
            if objgen is not None and objgen in fingerprint_cache:
                return fingerprint_cache[objgen]
            if objgen is not None and objgen in fingerprint_stack:
                return ("cycle", str(objgen))
            if objgen is not None:
                fingerprint_stack.add(objgen)
            result = (
                "stream",
                hashlib.sha256(value.read_raw_bytes()).hexdigest(),
                _dictionary_fingerprint(value),
            )
            if objgen is not None:
                fingerprint_stack.remove(objgen)
                fingerprint_cache[objgen] = result
            return result
        if isinstance(value, pikepdf.Dictionary):
            return _dictionary_fingerprint(value)
        if isinstance(value, pikepdf.Array):
            return ("array", tuple(_fingerprint(item) for item in value))
        return ("value", type(value).__name__, str(value))

    canonical: dict[tuple, object] = {}
    duplicates: dict[tuple[int, int], object] = {}
    for obj in pdf.objects:
        if isinstance(obj, pikepdf.Stream) and obj.get("/Subtype") == pikepdf.Name("/Image"):
            try:
                signature = _fingerprint(obj)
            except Exception:
                continue
            if signature in canonical:
                duplicates[obj.objgen] = canonical[signature]
            else:
                canonical[signature] = obj
    if not duplicates:
        return 0

    visited: set[tuple[int, int]] = set()

    def _rewrite(container: object) -> None:
        if isinstance(container, (pikepdf.Dictionary, pikepdf.Stream)):
            items = list(container.items())
        else:
            items = list(enumerate(container))
        for key, value in items:
            if not isinstance(value, pikepdf.Object):
                continue
            if value.is_indirect and value.objgen in duplicates:
                container[key] = duplicates[value.objgen]
            elif isinstance(value, (pikepdf.Dictionary, pikepdf.Array, pikepdf.Stream)):
                objgen = value.objgen if value.is_indirect else None
                if objgen is not None:
                    if objgen in visited:
                        continue
                    visited.add(objgen)
                _rewrite(value)

    for obj in pdf.objects:
        if isinstance(obj, (pikepdf.Dictionary, pikepdf.Array, pikepdf.Stream)):
            _rewrite(obj)

    remaining_references: set[tuple[int, int]] = set()
    visited.clear()

    def _find_remaining_references(container: object) -> None:
        if isinstance(container, (pikepdf.Dictionary, pikepdf.Stream)):
            values = list(container.values())
        else:
            values = list(container)
        for value in values:
            if not isinstance(value, pikepdf.Object):
                continue
            if value.is_indirect and value.objgen in duplicates:
                remaining_references.add(value.objgen)
                continue
            if isinstance(value, (pikepdf.Dictionary, pikepdf.Array, pikepdf.Stream)):
                objgen = value.objgen if value.is_indirect else None
                if objgen is not None:
                    if objgen in visited:
                        continue
                    visited.add(objgen)
                _find_remaining_references(value)

    for obj in pdf.objects:
        if isinstance(obj, (pikepdf.Dictionary, pikepdf.Array, pikepdf.Stream)):
            _find_remaining_references(obj)

    neutralized = 0
    for obj in pdf.objects:
        if obj.objgen in duplicates and obj.objgen not in remaining_references:
            for key in list(obj.keys()):
                if key not in ("/Type", "/Subtype", "/Length"):
                    del obj[key]
            obj["/Width"] = 1
            obj["/Height"] = 1
            obj["/ColorSpace"] = pikepdf.Name("/DeviceGray")
            obj["/BitsPerComponent"] = 8
            obj.write(b"\x00")
            neutralized += 1
    return neutralized


def save_pdf_for_fast_web_view(
    document: object,
    output_pdf: Path,
    warnings: Optional[List[str]] = None,
    *,
    preserve_source_fonts: bool = False,
) -> None:
    """Save a compact, linearized PDF so PDF.js can show page 1 with range reads."""
    if not preserve_source_fonts:
        _subset_embedded_cjk_fonts(document, warnings)
    output_pdf.parent.mkdir(parents=True, exist_ok=True)
    temp_pdf = output_pdf.with_name(f".{output_pdf.name}.{os.getpid()}.tmp")
    linearized_pdf = output_pdf.with_name(f".{output_pdf.name}.{os.getpid()}.linearized.tmp")
    # Translation inserts many independent text and formula streams. Deep
    # cleanup deduplicates their resources while clean=True combines each
    # page's stream array, which keeps PDF.js parsing work bounded.
    compact_save_options = {
        "garbage": 4,
        "clean": True,
        "deflate": True,
        "deflate_images": True,
        "deflate_fonts": True,
    }
    try:
        document.save(str(temp_pdf), **compact_save_options)
        try:
            import pikepdf

            with pikepdf.open(temp_pdf) as pdf:
                pdf.save(linearized_pdf, linearize=True, compress_streams=True)
            linearized_pdf.replace(output_pdf)
        except Exception as exc:
            if warnings is not None:
                warnings.append(f"Fast web PDF linearization failed; used standard save: {exc}")
            temp_pdf.replace(output_pdf)
    except Exception as exc:
        if warnings is not None:
            warnings.append(f"Fast web PDF save failed; used standard save: {exc}")
        document.save(str(output_pdf), garbage=2, deflate=True)
    finally:
        temp_pdf.unlink(missing_ok=True)
        linearized_pdf.unlink(missing_ok=True)


def _checkpoint_modified_document(
    document: object,
    output_pdf: Path,
    warnings: Optional[List[str]] = None,
    *,
    completed_pages: int,
) -> object:
    """Persist and reopen long native translations to isolate shared PDF resources."""
    import fitz

    output_pdf.parent.mkdir(parents=True, exist_ok=True)
    checkpoint = output_pdf.with_name(
        f".{output_pdf.name}.{os.getpid()}.{uuid.uuid4().hex}.checkpoint.tmp"
    )
    previous_checkpoint = getattr(document, "_translation_checkpoint_path", None)
    reopened = None
    try:
        document.save(str(checkpoint), garbage=2, deflate=True)
        reopened = fitz.open(str(checkpoint))
        document.close()
        if previous_checkpoint is not None:
            try:
                Path(previous_checkpoint).unlink(missing_ok=True)
            except OSError as exc:
                if warnings is not None:
                    warnings.append(f"Temporary PDF checkpoint cleanup failed: {exc}")
        try:
            checkpoint.unlink(missing_ok=True)
        except PermissionError:
            reopened._translation_checkpoint_path = checkpoint
        return reopened
    except Exception as exc:
        if reopened is not None:
            reopened.close()
        if warnings is not None:
            warnings.append(
                "Page %d: PDF object checkpoint failed; continued in memory: %s"
                % (completed_pages, exc)
            )
        return document
    finally:
        if reopened is None:
            checkpoint.unlink(missing_ok=True)


def create_dual_pdf(
    original_pdf: Path,
    translated_pdf: Path,
    output_pdf: Path,
) -> None:
    """Create a dual-language PDF by interleaving original and translated pages.

    For each page: original page, then translated page. This allows side-by-side
    viewing in PDF readers that support page pairs.
    """
    import fitz

    output_pdf = Path(output_pdf)
    staging_pdf = output_pdf.with_name(
        f".{output_pdf.stem}.{uuid.uuid4().hex}.tmp.pdf"
    )
    try:
        with (
            open_pdf_detached(original_pdf) as orig_doc,
            open_pdf_detached(translated_pdf) as trans_doc,
            fitz.open() as dual_doc,
        ):
            # Insert each source document in ONE call: per-page insert_pdf
            # duplicates shared resources (the embedded CJK font would be
            # copied once per page), bloating the file several-fold.
            original_count = orig_doc.page_count
            dual_doc.insert_pdf(orig_doc)
            translated_count = min(trans_doc.page_count, original_count)
            if translated_count:
                dual_doc.insert_pdf(
                    trans_doc, from_page=0, to_page=translated_count - 1
                )
            # Interleave: original page i, then its translation.
            for i in range(translated_count):
                dual_doc.move_page(original_count + i, 2 * i + 1)

            save_pdf_for_fast_web_view(dual_doc, staging_pdf)
        staging_pdf.replace(output_pdf)
    finally:
        staging_pdf.unlink(missing_ok=True)


_CJK_DETECT_RE = re.compile(r"[\u2e80-\u9fff\uf900-\ufaff]")
_ASCII_WORD_DETECT_RE = re.compile(r"[A-Za-z]{3,}")
_URL_RE = re.compile(r"https?://\S+", re.IGNORECASE)
_PRESERVED_NUMERIC_TOKEN_RE = re.compile(
    r"[+\-−]?(?:\d+(?:[.,]\d+)*|\.\d+)(?:[eE][+\-−]?\d+)?"
)
_REFERENCE_ENTRY_RE = re.compile(
    # `\d{1,3}\.(?!\d)` accepts numbered entries ("12. Smith...") but rejects
    # section numbering like "4.2. Conditional diffusion model training".
    r"^\s*(?:\[\d+\]|\d{1,3}\.(?!\d)|(?i:doi|arxiv):|"
    r"[A-Z][A-Za-z'’.-]+(?:\s+(?:et\s+al\.|and|&|[A-Z]\.|"
    r"[A-Z][A-Za-z'’.-]+|,)){0,8}\s+\((?:19|20)\d{2}[a-z]?\))",
)
# A leading citation marker flowing into lowercase prose ("[28] is a
# robustness-oriented benchmark ...") is a run-in-heading split leftover, not
# a reference entry. Lowercase surname particles (van/von/de/...) still start
# genuine entries and must keep the reference-entry shortcut.
_LEADING_CITATION_PROSE_RE = re.compile(
    r"^\s*\[\d+\]\s*[,;:]?\s+"
    r"(?!(?:van|von|vander|de|del|della|der|den|di|da|dos|das|du|la|le|lo|"
    r"ter|ten|te|el|al|bin|ibn|abu|zur|zum|am|auf|mac|st)\b)"
    r"[a-z]"
)
_REFERENCE_YEAR_RE = re.compile(r"\b(?:19|20)\d{2}[a-z]?\b", re.IGNORECASE)
_REFERENCE_FRAGMENT_CUE_RE = re.compile(
    r"(?:\bet al\.|\bpp\.|\bpages?\b|\bproceedings\b|\bconference\b|\bjournal\b"
    r"|\btransactions\b|\barxiv\b|\bpreprint\b|\. In\s+(?:Proceedings|Proc\.|"
    r"Conference|Workshop|Symposium|NeurIPS|ICML|ICLR|CVPR|ACL|CoRL|ICRA)\b"
    r"|\. In\s*$"
    r"|\bPMLR\b|\bIEEE\b"
    r"|\bICRA\b|\bICLR\b|\bCoRL\b|\bNeurIPS\b)",
    re.IGNORECASE,
)
_REFERENCE_AUTHOR_START_RE = re.compile(
    r"^\s*(?:"
    r"[A-Z]\.\s+[A-Z][A-Za-z'’.-]+"
    r"|[A-Z][A-Za-z'’.-]+,\s*(?:[A-Z]\.?|[A-Z][A-Za-z'’.-]+)"
    r"|[A-Z][A-Za-z'’.-]+\s+et\s+al\."
    r"|[A-Z][A-Za-z'’.-]+\s+(?:and\s+|&\s*)?[A-Z][A-Za-z'’.-]+"
    r")",
)
_BODY_PROSE_CITATION_CUE_RE = re.compile(
    r"\b(?:in this paper|this paper|we propose|we introduce|we show|we observe|"
    r"our core insight|the standard formalism|the rest of the paper|in practice|"
    r"however|therefore|these models|these methods|"
    r"open access version|computer vision foundation)\b",
    re.IGNORECASE,
)
_LEADING_DISCOURSE_PROSE_RE = re.compile(
    r"^\s*(?:although|because|following|given|since|while)\b",
    re.IGNORECASE,
)


_BODY_UNTRANSLATED_ISSUE_PRIORITY = {
    "untranslated_english": 0,
    "untranslated_natural_language": 1,
    "untranslated_block": 2,
}


def _dedupe_body_untranslated_issues(
    issues: Sequence[TranslationIssue],
) -> List[TranslationIssue]:
    """Keep one body-prose untranslated finding per page.

    The semantic QA and visual inspector inspect the same page through
    different representations. Reporting both findings inflates the defect
    count without identifying an additional repair target.
    """
    deduped: List[TranslationIssue] = []
    selected_index: Dict[int, int] = {}
    for issue in issues:
        priority = _BODY_UNTRANSLATED_ISSUE_PRIORITY.get(issue.code)
        if priority is None:
            deduped.append(issue)
            continue
        existing_index = selected_index.get(issue.page)
        if existing_index is None:
            selected_index[issue.page] = len(deduped)
            deduped.append(issue)
            continue
        existing = deduped[existing_index]
        if priority < _BODY_UNTRANSLATED_ISSUE_PRIORITY[existing.code]:
            deduped[existing_index] = issue
    return deduped


def _placeholder_leak_issues(
    page: int,
    source_text: str,
    translated_text: str,
) -> List[TranslationIssue]:
    """Report internal numbered placeholders introduced by translation."""
    source_placeholders = set(PLACEHOLDER_RE.findall(source_text))
    leaked_placeholders = sorted(
        set(PLACEHOLDER_RE.findall(translated_text)) - source_placeholders,
        key=int,
    )
    if not leaked_placeholders:
        return []
    return [
        TranslationIssue(
            page=page,
            code="placeholder_leak",
            message=(
                f"Page {page}: internal placeholder token(s) leaked into the "
                f"translated PDF: {', '.join(leaked_placeholders)}"
            ),
            severity="error",
        )
    ]


def verify_translation(original_pdf: Path, translated_pdf: Path) -> List[str]:
    """Verify translated PDF quality. Returns user-readable issue messages."""
    return [issue.message for issue in verify_translation_issues(original_pdf, translated_pdf)]


def verify_translation_issues(original_pdf: Path, translated_pdf: Path) -> List[TranslationIssue]:
    """Run post-translation QA.

    Checks:
    1. Untranslated English prose outside references/formulas
    2. Text block collisions that can indicate broken layout
    3. Empty pages
    4. Missing raster images after redaction/rendering
    5. Missing formula fragments from math-heavy source blocks
    6. Missing vector graphics from figures/tables
    7. Render-based visual layout score
    8. High-risk table/algorithm/float regions
    """

    issues: List[TranslationIssue] = []
    try:
        orig_doc = open_pdf_detached(original_pdf)
        trans_doc = open_pdf_detached(translated_pdf)
    except Exception as e:
        return [
            TranslationIssue(
                page=0,
                code="qa_open_failed",
                message=f"Failed to open PDFs for verification: {e}",
                severity="error",
            )
        ]

    if orig_doc.page_count != trans_doc.page_count:
        issues.append(
            TranslationIssue(
                page=0,
                code="page_count_mismatch",
                message=(
                    "Translated PDF page count differs from original: "
                    f"{trans_doc.page_count} vs {orig_doc.page_count}"
                ),
                severity="error",
            )
        )

    preserved_regions_by_page: Dict[int, List[BBox]] = {}
    equation_rows_by_page: Dict[int, List[BBox]] = {}
    try:
        source_units, _, _ = prepare_translation_units(
            orig_doc,
            preserve_graphics_text=True,
            preserved_regions_out=preserved_regions_by_page,
            equation_rows_out=equation_rows_by_page,
        )
    except Exception:
        source_units = []
        preserved_regions_by_page = {}
        equation_rows_by_page = {}
    # Captions anchor table envelopes yet are always translated, so their
    # bands must not participate in preserved-region text comparison.
    caption_bboxes_by_page: Dict[int, List[BBox]] = {}
    preserved_label_bboxes_by_page: Dict[int, List[BBox]] = {}
    translated_formula_prose_bboxes_by_page: Dict[int, List[BBox]] = {}
    translation_units_by_page: Dict[int, List[TextBlock]] = {}
    # Formula keepout lines are intentionally left verbatim inside translated
    # paragraphs; their English connector words must not count as
    # untranslated prose.
    keepout_bboxes_by_page: Dict[int, List[BBox]] = {}
    for unit_block, _, _ in source_units:
        translation_units_by_page.setdefault(unit_block.page_index, []).append(
            unit_block
        )
        if unit_block.block_type == "caption":
            caption_bboxes_by_page.setdefault(unit_block.page_index, []).append(
                expand_bbox(unit_block.bbox, 2.0)
            )
        if unit_block.block_type == "formula_prose" and unit_block.should_translate:
            formula_prose_bboxes = (
                unit_block.source_prose_bboxes
                or tuple(unit_block.redact_bboxes or [unit_block.bbox])
            )
            translated_formula_prose_bboxes_by_page.setdefault(
                unit_block.page_index,
                [],
            ).extend(formula_prose_bboxes)
        unit_plain = " ".join(strip_sentinels(unit_block.text).split()).strip()
        if (
            unit_block.block_type in {"heading", "run_in_heading"}
            and len(unit_plain) <= 90
            and unit_plain.endswith((":", "："))
            and any(
                bboxes_intersect(
                    expand_bbox(unit_block.bbox, 3.0),
                    expand_bbox(region, 3.0),
                )
                for region in preserved_regions_by_page.get(
                    unit_block.page_index,
                    [],
                )
            )
        ):
            # A translated run-in label may share one QA-merged row with
            # preserved pseudocode ("Action Skeleton:" + pick(...) -> ...).
            # Exempt only the compact heading bbox; the code remains compared.
            preserved_label_bboxes_by_page.setdefault(
                unit_block.page_index,
                [],
            ).append(expand_bbox(unit_block.bbox, 3.0))
        for keepout in unit_block.keepout_bboxes or []:
            keepout_bboxes_by_page.setdefault(unit_block.page_index, []).append(keepout)
    verbatim_sample_bboxes_by_page: Dict[int, List[BBox]] = {}
    for unit_page, page_units in translation_units_by_page.items():
        for unit_block in page_units:
            if _source_unit_is_verbatim_generated_sample(unit_block, page_units):
                verbatim_sample_bboxes_by_page.setdefault(unit_page, []).append(
                    expand_bbox(unit_block.bbox, 2.0)
                )
    for warning in fragmented_prose_warnings_from_units(source_units):
        match = re.search(r"Page (\d+):", warning)
        page = int(match.group(1)) if match else 0
        issues.append(
            TranslationIssue(
                page=page,
                code="fragmented_prose",
                message=warning,
                severity="warning",
            )
        )

    reference_section_active = False
    for page_idx in range(min(orig_doc.page_count, trans_doc.page_count)):
        orig_page = orig_doc[page_idx]
        trans_page = trans_doc[page_idx]

        # Check for untranslated English paragraphs
        orig_blocks = orig_page.get_text("dict").get("blocks", [])
        trans_blocks = trans_page.get_text("dict").get("blocks", [])
        translated_region_entries = _text_entries_from_blocks(trans_blocks)
        preserved_original_region_entries = _preserved_text_entries_from_blocks(
            orig_blocks
        )
        preserved_translated_region_entries = _preserved_text_entries_from_blocks(
            trans_blocks
        )
        orig_text = _text_from_blocks(orig_blocks)
        trans_text = _text_from_blocks(trans_blocks)
        issues.extend(
            _placeholder_leak_issues(page_idx + 1, orig_text, trans_text)
        )
        visual_regions = _visual_regions_for_page(orig_page, blocks=orig_blocks)
        preserved_regions = preserved_regions_by_page.get(page_idx, [])
        equation_rows = equation_rows_by_page.get(page_idx, [])
        preserved_text_regions = _preserved_text_qa_regions(preserved_regions)
        reference_y = _reference_section_start_y(trans_page, blocks=trans_blocks)
        if reference_y is None:
            reference_y = _reference_section_start_y(orig_page, blocks=orig_blocks)
        if reference_y is not None:
            reference_section_active = True
        elif reference_section_active and (
            _page_looks_like_reference_continuation(trans_page, blocks=trans_blocks)
            or _page_looks_like_reference_continuation(orig_page, blocks=orig_blocks)
        ):
            reference_y = 0.0
        else:
            reference_section_active = False

        # Count English-only text blocks in translated PDF
        untranslated_examples: List[str] = []
        untranslated_coordinates: List[BBox] = []
        untranslated_caption_examples: List[str] = []
        untranslated_formula_examples: List[str] = []
        untranslated_natural_language_examples: List[str] = []
        untranslated_natural_language_coordinates: List[BBox] = []
        preserved_changed_examples: List[str] = []
        page_formula_keepouts = keepout_bboxes_by_page.get(page_idx, [])
        page_caption_bboxes = caption_bboxes_by_page.get(page_idx, [])
        page_preserved_label_bboxes = preserved_label_bboxes_by_page.get(
            page_idx,
            [],
        )
        preserved_original_entries = _entries_outside_caption_bands(
            preserved_original_region_entries,
            page_caption_bboxes,
        )
        preserved_original_entries = _entries_outside_caption_bands(
            preserved_original_entries,
            page_preserved_label_bboxes,
        )
        page_formula_prose_bboxes = translated_formula_prose_bboxes_by_page.get(
            page_idx,
            [],
        )
        preserved_original_entries = _entries_outside_caption_bands(
            preserved_original_entries,
            page_formula_prose_bboxes,
        )
        preserved_translated_entries = _entries_outside_caption_bands(
            preserved_translated_region_entries,
            _extend_caption_bands_for_translated(
                page_caption_bboxes,
                translated_region_entries,
            ),
            base_bboxes=page_caption_bboxes,
        )
        preserved_translated_entries = _entries_outside_caption_bands(
            preserved_translated_entries,
            page_preserved_label_bboxes,
            base_bboxes=page_preserved_label_bboxes,
        )
        preserved_translated_entries = _entries_outside_caption_bands(
            preserved_translated_entries,
            page_formula_prose_bboxes,
            base_bboxes=page_formula_prose_bboxes,
        )
        for region in preserved_text_regions:
            original_region_text = _text_overlapping_region(
                preserved_original_entries,
                region,
            )
            if not original_region_text:
                continue
            translated_region_text = _text_overlapping_region(
                preserved_translated_entries,
                region,
            )
            if preserved_region_text_changed(original_region_text, translated_region_text):
                # Redaction can damage a nested source Form even when the
                # protected atom itself was untouched. Its raster repair is
                # intentionally visual-only so image-internal labels do not
                # re-enter the document text layer. Accept an absent semantic
                # copy only when the restored ink still matches the source.
                if (
                    not translated_region_text.strip()
                    and _formula_ink_similarity(
                        orig_page,
                        region,
                        trans_page,
                        region,
                    )
                    >= 0.94
                ):
                    continue
                preserved_changed_examples.append(" ".join(original_region_text.split())[:80])
                if len(preserved_changed_examples) >= 3:
                    break
        for block in trans_blocks:
            if block.get("type") != 0:
                continue
            if _block_in_reference_section(block, reference_y):
                continue
            if _block_overlaps_preserved_regions(
                block,
                verbatim_sample_bboxes_by_page.get(page_idx, []),
                min_total_overlap=0.55,
            ):
                continue
            text = _extract_text_from_block(block)
            if _looks_like_untranslated_caption(text):
                untranslated_caption_examples.append(" ".join(text.split())[:80])
            elif _looks_like_stranded_formula_prose_tail(text):
                if (
                    _block_overlaps_preserved_regions(block, preserved_regions)
                    and _block_inside_visual_region(block, visual_regions)
                    and not _visual_region_block_should_translate(block, text)
                ):
                    continue
                untranslated_formula_examples.append(" ".join(text.split())[:80])
            elif _looks_like_untranslated_formula_explanation(text):
                if _block_overlaps_preserved_regions(block, preserved_regions):
                    continue
                untranslated_formula_examples.append(" ".join(text.split())[:80])
            elif _looks_like_untranslated_english(text):
                if _block_overlaps_preserved_regions(
                    block,
                    equation_rows,
                    min_total_overlap=0.55,
                ):
                    continue
                if _block_overlaps_preserved_regions(block, preserved_regions):
                    continue
                if page_formula_keepouts and _block_overlaps_preserved_regions(
                    block,
                    page_formula_keepouts,
                    min_total_overlap=0.5,
                ):
                    continue
                if (
                    _block_inside_visual_region(block, visual_regions)
                    and not _visual_region_block_should_translate(block, text)
                ):
                    continue
                untranslated_examples.append(" ".join(text.split())[:80])
                if block.get("bbox"):
                    untranslated_coordinates.append(
                        tuple(float(value) for value in block["bbox"])
                    )

        for source_block in translation_units_by_page.get(page_idx, []):
            if _source_unit_is_verbatim_generated_sample(
                source_block,
                translation_units_by_page.get(page_idx, []),
            ):
                continue
            translated_unit_text = _text_overlapping_region(
                translated_region_entries,
                expand_bbox(source_block.bbox, 2.0),
            )
            source_plain = " ".join(strip_sentinels(source_block.text).split())
            translated_plain = " ".join(translated_unit_text.split())
            if (
                _looks_like_cjk_file_payload(translated_plain)
                or _looks_like_translated_identifier_payload(translated_plain)
            ):
                continue
            short_structure_echo = (
                looks_like_academic_structure_heading(source_block, source_plain)
                and source_plain.casefold() in translated_plain.casefold()
            )
            if _translation_retains_foreign_prose(
                source_block,
                translated_unit_text,
            ):
                example = " ".join(translated_unit_text.split())[:80]
                if example and example not in untranslated_natural_language_examples:
                    untranslated_natural_language_examples.append(example)
                    untranslated_natural_language_coordinates.append(source_block.bbox)
            if (
                not short_structure_echo
                and not _translation_retains_source_prose_run(
                    source_block,
                    translated_unit_text,
                )
            ):
                continue
            example = " ".join(translated_unit_text.split())[:80]
            if example and example not in untranslated_examples:
                untranslated_examples.append(example)
                untranslated_coordinates.append(source_block.bbox)

        if untranslated_examples:
            location = untranslated_coordinates[0] if untranslated_coordinates else None
            location_text = (
                f" at x={location[0]:.1f}, y={location[1]:.1f}"
                if location is not None
                else ""
            )
            issues.append(
                TranslationIssue(
                    page=page_idx + 1,
                    code="untranslated_english",
                    message=(
                        f"Page {page_idx + 1}: {len(untranslated_examples)} block(s) "
                        "look like untranslated English outside references/formulas"
                        f"{location_text}; example: {untranslated_examples[0]}"
                    ),
                    severity="error",
                )
            )
        if untranslated_caption_examples:
            issues.append(
                TranslationIssue(
                    page=page_idx + 1,
                    code="untranslated_caption",
                    message=(
                        f"Page {page_idx + 1}: {len(untranslated_caption_examples)} caption(s) "
                        "still look like English and should be translated"
                    ),
                    severity="error",
                )
            )
        if untranslated_formula_examples:
            issues.append(
                TranslationIssue(
                    page=page_idx + 1,
                    code="untranslated_formula_explanation",
                    message=(
                        f"Page {page_idx + 1}: {len(untranslated_formula_examples)} formula "
                        "explanation block(s) still look like English"
                    ),
                    severity="error",
                )
            )
        if untranslated_natural_language_examples:
            location = untranslated_natural_language_coordinates[0]
            issues.append(
                TranslationIssue(
                    page=page_idx + 1,
                    code="untranslated_natural_language",
                    message=(
                        f"Page {page_idx + 1}: "
                        f"{len(untranslated_natural_language_examples)} block(s) retain "
                        "source-language natural text outside references/formulas at "
                        f"x={location[0]:.1f}, y={location[1]:.1f}; example: "
                        f"{untranslated_natural_language_examples[0]}"
                    ),
                    severity="error",
                )
            )
        if preserved_changed_examples:
            issues.append(
                TranslationIssue(
                    page=page_idx + 1,
                    code="preserved_text_changed",
                    message=(
                        f"Page {page_idx + 1}: {len(preserved_changed_examples)} preserved "
                        "table/algorithm/metadata region(s) appear translated or altered"
                        f"; example: {preserved_changed_examples[0]}"
                    ),
                    severity="error",
                )
            )

        # Check for overlapping text blocks in translated PDF
        text_bboxes = []
        for block in trans_blocks:
            if block.get("type") != 0:
                continue
            if _block_in_reference_section(block, reference_y):
                continue
            for bbox, text in _overlap_text_entries_from_block(block):
                if (
                    len(text.strip()) < 4
                    or _is_reference_or_formula_text(text)
                    or _looks_like_overlap_exempt_text(text)
                ):
                    continue
                if _block_overlaps_preserved_regions(
                    {"bbox": bbox},
                    preserved_regions,
                    min_total_overlap=0.55,
                ):
                    continue
                text_bboxes.append((bbox, text))

        for i in range(len(text_bboxes)):
            for j in range(i + 1, len(text_bboxes)):
                (x0a, y0a, x1a, y1a), text_a = text_bboxes[i]
                (x0b, y0b, x1b, y1b), text_b = text_bboxes[j]
                h_overlap = max(0, min(x1a, x1b) - max(x0a, x0b))
                v_overlap = max(0, min(y1a, y1b) - max(y0a, y0b))
                if h_overlap > 10 and v_overlap > 8:
                    issues.append(
                        TranslationIssue(
                            page=page_idx + 1,
                            code="text_overlap",
                            message=(
                                f"Page {page_idx + 1}: text blocks overlap near "
                                f"y={max(y0a, y0b):.0f}"
                            ),
                            severity=(
                                "error"
                                if _CJK_DETECT_RE.search(text_a)
                                and _CJK_DETECT_RE.search(text_b)
                                else "warning"
                            ),
                        )
                    )
                    break

        issues.extend(
            _caption_graphic_overlap_issues(
                orig_page,
                trans_page,
                page_idx + 1,
                original_blocks=orig_blocks,
                translated_blocks=trans_blocks,
                visual_regions=visual_regions,
            )
        )
        issues.extend(
            _font_role_consistency_issues(
                translation_units_by_page.get(page_idx, []),
                trans_page,
                page_idx + 1,
            )
        )
        issues.extend(
            _raster_ink_overlap_issues(
                orig_page,
                trans_page,
                page_idx + 1,
                source_blocks=translation_units_by_page.get(page_idx, []),
            )
        )
        issues.extend(
            _table_caption_clearance_issues(
                orig_page,
                trans_page,
                page_idx + 1,
            )
        )

        # Check for empty translated page
        if len(orig_text.strip()) > 100 and len(trans_text.strip()) < 20:
            issues.append(
                TranslationIssue(
                    page=page_idx + 1,
                    code="empty_page",
                    message=f"Page {page_idx + 1}: translated page appears empty",
                    severity="error",
                )
            )

        orig_image_count, orig_image_area = _visible_image_stats(
            orig_page,
            blocks=orig_blocks,
        )
        trans_image_count, trans_image_area = _visible_image_stats(
            trans_page,
            blocks=trans_blocks,
        )
        image_count_missing = orig_image_count and trans_image_count < max(1, orig_image_count // 2)
        image_area_missing = (
            orig_image_area > 1.0 and trans_image_area < orig_image_area * 0.5
        )
        if image_count_missing or image_area_missing:
            issues.append(
                TranslationIssue(
                    page=page_idx + 1,
                    code="missing_image",
                    message=(
                        f"Page {page_idx + 1}: translated page has fewer visible image blocks "
                        f"({trans_image_count}/{orig_image_count})"
                    ),
                    severity="error",
                )
            )

        orig_graphics = _count_vector_graphics(orig_page)
        trans_graphics = _count_vector_graphics(trans_page)
        if orig_graphics and trans_graphics < max(1, orig_graphics // 2):
            issues.append(
                TranslationIssue(
                    page=page_idx + 1,
                    code="missing_graphic",
                    message=(
                        f"Page {page_idx + 1}: translated page has far fewer vector graphics "
                        f"({trans_graphics}/{orig_graphics})"
                    ),
                    severity="error",
                )
            )

        formula_fragments = _extract_formula_fragments(orig_page, blocks=orig_blocks)
        if formula_fragments:
            missing_formulas = _missing_formula_fragments(
                formula_fragments,
                [
                    _normalize_formula_fragment_for_compare(trans_text),
                    _normalize_formula_fragment_for_compare(trans_page.get_text("text")),
                    _normalize_formula_fragment_for_compare(
                        trans_page.get_text("text", sort=True)
                    ),
                ],
            )
            if missing_formulas:
                # Reflow can push a formula onto an adjacent page; only flag
                # fragments absent from the neighbouring pages too.
                neighbour_compacts = [
                    _normalize_formula_fragment_for_compare(
                        trans_doc[neighbour_idx].get_text("text")
                    )
                    for neighbour_idx in (page_idx - 1, page_idx + 1)
                    if 0 <= neighbour_idx < trans_doc.page_count
                ]
                missing_formulas = _missing_formula_fragments(
                    missing_formulas, neighbour_compacts
                )
            if missing_formulas:
                issues.append(
                    TranslationIssue(
                        page=page_idx + 1,
                        code="formula_changed",
                        message=(
                            f"Page {page_idx + 1}: {len(missing_formulas)} formula "
                            "fragment(s) appear missing or altered"
                        ),
                        severity="error",
                    )
                )

        inline_formula_fragments = _inline_formula_anchor_fragments(
            translation_units_by_page.get(page_idx, [])
        )
        if inline_formula_fragments:
            translated_formula_views = [
                _normalize_inline_formula_signature(trans_text),
                _normalize_inline_formula_signature(trans_page.get_text("text")),
            ]
            missing_inline_formulas = _missing_inline_formula_anchors(
                inline_formula_fragments,
                translated_formula_views,
            )
            if missing_inline_formulas:
                neighbour_formula_views = [
                    _normalize_inline_formula_signature(
                        trans_doc[neighbour_idx].get_text("text")
                    )
                    for neighbour_idx in (page_idx - 1, page_idx + 1)
                    if 0 <= neighbour_idx < trans_doc.page_count
                ]
                missing_inline_formulas = _missing_inline_formula_anchors(
                    missing_inline_formulas,
                    neighbour_formula_views,
                )
            if missing_inline_formulas:
                preview = missing_inline_formulas[0][:36]
                issues.append(
                    TranslationIssue(
                        page=page_idx + 1,
                        code="inline_formula_missing",
                        message=(
                            f"Page {page_idx + 1}: {len(missing_inline_formulas)} inline "
                            f"formula anchor(s) appear incomplete near {preview!r}"
                        ),
                        severity="error",
                    )
                )
        issues.extend(
            _formula_visible_ink_issues(
                orig_page,
                trans_page,
                translation_units_by_page.get(page_idx, []),
                page_idx + 1,
            )
        )

        for feature in _detect_high_risk_layout_features(
            orig_page,
            blocks=orig_blocks,
            page_text=orig_text,
        ):
            issues.append(
                TranslationIssue(
                    page=page_idx + 1,
                    code="high_risk_layout",
                    message=f"Page {page_idx + 1}: high-risk layout feature detected: {feature}",
                    severity="warning",
                )
            )

    try:
        from .visual_qa import score_visual_layout

        visual = score_visual_layout(original_pdf, translated_pdf)
        if getattr(visual, "page_count_delta", 0) != 0:
            issues.append(
                TranslationIssue(
                    page=0,
                    code="page_count_mismatch",
                    message=(
                        "Translated PDF page count differs from original "
                        f"({visual.translated_pages}/{visual.original_pages})"
                    ),
                    severity="error",
                )
            )
        if getattr(visual, "min_page_size_similarity", 1.0) < 0.85:
            worst = (
                min(
                    visual.pages,
                    key=lambda page: getattr(page, "page_size_similarity", 1.0),
                )
                if visual.pages
                else None
            )
            page_num = worst.page if worst else 0
            issues.append(
                TranslationIssue(
                    page=page_num,
                    code="page_size_mismatch",
                    message=(
                        "Rendered page size differs from original "
                        f"(similarity={visual.min_page_size_similarity:.2f})"
                    ),
                    severity="error",
                )
            )
        if visual.overall_score < 0.35:
            worst = min(visual.pages, key=lambda page: page.score) if visual.pages else None
            page_num = worst.page if worst else 0
            issues.append(
                TranslationIssue(
                    page=page_num,
                    code="visual_layout_score_low",
                    message=(
                        "Rendered layout similarity is low "
                        f"(score={visual.overall_score:.2f}); inspect visual output"
                    ),
                    severity="error",
                )
            )
        elif (
            visual.min_zone_score < 0.25
            and visual.overall_score < 0.90
            and _visual_min_zone_intersects_graphics(orig_doc, visual)
        ):
            worst = (
                min(visual.pages, key=lambda page: page.min_zone_score)
                if visual.pages
                else None
            )
            page_num = worst.page if worst else 0
            issues.append(
                TranslationIssue(
                    page=page_num,
                    code="visual_layout_region_low",
                    message=(
                        "Rendered layout has a low-similarity page region "
                        f"(overall={visual.overall_score:.2f}, "
                        f"min_region={visual.min_zone_score:.2f}); inspect figures/tables"
                    ),
                    severity="error",
                )
            )
    except Exception:
        pass

    try:
        from .page_inspector import inspect_translation

        issues.extend(inspect_translation(original_pdf, translated_pdf))
    except Exception as exc:
        issues.append(
            TranslationIssue(
                page=0,
                code="inspection_failed",
                message=f"Visual inspection pass failed: {exc}",
                severity="warning",
            )
        )

    trans_doc.close()
    orig_doc.close()
    return _dedupe_body_untranslated_issues(issues)


def _visual_min_zone_intersects_graphics(
    document: object,
    visual: object,
    *,
    grid_rows: int = 3,
    grid_cols: int = 2,
) -> bool:
    pages = getattr(visual, "pages", [])
    if not pages:
        return False
    worst = min(pages, key=lambda page: getattr(page, "min_zone_score", 1.0))
    zone_scores = getattr(worst, "zone_scores", ())
    if not zone_scores:
        return False
    min_zone_index = min(range(len(zone_scores)), key=zone_scores.__getitem__)
    page_number = int(getattr(worst, "page", 0))
    if page_number <= 0 or page_number > getattr(document, "page_count", 0):
        return False
    page = document[page_number - 1]
    regions = _visual_regions_for_page(page)
    if not regions:
        return False

    row = min_zone_index // grid_cols
    col = min_zone_index % grid_cols
    rect = page.rect
    zone = (
        float(rect.width) * col / grid_cols,
        float(rect.height) * row / grid_rows,
        float(rect.width) * (col + 1) / grid_cols,
        float(rect.height) * (row + 1) / grid_rows,
    )
    zone_area = max(1.0, bbox_area(zone))
    return any(bbox_intersection_area(zone, region) / zone_area >= 0.02 for region in regions)


def _extract_text_from_block(block: dict) -> str:
    text = ""
    for line in block.get("lines", []):
        for span in line.get("spans", []):
            text += span.get("text", "")
    return text.strip()


def _text_from_blocks(blocks: Sequence[dict]) -> str:
    lines: List[str] = []
    for block in blocks:
        if block.get("type") != 0:
            continue
        for line in block.get("lines", []):
            text = "".join(span.get("text", "") for span in line.get("spans", []))
            if text.strip():
                lines.append(text)
    return "\n".join(lines)


def _page_text_overlapping_region(page: object, region: BBox) -> str:
    blocks = page.get_text("dict").get("blocks", [])
    return _text_overlapping_region(_text_entries_from_blocks(blocks), region)


def _text_entries_from_blocks(blocks: Sequence[dict]) -> List[Tuple[BBox, str]]:
    entries: List[Tuple[BBox, str]] = []
    for block in blocks:
        if block.get("type") != 0:
            continue
        entries.extend(_overlap_text_entries_from_block(block))
    return entries


def _preserved_text_entries_from_blocks(
    blocks: Sequence[dict],
) -> List[Tuple[BBox, str]]:
    """Use span-level entries when prose and formula share one PDF line.

    Redaction can split a source mixed line into several translated text
    objects. Comparing the source line hull with those smaller objects changes
    which neighboring formula atoms cross the overlap threshold. Keeping each
    span as the comparison unit makes the preserved formula signature stable
    across that harmless object rewrite while ordinary prose remains line-level.
    """
    entries: List[Tuple[BBox, str]] = []
    for block in blocks:
        if block.get("type") != 0:
            continue
        block_entries: List[Tuple[BBox, str]] = []
        for line in block.get("lines", []):
            spans = [
                span
                for span in line.get("spans", [])
                if span.get("text", "").strip() and len(span.get("bbox", ())) == 4
            ]
            line_max_size = max(
                (float(span.get("size", 0.0)) for span in spans),
                default=0.0,
            )
            has_math_span = any(
                is_math_span(
                    str(span.get("font", "")),
                    int(span.get("flags", 0)),
                    str(span.get("text", "")),
                    float(span.get("size", 0.0)),
                    line_max_size,
                )
                for span in spans
            )
            if not has_math_span:
                line_text = "".join(span.get("text", "") for span in spans).strip()
                bbox = line.get("bbox")
                if line_text and bbox:
                    block_entries.append(
                        (tuple(float(value) for value in bbox), line_text)
                    )
                continue
            block_entries.extend(
                (
                    tuple(float(value) for value in span["bbox"]),
                    str(span.get("text", "")).strip(),
                )
                for span in spans
            )
        if block_entries:
            entries.extend(block_entries)
        else:
            entries.extend(_overlap_text_entries_from_block(block))
    return entries


def _extend_caption_bands_for_translated(
    caption_bboxes: Sequence[BBox],
    entries: Sequence[Tuple[BBox, str]],
    *,
    join_gap: float = 18.0,
    max_extra: float = 60.0,
) -> List[BBox]:
    """Grow caption bands downward over wrapped translated caption lines.

    Translated captions keep their anchor position but often wrap one or two
    lines taller than the English source — and when the translation needs
    one line more than the source bbox held, the orphan tail lands a full
    line-height below, just above the table's header row. Chain through CJK
    lines that start inside the band so those continuation lines are
    excluded from preserved-region comparison; English/numeric table rows
    stop the chain only indirectly (they are never CJK).
    """
    extended: List[BBox] = []
    for band in caption_bboxes:
        x0, y0, x1, y1 = band
        limit = y1 + max_extra
        changed = True
        while changed:
            changed = False
            for (ex0, ey0, ex1, ey1), text in entries:
                if ex1 <= x0 or ex0 >= x1:
                    continue
                if not _CJK_DETECT_RE.search(text):
                    continue
                if y0 <= ey0 <= y1 + join_gap and ey1 > y1 and ey1 <= limit:
                    y1 = ey1
                    changed = True
        extended.append((x0, y0, x1, y1))
    return extended


def _entries_outside_caption_bands(
    entries: Sequence[Tuple[BBox, str]],
    caption_bboxes: Sequence[BBox],
    *,
    min_overlap_ratio: float = 0.5,
    base_bboxes: Optional[Sequence[BBox]] = None,
) -> List[Tuple[BBox, str]]:
    """Drop text entries that sit mostly inside translated-caption bands.

    When ``base_bboxes`` (the unextended bands) is given, entries inside the
    extension zone are only dropped if they carry CJK text: the downward
    extension may vertically overlap preserved English table rows, and those
    rows must stay visible to the preserved-region comparison.
    """
    if not caption_bboxes:
        return list(entries)

    def _mostly_inside(bbox: BBox, bands: Sequence[BBox]) -> bool:
        area = max(0.1, bbox_area(bbox))
        return any(
            bbox_intersection_area(bbox, band) / area >= min_overlap_ratio
            for band in bands
        )

    excluded_cjk_bboxes: List[BBox] = []
    if base_bboxes is not None:
        excluded_cjk_bboxes = [
            bbox
            for bbox, text in entries
            if _CJK_DETECT_RE.search(text) and _mostly_inside(bbox, caption_bboxes)
        ]

    def _glued_to_excluded_cjk(bbox: BBox) -> bool:
        """Inline continuation of an excluded CJK caption line.

        Only fragments that START AFTER the CJK line's right edge count —
        they read as the same sentence ("分辨率为64" + "×64."). Entries
        horizontally overlapping the caption line are content underneath it
        (e.g. table header cells) and must stay visible to the comparison.
        The gap is capped at a single space: table cells sitting after a
        wrapped caption line start farther away.
        """
        height = max(0.1, bbox[3] - bbox[1])
        for other in excluded_cjk_bboxes:
            vertical_overlap = min(bbox[3], other[3]) - max(bbox[1], other[1])
            if vertical_overlap / height < 0.5:
                continue
            if 0.0 <= bbox[0] - other[2] <= 3.0:
                return True
        return False

    kept: List[Tuple[BBox, str]] = []
    for bbox, text in entries:
        if _mostly_inside(bbox, caption_bboxes):
            if (
                base_bboxes is None
                or _mostly_inside(bbox, base_bboxes)
                or _CJK_DETECT_RE.search(text)
                or _glued_to_excluded_cjk(bbox)
            ):
                continue
        kept.append((bbox, text))
    return kept


def _text_overlapping_region(
    entries: Sequence[Tuple[BBox, str]],
    region: BBox,
) -> str:
    pieces: List[str] = []
    for bbox, text in entries:
        if bbox_intersection_area(bbox, region) / max(1.0, bbox_area(bbox)) >= 0.55:
            pieces.append(text)
    return " ".join(pieces)


def preserved_region_text_changed(original_text: str, translated_text: str) -> bool:
    action_call_re = re.compile(
        r"\b(?:pick|pull|place|push)\s*\([^()]{0,120}\)",
        re.IGNORECASE,
    )
    original_actions = [
        " ".join(call.lower().split())
        for call in action_call_re.findall(original_text)
    ]
    if original_actions:
        translated_actions = [
            " ".join(call.lower().split())
            for call in action_call_re.findall(translated_text)
        ]
        original_arrows = len(re.findall(r"(?:→|⇒|->)", original_text))
        translated_arrows = len(re.findall(r"(?:→|⇒|->)", translated_text))
        if (
            original_actions != translated_actions
            or original_arrows != translated_arrows
        ):
            return True
    original_words = [
        word.lower()
        for word in _ASCII_WORD_DETECT_RE.findall(original_text)
        if len(word) >= 3
    ]
    original_numbers = sorted(_preserved_numeric_tokens(original_text))
    translated_numbers = sorted(_preserved_numeric_tokens(translated_text))
    if original_numbers and original_numbers != translated_numbers:
        return True
    if not original_words:
        return False
    translated_lower = " ".join(translated_text.lower().split())
    if not translated_lower:
        return True
    if (
        not _CJK_DETECT_RE.search(original_text)
        and len(_CJK_DETECT_RE.findall(translated_text)) >= 2
        and not _preserved_region_looks_like_formula(original_text)
    ):
        return True
    checked = 0
    missing = 0
    for word in original_words[:8]:
        checked += 1
        if word not in translated_lower:
            missing += 1
    return checked > 0 and missing / checked >= 0.6


def _preserved_numeric_tokens(text: str) -> List[str]:
    return [
        token.replace("−", "-")
        for token in _PRESERVED_NUMERIC_TOKEN_RE.findall(text)
    ]


def _preserved_region_looks_like_formula(text: str) -> bool:
    if looks_like_math(text):
        return True
    has_math_identifier = bool(
        re.search(r"\b(?:max|min|argmax|argmin|cos|sin|exp|log|clip)\b", text, re.IGNORECASE)
        or re.search(r"[\u0370-\u03ff\u2190-\u22ff]", text)
    )
    return "=" in text and has_math_identifier


def _preserved_text_qa_regions(regions: Sequence[BBox]) -> List[BBox]:
    """Merge adjacent formula/table atoms before comparing preserved text.

    PDF extractors often collapse several neighboring source glyph boxes into
    one translated-page text line. Comparing each atom independently then
    reports a missing cell even when the original formula is unchanged. Float
    envelopes are useful for reflow avoidance, but comparing all text inside
    them can absorb unrelated prose beside a table or figure. When an envelope
    contains several concrete protected atoms, compare those atoms instead.
    """
    unique_regions = list(dict.fromkeys(regions))
    atomic_regions: List[BBox] = []
    for region in unique_regions:
        contained_atoms = 0
        for candidate in unique_regions:
            if candidate == region:
                continue
            candidate_area = bbox_area(candidate)
            if candidate_area <= 0.0 or candidate_area >= bbox_area(region):
                continue
            if bbox_intersection_area(candidate, region) / candidate_area >= 0.98:
                contained_atoms += 1
                if contained_atoms >= 3:
                    break
        if contained_atoms < 3:
            atomic_regions.append(region)
    return merge_nearby_bboxes(atomic_regions, PRESERVED_TEXT_QA_MERGE_GAP)


def _overlap_text_entries_from_block(block: dict) -> List[Tuple[BBox, str]]:
    """Return line-level text bboxes for overlap QA.

    PyMuPDF may group table/grid text from several rows and columns into one
    text block. Using the outer block bbox then creates false overlaps even
    when no glyphs touch, so overlap QA works at physical-line granularity.
    """
    entries: List[Tuple[BBox, str]] = []
    for line in block.get("lines", []):
        spans = line.get("spans", [])
        line_text = "".join(span.get("text", "") for span in spans).strip()
        bbox = line.get("bbox")
        if line_text and bbox:
            prose_bboxes = [
                tuple(float(value) for value in span["bbox"])
                for span in spans
                if span.get("text", "").strip()
                and len(span.get("bbox", ())) == 4
                and not MATH_FONT_RE.search(str(span.get("font", "")))
                and not _is_reference_or_formula_text(span.get("text", ""))
            ]
            visible_bbox = union_bbox(prose_bboxes) if prose_bboxes else tuple(
                float(value) for value in bbox
            )
            entries.append((visible_bbox, line_text))
    if entries:
        return entries
    bbox = block.get("bbox")
    text = _extract_text_from_block(block)
    if text and bbox:
        return [(tuple(float(value) for value in bbox), text)]
    return []


def _is_reference_or_formula_text(text: str) -> bool:
    compact = " ".join(text.split())
    if not compact:
        return True
    if _looks_like_reference_entry_text(compact):
        return True
    compact_without_urls = " ".join(_URL_RE.sub(" ", compact).split())
    if not compact_without_urls:
        return True
    if _looks_like_code_or_symbolic_text(compact_without_urls):
        return True
    if looks_like_math(compact_without_urls):
        return True
    math_chars = sum(1 for char in compact_without_urls if char in MATH_SYMBOLS)
    return (
        math_chars >= 3
        and math_chars / max(len(compact_without_urls), 1) >= 0.08
    )


def _looks_like_split_parenthetical_gloss(text: str) -> bool:
    """A title-cased English glossary term split after its opening parenthesis."""
    match = re.fullmatch(
        r"(?P<term>[A-Z][A-Za-z]*(?:-[A-Z]?[A-Za-z]+)?"
        r"(?:\s+[A-Z][A-Za-z]*(?:-[A-Z]?[A-Za-z]+)?){1,7})"
        r"[)\uff09](?P<suffix>.*)",
        text,
    )
    if match is None:
        return False
    suffix = match.group("suffix")
    return bool(_CJK_DETECT_RE.search(suffix)) and not re.search(r"[.!?]", suffix)


def _looks_like_detached_prompt_code_fragment(text: str) -> bool:
    """Ignore a prompt code list split away from its translated field label."""
    call_re = re.compile(
        r"\b(?:pick|place|pull|push|on|inhand|under)\s*\([^()]{1,180}\)",
        re.IGNORECASE,
    )
    calls = call_re.findall(text)
    if len(calls) < 2:
        return False
    remainder = call_re.sub(" ", text)
    words = {word.casefold() for word in _ASCII_WORD_DETECT_RE.findall(remainder)}
    # A PDF line may begin or end halfway through a quoted object relation.
    object_vocabulary = {
        "box",
        "cube",
        "rack",
        "hook",
        "table",
        "cyan",
        "red",
        "blue",
        "yellow",
        "pick",
        "place",
        "pull",
        "push",
        "on",
        "under",
        "inhand",
    }
    return words <= object_vocabulary


def _looks_like_parenthetical_gloss_with_citation(text: str) -> bool:
    """Allow a translated first-use English term followed only by a citation."""
    match = re.fullmatch(
        r"(?:(?P<prefix>[A-Z][A-Za-z0-9.-]{1,15})\s*)?"
        r"[（(](?P<term>[^()（）\[\]]{2,100})[）)]\s*"
        r"\[(?P<citation>[^\[\]]{2,160})(?P<closed>\])?",
        text,
    )
    if match is None:
        return False
    term_words = re.findall(r"[A-Za-z][A-Za-z'-]*", match.group("term"))
    if not (1 <= len(term_words) <= 8) or not all(
        word[0].isupper() for word in term_words
    ):
        return False
    citation = match.group("citation")
    if not re.search(r"\b(?:19|20)\d{2}[a-z]?\b", citation):
        if match.group("closed") or not re.search(r"\b(?:et|al)\.?$", citation):
            return False
        return bool(
            re.fullmatch(
                r"[A-Z][A-Za-z'’-]*(?:\s+(?:and|et|al\.?|[A-Z][A-Za-z'’-]*)){0,5}",
                citation,
            )
        )
    residue = re.sub(r"\b(?:19|20)\d{2}[a-z]?\b", " ", citation)
    residue = re.sub(r"\b(?:and|et|al)\b\.?", " ", residue, flags=re.IGNORECASE)
    residue = re.sub(r"\b[A-Z][A-Za-z'’-]*\b", " ", residue)
    return not re.search(r"[A-Za-z]", residue)


_PROSE_SHAPED_WORD_RE = re.compile(r"^[A-Z]?[a-z]{1,}$")
_CONDITIONAL_PROB_RE = re.compile(r"\([^()]*\|[^()]*\)")
_CJK_SAMPLE_LABEL_RE = re.compile(r"^[\u4e00-\u9fff][^：:]{0,11}[：:]")
_CJK_SAMPLE_LABEL_KEYWORD_RE = re.compile(r"英语|英文|原文|提示|示例|样例|输入|输出")
_CJK_FILE_PAYLOAD_RE = re.compile(
    r"^(?:文件名|文件路径|路径)\s*[：:]\s*"
    r"(?P<payload>[A-Za-z0-9_.@~+\\/\-]+)$",
    re.IGNORECASE,
)


def _looks_like_cjk_sample_label(text: str) -> bool:
    """A translated sample-field label whose content is English by design.

    "较差的英语输入：Please provide ..." quotes model input/output kept
    verbatim; the label must carry an explicit sample cue so figure
    captions ("图6：...") and task records ("目标谓词集：...") stay checked.
    """
    match = _CJK_SAMPLE_LABEL_RE.match(text)
    if not match:
        return False
    return bool(_CJK_SAMPLE_LABEL_KEYWORD_RE.search(match.group(0)))


def _looks_like_cjk_file_payload(text: str) -> bool:
    """A translated filename/path label followed by one verbatim payload."""
    match = _CJK_FILE_PAYLOAD_RE.fullmatch(text)
    if match is None:
        return False
    payload = match.group("payload")
    return bool(
        "/" in payload
        or "\\" in payload
        or re.search(r"\.[A-Za-z0-9]{1,8}$", payload)
    )


def _looks_like_untranslated_english(text: str) -> bool:
    compact = " ".join(text.split())
    if len(compact) < 35 or _is_reference_or_formula_text(compact):
        return False
    if _looks_like_parenthetical_gloss_with_citation(compact):
        return False
    if _looks_like_split_parenthetical_gloss(compact):
        return False
    if _looks_like_detached_prompt_code_fragment(compact):
        return False
    # A CJK-labelled sample field ("较差的英语输入：Please provide ...") quotes
    # model input/output that stays verbatim by design.
    if _looks_like_cjk_sample_label(compact):
        return False
    if _looks_like_cjk_file_payload(compact):
        return False
    if _looks_like_translated_identifier_payload(compact):
        return False
    prompt_remainder = _without_structured_prompt_lists(compact)
    if (
        prompt_remainder != compact
        and len(_CJK_DETECT_RE.findall(compact)) >= 2
    ):
        compact = " ".join(prompt_remainder.split())
    if _looks_like_model_or_identifier_list_text(compact):
        return False
    if _looks_like_prompt_output_field_list(compact):
        return False
    if _looks_like_compact_control_table_row(compact):
        return False
    if _looks_like_author_or_affiliation_text(compact):
        return False
    if _looks_like_translated_metric_fragment(compact):
        return False
    # Judge the whole block on prose-shaped Latin words. Conditional
    # probability notation, dataset identifiers (SQuADv2, RACE-h) and math
    # words do not count as English prose.
    prose_basis = _CONDITIONAL_PROB_RE.sub(" ", compact)
    words = [
        word
        for word in _ASCII_WORD_DETECT_RE.findall(prose_basis)
        if _PROSE_SHAPED_WORD_RE.match(word) and word.lower() not in _MATH_WORDS
    ]
    if len(words) < 5:
        return False
    cjk_chars = len(_CJK_DETECT_RE.findall(compact))
    if cjk_chars >= max(4, len(words) // 2):
        return False
    ascii_letters = sum(1 for char in prose_basis if char.isascii() and char.isalpha())
    return ascii_letters / max(len(compact), 1) >= 0.45


_IDENTIFIER_PAYLOAD_RE = re.compile(
    r"\b(?:"
    r"[A-Za-z][A-Za-z0-9]*(?:_[A-Za-z0-9]+)+(?:\.[A-Za-z0-9]{2,5})?"
    r"|[A-Za-z][A-Za-z0-9]*(?:-[A-Za-z0-9]+){2,}"
    r")\b"
)


def _looks_like_translated_identifier_payload(text: str) -> bool:
    """Allow dataset task IDs and filenames embedded in translated prose."""
    identifiers = _IDENTIFIER_PAYLOAD_RE.findall(text)
    if not identifiers:
        return False
    strongly_structured = any(
        "-" in identifier and any(char.isdigit() for char in identifier)
        for identifier in identifiers
    )
    minimum_cjk = 2 if strongly_structured else 4
    if len(_CJK_DETECT_RE.findall(text)) < minimum_cjk:
        return False
    remainder = _IDENTIFIER_PAYLOAD_RE.sub(" ", text)
    prose_words = [
        word
        for word in _ASCII_WORD_DETECT_RE.findall(remainder)
        if _PROSE_SHAPED_WORD_RE.match(word)
        and word.lower() not in _MATH_WORDS
    ]
    return len(prose_words) <= 3


def _contains_untranslated_english_run(text: str) -> bool:
    """Detect a long English passage hidden inside an otherwise Chinese result."""
    if not _CJK_DETECT_RE.search(text):
        return False
    return any(
        _looks_like_untranslated_english(fragment)
        for fragment in _CJK_DETECT_RE.split(text)
        if fragment.strip()
    )


def _translation_contains_commentary(text: str) -> bool:
    """Reject model explanations accidentally returned alongside the translation."""
    compact = " ".join(text.split())
    if re.search(r"(?:这段|上述|以下).{0,10}(?:翻译|译文)", compact):
        return True
    if re.search(
        r"^\s*(?:here is|translation|translated text)\s*:",
        text,
        re.IGNORECASE | re.MULTILINE,
    ):
        return True
    section_markers = re.findall(
        r"^\s*(?:解释|步骤|翻译说明|译文说明|说明|注)\s*[：:]",
        text,
        re.MULTILINE,
    )
    numbered_steps = re.findall(r"^\s*\d+[.、]\s*", text, re.MULTILINE)
    return len(section_markers) >= 2 and len(numbered_steps) >= 2


def _looks_like_translated_metric_fragment(text: str) -> bool:
    """Allow Chinese prose lines that retain standard English metric labels."""
    if len(_CJK_DETECT_RE.findall(text)) < 2:
        return False
    metric_values = re.findall(
        r"\d+(?:\.\d+)?\s*(?:%|×|x\b|pp\b)",
        text,
        re.IGNORECASE,
    )
    if len(metric_values) < 2:
        return False
    allowed_metric_words = {
        "accuracy",
        "clock",
        "conflict",
        "error",
        "flops",
        "latency",
        "memory",
        "parameters",
        "params",
        "rate",
        "reduction",
        "runtime",
        "speedup",
        "success",
        "throughput",
        "time",
        "wall",
    }
    words = _ASCII_WORD_DETECT_RE.findall(text)
    return bool(words) and all(
        word.lower() in allowed_metric_words or word[:1].isupper()
        for word in words
    )


def _looks_like_model_or_identifier_list_text(text: str) -> bool:
    """Model-name stacks in tables are identifiers, not untranslated prose."""
    compact = " ".join(text.split())
    refs = re.findall(r"\[\d+\]", compact)
    if len(refs) < 4:
        return False
    without_refs = re.sub(r"\[\d+\]", " ", compact)
    if re.search(r"[。！？;；:：]", without_refs):
        return False
    words = _ASCII_WORD_DETECT_RE.findall(without_refs)
    if len(words) < max(4, len(refs) // 2):
        return False
    lowercase_words = [word for word in words if word.islower() and len(word) > 2]
    return len(lowercase_words) <= max(1, len(words) // 8)


def _looks_like_prompt_output_field_list(text: str) -> bool:
    """Prompt templates often preserve literal output field identifiers."""
    normalized = re.sub(r"[^a-z_]", "", text.lower())
    if not normalized:
        return False
    semantic_fields = (
        "robotness",
        "target_embodiment_match",
        "targetembodimentmatch",
        "interaction_preservation",
        "interactionpreservation",
        "scene_preservation",
        "scenepreservation",
    )
    perceptual_fields = (
        "naturalness",
        "artifact_absence",
        "artifactabsence",
        "local_coherence",
        "localcoherence",
    )
    semantic_hits = sum(1 for field in semantic_fields if field in normalized)
    perceptual_hits = sum(1 for field in perceptual_fields if field in normalized)
    return "reasoning" in normalized and (semantic_hits >= 3 or perceptual_hits >= 2)


def _looks_like_compact_control_table_row(text: str) -> bool:
    """Dense robotics/reward table rows are mostly identifiers and formulas."""
    compact = " ".join(text.split())
    lower = compact.lower()
    if len(compact) > 180:
        return False
    if not re.search(
        r"(?:locomotion|actuator|gravity|command|tracking|approach|ctrl|"
        r"court|ball\s*state|teammate\s*states|action\s*penalty|reward)",
        lower,
    ):
        return False
    if not (
        any(token in compact for token in ("=", "[", "]", "¬", "−", "+", "×"))
        or "exp(" in lower
        or re.search(r"(?:\d[A-Za-z]|[A-Za-z]\d)", compact)
    ):
        return False
    words = _ASCII_WORD_DETECT_RE.findall(compact)
    if len(words) > 24:
        return False
    body_cues = ("propose", "proposed", "show", "shows", "evaluate", "evaluates", "however")
    return not any(cue in lower for cue in body_cues)


def _looks_like_author_or_affiliation_text(text: str) -> bool:
    compact = " ".join(text.split())
    # Brace groups only signal affiliation e-mail lists ("{alice,bob}@edu");
    # a bare "{traj}" from a restored LaTeX subscript must not exempt a whole
    # formula-dense paragraph from untranslated-English detection.
    if "@" in compact or re.search(r"\{[^{}]{2,60}(?:,[^{}]{1,60})+\}", compact):
        return True
    authorish = re.sub(r"(?<=[a-z])\d+(?=[A-Z])", " ", compact)
    names = re.findall(r"\b[A-Z][A-Za-z-]+(?:\s+[A-Z][A-Za-z-]+)+", authorish)
    lower = compact.lower()
    body_verbs = (
        "propose",
        "proposed",
        "show",
        "shows",
        "using",
        "improve",
        "improves",
        "evaluate",
        "evaluates",
    )
    title_tokens = re.findall(r"\b[A-Z][A-Za-z-]+\b", authorish)
    lowercase_words = re.findall(r"\b[a-z]{3,}\b", authorish)
    if re.search(r"[∗†‡*]", compact):
        return (
            len(names) >= 3
            or compact.count(",") >= 3
            or (len(title_tokens) >= 5 and len(lowercase_words) <= 1)
        )
    if compact.count(",") >= 4 and len(names) >= 3:
        return True
    if (
        len(compact) <= 220
        and compact.count(",") >= 3
        and re.search(r"\b[A-Z][A-Za-z´'’.-]+,\s*[A-Z]\.?", compact)
    ):
        return not any(verb in lower for verb in body_verbs)
    if (
        len(compact) <= 220
        and len(title_tokens) >= 5
        and len(lowercase_words) <= 1
        and not re.search(r"[.!?。！？]", compact)
    ):
        return not any(verb in lower for verb in body_verbs)
    if len(compact) <= 220 and len(names) >= 4:
        return not any(verb in lower for verb in body_verbs)
    return False


def _looks_like_code_or_symbolic_text(text: str) -> bool:
    compact = " ".join(text.split())
    lower = compact.lower()
    words = _ASCII_WORD_DETECT_RE.findall(compact)
    if re.search(r"^(?:#|>>>|\.\.\.)\s*", compact):
        return True
    if re.search(r"\b(?:def|class)\s+\w+\s*\(", compact):
        return True
    if re.search(r"^\s*(?:import|from)\s+[A-Za-z_][\w.]*", compact):
        return True
    if re.search(r"\b(?:np|numpy|mcdc|h5py)\s*\.", compact):
        return True
    if re.search(
        r"\b(?:MaterialMG|Surface|Cell|Universe|Source|Tally|MeshTally|array)\s*\(",
        compact,
    ):
        return True
    if re.search(r"\b[a-z][a-z0-9]*_[a-z0-9_]*\b", compact):
        if any(marker in compact for marker in (":", "=", "-", "(", ")", "[", "]")):
            return True
    if re.search(r"^\s*\d+\s*:\s*[A-Za-z]", compact):
        return True
    if (
        re.search(r"^\s*(?:Require|Ensure|Input|Output)\s*:", compact, re.IGNORECASE)
        and len(words) <= 14
        and not re.search(r"[.!?。！？]", compact)
    ):
        return True
    if (
        re.search(r"\b[a-z_][\w-]*\s*:\s*", lower)
        and compact.count(":") >= 2
        and not re.search(r"[.!?。！？]", compact)
    ):
        return True
    if any(token in compact for token in ("✓", "——", "———")):
        return True
    if any(token in compact for token in (":=", "setdefault(", "supp[", "ρ", "π", "ϕ", "χ", "ξ")):
        return True
    if re.search(r"\[[0-9]+\]", compact) and len(words) <= 16:
        if re.search(r"\b(?:VoteNet|ScanRefer|ViewRefer|Success|Rate|Drop|Stage)\b", compact):
            return True
    if (
        re.search(r"\[[0-9]+\]", compact)
        and len(words) <= 30
        and (
            re.search(r"\b(?:Objects?|Geometry|Geom|Prior)\b", compact)
            or (
                ("Regular" in compact or "Irregular" in compact)
                and ("AC" in compact or "GA" in compact)
            )
        )
    ):
        return True
    camel_tokens = re.findall(r"\b[A-Z][A-Za-z0-9]*(?:[A-Z][a-z0-9]+)+\b", compact)
    if len(camel_tokens) >= 2 and len(words) <= 16 and not re.search(r"[.!?。！？]", compact):
        return True
    greek_chars = sum(1 for char in compact if "\u0370" <= char <= "\u03ff")
    math_chars = sum(1 for char in compact if char in MATH_SYMBOLS)
    if math_chars >= 2 and len(words) <= 18 and re.search(r"\b(?:for|return|end|do)\b", lower):
        return True
    if greek_chars >= 2 and (math_chars >= 1 or "supp" in lower):
        return True
    if greek_chars >= 2 and len(words) <= 12 and re.search(
        r"\b(?:dataset|error|rate|lrt|gap|centroid|feat|diff)\b",
        lower,
    ):
        return True
    if greek_chars >= 2 and len(words) <= 12 and not re.search(r"[.!?。！？]", compact):
        return True
    return False


def _looks_like_overlap_exempt_text(text: str) -> bool:
    compact = " ".join(text.split())
    if not compact:
        return True
    if not re.search(r"[A-Za-z0-9\u3400-\u9fff]", compact):
        return True
    control_chars = sum(1 for char in compact if ord(char) < 32)
    if control_chars >= 2:
        return True
    if _looks_like_code_or_symbolic_text(compact) or looks_like_math(compact):
        return True

    words = _PROSE_WORD_RE.findall(compact)
    math_chars = sum(1 for char in compact if char in MATH_SYMBOLS)
    greek_chars = sum(1 for char in compact if "\u0370" <= char <= "\u03ff")
    math_punct_chars = sum(1 for char in compact if char in "(){}[],⟨⟩")
    digit_chars = sum(1 for char in compact if char.isdigit())
    if (math_chars + greek_chars + math_punct_chars) >= 2 and len(words) <= 12:
        return True
    if greek_chars >= 1 and math_punct_chars >= 1 and len(words) <= 12:
        return True
    if re.search(r"\b(?:[CX][st]?\(|Xs|Xt|Orel|lsub)\b", compact) and len(words) <= 16:
        return True
    if (
        re.search(
            r"\b(?:arg|max|min|log|exp|sim|softmax|crossentropy|mlp|cos|supp)\b",
            compact,
            re.IGNORECASE,
        )
        and (math_chars or digit_chars)
        and len(words) <= 14
    ):
        return True

    no_space = re.sub(r"\s+", "", compact)
    if len(no_space) <= 180 and re.search(r"(?:[dp]\d+){3,}", no_space, re.IGNORECASE):
        return True
    if len(no_space) <= 140 and digit_chars / max(len(no_space), 1) >= 0.25:
        return True
    if len(compact) <= 120 and len(words) <= 8:
        has_sentence_mark = bool(re.search(r"[。！？.!?]", compact))
        title_like = sum(1 for word in words if word[0].isupper()) >= 2
        if not has_sentence_mark and title_like:
            return True
    cjk_chars = len(_CJK_DETECT_RE.findall(compact))
    if cjk_chars >= 30 and not re.search(r"[，。；：！？]", compact):
        return True
    return False


def _looks_like_untranslated_caption(text: str) -> bool:
    compact = " ".join(text.split())
    if not _ENGLISH_CAPTION_PREFIX_RE.match(compact):
        return False
    body = _ENGLISH_CAPTION_PREFIX_RE.sub("", compact, count=1).strip()
    if not body or _CJK_DETECT_RE.search(body):
        return False
    return bool(_ASCII_WORD_DETECT_RE.search(body))


def _looks_like_untranslated_formula_explanation(text: str) -> bool:
    compact = " ".join(text.split())
    if len(compact) < 12 or not _FORMULA_EXPLANATION_RE.match(compact):
        return False
    if _CJK_DETECT_RE.search(compact):
        return False
    words = _ASCII_WORD_DETECT_RE.findall(compact)
    if len(words) < 3:
        return False
    has_symbol_signal = (
        any(char in MATH_SYMBOLS for char in compact)
        or bool(re.search(r"\\[A-Za-z]+|[α-ωΑ-Ω]|[_^]", compact))
        or bool(re.search(r"\b[A-Za-z]\s*(?:=|∈|∉|≤|≥|<|>|~)", compact))
    )
    has_variable_explanation = bool(
        re.search(
            r"\b[A-Za-z]\b\s+(?:denotes?|represents?|indicates?|is|are)\b",
            compact,
            re.IGNORECASE,
        )
    )
    if not (has_symbol_signal or has_variable_explanation):
        return False
    ascii_letters = sum(1 for char in compact if char.isascii() and char.isalpha())
    return ascii_letters / max(len(compact), 1) >= 0.35


def _looks_like_stranded_formula_prose_tail(text: str) -> bool:
    """Detect a sentence tail stranded beside a preserved formula fragment."""
    compact = " ".join(text.split())
    if _CJK_DETECT_RE.search(compact) or not compact.endswith((".", "?", "!")):
        return False
    if not re.match(
        r"^(?:and|or|which|whereas|respectively|correspondingly)\b",
        compact,
        re.IGNORECASE,
    ):
        return False
    words = [
        word
        for word in _ASCII_WORD_DETECT_RE.findall(compact)
        if _PROSE_SHAPED_WORD_RE.match(word) and word.lower() not in _MATH_WORDS
    ]
    return len(words) >= 2


def _reference_section_start_y(
    page: object,
    *,
    blocks: Optional[Sequence[dict]] = None,
) -> float | None:
    page_blocks = blocks if blocks is not None else page.get_text("dict").get("blocks", [])
    for block in page_blocks:
        if block.get("type") != 0:
            continue
        compact = " ".join(_extract_text_from_block(block).split()).rstrip(":：")
        if _REFERENCES_HEADING_RE.match(compact):
            bbox = block.get("bbox")
            if bbox:
                return max(0.0, float(bbox[1]) - 1.0)
    return None


def _page_looks_like_reference_continuation(
    page: object,
    *,
    blocks: Optional[Sequence[dict]] = None,
) -> bool:
    text_blocks: List[str] = []
    page_blocks = blocks if blocks is not None else page.get_text("dict").get("blocks", [])
    for block in page_blocks:
        if block.get("type") != 0:
            continue
        compact = " ".join(_extract_text_from_block(block).split())
        if len(compact) >= 20:
            text_blocks.append(compact)
    if not text_blocks:
        return False

    reference_like = sum(1 for text in text_blocks if _looks_like_reference_entry_text(text))
    numbered_entries = sum(len(re.findall(r"\[\d{1,3}\]", text)) for text in text_blocks)
    if reference_like >= 1 and numbered_entries >= 3:
        return True
    if reference_like >= 2:
        return True
    return reference_like == 1 and len(text_blocks) <= 4


def _strip_inline_citations(text: str) -> str:
    """Remove parenthesized/bracketed inline citations from prose.

    Body prose cites as "(Author et al., 2023; Other, 2024)" while reference
    entries carry their years/venues outside parentheses. Stripping these
    segments lets year/venue cues indicate genuine reference entries only.
    Leading text before an unmatched ")" (a block split mid-citation) is
    dropped for the same reason.
    """
    stripped = text
    for _ in range(4):
        reduced = re.sub(r"\([^()]*\)", " ", stripped)
        reduced = re.sub(r"\[[^\[\]]*\]", " ", reduced)
        if reduced == stripped:
            break
        stripped = reduced
    if "(" not in stripped:
        stripped = re.sub(r"^[^)]{0,120}\)", " ", stripped)
    return " ".join(stripped.split())


def _looks_like_reference_entry_text(text: str) -> bool:
    compact = " ".join(text.split())
    if not compact:
        return False
    numbered_questions = re.findall(
        r"(?:^|[?]\s+)\d{1,2}\.(?!\d)\s+"
        r"(?:can|could|do|does|how|is|are|what|when|where|which|why)\b",
        compact,
        re.IGNORECASE,
    )
    if (
        _REFERENCE_ENTRY_RE.search(compact)
        and not _LEADING_CITATION_PROSE_RE.match(compact)
        and not _LEADING_DISCOURSE_PROSE_RE.match(compact)
        # Numbered research questions can share a long PDF record with the
        # following citation-heavy prose (RT-2 p7). The leading ``1.`` alone
        # must not turn that whole record into a standalone bibliography.
        and len(numbered_questions) < 2
    ):
        return True
    # APA entries commonly start with a comma-separated author list followed
    # by ``(year).``.  The generic entry expression intentionally stays narrow,
    # and inline-citation stripping removes that parenthesized year later, so
    # recognize this unambiguous entry anchor before stripping citations.
    if (
        _REFERENCE_AUTHOR_START_RE.match(compact)
        and re.search(r"\((?:19|20)\d{2}[a-z]?\)\.", compact[:320], re.IGNORECASE)
        and len(numbered_questions) < 2
    ):
        return True
    sentence_count = len(re.findall(r"[.!?]\s+[A-Z]", compact))
    lower = compact.lower()
    if "doi" in lower or "arxiv" in lower or "http://" in lower or "https://" in lower:
        # A bare link or a short label such as "Project page: <URL>" is
        # metadata. A normal prose sentence remains body text.
        without_urls = _URL_RE.sub(" ", compact)
        if len(_ASCII_WORD_DETECT_RE.findall(without_urls)) <= 4:
            return True
    if len(compact) > 520 and sentence_count >= 2:
        return False
    if _BODY_PROSE_CITATION_CUE_RE.search(compact) and sentence_count >= 1:
        return False
    words = _ASCII_WORD_DETECT_RE.findall(compact)
    outside_citations = _strip_inline_citations(compact)
    if (
        len(compact) <= 220
        and _REFERENCE_YEAR_RE.search(outside_citations)
        and _REFERENCE_FRAGMENT_CUE_RE.search(outside_citations)
    ):
        cjk_chars = len(_CJK_DETECT_RE.findall(compact))
        return cjk_chars < max(4, len(words) // 3)
    if len(words) < 6 or not _REFERENCE_YEAR_RE.search(compact):
        if not _REFERENCE_FRAGMENT_CUE_RE.search(compact):
            return False
        authorish = bool(_REFERENCE_AUTHOR_START_RE.match(compact))
        if not authorish:
            return False
        if len(compact) > 420 and not _REFERENCE_YEAR_RE.search(compact):
            return False
    else:
        if not _REFERENCE_AUTHOR_START_RE.match(compact):
            return False
        # Prose paragraphs keep years only inside inline citations; genuine
        # reference entries keep the year in the running text.
        if not _REFERENCE_YEAR_RE.search(outside_citations):
            return False
    cjk_chars = len(_CJK_DETECT_RE.findall(compact))
    return cjk_chars < max(4, len(words) // 3)


_REFERENCE_NAME_PARTICLES = {
    "van", "von", "de", "del", "della", "der", "den", "di", "da",
    "dos", "das", "du", "la", "le", "lo", "ter", "ten", "te", "el",
    "bin", "ibn",
}


def _looks_like_reference_author_line(text: str) -> bool:
    """True for pre-segmented author leads of wrapped reference entries.

    "R. Mohammad Ebrahim and J. Razmi." matches the lettered appendix-heading
    shape, but inside the references range it is the author list of a wrapped
    entry and must not terminate the bibliography. Author lines are made of
    name tokens only (initials, capitalized surnames, particles) joined by
    "and"/","/"&" and end with a period — or with a wrap hyphen when the
    line breaks inside a surname ("... and A. W. Smeul-").
    """
    compact = " ".join(text.split()).strip()
    if len(compact) > 90:
        return False
    # Some two-column bibliographies wrap the entry title onto the next line,
    # leaving an author-only lead followed by the publication year.  The
    # leading initial also resembles an appendix marker (``Z. Chen ...``), so
    # recognize the complete author grammar before appendix termination runs.
    author_year = re.fullmatch(
        r"(?P<authors>.+\.)\s+(?:19|20)\d{2}[a-z]?\.",
        compact,
        re.IGNORECASE,
    )
    if author_year:
        authors = author_year.group("authors").rstrip(".")
        author_names = re.findall(
            r"(?:[A-Z]\.){1,4}\s+[A-Z][A-Za-z'’-]+",
            authors,
        )
        if len(author_names) >= 2 and _reference_author_tokens_only(authors):
            return True
    if re.match(
        r"^(?:[A-Z]\.\s*){1,4},\s+(?:and|&)\s+"
        r"[A-Z][A-Za-z'’-]+,\s+(?:[A-Z]\.\s*){1,4}"
        r"[A-Z][A-Za-z0-9'’-]*:",
        compact,
    ):
        return True
    # An author lead followed by the opening quote of the entry title
    # ("R. Girshick, ..., and J. Malik, “Rich feature") is a wrapped
    # reference fragment, not an appendix heading.
    quote_index = compact.find("\u201c")
    if quote_index > 0:
        lead = compact[:quote_index].strip().rstrip(",")
        if _REFERENCE_AUTHOR_START_RE.match(lead) and _reference_author_tokens_only(lead):
            return True
    # PDF columns can split the final author from the rest of an entry
    # (MobileNet p8: ``Y. Chen.``).  The terminal period distinguishes this
    # reference fragment from ordinary lettered headings such as ``A. Prompt``.
    if re.fullmatch(r"(?:[A-Z]\.){1,4}\s+[A-Z][A-Za-z'’-]+\.", compact):
        return True
    ends_with_wrap_hyphen = bool(re.search(r"[A-Za-z]-$", compact))
    if ends_with_wrap_hyphen:
        author_tokens = re.findall(
            r"(?:^|[,;]\s*|\band\s+)[A-Z]\.\s+[A-Z][A-Za-z'’-]+",
            compact,
        )
        if len(author_tokens) >= 2:
            return True
    if not (compact.endswith(".") or ends_with_wrap_hyphen):
        return False
    if not _REFERENCE_AUTHOR_START_RE.match(compact):
        return False
    body = compact[:-1]
    has_joiner = bool(re.search(r"(?:^|\s)(?:and|&)\s", body)) or "," in body
    has_mid_initial = bool(re.search(r"\s[A-Z]\.(?=\s|$)", body))
    if not (has_joiner or has_mid_initial):
        return False
    return _reference_author_tokens_only(body)


def _reference_author_tokens_only(body: str) -> bool:
    joiners = {"and", "&", "et", "al", "al."}
    for token in body.replace(",", " ").split():
        low = token.lower()
        if low in joiners or low in _REFERENCE_NAME_PARTICLES:
            continue
        if re.fullmatch(r"(?:[A-Z]\.){1,4}", token):
            continue
        if re.fullmatch(r"[A-Z][A-Za-z'’-]*\.?", token):
            continue
        return False
    return True


def _block_in_reference_section(block: dict, reference_y: float | None) -> bool:
    if reference_y is None:
        return False
    bbox = block.get("bbox")
    return bool(bbox and float(bbox[1]) >= reference_y)


def _block_inside_visual_region(
    block: dict,
    visual_regions: Sequence[BBox],
    *,
    min_overlap: float = 0.65,
) -> bool:
    bbox = block.get("bbox")
    if not bbox or not visual_regions:
        return False
    block_bbox = tuple(float(value) for value in bbox)
    area = max(1.0, bbox_area(block_bbox))
    return any(
        bbox_intersection_area(block_bbox, region) / area >= min_overlap
        for region in visual_regions
    )


def _visual_region_block_should_translate(block: dict, text: str) -> bool:
    """Match QA exemptions to the translator's graphic-prose classifier."""
    bbox = block.get("bbox")
    if not bbox:
        return False
    lines = [
        line
        for line in block.get("lines", [])
        if any(str(span.get("text", "")).strip() for span in line.get("spans", []))
    ]
    font_sizes = [
        float(span.get("size", 0.0))
        for line in lines
        for span in line.get("spans", [])
        if float(span.get("size", 0.0)) > 0.0
    ]
    candidate = TextBlock(
        page_index=0,
        bbox=tuple(float(value) for value in bbox),
        text=text,
        font_size=statistics.median(font_sizes) if font_sizes else 9.0,
        color=(0.0, 0.0, 0.0),
        source_lines=max(1, len(lines)),
    )
    return looks_like_translatable_graphic_prose(
        candidate,
        " ".join(strip_sentinels(text).split()),
    )


def _block_overlaps_preserved_regions(
    block: dict,
    regions: Sequence[BBox],
    *,
    min_total_overlap: float = 0.20,
) -> bool:
    bbox = block.get("bbox")
    if not bbox or not regions:
        return False
    block_bbox = tuple(float(value) for value in bbox)
    area = max(1.0, bbox_area(block_bbox))
    total_overlap = sum(bbox_intersection_area(block_bbox, region) for region in regions)
    return total_overlap / area >= min_total_overlap


def _span_uses_bold_weight(span: dict) -> bool:
    font = str(span.get("font", ""))
    return bool(
        int(span.get("flags", 0)) & FLAG_BOLD
        or _BOLD_FONT_RE.search(font)
        or re.search(r"(?:^|[-_])W[6-9](?:$|[-_])", font, re.IGNORECASE)
    )


def _span_is_short_structural_label(span: dict) -> bool:
    """True for an expected translated label such as ``任务：``."""
    text = " ".join(str(span.get("text", "")).split()).strip()
    if not text or not re.search(r"[:：]$", text):
        return False
    label = text.rstrip(":：").strip()
    if not label or len(label) > 24 or re.search(r"[。！？.!?]", label):
        return False
    return len(re.findall(r"[\u3400-\u9fff]", label)) <= 8


def _page_cjk_spans(page: object) -> List[dict]:
    return [
        span
        for block in page.get_text("dict").get("blocks", [])
        if block.get("type") == 0
        for line in block.get("lines", [])
        for span in line.get("spans", [])
        if re.search(r"[\u3400-\u9fff]", span.get("text", ""))
        and len(span.get("bbox", ())) == 4
    ]


def _spans_for_source_role(spans: Sequence[dict], block: TextBlock) -> List[dict]:
    region = expand_bbox(block.bbox, 2.0)
    output: List[dict] = []
    for span in spans:
        bbox = tuple(float(value) for value in span["bbox"])
        center_x = (bbox[0] + bbox[2]) / 2.0
        center_y = (bbox[1] + bbox[3]) / 2.0
        if bbox_contains_point(region, center_x, center_y):
            output.append(span)
    return output


def _rendered_run_in_prefix_assignments(
    spans: Sequence[dict],
    source_blocks: Sequence[TextBlock],
) -> Dict[int, int]:
    """Map expanded translated run-in prefix spans back to their source role."""
    assignments: Dict[int, int] = {}
    for block_index, block in enumerate(source_blocks):
        if block.block_type != "run_in_heading":
            continue
        source_baseline = block.bbox[3]
        # Column cascade can move a run-in paragraph by roughly two source
        # lines while preserving its bold-prefix boundary. Keep matching the
        # prefix by baseline within that bounded reflow distance; a genuinely
        # over-bold line still lacks the required following regular span.
        baseline_tolerance = max(4.0, block.font_size * 3.2)
        start_tolerance = max(4.0, block.font_size * 0.5)
        same_line = sorted(
            (
                span
                for span in spans
                if span.get("origin")
                and abs(float(span["origin"][1]) - source_baseline)
                <= baseline_tolerance
                and float(span["bbox"][0]) >= block.bbox[0] - start_tolerance
            ),
            key=lambda span: float(span["bbox"][0]),
        )
        if not same_line:
            continue
        first_index = next(
            (
                index
                for index, span in enumerate(same_line)
                if _span_uses_bold_weight(span)
                and abs(float(span["bbox"][0]) - block.bbox[0]) <= start_tolerance
            ),
            None,
        )
        if first_index is None:
            continue
        prefix_spans: List[dict] = []
        previous_right: Optional[float] = None
        has_regular_boundary = False
        for span in same_line[first_index:]:
            left = float(span["bbox"][0])
            if previous_right is not None and left - previous_right > start_tolerance:
                break
            if _span_uses_bold_weight(span):
                prefix_spans.append(span)
                previous_right = float(span["bbox"][2])
                continue
            if prefix_spans:
                has_regular_boundary = True
            break
        if has_regular_boundary:
            assignments.update((id(span), block_index) for span in prefix_spans)
    return assignments


def _font_role_consistency_issues(
    source_blocks: Sequence[TextBlock],
    translated_page: object,
    page_number: int,
) -> List[TranslationIssue]:
    """Audit translated CJK size, heading role, and run-in bold scope."""
    cjk_spans = _page_cjk_spans(translated_page)
    if not cjk_spans:
        return []

    rendered_run_in_assignments = _rendered_run_in_prefix_assignments(
        cjk_spans,
        source_blocks,
    )
    assignments: List[List[dict]] = [[] for _ in source_blocks]
    for span in cjk_spans:
        run_in_block_index = rendered_run_in_assignments.get(id(span))
        if run_in_block_index is not None:
            assignments[run_in_block_index].append(span)
            continue
        span_bbox = tuple(float(value) for value in span["bbox"])
        center_x = (span_bbox[0] + span_bbox[2]) / 2.0
        center_y = (span_bbox[1] + span_bbox[3]) / 2.0
        candidates: List[Tuple[int, float, int]] = []
        for index, block in enumerate(source_blocks):
            in_line = any(
                bbox_contains_point(expand_bbox(line_bbox, 2.0), center_x, center_y)
                for line_bbox in block.source_line_bboxes
            )
            in_block = bbox_contains_point(
                expand_bbox(block.bbox, 2.0),
                center_x,
                center_y,
            )
            if in_line or in_block:
                candidates.append((0 if in_line else 1, bbox_area(block.bbox), index))
        if candidates:
            assignments[min(candidates)[2]].append(span)

    # Reflow can push a translated heading a few points below its source
    # rectangle while the preceding paragraph grows into that rectangle.
    # In that case fixed-coordinate assignment attributes body text to the
    # heading and reports both missing bold and collapsed hierarchy. Recover
    # only an expected bold heading from the same column immediately below;
    # a genuinely regular/missing heading still has no candidate and remains
    # an error.
    claimed_cascaded_headings: set[int] = {
        id(span)
        for owner_index, assigned in enumerate(assignments)
        if source_blocks[owner_index].block_type in {"title", "heading", "run_in_heading"}
        for span in assigned
        if _span_uses_bold_weight(span)
    }
    for index, block in enumerate(source_blocks):
        if block.block_type not in {"heading", "run_in_heading"} or not block.bold:
            continue
        if any(_span_uses_bold_weight(span) for span in assignments[index]):
            continue
        x_tolerance = max(6.0, block.font_size * 0.75)
        y_tolerance = max(8.0, block.font_size * 3.2)
        candidates = [
            span
            for span in cjk_spans
            if id(span) not in claimed_cascaded_headings
            and _span_uses_bold_weight(span)
            and abs(float(span["bbox"][0]) - block.bbox[0]) <= x_tolerance
            and float(span["bbox"][1]) >= block.bbox[1] - 2.0
            and float(span["bbox"][1]) <= block.bbox[3] + y_tolerance
            and float(span["size"]) >= block.font_size * 0.65
        ]
        if not candidates:
            continue
        recovered = min(
            candidates,
            key=lambda span: (
                abs(float(span["bbox"][1]) - block.bbox[1]),
                abs(float(span["bbox"][0]) - block.bbox[0]),
            ),
        )
        for other_index, assigned in enumerate(assignments):
            if other_index != index:
                assignments[other_index] = [
                    span for span in assigned if id(span) != id(recovered)
                ]
        assignments[index] = [recovered]
        claimed_cascaded_headings.add(id(recovered))

    issues: List[TranslationIssue] = []
    ordinary_body_sizes: List[float] = []
    source_body_sizes = [
        block.font_size
        for block in source_blocks
        if block.block_type == "body" and not block.bold
    ]
    source_body_size = (
        statistics.median(source_body_sizes) if source_body_sizes else None
    )
    run_in_blocks = [
        block for block in source_blocks if block.block_type == "run_in_heading"
    ]
    for block, role_spans in zip(source_blocks, assignments):
        if not role_spans:
            continue
        if block.block_type == "title":
            line_groups: Dict[float, List[dict]] = {}
            for span in role_spans:
                origin = span.get("origin")
                baseline = float(origin[1]) if origin else float(span["bbox"][3])
                line_groups.setdefault(round(baseline, 1), []).append(span)
            title_lines = [line_groups[key] for key in sorted(line_groups)]
            if len(title_lines) >= 2:
                line_boxes = [
                    union_bbox(
                        [tuple(float(value) for value in span["bbox"]) for span in line]
                    )
                    for line in title_lines
                ]
                final_text = "".join(span.get("text", "") for span in title_lines[-1])
                final_cjk = len(re.findall(r"[\u3400-\u9fff]", final_text))
                final_width = line_boxes[-1][2] - line_boxes[-1][0]
                previous_width = max(box[2] - box[0] for box in line_boxes[:-1])
                if final_cjk <= 1 or final_width < previous_width * 0.22:
                    bbox = line_boxes[-1]
                    issues.append(
                        TranslationIssue(
                            page=page_number,
                            code="font_role_title_orphan",
                            message=(
                                f"Page {page_number}: title ends with an orphan line "
                                f"({final_cjk} CJK glyphs, width ratio "
                                f"{final_width / max(previous_width, 0.1):.2f}) at "
                                f"x={bbox[0]:.1f}, y={bbox[1]:.1f}"
                            ),
                            severity="error",
                        )
                    )
            if block.bold and not any(
                _span_uses_bold_weight(span) for span in role_spans
            ):
                bbox = role_spans[0]["bbox"]
                issues.append(
                    TranslationIssue(
                        page=page_number,
                        code="font_role_heading_mismatch",
                        message=(
                            f"Page {page_number}: title role lost bold weight at "
                            f"x={bbox[0]:.1f}, y={bbox[1]:.1f}"
                        ),
                        severity="error",
                    )
                )
            continue
        if block.block_type in {"heading", "run_in_heading"}:
            if block.bold and not any(
                _span_uses_bold_weight(span) for span in role_spans
            ):
                bbox = role_spans[0]["bbox"]
                issues.append(
                    TranslationIssue(
                        page=page_number,
                        code="font_role_heading_mismatch",
                        message=(
                            f"Page {page_number}: heading role lost bold weight at "
                            f"x={bbox[0]:.1f}, y={bbox[1]:.1f}"
                        ),
                        severity="error",
                    )
                )
            continue
        if block.block_type != "body":
            continue
        has_run_in_predecessor = any(
            -1.0 <= block.bbox[1] - heading.bbox[3] <= 4.0
            and min(block.bbox[2], heading.bbox[2])
            - max(block.bbox[0], heading.bbox[0])
            > 0.0
            for heading in run_in_blocks
        )
        unexpected_bold = [
            span
            for span in role_spans
            if _span_uses_bold_weight(span)
            and not (
                block.bold_prefix and _span_is_short_structural_label(span)
            )
        ]
        if unexpected_bold and not block.bold and has_run_in_predecessor:
            bbox = unexpected_bold[0]["bbox"]
            issues.append(
                TranslationIssue(
                    page=page_number,
                    code="font_role_bold_spill",
                    message=(
                        f"Page {page_number}: run-in heading bold weight spills into body at "
                        f"x={bbox[0]:.1f}, y={bbox[1]:.1f}"
                    ),
                    severity="error",
                )
            )
        size_counts: Dict[float, int] = {}
        for span in role_spans:
            rounded = round(float(span["size"]), 2)
            cjk_weight = max(
                1,
                len(re.findall(r"[\u3400-\u9fff]", span.get("text", ""))),
            )
            size_counts[rounded] = size_counts.get(rounded, 0) + cjk_weight
        dominant_size = max(size_counts, key=lambda size: (size_counts[size], size))
        if source_body_size is not None and abs(block.font_size - source_body_size) <= max(
            1.0,
            source_body_size * 0.18,
        ):
            ordinary_body_sizes.extend(
                float(span["size"])
                for span in role_spans
                if abs(float(span["size"]) - dominant_size) <= 0.5
            )
        if (
            block.source_lines != 1
            or block.formula_anchors
            or block.keepout_bboxes
            or block.source_math_bboxes
        ):
            continue
        for span in role_spans:
            size = float(span["size"])
            if abs(size - dominant_size) <= 0.5:
                continue
            bbox = span["bbox"]
            issues.append(
                TranslationIssue(
                    page=page_number,
                    code="font_role_size_mismatch",
                    message=(
                        f"Page {page_number}: body CJK size {size:.2f}pt differs from role "
                        f"median {dominant_size:.2f}pt at x={bbox[0]:.1f}, y={bbox[1]:.1f}"
                    ),
                    severity="error",
                )
            )
            break

    if ordinary_body_sizes and source_body_size is not None:
        body_size = statistics.median(ordinary_body_sizes)
        for block, role_spans in zip(source_blocks, assignments):
            if block.block_type != "heading" or not role_spans:
                continue
            if block.font_size <= source_body_size + 0.5:
                continue
            heading_size = statistics.median(float(span["size"]) for span in role_spans)
            if heading_size >= body_size + 0.3:
                continue
            bbox = role_spans[0]["bbox"]
            issues.append(
                TranslationIssue(
                    page=page_number,
                    code="font_role_heading_mismatch",
                    message=(
                        f"Page {page_number}: heading hierarchy collapsed to "
                        f"{heading_size:.2f}pt body size at x={bbox[0]:.1f}, "
                        f"y={bbox[1]:.1f}"
                    ),
                    severity="error",
                )
            )
    return issues


def _normalized_formula_ink_mask(
    page: object,
    bbox: BBox,
    *,
    columns: int = 96,
    rows: int = 48,
) -> set[Tuple[int, int]]:
    import fitz

    rect = fitz.Rect(bbox) & page.rect
    if rect.width <= 0.2 or rect.height <= 0.2:
        return set()
    pixmap = page.get_pixmap(
        matrix=fitz.Matrix(5.0, 5.0),
        clip=rect,
        colorspace=fitz.csGRAY,
        alpha=False,
    )
    mask: set[Tuple[int, int]] = set()
    for index, sample in enumerate(pixmap.samples):
        if sample >= 205:
            continue
        row, column = divmod(index, pixmap.width)
        mask.add(
            (
                min(columns - 1, int(column * columns / max(1, pixmap.width))),
                min(rows - 1, int(row * rows / max(1, pixmap.height))),
            )
        )
    return mask


def _formula_ink_similarity(
    source_page: object,
    source_bbox: BBox,
    translated_page: object,
    translated_bbox: BBox,
) -> float:
    source_mask = _normalized_formula_ink_mask(source_page, source_bbox)
    translated_mask = _normalized_formula_ink_mask(
        translated_page,
        translated_bbox,
    )
    if not source_mask or not translated_mask:
        return 0.0

    def dilate(mask: set[Tuple[int, int]]) -> set[Tuple[int, int]]:
        return {
            (x + dx, y + dy)
            for x, y in mask
            for dx in (-1, 0, 1)
            for dy in (-1, 0, 1)
            if 0 <= x + dx < 96 and 0 <= y + dy < 48
        }

    source_dilated = dilate(source_mask)
    translated_dilated = dilate(translated_mask)
    source_coverage = len(source_mask & translated_dilated) / len(source_mask)
    translated_coverage = len(translated_mask & source_dilated) / len(translated_mask)
    return min(source_coverage, translated_coverage)


def _normalized_alpha_mask(
    pixmap: object,
    *,
    columns: int = 96,
    rows: int = 48,
) -> set[Tuple[int, int]]:
    """Normalize only painted alpha, trimming transparent sprite padding."""
    if not getattr(pixmap, "alpha", False):
        return set()
    channel_count = int(pixmap.n)
    width = int(pixmap.width)
    alpha = pixmap.samples[channel_count - 1 :: channel_count]
    painted = [
        (index % width, index // width)
        for index, value in enumerate(alpha)
        if value >= 16
    ]
    if not painted:
        return set()
    min_x = min(x for x, _ in painted)
    max_x = max(x for x, _ in painted) + 1
    min_y = min(y for _, y in painted)
    max_y = max(y for _, y in painted) + 1
    ink_width = max(1, max_x - min_x)
    ink_height = max(1, max_y - min_y)
    return {
        (
            min(columns - 1, int((x - min_x) * columns / ink_width)),
            min(rows - 1, int((y - min_y) * rows / ink_height)),
        )
        for x, y in painted
    }


def _normalized_mask_similarity(
    source_mask: set[Tuple[int, int]],
    translated_mask: set[Tuple[int, int]],
    *,
    columns: int = 96,
    rows: int = 48,
) -> float:
    if not source_mask or not translated_mask:
        return 0.0

    def dilate(mask: set[Tuple[int, int]]) -> set[Tuple[int, int]]:
        return {
            (x + dx, y + dy)
            for x, y in mask
            for dx in (-1, 0, 1)
            for dy in (-1, 0, 1)
            if 0 <= x + dx < columns and 0 <= y + dy < rows
        }

    source_dilated = dilate(source_mask)
    translated_dilated = dilate(translated_mask)
    source_coverage = len(source_mask & translated_dilated) / len(source_mask)
    translated_coverage = len(translated_mask & source_dilated) / len(translated_mask)
    return min(source_coverage, translated_coverage)


def _formula_sprite_alpha_similarity(
    source_document: object,
    page_index: int,
    source_bbox: BBox,
    source_atom_bboxes: Sequence[BBox],
    source_exclusion_bboxes: Sequence[BBox],
    source_size: float,
    translated_document: object,
    image_xref: int,
    *,
    columns: int = 96,
    rows: int = 48,
) -> Optional[float]:
    """Compare the embedded sprite itself, excluding nearby page text."""
    if not source_atom_bboxes or image_xref <= 0:
        return None
    try:
        import fitz

        image_meta = translated_document.extract_image(image_xref)
        soft_mask_xref = int(image_meta.get("smask") or 0)
        if soft_mask_xref <= 0:
            return None
        core = fitz.Rect(source_bbox)
        pad_y = max(0.8, source_size * 0.12)
        source_rect = fitz.Rect(
            core.x0 - 0.25,
            core.y0 - pad_y,
            core.x1 + 0.25,
            core.y1 + pad_y,
        )
        source_pixmap = _formula_atom_masked_pixmap(
            source_document,
            page_index,
            source_rect,
            source_atom_bboxes,
            5.0,
            source_exclusion_bboxes,
        )
        base_pixmap = fitz.Pixmap(translated_document, image_xref)
        mask_pixmap = fitz.Pixmap(translated_document, soft_mask_xref)
        translated_pixmap = fitz.Pixmap(base_pixmap, mask_pixmap)
        return _normalized_mask_similarity(
            _normalized_alpha_mask(
                source_pixmap,
                columns=columns,
                rows=rows,
            ),
            _normalized_alpha_mask(
                translated_pixmap,
                columns=columns,
                rows=rows,
            ),
            columns=columns,
            rows=rows,
        )
    except Exception:
        return None


def _formula_visible_ink_issues(
    source_page: object,
    translated_page: object,
    source_blocks: Sequence[TextBlock],
    page_number: int,
) -> List[TranslationIssue]:
    """Require one visible raster owner for every hidden semantic formula."""
    issues: List[TranslationIssue] = []
    hidden_runs: List[Tuple[str, BBox]] = []
    for trace in translated_page.get_texttrace():
        if int(trace.get("type", 0)) != 3:
            continue
        text = "".join(chr(char[0]) for char in trace.get("chars", []))
        bbox = trace.get("bbox")
        if not text or not bbox:
            continue
        current_bbox = tuple(float(value) for value in bbox)
        if hidden_runs:
            previous_text, previous_bbox = hidden_runs[-1]
            previous_center = (previous_bbox[1] + previous_bbox[3]) / 2.0
            current_center = (current_bbox[1] + current_bbox[3]) / 2.0
            gap = current_bbox[0] - previous_bbox[2]
            if abs(current_center - previous_center) <= 1.5 and -0.5 <= gap <= 2.5:
                hidden_runs[-1] = (
                    previous_text + text,
                    union_bbox([previous_bbox, current_bbox]),
                )
                continue
        hidden_runs.append((text, current_bbox))

    images = [
        image
        for image in translated_page.get_image_info(xrefs=True)
        if image.get("bbox")
    ]
    used_runs: set[int] = set()
    source_document = getattr(source_page, "parent", None)
    translated_document = getattr(translated_page, "parent", None)

    def semantic_signature(text: str) -> str:
        return re.sub(r"\s+", "", _normalize_inline_formula_signature(text))

    def relocated_formula_has_visible_owner(token: "_Token") -> bool:
        if (
            token.source_bbox is None
            or not token.source_atom_bboxes
            or source_document is None
            or translated_document is None
        ):
            return False
        semantic = semantic_signature(token.text)
        matches: List[Tuple[float, int]] = []
        for run_index, (text, semantic_bbox) in enumerate(hidden_runs):
            if run_index in used_runs or semantic_signature(text) != semantic:
                continue
            semantic_center = (
                (semantic_bbox[0] + semantic_bbox[2]) / 2.0,
                (semantic_bbox[1] + semantic_bbox[3]) / 2.0,
            )
            for image in images:
                image_bbox = tuple(float(value) for value in image["bbox"])
                if not bbox_contains_point(
                    expand_bbox(image_bbox, 2.0),
                    semantic_center[0],
                    semantic_center[1],
                ):
                    continue
                similarity = _formula_sprite_alpha_similarity(
                    source_document,
                    token.source_page,
                    token.source_bbox,
                    token.source_atom_bboxes,
                    token.source_exclusion_bboxes,
                    token.source_size,
                    translated_document,
                    int(image.get("xref") or 0),
                    columns=64,
                    rows=32,
                )
                if similarity is not None:
                    matches.append((similarity, run_index))
        if not matches:
            return False
        similarity, run_index = max(matches)
        if similarity < 0.55:
            return False
        used_runs.add(run_index)
        return True

    for block in source_blocks:
        if not _uses_fixed_source_math(block):
            continue
        formula_tokens = [
            token
            for token in _tokenize_translation_with_formula_clips(block.text, block)
            if token.kind == "formula" and token.source_bbox is not None
        ]
        represented_atoms = {
            atom for token in formula_tokens for atom in token.source_atom_bboxes
        }
        formula_groups = [
            (token, tuple(dict.fromkeys(token.source_atom_bboxes)))
            for token in formula_tokens
            if token.source_atom_bboxes
        ]
        formula_groups.extend(
            (None, (atom,))
            for atom in dict.fromkeys(block.source_math_atom_bboxes)
            if atom not in represented_atoms
        )
        for token, atom_bboxes in formula_groups:
            missing_atom: Optional[Tuple[BBox, float]] = None
            for atom_bbox in atom_bboxes:
                atom_width = atom_bbox[2] - atom_bbox[0]
                atom_height = atom_bbox[3] - atom_bbox[1]
                if (
                    atom_width < 1.5
                    or atom_height < 1.5
                    or not _raster_rect_has_ink(source_page, atom_bbox, dpi=240)
                ):
                    continue
                similarity = _formula_ink_similarity(
                    source_page,
                    atom_bbox,
                    translated_page,
                    atom_bbox,
                )
                if similarity < 0.55:
                    missing_atom = (atom_bbox, similarity)
                    break
            if missing_atom is None or (
                token is not None and relocated_formula_has_visible_owner(token)
            ):
                continue
            atom_bbox, similarity = missing_atom
            issues.append(
                TranslationIssue(
                    page=page_number,
                    code="formula_visible_ink_mismatch",
                    message=(
                        f"Page {page_number}: fixed formula atom differs from source "
                        f"near x={atom_bbox[0]:.1f}, y={atom_bbox[1]:.1f} "
                        f"(similarity={similarity:.2f})"
                    ),
                    severity="error",
                )
            )
            break

    expected: List[Tuple[str, BBox, Tuple[BBox, ...], Tuple[BBox, ...], float]] = []
    for block in source_blocks:
        for token in _tokenize_translation_with_formula_clips(block.text, block):
            if (
                token.kind == "formula"
                and token.source_bbox is not None
                and re.search(r"(?:∈R\^\{|∑\^\{)", token.text)
            ):
                expected.append(
                    (
                        re.sub(r"\s+", "", token.text),
                        token.source_bbox,
                        token.source_atom_bboxes,
                        token.source_exclusion_bboxes,
                        token.source_size,
                    )
                )
    if not expected:
        return issues

    for semantic, source_bbox, source_atoms, source_exclusions, source_size in expected:
        semantic = semantic_signature(semantic)
        match_index = next(
            (
                index
                for index, (text, _bbox) in enumerate(hidden_runs)
                if index not in used_runs and semantic_signature(text) == semantic
            ),
            None,
        )
        if match_index is None:
            continue
        used_runs.add(match_index)
        _, semantic_bbox = hidden_runs[match_index]
        semantic_center = (
            (semantic_bbox[0] + semantic_bbox[2]) / 2.0,
            (semantic_bbox[1] + semantic_bbox[3]) / 2.0,
        )
        candidates = [
            image
            for image in images
            for image_bbox in [tuple(float(value) for value in image["bbox"])]
            if bbox_contains_point(
                expand_bbox(image_bbox, 2.0),
                semantic_center[0],
                semantic_center[1],
            )
        ]
        if not candidates:
            issues.append(
                TranslationIssue(
                    page=page_number,
                    code="formula_visible_ink_mismatch",
                    message=(
                        f"Page {page_number}: hidden semantic formula {semantic[:32]!r} "
                        "has no visible formula region"
                    ),
                    severity="error",
                )
            )
            continue
        image = min(
            candidates,
            key=lambda candidate: bbox_area(
                tuple(float(value) for value in candidate["bbox"])
            ),
        )
        image_bbox = tuple(float(value) for value in image["bbox"])
        trimmed_source = source_bbox
        if source_document is not None:
            trimmed_source = _trim_formula_clip_against_foreign_ink(
                source_document,
                page_number - 1,
                source_bbox,
            )
        similarity = _formula_ink_similarity(
            source_page,
            trimmed_source,
            translated_page,
            image_bbox,
        )
        if source_document is not None and translated_document is not None:
            sprite_similarity = _formula_sprite_alpha_similarity(
                source_document,
                page_number - 1,
                source_bbox,
                source_atoms,
                source_exclusions,
                source_size,
                translated_document,
                int(image.get("xref") or 0),
            )
            if sprite_similarity is not None:
                similarity = max(similarity, sprite_similarity)
        source_width = max(0.1, source_bbox[2] - source_bbox[0])
        source_height = max(0.1, source_bbox[3] - source_bbox[1])
        trimmed_width = max(0.0, trimmed_source[2] - trimmed_source[0])
        trimmed_height = max(0.0, trimmed_source[3] - trimmed_source[1])
        if (
            trimmed_width / source_width < 0.5
            or trimmed_height / source_height < 0.5
        ):
            # Foreign-ink trimming is designed for neighboring-line residue,
            # but a cramped inline formula can be mistaken for that residue
            # and reduced to a hairline. The complete source formula remains
            # a valid visual oracle when the trim discarded most of one axis.
            similarity = max(
                similarity,
                _formula_ink_similarity(
                    source_page,
                    source_bbox,
                    translated_page,
                    image_bbox,
                ),
            )
        if similarity < 0.55:
            issues.append(
                TranslationIssue(
                    page=page_number,
                    code="formula_visible_ink_mismatch",
                    message=(
                        f"Page {page_number}: visible formula ink differs from source "
                        f"near x={image_bbox[0]:.1f}, y={image_bbox[1]:.1f} "
                        f"(similarity={similarity:.2f})"
                    ),
                    severity="error",
                )
            )
    return issues


def _output_span_looks_formula(span: dict) -> bool:
    if "char_flags" in span and not int(span.get("char_flags", 0)) & 0x18:
        # Selectable formula accessibility copies use render_mode=3. Their
        # extraction bbox can overlap following text although they have no
        # fill or stroke ink. The lower bits still carry font-style flags.
        return False
    text = " ".join(span.get("text", "").split())
    if not text or re.search(r"[\u3400-\u9fff]", text):
        return False
    if MATH_FONT_RE.search(str(span.get("font", ""))):
        return True
    return bool(
        looks_like_math(text)
        or re.search(r"[=≤≥∑∏⊤⊙]", text)
        and len(text.split()) <= 6
    )


def _raster_rect_has_ink(page: object, bbox: BBox, *, dpi: int = 180) -> bool:
    import fitz

    rect = fitz.Rect(bbox) & page.rect
    if rect.width <= 0.2 or rect.height <= 0.2:
        return False
    pixmap = page.get_pixmap(clip=rect, dpi=dpi, colorspace=fitz.csGRAY, alpha=False)
    samples = pixmap.samples
    if not samples:
        return False
    dark = sum(sample < 220 for sample in samples)
    return dark >= max(2, int(len(samples) * 0.015))


def _bbox_intersection_rect(first: BBox, second: BBox) -> Optional[BBox]:
    intersection = (
        max(first[0], second[0]),
        max(first[1], second[1]),
        min(first[2], second[2]),
        min(first[3], second[3]),
    )
    if intersection[2] <= intersection[0] or intersection[3] <= intersection[1]:
        return None
    return intersection


def _raster_spans_share_ink_component(
    page: object,
    first: BBox,
    second: BBox,
    intersection: BBox,
    *,
    dpi: int = 240,
    allow_bbox_fallback: bool = True,
) -> bool:
    """Prove that two span regions meet in one visible ink component."""
    import fitz

    min_height = min(first[3] - first[1], second[3] - second[1])
    min_width = min(first[2] - first[0], second[2] - second[0])
    pad_x = max(2.0, min(8.0, min_width * 0.45))
    pad_y = max(2.0, min(6.0, min_height * 0.45))
    rect = fitz.Rect(
        intersection[0] - pad_x,
        intersection[1] - pad_y,
        intersection[2] + pad_x,
        intersection[3] + pad_y,
    ) & page.rect
    if rect.width <= 0.2 or rect.height <= 0.2:
        return False
    pixmap = page.get_pixmap(clip=rect, dpi=dpi, colorspace=fitz.csGRAY, alpha=False)
    width = int(pixmap.width)
    height = int(pixmap.height)
    samples = pixmap.samples
    if width <= 0 or height <= 0 or not samples:
        return False

    dark = bytearray(sample < 185 for sample in samples)
    visited = bytearray(width * height)
    scale_x = rect.width / width
    scale_y = rect.height / height
    for start in range(width * height):
        if not dark[start] or visited[start]:
            continue
        stack = [start]
        visited[start] = 1
        first_only = False
        second_only = False
        shared = False
        while stack:
            pixel = stack.pop()
            row, column = divmod(pixel, width)
            x = rect.x0 + (column + 0.5) * scale_x
            y = rect.y0 + (row + 0.5) * scale_y
            in_first = first[0] <= x <= first[2] and first[1] <= y <= first[3]
            in_second = second[0] <= x <= second[2] and second[1] <= y <= second[3]
            first_only = first_only or (in_first and not in_second)
            second_only = second_only or (in_second and not in_first)
            shared = shared or (in_first and in_second)
            for row_offset in (-1, 0, 1):
                next_row = row + row_offset
                if not 0 <= next_row < height:
                    continue
                for column_offset in (-1, 0, 1):
                    if row_offset == 0 and column_offset == 0:
                        continue
                    next_column = column + column_offset
                    if not 0 <= next_column < width:
                        continue
                    neighbor = next_row * width + next_column
                    if dark[neighbor] and not visited[neighbor]:
                        visited[neighbor] = 1
                        stack.append(neighbor)
        if first_only and second_only and shared:
            return True

    smaller = min(bbox_area(first), bbox_area(second))
    overlap_ratio = bbox_area(intersection) / max(smaller, 1.0)
    return bool(
        allow_bbox_fallback
        and overlap_ratio >= 0.55
        and _raster_rect_has_ink(page, intersection, dpi=dpi)
    )


def _formula_image_visible_ink_bbox(
    page: object,
    image: dict,
    smask_by_xref: Dict[int, int],
) -> BBox:
    """Return the page-space alpha envelope of a formula sprite."""
    bbox = tuple(float(value) for value in image["bbox"])
    xref = int(image.get("xref", 0) or 0)
    smask = int(smask_by_xref.get(xref, 0) or 0)
    if smask <= 0:
        return bbox
    try:
        import fitz

        mask = fitz.Pixmap(page.parent, smask)
        samples = mask.samples
        if mask.width <= 0 or mask.height <= 0 or not samples:
            return bbox
        channels = max(1, int(mask.n))
        visible = [
            index // channels
            for index in range(0, len(samples), channels)
            if samples[index] > 8
        ]
        if not visible:
            return bbox
        x0 = min(index % mask.width for index in visible)
        x1 = max(index % mask.width for index in visible) + 1
        y0 = min(index // mask.width for index in visible)
        y1 = max(index // mask.width for index in visible) + 1
        width = bbox[2] - bbox[0]
        height = bbox[3] - bbox[1]
        return (
            bbox[0] + x0 / mask.width * width,
            bbox[1] + y0 / mask.height * height,
            bbox[0] + x1 / mask.width * width,
            bbox[1] + y1 / mask.height * height,
        )
    except Exception:
        return bbox


def _qa_text_spans(page: object) -> List[dict]:
    """Return text spans whose bboxes exclude leading/trailing whitespace."""
    spans: List[dict] = []
    for block in page.get_text("rawdict").get("blocks", []):
        if block.get("type") != 0:
            continue
        for line in block.get("lines", []):
            for raw_span in line.get("spans", []):
                chars = raw_span.get("chars", [])
                text = "".join(char.get("c", "") for char in chars)
                if not text.strip():
                    continue
                ink_chars = [
                    char
                    for char in chars
                    if char.get("c", "").strip()
                    and len(char.get("bbox", ())) == 4
                ]
                span = dict(raw_span)
                span["text"] = text
                if ink_chars:
                    span["bbox"] = union_bbox(
                        [
                            tuple(float(value) for value in char["bbox"])
                            for char in ink_chars
                        ]
                    )
                spans.append(span)
    return spans


def _raster_ink_overlap_issues(
    original_page: object,
    translated_page: object,
    page_number: int,
    *,
    source_blocks: Sequence[TextBlock] = (),
) -> List[TranslationIssue]:
    """Confirm formula/body and heading/body collisions against 180-dpi ink."""
    spans = _qa_text_spans(translated_page)
    cjk_spans = [
        span for span in spans if re.search(r"[\u3400-\u9fff]", span.get("text", ""))
    ]
    formula_spans = [span for span in spans if _output_span_looks_formula(span)]
    hidden_formula_spans = [
        span
        for span in spans
        if not (int(span.get("char_flags", 16)) & 16)
        and not re.search(r"[\u3400-\u9fff]", span.get("text", ""))
    ]
    smask_by_xref = {
        int(image[0]): int(image[1])
        for image in translated_page.parent.get_page_images(
            translated_page.number,
            full=True,
        )
        if len(image) > 1
    }
    image_infos = list(translated_page.get_image_info(xrefs=True))
    original_image_infos = list(original_page.get_image_info(xrefs=True))

    def matches_source_image(image: dict) -> bool:
        image_bbox = tuple(float(value) for value in image["bbox"])
        return any(
            image.get("digest") == source_image.get("digest")
            and all(
                abs(image_bbox[index] - float(source_image["bbox"][index])) <= 0.5
                for index in range(4)
            )
            for source_image in original_image_infos
        )

    source_native_image_indexes = {
        index
        for index, image in enumerate(image_infos)
        if matches_source_image(image)
    }
    formula_image_indexes = [
        index
        for index, image in enumerate(image_infos)
        if any(
            _bbox_intersection_rect(
                tuple(float(value) for value in image["bbox"]),
                tuple(float(value) for value in span["bbox"]),
            )
            is not None
            for span in hidden_formula_spans
        )
    ]
    candidate_image_indexes = set(formula_image_indexes)
    for formula_index in formula_image_indexes:
        formula_raw_bbox = tuple(
            float(value) for value in image_infos[formula_index]["bbox"]
        )
        for other_index, other_image in enumerate(image_infos):
            if other_index == formula_index:
                continue
            other_raw_bbox = tuple(float(value) for value in other_image["bbox"])
            if (
                other_raw_bbox[3] - other_raw_bbox[1] > 80.0
                or other_raw_bbox[2] - other_raw_bbox[0]
                > float(translated_page.rect.width) * 0.5
                or _bbox_intersection_rect(formula_raw_bbox, other_raw_bbox) is None
            ):
                continue
            candidate_image_indexes.add(other_index)
    image_ink_bboxes = {
        index: _formula_image_visible_ink_bbox(
            translated_page,
            image_infos[index],
            smask_by_xref,
        )
        for index in candidate_image_indexes
    }
    formula_images = [image_ink_bboxes[index] for index in formula_image_indexes]
    visible_cjk_spans = [
        span for span in cjk_spans if int(span.get("char_flags", 16)) & 16
    ]
    for image_bbox in formula_images:
        for cjk_span in visible_cjk_spans:
            cjk_bbox = tuple(float(value) for value in cjk_span["bbox"])
            intersection = _bbox_intersection_rect(image_bbox, cjk_bbox)
            if intersection is None or intersection[3] - intersection[1] < 1.0:
                continue
            smaller = min(bbox_area(image_bbox), bbox_area(cjk_bbox))
            if smaller <= 0.0 or bbox_area(intersection) / smaller < 0.08:
                continue
            if not _raster_spans_share_ink_component(
                translated_page,
                image_bbox,
                cjk_bbox,
                intersection,
                dpi=240,
                allow_bbox_fallback=False,
            ):
                continue
            return [
                TranslationIssue(
                    page=page_number,
                    code="raster_ink_overlap",
                    message=(
                        f"Page {page_number}: 240dpi formula-image ink overlap at "
                        f"x={intersection[0]:.1f}, y={intersection[1]:.1f}"
                    ),
                    severity="error",
                )
            ]
    for formula_index in formula_image_indexes:
        formula_bbox = image_ink_bboxes[formula_index]
        for other_index in candidate_image_indexes:
            if other_index == formula_index:
                continue
            if (
                formula_index in source_native_image_indexes
                and other_index in source_native_image_indexes
            ):
                continue
            other_bbox = image_ink_bboxes[other_index]
            other_raw_bbox = tuple(
                float(value) for value in image_infos[other_index]["bbox"]
            )
            if (
                other_raw_bbox[3] - other_raw_bbox[1] > 80.0
                or other_raw_bbox[2] - other_raw_bbox[0]
                > float(translated_page.rect.width) * 0.5
            ):
                continue
            intersection = _bbox_intersection_rect(formula_bbox, other_bbox)
            if intersection is None or intersection[3] - intersection[1] < 1.0:
                continue
            smaller = min(bbox_area(formula_bbox), bbox_area(other_bbox))
            if smaller <= 0.0 or bbox_area(intersection) / smaller < 0.08:
                continue
            if not _raster_spans_share_ink_component(
                translated_page,
                formula_bbox,
                other_bbox,
                intersection,
                dpi=240,
                allow_bbox_fallback=False,
            ):
                continue
            return [
                TranslationIssue(
                    page=page_number,
                    code="raster_ink_overlap",
                    message=(
                        f"Page {page_number}: 240dpi formula sprites overlap at "
                        f"x={intersection[0]:.1f}, y={intersection[1]:.1f}"
                    ),
                    severity="error",
                )
            ]
    for cjk_span in cjk_spans:
        cjk_bbox = tuple(float(value) for value in cjk_span["bbox"])
        for formula_span in formula_spans:
            formula_bbox = tuple(float(value) for value in formula_span["bbox"])
            formula_text = formula_span.get("text", "")
            script_match = re.search(r"(?:\^|_)\{([^{}]+)\}\s*$", formula_text)
            if script_match:
                script_text = re.sub(r"\s+", "", script_match.group(1))
                script_right_edges = [
                    float(candidate["bbox"][2])
                    for candidate in spans
                    if candidate is not formula_span
                    and float(candidate.get("size", 0.0))
                    <= float(formula_span.get("size", 0.0)) * 0.85
                    and re.sub(r"\s+", "", candidate.get("text", "")) == script_text
                    and formula_bbox[0] <= float(candidate["bbox"][0])
                    and float(candidate["bbox"][2]) <= formula_bbox[2]
                    and float(candidate["bbox"][1]) < formula_bbox[3]
                    and float(candidate["bbox"][3]) > formula_bbox[1]
                ]
                if script_right_edges:
                    formula_bbox = (
                        formula_bbox[0],
                        formula_bbox[1],
                        min(
                            formula_bbox[2],
                            max(script_right_edges)
                            + float(formula_span.get("size", 0.0)) * 0.08,
                        ),
                        formula_bbox[3],
                    )
            intersection = _bbox_intersection_rect(cjk_bbox, formula_bbox)
            if intersection is None:
                continue
            if intersection[3] - intersection[1] < 2.0:
                # Sub-2pt intersections are font-bbox antialias fringes. At
                # 240dpi they are not a reliable two-layer ink collision.
                continue
            smaller = min(bbox_area(cjk_bbox), bbox_area(formula_bbox))
            if smaller <= 0.0 or bbox_area(intersection) / smaller < 0.20:
                continue
            if not _raster_spans_share_ink_component(
                translated_page,
                cjk_bbox,
                formula_bbox,
                intersection,
            ):
                continue
            return [
                TranslationIssue(
                    page=page_number,
                    code="raster_ink_overlap",
                    message=(
                        f"Page {page_number}: 180dpi formula-text ink overlap at "
                        f"x={intersection[0]:.1f}, y={intersection[1]:.1f}"
                    ),
                    severity="error",
                )
            ]

    heading_regions: List[BBox] = []
    for block in source_blocks:
        plain = " ".join(strip_sentinels(block.text).split())
        if _ACADEMIC_FORMULA_STATEMENT_RE.match(plain):
            continue
        standalone_heading = block.block_type == "heading" and block.bold
        run_in_heading = block.block_type == "run_in_heading" or block.bold_prefix
        if not standalone_heading and not run_in_heading:
            continue
        first_line = (
            block.source_line_bboxes[0]
            if block.source_line_bboxes
            else (
                block.bbox[0],
                block.bbox[1],
                block.bbox[2],
                min(block.bbox[3], block.bbox[1] + block.font_size * 1.4),
            )
        )
        if standalone_heading:
            heading_regions.append(
                (
                    block.bbox[0] - 2.0,
                    block.bbox[1] - 2.0,
                    block.bbox[2] + max(4.0, block.font_size * 0.5),
                    block.bbox[3] + block.font_size * 1.3,
                )
            )
        else:
            heading_regions.append(expand_bbox(first_line, 2.0))
    bold_cjk_spans = [
        span
        for span in cjk_spans
        if _span_uses_bold_weight(span)
        and any(
            bbox_contains_point(
                region,
                (float(span["bbox"][0]) + float(span["bbox"][2])) / 2.0,
                (float(span["bbox"][1]) + float(span["bbox"][3])) / 2.0,
            )
            for region in heading_regions
        )
    ]
    body_cjk_spans = [span for span in cjk_spans if not _span_uses_bold_weight(span)]
    for heading_span in bold_cjk_spans:
        heading_bbox = tuple(float(value) for value in heading_span["bbox"])
        heading_origin = heading_span.get("origin")
        heading_baseline = (
            float(heading_origin[1]) if heading_origin else heading_bbox[3]
        )
        for body_span in body_cjk_spans:
            body_bbox = tuple(float(value) for value in body_span["bbox"])
            body_origin = body_span.get("origin")
            body_baseline = float(body_origin[1]) if body_origin else body_bbox[3]
            if abs(heading_baseline - body_baseline) < 2.0:
                continue
            intersection = _bbox_intersection_rect(heading_bbox, body_bbox)
            if intersection is None:
                continue
            if (
                intersection[2] - intersection[0] < 4.0
                or intersection[3] - intersection[1] < 1.5
                or not _raster_rect_has_ink(
                    translated_page,
                    intersection,
                    dpi=240,
                )
            ):
                continue
            return [
                TranslationIssue(
                    page=page_number,
                    code="raster_heading_body_overlap",
                    message=(
                        f"Page {page_number}: 240dpi heading-body ink overlap at "
                        f"x={intersection[0]:.1f}, y={intersection[1]:.1f}"
                    ),
                    severity="error",
                )
            ]
    return []


def _raster_ink_bottom(
    page: object,
    bbox: BBox,
    *,
    dpi: int = 180,
) -> Optional[float]:
    import fitz

    rect = fitz.Rect(bbox) & page.rect
    if rect.width <= 0.2 or rect.height <= 0.2:
        return None
    pixmap = page.get_pixmap(clip=rect, dpi=dpi, colorspace=fitz.csGRAY, alpha=False)
    width = int(pixmap.width)
    height = int(pixmap.height)
    samples = pixmap.samples
    if width <= 0 or height <= 0 or not samples:
        return None
    last_row = -1
    for row in range(height):
        row_samples = samples[row * width : (row + 1) * width]
        if sum(sample < 220 for sample in row_samples) >= 2:
            last_row = row
    if last_row < 0:
        return None
    return float(rect.y0 + (last_row + 1) * 72.0 / dpi)


def _table_caption_clearance_issues(
    original_page: object,
    translated_page: object,
    page_number: int,
) -> List[TranslationIssue]:
    """Measure translated table-caption glyph/ink clearance from the first rule."""
    source_captions = [
        (key, bbox)
        for key, bbox in _source_caption_regions(original_page)
        if key[0] == "table"
    ]
    if not source_captions:
        return []
    source_rules = [
        (
            float(drawing["rect"].y0),
            float(drawing["rect"].x0),
            float(drawing["rect"].x1),
        )
        for drawing in _page_drawings(original_page)
        if drawing.get("rect") is not None
        and float(drawing["rect"].width) >= 80.0
        and float(drawing["rect"].height) <= 0.25
    ]
    translated_blocks = translated_page.get_text("dict").get("blocks", [])
    issues: List[TranslationIssue] = []
    for key, source_bbox in source_captions:
        rule_candidates = [
            rule_y
            for rule_y, rule_x0, rule_x1 in source_rules
            if source_bbox[1] < rule_y <= source_bbox[3] + 14.0
            and min(source_bbox[2], rule_x1) - max(source_bbox[0], rule_x0)
            >= min(source_bbox[2] - source_bbox[0], rule_x1 - rule_x0) * 0.45
        ]
        if not rule_candidates:
            continue
        rule_y = min(rule_candidates)
        matching_caption_bboxes: List[BBox] = []
        for block in translated_blocks:
            if block.get("type") != 0:
                continue
            lines = block.get("lines", [])
            for line_index, line in enumerate(lines):
                line_text = "".join(
                    span.get("text", "") for span in line.get("spans", [])
                ).strip()
                if _caption_key(line_text) != key:
                    continue
                line_bbox_value = line.get("bbox")
                if not line_bbox_value:
                    span_bboxes = [
                        tuple(float(value) for value in span["bbox"])
                        for span in line.get("spans", [])
                        if span.get("bbox")
                    ]
                    line_bbox_value = union_bbox(span_bboxes) if span_bboxes else None
                if not line_bbox_value:
                    continue
                caption_line_bbox = tuple(
                    float(value) for value in line_bbox_value
                )
                if caption_line_bbox[1] >= rule_y:
                    continue
                caption_lines = [caption_line_bbox]
                previous_bbox = caption_lines[0]
                for continuation in lines[line_index + 1 :]:
                    continuation_bbox_value = continuation.get("bbox")
                    if not continuation_bbox_value:
                        continuation_span_bboxes = [
                            tuple(float(value) for value in span["bbox"])
                            for span in continuation.get("spans", [])
                            if span.get("bbox")
                        ]
                        continuation_bbox_value = (
                            union_bbox(continuation_span_bboxes)
                            if continuation_span_bboxes
                            else None
                        )
                    if not continuation_bbox_value:
                        break
                    continuation_bbox = tuple(
                        float(value) for value in continuation_bbox_value
                    )
                    if continuation_bbox[1] >= rule_y:
                        break
                    vertical_gap = continuation_bbox[1] - previous_bbox[3]
                    max_gap = max(
                        4.0,
                        (previous_bbox[3] - previous_bbox[1]) * 0.8,
                    )
                    if vertical_gap < -2.0 or vertical_gap > max_gap:
                        break
                    horizontal_overlap = max(
                        0.0,
                        min(source_bbox[2], continuation_bbox[2])
                        - max(source_bbox[0], continuation_bbox[0]),
                    )
                    overlap_basis = min(
                        source_bbox[2] - source_bbox[0],
                        continuation_bbox[2] - continuation_bbox[0],
                    )
                    if overlap_basis <= 0.0 or horizontal_overlap < overlap_basis * 0.25:
                        break
                    continuation_text = "".join(
                        span.get("text", "")
                        for span in continuation.get("spans", [])
                    ).strip()
                    continuation_key = _caption_key(continuation_text)
                    if continuation_key not in {("", ""), key}:
                        break
                    caption_lines.append(continuation_bbox)
                    previous_bbox = continuation_bbox
                matching_caption_bboxes.append(union_bbox(caption_lines))
        if not matching_caption_bboxes:
            continue
        translated_bbox = union_bbox(matching_caption_bboxes)
        raster_bottom = _raster_ink_bottom(
            translated_page,
            (
                translated_bbox[0],
                max(0.0, translated_bbox[1] - 1.0),
                translated_bbox[2],
                min(rule_y - 0.5, translated_bbox[3] + 1.0),
            ),
        )
        glyph_bottom = translated_bbox[3]
        if raster_bottom is not None:
            glyph_bottom = max(glyph_bottom, raster_bottom)
        gap = rule_y - glyph_bottom
        if gap >= 3.0:
            continue
        issues.append(
            TranslationIssue(
                page=page_number,
                code="raster_caption_clearance",
                message=(
                    f"Page {page_number}: Table {key[1]} caption ink is only "
                    f"{gap:.2f}pt above the first rule at x={translated_bbox[0]:.1f}, "
                    f"y={glyph_bottom:.1f}"
                ),
                severity="error",
            )
        )
    return issues


def _block_translates_to_words(block: TextBlock) -> bool:
    """Whether the unit loop would actually send this block for translation.

    Mirrors the word check applied when building translation units: after
    protecting math sentinels, at least one plain word must remain.
    """
    try:
        protected, _ = protect_text(block.text)
    except Exception:
        return True
    bare = PLACEHOLDER_RE.sub("", protected)
    return bool(re.search(r"[A-Za-z]{2,}", bare))


def _blocks_ink_overlap_ratio(first: TextBlock, second: TextBlock) -> float:
    """Overlap between two blocks measured on replaceable ink, not hulls.

    Math-heavy paragraphs get hull bboxes inflated across display equations,
    so consecutive full-column blocks interlock vertically while their
    actual prose never touches. Redaction boxes are the closest description
    of the English ink that translation will replace; fall back to line boxes
    and finally hulls when that extraction detail is unavailable.
    """
    first_lines = tuple(first.redact_bboxes or first.source_line_bboxes or (first.bbox,))
    second_lines = tuple(
        second.redact_bboxes or second.source_line_bboxes or (second.bbox,)
    )
    intersection = sum(
        bbox_intersection_area(a, b) for a in first_lines for b in second_lines
    )
    smaller = min(
        sum(bbox_area(a) for a in first_lines),
        sum(bbox_area(b) for b in second_lines),
    )
    if smaller <= 0.0:
        return 0.0
    return intersection / smaller


def _overlapping_translation_block_bboxes(
    blocks: Sequence[TextBlock],
    *,
    min_overlap_ratio: float = 0.5,
) -> List[BBox]:
    """Bboxes of translation candidates that substantially overlap each other.

    Interleaved borderless-table extractions can yield one block nested inside
    another. Translating both overprints Chinese text at the same coordinates,
    so such blocks must keep their original typesetting instead. Only blocks
    that will really be translated (words survive math protection) count, and
    overlap is measured on line ink rather than hull bboxes. Line-level
    interlock between consecutive math-inflated paragraphs peaks around 0.3,
    while genuine nesting/overprint approaches 1.0, hence the 0.5 bar.
    """
    candidates = [block for block in blocks if _block_translates_to_words(block)]
    flagged: List[BBox] = []
    for index, first in enumerate(candidates):
        for second in candidates[index + 1 :]:
            if bbox_intersection_area(first.bbox, second.bbox) <= 0.0:
                continue
            if _blocks_ink_overlap_ratio(first, second) < min_overlap_ratio:
                continue
            flagged.append(first.bbox)
            flagged.append(second.bbox)
    return list(dict.fromkeys(flagged))



def _candidate_bboxes_colliding_with_preserved(
    candidates: Sequence[TextBlock],
    preserved_regions: Sequence[BBox],
    *,
    min_area_ratio: float = 0.25,
    min_penetration: float = 2.0,
) -> List[BBox]:
    """Translation candidates whose redaction would erase preserved ink.

    Figure labels and formula regions are preserved in place; a candidate
    whose bbox meaningfully covers one (e.g. a mis-segmented caption cell
    overhanging a label) would first redact that ink away and then overprint
    it. Such candidates keep their original typesetting instead.

    Probe granularity depends on the block. A clean prose paragraph wrapping
    a float table has a hull covering the cells but lines that never touch
    them, so line-level probing lets it translate. A formula-dense block, or
    one whose lines were carved around preserved inline math (ragged left
    edges), is reflowed from its hull origin and will overprint the region,
    so it must keep the conservative hull test.
    """
    flagged: List[BBox] = []
    for block in candidates:
        text = block.text or ""
        formula_dense = (
            len(text) > 0 and sentinel_char_count(text) / len(text) >= 0.15
        )
        lines = list(block.source_line_bboxes)
        ragged = bool(lines) and (
            sum(1 for line in lines if line[0] > block.bbox[0] + 20.0) / len(lines)
            >= 0.5
        )
        precise_redacts = list(block.redact_bboxes or [])
        if (formula_dense or ragged) and len(precise_redacts) >= 2:
            # Formula-aware extraction already separated replaceable prose
            # from protected glyphs. Its redaction boxes are a stronger
            # collision oracle than the formula-inflated paragraph hull.
            probe_bboxes = precise_redacts
            hull_probe = False
        elif formula_dense or ragged:
            probe_bboxes = [block.bbox]
            hull_probe = True
        else:
            probe_bboxes = lines or [block.bbox]
            hull_probe = not lines
        hit = False
        for bx0, by0, bx1, by1 in probe_bboxes:
            for region in preserved_regions:
                rx0, ry0, rx1, ry1 = region
                x_overlap = min(bx1, rx1) - max(bx0, rx0)
                y_overlap = min(by1, ry1) - max(by0, ry0)
                if x_overlap < min_penetration or y_overlap < min_penetration:
                    continue
                probe_area = max(0.1, (bx1 - bx0) * (by1 - by0))
                region_area = max(0.1, (rx1 - rx0) * (ry1 - ry0))
                # Hull probes stay conservative (smaller area as denominator):
                # reflow re-wraps from the hull origin. Line probes measure
                # coverage of the LINE itself — a clean prose line brushing a
                # tall formula bbox's empty tail is not a collision
                # (PhiZero p4).
                denominator = min(probe_area, region_area) if hull_probe else probe_area
                if (x_overlap * y_overlap) / denominator >= min_area_ratio:
                    hit = True
                    break
            if hit:
                break
        if hit:
            flagged.append(block.bbox)
    return flagged


def _side_adjacent_preserved_regions(
    block: TextBlock,
    preserved_regions: Sequence[BBox],
    *,
    max_gap: float = 4.0,
) -> List[BBox]:
    """Preserved ink immediately beside a translated run-in label.

    Redaction margins around labels such as ``Action Skeleton:`` must not
    erase the first glyph of adjacent pseudocode on the same baseline.
    """
    bx0, by0, bx1, by1 = block.bbox
    block_height = max(by1 - by0, 1.0)
    adjacent: List[BBox] = []
    for region in preserved_regions:
        rx0, ry0, rx1, ry1 = region
        region_height = max(ry1 - ry0, 1.0)
        vertical_overlap = min(by1, ry1) - max(by0, ry0)
        if vertical_overlap / min(block_height, region_height) < 0.5:
            continue
        is_right_neighbor = rx0 >= bx1 - 1.0 and rx0 - bx1 <= max_gap
        is_left_neighbor = rx1 <= bx0 + 1.0 and bx0 - rx1 <= max_gap
        if is_right_neighbor or is_left_neighbor:
            adjacent.append(region)
    return adjacent


def _preserved_keepout_regions(
    block: TextBlock,
    preserved_regions: Sequence[BBox],
) -> List[BBox]:
    """Protected regions that reflowed text must route around.

    Besides same-baseline neighbours, include a preserved formula/table that
    materially crosses a prose box.  A sub-2pt PDF hull graze is ignored; it
    does not represent visible ink ownership and would needlessly constrain
    the preceding line.
    """
    bx0, by0, bx1, by1 = block.bbox
    block_height = max(1.0, by1 - by0)
    keepouts = list(_side_adjacent_preserved_regions(block, preserved_regions))
    for region in preserved_regions:
        rx0, ry0, rx1, ry1 = region
        horizontal_overlap = min(bx1, rx1) - max(bx0, rx0)
        vertical_overlap = min(by1, ry1) - max(by0, ry0)
        if horizontal_overlap <= 0.5:
            continue
        region_height = max(1.0, ry1 - ry0)
        if vertical_overlap < max(2.0, min(block_height, region_height) * 0.20):
            continue
        keepouts.append(region)
    return list(dict.fromkeys(keepouts))


_PARALLEL_PANEL_MARKER_RE = re.compile(r"^\s*\([a-z]\)\s+", re.IGNORECASE)


def _has_parallel_panel_sibling(
    block: TextBlock,
    candidates: Sequence[TextBlock],
) -> bool:
    """Distinguish horizontal subfigure captions from vertical list items."""
    plain = " ".join(strip_sentinels(block.text).split()).strip()
    if not _PARALLEL_PANEL_MARKER_RE.match(plain):
        return False

    bx0, by0, bx1, by1 = block.bbox
    block_width = max(1.0, bx1 - bx0)
    block_height = max(1.0, by1 - by0)
    for other in candidates:
        if other is block or other.page_index != block.page_index:
            continue
        other_plain = " ".join(strip_sentinels(other.text).split()).strip()
        if not _PARALLEL_PANEL_MARKER_RE.match(other_plain):
            continue
        ox0, oy0, ox1, oy1 = other.bbox
        other_width = max(1.0, ox1 - ox0)
        other_height = max(1.0, oy1 - oy0)
        vertical_overlap = min(by1, oy1) - max(by0, oy0)
        if vertical_overlap < 0.55 * min(block_height, other_height):
            continue
        horizontal_gap = max(ox0 - bx1, bx0 - ox1, 0.0)
        if horizontal_gap <= max(18.0, 0.2 * min(block_width, other_width)):
            return True
    return False


def _block_mostly_inside_preserved_regions(
    block: TextBlock,
    regions: Sequence[BBox],
    *,
    min_ratio: float = 0.7,
) -> bool:
    """Whether a translation block sits mostly inside QA-preserved regions.

    Table cells that escape structural classification would otherwise be
    translated and then rejected by preserved-region QA, so the translate
    path must honor the same envelopes verification uses.
    """
    if not regions:
        return False
    area = bbox_area(block.bbox)
    if area <= 0:
        return False
    return any(
        bbox_intersection_area(block.bbox, region) / area >= min_ratio
        for region in regions
    )


def preserved_original_text_regions(document: object) -> Dict[int, List[BBox]]:
    """Regions whose English text is intentionally preserved in graphics/table mode."""
    regions: Dict[int, List[BBox]] = {}
    prepare_translation_units(
        document,
        preserve_graphics_text=True,
        preserved_regions_out=regions,
    )
    return regions


def translation_unit_source_texts(pdf_path: Path) -> List[str]:
    """Plain source texts of the blocks that actually get translated.

    Excludes references, tables, algorithms, and other preserved regions so
    downstream checks (e.g. terminology adherence) don't flag text that was
    intentionally kept in English.
    """
    import fitz

    document = fitz.open(str(pdf_path))
    try:
        units, _, _ = prepare_translation_units(document, preserve_graphics_text=True)
        return [
            " ".join(strip_sentinels(block.text).split())
            for block, _, _ in units
        ]
    finally:
        document.close()


def _restore_unit_translation(
    translated_text: str,
    mapping: Dict[int, str],
    block: Optional[TextBlock] = None,
) -> Tuple[str, List[int]]:
    restored, missing = restore_text(
        translated_text,
        mapping,
        preserve_indices=block.preserved_math_placeholders if block is not None else (),
    )
    cleaned = clean_translation(restored)
    if block is not None and block.preserved_math_placeholders:
        # Separate source formula runs stay separate after translators or the
        # spacing normalizer collapse their two-space boundary. Otherwise the
        # sentinel matcher merges the runs, formula anchors no longer align,
        # and rendering falls back to duplicate hidden/visible formula text.
        cleaned = re.sub(
            rf"{re.escape(SENTINEL_CLOSE)}\s?{re.escape(SENTINEL_OPEN)}",
            SENTINEL_CLOSE + "  " + SENTINEL_OPEN,
            cleaned,
        )
    return cleaned, missing


def _translation_echoes_source(block: TextBlock, translated_text: str) -> bool:
    """The result is word-for-word the source: the supplier echoed it or the
    placeholder fallback kept it. The legitimately-English exemptions do not
    apply here — a prose block that should have been translated is never
    correctly left identical to its source, whatever it looks like."""
    if _CJK_DETECT_RE.search(translated_text):
        return False
    source = " ".join(strip_sentinels(block.text).split())
    source_words = [
        word.lower()
        for word in _PROSE_WORD_RE.findall(source)
        if word.lower() not in _MATH_WORDS
    ]
    short_structure_heading = looks_like_academic_structure_heading(block, source)
    if len(source_words) < 5 and not short_structure_heading:
        return False
    result_words = [
        word.lower()
        for word in _PROSE_WORD_RE.findall(translated_text)
        if word.lower() not in _MATH_WORDS
    ]
    if not result_words:
        return False
    import difflib

    return (
        difflib.SequenceMatcher(
            None, " ".join(source_words), " ".join(result_words)
        ).ratio()
        >= 0.75
    )


def _translation_retains_source_prose_run(
    block: TextBlock,
    translated_text: str,
    min_run: int = 5,
) -> bool:
    """Whether a result kept a long contiguous prose phrase from its source.

    Region-level QA needs this because formula-heavy paragraphs can be split
    into several short output blocks, each below the generic English ratio
    threshold. Technical names shorter than five words remain allowed.
    """
    if not block.should_translate:
        return False
    if block.block_type in (
        "algorithm",
        "bibliography",
        "equation",
        "figure_label",
        "footer",
    ):
        return False
    source_plain = strip_sentinels(block.text).strip()
    if _looks_like_author_or_affiliation_text(source_plain):
        return False
    if URL_RE.search(source_plain) or URL_RE.search(translated_text):
        return False
    if not re.search(r"\s", source_plain) and (
        "@" in source_plain or source_plain.count("/") >= 2
    ):
        return False
    result_plain = " ".join(strip_sentinels(translated_text).split())
    # A CJK-labelled sample field ("较差的英语输入：Please ...") quotes model
    # input/output that stays in English by design.
    if _looks_like_cjk_sample_label(result_plain):
        return False

    def prose_word_segments(text: str, *, source: bool = False) -> List[List[str]]:
        # Source sentinels mark formulas and protected PDF atoms. Their literal
        # accessibility text is expected to reappear unchanged and must never
        # count as an untranslated prose n-gram. Result text has no sentinels,
        # so keep scanning it in full for genuine source prose residue.
        plain = (
            SENTINEL_RUN_RE.sub("\n", text)
            if source
            else strip_sentinels(text)
        )
        plain = re.sub(
            r"\b[A-Za-z][A-Za-z0-9]*(?:[-\u00ad\u2010-\u2015][A-Za-z0-9]+)+\b",
            "\n",
            plain,
        )
        plain = re.sub(
            r"\b(?:BLEU|chrF|TER)(?:\+[A-Za-z0-9_.-]+){3,}\b",
            "\n",
            plain,
            flags=re.IGNORECASE,
        )
        plain = _without_structured_prompt_lists(plain)
        plain = re.sub(
            r"\b(?:pick|place|pull|push|on|inhand|under)\s*\([^()]{1,180}\)",
            "\n",
            plain,
            flags=re.IGNORECASE,
        )
        if _CJK_DETECT_RE.search(plain):
            # Academic Chinese commonly keeps the English term in parentheses
            # on first mention. It is an intentional glossary, not an
            # untranslated prose run, provided the surrounding result is CJK.
            parenthetical_re = re.compile(
                r"(?:\([^()\n]{1,180}\)|\uff08[^\uff08\uff09\n]{1,180}\uff09)"
            )
            plain = parenthetical_re.sub(
                lambda match: "\n"
                if re.search(r"[A-Za-z]", match.group(0))
                else match.group(0),
                plain,
            )
        for boundary_re in (
            EMAIL_RE,
            AUTHOR_YEAR_CITATION_RE,
            BRACKETED_AUTHOR_YEAR_CITATION_RE,
            CITATION_RE,
        ):
            plain = boundary_re.sub("\n", plain)
        plain = re.sub(
            r"(?:\(|（)[^()（）\n]{0,1200}"
            r"(?:\bet\s+al\.?|\b(?:19|20)\d{2})[^()（）\n]*$",
            "\n",
            plain,
            flags=re.IGNORECASE,
        )
        return [
            [
                word
                for word in re.findall(r"[A-Za-z]{2,}", segment)
                if word.lower() not in _MATH_WORDS
            ]
            for segment in plain.splitlines()
            if segment.strip()
        ]

    source_segments = prose_word_segments(block.text, source=True)
    result_segments = prose_word_segments(translated_text)
    if (
        sum(len(segment) for segment in source_segments) < min_run
        or sum(len(segment) for segment in result_segments) < min_run
    ):
        return False
    result_runs = {
        tuple(word.lower() for word in segment[index : index + min_run])
        for segment in result_segments
        for index in range(len(segment) - min_run + 1)
    }
    for segment in source_segments:
        for index in range(len(segment) - min_run + 1):
            source_run = segment[index : index + min_run]
            if sum(word[:1].islower() for word in source_run) < 3:
                continue
            if tuple(word.lower() for word in source_run) in result_runs:
                return True
    return False


def _translated_block_still_english(block: TextBlock, translated_text: str) -> bool:
    if not block.should_translate:
        return False
    if block.block_type in ("algorithm", "bibliography", "equation", "figure_label", "footer"):
        return False
    # URL-dominant blocks (footnote link lists) legitimately echo their
    # source: after stripping URLs there is nothing left to translate, and
    # retrying such blocks loops forever between echo and paraphrase.
    plain_source = strip_sentinels(block.text)
    url_stripped = re.sub(r"(?:https?://|www\.)\S+", " ", plain_source)
    if url_stripped != plain_source:
        source_without_urls = " ".join(url_stripped.split())
        remaining_words = len(_prose_words(source_without_urls))
        if remaining_words < 4:
            return False
        # Link footnotes ("1The test set is available at <url>"): the
        # payload is the link itself; vendors echo the scaffolding half
        # the time, and the retry churns forever without improving
        # anything.
        if remaining_words < 10 and re.match(r"^\d{1,2}[A-Z]", source_without_urls):
            return False
    return (
        _translation_echoes_source(block, translated_text)
        or _translation_retains_source_prose_run(block, translated_text)
        or _translation_retains_foreign_prose(block, translated_text)
        or bool(_retained_bracketed_natural_language(translated_text))
        or _looks_like_untranslated_english(translated_text)
        or _contains_untranslated_english_run(translated_text)
        or _looks_like_untranslated_formula_explanation(translated_text)
        or _translation_contains_commentary(translated_text)
    )


_FRENCH_FUNCTION_WORDS = frozenset(
    (
        "au aux avec ce ces dans de des du elle en est et il la le les leur lui "
        "mais ne nous ou par pour que qui sa se ses son sur un une vous"
    ).split()
)
_FOREIGN_RESIDUE_WORDS = frozenset(
    (
        "an and are as at be been being by for from had has have he her hers "
        "him his in is it its of on or our she that the their them they this "
        "to was we were with you your added said such"
    ).split()
) | _FRENCH_FUNCTION_WORDS
_SINGLE_TOKEN_FOREIGN_RESIDUES = frozenset(
    "he her hers him his its she their them they we you your added said such".split()
)


def _latin_prose_words(text: str) -> List[str]:
    normalized = unicodedata.normalize("NFKD", text)
    normalized = "".join(
        char for char in normalized if not unicodedata.combining(char)
    )
    return re.findall(r"[A-Za-z]+", normalized)


def _residue_comparison_text(text: str) -> str:
    plain = _text_outside_sentinels(text)
    if _CJK_DETECT_RE.search(plain):
        plain = re.sub(r"\([^()\n]{1,180}\)|（[^（）\n]{1,180}）", " ", plain)
        plain = re.sub(
            r"“[^“”\n]{1,500}”|‘[^‘’\n]{1,500}’|\"[^\"\n]{1,500}\"",
            " ",
            plain,
        )
    for boundary_re in (
        EMAIL_RE,
        URL_RE,
        AUTHOR_YEAR_CITATION_RE,
        BRACKETED_AUTHOR_YEAR_CITATION_RE,
        CITATION_RE,
    ):
        plain = boundary_re.sub(" ", plain)
    plain = re.sub(r"\bet\s+al\.?", " ", plain, flags=re.IGNORECASE)
    return plain


def _translation_retains_foreign_prose(
    block: TextBlock,
    translated_text: str,
) -> bool:
    """Detect short source-language function words left in a Chinese result.

    The generic English detector intentionally ignores short Latin fragments
    to avoid flagging acronyms and names. Source comparison makes this narrow
    check safe enough to catch split PDF spans such as ``he`` or French
    ``un ... son ... de`` without treating GPU, RNNsearch, or a first-use
    parenthetical gloss as untranslated prose.
    """
    if not block.should_translate or block.block_type in (
        "algorithm",
        "bibliography",
        "equation",
        "figure_label",
        "footer",
    ):
        return False
    if not _CJK_DETECT_RE.search(translated_text):
        return False
    result_plain = " ".join(translated_text.split())
    if _looks_like_cjk_sample_label(result_plain):
        return False
    if (
        ("→" in result_plain or "->" in result_plain)
        and re.search(r"(?:格式|示例|样例)[：:]", result_plain)
        and len(_CJK_DETECT_RE.findall(result_plain)) >= 20
    ):
        return False

    source_words = {
        word.casefold()
        for word in _latin_prose_words(_residue_comparison_text(block.text))
    }
    protected_word_budget = Counter(
        word.casefold()
        for formula_text in SENTINEL_RUN_RE.findall(block.text)
        for word in _latin_prose_words(formula_text)
        if word.casefold() in _FOREIGN_RESIDUE_WORDS
    )
    result_text = _residue_comparison_text(translated_text)
    quoted_single_words = {
        words[0].casefold()
        for quoted in re.findall(
            r"[‘’“”\"']([^‘’“”\"'\n]{1,40})[‘’“”\"']",
            translated_text,
        )
        if len(words := _latin_prose_words(quoted)) == 1
    }
    result_words = _latin_prose_words(result_text)
    residues: List[str] = []
    for word in result_words:
        lowered = word.casefold()
        if (
            not word.islower()
            or lowered not in source_words
            or lowered not in _FOREIGN_RESIDUE_WORDS
            or lowered in quoted_single_words
        ):
            continue
        if protected_word_budget[lowered] > 0:
            protected_word_budget[lowered] -= 1
            continue
        residues.append(lowered)
    if any(word in _SINGLE_TOKEN_FOREIGN_RESIDUES for word in residues):
        return True
    if residues and len(set(residues)) == 1:
        return False
    return len(residues) >= 2


def _source_looks_like_foreign_example(text: str) -> bool:
    words = [word.casefold() for word in _latin_prose_words(_text_outside_sentinels(text))]
    return sum(word in _FRENCH_FUNCTION_WORDS for word in words) >= 3


_RETAINED_LATIN_PHRASE_RE = re.compile(
    r"[A-Za-z][A-Za-z0-9]*(?:"
    r"[ \t\r,.;:!?\"'’‘“”(){}\[\]/+\-]+[A-Za-z][A-Za-z0-9]*"
    r"){4,}"
)


def _retained_source_prose_phrases(
    block: TextBlock,
    translated_text: str,
    *,
    min_words: int = 5,
) -> List[str]:
    """Exact source prose spans still embedded in an otherwise CJK result."""
    if not block.should_translate or block.block_type in (
        "algorithm",
        "bibliography",
        "equation",
        "figure_label",
        "footer",
    ):
        return []
    source_plain = SENTINEL_RUN_RE.sub(" ", block.text)
    source_words = [
        word.casefold()
        for word in re.findall(r"[A-Za-z]{2,}", source_plain)
        if word.casefold() not in _MATH_WORDS
    ]
    source_normalized = " ".join(source_words)
    if len(source_words) < min_words:
        return []

    phrases: List[str] = []
    outside_formula_text = SENTINEL_RUN_RE.sub("\n", translated_text)
    for match in _RETAINED_LATIN_PHRASE_RE.finditer(outside_formula_text):
        phrase = match.group(0).strip()
        words = [
            word
            for word in re.findall(r"[A-Za-z]{2,}", phrase)
            if word.casefold() not in _MATH_WORDS
        ]
        if len(words) < min_words or sum(word[:1].islower() for word in words) < 3:
            continue
        normalized = " ".join(word.casefold() for word in words)
        if normalized not in source_normalized:
            continue
        left = outside_formula_text[: match.start()].rstrip()[-1:]
        right = outside_formula_text[match.end() :].lstrip()[:1]
        if left in {"(", "（"} and right in {")", "）"}:
            continue
        if URL_RE.search(phrase) or EMAIL_RE.search(phrase):
            continue
        phrases.append(phrase)
    return list(dict.fromkeys(phrases))


_VERBATIM_GENERATED_SAMPLE_RE = re.compile(
    r"(?:\bGenerated\s+(?:Completion|Output|Poem|Sample|Story)\s+\d+\b|"
    r"\b[A-Za-z][A-Za-z0-9.-]{1,30}\s+\d+(?:\.\d+)?[BMKT]?\s+"
    r"completion\s*:)",
    re.IGNORECASE,
)


def _source_unit_is_verbatim_generated_sample(
    block: TextBlock,
    page_units: Sequence[TextBlock],
) -> bool:
    """Whether a source unit belongs to a labeled generated-text sample."""
    source = " ".join(strip_sentinels(block.text).split())
    if _VERBATIM_GENERATED_SAMPLE_RE.search(source):
        return True
    bx0, by0, bx1, _by1 = block.bbox
    for candidate in page_units:
        if candidate.page_index != block.page_index:
            continue
        label = " ".join(strip_sentinels(candidate.text).split())
        if not _VERBATIM_GENERATED_SAMPLE_RE.search(label):
            continue
        cx0, _cy0, cx1, cy1 = candidate.bbox
        if min(bx1, cx1) - max(bx0, cx0) <= 0.0:
            continue
        # Generated sample grids commonly have one label row followed by a
        # long poem/story column that occupies most of the remaining page.
        if -4.0 <= by0 - cy1 <= 520.0:
            return True
    return False


def _retained_bracketed_natural_language(text: str) -> List[str]:
    """Natural-language square-bracket spans eligible for focused retry."""
    phrases: List[str] = []
    for match in re.finditer(r"\[([^\[\]]{2,180})\]", text):
        phrase = " ".join(match.group(1).split()).strip()
        if not phrase or _CJK_DETECT_RE.search(phrase):
            continue
        if re.fullmatch(r"\d+(?:\s*[,\u2013-]\s*\d+)*", phrase):
            continue
        if re.fullmatch(r"[A-Za-z](?:\s*,\s*[A-Za-z])+", phrase):
            continue
        words = _latin_prose_words(phrase)
        single_natural_word = bool(
            len(words) == 1
            and not phrase.isupper()
            and (
                len(words[0]) >= 3
                or words[0].casefold() in _FOREIGN_RESIDUE_WORDS
                or bool(re.fullmatch(r"[A-Za-z]['’]", phrase))
            )
        )
        if len(words) < 2 and not single_natural_word:
            continue
        if looks_like_math(phrase) or URL_RE.search(phrase):
            continue
        phrases.append(phrase)
    return phrases


def _focused_foreign_phrase_translation(
    phrase: str,
    translated_phrase: str,
) -> str:
    """Validate a focused retry and gloss isolated linguistic morphemes."""
    candidate = translated_phrase.strip()
    if (
        candidate
        and _CJK_DETECT_RE.search(candidate)
        and candidate.casefold() != phrase.casefold()
    ):
        return candidate
    normalized = phrase.strip().replace("’", "'").casefold()
    if normalized == "l'":
        return "省音定冠词（l'）"
    if normalized in {"le", "la", "les"}:
        return f"定冠词（{normalized}）"
    if normalized == "the":
        return "定冠词（the）"
    if normalized == "man":
        return "男人（man）"
    if normalized == "homme":
        return "男人（homme）"
    return ""


def _visible_image_stats(
    page: object,
    *,
    blocks: Optional[Sequence[dict]] = None,
) -> Tuple[int, float]:
    """Count visible raster image blocks and their displayed page area."""
    try:
        page_blocks = (
            blocks if blocks is not None else page.get_text("dict").get("blocks", [])
        )
        image_blocks = [
            block
            for block in page_blocks
            if block.get("type") == 1 and block.get("bbox")
        ]
    except Exception:
        image_blocks = []
    if image_blocks:
        area = 0.0
        for block in image_blocks:
            x0, y0, x1, y1 = (float(value) for value in block["bbox"])
            area += max(0.0, x1 - x0) * max(0.0, y1 - y0)
        # Nested clipped Form XObjects can make PyMuPDF report every source
        # sprite once per enclosing form even though the renderer paints only
        # one placement. Dense video-frame montages expose this strongly: 130
        # real image resources become 890 text-dict blocks. When both the
        # resource population and amplification are large, use the resource
        # count and normalize the repeated block area. A long resource list
        # containing relatively few distinct xrefs instead indicates genuine
        # repeated placements; those and small/reused icons stay on the
        # placement-count path so deleting repeated instances remains
        # detectable.
        try:
            image_resources = page.get_images(full=True)
            resource_count = len({int(image[0]) for image in image_resources})
        except Exception:
            image_resources = []
            resource_count = 0
        resources_are_not_heavily_reused = (
            len(image_resources) <= resource_count * 1.5
        )
        if (
            resource_count >= 16
            and len(image_blocks) >= resource_count * 4
            and resources_are_not_heavily_reused
        ):
            return resource_count, area * resource_count / len(image_blocks)
        return len(image_blocks), area
    try:
        return len(page.get_images()), 0.0
    except Exception:
        return 0, 0.0


def _page_drawings(page: object) -> List[dict]:
    """`page.get_drawings()` with a per-document cache.

    Vector-drawing extraction is one of the most expensive PyMuPDF calls and
    several read-only analyses need it for the same page (graphic regions,
    visual regions, risk features, graphics counting). All call sites are
    pre-mutation or read-only, so caching on the document is safe.
    """
    document = getattr(page, "parent", None)
    number = getattr(page, "number", None)
    if document is None or number is None:
        try:
            return page.get_drawings()
        except Exception:
            return []
    cache = getattr(document, "_pdfzh_drawings_cache", None)
    if cache is None:
        cache = {}
        try:
            document._pdfzh_drawings_cache = cache
        except Exception:
            try:
                return page.get_drawings()
            except Exception:
                return []
    if number not in cache:
        try:
            cache[number] = page.get_drawings()
        except Exception:
            cache[number] = []
    return cache[number]


def _count_vector_graphics(page: object) -> int:
    drawings = _page_drawings(page)
    count = 0
    for drawing in drawings:
        rect = drawing.get("rect")
        if rect is None:
            continue
        width = float(rect.x1 - rect.x0)
        height = float(rect.y1 - rect.y0)
        if width >= GRAPHIC_REGION_MIN_SIDE and height >= GRAPHIC_REGION_MIN_SIDE:
            count += 1
    return count


def _caption_graphic_overlap_issues(
    original_page: object,
    translated_page: object,
    page_number: int,
    *,
    original_blocks: Optional[Sequence[dict]] = None,
    translated_blocks: Optional[Sequence[dict]] = None,
    visual_regions: Optional[Sequence[BBox]] = None,
) -> List[TranslationIssue]:
    page_visual_regions = (
        list(visual_regions)
        if visual_regions is not None
        else _visual_regions_for_page(original_page, blocks=original_blocks)
    )
    if not page_visual_regions:
        return []
    source_captions = _source_caption_regions(original_page, blocks=original_blocks)
    page_translated_blocks = (
        translated_blocks
        if translated_blocks is not None
        else translated_page.get_text("dict").get("blocks", [])
    )

    issues: List[TranslationIssue] = []
    for block in page_translated_blocks:
        if block.get("type") != 0:
            continue
        text = _extract_text_from_block(block)
        if not _CAPTION_RE.match(text.strip()):
            continue
        bbox = block.get("bbox")
        if not bbox:
            continue
        caption_bbox = tuple(float(value) for value in bbox)
        if _caption_near_source_caption(text, caption_bbox, source_captions):
            continue
        for region in page_visual_regions:
            if _bbox_overlap_ratio(caption_bbox, region) >= 0.08:
                issues.append(
                    TranslationIssue(
                        page=page_number,
                        code="caption_overlap",
                        message=(
                            f"Page {page_number}: caption overlaps a figure or table region"
                        ),
                    )
                )
                break
    return issues


def _source_caption_regions(
    page: object,
    *,
    blocks: Optional[Sequence[dict]] = None,
) -> List[Tuple[Tuple[str, str], BBox]]:
    captions: List[Tuple[Tuple[str, str], BBox]] = []
    page_blocks = blocks if blocks is not None else page.get_text("dict").get("blocks", [])
    for block in page_blocks:
        if block.get("type") != 0 or not block.get("bbox"):
            continue
        text = _extract_text_from_block(block).strip()
        if not _CAPTION_RE.match(text):
            continue
        captions.append(
            (
                _caption_key(text),
                tuple(float(value) for value in block["bbox"]),
            )
        )
    return captions


def _caption_key(text: str) -> Tuple[str, str]:
    compact = " ".join(text.split())
    match = re.match(r"^(Figure|Fig\.|Table|图|表)\s*(\d+)", compact, re.IGNORECASE)
    if not match:
        return ("", "")
    kind = match.group(1).lower()
    if kind in {"figure", "fig.", "图"}:
        kind = "figure"
    elif kind in {"table", "表"}:
        kind = "table"
    return kind, match.group(2)


def _caption_near_source_caption(
    text: str,
    bbox: BBox,
    source_captions: Sequence[Tuple[Tuple[str, str], BBox]],
) -> bool:
    if not source_captions:
        return False
    key = _caption_key(text)
    candidates = [caption for caption in source_captions if key != ("", "") and caption[0] == key]
    if not candidates:
        candidates = source_captions
    for _candidate_key, source_bbox in candidates:
        height = max(1.0, source_bbox[3] - source_bbox[1])
        expanded = (
            source_bbox[0] - 12.0,
            source_bbox[1] - max(20.0, height * 0.5),
            source_bbox[2] + 12.0,
            source_bbox[3] + max(20.0, height * 0.8),
        )
        if _bbox_overlap_ratio(bbox, expanded) >= 0.75:
            return True
    return False


def _visual_regions_for_page(
    page: object,
    *,
    blocks: Optional[Sequence[dict]] = None,
) -> List[BBox]:
    regions: List[BBox] = []
    page_blocks = blocks if blocks is not None else page.get_text("dict").get("blocks", [])
    text_boxes = [
        tuple(float(value) for value in block.get("bbox", (0, 0, 0, 0)))
        for block in page_blocks
        if block.get("type") == 0 and block.get("bbox")
    ]
    for block in page_blocks:
        if block.get("type") == 0 or not block.get("bbox"):
            continue
        bbox = tuple(float(value) for value in block["bbox"])
        if bbox_is_graphic_candidate(bbox, page.rect):
            regions.append(bbox)
    for img in page.get_images():
        try:
            rect = page.get_image_bbox(img)
        except Exception:
            continue
        if rect and rect.is_empty is False and rect.is_valid:
            regions.append((rect.x0, rect.y0, rect.x1, rect.y1))
    for drawing in _page_drawings(page):
        rect = drawing.get("rect")
        if rect is None:
            continue
        width = float(rect.x1 - rect.x0)
        height = float(rect.y1 - rect.y0)
        bbox = (float(rect.x0), float(rect.y0), float(rect.x1), float(rect.y1))
        if _looks_like_text_background(bbox, text_boxes):
            continue
        if width >= GRAPHIC_REGION_MIN_SIDE and height >= GRAPHIC_REGION_MIN_SIDE:
            regions.append(bbox)
    if not regions:
        return []
    return merge_nearby_bboxes(regions, 2.0)


_FRAME_RULE_MAX_THICKNESS = 2.5
_FRAME_RULE_MIN_LENGTH = 12.0


def _page_frame_rule_bboxes(page: object) -> Tuple[List[BBox], List[BBox]]:
    """Thin stroked rules on a page, split into (horizontal, vertical) bboxes.

    Boxed prompts, framed notes and booktabs rows are drawn as hairline rules
    or stroked rectangles; the text they enclose must not be widened or grown
    across them. Stroked rectangles contribute their four edges so a framed
    block sees the frame whether it was drawn as one path or four segments.
    """
    horizontal: List[BBox] = []
    vertical: List[BBox] = []

    def add_segment(x0: float, y0: float, x1: float, y1: float) -> None:
        width, height = abs(x1 - x0), abs(y1 - y0)
        if height <= _FRAME_RULE_MAX_THICKNESS and width >= _FRAME_RULE_MIN_LENGTH:
            horizontal.append((min(x0, x1), min(y0, y1), max(x0, x1), max(y0, y1)))
        elif width <= _FRAME_RULE_MAX_THICKNESS and height >= _FRAME_RULE_MIN_LENGTH:
            vertical.append((min(x0, x1), min(y0, y1), max(x0, x1), max(y0, y1)))

    for drawing in _page_drawings(page):
        dashes = drawing.get("dashes")
        if dashes and dashes not in ("", "[] 0"):
            continue
        for item in drawing.get("items", ()):
            if not item:
                continue
            kind = item[0]
            if kind == "l":
                p1, p2 = item[1], item[2]
                add_segment(float(p1.x), float(p1.y), float(p2.x), float(p2.y))
            elif kind == "re":
                rect = item[1]
                x0, y0, x1, y1 = (
                    float(rect.x0),
                    float(rect.y0),
                    float(rect.x1),
                    float(rect.y1),
                )
                width, height = x1 - x0, y1 - y0
                if height <= _FRAME_RULE_MAX_THICKNESS or width <= _FRAME_RULE_MAX_THICKNESS:
                    add_segment(x0, y0, x1, y1)
                    continue
                if drawing.get("fill") is not None or drawing.get("color") is None:
                    continue
                if width < _FRAME_RULE_MIN_LENGTH or height < _FRAME_RULE_MIN_LENGTH:
                    continue
                horizontal.append((x0, y0, x1, y0))
                horizontal.append((x0, y1, x1, y1))
                vertical.append((x0, y0, x0, y1))
                vertical.append((x1, y0, x1, y1))

    def unique(rules: List[BBox]) -> List[BBox]:
        # A closed path retraces its last edge; identical segments count once.
        seen: Dict[Tuple[float, float, float, float], BBox] = {}
        for rule in rules:
            key = tuple(round(value, 1) for value in rule)
            seen.setdefault(key, rule)
        return list(seen.values())

    return unique(horizontal), unique(vertical)


def _frame_right_limit(
    bbox: BBox,
    vertical_rules: Sequence[BBox],
    *,
    inset: float,
) -> Optional[float]:
    """Nearest vertical rule to the right of a block that spans its rows.

    Distance does not matter: a short line inside a wide box is still bounded
    by the box, and a figure frame further right must not be painted over.
    """
    x0, y0, x1, y1 = bbox
    height = max(1.0, y1 - y0)
    limits = []
    for rule in vertical_rules:
        rule_x = (rule[0] + rule[2]) / 2.0
        if rule_x < x1 - 1.0:
            continue
        overlap = min(y1, rule[3]) - max(y0, rule[1])
        if overlap < height * 0.5:
            continue
        limits.append(rule_x - inset)
    return min(limits) if limits else None


def _clip_block_bbox_against_floats(
    bbox: BBox,
    floats: Sequence[BBox],
    page_width: float,
    *,
    min_keep_ratio: float = 0.20,
    side_gap: float = 3.0,
) -> BBox:
    """Shrink a wide (cross-column) block's right edge so reflowed CJK text stays
    out of a right-column figure/table/caption.

    Source PDFs often give a paragraph that visually wraps around a right-side
    float a full-width bounding box (lines above/below the float span the page).
    The CJK engine then fills that whole box left-to-right and paints over the
    float. We only clip when the block is clearly cross-column, a float occupies
    its right region, and the clipped box still keeps a usable width; otherwise
    the original bbox is returned so nothing gets worse.
    """
    x0, y0, x1, y1 = bbox
    width = x1 - x0
    if page_width <= 0 or width < page_width * 0.55:
        return bbox
    merged_floats = [tuple(float(value) for value in item) for item in floats]
    changed = True
    while changed:
        changed = False
        remaining: List[BBox] = []
        while merged_floats:
            current = merged_floats.pop(0)
            index = 0
            while index < len(merged_floats):
                candidate = merged_floats[index]
                horizontal_gap = max(
                    candidate[0] - current[2],
                    current[0] - candidate[2],
                    0.0,
                )
                vertical_overlap = max(
                    0.0,
                    min(current[3], candidate[3])
                    - max(current[1], candidate[1]),
                )
                shorter_height = max(
                    1.0,
                    min(current[3] - current[1], candidate[3] - candidate[1]),
                )
                if horizontal_gap <= 4.0 and vertical_overlap / shorter_height >= 0.65:
                    current = union_bbox([current, candidate])
                    merged_floats.pop(index)
                    changed = True
                    index = 0
                    continue
                index += 1
            remaining.append(current)
        merged_floats = remaining

    new_x1 = x1
    for fx0, fy0, fx1, fy1 in merged_floats:
        if min(y1, fy1) - max(y0, fy0) <= 4.0:
            continue
        if fx0 <= x0 + width * 0.35:
            continue
        if fx1 >= x1 - width * 0.10 and fx0 < new_x1:
            new_x1 = min(new_x1, fx0 - side_gap)
    if new_x1 < x1 - 1.0 and (new_x1 - x0) >= page_width * min_keep_ratio:
        return (x0, y0, new_x1, y1)
    return bbox


def _float_clip_min_font_size(min_font_size: float, requested_size: float) -> float:
    """A permanent side-column clip must preserve the page's body-size role."""
    return max(min_font_size, requested_size * 0.96)


def _looks_like_text_background(bbox: BBox, text_boxes: Sequence[BBox]) -> bool:
    area = max(1.0, bbox_area(bbox))
    return any(bbox_intersection_area(bbox, text_box) / area >= 0.10 for text_box in text_boxes)


def _bbox_overlap_ratio(a: BBox, b: BBox) -> float:
    ax0, ay0, ax1, ay1 = a
    bx0, by0, bx1, by1 = b
    overlap_w = max(0.0, min(ax1, bx1) - max(ax0, bx0))
    overlap_h = max(0.0, min(ay1, by1) - max(ay0, by0))
    if overlap_w <= 0 or overlap_h <= 0:
        return 0.0
    area = max(1.0, (ax1 - ax0) * (ay1 - ay0))
    return (overlap_w * overlap_h) / area


def _extract_formula_fragments(
    page: object,
    *,
    blocks: Optional[Sequence[dict]] = None,
) -> List[str]:
    fragments: List[str] = []
    seen: set[str] = set()
    page_blocks = blocks if blocks is not None else page.get_text("dict").get("blocks", [])
    review_line_number_bboxes = _review_line_number_bboxes({"blocks": page_blocks})
    for block in page_blocks:
        if block.get("type") != 0:
            continue
        text_parts: List[str] = []
        saw_span = False
        for line in block.get("lines", []):
            for span in line.get("spans", []):
                saw_span = True
                span_bbox = tuple(float(value) for value in span.get("bbox", ()))
                is_review_line_number = len(span_bbox) == 4 and any(
                    all(
                        abs(value - expected) <= 0.75
                        for value, expected in zip(span_bbox, gutter_bbox)
                    )
                    for gutter_bbox in review_line_number_bboxes
                )
                if not is_review_line_number:
                    span_text = span.get("text", "")
                    if span_text.strip().casefold() in {"and", "where"}:
                        span_text = f" {span_text.strip()} "
                    text_parts.append(span_text)
        text = "".join(text_parts) if saw_span else _extract_text_from_block(block)
        # Explanatory parentheticals can be emitted in the same PDF text
        # object as a preceding scalar (``d (i.e., ||eps||...)``).  They are
        # prose, not a formula preservation signature.
        text = re.split(
            r"\(\s*(?:i\.?e\.?|e\.?g\.?)\s*,",
            text,
            maxsplit=1,
            flags=re.IGNORECASE,
        )[0]
        # Author-year citations that share a PDF object with a short inline
        # formula are translated prose, not part of the preservation
        # signature (``sqrt(beta(tau)) (Song et al., 2020)``).
        text = AUTHOR_YEAR_CITATION_RE.sub("", text)
        # Natural-language connectors embedded between two equations belong
        # to translatable prose. Keeping them inside one preservation
        # signature makes a correct ``and -> 及`` translation look like a
        # damaged formula and also couples otherwise independent equations.
        for candidate in re.split(
            r"\b(?:and|where|indicates|initialize(?:d|s|ing)?)\b",
            text,
            flags=re.IGNORECASE,
        ):
            if not _looks_like_formula_fragment(candidate):
                continue
            compact = re.sub(r"\s+", "", candidate)
            if compact and compact not in seen:
                fragments.append(compact)
                seen.add(compact)
    return fragments[:20]


def _normalize_formula_fragment_for_compare(text: str) -> str:
    compact = re.sub(r"\s+", "", text)
    return (
        compact.replace("：", ":")
        .replace("，", ",")
        .replace("（", "(")
        .replace("）", ")")
        .replace("−", "-")
        # Computer Modern extraction may expose the same Greek variable as
        # either the micro sign or Greek small mu.
        .replace("µ", "μ")
        # TeX math fonts use both the lunate epsilon (ϵ) and Greek epsilon
        # (ε) for the same semantic variable. Formula sprites and their
        # accessibility text can legitimately extract as either glyph.
        .replace("ϵ", "ε")
        # Accessibility fallbacks commonly encode mathematical script ell as
        # ASCII l. They are the same variable, not a formula edit.
        .replace("ℓ", "l")
    )


def _strip_formula_compare_tail(text: str) -> str:
    previous = None
    current = text
    while current != previous:
        previous = current
        current = re.sub(r"[.,;:，。；：]+$", "", current)
        current = re.sub(r"\(\d{1,3}(?:\.\d+)?\)$", "", current)
    return current


def _missing_formula_fragments(
    fragments: Sequence[str],
    translated_compacts: Sequence[str],
) -> List[str]:
    """Fragments absent from every extraction view of the translated page.

    Block-joined and raw text extraction can order 2D math (sub/superscripts,
    stacked operators) differently; a fragment present in either view
    survived translation.
    """
    return [
        fragment
        for fragment in fragments
        if not (
            any(
                _formula_fragment_present(fragment, compact)
                for compact in translated_compacts
            )
            or _large_operator_formula_present_across_views(
                fragment,
                translated_compacts,
            )
        )
    ]


def _large_operator_formula_present_across_views(
    fragment: str,
    translated_compacts: Sequence[str],
) -> bool:
    """Join exact evidence split by repaired 2D operator extraction order.

    A redacted CMEX operator is reinserted at the correct coordinates, but
    MuPDF's content-stream view lists that hidden glyph at the end of the
    page. The spatially sorted view contains ``lhs=operator`` while the
    content view retains the same ``lhs=scripts+operand``. Require both exact
    prefixes with one shared left-hand side; unrelated page-level symbols
    cannot satisfy the check.
    """
    normalized = _strip_formula_compare_tail(
        _normalize_formula_fragment_for_compare(fragment)
    ).replace("∑", "P").replace("Σ", "P")
    views = [
        _normalize_formula_fragment_for_compare(view)
        .replace("∑", "P")
        .replace("Σ", "P")
        for view in translated_compacts
    ]
    approximate = re.fullmatch(
        r"(?P<left>[^=≈]{1,30})≈(?P<operator>[PX])(?P<rest>.+)",
        normalized,
    )
    if approximate is not None:
        left = approximate.group("left")
        operator = approximate.group("operator")
        rest = approximate.group("rest")
        if re.search(r"[A-Za-zα-ωΑ-Ω]+(?:=?|-)?\d", rest):
            return bool(
                any(f"{left}≈{rest}" in view for view in views)
                and any(
                    f"{operator}{rest}{left}≈" in view
                    for view in views
                )
            )
    match = re.fullmatch(
        r"(?P<left>[^=]{1,30})=P(?P<rest>.+)",
        normalized,
    )
    if not match:
        return False
    rest = match.group("rest")
    if not re.search(r"[A-Za-zα-ωΑ-Ω]+=?\d", rest):
        return False
    prefix = f"{match.group('left')}="
    return bool(
        any(f"{prefix}P" in view for view in views)
        and any(f"{prefix}{rest}" in view for view in views)
    )


_INLINE_FORMULA_SIGNATURE_STRIP_RE = re.compile(
    r"[\^_{}\x00∗⋆′†‡\ufe00-\ufe0f]"
)
_INLINE_FORMULA_MATH_CUE_RE = re.compile(r"[=+−\-*/→↗↘∈≤≥<>()\[\],]|·")


def _normalize_inline_formula_signature(text: str) -> str:
    """Flatten source script wrappers while preserving formula reading order."""
    normalized = _normalize_formula_fragment_for_compare(
        _normalize_formula_accessibility_text(text)
    ).replace("∑", "P")
    return _INLINE_FORMULA_SIGNATURE_STRIP_RE.sub("", normalized)


def _normalize_formula_accessibility_text(text: str) -> str:
    """Return a font-portable copy/search representation of formula text.

    Mathematical alphanumeric Unicode glyphs are compatibility characters.
    NFKC maps them to ordinary Latin/Greek code points that the hidden text
    layer's fallback fonts can encode, while the visible formula remains the
    untouched source raster. Normalise the Unicode minus as well so copied
    expressions and QA signatures use the same stable ASCII spelling.
    """
    return unicodedata.normalize("NFKC", text).replace("−", "-")


def _inline_formula_anchor_fragments(blocks: Sequence[TextBlock]) -> List[str]:
    """Return high-confidence signatures for reflowed inline formula anchors."""
    fragments: List[str] = []
    seen: set[str] = set()
    for block in blocks:
        if not block.formula_anchors:
            continue
        markers = SENTINEL_RUN_RE.findall(block.text)
        if len(markers) != len(block.formula_anchors):
            continue
        for marker in markers:
            signature = _normalize_inline_formula_signature(strip_sentinels(marker))
            if (
                len(signature) < 4
                or "=" not in signature
                or not _INLINE_FORMULA_MATH_CUE_RE.search(signature)
                or signature in seen
            ):
                continue
            fragments.append(signature)
            seen.add(signature)
    return fragments


def _missing_inline_formula_anchors(
    fragments: Sequence[str],
    translated_signatures: Sequence[str],
) -> List[str]:
    return [
        fragment
        for fragment in fragments
        if not any(fragment in signature for signature in translated_signatures)
    ]


def _longest_prefix_present(stripped: str, translated_compact: str) -> int:
    low, high = 0, len(stripped)
    while low < high:
        mid = (low + high + 1) // 2
        if stripped[:mid] in translated_compact:
            low = mid
        else:
            high = mid - 1
    return low


_MATH_FUNCTION_WORDS = frozenset(
    {
        "arg",
        "min",
        "max",
        "exp",
        "log",
        "ln",
        "sin",
        "cos",
        "tan",
        "sup",
        "inf",
        "lim",
        "det",
        "tr",
        "diag",
        "std",
        "var",
        "softmax",
        "relu",
        "st",
    }
)


def _trim_fragment_prose(text: str) -> str:
    """Drop leading/trailing prose words from a formula fragment.

    Source lines often prepend or append sentence words to inline math
    (e.g. ``objective), g'(e) = -H(F*e).``); the prose is legitimately
    translated, so only the math core must survive verbatim.
    """

    def _is_prose_word(word: str) -> bool:
        cleaned = word.strip("()[]{},.;:")
        return (
            cleaned.isascii()
            and cleaned.isalpha()
            and len(cleaned) >= 3
            and cleaned.lower() not in _MATH_FUNCTION_WORDS
        )

    words = text.split()
    if len(words) > 1:
        start, end = 0, len(words)
        while start < end and _is_prose_word(words[start]):
            start += 1
        while end > start and _is_prose_word(words[end - 1]):
            end -= 1
        trimmed = " ".join(words[start:end])
        return trimmed if trimmed else text
    return _trim_compact_fragment_prose(text)


_COMPACT_PROSE_LEAD_RE = re.compile(r"^[A-Za-z]{3,}[)\],.;:]*")
_COMPACT_PROSE_TAIL_RE = re.compile(r"[(\[,;:]*[A-Za-z]{3,}[.,;:]*$")


def _trim_compact_fragment_prose(compact: str) -> str:
    """Prose trim for fragments already stripped of whitespace."""
    original = compact
    while True:
        match = _COMPACT_PROSE_LEAD_RE.match(compact)
        if not match:
            break
        word = match.group(0).rstrip(")],.;:").lower()
        if word in _MATH_FUNCTION_WORDS:
            break
        compact = compact[match.end() :]
    while True:
        match = _COMPACT_PROSE_TAIL_RE.search(compact)
        if not match:
            break
        word = match.group(0).strip("([,;:.").lower()
        if word in _MATH_FUNCTION_WORDS:
            break
        compact = compact[: match.start()]
    return compact if compact else original


_FRAGMENT_CHUNK_MAX_GAP = 160
_FRAGMENT_CHUNK_MAX_COUNT = 4
_FRAGMENT_STRUCTURAL_CHARS = frozenset("()[]{}|,;.:⟩⟨")


def _fragment_chunks_present_in_order(stripped: str, translated_compact: str) -> bool:
    """Match a fragment as an ordered sequence of contiguous chunks.

    Re-extracted math often interleaves with translated prose (sub/superscript
    spans migrate between lines). Accept the fragment when its characters can
    be consumed left-to-right in at most a few long chunks with bounded gaps.
    Structural characters stranded by script migration may be skipped.
    """
    if len(stripped) < 4:
        return False
    first_chunk_len = _longest_prefix_present(stripped, translated_compact)
    if first_chunk_len < 2:
        return False
    first_chunk = stripped[:first_chunk_len]
    anchor = translated_compact.find(first_chunk)
    anchors_tried = 0
    while anchor >= 0 and anchors_tried < 8:
        if _fragment_chunks_match_from(
            stripped, translated_compact, anchor, first_chunk_len
        ):
            return True
        anchors_tried += 1
        anchor = translated_compact.find(first_chunk, anchor + 1)
    return False


def _fragment_chunks_match_from(
    stripped: str,
    translated_compact: str,
    anchor: int,
    first_chunk_len: int,
) -> bool:
    window_end = anchor + len(stripped) * 10 + 300
    position = anchor + first_chunk_len
    remaining = stripped[first_chunk_len:]
    chunks_used = 1
    while remaining:
        if chunks_used >= _FRAGMENT_CHUNK_MAX_COUNT:
            return False
        search_region = translated_compact[position:window_end]
        # Longest prefix of the remainder present in the search region.
        low, high = 0, len(remaining)
        while low < high:
            mid = (low + high + 1) // 2
            if remaining[:mid] in search_region:
                low = mid
            else:
                high = mid - 1
        min_chunk = 1 if (low == len(remaining) or len(remaining) <= 2) else 2
        if low < min_chunk:
            if remaining[0] in _FRAGMENT_STRUCTURAL_CHARS:
                remaining = remaining[1:]
                continue
            return False
        found_at = search_region.find(remaining[:low])
        if found_at > _FRAGMENT_CHUNK_MAX_GAP:
            return False
        position += found_at + low
        remaining = remaining[low:]
        chunks_used += 1
    return True


_SCRIPT_NOTATION_MARKER_RE = re.compile(r"[\^_]\{|\x00")
_SCRIPT_NOTATION_LENIENT_STRIP_RE = re.compile(r"[\^_{}\x00∗⋆′†‡¯̄˜̃]")


def _script_notation_lenient(text: str) -> str:
    """Flatten script-notation fallback rendering for comparison.

    Formulas re-rendered with the script-notation fallback extract as e.g.
    ``F^{\x00}_{ε}``: sub/superscripts gain ``^{}``/``_{}`` wrappers and
    glyphs missing from the fallback font extract as NUL. Drop the wrappers,
    the NULs, and the decorative glyphs NULs usually stand for, on both
    sides of the comparison.
    """
    return _SCRIPT_NOTATION_LENIENT_STRIP_RE.sub("", text)


def _two_dimensional_formula_sides_present(
    normalized: str,
    translated_compact: str,
) -> bool:
    """Match large-operator equations whose PDF span order is reversed."""
    if normalized.count("=") != 1:
        return False
    left, right = normalized.split("=", 1)
    left = _script_notation_lenient(left)
    right = _script_notation_lenient(_strip_formula_compare_tail(right))
    if (
        len(left) < 2
        or len(right) < 2
        or not re.match(r"^(?:Q|[∏∑ΣΠ])", right)
    ):
        return False
    page = _script_notation_lenient(
        _normalize_formula_fragment_for_compare(translated_compact)
    )
    return f"{left}=" in page and right in page


def _formula_fragment_present(fragment: str, translated_compact: str) -> bool:
    normalized = _normalize_formula_fragment_for_compare(fragment)
    normalized_page = _normalize_formula_fragment_for_compare(translated_compact)
    if _formula_fragment_present_core(normalized, normalized_page):
        return True
    # Sentence words glued to inline math are legitimately translated; retry
    # the comparison on the math core only.
    prose_trimmed = _normalize_formula_fragment_for_compare(
        _trim_fragment_prose(fragment)
    )
    if prose_trimmed != normalized and _formula_fragment_present_core(
        prose_trimmed, normalized_page
    ):
        return True
    # Script-notation fallback rendering rewrites sub/superscripts; compare
    # leniently only when the page shows evidence of that rendering.
    if _SCRIPT_NOTATION_MARKER_RE.search(normalized_page):
        # The accessibility fallback can express a native short ratio such
        # as ``𝐻′=𝑊`` as ``^{H}_{H}_{′}=^{W}_{W}_{′}``.  Flatten only the
        # script wrappers and compatibility math alphabet first, retaining
        # semantically significant primes and operators.  The broader
        # lenient path below may still discard decorations for long formulas
        # whose missing font glyphs extract as NUL.
        structural_page = re.sub(
            r"[\^_{}\x00]",
            "",
            unicodedata.normalize("NFKC", normalized_page),
        )
        for candidate in dict.fromkeys((normalized, prose_trimmed)):
            structural_fragment = re.sub(
                r"[\^_{}\x00]",
                "",
                unicodedata.normalize("NFKC", candidate),
            )
            if (
                len(_strip_formula_compare_tail(structural_fragment)) >= 4
                and _formula_fragment_present_core(
                    structural_fragment,
                    structural_page,
                )
            ):
                return True
        lenient_page = _script_notation_lenient(normalized_page)
        for candidate in dict.fromkeys((normalized, prose_trimmed)):
            lenient_fragment = _script_notation_lenient(candidate)
            if len(_strip_formula_compare_tail(lenient_fragment)) >= 4 and (
                _formula_fragment_present_core(lenient_fragment, lenient_page)
            ):
                return True
    if _two_dimensional_formula_sides_present(normalized, normalized_page):
        return True
    return False


def _formula_fragment_present_core(normalized: str, translated_compact: str) -> bool:
    if normalized in translated_compact:
        return True
    stripped = _strip_formula_compare_tail(normalized)
    if len(stripped) >= 6 and stripped in translated_compact:
        return True
    # Sub/superscript glyphs migrate across physical lines when a formula is
    # stamped or re-extracted: accept the fragment when its characters can be
    # consumed in reading order as a few long chunks with bounded gaps.
    if _fragment_chunks_present_in_order(stripped, translated_compact):
        return True
    return (
        len(stripped) >= 3
        and bool(re.search(r"[\d=+\-*/^_≤≥<>∥ρϵηαβγδ]", stripped))
        and stripped in translated_compact
    )


def _looks_like_formula_fragment(text: str) -> bool:
    compact = unicodedata.normalize("NFKC", " ".join(text.split()))
    if len(compact) < 3 or _REFERENCE_ENTRY_RE.search(compact):
        return False
    if any(ord(char) < 32 for char in text):
        return False
    if _looks_like_reference_entry_text(compact) or _looks_like_author_or_affiliation_text(compact):
        return False
    if re.search(
        r"\b(?:import|np\.|numpy\.|mcdc\.|h5py|MaterialMG|Surface|Cell|Universe)\b",
        compact,
    ):
        return False
    if re.search(r"\b[a-z][a-z0-9]*_[a-z0-9_]*\s*=", compact):
        return False
    if re.search(r"^[A-Za-z]\s*=\s*\[[^\]]+\]\s*,?\d*$", compact):
        return False
    if re.search(r'^"[^"]+"\s*:\s*<[^>]+>\s*,?\d*$', compact):
        return False
    if re.search(r"^[A-Za-z_][A-Za-z0-9_]*\s*=\s*[-+]?\d+(?:\.\d+)?\d*$", compact):
        return False
    if re.search(r"^[A-Za-z_][A-Za-z0-9_]*\s*=\s*[A-Za-z_][A-Za-z0-9_]*\d*$", compact):
        return False
    if re.search(r"^\s*\d+\s*:\s*[A-Za-z]", compact):
        return False
    if re.search(
        r"(?i)(?:^|[^a-z])(?:if|and|by|wehave|where|then|for|with|recall|hence|"
        r"similarly|moreover|therefore)(?:[^a-z]|$)",
        compact,
    ):
        return False
    if re.search(r"\bHandover\d+(?:/\d+){3,}", compact):
        return False
    compact_no_space = re.sub(r"\s+", "", compact)
    if compact_no_space[-1:] in {"=", "+", "−", "-", "≤", "≥", "<", ">", "∈", "∩", "×"}:
        return False
    if re.fullmatch(r"[A-Za-z][A-Za-z0-9]*=√", compact_no_space):
        return False
    digit_chars = sum(1 for char in compact_no_space if char.isdigit())
    slash_chars = compact_no_space.count("/")
    if re.search(r"\d{3}\d{3}", compact_no_space) and "=" not in compact_no_space:
        return False
    if slash_chars >= 3 and digit_chars / max(len(compact_no_space), 1) >= 0.35:
        return False
    words = _ASCII_WORD_DETECT_RE.findall(compact)
    math_chars = sum(1 for char in compact if char in MATH_SYMBOLS)
    if "=" in compact and not words:
        return True
    if looks_like_math(compact) and len(words) <= 1:
        return True
    return math_chars >= 2 and math_chars / max(len(compact), 1) >= 0.08 and len(words) <= 1


def _detect_high_risk_layout_features(
    page: object,
    *,
    blocks: Optional[Sequence[dict]] = None,
    page_text: Optional[str] = None,
) -> List[str]:
    features: List[str] = []
    if len(_page_drawings(page)) >= 40:
        features.append("dense vector drawing or table grid")
    if _has_table_like_text_grid(page, blocks=blocks):
        features.append("table-like text grid")
    if _has_algorithm_like_text(page, text=page_text):
        features.append("algorithm or pseudocode block")
    if _has_cross_page_float_risk(page):
        features.append("float near page boundary")
    return features


def _has_table_like_text_grid(
    page: object,
    *,
    blocks: Optional[Sequence[dict]] = None,
) -> bool:
    rows: Dict[int, int] = {}
    page_blocks = blocks if blocks is not None else page.get_text("dict").get("blocks", [])
    for block in page_blocks:
        if block.get("type") != 0:
            continue
        text = _extract_text_from_block(block)
        if len(text.strip()) > 35:
            continue
        bbox = block.get("bbox")
        if not bbox:
            continue
        row = int(float(bbox[1]) // 8)
        rows[row] = rows.get(row, 0) + 1
    return sum(1 for count in rows.values() if count >= 4) >= 3


def _has_algorithm_like_text(page: object, *, text: Optional[str] = None) -> bool:
    page_text = text if text is not None else page.get_text("text")
    markers = len(re.findall(r"^\s*\d{1,2}:\s+\S", page_text, flags=re.MULTILINE))
    keywords = re.search(r"\b(Require|Ensure|Input|Output|Algorithm)\b", page_text)
    return markers >= 2 or bool(markers and keywords)


def _has_cross_page_float_risk(page: object) -> bool:
    height = float(page.rect.height)
    risky = 0
    for zone in detect_image_zones(page):
        _x0, y0, _x1, y1 = zone
        if y0 < 40.0 or y1 > height - 40.0:
            risky += 1
    return risky >= 1


def _normalize_font_name(name: str) -> str:
    """Match display names ('Hiragino Sans GB W6') against PostScript base
    names ('HiraginoSansGB-W6')."""
    return re.sub(r"[\s\-_,]+", "", name.split("+")[-1]).lower()


def inserted_font_names(font_pack: FontPack) -> set:
    """Normalized names of the CJK faces this engine inserts."""
    names = set()
    for font in (
        font_pack.regular,
        font_pack.bold,
        font_pack.fallback,
        font_pack.math_fallback,
    ):
        name = getattr(font, "name", None)
        if name:
            names.add(_normalize_font_name(name))
    return names


def subset_fonts_safely(
    document: object,
    font_pack: FontPack,
    warnings: List[str],
    *,
    preserve_source_fonts: bool = False,
) -> object:
    """Subset fonts, but roll back when our inserted CJK glyphs are lost.

    PyMuPDF's subset_fonts() occasionally drops glyphs from CJK collection
    faces (e.g. Hiragino bold), rendering headings as blanks while the text
    layer stays intact. Full CJK faces cost ~20 MB each, so subsetting is
    worth attempting -- guarded by a glyph-coverage check with rollback.

    Only the fonts this engine inserted are checked: original document fonts
    (LaTeX CM math faces etc.) use custom encodings that defeat the
    Unicode-based has_glyph probe and would always flag as lost."""
    if preserve_source_fonts:
        warnings.append("Kept source fonts intact to preserve figure and formula glyph mappings")
        return document

    import fitz

    try:
        snapshot = document.tobytes(garbage=0)
    except Exception as exc:
        warnings.append("Font subsetting skipped (snapshot failed: %s)" % exc)
        return document
    try:
        document.subset_fonts()
    except Exception as exc:
        warnings.append("Font subsetting failed: %s" % exc)
        return document
    if not subset_lost_glyphs(document, inserted_font_names(font_pack)):
        return document
    warnings.append("Font subsetting dropped glyphs; keeping full fonts")
    document.close()
    return fitz.open("pdf", snapshot)


def subset_lost_glyphs(document: object, font_names: Optional[set] = None) -> bool:
    """True when a character drawn in one of `font_names` (normalized names,
    see _normalize_font_name; None = all fonts) lacks a glyph in its embedded
    font."""
    import fitz

    usage: Dict[str, set] = {}
    for page_index in range(document.page_count):
        page_dict = document[page_index].get_text("dict")
        for block in page_dict.get("blocks", []):
            if block.get("type") != 0:
                continue
            for line in block.get("lines", []):
                for span in line.get("spans", []):
                    base = _normalize_font_name(span.get("font", ""))
                    if font_names is not None and base not in font_names:
                        continue
                    usage.setdefault(base, set()).update(span.get("text", ""))

    checked: set = set()
    for page_index in range(document.page_count):
        for font_info in document.get_page_fonts(page_index):
            xref, basefont = font_info[0], font_info[3]
            base = _normalize_font_name(basefont)
            if base in checked:
                continue
            checked.add(base)
            chars = usage.get(base)
            if not chars:
                continue
            try:
                buffer = document.extract_font(xref)[-1]
                if not buffer:
                    continue
                font = fitz.Font(fontbuffer=buffer)
            except Exception:
                continue
            for char in chars:
                if char.strip() and not font.has_glyph(ord(char)):
                    return True
    return False


# --- Fonts -------------------------------------------------------------------


def build_font_pack(font_file: Optional[Path], warnings: List[str]) -> FontPack:
    """Resolve the body/bold/fallback fonts used for inserted Chinese text."""
    import fitz

    fallback_file = find_fallback_font_file()
    fallback_font = fitz.Font(fontfile=str(fallback_file)) if fallback_file else None
    math_file = find_math_fallback_font_file()
    if math_file is not None and math_file == fallback_file:
        math_file = None
    math_font = fitz.Font(fontfile=str(math_file)) if math_file else None

    if font_file is not None:
        user_font = fitz.Font(fontfile=str(font_file))
        return FontPack(
            regular=user_font,
            regular_file=Path(font_file),
            bold=user_font,
            bold_file=Path(font_file),
            fallback=fallback_font,
            fallback_file=fallback_file,
            math_fallback=math_font,
            math_fallback_file=math_file,
            bold_alias="zhbody",
        )

    body_file, bold_file = ensure_font_pack_files(warnings)
    if body_file is None:
        discovered = find_default_font_file()
        if discovered is None:
            raise RuntimeError(
                "No CJK font available. Pass --font-file with a TTF/OTF that covers Chinese."
            )
        warnings.append("Using system CJK font: %s" % discovered)
        body_file = discovered
    if bold_file is None:
        bold_file = body_file

    regular = fitz.Font(fontfile=str(body_file))
    bold = fitz.Font(fontfile=str(bold_file))
    return FontPack(
        regular=regular,
        regular_file=body_file,
        bold=bold,
        bold_file=bold_file,
        fallback=fallback_font,
        fallback_file=fallback_file,
        math_fallback=math_font,
        math_fallback_file=math_file,
        bold_alias="zhbold" if bold_file != body_file else "zhbody",
    )


def ensure_font_pack_files(warnings: List[str]) -> Tuple[Optional[Path], Optional[Path]]:
    """Resolve valid body/heading faces in the local user font cache."""
    with _FONT_PACK_LOCK:
        results: List[Optional[Path]] = []
        for destination, candidates in TTC_FACE_SOURCES:
            if _font_file_has_valid_signature(destination):
                _sanitize_noto_cjk_font_file(destination, warnings)
                results.append(destination)
                continue
            if destination.exists():
                warnings.append(
                    "Rebuilding invalid cached CJK font: %s" % destination.name
                )
            extracted = None
            for ttc_path, face_name in candidates:
                candidate = extract_ttc_face(Path(ttc_path), face_name, destination)
                if candidate is not None and _font_file_has_valid_signature(candidate):
                    extracted = candidate
                    break
            if extracted is None:
                warnings.append("Could not extract a valid face for %s" % destination.name)
            else:
                _sanitize_noto_cjk_font_file(extracted, warnings)
            results.append(extracted)
        return results[0], results[1]


def _font_file_has_valid_signature(path: Path) -> bool:
    try:
        stat = path.stat()
        if stat.st_size <= 0:
            return False
        # A non-empty file with no allocated blocks is a macOS/iCloud dataless
        # placeholder. Reject it before opening so the read cannot block on a
        # cloud materialization attempt.
        if getattr(stat, "st_blocks", 1) == 0:
            return False
        with path.open("rb") as stream:
            return stream.read(4) in _FONT_FILE_SIGNATURES
    except OSError:
        return False


def _sanitize_noto_cjk_unicode_cmap(font: object) -> bool:
    """Remove ambiguous reverse mappings that corrupt copied PDF text."""
    try:
        font_name = font["name"].getDebugName(4) or ""
        cmap_tables = font["cmap"].tables
    except (KeyError, AttributeError, TypeError):
        return False
    if "Noto" not in font_name or "CJK" not in font_name:
        return False

    changed = False
    for table in cmap_tables:
        if not table.isUnicode():
            continue
        cmap = table.cmap
        canonical_glyphs = {
            glyph
            for codepoint, glyph in cmap.items()
            if not (
                codepoint in _AMBIGUOUS_NOTO_COPY_CODEPOINTS
                or 0xF900 <= codepoint <= 0xFAFF
                or 0x2F800 <= codepoint <= 0x2FA1F
            )
        }
        for codepoint, glyph in list(cmap.items()):
            canonical_codepoint = _AMBIGUOUS_NOTO_COPY_CODEPOINTS.get(codepoint)
            explicit_duplicate = (
                canonical_codepoint is not None
                and cmap.get(canonical_codepoint) == glyph
            )
            compatibility_duplicate = (
                0xF900 <= codepoint <= 0xFAFF
                or 0x2F800 <= codepoint <= 0x2FA1F
            ) and glyph in canonical_glyphs
            if explicit_duplicate or compatibility_duplicate:
                del cmap[codepoint]
                changed = True
    return changed


# Reference vertical metrics for the extracted CJK faces, taken from the
# macOS faces (Songti SC body, Hiragino Sans GB W6 bold) that the layout
# engine and the raster QA checkers were tuned against. Linux Noto CJK files
# carry hhea box metrics sized for kana/hangul (ascender 1.15em, descender
# 0.29em); the engine's line stacking and the QA span boxes both read these
# values, so unnormalized fonts make CI/server layout diverge from macOS.
# Noto's own OS/2 typographic metrics are 0.88/-0.12 — the hhea box is the
# outlier being normalized here.
_CJK_VERTICAL_METRIC_TARGETS = {
    "SongtiSC-Regular.ttf": (1.06, -0.34),
    "HiraginoSansGB-W6.ttf": (0.88, -0.12),
}


def _normalize_cjk_vertical_metrics(font: object, path: Path) -> bool:
    targets = _CJK_VERTICAL_METRIC_TARGETS.get(path.name)
    if targets is None:
        return False
    ascent_em, descent_em = targets
    try:
        upem = int(font["head"].unitsPerEm) or 1000
        hhea = font["hhea"]
    except Exception:
        return False
    target_ascent = int(round(ascent_em * upem))
    target_descent = int(round(descent_em * upem))
    if hhea.ascent == target_ascent and hhea.descent == target_descent:
        return False
    hhea.ascent = target_ascent
    hhea.descent = target_descent
    try:
        os2 = font["OS/2"]
    except Exception:
        os2 = None
    if os2 is not None:
        os2.sTypoAscender = target_ascent
        os2.sTypoDescender = target_descent
        os2.usWinAscent = target_ascent
        os2.usWinDescent = -target_descent
    return True


def _sanitize_noto_cjk_font_file(path: Path, warnings: List[str]) -> None:
    try:
        stat = path.stat()
    except OSError:
        return
    signature = (str(path.resolve()), stat.st_size, stat.st_mtime_ns)
    if signature in _SANITIZED_NOTO_CJK_FONT_FILES:
        return

    try:
        from fontTools.ttLib import TTFont

        font = TTFont(str(path), lazy=False)
        changed = _sanitize_noto_cjk_unicode_cmap(font)
        changed = _normalize_cjk_vertical_metrics(font, path) or changed
        if changed:
            temporary = path.with_name(f".{path.name}.{uuid.uuid4().hex}.tmp")
            try:
                font.save(str(temporary))
                os.replace(temporary, path)
            finally:
                temporary.unlink(missing_ok=True)
        font.close()
    except Exception as exc:
        warnings.append(f"Could not sanitize CJK font copy mappings: {exc}")
        return

    current = path.stat()
    _SANITIZED_NOTO_CJK_FONT_FILES.add(
        (str(path.resolve()), current.st_size, current.st_mtime_ns)
    )


def extract_ttc_face(ttc_path: Path, face_name: str, destination: Path) -> Optional[Path]:
    if not ttc_path.is_file():
        return None
    try:
        from fontTools.ttLib import TTCollection
    except ImportError:
        return None
    try:
        collection = TTCollection(str(ttc_path), lazy=False)
        try:
            for face in collection.fonts:
                name = face["name"].getDebugName(4) or ""
                if not name.startswith(face_name):
                    continue
                destination.parent.mkdir(parents=True, exist_ok=True)
                temporary = destination.with_name(
                    f".{destination.name}.{uuid.uuid4().hex}.tmp"
                )
                try:
                    face.save(str(temporary))
                    if not _font_file_has_valid_signature(temporary):
                        return None
                    os.replace(temporary, destination)
                finally:
                    temporary.unlink(missing_ok=True)
                return destination
        finally:
            collection.close()
    except Exception:
        return None
    return None


def find_fallback_font_file() -> Optional[Path]:
    for candidate in FALLBACK_FONT_CANDIDATES:
        path = Path(candidate).expanduser()
        if path.is_file():
            return path
    return None


def find_math_fallback_font_file() -> Optional[Path]:
    for candidate in MATH_FALLBACK_FONT_CANDIDATES:
        path = Path(candidate).expanduser()
        if path.is_file():
            return path
    return None


def find_default_font_file() -> Optional[Path]:
    env_override = os.environ.get("PDF_ZH_FONT_FILE", "").strip()
    if env_override:
        override_path = Path(env_override).expanduser()
        if override_path.is_file():
            return override_path
    for candidate in FONT_FILE_CANDIDATES:
        path = Path(candidate).expanduser()
        if path.is_file():
            return path
    for root in FONT_SEARCH_ROOTS:
        if not root.is_dir():
            continue
        for pattern in FONT_SEARCH_PATTERNS:
            for found in sorted(root.rglob(pattern)):
                if found.is_file():
                    return found
    return None


def register_font_pack(page: object, pack: FontPack) -> None:
    page.insert_font(fontname=pack.regular_alias, fontfile=str(pack.regular_file))
    if pack.bold_alias != pack.regular_alias:
        page.insert_font(fontname=pack.bold_alias, fontfile=str(pack.bold_file))
    if pack.fallback_file is not None:
        page.insert_font(fontname=pack.fallback_alias, fontfile=str(pack.fallback_file))
    if pack.math_fallback_file is not None:
        page.insert_font(
            fontname=pack.math_fallback_alias, fontfile=str(pack.math_fallback_file)
        )


TranslationUnit = Tuple[TextBlock, str, Dict[int, str]]


def fragmented_prose_warnings_from_units(units: Sequence[TranslationUnit]) -> List[str]:
    """Flag pages where prose was split into many fixed-width single-line units."""
    page_counts: Dict[int, Tuple[int, int]] = {}
    for block, _, _ in units:
        if block.block_type != "body":
            continue
        body_count, fragmented_count = page_counts.get(block.page_index, (0, 0))
        body_count += 1
        plain = strip_sentinels(block.text)
        if (
            block.nowrap
            and block.source_lines <= 1
            and len(plain.strip()) >= 20
            and not _looks_like_small_fixed_width_table_fragment(block, plain)
        ):
            fragmented_count += 1
        page_counts[block.page_index] = (body_count, fragmented_count)

    warnings: List[str] = []
    for page_index, (body_count, fragmented_count) in sorted(page_counts.items()):
        threshold = max(6, int(body_count * 0.35))
        if fragmented_count >= threshold:
            warnings.append(
                "Page %d: %d body line(s) were treated as fixed-width fragments; "
                "prose may have been translated line-by-line"
                % (page_index + 1, fragmented_count)
            )
    return warnings


def _looks_like_small_fixed_width_table_fragment(block: TextBlock, text: str) -> bool:
    """Small fixed-width cells are usually tables/figure labels, not prose flow."""
    compact = " ".join(text.split())
    if not compact:
        return True
    width = block.bbox[2] - block.bbox[0]
    words = _PROSE_WORD_RE.findall(compact)
    lower = compact.lower()
    if block.font_size <= 8.5:
        return True
    if _looks_like_code_or_symbolic_text(compact) or looks_like_math(compact):
        return True
    if block.font_size <= 10.5 and re.search(
        r"\b(?:prompt template|your task is|please assign|use the following scale|"
        r"output a concise rationale|integer score from|brief explanation|"
        r"target-embodiment match|interaction preservation|scene preservation|"
        r"robotness|naturalness|artifact absence|local coherence)\b",
        lower,
    ):
        return True
    if re.search(r"\b(?:CR1|CR2|ICD|K-NN|BA:|Dataset|Success Rate)\b", compact):
        return True
    if any(marker in compact for marker in ("↔", "✓", "✗")):
        return True
    if width <= 240.0 and len(words) <= 8 and not re.search(r"[.!?。！？]$", compact):
        return True
    if compact.count(",") >= 2 and len(words) <= 24:
        return True
    if block.font_size <= 9.5 and width <= 380.0:
        if re.search(
            r"\b(?:beaker|flask|reagent|cylinder|pipette|centrifuge|thermometer|"
            r"cuvette|crucible|funnel|stirrer|mantle|hygrometer|balance|"
            r"yaml|schema|registry|verifier|constraint|constraints|reachability|"
            r"support table|stage-conditional|table\s+\d+)\b",
            lower,
        ):
            return True
    return False


def _preserved_block_regions(block: TextBlock) -> List[BBox]:
    """Return the source ink regions that must remain untouched for a block.

    Formula and action-skeleton hulls often span large empty bands between
    independently positioned glyph rows. Preserving those hulls would freeze
    neighboring prose that only crosses the empty area, so retain their actual
    source lines instead.
    """
    if math_heavy_block(block) and block.source_math_atom_bboxes:
        return list(block.source_math_atom_bboxes)
    if block.source_line_bboxes and (
        looks_like_action_skeleton_sequence(block.text) or math_heavy_block(block)
    ):
        return list(block.source_line_bboxes)
    return [block.bbox]


def _regions_not_owned_by_formula_blocks(
    regions: Sequence[BBox],
    blocks: Sequence[TextBlock],
) -> List[BBox]:
    """Drop equation regions captured as movable formula tokens by a block."""
    owned = [
        source_region
        for block in blocks
        if block.flow_inline_math and block.block_type == "formula_prose"
        for source_region in (
            *block.source_math_bboxes,
            *block.source_prose_bboxes,
        )
    ]
    output: List[BBox] = []
    for region in regions:
        area = max(bbox_area(region), 0.1)
        if any(
            bbox_intersection_area(region, formula) / area >= 0.9
            for formula in owned
        ):
            continue
        output.append(region)
    return output


def _promote_run_in_academic_statement_bodies(blocks: Sequence[TextBlock]) -> None:
    """Keep formula-bearing theorem text translatable after a split label.

    TeX commonly emits ``Lemma 3.`` and its same-line ``If ...`` body as
    separate PDF records.  Once paragraph merging correctly stops at the
    following paragraph, the isolated body can look math-heavy and be
    preserved as artwork.  Recover the shared run-in structure before the
    preservation pass instead of weakening math preservation globally.
    """
    for heading, body in zip(blocks, blocks[1:]):
        if (
            heading.page_index != body.page_index
            or heading.block_type != "run_in_heading"
            or body.block_type not in {"body", "formula_prose"}
            or not body.source_math_bboxes
        ):
            continue
        heading_text = " ".join(strip_sentinels(heading.text).split())
        body_text = " ".join(SENTINEL_RUN_RE.sub(" ", body.text).split())
        if not _ACADEMIC_FORMULA_STATEMENT_RE.match(heading_text):
            continue
        if not re.match(
            r"^(?:If|Let|Suppose|Assume|Given|For\s+(?:all|any|each))\b",
            body_text,
            re.IGNORECASE,
        ):
            continue
        heading_height = max(heading.bbox[3] - heading.bbox[1], 1.0)
        body_first_line = (
            body.source_line_bboxes[0] if body.source_line_bboxes else body.bbox
        )
        body_height = max(body_first_line[3] - body_first_line[1], 1.0)
        vertical_overlap = min(heading.bbox[3], body_first_line[3]) - max(
            heading.bbox[1], body_first_line[1]
        )
        horizontal_gap = body_first_line[0] - heading.bbox[2]
        if (
            vertical_overlap < min(heading_height, body_height) * 0.55
            or not -2.0 <= horizontal_gap <= 8.0
        ):
            continue
        body.block_type = "formula_prose"
        body.should_translate = True
        body.preserve_position = False
        body.no_merge = True


def _detach_terminal_formula_punctuation(block: TextBlock) -> None:
    """Return sentence punctuation at the end of an inline formula to prose.

    TeX PDFs often emit the final period or comma with the surrounding math
    font.  Keeping that glyph in the formula sprite moves it with the formula's
    ink box, which can leave a visibly lowered punctuation mark after CJK
    reflow.  Only detach a narrow, rightmost atom from a multi-atom terminal
    formula run; decimal points and punctuation inside a formula remain owned
    by the formula.
    """
    matches = list(SENTINEL_RUN_RE.finditer(block.text))
    if not matches:
        return
    marker = matches[-1]
    if block.text[marker.end() :].strip():
        return
    terminal = re.search(
        rf"{re.escape(SENTINEL_OPEN)}([.,;:]){re.escape(SENTINEL_CLOSE)}$",
        marker.group(0),
    )
    if terminal is None:
        return
    formula_index = len(matches) - 1
    if formula_index >= len(block.source_math_atom_groups):
        return
    atom_group = list(block.source_math_atom_groups[formula_index])
    if len(atom_group) < 2:
        return
    punctuation_bbox = atom_group[-1]
    punctuation_width = punctuation_bbox[2] - punctuation_bbox[0]
    if punctuation_width > max(4.0, block.font_size * 0.8):
        return
    if punctuation_bbox[2] + 0.25 < max(atom[2] for atom in atom_group[:-1]):
        return

    punctuation = terminal.group(1)
    shortened_marker = marker.group(0)[: terminal.start()]
    block.text = (
        block.text[: marker.start()]
        + shortened_marker
        + punctuation
        + block.text[marker.end() :]
    )

    atom_group.pop()
    math_groups = list(block.source_math_atom_groups)
    math_groups[formula_index] = tuple(atom_group)
    block.source_math_atom_groups = tuple(math_groups)

    math_runs = list(block.source_math_bboxes)
    if formula_index < len(math_runs):
        math_runs[formula_index] = union_bbox(atom_group)
        block.source_math_bboxes = tuple(math_runs)

    math_atoms = list(block.source_math_atom_bboxes)
    for index in range(len(math_atoms) - 1, -1, -1):
        if math_atoms[index] == punctuation_bbox:
            del math_atoms[index]
            break
    block.source_math_atom_bboxes = tuple(math_atoms)
    block.source_prose_bboxes = tuple(
        dict.fromkeys([*block.source_prose_bboxes, punctuation_bbox])
    )


def prepare_translation_units(
    document: object,
    preserve_graphics_text: bool = False,
    *,
    preserved_regions_out: Optional[Dict[int, List[BBox]]] = None,
    equation_rows_out: Optional[Dict[int, List[BBox]]] = None,
    algorithm_regions_out: Optional[Dict[int, List[BBox]]] = None,
    table_regions_out: Optional[Dict[int, List[BBox]]] = None,
) -> Tuple[List[TranslationUnit], Dict[int, List[BBox]], int]:
    """Shared extraction pipeline for both `translate` and `export`.

    Returns (units, gutter_rects, skipped) where each unit carries the block,
    its placeholder-protected text, and the restore mapping.

    Phase 1: Structure analysis — classify blocks by semantic type before translation.
    """
    global _bibliography_ended, _bibliography_heading_size

    algorithm_regions: Dict[int, List[BBox]] = {}
    equation_table_regions: Dict[int, List[BBox]] = {}
    display_equation_regions: Dict[int, List[BBox]] = {}
    rule_bounded_sample_regions: Dict[int, List[BBox]] = {}
    compute_preserved = preserve_graphics_text or preserved_regions_out is not None
    raw_blocks, gutter_rects = collect_text_blocks(
        document,
        algorithm_regions_out=(algorithm_regions if compute_preserved else None),
        equation_table_regions_out=equation_table_regions,
        # Always collected: reflow avoidance uses them even when preserved
        # graphics mode is off.
        display_equation_regions_out=display_equation_regions,
    )
    piecewise_equation_regions = _piecewise_display_equation_regions(
        raw_blocks,
        display_equation_regions,
    )
    if algorithm_regions_out is not None:
        algorithm_regions_out.clear()
        for page_index, page_algorithm_regions in algorithm_regions.items():
            algorithm_regions_out[page_index] = list(page_algorithm_regions)
    if equation_rows_out is not None:
        equation_rows_out.clear()
        for page_index, page_rows in display_equation_regions.items():
            equation_rows_out[page_index] = list(page_rows)
    if table_regions_out is not None:
        table_regions_out.clear()
    analyze_graphics = compute_preserved
    graphic_regions = collect_graphic_regions(document) if analyze_graphics else {}
    paragraph_merge_obstacles: Dict[int, List[BBox]] = {
        page_index: list(page_regions)
        for page_index, page_regions in (
            graphic_regions.items() if preserve_graphics_text else ()
        )
    }
    for page_index, page_rows in piecewise_equation_regions.items():
        paragraph_merge_obstacles.setdefault(page_index, []).extend(page_rows)
    blocks = merge_paragraph_blocks(
        raw_blocks,
        graphic_regions_by_page=paragraph_merge_obstacles,
    )
    for page_index in range(document.page_count):
        _attach_blank_completion_rule_vectors(
            document[page_index],
            [block for block in blocks if block.page_index == page_index],
        )
        _attach_inline_formula_rule_vectors(
            document[page_index],
            [block for block in blocks if block.page_index == page_index],
        )
    repeated_headers = _repeated_top_header_texts(blocks, document.page_count)

    # --- Phase 1: Structure-aware classification ---
    _bibliography_seen.clear()
    _bibliography_ended = False
    _bibliography_heading_size = 0.0
    for page_index in range(document.page_count):
        page = document[page_index]
        page_height = page.rect.height
        image_zones = detect_image_zones(
            page,
            graphic_regions.get(page_index, []) if analyze_graphics else None,
        )
        page_blocks = [b for b in blocks if b.page_index == page_index]
        classify_blocks(page_blocks, page_index, page_height, image_zones)
        _promote_run_in_academic_statement_bodies(page_blocks)
        page_sample_regions = _rule_bounded_sample_table_regions(page, page_blocks)
        if page_sample_regions:
            rule_bounded_sample_regions[page_index] = page_sample_regions
        for registry in (equation_table_regions, display_equation_regions):
            if page_index in registry:
                registry[page_index] = _regions_not_owned_by_formula_blocks(
                    registry[page_index],
                    page_blocks,
                )
        for block in page_blocks:
            plain = _normalized_running_header_text(block.text)
            if plain not in repeated_headers or block.bbox[3] > 72.0:
                continue
            block.block_type = "header"
            block.should_translate = True
            block.preserve_position = True
            block.nowrap = True
            block.no_merge = True
        _promote_equation_table_neighbor_blocks(
            page_blocks,
            equation_table_regions.get(page_index, ()),
        )
        if table_regions_out is not None:
            page_table_regions = [
                block.bbox for block in page_blocks if block.block_type == "table"
            ]
            page_table_regions.extend(page_sample_regions)
            if page_table_regions:
                table_regions_out[page_index] = list(
                    dict.fromkeys(page_table_regions)
                )

    preserved_union: Dict[int, List[BBox]] = {}
    if compute_preserved:
        for block in blocks:
            if should_preserve_original_block(
                block,
                graphic_regions.get(block.page_index, []),
            ):
                regions = _preserved_block_regions(block)
                preserved_union.setdefault(block.page_index, []).extend(regions)
        for page_index in range(document.page_count):
            page_blocks = [block for block in blocks if block.page_index == page_index]
            preserved_union.setdefault(page_index, []).extend(
                _captioned_composite_figure_regions(
                    page_blocks,
                    graphic_regions.get(page_index, ()),
                )
            )
            preserved_union.setdefault(page_index, []).extend(
                _table_region_bboxes(page_blocks)
            )
            preserved_union.setdefault(page_index, []).extend(
                _vector_table_region_bboxes(document[page_index], page_blocks)
            )
            preserved_union.setdefault(page_index, []).extend(
                _formatted_dataset_example_region_bboxes(
                    document[page_index],
                    page_blocks,
                )
            )
            preserved_union.setdefault(page_index, []).extend(
                rule_bounded_sample_regions.get(page_index, ())
            )
        for page_index, page_algorithm_regions in algorithm_regions.items():
            preserved_union.setdefault(page_index, []).extend(page_algorithm_regions)
        for page_index, page_table_regions in equation_table_regions.items():
            preserved_union.setdefault(page_index, []).extend(page_table_regions)
        for page_index, page_rows in piecewise_equation_regions.items():
            preserved_union.setdefault(page_index, []).extend(page_rows)

        # Mutually overlapping translation candidates would overprint each
        # other's Chinese text; keep their original typesetting and exempt
        # the area from untranslated-English QA. Adding the bboxes to the
        # preserved union both skips them in the unit loop below (via
        # _block_mostly_inside_preserved_regions at ratio 1.0) and keeps the
        # QA layer consistent.
        for page_index in range(document.page_count):
            page_candidates = [
                block
                for block in blocks
                if block.page_index == page_index
                and block.should_translate
                and not should_preserve_original_block(
                    block,
                    graphic_regions.get(page_index, []),
                )
            ]
            flagged = _overlapping_translation_block_bboxes(page_candidates)
            if flagged:
                preserved_union.setdefault(page_index, []).extend(flagged)
            colliding = _candidate_bboxes_colliding_with_preserved(
                page_candidates,
                preserved_union.get(page_index, []),
            )
            if colliding:
                preserved_union.setdefault(page_index, []).extend(colliding)

        for page_index, page_regions in preserved_union.items():
            preserved_union[page_index] = list(dict.fromkeys(page_regions))

    if preserved_regions_out is not None:
        preserved_regions_out.clear()
        for page_index, page_regions in preserved_union.items():
            preserved_regions_out[page_index] = list(page_regions)

    units: List[TranslationUnit] = []
    skipped = 0
    for block in blocks:
        # Use structure-aware classification
        if not block.should_translate:
            skipped += 1
            continue
        if preserve_graphics_text and should_preserve_original_block(
            block,
            graphic_regions.get(block.page_index, []),
        ):
            skipped += 1
            continue
        if (
            block.block_type != "caption"
            and _block_mostly_inside_preserved_regions(
                block,
                piecewise_equation_regions.get(block.page_index, []),
            )
        ):
            skipped += 1
            continue
        # Table cells that escaped structural classification (e.g. header
        # cells merged as body prose) must stay untranslated whenever the
        # verification layer treats their enclosing envelope as preserved;
        # translating them would flag preserved_text_changed later. Captions
        # are exempt: they anchor table envelopes (and often sit inside
        # them), yet must always be translated — QA separately flags any
        # caption left in English.
        if (
            preserve_graphics_text
            and block.block_type != "caption"
            and _block_mostly_inside_preserved_regions(
                block,
                preserved_union.get(block.page_index, []),
            )
        ):
            skipped += 1
            continue
        _detach_terminal_formula_punctuation(block)
        plain = strip_sentinels(block.text)
        formula_prose = _looks_like_translatable_formula_prose_block(block)
        if not is_translatable(plain) and not formula_prose:
            skipped += 1
            continue
        protected, mapping = protect_text(block.text)
        block.preserved_math_placeholders = tuple(
            range(len(SENTINEL_RUN_RE.findall(block.text)))
        )
        block.formula_anchors = _align_formula_anchors(
            block.source_math_bboxes,
            len(block.preserved_math_placeholders),
            block.keepout_bboxes or (),
        )
        if block.formula_anchors and not _uses_fixed_source_math(block):
            keepout_lines = [
                _LineRec(text="", bbox=union_bbox(group), spans=[])
                for group in block.keepout_formula_atom_groups
                if group
                and not any(
                    bbox_intersection_area(union_bbox(group), anchor)
                    / max(1.0, bbox_area(union_bbox(group)))
                    >= 0.9
                    for anchor in block.formula_anchors
                )
            ]
            formula_redacts = [
                trim_redact_bbox_against_formula_lines(anchor, keepout_lines)
                for anchor in block.formula_anchors
            ]
            block.redact_bboxes = list(
                dict.fromkeys(
                    [*(block.redact_bboxes or []), *formula_redacts]
                )
            )
        bare = PLACEHOLDER_RE.sub("", protected)
        if not re.search(r"[A-Za-z]{2,}", bare):
            skipped += 1
            continue
        units.append((block, protected, mapping))
    return units, gutter_rects, skipped


_PIECEWISE_BRANCH_PREFIX_RE = re.compile(
    r"^(?:if(?:\s|FORMULA)|otherwise\b|else\b|when(?:\s|FORMULA))",
    re.IGNORECASE,
)


def _piecewise_display_equation_regions(
    blocks: Sequence[TextBlock],
    display_equation_regions: Dict[int, List[BBox]],
) -> Dict[int, List[BBox]]:
    """Select formula rows whose natural-language branch labels stay immutable."""
    selected: Dict[int, List[BBox]] = {}
    for block in blocks:
        branch_text = " ".join(
            SENTINEL_RUN_RE.sub(" FORMULA ", block.text).split()
        )
        if not _PIECEWISE_BRANCH_PREFIX_RE.match(branch_text):
            continue
        block_area = max(bbox_area(block.bbox), 0.1)
        for region in display_equation_regions.get(block.page_index, ()):
            coverage = bbox_intersection_area(block.bbox, region) / block_area
            vertical_gap = max(
                block.bbox[1] - region[3],
                region[1] - block.bbox[3],
                0.0,
            )
            horizontal_overlap = max(
                min(block.bbox[2], region[2]) - max(block.bbox[0], region[0]),
                0.0,
            )
            detached_short_branch = (
                coverage < 0.65
                and vertical_gap <= 2.5
                and horizontal_overlap / max(block.bbox[2] - block.bbox[0], 0.1)
                >= 0.8
                and block.source_lines <= 1
                and substantial_prose_word_count(branch_text) <= 4
            )
            if coverage < 0.65 and not detached_short_branch:
                continue
            block.block_type = "equation"
            block.should_translate = False
            block.preserve_position = True
            block.no_merge = True
            block.nowrap = True
            selected.setdefault(block.page_index, []).append(region)
            break
    return {
        page_index: list(dict.fromkeys(page_regions))
        for page_index, page_regions in selected.items()
    }


def _repeated_top_header_texts(
    blocks: Sequence[TextBlock],
    page_count: int,
) -> set[str]:
    """Return normalized top-band labels repeated across most document pages."""
    pages_by_text: Dict[str, set[int]] = {}
    for block in blocks:
        if block.bbox[3] > 72.0:
            continue
        plain = " ".join(strip_sentinels(block.text).split()).strip()
        if len(_PROSE_WORD_RE.findall(plain)) < 3 or len(plain) > 180:
            continue
        normalized = re.sub(r"\s+\d{1,4}\s*$", "", plain).casefold()
        pages_by_text.setdefault(normalized, set()).add(block.page_index)
    threshold = max(2, (page_count + 1) // 2)
    return {
        text for text, pages in pages_by_text.items() if len(pages) >= threshold
    }


def _normalized_running_header_text(text: str) -> str:
    return re.sub(
        r"\s+\d{1,4}\s*$",
        "",
        " ".join(strip_sentinels(text).split()),
    ).casefold()


def _align_formula_anchors(
    source_math_bboxes: Sequence[BBox],
    placeholder_count: int,
    related_bboxes: Sequence[BBox] = (),
) -> Tuple[BBox, ...]:
    """Align source math runs with sentinel placeholders in reading order."""
    if placeholder_count <= 0 or len(source_math_bboxes) < placeholder_count:
        return ()
    aligned = list(source_math_bboxes)
    while len(aligned) > placeholder_count:
        merge_candidates = [
            (
                _formula_anchor_merge_cost(aligned[index], aligned[index + 1]),
                index,
            )
            for index in range(len(aligned) - 1)
            if _formula_markers_form_atom(aligned[index], aligned[index + 1], "")
        ]
        if not merge_candidates:
            return ()
        _, merge_index = min(merge_candidates)
        aligned[merge_index : merge_index + 2] = [
            union_bbox(aligned[merge_index : merge_index + 2])
        ]
    anchors: List[BBox] = []
    for source_bbox in aligned:
        anchor = source_bbox
        source_area = max(1.0, bbox_area(source_bbox))
        for related in related_bboxes:
            related_area = max(1.0, bbox_area(related))
            if related_area > source_area * 0.7:
                continue
            anchor_height = max(1.0, anchor[3] - anchor[1])
            related_height = max(1.0, related[3] - related[1])
            vertical_extension = max(
                anchor[1] - related[1],
                related[3] - anchor[3],
                0.0,
            )
            center_offset = abs(
                (related[1] + related[3]) / 2.0
                - (anchor[1] + anchor[3]) / 2.0
            )
            different_physical_row = bool(
                vertical_extension > max(2.5, anchor_height * 0.3)
                and center_offset
                > max(2.0, min(anchor_height, related_height) * 0.35)
            )
            overlap_ratio = bbox_intersection_area(anchor, related) / related_area
            adjacent_leading_operator = bool(
                related[2] <= anchor[0] + 0.8
                and -0.8 <= anchor[0] - related[2] <= 1.8
                and related[2] - related[0]
                <= max(12.0, (related[3] - related[1]) * 1.2)
                and min(anchor[3], related[3]) - max(anchor[1], related[1])
                >= min(anchor[3] - anchor[1], related[3] - related[1]) * 0.25
                and center_offset <= max(8.0, anchor_height * 0.7)
            )
            if (
                (not different_physical_row and overlap_ratio >= 0.35)
                or adjacent_leading_operator
            ):
                anchor = union_bbox([anchor, related])
        anchors.append(anchor)
    return tuple(anchors)


def _attach_blank_completion_rule_vectors(
    page: object,
    blocks: Sequence[TextBlock],
) -> None:
    """Join a blank underline vector to its trailing arrow formula sprite."""
    rules: List[BBox] = []
    for drawing in _page_drawings(page):
        rect = drawing.get("rect")
        if rect is None:
            continue
        bbox = (
            float(rect.x0),
            float(rect.y0),
            float(rect.x1),
            float(rect.y1),
        )
        width = bbox[2] - bbox[0]
        height = bbox[3] - bbox[1]
        if 8.0 <= width <= 80.0 and height <= 1.5:
            rules.append(bbox)
    if not rules:
        return

    for block in blocks:
        runs = list(block.source_math_bboxes)
        if not runs:
            continue
        _, mapping = protect_text(block.text)
        formula_texts = list(mapping.values())
        if len(formula_texts) != len(runs):
            continue
        atom_groups = [list(group) for group in block.source_math_atom_groups]
        while len(atom_groups) < len(runs):
            atom_groups.append([])
        atoms = list(block.source_math_atom_bboxes)
        redacts = list(block.redact_bboxes or [])
        changed = False
        for index, (formula_text, run) in enumerate(zip(formula_texts, runs)):
            compact = "".join(formula_text.split())
            if not re.fullmatch(r"(?:[._…·•—-]*)?(?:→|⇒|->)", compact):
                continue
            candidates = [
                rule
                for rule in rules
                if abs(rule[2] - run[0]) <= 1.5
                and run[1] - 1.0 <= (rule[1] + rule[3]) / 2.0 <= run[3] + 1.0
            ]
            if not candidates:
                continue
            rule = min(
                candidates,
                key=lambda candidate: (
                    abs(candidate[2] - run[0]),
                    abs((candidate[1] + candidate[3]) / 2.0 - run[3]),
                ),
            )
            center_y = (rule[1] + rule[3]) / 2.0
            vector_atom = (rule[0], center_y - 0.5, rule[2], center_y + 0.5)
            runs[index] = union_bbox([run, vector_atom])
            atom_groups[index] = list(
                dict.fromkeys([*atom_groups[index], vector_atom])
            )
            atoms = list(dict.fromkeys([*atoms, vector_atom]))
            redacts = list(dict.fromkeys([*redacts, vector_atom]))
            changed = True
        if changed:
            block.source_math_bboxes = tuple(runs)
            block.source_math_atom_groups = tuple(
                tuple(group) for group in atom_groups
            )
            block.source_math_atom_bboxes = tuple(atoms)
            block.redact_bboxes = redacts


def _attach_inline_formula_rule_vectors(
    page: object,
    blocks: Sequence[TextBlock],
) -> None:
    """Give movable formulas ownership of nearby fraction and radical rules."""
    rules: List[BBox] = []
    for drawing in _page_drawings(page):
        rect = drawing.get("rect")
        if rect is None:
            continue
        bbox = (
            float(rect.x0),
            float(rect.y0),
            float(rect.x1),
            float(rect.y1),
        )
        width = bbox[2] - bbox[0]
        height = bbox[3] - bbox[1]
        if 8.0 <= width <= 180.0 and height <= 1.5:
            rules.append(bbox)
    if not rules:
        return
    radical_ink_bboxes = _cmex_radical_ink_bboxes(page)

    for block in blocks:
        if not block.flow_inline_math or not block.source_math_atom_groups:
            continue
        block_width = max(1.0, block.bbox[2] - block.bbox[0])
        groups = [list(group) for group in block.source_math_atom_groups]
        runs = list(block.source_math_bboxes)
        atoms = list(block.source_math_atom_bboxes)
        redacts = list(block.redact_bboxes or [])
        changed = False
        for rule in rules:
            rule_width = rule[2] - rule[0]
            if rule_width > block_width * 0.75:
                continue
            center_y = (rule[1] + rule[3]) / 2.0
            vector_atom = (rule[0], center_y - 0.5, rule[2], center_y + 0.5)
            candidates: List[Tuple[int, float, float]] = []
            for index, group in enumerate(groups):
                if not group:
                    continue
                hull = union_bbox(group)
                radical_edge = abs(rule[0] - hull[2]) <= 1.5 and (
                    hull[1] - 2.0 <= center_y <= hull[3] + 2.0
                )
                horizontal_overlap = max(
                    0.0,
                    min(rule[2], hull[2]) - max(rule[0], hull[0]),
                )
                contained_rule = bool(
                    horizontal_overlap / max(rule_width, 0.1) >= 0.65
                    and hull[1] - 2.0 <= center_y <= hull[3] + 2.0
                )
                if radical_edge or contained_rule:
                    candidates.append(
                        (
                            index,
                            1.0 if radical_edge else 0.0,
                            horizontal_overlap / max(rule_width, 0.1),
                        )
                    )
            if not candidates:
                continue
            selected = max(candidates, key=lambda item: (item[1], item[2]))
            group_index = selected[0]
            if selected[1] > 0.0:
                for atom_index, atom in enumerate(groups[group_index]):
                    expanded = next(
                        (
                            expanded_bbox
                            for normalized_bbox, expanded_bbox in radical_ink_bboxes
                            if atom == normalized_bbox
                        ),
                        None,
                    )
                    if expanded is None:
                        continue
                    groups[group_index][atom_index] = expanded
                    atoms = [expanded if item == atom else item for item in atoms]
                    redacts = [expanded if item == atom else item for item in redacts]
            groups[group_index] = list(
                dict.fromkeys([*groups[group_index], vector_atom])
            )
            if group_index < len(runs):
                runs[group_index] = union_bbox(groups[group_index])
            atoms = list(dict.fromkeys([*atoms, vector_atom]))
            redacts = list(dict.fromkeys([*redacts, vector_atom]))
            changed = True
        if changed:
            block.source_math_atom_groups = tuple(tuple(group) for group in groups)
            block.source_math_bboxes = tuple(runs)
            block.source_math_atom_bboxes = tuple(atoms)
            block.redact_bboxes = redacts


def _cmex_radical_ink_bboxes(page: object) -> List[Tuple[BBox, BBox]]:
    """Return post-segmentation ink bounds for tall Computer Modern roots."""
    get_text = getattr(page, "get_text", None)
    if not callable(get_text):
        return []
    try:
        raw_blocks = get_text("dict").get("blocks", [])
    except Exception:
        return []
    radicals: List[Tuple[BBox, BBox]] = []
    for raw_block in raw_blocks:
        for line in raw_block.get("lines", []):
            for span in line.get("spans", []):
                if (
                    "CMEX" not in str(span.get("font", "")).upper()
                    or normalize_span_text(span.get("text", "")).strip() != "q"
                    or len(span.get("bbox", ())) != 4
                    or len(span.get("origin", ())) < 2
                ):
                    continue
                size = float(span.get("size", 0.0))
                if size <= 0.0:
                    continue
                normalized_span = _normalized_extracted_math_span(span)
                normalized_bbox = tuple(
                    float(value) for value in normalized_span["bbox"]
                )
                raw_bbox = tuple(float(value) for value in span["bbox"])
                expanded_y1 = min(
                    raw_bbox[3],
                    float(span["origin"][1]) + size * 1.85,
                )
                if expanded_y1 <= normalized_bbox[3] + size * 0.5:
                    continue
                radicals.append(
                    (
                        normalized_bbox,
                        (
                            normalized_bbox[0],
                            normalized_bbox[1],
                            normalized_bbox[2],
                            expanded_y1,
                        ),
                    )
                )
    return radicals


def _erase_reflowed_formula_vector_decorations(
    page: object,
    blocks: Sequence[TextBlock],
) -> int:
    """Cover source vector atoms that are repainted inside movable formulas."""
    try:
        import fitz
    except ImportError:
        return 0
    vector_atoms = list(
        dict.fromkeys(
            atom
            for block in blocks
            if not _uses_fixed_source_math(block)
            for atom in block.source_math_atom_bboxes
            if atom[2] - atom[0] >= 8.0 and atom[3] - atom[1] <= 2.0
        )
    )
    if not vector_atoms:
        return 0
    background = render_background(page)
    for atom in vector_atoms:
        fill = sample_background_color(background, atom, 1.8) or (1.0, 1.0, 1.0)
        rect = fitz.Rect(
            atom[0] - 0.4,
            atom[1] - 0.8,
            atom[2] + 0.4,
            atom[3] + 0.8,
        )
        page.draw_rect(rect, color=fill, fill=fill, width=0, overlay=True)
    return len(vector_atoms)


def _formula_anchor_merge_cost(first: BBox, second: BBox) -> float:
    first_center_y = (first[1] + first[3]) / 2.0
    second_center_y = (second[1] + second[3]) / 2.0
    same_line = bbox_share_y_band(first, second)
    horizontal_gap = max(0.0, second[0] - first[2])
    return horizontal_gap + abs(second_center_y - first_center_y) + (0.0 if same_line else 500.0)


_REFERENCES_HEADING_RE = re.compile(
    r"^(?:references(?:\s+and\s+notes)?|bibliography|参考文献)$",
    re.IGNORECASE,
)
_APPENDIX_HEADING_RE = re.compile(r"^(?:appendix\b|appendix[A-Z0-9])", re.IGNORECASE)
_APPENDIX_LETTER_HEADING_RE = re.compile(r"^[A-Z]\.?\s+(.+)$")
_POST_BIBLIOGRAPHY_SECTION_RE = re.compile(
    r"^(?:author contributions?|contributor statements?|"
    r"supplementary materials?|additional materials?|"
    r"the [A-Z0-9][A-Z0-9 \-]{1,50} appendix)$",
    re.IGNORECASE,
)
_ROMAN_SECTION_HEADING_RE = re.compile(r"^[IVXLCDM]{1,6}\.\s+(.+)$")


def _looks_like_appendix_heading(text: str, source_lines: int = 1) -> bool:
    compact = " ".join(text.split()).strip()
    if not compact:
        return False
    if _APPENDIX_HEADING_RE.match(compact):
        return True
    if source_lines > 2 or len(compact) > 80:
        return False
    if _POST_BIBLIOGRAPHY_SECTION_RE.fullmatch(compact):
        return True
    roman_match = _ROMAN_SECTION_HEADING_RE.match(compact)
    if roman_match:
        heading = roman_match.group(1).strip()
        words = _PROSE_WORD_RE.findall(heading)
        if words and len(words) <= 12 and heading.upper() == heading:
            return True
    # Wrapped editor-name fragments inside reference entries ("H. Wallach,")
    # match the "<letter>. <title>" shape; headings never end mid-list.
    if compact.endswith((",", ";")):
        return False
    if _REFERENCE_ENTRY_RE.search(compact) or _looks_like_reference_entry_text(compact):
        return False
    match = _APPENDIX_LETTER_HEADING_RE.match(compact)
    if not match:
        return False
    heading = match.group(1)
    words = _PROSE_WORD_RE.findall(heading)
    if not words or len(words) > 8:
        return False
    if heading.upper() == heading:
        return True
    significant = [
        word
        for word in words
        if word.lower() not in {"a", "an", "and", "for", "in", "of", "on", "the", "to", "with"}
    ]
    if not significant:
        return False
    title_case_words = sum(1 for word in significant if word[0].isupper())
    return title_case_words >= max(1, len(significant) - 1)


def mark_bibliography_blocks(
    blocks: Sequence[TextBlock], page_heights: Optional[Dict[int, float]] = None
) -> List[bool]:
    """Reference entries keep their original (English) typesetting: translated
    bibliographies are non-standard and reflowing them degrades the layout.

    The range starts after a "References" heading and ends at the next bold
    section heading (appendices). Page footers inside the range are exempt so
    they stay translated like on every other page."""
    page_heights = page_heights or {}
    flags: List[bool] = []
    in_references = False
    heading_size = 0.0
    for block in blocks:
        compact = " ".join(strip_sentinels(block.text).split())
        if _REFERENCES_HEADING_RE.match(compact):
            in_references = True
            heading_size = block.font_size
            flags.append(False)  # the heading itself is translated
            continue
        if in_references and _is_structural_bibliography_terminator(
            block,
            compact,
            heading_size,
        ):
            in_references = False
        if in_references and block.bold and block.font_size >= max(heading_size * 0.92, 10.5):
            in_references = False  # next section (appendix) starts
        page_height = page_heights.get(block.page_index, 0.0)
        is_footer = page_height > 0 and block.bbox[1] >= page_height * 0.92
        flags.append(in_references and not is_footer)
    return flags


def collect_graphic_regions(document: object) -> Dict[int, List[BBox]]:
    """Find page regions that contain figures, vector diagrams, tables, or images."""
    regions: Dict[int, List[BBox]] = {}
    for page_index in range(document.page_count):
        page_regions = graphic_regions_for_page(document[page_index])
        if page_regions:
            regions[page_index] = page_regions
    return regions


def graphic_regions_for_page(page: object) -> List[BBox]:
    try:
        import fitz
    except ImportError as exc:
        raise RuntimeError("PyMuPDF is required. Install with: pip install -e .") from exc

    page_rect = page.rect
    image_candidates: List[BBox] = []
    for raw_block in page.get_text("dict").get("blocks", []):
        if raw_block.get("type") == 0 or "bbox" not in raw_block:
            continue
        bbox = tuple(float(value) for value in raw_block["bbox"])
        if bbox_is_graphic_candidate(bbox, page_rect):
            image_candidates.append(bbox)

    drawing_candidates: List[BBox] = []
    for drawing in _page_drawings(page):
        rect = drawing.get("rect")
        if not isinstance(rect, fitz.Rect):
            continue
        bbox = (float(rect.x0), float(rect.y0), float(rect.x1), float(rect.y1))
        if _looks_like_page_background_rule(bbox, page_rect):
            continue
        if bbox_is_graphic_candidate(bbox, page_rect):
            drawing_candidates.append(bbox)

    drawing_candidates = [
        bbox
        for bbox in drawing_candidates
        if not _image_bbox_clipped_by_wide_drawing_band(
            bbox,
            drawing_candidates,
            page_rect,
        )
    ]

    candidates = [
        bbox
        for bbox in image_candidates
        if not _image_bbox_clipped_by_wide_drawing_band(
            bbox,
            drawing_candidates,
            page_rect,
        )
    ]
    candidates.extend(drawing_candidates)

    merged = merge_nearby_bboxes(candidates, GRAPHIC_REGION_CLUSTER_GAP)
    output: List[BBox] = []
    for bbox in merged:
        if bbox_area(bbox) < GRAPHIC_REGION_MIN_AREA:
            continue
        output.append(expand_bbox_to_page(bbox, GRAPHIC_REGION_PADDING, page_rect))
    return output


def _captioned_composite_figure_regions(
    blocks: Sequence[TextBlock],
    graphic_regions: Sequence[BBox],
) -> List[BBox]:
    """Join dense multi-band artwork anchored by one explicit figure caption.

    Full-page annotation guides and UI screenshots can be exported as many
    separately clipped images.  Their text sits in the whitespace between the
    image bands, so preserving each image rectangle independently still
    translates and overlays the artwork's labels.  Five tightly stacked bands
    plus a nearby Figure caption is deliberately strict enough to distinguish
    this shape from ordinary pages containing several independent figures.
    """
    figure_captions = sorted(
        (
            block
            for block in blocks
            if block.block_type == "caption"
            and re.match(r"^\s*(?:figure|fig\.)\s*\d+", strip_sentinels(block.text), re.I)
        ),
        key=lambda block: block.bbox[1],
    )
    if not figure_captions or len(graphic_regions) < 5:
        return []

    output: List[BBox] = []
    previous_caption_bottom = 0.0
    for caption in figure_captions:
        candidates = sorted(
            (
                region
                for region in graphic_regions
                if region[1] >= previous_caption_bottom - 1.0
                and region[3] <= caption.bbox[1] + 1.0
            ),
            key=lambda region: (region[1], region[0]),
        )
        previous_caption_bottom = max(previous_caption_bottom, caption.bbox[3])
        if len(candidates) < 5:
            continue

        # Work backwards from the graphic band nearest the caption. A distant
        # earlier illustration must not be pulled into this figure envelope.
        group = [candidates[-1]]
        for region in reversed(candidates[:-1]):
            vertical_gap = group[-1][1] - region[3]
            if vertical_gap > 42.0:
                break
            group.append(region)
        group.reverse()
        if len(group) < 5:
            continue
        envelope = union_bbox(group)
        caption_gap = caption.bbox[1] - envelope[3]
        caption_width = max(1.0, caption.bbox[2] - caption.bbox[0])
        if not (0.0 <= caption_gap <= 60.0):
            continue
        if envelope[2] - envelope[0] < caption_width * 0.72:
            continue
        output.append(envelope)
    return output


def _image_bbox_clipped_by_wide_drawing_band(
    image_bbox: BBox,
    drawing_bboxes: Sequence[BBox],
    page_rect: object,
) -> bool:
    """Ignore an image's un-clipped sprite bbox when a drawing gives its band.

    Some TeX figures place the same tall sprite repeatedly under a short clip
    path. PyMuPDF reports the full transformed image bbox, which can cover
    nearby prose, while a wide drawing rectangle still records the visible
    figure band. In that shape the drawing is the reliable region envelope.
    """
    image_width = image_bbox[2] - image_bbox[0]
    image_height = image_bbox[3] - image_bbox[1]
    page_width = max(float(page_rect.width), 1.0)
    for drawing_bbox in drawing_bboxes:
        drawing_width = drawing_bbox[2] - drawing_bbox[0]
        drawing_height = drawing_bbox[3] - drawing_bbox[1]
        if drawing_width < max(page_width * 0.30, image_width * 2.0):
            continue
        if drawing_height > image_height * 0.75:
            continue
        if bbox_intersection_area(image_bbox, drawing_bbox) > 4.0:
            return True
    return False


def bbox_is_graphic_candidate(bbox: BBox, page_rect: object) -> bool:
    page_width = float(page_rect.width)
    page_height = float(page_rect.height)
    if bbox[2] <= 0 or bbox[0] >= page_width or bbox[3] <= 0 or bbox[1] >= page_height:
        return False
    width = bbox[2] - bbox[0]
    height = bbox[3] - bbox[1]
    if width < GRAPHIC_REGION_MIN_SIDE or height < GRAPHIC_REGION_MIN_SIDE:
        return False
    if bbox_area(bbox) < GRAPHIC_REGION_MIN_AREA:
        return False
    page_area = max(page_width * page_height, 1.0)
    return bbox_area(bbox) <= page_area * 0.85


def _looks_like_page_background_rule(bbox: BBox, page_rect: object) -> bool:
    page_width = max(float(page_rect.width), 1.0)
    page_height = max(float(page_rect.height), 1.0)
    width = bbox[2] - bbox[0]
    height = bbox[3] - bbox[1]
    return (
        width >= page_width * 0.90
        and height <= max(14.0, page_height * 0.025)
        and (bbox[0] <= page_width * 0.02 or bbox[2] >= page_width * 0.98)
    )


def merge_nearby_bboxes(bboxes: Sequence[BBox], gap: float) -> List[BBox]:
    merged = list(bboxes)
    changed = True
    while changed:
        changed = False
        next_round: List[BBox] = []
        while merged:
            current = merged.pop(0)
            index = 0
            while index < len(merged):
                if bboxes_intersect(expand_bbox(current, gap), merged[index]):
                    current = union_bbox([current, merged.pop(index)])
                    changed = True
                else:
                    index += 1
            next_round.append(current)
        merged = next_round
    return merged


def should_preserve_original_block(block: TextBlock, graphic_regions: Sequence[BBox]) -> bool:
    """Conservative-mode filter: keep figure/table internals and formulas untouched."""
    plain = " ".join(strip_sentinels(block.text).split())
    if not plain:
        return True
    if block.block_type in (
        "algorithm",
        "bibliography",
        "equation",
        "figure_label",
        "footer",
        "metadata",
        "table",
    ):
        return True
    if looks_like_author_metadata(block, plain):
        return True
    if looks_like_vertical_margin_metadata(block, plain):
        return True
    if block.block_type == "caption" or _CAPTION_RE.match(plain):
        return False
    if block.block_type == "heading":
        return False
    if block.block_type == "table" and block.nowrap and block.no_merge:
        return True
    if (
        block.block_type == "formula_prose"
        and block.no_merge
        and re.match(
            r"^(?:If|Let|Suppose|Assume|Given|For\s+(?:all|any|each))\b",
            plain,
            re.IGNORECASE,
        )
        and _looks_like_translatable_formula_prose_block(block)
    ):
        return False
    if looks_like_action_skeleton_sequence(plain):
        return True
    if looks_like_preserved_diagram_label(plain):
        return True
    if _looks_like_translatable_formula_prose_block(block):
        return False
    if _is_low_font_graphic_content(block, graphic_regions):
        return True
    if looks_like_translatable_graphic_prose(block, plain):
        return False
    if _looks_like_prose_grazing_graphic_padding(block, plain, graphic_regions):
        return False
    if block_overlaps_graphic_region(block.bbox, graphic_regions):
        return True
    if math_heavy_block(block):
        return True
    return False


def _looks_like_translatable_formula_prose_block(block: TextBlock) -> bool:
    # Structural classification may relabel formula_prose as body, so retain
    # the extraction marker through its no-merge flag and formula anchors.
    outside = " ".join(SENTINEL_RUN_RE.sub(" ", block.text).split())
    if not block.source_math_bboxes:
        return False
    if _ACADEMIC_FORMULA_STATEMENT_RE.match(outside):
        # TeX often cuts ``Lemma 10.4. Let <formula>`` into a short body
        # fragment. It has too few ordinary words for the generic prose gate,
        # but leaving it untouched creates a conspicuous English theorem lead.
        return True
    if not block.no_merge:
        return False
    prose_words = [
        word
        for word in re.findall(r"[A-Za-z]{2,}", outside)
        if word.lower() not in _MATH_WORDS | _SHORT_PROSE_WORDS
    ]
    if (
        block.block_type == "formula_prose"
        and prose_words
        and re.match(
            r"^\s*[.,;:]?\s*(?:for|let|suppose|assume|if|when|where|such\s+that)\b",
            outside,
            re.IGNORECASE,
        )
    ):
        return True
    if block.block_type == "formula_prose" and len(prose_words) >= 4:
        # Extraction has already isolated a natural-language explanation and
        # supplied formula keepouts. Do not require it to begin with a narrow
        # cue such as "where"; run-in comparisons such as "AdaGrad
        # corresponds ..." are equally translatable.
        return True
    cue = _FORMULA_PROSE_SUFFIX_CUE_RE.search(outside)
    leading_explanation = re.match(
        r"^\s*(?:knowing|given|using|letting|assuming|supposing)\b",
        outside,
        re.IGNORECASE,
    )
    if cue is None and leading_explanation is None:
        return False
    cue_word = re.search(r"[A-Za-z]+", (cue or leading_explanation).group(0))
    cue_name = cue_word.group(0).lower() if cue_word else ""
    if cue_name == "where":
        explains_formula = bool(
            re.search(r"\b(?:is|are|denotes?|represents?)\b", outside, re.IGNORECASE)
            and len(prose_words) >= 2
        )
        chained_definition = " and " in f" {outside.lower()} " and len(
            block.source_math_bboxes
        ) >= 2
        return explains_formula or chained_definition
    return len(prose_words) >= 3


def _is_low_font_graphic_content(
    block: TextBlock,
    graphic_regions: Sequence[BBox],
) -> bool:
    """Keep low-point text whose center is physically inside a figure.

    Diagram prompts and response examples can look like prose, but translating
    them overlays the raster/vector artwork. Captions and headings have already
    been handled before this predicate.
    """
    if block.font_size > DIAGRAM_INTERNAL_MAX_FONT_SIZE:
        return False
    center_x = (block.bbox[0] + block.bbox[2]) / 2.0
    center_y = (block.bbox[1] + block.bbox[3]) / 2.0
    return any(
        bbox_contains_point(region, center_x, center_y)
        for region in graphic_regions
    )


def _looks_like_prose_grazing_graphic_padding(
    block: TextBlock,
    plain: str,
    graphic_regions: Sequence[BBox],
) -> bool:
    """Keep a wide prose line translatable when only float padding touches it."""
    width = max(1.0, block.bbox[2] - block.bbox[0])
    height = max(1.0, block.bbox[3] - block.bbox[1])
    if (
        block.source_lines != 1
        or block.nowrap
        or block.font_size <= DIAGRAM_INTERNAL_MAX_FONT_SIZE
        or width < max(220.0, block.font_size * 22.0)
        or substantial_prose_word_count(plain) < 10
        or _looks_like_code_or_symbolic_text(plain)
        or looks_like_preserved_diagram_label(plain)
    ):
        return False

    center_x = (block.bbox[0] + block.bbox[2]) / 2.0
    center_y = (block.bbox[1] + block.bbox[3]) / 2.0
    touched = False
    for region in graphic_regions:
        intersection = bbox_intersection_area(block.bbox, region)
        if intersection <= 0.0:
            continue
        touched = True
        vertical_overlap = min(block.bbox[3], region[3]) - max(
            block.bbox[1], region[1]
        )
        crosses_vertical_edge = (
            block.bbox[1] < region[1] < block.bbox[3]
            or block.bbox[1] < region[3] < block.bbox[3]
        )
        edge_grazing = crosses_vertical_edge and vertical_overlap <= height * 0.60
        if bbox_contains_point(region, center_x, center_y) and not edge_grazing:
            return False
        horizontal_overlap = min(block.bbox[2], region[2]) - max(
            block.bbox[0], region[0]
        )
        if (
            horizontal_overlap < width * 0.75
            or vertical_overlap > height * 0.60
        ):
            return False
    return touched


def looks_like_author_metadata(block: TextBlock, plain: str) -> bool:
    """First-page bylines and anonymous-review metadata are not prose.

    Translating them creates dense overlapping name strings because author
    lines are often set as many small superscript fragments in one narrow band.
    """
    if block.page_index != 0:
        return False
    x0, y0, x1, y1 = block.bbox
    width = x1 - x0
    height = y1 - y0
    if y0 > 240.0 or width < 120.0 or height > 170.0:
        return False
    compact = " ".join(plain.split())
    lower = compact.lower()
    name_pairs = re.findall(
        r"\b[A-Z][a-z]+(?:[- ][A-Z][a-z]+)?\s+[A-Z][A-Za-z-]+(?:\^\{\d+\})?",
        compact,
    )
    if height > 90.0:
        # Tall blocks are usually the abstract; only industry-style author
        # walls qualify: rows of capitalized name pairs with almost no
        # lowercase sentence words.
        lowercase_words = [
            word
            for word in re.findall(r"\b[a-z]{3,}\b", compact)
            if not re.match(r"^https?", word)
        ]
        return len(name_pairs) >= 12 and len(lowercase_words) <= max(
            3, len(name_pairs) // 6
        )
    if re.search(r"\bauthor\s+names?\s+omitted\b|\banonymous\s+review\b|\bpaper-?\s*id\b", lower):
        return True
    affiliation_cue = re.search(
        r"\b(university|institute|department|school|college|laboratory|"
        r"hong kong|tsinghua|zhejiang|equal contribution|corresponding author)\b",
        lower,
    )
    if affiliation_cue and len(name_pairs) >= 2:
        return True
    return len(name_pairs) >= 5 and y0 < 190.0


def looks_like_preserved_diagram_label(plain: str) -> bool:
    """Short labels inside architecture figures stay in their original language.

    Captions still translate; this only covers diagram-internal labels such as
    "(i) Object Head (ii) Skill Head (iii) Depth Head".
    """
    compact = " ".join(strip_sentinels(plain).split()).strip()
    if not compact or len(compact) > 120:
        return False
    if _CAPTION_RE.match(compact):
        return False
    if re.search(r"[.!?:。！？：]$", compact):
        return False
    without_markers = re.sub(r"\(?[ivx]{1,4}\)\s*", " ", compact, flags=re.IGNORECASE)
    without_markers = re.sub(
        rf"\b(Head)(?={_DIAGRAM_HEAD_LABEL_WORDS}\s+Head\b)",
        r"\1 ",
        without_markers,
        flags=re.IGNORECASE,
    )
    normalized = " ".join(without_markers.split())
    if re.fullmatch(
        rf"(?:(?:{_DIAGRAM_HEAD_LABEL_WORDS})\s+Head\s*){{1,4}}",
        normalized,
        re.IGNORECASE,
    ):
        return True
    if re.fullmatch(
        rf"(?:(?:{_DIAGRAM_MEMORY_LABEL_WORDS})\s+Memory\s*){{1,5}}",
        normalized,
        re.IGNORECASE,
    ):
        return True
    if re.fullmatch(
        r"(?:(?:Action|Video|World|Policy|Vision|Language)\s+Expert\s*){1,4}",
        normalized,
        re.IGNORECASE,
    ):
        return True
    return False


def looks_like_parallel_figure_label_row(block: TextBlock, plain: str) -> bool:
    """Detect separate figure labels extracted as one same-baseline block."""
    line_bboxes = tuple(block.source_line_bboxes)
    if block.source_lines < 3 or len(line_bboxes) < 3:
        return False
    if block.bbox[3] - block.bbox[1] > max(18.0, block.font_size * 1.8):
        return False
    compact = " ".join(strip_sentinels(plain).split()).strip()
    if not compact or re.search(r"[.!?;:。！？；：]", compact):
        return False
    words = _PROSE_WORD_RE.findall(compact)
    if len(words) < len(line_bboxes) or len(words) > len(line_bboxes) * 4:
        return False
    centers = [(bbox[1] + bbox[3]) / 2.0 for bbox in line_bboxes]
    if max(centers) - min(centers) > max(1.5, block.font_size * 0.25):
        return False
    ordered = sorted(line_bboxes, key=lambda bbox: bbox[0])
    return all(
        right[0] - left[2] >= max(10.0, block.font_size)
        for left, right in zip(ordered, ordered[1:])
    )


def looks_like_action_skeleton_sequence(plain: str) -> bool:
    """Function-call action chains are pseudocode, not translatable prose."""
    compact = " ".join(strip_sentinels(plain).split()).strip()
    call_pattern = r"[A-Za-z][A-Za-z0-9_-]*\s*\([^()]{0,100}\)"
    if re.fullmatch(call_pattern, compact):
        return True
    if (
        len(compact) > 500
        or substantial_prose_word_count(compact) > 30
        or len(re.findall(r"[.!?](?:\s|$)", compact)) > 1
    ):
        return False
    calls = re.findall(rf"\b{call_pattern}", compact)
    arrows = re.findall(r"(?:→|⇒|->)", compact)
    return len(calls) >= 2 and bool(arrows)


def looks_like_vertical_margin_metadata(block: TextBlock, plain: str) -> bool:
    width = block.bbox[2] - block.bbox[0]
    height = block.bbox[3] - block.bbox[1]
    if width > 45.0 or height < 80.0:
        return False
    compact = " ".join(plain.split())
    return bool(re.search(r"\barxiv\b|\[[a-z]{2}\.[a-z]{2}\]", compact, re.IGNORECASE))


def looks_like_translatable_graphic_prose(block: TextBlock, plain: str) -> bool:
    outside_math = " ".join(_text_outside_sentinels(block.text).split())
    prose_words = substantial_prose_word_count(outside_math or plain)
    if block.block_type in {"heading", "run_in_heading"} and prose_words >= 2:
        return True
    if (
        prose_words >= 2
        and (
            re.match(r"^\s*[•—–-]", plain)
            or plain.rstrip().endswith(":")
            or re.search(
                r"\b(?:Prompt|Annotation)\s+Template\s*$",
                plain,
                re.IGNORECASE,
            )
        )
        and not _looks_like_code_or_symbolic_text(plain)
    ):
        return True
    if re.match(r"^\(\d{1,2}\)\s+[A-Z]", plain) and prose_words >= 3:
        return True
    if (
        sentinel_char_count(block.text)
        and prose_words >= 3
        and re.search(
            r"\b(?:is|are|was|were|be|gives?|receives?|closer|than|that|where|"
            r"when|with|from|into|to)\b",
            outside_math,
            re.IGNORECASE,
        )
    ):
        return True
    if block.nowrap:
        return False
    if _ACADEMIC_BOX_PROSE_RE.match(plain):
        return True
    if _ENUMERATED_ACADEMIC_BOX_RE.match(plain):
        return True
    if block.source_lines < 2:
        return False
    if prose_words < 8:
        return False
    if prose_words >= 20:
        return True
    if _looks_like_code_or_symbolic_text(plain):
        return False
    return True


def block_overlaps_graphic_region(bbox: BBox, regions: Sequence[BBox]) -> bool:
    area = max(bbox_area(bbox), 1.0)
    center_x = (bbox[0] + bbox[2]) / 2.0
    center_y = (bbox[1] + bbox[3]) / 2.0
    for region in regions:
        if bbox_contains_point(region, center_x, center_y):
            return True
        if bbox_intersection_area(bbox, region) / area >= GRAPHIC_BLOCK_OVERLAP_RATIO:
            return True
    return False


def bbox_crosses_graphic_region(bbox: BBox, regions: Sequence[BBox]) -> bool:
    return any(bboxes_intersect(bbox, region) for region in regions)


def math_heavy_block(block: TextBlock) -> bool:
    bare = strip_sentinels(block.text)
    compact = "".join(bare.split())
    if not compact:
        return False
    if substantial_prose_word_count(bare) >= 5:
        return False
    if looks_like_math(bare):
        return True
    math_chars = sentinel_char_count(block.text)
    if not math_chars:
        return False
    ratio = math_chars / len(compact)
    if ratio >= MATH_HEAVY_RATIO:
        return True
    return block.source_lines <= 2 and ratio >= MATH_SHORT_BLOCK_RATIO


def short_graphic_label_block(block: TextBlock, plain: str) -> bool:
    words = _PROSE_WORD_RE.findall(plain)
    return (
        block.font_size <= 8.5
        and block.source_lines <= 2
        and len(plain) <= 80
        and len(words) <= 6
    )


def substantial_prose_word_count(text: str) -> int:
    return sum(
        1 for word in _PROSE_WORD_RE.findall(text) if word.lower() not in _MATH_WORDS
    )


def _bottom_caption_algorithm_regions(
    records: Sequence[_RawBlockRec],
) -> List[BBox]:
    """Recover algorithm floats whose ``Algorithm N`` caption is below the box."""
    regions: List[BBox] = []
    for title_index, title_record in enumerate(records):
        title_plain = " ".join(strip_sentinels(title_record.bare_text()).split())
        if not _ALGORITHM_TITLE_RE.match(title_plain):
            continue
        title = title_record.bbox
        cursor_top = title[1]
        payload: List[_RawBlockRec] = []
        for candidate in reversed(records[:title_index]):
            bbox = candidate.bbox
            overlap = min(title[2], bbox[2]) - max(title[0], bbox[0])
            narrower = min(title[2] - title[0], bbox[2] - bbox[0])
            if narrower <= 0.0 or overlap / narrower < 0.45:
                continue
            gap = cursor_top - bbox[3]
            if gap > 30.0:
                break
            if bbox[1] >= cursor_top + 2.0:
                continue

            plain = " ".join(strip_sentinels(candidate.bare_text()).split())
            algorithm_cue = bool(
                record_is_algorithm(candidate)
                or _ALGORITHM_IO_RE.search(plain)
                or re.match(r"^\d+\s*:", plain)
                or "//" in plain
            )
            formula_cue = any(
                line.math_bboxes or sentinel_char_count(line.text)
                for line in candidate.lines
            )
            prose_words = substantial_prose_word_count(plain)
            natural_language_boundary = bool(
                not algorithm_cue
                and prose_words >= (6 if not payload else 10)
            )
            if natural_language_boundary:
                break
            if not payload and not (algorithm_cue or formula_cue):
                break
            payload.append(candidate)
            cursor_top = min(cursor_top, bbox[1])

        if not payload:
            continue
        if not any(
            record_is_algorithm(candidate)
            or _ALGORITHM_IO_RE.search(
                " ".join(strip_sentinels(candidate.bare_text()).split())
            )
            or re.match(
                r"^\d+\s*:",
                " ".join(strip_sentinels(candidate.bare_text()).split()),
            )
            or "//" in strip_sentinels(candidate.bare_text())
            for candidate in payload
        ):
            continue
        region_records = [*payload, title_record]
        region = union_bbox(record.bbox for record in region_records)
        if title[1] - region[1] < 24.0:
            continue
        regions.append(region)
    return regions


def algorithm_regions_for_page(
    page: object, records: Sequence[_RawBlockRec]
) -> List[BBox]:
    """Full algorithm-float regions delimited by their horizontal rules.

    An algorithm float is typeset as: top rule, "Algorithm N ..." title, a
    second rule, the pseudocode body, and a closing rule. The extractor often
    splits the body into several raw blocks ("Sample eps ~ N(0, I)...",
    "end for"); translating any of them corrupts the float, so every block
    inside the ruled region is preserved verbatim.
    """
    title_bboxes = []
    for record in records:
        for line_index, line in enumerate(record.lines):
            if _ALGORITHM_TITLE_RE.match(
                " ".join(strip_sentinels(line.text).split())
            ):
                title_lines = [line.bbox]
                for continuation in record.lines[line_index + 1 :]:
                    compact = " ".join(strip_sentinels(continuation.text).split())
                    if _ALGORITHM_IO_RE.search(compact):
                        break
                    if continuation.bbox[1] - title_lines[-1][3] > 4.0:
                        break
                    title_lines.append(continuation.bbox)
                title_bboxes.append(union_bbox(title_lines))
                break
    regions = _bottom_caption_algorithm_regions(records)
    if not title_bboxes:
        return regions
    drawings = _page_drawings(page)
    if not drawings:
        return regions
    rules: List[BBox] = []
    for drawing in drawings:
        rect = drawing.get("rect")
        if rect is None:
            continue
        if rect.height <= 2.5 and rect.width >= 60:
            rules.append((float(rect.x0), float(rect.y0), float(rect.x1), float(rect.y1)))
    for title in title_bboxes:
        spanning = [
            rule
            for rule in rules
            if rule[0] <= title[0] + 6.0 and rule[2] >= title[2] - 6.0
        ]
        below = sorted(
            (rule for rule in spanning if rule[1] >= title[3] - 1.0),
            key=lambda rule: rule[1],
        )
        if len(below) < 2:
            continue
        first, closing = below[0], below[1]
        if first[1] - title[3] > 8.0:
            continue
        region_x0 = min(title[0], first[0])
        region_x1 = max(title[2], first[2])
        regions.append((region_x0, title[1] - 4.0, region_x1, closing[3] + 2.0))
    return list(dict.fromkeys(regions))


def _record_in_regions(record: _RawBlockRec, regions: Sequence[BBox]) -> bool:
    bbox = record.bbox
    center_x = (bbox[0] + bbox[2]) / 2.0
    center_y = (bbox[1] + bbox[3]) / 2.0
    return any(bbox_contains_point(region, center_x, center_y) for region in regions)


def collect_text_blocks(
    document: object,
    *,
    algorithm_regions_out: Optional[Dict[int, List[BBox]]] = None,
    equation_table_regions_out: Optional[Dict[int, List[BBox]]] = None,
    display_equation_regions_out: Optional[Dict[int, List[BBox]]] = None,
) -> Tuple[List[TextBlock], Dict[int, List[BBox]]]:
    """Extract text blocks and the bboxes of stripped gutter line numbers.

    Display-equation regions (clusters of raw blocks holding big operators,
    sub/superscript lines, equation numbers, ...) are detected geometrically
    and excluded entirely: their original typesetting is preserved.
    """
    blocks: List[TextBlock] = []
    gutter_rects: Dict[int, List[BBox]] = {}
    for page_index in range(document.page_count):
        page = document[page_index]
        page_width = float(page.rect.width)
        page_dict = page.get_text("dict")
        review_line_number_bboxes = _review_line_number_bboxes(page_dict)
        records: List[_RawBlockRec] = []
        for raw_block in page_dict.get("blocks", []):
            if raw_block.get("type") != 0:
                continue
            record, dropped = parse_block_lines(
                raw_block,
                page_width=page_width,
                known_gutter_bboxes=review_line_number_bboxes,
            )
            if dropped:
                gutter_rects.setdefault(page_index, []).extend(dropped)
            if record is not None:
                records.extend(_split_column_straddling_record(record))
        records = _merge_wrapped_formula_continuation_records(records)
        equation_flags = mark_equation_blocks(records)
        algorithm_flags = [record_is_algorithm(record) for record in records]
        if equation_table_regions_out is not None:
            page_table_regions = _equation_table_region_bboxes(records, equation_flags)
            if page_table_regions:
                equation_table_regions_out[page_index] = page_table_regions
        if display_equation_regions_out is not None:
            # Register display-equation ROWS (y-bands holding formula lines)
            # so extraction filtering, reflow avoidance, and QA all share one
            # preserved-region registry instead of each guessing separately.
            # The region spans only the formula lines themselves: a prose line
            # in the same band at a different x (a translatable explanation)
            # stays outside, while a clause wedged BETWEEN formula chunks of
            # the same row ("where U(a,b) = {...}" in MCF eq (1)) is covered
            # by the union and kept with the equation.
            row_regions: List[BBox] = []
            for record, is_equation in zip(records, equation_flags):
                if not is_equation:
                    continue
                if (
                    _equation_flagged_small_caps_heading_block(
                        page_index,
                        record,
                        is_equation,
                    )
                    is not None
                ):
                    continue
                formula_lines_in_record = [
                    line for line in record.lines if not line_is_prose(line)
                ]
                # Only display-equation-DOMINANT records register rows. A
                # prose paragraph carrying inline math (placeholder-kept)
                # would otherwise register its own fragments and get its
                # extracted prose blocks condemned by the collision checks.
                if len(formula_lines_in_record) <= len(record.lines) / 2.0:
                    continue
                for row in group_same_y_lines(record.lines):
                    formula_bboxes = [
                        line.bbox for line in row if not line_is_prose(line)
                    ]
                    if formula_bboxes:
                        row_regions.append(union_bbox(formula_bboxes))
            if row_regions:
                display_equation_regions_out[page_index] = list(dict.fromkeys(row_regions))
        formula_lines = [
            line
            for record, is_equation in zip(records, equation_flags)
            if is_equation
            for line in record.lines
            if not line_is_prose(line)
        ]
        alg_regions = algorithm_regions_for_page(page, records)
        if algorithm_regions_out is not None:
            page_algorithm_regions = list(alg_regions)
            page_algorithm_regions.extend(
                record.bbox
                for record, is_algorithm in zip(records, algorithm_flags)
                if is_algorithm
            )
            if page_algorithm_regions:
                algorithm_regions_out[page_index] = list(
                    dict.fromkeys(page_algorithm_regions)
                )
        for record_index, (record, is_equation, is_algorithm) in enumerate(
            zip(records, equation_flags, algorithm_flags)
        ):
            if is_algorithm:
                continue
            if alg_regions and _record_in_regions(record, alg_regions):
                continue
            record_segments = segments_from_record(
                page_index, record, equation_record=is_equation
            )
            structural_heading = bool(
                record_segments
                and all(segment.block_type == "heading" for segment in record_segments)
            )
            if is_equation and not structural_heading and (
                _inline_formula_record_is_part_of_2d_cluster(
                    records,
                    record_index,
                )
                or _equation_record_is_numbered_formula_row(
                    records,
                    equation_flags,
                    record_index,
                )
            ):
                connector_texts = {
                    " ".join(strip_sentinels(segment.text).split())
                    .casefold()
                    .rstrip(":,")
                    for segment in record_segments
                }
                if not connector_texts or not connector_texts <= {
                    "where",
                    "and",
                    "with",
                }:
                    continue
            if not record_segments:
                formula_bridge = _inline_formula_bridge_block(
                    page_index,
                    records,
                    equation_flags,
                    algorithm_flags,
                    record_index,
                )
                if formula_bridge is not None:
                    record_segments = [formula_bridge]
            for block in record_segments:
                redacts = block.redact_bboxes or [block.bbox]
                trimmed_redacts = (
                    list(redacts)
                    if _formula_prose_uses_atom_restore(block)
                    else [
                        trim_redact_bbox_against_formula_lines(redact, formula_lines)
                        for redact in redacts
                    ]
                )
                if trimmed_redacts != redacts:
                    block.redact_bboxes = trimmed_redacts
            _attach_formula_keepouts(record_segments, formula_lines)
            _trim_redacts_against_block_keepouts(record_segments)
            blocks.extend(record_segments)
    return blocks, gutter_rects


def _merge_wrapped_formula_continuation_records(
    records: Sequence[_RawBlockRec],
) -> List[_RawBlockRec]:
    """Rejoin a prose paragraph split across a stacked inline fraction.

    TeX can close one PDF text object midway through a fraction, then emit its
    denominator and the sentence tail in a second object.  Classifying the
    objects independently preserves both halves as display math and drops the
    surrounding prose.  Only join a long prose-majority record whose final
    line starts an unfinished formula with a compact adjacent record that has
    both a formula tower and a complete natural-language tail.
    """
    output: List[_RawBlockRec] = []
    index = 0
    while index < len(records):
        current = records[index]
        inline_fragment_end = _inline_formula_prose_fragment_sequence_end(
            records,
            index,
        )
        if inline_fragment_end is not None:
            merged_records = records[index : inline_fragment_end + 1]
            output.append(
                _RawBlockRec(
                    lines=_promote_stacked_plain_formula_fragments(
                        [
                            line
                            for record in merged_records
                            for line in record.lines
                        ]
                    ),
                    detached_inline_scripts=True,
                    flow_inline_math=True,
                )
            )
            index = inline_fragment_end + 1
            continue
        flowing_paragraph_end = _flow_inline_math_paragraph_sequence_end(records, index)
        if flowing_paragraph_end is not None:
            merged_records = records[index : flowing_paragraph_end + 1]
            output.append(
                _RawBlockRec(
                    lines=_promote_stacked_plain_formula_fragments(
                        [line for record in merged_records for line in record.lines]
                    ),
                    detached_inline_scripts=True,
                )
            )
            index = flowing_paragraph_end + 1
            continue
        fragmented_formula_end = _fragmented_inline_formula_record_sequence_end(
            records,
            index,
        )
        if fragmented_formula_end is not None:
            merged_records = records[index : fragmented_formula_end + 1]
            output.append(
                _RawBlockRec(
                    lines=_promote_stacked_plain_formula_fragments(
                        [
                            line
                            for record in merged_records
                            for line in record.lines
                        ]
                    ),
                    detached_inline_scripts=True,
                )
            )
            index = fragmented_formula_end + 1
            continue
        stacked_paragraph_end = _stacked_inline_formula_paragraph_end(
            records,
            index,
        )
        if stacked_paragraph_end is not None:
            merged_records = records[index : stacked_paragraph_end + 1]
            output.append(
                _RawBlockRec(
                    lines=_promote_stacked_plain_formula_fragments(
                        [
                            line
                            for record in merged_records
                            for line in record.lines
                        ]
                    ),
                    detached_inline_scripts=True,
                )
            )
            index = stacked_paragraph_end + 1
            continue
        compact_formula_end = _compact_inline_formula_paragraph_end(
            records,
            index,
        )
        if compact_formula_end is not None:
            merged_records = records[index : compact_formula_end + 1]
            output.append(
                _RawBlockRec(
                    lines=_promote_stacked_plain_formula_fragments(
                        [
                            line
                            for record in merged_records
                            for line in record.lines
                        ]
                    ),
                    detached_inline_scripts=True,
                )
            )
            index = compact_formula_end + 1
            continue
        if _records_form_two_record_inline_formula_paragraph(records, index):
            following = records[index + 1]
            output.append(
                _RawBlockRec(
                    lines=_promote_stacked_plain_formula_fragments(
                        [*current.lines, *following.lines]
                    ),
                    detached_inline_scripts=True,
                )
            )
            index += 2
            continue
        if _records_form_inline_formula_tail_sentence(records, index):
            following = records[index + 1]
            output.append(
                _RawBlockRec(
                    lines=_promote_stacked_plain_formula_fragments(
                        [*current.lines, *following.lines]
                    ),
                    detached_inline_scripts=True,
                    flow_inline_math=True,
                )
            )
            index += 2
            continue
        paragraph_end = _inline_fraction_paragraph_before_statement_end(
            records,
            index,
        )
        if paragraph_end is not None:
            merged_records = records[index : paragraph_end + 1]
            output.append(
                _RawBlockRec(
                    lines=_promote_stacked_plain_formula_fragments(
                        [line for record in merged_records for line in record.lines]
                    ),
                    detached_inline_scripts=any(
                        record.detached_inline_scripts for record in merged_records
                    ),
                )
            )
            index = paragraph_end + 1
            continue
        fragmented_end = _fragmented_inline_math_paragraph_end(records, index)
        if fragmented_end is not None:
            merged_records = records[index : fragmented_end + 1]
            output.append(
                _RawBlockRec(
                    lines=_promote_stacked_plain_formula_fragments(
                        [line for record in merged_records for line in record.lines]
                    ),
                    detached_inline_scripts=True,
                )
            )
            index = fragmented_end + 1
            continue
        bridge_end = _formula_bridge_sequence_end(records, index)
        if bridge_end is not None:
            merged_lines = [
                line
                for record in records[index : bridge_end + 1]
                for line in record.lines
            ]
            output.append(
                _RawBlockRec(
                    lines=_promote_stacked_plain_formula_fragments(merged_lines),
                    detached_inline_scripts=True,
                    flow_inline_math=True,
                )
            )
            index = bridge_end + 1
            continue
        following = records[index + 1] if index + 1 < len(records) else None
        if following is not None and _records_form_wrapped_formula_continuation(
            current,
            following,
        ):
            merged_lines = [*current.lines, *following.lines]
            merged_lines = _promote_stacked_plain_formula_fragments(merged_lines)
            output.append(
                _RawBlockRec(
                    lines=merged_lines,
                    detached_inline_scripts=(
                        current.detached_inline_scripts
                        or following.detached_inline_scripts
                    ),
                )
            )
            index += 2
            continue
        output.append(current)
        index += 1
    return output


def _inline_formula_prose_fragment_sequence_end(
    records: Sequence[_RawBlockRec],
    start: int,
) -> Optional[int]:
    """Rejoin prose split across consecutive, touching inline-math objects.

    Some TeX producers emit an inline fraction or large operator as several
    PDF text objects.  The prose lead remains in the first object and the
    grammatical suffix begins in the last one.  Only consume a chain whose
    formula runs touch geometrically, whose continuation objects begin with
    math, and which has no equation number; centered display equations thus
    remain independent.
    """
    if start < 0 or start + 1 >= len(records):
        return None
    first = records[start]
    first_outside = " ".join(
        " ".join(_text_outside_sentinels(line.text).split())
        for line in first.lines
    ).strip()
    short_inline_lead = bool(
        re.fullmatch(
            r"(?:Note|Observe|Recall) that",
            first_outside,
            re.IGNORECASE,
        )
    )
    if (
        len(_prose_words(first_outside)) < (2 if short_inline_lead else 4)
        or sentence_final_text(first.bare_text())
        or not any(line.prose_bboxes for line in first.lines)
        or not any(line.math_run_bboxes for line in first.lines)
        or any(line_looks_like_section_heading(line) for line in first.lines)
        or any(
            EQUATION_NUMBER_RE.fullmatch(
                "".join(strip_sentinels(line.text).split())
            )
            for line in first.lines
        )
    ):
        return None

    previous_math = next(
        (
            bbox
            for line in reversed(first.lines)
            for bbox in reversed(line.math_run_bboxes)
        ),
        None,
    )
    if previous_math is None:
        return None
    trailing_pure_math_lines = 0
    for line in reversed(first.lines):
        if line_is_prose(line):
            break
        trailing_pure_math_lines += 1

    for candidate_index in range(start + 1, min(len(records), start + 5)):
        candidate = records[candidate_index]
        first_math = next(
            (
                bbox
                for line in candidate.lines
                for bbox in line.math_run_bboxes
            ),
            None,
        )
        if (
            first_math is None
            or not candidate.lines
            or not candidate.lines[0].text.lstrip().startswith(SENTINEL_OPEN)
            or any(line_looks_like_section_heading(line) for line in candidate.lines)
            or any(
                EQUATION_NUMBER_RE.fullmatch(
                    "".join(strip_sentinels(line.text).split())
                )
                for line in candidate.lines
            )
        ):
            break

        previous_height = max(1.0, previous_math[3] - previous_math[1])
        candidate_height = max(1.0, first_math[3] - first_math[1])
        vertical_overlap = min(previous_math[3], first_math[3]) - max(
            previous_math[1], first_math[1]
        )
        horizontal_gap = max(
            previous_math[0] - first_math[2],
            first_math[0] - previous_math[2],
            0.0,
        )
        if (
            vertical_overlap < -2.0
            or horizontal_gap
            > max(18.0, min(previous_height, candidate_height) * 3.0)
        ):
            break

        previous_math = next(
            (
                bbox
                for line in reversed(candidate.lines)
                for bbox in reversed(line.math_run_bboxes)
            ),
            first_math,
        )
        outside = " ".join(
            " ".join(_text_outside_sentinels(line.text).split())
            for line in candidate.lines
        ).strip()
        outside_words = len(_prose_words(outside))
        has_prose_suffix = bool(
            outside_words >= 1 and any(line.prose_bboxes for line in candidate.lines)
        )
        if not has_prose_suffix:
            continue
        intervening_records = records[start + 1 : candidate_index]
        detached_formula_tower = bool(
            trailing_pure_math_lines >= 2
            and intervening_records
            and all(
                record.lines
                and all(not line_is_prose(line) for line in record.lines)
                for record in intervening_records
            )
        )
        if detached_formula_tower:
            # A prose record can end with the left side, numerator, and radical
            # of a displayed fraction while later PDF objects contain its
            # denominator and the sentence continuation.  That is a native 2-D
            # formula cluster, not several inline tokens to be reflowed.
            return None
        if sentence_final_text(
            candidate.bare_text()
        ) or candidate.bare_text().rstrip().endswith(":"):
            return candidate_index

        trailing_records = records[candidate_index + 1 :]
        page_bottom_fragment = bool(
            outside_words >= 8
            and trailing_records
            and all(
                re.fullmatch(
                    r"\d{1,3}",
                    "".join(strip_sentinels(record.bare_text()).split()),
                )
                for record in trailing_records
            )
        )
        if page_bottom_fragment:
            return candidate_index
    return None


def _records_form_inline_formula_tail_sentence(
    records: Sequence[_RawBlockRec],
    start: int,
) -> bool:
    """Join a sentence whose tall inline formula was emitted separately.

    A radical can end the prose record while the radicand, scripts, and short
    grammatical tail occupy the next record.  The prose slots still share one
    source baseline and the formula runs form a left-to-right chain.  Requiring
    both signals keeps a following centered display equation separate.
    """
    if start < 0 or start + 1 >= len(records):
        return False
    prefix, formula_tail = records[start : start + 2]
    if (
        not prefix.lines
        or len(formula_tail.lines) < 2
        or any(
            line_looks_like_section_heading(line)
            or EQUATION_NUMBER_RE.fullmatch(
                "".join(strip_sentinels(line.text).split())
            )
            for record in (prefix, formula_tail)
            for line in record.lines
        )
    ):
        return False

    prefix_prose = [
        bbox for line in prefix.lines for bbox in line.prose_bboxes
    ]
    prefix_math = [
        bbox for line in prefix.lines for bbox in line.math_run_bboxes
    ]
    tail_prose = [
        bbox for line in formula_tail.lines for bbox in line.prose_bboxes
    ]
    tail_math = [
        bbox for line in formula_tail.lines for bbox in line.math_run_bboxes
    ]
    if (
        not prefix_prose
        or not prefix_math
        or len(tail_math) < 2
    ):
        return False

    prefix_outside = " ".join(
        " ".join(_text_outside_sentinels(line.text).split())
        for line in prefix.lines
    ).strip()
    tail_outside = " ".join(
        " ".join(_text_outside_sentinels(line.text).split())
        for line in formula_tail.lines
    ).strip()
    grammatical_tail = bool(
        tail_prose
        and 1 <= len(_prose_words(tail_outside)) <= 4
        and re.search(r"[A-Za-z]{2,}", tail_outside)
        and re.search(r"[,;:.!?]\s*$", tail_outside)
    )
    formula_only_tail = bool(
        not _prose_words(tail_outside)
        and re.search(
            r"[,;:.!?]\s*$",
            strip_sentinels(formula_tail.bare_text()),
        )
    )
    if (
        len(_prose_words(prefix_outside)) < 5
        or sentence_final_text(prefix_outside)
        or not (grammatical_tail or formula_only_tail)
    ):
        return False

    prefix_prose_bbox = union_bbox(prefix_prose)
    prefix_math_bbox = max(prefix_math, key=lambda bbox: bbox[2])
    tail_math_bbox = union_bbox(tail_math)
    comparison_bbox = union_bbox(tail_prose) if grammatical_tail else tail_math_bbox
    baseline_overlap = min(prefix_prose_bbox[3], comparison_bbox[3]) - max(
        prefix_prose_bbox[1], comparison_bbox[1]
    )
    comparison_height = max(
        1.0,
        min(
            prefix_prose_bbox[3] - prefix_prose_bbox[1],
            comparison_bbox[3] - comparison_bbox[1],
        ),
    )
    formula_gap = tail_math_bbox[0] - prefix_math_bbox[2]
    prefix_gap = prefix_math_bbox[0] - prefix_prose_bbox[2]
    suffix_gap = (
        union_bbox(tail_prose)[0] - tail_math_bbox[2]
        if grammatical_tail
        else 0.0
    )
    combined_height = max(prefix.bbox[3], formula_tail.bbox[3]) - min(
        prefix.bbox[1], formula_tail.bbox[1]
    )
    return bool(
        baseline_overlap >= comparison_height * (0.7 if grammatical_tail else 0.35)
        and -2.0 <= prefix_gap <= 16.0
        and -4.0 <= formula_gap <= 16.0
        and -2.0 <= suffix_gap <= 16.0
        and combined_height <= max(48.0, comparison_height * 4.25)
    )


def _flow_inline_math_paragraph_sequence_end(
    records: Sequence[_RawBlockRec],
    start: int,
) -> Optional[int]:
    """Join one prose paragraph fragmented into overlapping PDF text objects.

    Tall fractions and summations are frequently emitted as side-by-side or
    vertically overlapping records.  This recognizes the paragraph from its
    reading-order continuity and source geometry, while stopping at structural
    headings and numbered display equations.
    """
    if start < 0 or start + 1 >= len(records):
        return None
    first = records[start]
    first_plain = " ".join(strip_sentinels(first.bare_text()).split())
    first_width = first.bbox[2] - first.bbox[0]
    first_words = len(_prose_words(first_plain))
    first_math = sum(sentinel_char_count(line.text) for line in first.lines)
    if (
        first_width < 180.0
        or first_words < 8
        or sentence_final_text(first_plain)
        or first_math > max(90, first_words * 3)
        or not any(line_is_prose(line) for line in first.lines)
        or any(split_bold_leadin_line(line) is not None for line in first.lines)
        or any(line_looks_like_section_heading(line) for line in first.lines)
        or any(
            EQUATION_NUMBER_RE.fullmatch("".join(strip_sentinels(line.text).split()))
            for line in first.lines
        )
    ):
        return None

    following = records[start + 1]
    first_overlap = min(first.bbox[3], following.bbox[3]) - max(
        first.bbox[1], following.bbox[1]
    )
    first_overlap_ratio = first_overlap / max(
        1.0,
        min(
            first.bbox[3] - first.bbox[1],
            following.bbox[3] - following.bbox[1],
        ),
    )
    if first_overlap_ratio < 0.34:
        return None

    sequence_bottom = first.bbox[3]
    total_words = first_words
    total_math = first_math
    saw_overlapping_record = False
    for candidate_index in range(start + 1, min(len(records), start + 10)):
        candidate = records[candidate_index]
        if any(line_looks_like_section_heading(line) for line in candidate.lines):
            break
        if any(
            EQUATION_NUMBER_RE.fullmatch("".join(strip_sentinels(line.text).split()))
            for line in candidate.lines
        ):
            break
        if (
            candidate.bbox[1] < first.bbox[1] - 4.0
            or candidate.bbox[1] > sequence_bottom + 4.0
            or candidate.bbox[0] < first.bbox[0] - 8.0
            or candidate.bbox[2] > first.bbox[2] + 8.0
            or candidate.bbox[3] - first.bbox[1] > 230.0
        ):
            break
        vertical_overlap = min(sequence_bottom, candidate.bbox[3]) - max(
            first.bbox[1], candidate.bbox[1]
        )
        horizontal_overlap = min(first.bbox[2], candidate.bbox[2]) - max(
            first.bbox[0], candidate.bbox[0]
        )
        side_by_side = bool(
            vertical_overlap > 0.0
            and candidate.bbox[0] <= first.bbox[2] + 4.0
            and candidate.bbox[2] >= first.bbox[0] - 4.0
        )
        if horizontal_overlap <= 0.0 and not side_by_side:
            break
        saw_overlapping_record = saw_overlapping_record or candidate.bbox[1] < sequence_bottom
        candidate_plain = " ".join(strip_sentinels(candidate.bare_text()).split())
        total_words += len(_prose_words(candidate_plain))
        total_math += sum(sentinel_char_count(line.text) for line in candidate.lines)
        sequence_bottom = max(sequence_bottom, candidate.bbox[3])
        if sentence_final_text(candidate_plain):
            if saw_overlapping_record and total_words >= 24 and total_math >= 8:
                return candidate_index
            break
    return None


def _fragmented_inline_formula_record_sequence_end(
    records: Sequence[_RawBlockRec],
    start: int,
) -> Optional[int]:
    """Join a prose sentence split across a three-object inline formula."""
    if start < 0 or start + 2 >= len(records):
        return None
    prefix, formula_middle, suffix = records[start : start + 3]
    if len(prefix.lines) < 3 or not formula_middle.lines or not suffix.lines:
        return None

    prefix_tail = prefix.lines[-1]
    prefix_outside = " ".join(
        " ".join(_text_outside_sentinels(line.text).split())
        for line in prefix.lines
    ).strip()
    suffix_outside = " ".join(
        " ".join(_text_outside_sentinels(line.text).split())
        for line in suffix.lines
    ).strip()
    suffix_prose_words = len(_prose_words(suffix_outside))
    if (
        len(_prose_words(prefix_outside)) < 20
        or sentence_final_text(prefix.bare_text())
        or not prefix_tail.prose_bboxes
        or not prefix_tail.math_run_bboxes
        or any(line.prose_bboxes for line in formula_middle.lines)
        or not all(line.math_run_bboxes for line in formula_middle.lines)
        or not any(line.prose_bboxes for line in suffix.lines)
        or not any(line.math_run_bboxes for line in suffix.lines)
        or suffix_prose_words < 5
        or not (
            sentence_final_text(suffix.bare_text())
            or suffix_outside.endswith(":")
        )
        or any(
            line_looks_like_section_heading(line)
            or EQUATION_NUMBER_RE.fullmatch(
                "".join(strip_sentinels(line.text).split())
            )
            for record in (prefix, formula_middle, suffix)
            for line in record.lines
        )
    ):
        return None

    prefix_formula = union_bbox(prefix_tail.math_run_bboxes)
    middle_formula = union_bbox(
        [bbox for line in formula_middle.lines for bbox in line.math_run_bboxes]
    )
    suffix_formula = union_bbox(
        [bbox for line in suffix.lines for bbox in line.math_run_bboxes]
    )
    formula_height = max(
        1.0,
        prefix_formula[3] - prefix_formula[1],
        middle_formula[3] - middle_formula[1],
        suffix_formula[3] - suffix_formula[1],
    )

    def formula_runs_touch(left: BBox, right: BBox) -> bool:
        vertical_overlap = min(left[3], right[3]) - max(left[1], right[1])
        shorter_height = max(
            1.0,
            min(left[3] - left[1], right[3] - right[1]),
        )
        horizontal_gap = right[0] - left[2]
        return bool(
            vertical_overlap >= shorter_height * 0.45
            and -formula_height <= horizontal_gap <= formula_height * 1.5
        )

    if not (
        formula_runs_touch(prefix_formula, middle_formula)
        and formula_runs_touch(middle_formula, suffix_formula)
    ):
        return None
    if (
        formula_middle.bbox[1] > prefix.bbox[3] + 3.0
        or suffix.bbox[1] > max(prefix.bbox[3], formula_middle.bbox[3]) + 3.0
        or suffix.bbox[3] - prefix.bbox[1] > 60.0
    ):
        return None
    return start + 2


def _stacked_inline_formula_paragraph_end(
    records: Sequence[_RawBlockRec],
    start: int,
) -> Optional[int]:
    """Join prose split into an intro, a formula tower, and a prose tail."""
    if start < 0 or start + 2 >= len(records):
        return None
    intro, formula_lead, formula_tail = records[start : start + 3]
    if len(intro.lines) != 1 or not line_is_prose(intro.lines[0]):
        return None
    intro_outside = " ".join(
        _text_outside_sentinels(intro.lines[0].text).split()
    )
    lead_outside = " ".join(
        " ".join(_text_outside_sentinels(line.text).split())
        for line in formula_lead.lines
    ).strip()
    tail_outside = " ".join(
        " ".join(_text_outside_sentinels(line.text).split())
        for line in formula_tail.lines
    ).strip()
    if (
        len(_prose_words(intro_outside)) < 6
        or sentence_final_text(intro_outside)
        or not re.search(r"\b(?:is|are|be)\s*$", intro_outside, re.IGNORECASE)
        or not re.match(
            r"^(?:to\s+)?(?:compute|calculate|evaluate|obtain|derive)\b",
            lead_outside,
            re.IGNORECASE,
        )
        or len(_prose_words(tail_outside)) < 12
        or not (
            sentence_final_text(tail_outside)
            or tail_outside.rstrip().endswith(":")
        )
        or not re.search(r"\b(?:where|with|for)\b", tail_outside, re.IGNORECASE)
    ):
        return None
    lead_math = sum(not line_is_prose(line) for line in formula_lead.lines)
    tail_math = sum(not line_is_prose(line) for line in formula_tail.lines)
    tail_prose = sum(line_is_prose(line) for line in formula_tail.lines)
    if lead_math < 2 or tail_math < 2 or tail_prose < 2:
        return None
    if any(
        line_looks_like_section_heading(line)
        or EQUATION_NUMBER_RE.fullmatch(
            "".join(strip_sentinels(line.text).split())
        )
        for record in (intro, formula_lead, formula_tail)
        for line in record.lines
    ):
        return None
    intro_width = max(1.0, intro.bbox[2] - intro.bbox[0])
    if any(
        abs(record.bbox[0] - intro.bbox[0]) > max(18.0, intro_width * 0.05)
        or record.bbox[2] > intro.bbox[2] + max(18.0, intro_width * 0.05)
        for record in (formula_lead, formula_tail)
    ):
        return None
    sequence_bottom = intro.bbox[3]
    for record in (formula_lead, formula_tail):
        if record.bbox[1] > sequence_bottom + 4.0:
            return None
        sequence_bottom = max(sequence_bottom, record.bbox[3])
    return start + 2


def _compact_inline_formula_paragraph_end(
    records: Sequence[_RawBlockRec],
    start: int,
) -> Optional[int]:
    """Join a short paragraph fragmented around multiple inline fractions."""
    if start < 0 or start + 3 >= len(records):
        return None
    first = records[start]
    first_prose = [line for line in first.lines if line_is_prose(line)]
    first_formula = [line for line in first.lines if not line_is_prose(line)]
    first_words = sum(
        len(_prose_words(_text_outside_sentinels(line.text)))
        for line in first.lines
    )
    if (
        not first_prose
        or len(first_formula) < 2
        or first_words < 6
        or sentence_final_text(first.bare_text())
        or any(line_looks_like_section_heading(line) for line in first.lines)
    ):
        return None

    sequence_bottom = first.bbox[3]
    prose_records = 1
    prose_words = first_words
    formula_dominant_records = 1
    for candidate_index in range(start + 1, min(len(records), start + 7)):
        candidate = records[candidate_index]
        if (
            candidate.bbox[1] < first.bbox[1] - 3.0
            or candidate.bbox[1] > sequence_bottom + 4.0
            or candidate.bbox[3] - first.bbox[1] > 50.0
            or any(line_looks_like_section_heading(line) for line in candidate.lines)
            or any(
                EQUATION_NUMBER_RE.fullmatch(
                    "".join(strip_sentinels(line.text).split())
                )
                for line in candidate.lines
            )
        ):
            break
        outside_words = sum(
            len(_prose_words(_text_outside_sentinels(line.text)))
            for line in candidate.lines
        )
        prose_lines = sum(line_is_prose(line) for line in candidate.lines)
        formula_lines = len(candidate.lines) - prose_lines
        if outside_words >= 4:
            prose_records += 1
            prose_words += outside_words
        if formula_lines > prose_lines or (
            formula_lines and outside_words <= 2
        ):
            formula_dominant_records += 1
        sequence_bottom = max(sequence_bottom, candidate.bbox[3])
        if sentence_final_text(candidate.bare_text()):
            if (
                prose_records >= 3
                and prose_words >= 30
                and formula_dominant_records >= 2
            ):
                return candidate_index
            break
    return None


def _records_form_two_record_inline_formula_paragraph(
    records: Sequence[_RawBlockRec],
    start: int,
) -> bool:
    """Rejoin a two-line prose paragraph split by an inline formula tower."""
    if start < 0 or start + 2 >= len(records):
        return False
    current, following, next_record = records[start : start + 3]
    if any(
        line_looks_like_section_heading(line)
        for record in (current, following)
        for line in record.lines
    ):
        return False
    current_prose = [line for line in current.lines if line_is_prose(line)]
    following_prose = [line for line in following.lines if line_is_prose(line)]
    current_formula = [line for line in current.lines if not line_is_prose(line)]
    following_formula = [line for line in following.lines if not line_is_prose(line)]
    if (
        len(current_prose) < 2
        or len(current_formula) < 2
        or not following_prose
        or not following_formula
    ):
        return False
    current_outside = " ".join(
        _text_outside_sentinels(line.text) for line in current.lines
    )
    following_outside = " ".join(
        _text_outside_sentinels(line.text) for line in following.lines
    )
    if (
        len(_prose_words(current_outside)) < 12
        or len(_prose_words(following_outside)) < 8
        or sentence_final_text(current.bare_text())
        or sentence_final_text(following.bare_text())
    ):
        return False
    vertical_gap = max(
        following.bbox[1] - current.bbox[3],
        current.bbox[1] - following.bbox[3],
        0.0,
    )
    horizontal_overlap = min(current.bbox[2], following.bbox[2]) - max(
        current.bbox[0], following.bbox[0]
    )
    if vertical_gap > 4.0 or horizontal_overlap < 0.6 * min(
        current.bbox[2] - current.bbox[0],
        following.bbox[2] - following.bbox[0],
    ):
        return False
    next_gap = next_record.bbox[1] - following.bbox[3]
    next_has_number = any(
        EQUATION_NUMBER_RE.fullmatch(
            "".join(strip_sentinels(line.text).split())
        )
        for line in next_record.lines
    )
    return bool(0.0 <= next_gap <= 18.0 and next_has_number)


def _fragmented_inline_math_paragraph_end(
    records: Sequence[_RawBlockRec],
    start: int,
) -> Optional[int]:
    """Join one prose paragraph fragmented into alternating TeX text objects."""
    if start < 0 or start + 2 >= len(records):
        return None
    first = records[start]
    first_outside = " ".join(
        " ".join(_text_outside_sentinels(line.text).split())
        for line in first.lines
    ).strip()
    if (
        len(_prose_words(first_outside)) < 15
        or sum(sentinel_char_count(line.text) for line in first.lines) <= 0
        or sentence_final_text(first.bare_text())
        or any(line_looks_like_section_heading(line) for line in first.lines)
        or any(
            _ACADEMIC_FORMULA_STATEMENT_RE.match(
                " ".join(strip_sentinels(line.text).split())
            )
            for line in first.lines
        )
    ):
        return None

    first_width = max(1.0, first.bbox[2] - first.bbox[0])
    sequence_bottom = first.bbox[3]
    prose_records = 1
    prose_words = len(_prose_words(first_outside))
    math_dominant_records = 0
    for candidate_index in range(start + 1, min(len(records), start + 8)):
        candidate = records[candidate_index]
        if (
            candidate.bbox[1] < first.bbox[1] - 2.0
            or candidate.bbox[1] > sequence_bottom + 3.0
            or candidate.bbox[3] - first.bbox[1] > 120.0
            or candidate.bbox[0] < first.bbox[0] - 4.0
            or candidate.bbox[2] > first.bbox[2] + max(20.0, first_width * 0.08)
            or any(line_looks_like_section_heading(line) for line in candidate.lines)
            or any(
                _ACADEMIC_FORMULA_STATEMENT_RE.match(
                    " ".join(strip_sentinels(line.text).split())
                )
                for line in candidate.lines
            )
            or any(
                EQUATION_NUMBER_RE.fullmatch(
                    "".join(strip_sentinels(line.text).split())
                )
                for line in candidate.lines
            )
        ):
            break
        outside = " ".join(
            " ".join(_text_outside_sentinels(line.text).split())
            for line in candidate.lines
        ).strip()
        outside_words = len(_prose_words(outside))
        prose_lines = sum(line_is_prose(line) for line in candidate.lines)
        if prose_lines > len(candidate.lines) / 2.0 and outside_words >= 8:
            prose_records += 1
            prose_words += outside_words
        else:
            math_dominant_records += 1
        sequence_bottom = max(sequence_bottom, candidate.bbox[3])
        if sentence_final_text(candidate.bare_text()):
            if (
                prose_records >= 3
                and prose_words >= 70
                and math_dominant_records >= 2
            ):
                return candidate_index
            break
    return None


def _inline_fraction_paragraph_before_statement_end(
    records: Sequence[_RawBlockRec],
    start: int,
) -> Optional[int]:
    """Join a body paragraph split by a stacked fraction before a theorem.

    Some TeX producers emit the numerator, denominator, and sentence tail as
    separate text objects whose hulls overlap several body rows.  The final
    object can also begin the following theorem.  Keeping the records apart
    makes each fragment compete for the same CJK layout band; joining through
    the structural boundary lets ``segments_from_record`` split the theorem
    after the complete prose paragraph has been recovered.
    """
    if start < 0 or start + 2 >= len(records):
        return None
    first = records[start]
    first_plain = " ".join(
        " ".join(_text_outside_sentinels(line.text).split())
        for line in first.lines
    ).strip()
    if (
        len(_prose_words(first_plain)) < 3
        or sentence_final_text(first_plain)
        or sum(sentinel_char_count(line.text) for line in first.lines) <= 0
        or any(line_looks_like_section_heading(line) for line in first.lines)
    ):
        return None

    first_x0 = first.bbox[0]
    sequence_bottom = first.bbox[3]
    saw_stacked_inline_formula = first.detached_inline_scripts
    prefix_lines = list(first.lines)
    for candidate_index in range(start + 1, min(len(records), start + 7)):
        candidate = records[candidate_index]
        if candidate.bbox[1] < first.bbox[1] - 2.0:
            break
        if candidate.bbox[1] > sequence_bottom + 14.0:
            break
        if abs(candidate.bbox[0] - first_x0) > 8.0:
            break

        academic_index = next(
            (
                line_index
                for line_index, line in enumerate(candidate.lines)
                if _ACADEMIC_FORMULA_STATEMENT_RE.match(
                    " ".join(strip_sentinels(line.text).split())
                )
            ),
            None,
        )
        candidate_prefix = (
            candidate.lines
            if academic_index is None
            else candidate.lines[:academic_index]
        )
        if academic_index is None and any(
            line_looks_like_section_heading(line) for line in candidate.lines
        ):
            break

        prefix_lines.extend(candidate_prefix)
        saw_stacked_inline_formula = bool(
            saw_stacked_inline_formula or candidate.detached_inline_scripts
        )
        if academic_index is not None:
            prefix_plain = " ".join(
                " ".join(_text_outside_sentinels(line.text).split())
                for line in prefix_lines
            ).strip()
            prefix_source = " ".join(
                " ".join(strip_sentinels(line.text).split())
                for line in prefix_lines
            ).strip()
            prose_line_count = sum(
                len(_prose_words(_text_outside_sentinels(line.text))) >= 3
                for line in prefix_lines
            )
            if (
                saw_stacked_inline_formula
                and len(_prose_words(prefix_plain)) >= 45
                and prose_line_count >= 5
                and sentence_final_text(prefix_source)
            ):
                return candidate_index
            return None
        sequence_bottom = max(sequence_bottom, candidate.bbox[3])
    return None


def _formula_bridge_sequence_end(
    records: Sequence[_RawBlockRec],
    start: int,
) -> Optional[int]:
    """Find prose split around a connected multi-record inline formula tower."""
    if start < 0 or start + 2 >= len(records):
        return None
    first = records[start]
    first_outside = " ".join(
        " ".join(_text_outside_sentinels(line.text).split())
        for line in first.lines
    ).strip()
    short_derivation = bool(
        re.match(
            r"^(?:This result can be obtained|Thus we can get|Knowing)\b",
            first_outside,
            re.IGNORECASE,
        )
    )
    if (
        sum(sentinel_char_count(line.text) for line in first.lines) <= 0
        or len(_prose_words(first_outside)) < (6 if short_derivation else 8)
        or sentence_final_text(first_outside)
        or not re.search(
            r"\b(?:and|as|by|can be|namely|then|to be|version|where|with)\s*$",
            first_outside,
            re.IGNORECASE,
        )
    ):
        return None

    math_dominant_records = 0
    sequence_bottom = first.bbox[3]
    for candidate_index in range(start + 1, min(len(records), start + 8)):
        candidate = records[candidate_index]
        # PDF object order commonly finishes the left column before jumping
        # back to the top of the right column. That jump is not a continued
        # formula tower even when the left-column lead happens to end in
        # "with" and the next-column caption contains inline math.
        if candidate.bbox[1] < first.bbox[1] - 12.0:
            break
        if candidate.bbox[1] > sequence_bottom + 12.0:
            break
        if any(line_looks_like_section_heading(line) for line in candidate.lines):
            break
        if sum(sentinel_char_count(line.text) for line in candidate.lines) <= 0:
            break
        outside = " ".join(
            " ".join(_text_outside_sentinels(line.text).split())
            for line in candidate.lines
        ).strip()
        outside_words = len(_prose_words(outside))
        math_lines = sum(not line_is_prose(line) for line in candidate.lines)
        if math_lines > len(candidate.lines) / 2.0 or outside_words <= 3:
            math_dominant_records += 1
        if (
            math_dominant_records >= 2
            and (
                (outside_words >= 12 and sentence_final_text(outside))
                or (
                    first_outside.lower().endswith("can be")
                    and re.match(r"^and\b", outside, re.IGNORECASE)
                    and re.search(r"\bThen\b", outside, re.IGNORECASE)
                )
                or (
                    short_derivation
                    and any(sentence_final_text(line.text) for line in candidate.lines)
                )
            )
        ):
            return candidate_index
        sequence_bottom = max(sequence_bottom, candidate.bbox[3])
        if outside_words >= 12 and sentence_final_text(outside):
            break
    return None


def _records_form_wrapped_formula_continuation(
    current: _RawBlockRec,
    following: _RawBlockRec,
) -> bool:
    if len(current.lines) < 12 or not 3 <= len(following.lines) <= 8:
        return False
    current_prose = sum(line_is_prose(line) for line in current.lines)
    if current_prose / len(current.lines) < 0.65:
        return False
    if len(_prose_words(strip_sentinels(current.bare_text()))) < 50:
        return False
    tail = current.lines[-1]
    tail_outside = " ".join(_text_outside_sentinels(tail.text).split())
    if (
        not sentinel_char_count(tail.text)
        or sentence_final_text(tail.text)
        or not re.match(r"^(?:by|given\s+by)\b", tail_outside, re.IGNORECASE)
    ):
        return False
    gap = following.bbox[1] - current.bbox[3]
    horizontal_overlap = min(current.bbox[2], following.bbox[2]) - max(
        current.bbox[0], following.bbox[0]
    )
    if gap > 3.0 or horizontal_overlap < min(
        current.bbox[2] - current.bbox[0],
        following.bbox[2] - following.bbox[0],
    ) * 0.45:
        return False
    compact_lines = [
        line
        for line in following.lines
        if len("".join(strip_sentinels(line.text).split())) <= 8
    ]
    formula_lines = [
        line
        for line in following.lines
        if sentinel_char_count(line.text) or not line_is_prose(line)
    ]
    natural_tail = any(
        sentence_final_text(line.text)
        and len(_prose_words(_text_outside_sentinels(line.text))) >= 2
        for line in following.lines
    )
    has_equation_number = any(
        EQUATION_NUMBER_RE.fullmatch("".join(strip_sentinels(line.text).split()))
        for line in following.lines
    )
    return bool(
        len(formula_lines) >= 2
        and compact_lines
        and natural_tail
        and not has_equation_number
    )


def _promote_stacked_plain_formula_fragments(
    lines: Sequence[_LineRec],
) -> List[_LineRec]:
    """Wrap tiny plain-font numerator/denominator pieces as math markers."""
    formula_lines = [line for line in lines if sentinel_char_count(line.text)]
    promoted: List[_LineRec] = []
    for line in lines:
        compact = "".join(strip_sentinels(line.text).split())
        if sentinel_char_count(line.text) or not re.fullmatch(r"\d{1,4}", compact):
            promoted.append(line)
            continue
        height = max(1.0, line.bbox[3] - line.bbox[1])
        touches_formula = any(
            max(
                line.bbox[1] - candidate.bbox[3],
                candidate.bbox[1] - line.bbox[3],
                0.0,
            )
            <= 1.5
            and max(
                line.bbox[0] - candidate.bbox[2],
                candidate.bbox[0] - line.bbox[2],
                0.0,
            )
            <= max(12.0, height * 1.8)
            for candidate in formula_lines
        )
        if not touches_formula:
            promoted.append(line)
            continue
        promoted.append(
            replace(
                line,
                text=f"{SENTINEL_OPEN}{compact}{SENTINEL_CLOSE}",
                math_bboxes=[line.bbox],
                math_run_bboxes=[line.bbox],
                prose_bboxes=[],
            )
        )
    return promoted


def _equation_table_region_bboxes(
    records: Sequence[_RawBlockRec],
    equation_flags: Sequence[bool],
) -> List[BBox]:
    """Return cell-level regions for numeric tables skipped as equations.

    Prose-dominant sentence lines are excluded: they are extracted as
    translatable blocks (formula cells stay protected by placeholder
    markers), so treating them as preserved regions would both hide them
    from translation and falsely condemn their Chinese text as
    preserved-area changes.
    """
    regions: List[BBox] = []
    for record, is_equation in zip(records, equation_flags):
        if not is_equation or not record_is_table(record):
            continue
        prose_prefix_count = _prose_wrapped_numbered_equation_prefix_count(record)
        cells: List[BBox] = []
        for index, line in enumerate(record.lines):
            if index < prose_prefix_count or not strip_sentinels(line.text).strip():
                continue
            if _line_is_prose_dominant_sentence(line):
                continue
            mixed_formula_prose = bool(
                line.math_run_bboxes
                and line.prose_bboxes
                and substantial_prose_word_count(strip_sentinels(line.text)) >= 2
            )
            if mixed_formula_prose:
                cells.extend(line.math_run_bboxes)
            else:
                cells.append(line.bbox)
        if not cells and not any(strip_sentinels(line.text).strip() for line in record.lines):
            cells = [record.bbox]
        regions.extend(cells)
    return list(dict.fromkeys(regions))


def _equation_zone_cluster_has_number(
    records: Sequence["_RawBlockRec"],
    equation_flags: Sequence[bool],
    record_index: int,
    *,
    max_gap: float = 30.0,
) -> bool:
    """Whether a vertically-adjacent equation-flagged record carries an
    equation number — i.e. this record is one row of a multi-record display
    equation, not an inline formula between prose."""
    record = records[record_index]
    for offset in (-2, -1, 1, 2):
        other_index = record_index + offset
        if not 0 <= other_index < len(records) or not equation_flags[other_index]:
            continue
        other = records[other_index]
        vertical_gap = max(
            record.bbox[1] - other.bbox[3],
            other.bbox[1] - record.bbox[3],
            0.0,
        )
        if vertical_gap > max_gap:
            continue
        for line in other.lines:
            compact = "".join(strip_sentinels(line.text).split())
            if compact and EQUATION_NUMBER_RE.fullmatch(compact):
                return True
    return False


def _equation_record_is_numbered_formula_row(
    records: Sequence["_RawBlockRec"],
    equation_flags: Sequence[bool],
    record_index: int,
) -> bool:
    """Keep formula-language operators immutable inside a numbered display."""
    if not equation_flags[record_index]:
        return False
    record = records[record_index]
    numbered = any(
        EQUATION_NUMBER_RE.fullmatch(
            "".join(strip_sentinels(line.text).split())
        )
        for line in record.lines
    ) or _equation_zone_cluster_has_number(
        records,
        equation_flags,
        record_index,
    )
    has_natural_language_lead = any(
        (
            sentinel_char_count(line.text) > 0
            and line.prose_bboxes
            and len(
                re.findall(
                    r"[A-Za-z]{2,}",
                    _text_outside_sentinels(line.text),
                )
            )
            >= 2
        )
        or substantial_prose_word_count(
            _text_outside_sentinels(line.text)
        )
        >= 6
        for line in record.lines
    )
    return bool(
        numbered
        and not has_natural_language_lead
        and not any(
            _line_is_prose_dominant_sentence(line) for line in record.lines
        )
    )


def _equation_zone_cluster_has_distinct_math_row(
    records: Sequence["_RawBlockRec"],
    equation_flags: Sequence[bool],
    record_index: int,
    *,
    max_gap: float = 8.0,
) -> bool:
    """Whether an equation-only record is one row of a multiline display.

    Unnumbered derivations are often emitted as several adjacent raw records.
    Their final row can sit within a point or two of the following paragraph,
    which otherwise makes it look like a detached inline-math fragment. Keep
    that row in the original equation when another aligned math row is nearby.
    """
    record = records[record_index]
    width = max(1.0, record.bbox[2] - record.bbox[0])
    height = max(1.0, record.bbox[3] - record.bbox[1])
    center_x = (record.bbox[0] + record.bbox[2]) / 2.0

    for other_index, (other, is_equation) in enumerate(
        zip(records, equation_flags)
    ):
        if other_index == record_index or not is_equation:
            continue
        if not other.lines or any(line_is_prose(line) for line in other.lines):
            continue

        other_width = max(1.0, other.bbox[2] - other.bbox[0])
        other_height = max(1.0, other.bbox[3] - other.bbox[1])
        vertical_overlap = min(record.bbox[3], other.bbox[3]) - max(
            record.bbox[1], other.bbox[1]
        )
        if vertical_overlap >= 0.5 * min(height, other_height):
            continue
        vertical_gap = max(
            record.bbox[1] - other.bbox[3],
            other.bbox[1] - record.bbox[3],
            0.0,
        )
        if vertical_gap > max_gap:
            continue

        horizontal_overlap = min(record.bbox[2], other.bbox[2]) - max(
            record.bbox[0], other.bbox[0]
        )
        other_center_x = (other.bbox[0] + other.bbox[2]) / 2.0
        aligned = horizontal_overlap >= 0.25 * min(width, other_width)
        similarly_centered = abs(center_x - other_center_x) <= 0.6 * max(
            width, other_width
        )
        if aligned or similarly_centered:
            return True
    return False


def _inline_formula_record_is_part_of_2d_cluster(
    records: Sequence["_RawBlockRec"],
    record_index: int,
) -> bool:
    """Detect an inline formula tower split across adjacent raw records."""
    record = records[record_index]
    if any(_line_is_equation_explanation(line) for line in record.lines):
        return False
    first = max(0, record_index - 2)
    last = min(len(records), record_index + 3)

    def is_formula_cluster_line(line: _LineRec) -> bool:
        if not line_is_prose(line):
            return True
        outside_words = _PROSE_WORD_RE.findall(
            _text_outside_sentinels(line.text)
        )
        return sentinel_char_count(line.text) >= 2 and len(outside_words) <= 2

    candidates = [
        (index, line)
        for index in range(first, last)
        for line in records[index].lines
        if is_formula_cluster_line(line)
    ]
    seeds = [(index, line) for index, line in candidates if index == record_index]
    if not seeds:
        return False

    cluster = list(seeds)
    pending = list(seeds)
    while pending:
        _, current = pending.pop()
        current_height = max(1.0, current.bbox[3] - current.bbox[1])
        for candidate_index, candidate in candidates:
            if any(candidate is known for _, known in cluster):
                continue
            candidate_height = max(1.0, candidate.bbox[3] - candidate.bbox[1])
            vertical_overlap = min(current.bbox[3], candidate.bbox[3]) - max(
                current.bbox[1], candidate.bbox[1]
            )
            horizontal_gap = max(
                current.bbox[0] - candidate.bbox[2],
                candidate.bbox[0] - current.bbox[2],
                0.0,
            )
            if (
                vertical_overlap >= -1.0
                and horizontal_gap
                <= max(12.0, min(current_height, candidate_height))
            ):
                item = (candidate_index, candidate)
                cluster.append(item)
                pending.append(item)

    record_indexes = {index for index, _ in cluster}
    has_stacked_ink = any(
        min(first_line.bbox[2], second_line.bbox[2])
        - max(first_line.bbox[0], second_line.bbox[0])
        >= 0.2
        * min(
            first_line.bbox[2] - first_line.bbox[0],
            second_line.bbox[2] - second_line.bbox[0],
        )
        and abs(
            (first_line.bbox[1] + first_line.bbox[3]) / 2.0
            - (second_line.bbox[1] + second_line.bbox[3]) / 2.0
        )
        >= 0.2
        * min(
            first_line.bbox[3] - first_line.bbox[1],
            second_line.bbox[3] - second_line.bbox[1],
        )
        for first_offset, (_, first_line) in enumerate(cluster)
        for _, second_line in cluster[first_offset + 1 :]
    )
    return bool(
        len(cluster) >= 4
        and len(record_indexes) >= 3
        and has_stacked_ink
    )


def _inline_formula_bridge_block(
    page_index: int,
    records: Sequence[_RawBlockRec],
    equation_flags: Sequence[bool],
    algorithm_flags: Sequence[bool],
    record_index: int,
) -> Optional[TextBlock]:
    """Expose an inline formula record that belongs to surrounding prose."""
    record = records[record_index]
    if (
        not equation_flags[record_index]
        or algorithm_flags[record_index]
        or record_is_table(record)
        or not record.lines
        or any(line_is_prose(line) for line in record.lines)
    ):
        return None
    if _inline_formula_record_is_part_of_2d_cluster(records, record_index):
        return None
    # A display formula may be emitted as two horizontally contiguous text
    # objects on one visual row (for example, a radical prefix and its
    # radicand suffix). Exposing either object as an inline bridge lets later
    # paragraph merging erase and re-typeset half of the display equation.
    # Keep compact multi-record inline fragments eligible, but preserve a
    # wide combined math row as native PDF ink.
    for neighbour_index in (record_index - 1, record_index + 1):
        if not 0 <= neighbour_index < len(records):
            continue
        neighbour = records[neighbour_index]
        if (
            not equation_flags[neighbour_index]
            or algorithm_flags[neighbour_index]
            or not neighbour.lines
            or any(line_is_prose(line) for line in neighbour.lines)
        ):
            continue
        record_height = max(1.0, record.bbox[3] - record.bbox[1])
        neighbour_height = max(1.0, neighbour.bbox[3] - neighbour.bbox[1])
        shorter_height = min(record_height, neighbour_height)
        vertical_overlap = min(record.bbox[3], neighbour.bbox[3]) - max(
            record.bbox[1], neighbour.bbox[1]
        )
        horizontal_gap = max(
            record.bbox[0] - neighbour.bbox[2],
            neighbour.bbox[0] - record.bbox[2],
            0.0,
        )
        combined_width = max(record.bbox[2], neighbour.bbox[2]) - min(
            record.bbox[0], neighbour.bbox[0]
        )
        if (
            vertical_overlap >= shorter_height * 0.6
            and horizontal_gap <= max(2.0, shorter_height * 0.2)
            and combined_width >= max(96.0, shorter_height * 7.0)
        ):
            return None
    # One row of a display equation (e.g. the fraction rows of MCF eq (8),
    # or an unnumbered multi-line derivation) must never be glued into the
    # adjacent paragraph: redacting it hollows out the equation.
    if _equation_zone_cluster_has_number(
        records, equation_flags, record_index
    ) or _equation_zone_cluster_has_distinct_math_row(
        records, equation_flags, record_index
    ):
        return None

    if not _is_strict_inline_formula_bridge(records, record_index):
        compact = "".join(record.bare_text().split())
        has_equation_number = any(
            EQUATION_NUMBER_RE.fullmatch(
                "".join(strip_sentinels(line.text).split())
            )
            for line in record.lines
        )
        if (
            not compact
            or len(compact) > 100
            or has_equation_number
            or not any(sentinel_char_count(line.text) for line in record.lines)
            or not _inline_formula_record_touches_formula_prose(records, record_index)
        ):
            return None

    accumulator = _SegmentAccumulator()
    for line in record.lines:
        _accumulate_line(accumulator, line)
    return accumulator.flush(page_index)


def _is_strict_inline_formula_bridge(
    records: Sequence[_RawBlockRec],
    record_index: int,
) -> bool:
    """Match the original immediate prose/formula/prose bridge pattern."""
    if record_index <= 0 or record_index + 1 >= len(records):
        return False
    record = records[record_index]
    if record.sentinel_ratio() < 0.45:
        return False

    previous = records[record_index - 1]
    following = records[record_index + 1]
    previous_prose = [line for line in previous.lines if line_is_prose(line)]
    following_prose = [
        line
        for line in following.lines
        if line_is_prose(line) and line.text.lstrip().startswith(SENTINEL_OPEN)
    ]
    if not previous_prose or not following_prose:
        return False

    following_line = following_prose[0]
    following_words = [
        word
        for word in _PROSE_WORD_RE.findall(strip_sentinels(following_line.text))
        if word.lower() not in _MATH_WORDS
    ]
    if len(following_words) < 2:
        return False

    outside_text = " ".join(_text_outside_sentinels(line.text) for line in record.lines)
    outside_words = _PROSE_WORD_RE.findall(outside_text)
    if len(outside_words) > 3:
        return False
    previous_tail = strip_sentinels(previous_prose[-1].text).rstrip()
    if not previous_tail.endswith(("=", ":=")) and not outside_words:
        return False

    record_height = max(1.0, record.bbox[3] - record.bbox[1])
    horizontal_gap = following_line.bbox[0] - record.bbox[2]
    if abs(horizontal_gap) > max(8.0, record_height * 0.6):
        return False
    if record.bbox[1] - previous.bbox[3] > record_height * 0.75:
        return False
    return following.bbox[1] - record.bbox[3] <= record_height * 0.75


def _inline_formula_record_touches_formula_prose(
    records: Sequence[_RawBlockRec],
    record_index: int,
) -> bool:
    """Find a nearby formula-rich prose line sharing this record's baseline."""
    record_bbox = records[record_index].bbox
    first = max(0, record_index - 3)
    last = min(len(records), record_index + 4)
    for nearby_index in range(first, last):
        if nearby_index == record_index:
            continue
        for line in records[nearby_index].lines:
            if not line_is_prose(line) or not sentinel_char_count(line.text):
                continue
            record_height = max(1.0, record_bbox[3] - record_bbox[1])
            line_height = max(1.0, line.bbox[3] - line.bbox[1])
            if record_height > max(line_height * 2.2, line_height + 10.0):
                continue
            vertical_overlap = min(record_bbox[3], line.bbox[3]) - max(
                record_bbox[1], line.bbox[1]
            )
            shorter_height = max(
                1.0,
                min(record_height, line_height),
            )
            horizontal_gap = max(
                record_bbox[0] - line.bbox[2],
                line.bbox[0] - record_bbox[2],
                0.0,
            )
            if (
                vertical_overlap >= -1.5
                and horizontal_gap <= max(18.0, shorter_height * 3.0)
            ):
                return True
    return False


def _promote_equation_table_neighbor_blocks(
    blocks: Sequence[TextBlock],
    cell_regions: Sequence[BBox],
) -> None:
    """Preserve textual headers and labels attached to equation-like table cells."""
    components: List[List[BBox]] = []
    for cell in sorted(cell_regions, key=lambda bbox: (bbox[1], bbox[0])):
        for component in components:
            envelope = union_bbox(component)
            horizontal_gap = max(envelope[0] - cell[2], cell[0] - envelope[2], 0.0)
            vertical_gap = max(envelope[1] - cell[3], cell[1] - envelope[3], 0.0)
            if (
                horizontal_gap <= _TABLE_COMPONENT_HORIZONTAL_PAD
                and vertical_gap <= 18.0
            ):
                component.append(cell)
                break
        else:
            components.append([cell])

    envelopes = [union_bbox(component) for component in components]
    excluded_types = {
        "algorithm",
        "bibliography",
        "caption",
        "equation",
        "figure_label",
        "footer",
        "metadata",
        "table",
    }
    for block in blocks:
        if block.block_type == "formula_prose" and block.flow_inline_math:
            continue
        if block.block_type in excluded_types or block.source_lines > 4:
            continue
        plain = " ".join(strip_sentinels(block.text).split())
        if not plain or len(plain) > 180 or block.font_size > 11.5:
            continue
        # Section headings are structural anchors, never table components; a
        # wide envelope reaching across the column gutter must not swallow
        # them (oc p9: "A.2. Additional Details" next to Algorithm 1 cells).
        # Table header rows mis-classified as headings ("2 Cos. alignment…")
        # carry no section-number pattern and still promote.
        if looks_like_academic_structure_heading(block, plain):
            continue
        if block.block_type == "heading" and re.match(
            r"^(?:\d+\.\d|\d+\.\s|[A-Z]\.\d|[A-Z]\.\s)", plain
        ):
            continue
        for envelope in envelopes:
            horizontal_gap = max(
                envelope[0] - block.bbox[2],
                block.bbox[0] - envelope[2],
                0.0,
            )
            if horizontal_gap > _TABLE_COMPONENT_HORIZONTAL_PAD:
                continue
            if (
                horizontal_gap > 0.0
                and block.source_lines >= 2
                and substantial_prose_word_count(plain) >= 10
                and len(_PROSE_STOPWORD_RE.findall(plain)) >= 6
                and re.search(r"[,.;:]", plain)
            ):
                # A formula table in the neighboring page column can share
                # the paragraph's y-band while remaining physically disjoint.
                # Multi-line running prose is not a textual table component.
                continue
            center_y = (block.bbox[1] + block.bbox[3]) / 2.0
            center_inside_table = envelope[1] <= center_y <= envelope[3]
            header_gap = envelope[1] - block.bbox[3]
            if not center_inside_table and not 0.0 <= header_gap <= 14.0:
                continue
            if (
                not center_inside_table
                and substantial_prose_word_count(plain) >= TABLE_HEADER_PROSE_WORD_LIMIT
            ):
                continue
            if (
                not center_inside_table
                and len(_prose_words(plain)) >= 4
                and _PROSE_VERB_RE.search(plain)
                and not _looks_like_table_header_text(plain)
                and len(re.findall(r"\d+(?:\.\d+)?", plain)) < 2
            ):
                continue
            # A sentence ending in ":" introduces what follows (an equation, a
            # list); it is never a table header ("This leads to the Static SB
            # problem:" above equation (2) on IPMF p3).
            if (
                not center_inside_table
                and plain.endswith(":")
                and len(_prose_words(plain)) >= 3
                and _PROSE_VERB_RE.search(plain)
            ):
                continue
            block.block_type = "table"
            block.should_translate = False
            block.preserve_position = True
            block.nowrap = True
            block.no_merge = True
            break


def _attach_formula_keepouts(
    blocks: Sequence[TextBlock],
    formula_lines: Sequence[_LineRec],
) -> None:
    """Keep translated prose from painting over neighboring formula records."""
    for block in blocks:
        expanded = expand_bbox(block.bbox, 1.5)
        prose_baselines = [
            bbox[3] - block.font_size * 0.18
            for bbox in block.source_prose_bboxes
        ]
        source_prose_baseline = (
            statistics.median(prose_baselines) if prose_baselines else None
        )
        candidates: List[Tuple[BBox, BBox, Tuple[BBox, ...], bool]] = []
        for line in formula_lines:
            line_origins = [
                float(span["origin"][1])
                for span in line.spans
                if span.get("origin") is not None
            ]
            line_baseline = (
                statistics.median(line_origins)
                if line_origins
                else line.bbox[3] - block.font_size * 0.18
            )
            if (
                block.flow_inline_math
                and block.source_lines == 1
                and block.source_math_bboxes
                and source_prose_baseline is not None
                and line_baseline - source_prose_baseline
                >= block.font_size * 0.45
            ):
                continue
            runs = line.math_run_bboxes or [line.bbox]
            groups = _group_math_atoms_by_run(runs, line.math_bboxes)
            for index, keepout in enumerate(runs):
                group = groups[index] if index < len(groups) else ()
                raw_atoms: List[BBox] = []
                for atom in group:
                    raw_atom = atom
                    for span in line.spans:
                        span_bbox = tuple(
                            float(value) for value in span.get("bbox", ())
                        )
                        if span_bbox == atom:
                            raw_atom = tuple(
                                float(value)
                                for value in span.get("_raw_bbox", span_bbox)
                            )
                            break
                    raw_atoms.append(raw_atom)
                raw_keepout = union_bbox(raw_atoms) if raw_atoms else keepout
                normalized_hit = bboxes_intersect(expanded, keepout)
                raw_delete_hit = bool(
                    raw_keepout != keepout
                    and bboxes_intersect(expanded, raw_keepout)
                )
                keepout_area = max(bbox_area(keepout), 0.1)
                if any(
                    bbox_intersection_area(keepout, owned) / keepout_area >= 0.9
                    for owned in block.source_math_bboxes
                ):
                    continue
                # MuPDF removes a text object when a redaction intersects its
                # extracted bbox, not only its painted ink. Keep the original
                # CMEX delete boundary for carving, while restoration and
                # layout continue to use the normalized visible atom boxes.
                candidates.append(
                    (keepout, raw_keepout, group, normalized_hit or raw_delete_hit)
                )
        selected = {
            index
            for index, (keepout, _, _, direct_hit) in enumerate(candidates)
            if direct_hit
            or any(
                bbox_intersection_area(keepout, existing)
                / max(0.1, bbox_area(keepout))
                >= 0.9
                for existing in (block.keepout_bboxes or [])
            )
        }
        # A single visual formula row is sometimes split across neighboring
        # PDF text objects.  The object touching the prose segment becomes a
        # keepout, but an immediately following object can otherwise remain
        # unprotected (IPMF's product operator and conditional-Gaussian body
        # are a real example).  Grow only through tightly adjacent runs on the
        # same baseline; stacked or merely nearby equations stay independent.
        changed = True
        while selected and changed:
            changed = False
            for index, (keepout, _, _, _) in enumerate(candidates):
                if index in selected:
                    continue
                height = max(1.0, keepout[3] - keepout[1])
                for selected_index in selected:
                    neighbor = candidates[selected_index][0]
                    neighbor_height = max(1.0, neighbor[3] - neighbor[1])
                    vertical_overlap = min(keepout[3], neighbor[3]) - max(
                        keepout[1], neighbor[1]
                    )
                    horizontal_gap = max(
                        keepout[0] - neighbor[2],
                        neighbor[0] - keepout[2],
                        0.0,
                    )
                    if (
                        vertical_overlap
                        >= 0.6 * min(height, neighbor_height)
                        and horizontal_gap
                        <= max(3.0, 0.35 * min(height, neighbor_height))
                    ):
                        selected.add(index)
                        changed = True
                        break
        hits = [
            raw_keepout if raw_keepout != keepout else keepout
            for index, (keepout, raw_keepout, _, _) in enumerate(candidates)
            if index in selected
        ]
        atom_groups = [
            group
            for index, (_, _, group, _) in enumerate(candidates)
            if index in selected and group
        ]
        if hits:
            block.keepout_bboxes = list(
                dict.fromkeys([*(block.keepout_bboxes or []), *hits])
            )
        if atom_groups:
            block.keepout_formula_atom_groups = tuple(
                dict.fromkeys(
                    [*block.keepout_formula_atom_groups, *atom_groups]
                )
            )
            if (
                block.block_type == "formula_prose"
                and block.flow_inline_math
                and block.nowrap
                and block.preserve_position
                and not block.source_math_bboxes
            ):
                block.redaction_formula_restore_groups = tuple(
                    dict.fromkeys(
                        [
                            *block.redaction_formula_restore_groups,
                            *atom_groups,
                        ]
                    )
                )


def detect_image_zones(
    page: object,
    graphic_regions: Optional[Sequence[BBox]] = None,
) -> List[BBox]:
    """Detect visual regions and extend them to include nearby captions.

    Returns a list of bboxes representing figure+caption zones.
    """
    zones: List[BBox] = []
    for img in page.get_images():
        try:
            rect = page.get_image_bbox(img)
            if rect and rect.is_empty is False and rect.is_valid:
                # Extend zone downward to include nearby captions
                pad = _IMAGE_ZONE_CAPTION_GAP
                zones.append((
                    rect.x0 - pad,
                    rect.y0,
                    rect.x1 + pad,
                    rect.y1 + pad * 3,
                ))
        except Exception:
            continue
    zones.extend(
        graphic_regions_for_page(page)
        if graphic_regions is None
        else graphic_regions
    )
    if not zones:
        return []
    return merge_nearby_bboxes(zones, _IMAGE_ZONE_CAPTION_GAP)


def detect_columns(blocks: List[TextBlock]) -> List[Tuple[float, float]]:
    """Detect single/two-column layout from block x0 positions.

    Returns list of (left_margin, col_width) tuples, sorted by left_margin.
    """
    import statistics as _stats

    x0_weighted: Dict[float, float] = {}
    x0_to_widths: Dict[float, List[float]] = {}

    for block in blocks:
        if block.block_type in ("equation", "algorithm", "footer"):
            continue
        x0, y0, x1, y1 = block.bbox
        width = x1 - x0
        if width < 30:
            continue
        text_len = len(block.text.strip())
        x0_rounded = round(x0, 0)
        x0_weighted[x0_rounded] = x0_weighted.get(x0_rounded, 0) + text_len
        x0_to_widths.setdefault(x0_rounded, []).append(round(width, 0))

    if not x0_weighted:
        return []

    sorted_x0s = sorted(x0_weighted, key=x0_weighted.get, reverse=True)
    primary_x0 = sorted_x0s[0]

    # Look for a second column > _COLUMN_CLUSTER_GAP away
    for x0 in sorted_x0s[1:]:
        if abs(x0 - primary_x0) > _COLUMN_CLUSTER_GAP:
            columns = []
            column_xs = sorted([primary_x0, x0])
            for index, x in enumerate(column_xs):
                widths = x0_to_widths[x]
                bounded_widths = []
                if index + 1 < len(column_xs):
                    max_column_width = column_xs[index + 1] - x - 4.0
                    bounded_widths = [w for w in widths if w <= max_column_width]
                full_widths = [w for w in widths if w > 300]
                widths_to_use = bounded_widths or full_widths or widths
                col_w = float(_stats.mode(widths_to_use))
                columns.append((float(x), col_w))
            return columns

    # Single column
    all_widths = [w for ws in x0_to_widths.values() for w in ws]
    full_widths = [w for w in all_widths if w > 300]
    widths_to_use = full_widths or all_widths
    col_width = float(_stats.mode(widths_to_use))
    # Long indented lists can outweigh surrounding prose by character count.
    # In a single-column page the true column margin is the left-most cluster
    # that still carries full-width blocks, not the most verbose indent.
    near_full_width_x0s = [
        x0
        for x0, widths in x0_to_widths.items()
        if any(width >= col_width - 12.0 for width in widths)
    ]
    column_left = min(near_full_width_x0s) if near_full_width_x0s else primary_x0
    return [(float(column_left), col_width)]


def _block_in_zone(bbox: BBox, zone: BBox) -> bool:
    """Check if a block's bbox overlaps significantly with a zone."""
    bx0, by0, bx1, by1 = bbox
    zx0, zy0, zx1, zy1 = zone
    ox0 = max(bx0, zx0)
    oy0 = max(by0, zy0)
    ox1 = min(bx1, zx1)
    oy1 = min(by1, zy1)
    overlap_area = max(0, ox1 - ox0) * max(0, oy1 - oy0)
    block_area = max(1, (bx1 - bx0) * (by1 - by0))
    return overlap_area / block_area > 0.3


_TABLE_COMPONENT_MAX_VERTICAL_GAP = 110.0
_TABLE_COMPONENT_HORIZONTAL_PAD = 48.0
_TABLE_CAPTION_MAX_ABOVE_GAP = 80.0
_TABLE_CAPTION_MAX_BELOW_GAP = 40.0
_TABLE_CAPTION_FRAGMENT_MAX_GAP = 60.0
_TABLE_CAPTION_RE = re.compile(r"^\s*(?:table\b|tab\.\s*)", re.IGNORECASE)
_TABLE_HEADER_TERMS_RE = re.compile(
    r"\b(?:hyperparameters?|notation|values?|rewards?|expressions?|weights?|"
    r"tasks?|methods?|models?|datasets?|metrics?|scores?|accuracy|success|rate|"
    r"precision|recall|average|avg|baselines?|settings?|configurations?|"
    r"training|regimes?|signals?|domains?|famil(?:y|ies)|init(?:ialization)?|"
    r"unsat(?:isfied)?|reduction|solved|variables?|inference|loss|solver|"
    r"overall|median|win|time|neural|random|polarity|capture|instances?|labels?|"
    r"mean|acc(?:uracy)?|dispersion|status|gap|supervised|sup)\b",
    re.IGNORECASE,
)
_FORMATTED_DATASET_EXAMPLE_CAPTION_RE = re.compile(
    r"^\s*(?:figure|fig\.)\s+\S+\s*:\s*(?:"
    r"formatted\s+dataset\s+example\b|"
    r"model\s+samples?\s+on\s+(?:a|the)\s+prompt\b|"
    r"complete\s+instructions?\s+given\s+to\s+labelers?\b|"
    r"[^:\n]{2,80}:\s*prompting,\s*examples?,\s*and\s+dataset\s+features\b)",
    re.IGNORECASE,
)


def _is_strong_uncaptioned_table_component(component: Sequence[BBox]) -> bool:
    """Recognize a dense cell grid when its caption is labelled as a figure."""
    if len(component) < 8:
        return False
    rows: List[List[BBox]] = []
    for bbox in sorted(component, key=lambda item: (item[1], item[0])):
        for row in rows:
            if any(_bboxes_share_y_band(bbox, existing) for existing in row):
                row.append(bbox)
                break
        else:
            rows.append([bbox])
    dense_rows = [row for row in rows if len(row) >= 3]
    if len(dense_rows) < 3:
        return False
    region = union_bbox(component)
    return region[2] - region[0] >= 120.0 and region[3] - region[1] >= 24.0


def _table_region_bboxes(blocks: Sequence[TextBlock]) -> List[BBox]:
    """Return connected table envelopes with caption or strong cell-grid evidence."""
    table_blocks = sorted(
        (block for block in blocks if block.block_type == "table"),
        key=lambda block: (block.bbox[1], block.bbox[0]),
    )
    if not table_blocks:
        return []
    caption_blocks = [block for block in blocks if block.block_type == "caption"]
    table_captions = [
        block
        for block in caption_blocks
        if _TABLE_CAPTION_RE.match(strip_sentinels(block.text))
    ]

    components: List[List[BBox]] = []
    for group in _partition_table_blocks_by_caption(table_blocks, table_captions):
        current: List[BBox] = []
        current_bottom = 0.0
        for block in group:
            caption_between = current and any(
                caption.bbox[1] >= current_bottom and caption.bbox[3] <= block.bbox[1]
                for caption in caption_blocks
            )
            if current and (
                block.bbox[1] - current_bottom > _TABLE_COMPONENT_MAX_VERTICAL_GAP
                or caption_between
            ):
                components.append(current)
                current = []
            current.append(block.bbox)
            current_bottom = (
                max(current_bottom, block.bbox[3])
                if len(current) > 1
                else block.bbox[3]
            )
        if current:
            components.append(current)

    regions: List[BBox] = []
    for component in components:
        for sub_component in _split_table_component_columns(component):
            region = union_bbox(sub_component)
            anchors = [
                caption
                for caption in table_captions
                if (
                    (
                        caption.bbox[3] <= region[1]
                        and region[1] - caption.bbox[3] <= _TABLE_CAPTION_MAX_ABOVE_GAP
                    )
                    or (
                        caption.bbox[1] >= region[3]
                        and caption.bbox[1] - region[3] <= _TABLE_CAPTION_MAX_BELOW_GAP
                    )
                )
                and caption.bbox[0] < region[2]
                and caption.bbox[2] > region[0]
            ]
            if anchors:
                anchor = min(
                    anchors,
                    key=lambda caption: (
                        region[1] - caption.bbox[3]
                        if caption.bbox[3] <= region[1]
                        else caption.bbox[1] - region[3]
                    ),
                )
                regions.append(
                    (
                        min(region[0], anchor.bbox[0]),
                        region[1],
                        max(region[2], anchor.bbox[2]),
                        region[3],
                    )
                )
            elif _is_strong_uncaptioned_table_component(sub_component):
                regions.append(region)
    return regions


def _formatted_dataset_example_region_bboxes(
    page: object,
    blocks: Sequence[TextBlock],
) -> List[BBox]:
    """Protect rule-bounded dataset payloads while leaving captions translatable."""
    figure_blocks = sorted(
        (
            block
            for block in blocks
            if re.match(
                r"^\s*(?:figure|fig\.)\s+\S+\s*:",
                strip_sentinels(block.text),
                re.IGNORECASE,
            )
        ),
        key=lambda block: block.bbox[1],
    )
    sample_captions = [
        block
        for block in figure_blocks
        if _FORMATTED_DATASET_EXAMPLE_CAPTION_RE.match(
            strip_sentinels(block.text)
        )
    ]
    if not sample_captions:
        return []

    horizontal_rules: List[BBox] = []
    for drawing in _page_drawings(page):
        rect = drawing.get("rect")
        if rect is None:
            continue
        rule = (
            float(rect.x0),
            float(rect.y0),
            float(rect.x1),
            float(rect.y1),
        )
        if rule[2] - rule[0] >= 180.0 and rule[3] - rule[1] <= 2.5:
            horizontal_rules.append(rule)

    regions: List[BBox] = []
    for caption in sample_captions:
        previous_caption_bottom = max(
            (
                candidate.bbox[3]
                for candidate in figure_blocks
                if candidate.bbox[3] < caption.bbox[1]
            ),
            default=0.0,
        )
        candidates = [
            rule
            for rule in horizontal_rules
            if previous_caption_bottom < (rule[1] + rule[3]) / 2.0 < caption.bbox[1]
        ]
        if len(candidates) < 2:
            continue
        bottom_rule = max(candidates, key=lambda rule: rule[1])
        aligned = [
            rule
            for rule in candidates
            if abs(rule[0] - bottom_rule[0]) <= 8.0
            and abs(rule[2] - bottom_rule[2]) <= 8.0
        ]
        if len(aligned) < 2:
            continue
        top = min(rule[1] for rule in aligned)
        bottom = max(rule[3] for rule in aligned)
        if caption.bbox[1] - bottom > 20.0 or bottom - top < 20.0:
            continue
        regions.append(
            (
                min(rule[0] for rule in aligned),
                top,
                max(rule[2] for rule in aligned),
                bottom,
            )
        )
    return regions


def _rule_bounded_sample_table_regions(
    page: object,
    blocks: Sequence[TextBlock],
) -> List[BBox]:
    """Protect sample tables whose rows are separated only by long rules.

    Long-form prompt and generation appendices often use booktabs-style
    horizontal rules without a ``Table N`` caption or vertical grid.  Their
    payload is verbatim evaluation data, not paper prose.  Require a repeated,
    aligned rule family and split it at real section headings so ordinary page
    rules and prose between adjacent tables remain translatable.
    """
    page_width = float(page.rect.width)
    min_rule_width = max(180.0, page_width * 0.55)
    rules: List[BBox] = []
    for drawing in _page_drawings(page):
        rect = drawing.get("rect")
        if rect is None:
            continue
        rule = (
            float(rect.x0),
            float(rect.y0),
            float(rect.x1),
            float(rect.y1),
        )
        if rule[2] - rule[0] >= min_rule_width and rule[3] - rule[1] <= 2.5:
            rules.append(rule)
    if len(rules) < 3:
        return []

    families: List[List[BBox]] = []
    for rule in sorted(rules, key=lambda item: (item[0], item[2], item[1])):
        for family in families:
            median_left = statistics.median(item[0] for item in family)
            median_right = statistics.median(item[2] for item in family)
            if abs(rule[0] - median_left) <= 8.0 and abs(rule[2] - median_right) <= 8.0:
                family.append(rule)
                break
        else:
            families.append([rule])

    regions: List[BBox] = []
    for family in families:
        ordered = sorted(family, key=lambda item: item[1])
        if len(ordered) < 3:
            continue
        segments: List[List[BBox]] = [[]]
        for previous, rule in zip(ordered, ordered[1:]):
            gap_headings = [
                block
                for block in blocks
                if previous[3] + 3.0 < block.bbox[1]
                and block.bbox[3] < rule[1] - 3.0
                and re.match(
                    r"^\s*(?:[A-Z]\.)?\d+(?:\.\d+)+\s+[A-Z]",
                    " ".join(strip_sentinels(block.text).split()),
                )
            ]
            segments[-1].append(previous)
            if gap_headings:
                segments.append([])
        segments[-1].append(ordered[-1])

        for segment in segments:
            if len(segment) < 3:
                continue
            x0 = min(rule[0] for rule in segment)
            x1 = max(rule[2] for rule in segment)
            y0 = min(rule[1] for rule in segment)
            y1 = max(rule[3] for rule in segment)
            if y1 - y0 < 40.0:
                continue
            contents = [
                block
                for block in blocks
                if block.block_type != "caption"
                and x0 - 4.0 <= (block.bbox[0] + block.bbox[2]) / 2.0 <= x1 + 4.0
                and y0 <= (block.bbox[1] + block.bbox[3]) / 2.0 <= y1
            ]
            if len(contents) < 2:
                continue
            caption_anchored = any(
                _TABLE_CAPTION_RE.match(strip_sentinels(block.text))
                and block.bbox[0] < x1
                and block.bbox[2] > x0
                and (
                    0.0 <= y0 - block.bbox[3] <= _TABLE_CAPTION_MAX_ABOVE_GAP
                    or 0.0 <= block.bbox[1] - y1 <= _TABLE_CAPTION_MAX_BELOW_GAP
                )
                for block in blocks
            )
            if caption_anchored:
                # Numbered academic tables already have stronger cell/grid
                # ownership and rule QA. This fallback is only for uncatalogued
                # prompt/sample payloads.
                continue
            content_text = " ".join(strip_sentinels(block.text) for block in contents)
            sample_cue = bool(
                re.search(r"\buse\s+case\s+example\b", content_text, re.IGNORECASE)
                or re.search(
                    r"\bgenerated\s+(?:poem|text|sample|completion|response|output)\b",
                    content_text,
                    re.IGNORECASE,
                )
                or (
                    re.search(r"\bcontext\s*(?:→|->|:)\s*", content_text, re.IGNORECASE)
                    and re.search(
                        r"\b(?:generated|completion|response|output)\b",
                        content_text,
                        re.IGNORECASE,
                    )
                )
                or (
                    re.search(r"\bhuman\s*:", content_text, re.IGNORECASE)
                    and re.search(r"\b(?:AI|assistant)\s*:", content_text, re.IGNORECASE)
                )
            )
            if not sample_cue:
                continue
            regions.append((x0, y0, x1, y1))
    return list(dict.fromkeys(regions))


def _vector_table_region_bboxes(
    page: object,
    blocks: Sequence[TextBlock],
) -> List[BBox]:
    """Return caption-anchored table grids missed by text classification.

    Some PDFs expose every table cell as an ordinary prose block. Their vector
    rules still form an unambiguous connected grid, so use that geometry as a
    conservative fallback. Requiring an explicit Table caption avoids treating
    chart frames and generic diagrams as preserved tables.
    """
    captions = [
        block
        for block in blocks
        if block.block_type == "caption"
        and _TABLE_CAPTION_RE.match(strip_sentinels(block.text))
    ]
    if not captions:
        return []

    horizontal: List[List[float]] = []
    vertical: List[List[float]] = []
    vertical_fragments: List[List[float]] = []
    for drawing in _page_drawings(page):
        rect = drawing.get("rect")
        if rect is None:
            continue
        x0, y0, x1, y1 = (float(rect.x0), float(rect.y0), float(rect.x1), float(rect.y1))
        width = x1 - x0
        height = y1 - y0
        if width >= 80.0 and height <= 2.5:
            horizontal.append([x0, (y0 + y1) / 2.0, x1])
        elif height >= 8.0 and width <= 2.5:
            segment = [(x0 + x1) / 2.0, y0, y1]
            vertical_fragments.append(segment)
            if height >= 12.0:
                vertical.append(segment)

    def merge_collinear(
        segments: List[List[float]],
        *,
        horizontal_axis: bool,
    ) -> List[List[float]]:
        merged: List[List[float]] = []
        join_gap = (
            2.5
            if horizontal_axis or len(horizontal) < 5 or not captions
            else 14.0
        )
        for segment in sorted(segments, key=lambda item: (item[1], item[0])):
            coordinate = segment[1] if horizontal_axis else segment[0]
            start = segment[0] if horizontal_axis else segment[1]
            end = segment[2]
            for existing in merged:
                existing_coordinate = existing[1] if horizontal_axis else existing[0]
                existing_start = existing[0] if horizontal_axis else existing[1]
                if abs(coordinate - existing_coordinate) > 1.0:
                    continue
                if start > existing[2] + join_gap or existing_start > end + join_gap:
                    continue
                if horizontal_axis:
                    existing[0] = min(existing[0], start)
                    existing[2] = max(existing[2], end)
                else:
                    existing[1] = min(existing[1], start)
                    existing[2] = max(existing[2], end)
                break
            else:
                merged.append(list(segment))
        return merged

    horizontal = merge_collinear(horizontal, horizontal_axis=True)
    vertical = merge_collinear(vertical, horizontal_axis=False)
    horizontal_only_regions: List[BBox] = []
    long_horizontal = sorted(
        (segment for segment in horizontal if segment[2] - segment[0] >= 180.0),
        key=lambda item: item[1],
    )
    for top, bottom in zip(long_horizontal, long_horizontal[1:]):
        if not 20.0 <= bottom[1] - top[1] <= 520.0:
            continue
        if abs(top[0] - bottom[0]) > 8.0 or abs(top[2] - bottom[2]) > 8.0:
            continue
        x0 = min(top[0], bottom[0])
        x1 = max(top[2], bottom[2])
        y0, y1 = top[1], bottom[1]
        if any(
            x0 - 2.5 <= x <= x1 + 2.5
            and min(y1, vertical_bottom) - max(y0, vertical_top) > 2.5
            for x, vertical_top, vertical_bottom in vertical_fragments
        ):
            continue
        anchors = [
            caption
            for caption in captions
            if caption.bbox[0] < x1
            and caption.bbox[2] > x0
            and (
                0.0 <= y0 - caption.bbox[3] <= _TABLE_CAPTION_MAX_ABOVE_GAP
                or 0.0
                <= caption.bbox[1] - y1
                <= _TABLE_CAPTION_MAX_BELOW_GAP + 40.0
            )
        ]
        cell_blocks = [
            block
            for block in blocks
            if block.block_type != "caption"
            and x0 <= (block.bbox[0] + block.bbox[2]) / 2.0 <= x1
            and y0 <= (block.bbox[1] + block.bbox[3]) / 2.0 <= y1
        ]
        page_rect = getattr(page, "rect", None)
        page_height = float(getattr(page_rect, "height", 0.0) or 0.0)
        footer_rule_with_following_section = bool(
            page_height > 0.0
            and y1 >= page_height * 0.90
            and any(
                block.block_type in {"heading", "run_in_heading"}
                and y0 <= (block.bbox[1] + block.bbox[3]) / 2.0 <= y1
                for block in cell_blocks
            )
        )
        if footer_rule_with_following_section:
            continue
        if anchors and len(cell_blocks) >= 3:
            horizontal_only_regions.append((x0, y0, x1, y1))
    if len(horizontal) >= 3:
        groups: List[List[List[float]]] = []
        for segment in sorted(horizontal, key=lambda item: item[1]):
            for group in groups:
                previous = group[-1]
                if (
                    segment[1] - previous[1] <= 90.0
                    and not any(
                        previous[1] + 2.0
                        < (caption.bbox[1] + caption.bbox[3]) / 2.0
                        < segment[1] - 2.0
                        for caption in captions
                    )
                    and abs(segment[0] - statistics.median(item[0] for item in group))
                    <= 8.0
                    and abs(segment[2] - statistics.median(item[2] for item in group))
                    <= 8.0
                ):
                    group.append(segment)
                    break
            else:
                groups.append([segment])
        for group in groups:
            if len(group) < 3:
                continue
            widths = [segment[2] - segment[0] for segment in group]
            if min(widths) / max(max(widths), 1.0) < 0.85:
                continue
            x0 = min(segment[0] for segment in group)
            x1 = max(segment[2] for segment in group)
            y0 = min(segment[1] for segment in group)
            y1 = max(segment[1] for segment in group)
            if any(
                x0 - 2.5 <= x <= x1 + 2.5
                and vy0 <= y0 + 2.5
                and vy1 >= y1 - 2.5
                for x, vy0, vy1 in vertical
            ):
                # A local spanning vertical belongs to the regular grid path
                # below. Ignore unrelated chart axes elsewhere on the page.
                continue
            anchors = [
                caption
                for caption in captions
                if caption.bbox[0] < x1
                and caption.bbox[2] > x0
                and (
                    (
                        caption.bbox[1] <= y0
                        and -20.0
                        <= y0 - caption.bbox[3]
                        <= _TABLE_CAPTION_MAX_ABOVE_GAP
                    )
                    or 0.0
                    <= caption.bbox[1] - y1
                    <= _TABLE_CAPTION_MAX_BELOW_GAP + 40.0
                )
            ]
            cell_blocks = [
                block
                for block in blocks
                if block.block_type != "caption"
                and x0 <= (block.bbox[0] + block.bbox[2]) / 2.0 <= x1
                and y0 <= (block.bbox[1] + block.bbox[3]) / 2.0 <= y1
            ]
            if anchors and len(cell_blocks) >= 3:
                horizontal_only_regions.append((x0, y0, x1, y1))
    single_separator_grid = bool(
        len(horizontal) >= 5
        and len(vertical) == 1
        and sum(
            vertical[0][1] - 3.0 <= y <= vertical[0][2] + 3.0
            and x0 - 3.0 <= vertical[0][0] <= x1 + 3.0
            for x0, y, x1 in horizontal
        )
        >= 5
    )
    if len(horizontal) < 2 or (len(vertical) < 2 and not single_separator_grid):
        return horizontal_only_regions

    nodes = [("h", index) for index in range(len(horizontal))]
    nodes.extend(("v", index) for index in range(len(vertical)))
    adjacency = {node: set() for node in nodes}
    for h_index, (x0, y, x1) in enumerate(horizontal):
        for v_index, (x, y0, y1) in enumerate(vertical):
            if x0 - 2.5 <= x <= x1 + 2.5 and y0 - 2.5 <= y <= y1 + 2.5:
                adjacency[("h", h_index)].add(("v", v_index))
                adjacency[("v", v_index)].add(("h", h_index))

    regions: List[BBox] = list(horizontal_only_regions)
    unseen = set(nodes)
    while unseen:
        start = unseen.pop()
        component = {start}
        pending = [start]
        while pending:
            node = pending.pop()
            for neighbor in adjacency[node]:
                if neighbor not in component:
                    component.add(neighbor)
                    unseen.discard(neighbor)
                    pending.append(neighbor)
        h_indexes = [index for kind, index in component if kind == "h"]
        v_indexes = [index for kind, index in component if kind == "v"]
        component_single_separator = bool(
            len(h_indexes) >= 5
            and len(v_indexes) == 1
            and vertical[v_indexes[0]][1]
            <= min(horizontal[index][1] for index in h_indexes) + 3.0
            and vertical[v_indexes[0]][2]
            >= max(horizontal[index][1] for index in h_indexes) - 3.0
        )
        if len(h_indexes) < 2 or (
            len(v_indexes) < 2 and not component_single_separator
        ):
            continue
        x0 = min(horizontal[index][0] for index in h_indexes)
        x1 = max(horizontal[index][2] for index in h_indexes)
        y0 = min(vertical[index][1] for index in v_indexes)
        y1 = max(vertical[index][2] for index in v_indexes)
        region = (x0, y0, x1, y1)
        anchors = [
            caption
            for caption in captions
            if caption.bbox[0] < x1
            and caption.bbox[2] > x0
            and (
                0.0 <= y0 - caption.bbox[3] <= _TABLE_CAPTION_MAX_ABOVE_GAP
                or 0.0 <= caption.bbox[1] - y1 <= _TABLE_CAPTION_MAX_BELOW_GAP + 40.0
            )
        ]
        cell_blocks = [
            block
            for block in blocks
            if block.block_type != "caption"
            and x0 <= (block.bbox[0] + block.bbox[2]) / 2.0 <= x1
            and y0 <= (block.bbox[1] + block.bbox[3]) / 2.0 <= y1
        ]
        if anchors and len(cell_blocks) >= 3:
            regions.append(region)
    return regions


def _partition_table_blocks_by_caption(
    table_blocks: Sequence[TextBlock],
    table_captions: Sequence[TextBlock],
) -> List[List[TextBlock]]:
    """Assign table blocks to the x-band of their owning caption.

    Side-by-side tables (two captions at the same y with disjoint x-ranges)
    would otherwise chain into a single vertical component whose envelope
    swallows the prose around both tables. With fewer than two captions
    there is nothing to partition.
    """
    if len(table_captions) < 2:
        return [list(table_blocks)]
    captions = sorted(table_captions, key=lambda caption: caption.bbox[0])
    groups: List[List[TextBlock]] = [[] for _ in captions]
    for block in table_blocks:
        bx0, _, bx1, _ = block.bbox
        best_index = 0
        best_score = float("-inf")
        for index, caption in enumerate(captions):
            cx0, _, cx1, _ = caption.bbox
            overlap = min(bx1, cx1) - max(bx0, cx0)
            # Prefer the caption whose band the block overlaps; fall back to
            # the horizontally nearest one (negative distance).
            score = overlap if overlap > 0 else -(min(abs(bx0 - cx1), abs(cx0 - bx1)))
            if score > best_score:
                best_score = score
                best_index = index
        groups[best_index].append(block)
    return [group for group in groups if group]


def _split_table_component_columns(component: Sequence[BBox]) -> List[List[BBox]]:
    """Split side-by-side tables chained into one vertical component.

    Two tables printed in separate columns connect through the vertical-gap
    rule, and their union envelope swallows the prose around them (a QA
    false positive when that prose is translated). Row spans expose the
    gutter: rows whose x-spans never intersect belong to different tables.
    """
    rows: List[List[BBox]] = []
    for bbox in sorted(component, key=lambda b: ((b[1] + b[3]) / 2.0, b[0])):
        for row in rows:
            if any(_bboxes_share_y_band(bbox, existing) for existing in row):
                row.append(bbox)
                break
        else:
            rows.append([bbox])
    clusters: List[List[object]] = []
    for row in rows:
        row_x0 = min(b[0] for b in row)
        row_x1 = max(b[2] for b in row)
        for cluster in clusters:
            overlap = min(row_x1, cluster[1]) - max(row_x0, cluster[0])
            narrower_width = min(row_x1 - row_x0, cluster[1] - cluster[0])
            # A small incidental overlap is common when a right-column
            # figure header starts shortly below a wide table. Requiring a
            # substantial shared x-band keeps genuine full/short table rows
            # connected while preventing the figure labels from extending
            # the caption-anchored table envelope into adjacent body prose.
            if overlap / max(narrower_width, 1.0) >= 0.60:
                cluster[0] = min(cluster[0], row_x0)
                cluster[1] = max(cluster[1], row_x1)
                cluster[2].extend(row)
                break
        else:
            clusters.append([row_x0, row_x1, list(row)])
    return [cluster[2] for cluster in clusters]


def _bboxes_share_y_band(first: BBox, second: BBox) -> bool:
    min_height = min(first[3] - first[1], second[3] - second[1])
    if min_height <= 0:
        return False
    overlap = min(first[3], second[3]) - max(first[1], second[1])
    return overlap >= 0.5 * min_height


def _looks_like_table_header_text(text: str) -> bool:
    terms = {match.group(0).lower() for match in _TABLE_HEADER_TERMS_RE.finditer(text)}
    if len(terms) >= 2:
        return True
    parameter_fields = re.findall(
        r"\b(?:num_[a-z0-9_]+|d_[a-z0-9_]+|[a-z]/[a-z]\s+size|flops?)\b",
        text,
        re.IGNORECASE,
    )
    return bool(
        re.search(r"\bparameters?\b", text, re.IGNORECASE)
        and len(parameter_fields) >= 2
    )


def _promote_borderless_captioned_table_blocks(
    blocks: Sequence[TextBlock],
    table_captions: Sequence[TextBlock],
) -> None:
    """Preserve aligned multi-column tables that expose no vector rules."""
    excluded_types = {
        "algorithm",
        "bibliography",
        "caption",
        "equation",
        "figure_label",
        "footer",
        "heading",
        "metadata",
        "table",
    }
    for caption in table_captions:
        candidates = [
            block
            for block in blocks
            if block.block_type not in excluded_types
            and block.source_lines <= 2
            and block.font_size <= caption.font_size + 1.0
            and caption.bbox[1] - 90.0 <= block.bbox[1]
            and block.bbox[3] <= caption.bbox[1]
            and block.bbox[0] < caption.bbox[2]
            and block.bbox[2] > caption.bbox[0]
        ]
        rows: List[List[TextBlock]] = []
        for block in sorted(candidates, key=lambda item: (item.bbox[1], item.bbox[0])):
            center_y = (block.bbox[1] + block.bbox[3]) / 2.0
            for row in rows:
                row_center = statistics.median(
                    (item.bbox[1] + item.bbox[3]) / 2.0 for item in row
                )
                if abs(center_y - row_center) <= 2.0:
                    row.append(block)
                    break
            else:
                rows.append([block])
        dense_rows = [row for row in rows if len(row) >= 3]
        numeric_rows = [
            row
            for row in dense_rows
            if sum(
                bool(_PRESERVED_NUMERIC_TOKEN_RE.search(strip_sentinels(item.text)))
                for item in row
            )
            >= 2
        ]
        if len(dense_rows) < 3 or len(numeric_rows) < 2:
            continue
        column_centers = sorted(
            (item.bbox[0] + item.bbox[2]) / 2.0 for item in dense_rows[0]
        )
        aligned_rows = [
            row
            for row in dense_rows
            if all(
                any(
                    abs((item.bbox[0] + item.bbox[2]) / 2.0 - center) <= 45.0
                    for item in row
                )
                for center in column_centers[:3]
            )
        ]
        if len(aligned_rows) < 3:
            continue
        for row in aligned_rows:
            for block in row:
                block.block_type = "table"
                block.should_translate = False
                block.preserve_position = True
                block.nowrap = True
                block.no_merge = True


def _promote_adjacent_table_rows(
    blocks: Sequence[TextBlock],
    table_captions: Sequence[TextBlock],
) -> None:
    """Extend a captioned table through split rows next to its known cells."""
    excluded_types = {
        "algorithm",
        "bibliography",
        "caption",
        "equation",
        "figure_label",
        "footer",
        "heading",
        "metadata",
        "table",
    }
    for _ in range(3):
        table_regions = _table_region_bboxes(blocks)
        promoted = False
        for region in table_regions:
            anchors = [
                caption
                for caption in table_captions
                if min(caption.bbox[2], region[2])
                - max(caption.bbox[0], region[0])
                > 0.35 * min(
                    caption.bbox[2] - caption.bbox[0],
                    region[2] - region[0],
                )
                and (
                    0.0 <= region[1] - caption.bbox[3] <= 90.0
                    or 0.0 <= caption.bbox[1] - region[3] <= 50.0
                )
            ]
            if not anchors:
                continue
            caption = min(
                anchors,
                key=lambda item: min(
                    abs(region[1] - item.bbox[3]),
                    abs(item.bbox[1] - region[3]),
                ),
            )
            candidates = [
                block
                for block in blocks
                if block.block_type not in excluded_types
                and block.source_lines <= 8
                and block.font_size <= caption.font_size + 1.0
                and min(block.bbox[2], region[2])
                - max(block.bbox[0], region[0])
                > 0.0
                and max(
                    block.bbox[1] - region[3],
                    region[1] - block.bbox[3],
                    0.0,
                )
                <= 60.0
            ]
            rows: List[List[TextBlock]] = []
            for block in sorted(
                candidates,
                key=lambda item: (item.bbox[1], item.bbox[0]),
            ):
                for row in rows:
                    if any(_bboxes_share_y_band(block.bbox, item.bbox) for item in row):
                        row.append(block)
                        break
                else:
                    rows.append([block])
            for row in rows:
                row_bbox = union_bbox([block.bbox for block in row])
                row_overlap = min(row_bbox[2], region[2]) - max(
                    row_bbox[0], region[0]
                )
                row_width = max(row_bbox[2] - row_bbox[0], 1.0)
                row_gap = max(
                    row_bbox[1] - region[3],
                    region[1] - row_bbox[3],
                    0.0,
                )
                is_parallel_row = (
                    row_gap <= 8.0
                    and len(row) >= 2
                    and row_overlap >= 0.65 * row_width
                )
                is_header_row = (
                    row_gap <= 8.0
                    and len(row) == 1
                    and _looks_like_table_header_text(
                        strip_sentinels(row[0].text)
                    )
                )
                if not (is_parallel_row or is_header_row):
                    continue
                for block in row:
                    block.block_type = "table"
                    block.should_translate = False
                    block.preserve_position = True
                    block.nowrap = True
                    block.no_merge = True
                    promoted = True
        if not promoted:
            break


def _promote_table_component_blocks(blocks: Sequence[TextBlock]) -> None:
    """Preserve table headers and group labels split from detected cell rows."""
    table_captions = [
        block
        for block in blocks
        if block.block_type == "caption"
        and _TABLE_CAPTION_RE.match(strip_sentinels(block.text))
    ]

    _promote_borderless_captioned_table_blocks(blocks, table_captions)

    excluded_types = {
        "algorithm",
        "bibliography",
        "caption",
        "equation",
        "figure_label",
        "footer",
        "heading",
        "metadata",
        "table",
    }

    # A ruled or borderless table body may already be split into protected
    # cells while its header remains one prose block containing parallel cell
    # lines. Promote that header from the table geometry itself; an explicit
    # caption is not required (symbol-definition tables commonly omit one).
    table_blocks = [block for block in blocks if block.block_type == "table"]
    for block in blocks:
        if block.block_type in excluded_types or not _has_parallel_header_cell_lines(block):
            continue
        nearby_cells = [
            cell
            for cell in table_blocks
            if 0.0 <= cell.bbox[1] - block.bbox[3] <= 28.0
            and cell.bbox[0] < block.bbox[2] + _TABLE_COMPONENT_HORIZONTAL_PAD
            and cell.bbox[2] > block.bbox[0] - _TABLE_COMPONENT_HORIZONTAL_PAD
        ]
        # A compact table body is often one protected block holding every
        # row; that single multi-row neighbour is as good as two cells.
        multi_row_body = any(cell.source_lines >= 3 for cell in nearby_cells)
        if len(nearby_cells) < 2 and not multi_row_body:
            continue
        nearby_union = union_bbox([cell.bbox for cell in nearby_cells])
        overlap = min(block.bbox[2], nearby_union[2]) - max(
            block.bbox[0], nearby_union[0]
        )
        if overlap < 0.45 * min(
            block.bbox[2] - block.bbox[0],
            nearby_union[2] - nearby_union[0],
        ):
            continue
        block.block_type = "table"
        block.should_translate = False
        block.preserve_position = True
        block.nowrap = True
        block.no_merge = True
        table_blocks.append(block)

    # Formula-heavy tables may expose only one textual header cell while all
    # neighboring cells are protected as equations. Anchor that orphan cell
    # directly to the explicit Table caption before computing table regions.
    for block in blocks:
        if block.block_type in excluded_types:
            continue
        plain = " ".join(strip_sentinels(block.text).split())
        words = _PROSE_WORD_RE.findall(plain)
        anchors_above = [
            caption
            for caption in table_captions
            if 0.0 <= block.bbox[1] - caption.bbox[3] <= 24.0
            and max(
                caption.bbox[0] - block.bbox[2],
                block.bbox[0] - caption.bbox[2],
                0.0,
            )
            <= _TABLE_COMPONENT_HORIZONTAL_PAD
        ]
        if not anchors_above:
            continue
        caption = max(anchors_above, key=lambda item: item.bbox[3])
        caption_width = max(1.0, caption.bbox[2] - caption.bbox[0])
        block_width = block.bbox[2] - block.bbox[0]
        is_orphan_header = (
            bool(plain)
            and len(words) <= 8
            and block.source_lines <= 3
            and block_width <= caption_width * 0.65
            and block.font_size <= caption.font_size + 0.75
            and not re.search(r"[.!?。！？]\s*$", plain)
            and (
                bool(_TABLE_HEADER_TERMS_RE.search(plain))
                or bool(re.search(r"\d", plain))
            )
        )
        if is_orphan_header:
            block.block_type = "table"
            block.should_translate = False
            block.preserve_position = True
            block.nowrap = True
            block.no_merge = True

    _promote_adjacent_table_rows(blocks, table_captions)

    table_regions = _table_region_bboxes(blocks)
    if not table_regions:
        return

    for block in blocks:
        if block.block_type in excluded_types:
            continue
        plain = " ".join(strip_sentinels(block.text).split())
        if not plain:
            continue
        for region in table_regions:
            horizontal_gap = max(region[0] - block.bbox[2], block.bbox[0] - region[2], 0.0)
            if horizontal_gap > _TABLE_COMPONENT_HORIZONTAL_PAD:
                continue
            center_x = (block.bbox[0] + block.bbox[2]) / 2.0
            center_y = (block.bbox[1] + block.bbox[3]) / 2.0
            center_inside_table = bbox_contains_point(region, center_x, center_y)
            if center_inside_table:
                block_area = max(bbox_area(block.bbox), 1.0)
                region_coverage = bbox_intersection_area(block.bbox, region) / block_area
                if (
                    (len(plain) > 180 or block.source_lines > 4)
                    and region_coverage < 0.65
                ):
                    # A full-width table band can cross the center of a long
                    # paragraph in one column. Only promote long text when
                    # most of its own box is actually enclosed by the table.
                    continue
                block.block_type = "table"
                block.should_translate = False
                block.preserve_position = True
                block.nowrap = True
                block.no_merge = True
                break
            if len(plain) > 180 or block.source_lines > 4:
                continue
            overlaps_vertically = block.bbox[1] < region[3] and block.bbox[3] > region[1]
            header_gap = region[1] - block.bbox[3]
            is_header = 0.0 <= header_gap <= 20.0 and _looks_like_table_header_text(plain)
            group_gap = block.bbox[1] - region[3]
            region_width = max(1.0, region[2] - region[0])
            block_width = block.bbox[2] - block.bbox[0]
            words = _PROSE_WORD_RE.findall(plain)
            is_group_label_after = (
                0.0 <= group_gap <= 24.0
                and block_width <= region_width * 0.5
                and len(words) <= 8
                and not re.search(r"[.!?。！？]\s*$", plain)
            )
            anchors_above = [
                caption
                for caption in table_captions
                if caption.bbox[3] <= block.bbox[1]
                and region[1] - caption.bbox[3] <= _TABLE_CAPTION_MAX_ABOVE_GAP
                and block.bbox[1] - caption.bbox[3]
                <= _TABLE_CAPTION_FRAGMENT_MAX_GAP
            ]
            is_caption_table_fragment = (
                bool(anchors_above)
                and block.bbox[3] <= region[1]
                and 0.0 <= header_gap <= _TABLE_CAPTION_MAX_BELOW_GAP
                and block_width <= region_width * 0.65
                and len(words) <= 8
                and not re.search(r"[.!?。！？]\s*$", plain)
                and (
                    bool(_TABLE_HEADER_TERMS_RE.search(plain))
                    or bool(re.search(r"\d", plain))
                )
                and block.font_size
                <= max(caption.font_size for caption in anchors_above) + 0.75
            )
            # A block beside the region qualifies only as an overflowing
            # cell: it must actually touch the region horizontally (the
            # 48pt pad covers above/below attachment, not a column gutter)
            # and must not read like a prose paragraph.
            is_side_cell_overflow = (
                overlaps_vertically
                and horizontal_gap <= 8.0
                and substantial_prose_word_count(plain) < TABLE_HEADER_PROSE_WORD_LIMIT
            )
            if (
                not is_side_cell_overflow
                and not is_header
                and not is_group_label_after
                and not is_caption_table_fragment
            ):
                continue
            block.block_type = "table"
            block.should_translate = False
            block.preserve_position = True
            block.nowrap = True
            block.no_merge = True
            break


def _looks_like_document_title(
    block: TextBlock,
    plain: str,
    blocks: Sequence[TextBlock],
    page_index: int,
    page_height: float,
) -> bool:
    """Identify the primary first-page title from source typography."""
    if (
        page_index != 0
        or not 12 <= len(plain) <= 240
        or not 1 <= block.source_lines <= 4
        or block.bbox[1] > page_height * 0.20
        or _CAPTION_RE.match(plain)
        or _REFERENCES_HEADING_RE.match(plain)
    ):
        return False
    top_blocks = [
        candidate
        for candidate in blocks
        if candidate.bbox[1] <= page_height * 0.28
        and candidate.block_type not in {"footer", "figure_label"}
    ]
    if not top_blocks:
        return False
    top_size = max(candidate.font_size for candidate in top_blocks)
    body_sizes = [
        candidate.font_size
        for candidate in blocks
        if candidate.bbox[1] > block.bbox[3]
        and candidate.source_lines >= 2
        and len(strip_sentinels(candidate.text)) >= 80
    ]
    if not body_sizes:
        return False
    body_size = statistics.median(body_sizes)
    return (
        block.font_size >= top_size - 0.25
        and block.font_size >= max(11.0, body_size + 1.5)
    )


def classify_blocks(
    blocks: List[TextBlock],
    page_index: int,
    page_height: float,
    image_zones: List[BBox],
) -> None:
    """Classify blocks by semantic type. Modifies blocks in-place.

    Priority order:
    1. Equation zone → equation (should_translate=False)
    2. Algorithm → algorithm (should_translate=False)
    3. Academic structure label → heading
    4. First-page primary title → title
    5. Inside image zone + short label → figure_label (should_translate=False)
    6. Caption pattern → caption (preserve_position=True)
    7. Bold + numbered + short → heading
    8. Bibliography → bibliography (should_translate=False)
    9. Footer → footer (should_translate=False)
    10. Otherwise → body
    """
    numbered_list_block_ids: set[int] = set()
    numbered_candidates: List[Tuple[TextBlock, List[int]]] = []
    for candidate in blocks:
        compact = " ".join(strip_sentinels(candidate.text).split()).strip()
        marker_numbers = [
            int(value)
            for value in re.findall(
                r"(?:^|[,;]\s+)(\d{1,2})\.\s+(?=[A-Za-z])",
                compact,
            )
        ]
        if marker_numbers and marker_numbers == list(
            range(marker_numbers[0], marker_numbers[0] + len(marker_numbers))
        ):
            numbered_candidates.append((candidate, marker_numbers))
    for (previous, previous_numbers), (current, current_numbers) in zip(
        numbered_candidates,
        numbered_candidates[1:],
    ):
        vertical_gap = current.bbox[1] - previous.bbox[3]
        if (
            current_numbers[0] == previous_numbers[-1] + 1
            and abs(current.bbox[0] - previous.bbox[0]) <= 6.0
            and abs(current.font_size - previous.font_size) <= 0.5
            and -4.0
            <= vertical_gap
            <= max(18.0, min(current.font_size, previous.font_size) * 2.0)
        ):
            numbered_list_block_ids.update((id(previous), id(current)))

    for block in blocks:
        text = block.text.strip()
        plain = " ".join(strip_sentinels(text).split())
        x0, y0, x1, y1 = block.bbox
        caption_match = bool(_CAPTION_RE.match(plain)) and not (
            _looks_like_split_caption_reference(block, plain, blocks)
        )

        # A references heading is a cross-page structure anchor. It must win
        # over run-in-heading and nearby figure-zone classification so the
        # following entries stay outside translation and terminology audits.
        if _REFERENCES_HEADING_RE.match(plain):
            _is_bibliography_context(block, blocks)
            block.block_type = "heading"
            block.should_translate = True
            block.bold = True
            block.no_merge = True
            block.preserve_position = True
            continue

        if id(block) in numbered_list_block_ids:
            if _bibliography_seen and _is_bibliography_context(block, blocks):
                block.block_type = "bibliography"
                block.should_translate = False
                block.preserve_position = True
            else:
                block.block_type = "body"
                block.should_translate = True
                block.bold = False
                block.no_merge = True
                block.preserve_position = False
            continue

        # Pre-segmented appendix headings still delimit the bibliography.
        # Update that cross-page state before the heading fast paths below.
        if _bibliography_seen and _looks_like_appendix_heading(
            plain,
            block.source_lines,
        ):
            _is_bibliography_context(block, blocks)

        # Extraction may pre-classify a wrapped author lead as a run-in
        # heading.  Bibliography ownership has higher priority than that
        # typographic hint; otherwise the fast path below reopens translation
        # in the middle of a reference entry or its next column.
        if (
            block.block_type == "run_in_heading"
            or _looks_like_reference_author_line(plain)
        ) and _is_bibliography_context(block, blocks):
            block.block_type = "bibliography"
            block.should_translate = False
            block.preserve_position = True
            continue

        if block.block_type == "run_in_heading" and _looks_like_fragmented_byline_metadata(
            block,
            plain,
            blocks,
        ):
            block.block_type = "metadata"
            block.should_translate = False
            block.preserve_position = True
            continue

        if block.bold_prefix and _ACADEMIC_FORMULA_STATEMENT_RE.match(plain):
            # The source typography owns only the theorem/proposition label.
            # Preserve that range-level role while keeping the statement in
            # the same flowing block; setting ``bold`` here would spill the
            # label weight across the complete translated statement.
            block.block_type = "run_in_heading"
            block.should_translate = True
            block.bold = False
            block.no_merge = True
            block.preserve_position = False
            continue

        if block.block_type == "run_in_heading" and re.fullmatch(
            r"(?:[A-Z](?:\.\d+)?|\d+(?:\.\d+)*)\s+[A-Z][A-Z\s-]{3,80}",
            plain,
        ):
            block.block_type = "heading"
            block.should_translate = True
            block.bold = True
            block.no_merge = True
            block.preserve_position = True
            continue

        if block.block_type == "run_in_heading":
            block.should_translate = True
            block.bold = True
            block.no_merge = True
            block.preserve_position = True
            continue

        if block.block_type == "table" and block.nowrap and block.no_merge:
            # Caption-pattern text ("Table 4: ...", "Figure 2: ...") is never
            # a table cell even when its record looked tabular — captions must
            # always be translated, and QA flags any left in English.
            if caption_match:
                block.block_type = "caption"
                block.preserve_position = True
                block.should_translate = True
                block.bold_prefix = block.bold_prefix or bool(block.bold_terms)
                continue
            block.should_translate = False
            block.preserve_position = True
            continue

        if looks_like_author_metadata(
            block, plain
        ) or _looks_like_fragmented_byline_metadata(block, plain, blocks):
            block.block_type = "metadata"
            block.should_translate = False
            block.preserve_position = True
            continue

        if (
            block.font_size >= 8.8
            and _looks_like_appendix_heading(
                plain,
                block.source_lines,
            )
            and (
                not _bibliography_seen
                or _bibliography_ended
                or _is_structural_bibliography_terminator(
                    block,
                    plain,
                    _bibliography_heading_size,
                )
            )
        ):
            # Small-caps appendix titles are often split into mixed-size,
            # non-bold spans. Their semantic role must win over the aggregate
            # span weight so the translated title keeps the source hierarchy.
            # Author leads of wrapped reference entries ("R. Mohammad Ebrahim
            # and J. Razmi.") share the lettered-heading shape but must stay
            # inside the bibliography range.
            block.block_type = "heading"
            block.should_translate = True
            block.bold = True
            block.no_merge = True
            block.preserve_position = True
            continue

        # Already classified as equation by native engine
        if getattr(block, "_equation_zone", False):
            block.block_type = "equation"
            block.should_translate = False
            continue

        # Formula-leading prose fragments are extracted with redaction boxes
        # limited to the normal-font suffix. Preserve that decision even when
        # the fragment happens to sit in the page footer band.
        if block.block_type == "formula_prose":
            # A reference title may begin with a math-font model name (for
            # example ``π0: A vision-language-action flow model ...``).  The
            # extraction pass then labels its normal-font suffix as formula
            # prose, but bibliography ownership must still win once the
            # References range is active.
            if _is_bibliography_context(block, blocks):
                block.block_type = "bibliography"
                block.should_translate = False
                block.preserve_position = True
                continue
            if _looks_like_piecewise_formula_condition(block, plain):
                block.block_type = "equation"
                block.should_translate = False
                block.preserve_position = True
                continue
            block.should_translate = True
            block.preserve_position = not block.flow_inline_math
            continue

        if looks_like_academic_structure_heading(block, plain):
            block.block_type = "heading"
            block.should_translate = True
            block.bold = True
            block.no_merge = True
            block.preserve_position = True
            continue

        if _looks_like_document_title(block, plain, blocks, page_index, page_height):
            block.block_type = "title"
            block.should_translate = True
            block.no_merge = True
            block.preserve_position = False
            continue

        if looks_like_preserved_diagram_label(text):
            block.block_type = "figure_label"
            block.should_translate = False
            block.preserve_position = True
            continue

        # Inside image zone
        in_image = any(_block_in_zone(block.bbox, z) for z in image_zones)
        if in_image:
            if (
                _has_parallel_panel_sibling(block, blocks)
                and substantial_prose_word_count(plain) >= 8
            ):
                block.block_type = "caption"
                block.should_translate = True
                block.preserve_position = True
                continue
            if looks_like_parallel_figure_label_row(block, text):
                block.block_type = "figure_label"
                block.should_translate = False
                block.preserve_position = True
                continue
            if len(text) <= _FIGURE_LABEL_MAX_LEN and not caption_match:
                block.block_type = "figure_label"
                block.should_translate = False
                block.preserve_position = True
                continue
            # Caption inside image zone — still translate but preserve position
            if caption_match:
                block.block_type = "caption"
                block.preserve_position = True
                block.bold_prefix = block.bold_prefix or bool(block.bold_terms)
                continue

        # Caption pattern (Figure N, Table N, etc.)
        if caption_match:
            block.block_type = "caption"
            block.preserve_position = True
            block.bold_prefix = block.bold_prefix or bool(block.bold_terms)
            continue

        # Bibliography: after "References" heading
        if _is_bibliography_context(block, blocks):
            block.block_type = "bibliography"
            block.should_translate = False
            continue

        if block.block_type == "heading":
            block.should_translate = True
            if not (
                _APPENDIX_STYLE_HEADING_LINE_RE.match(plain)
                or _ROMAN_HEADING_LINE_RE.match(plain)
            ):
                block.bold = True
            block.no_merge = True
            continue

        # Heading: bold + numbered + short
        if block.bold and len(text) < 100 and _HEADING_RE.match(text):
            block.block_type = "heading"
            continue

        # Footer: near bottom of page or page number
        if y0 > page_height - _FOOTER_MAX_Y_OFFSET:
            if _FOOTER_PAGE_NUM_RE.match(text) or len(text) < 30:
                block.block_type = "footer"
                block.should_translate = False
                continue

        # Default
        block.block_type = "body"
        block.should_translate = True

    _promote_table_component_blocks(blocks)


def _looks_like_split_caption_reference(
    block: TextBlock,
    plain: str,
    blocks: Sequence[TextBlock],
) -> bool:
    """Detect a prose reference split immediately after phrases like `shown in`."""
    if re.match(
        r"^(?:Figure|Fig\.)\s*\d+\s*\([a-z]\)\.\s*"
        r"(?:Consider|Suppose|Assume|Let|Observe|Note|We)\b",
        plain,
        re.IGNORECASE,
    ):
        return True
    if not re.match(
        r"^(?:Figure|Fig\.|Table)\s*(?:\d+|[IVXLCDM]+)(?:[.:]\s+|\s+)",
        plain,
        re.IGNORECASE,
    ):
        return False
    for previous in blocks:
        if previous is block or previous.page_index != block.page_index:
            continue
        vertical_gap = block.bbox[1] - previous.bbox[3]
        if not (0.0 <= vertical_gap <= max(6.0, block.font_size * 0.7)):
            continue
        horizontal_overlap = min(block.bbox[2], previous.bbox[2]) - max(
            block.bbox[0], previous.bbox[0]
        )
        if horizontal_overlap <= 0.0:
            continue
        previous_plain = " ".join(strip_sentinels(previous.text).split()).rstrip()
        if re.search(
            r"\b(?:shown|reported|presented|illustrated|summari[sz]ed|listed|given|"
            r"demonstrated(?:\s+qualitatively)?)\s+in$",
            previous_plain,
            re.IGNORECASE,
        ):
            return True
    return False


def _looks_like_piecewise_formula_condition(block: TextBlock, plain: str) -> bool:
    """Keep short branch labels inside a display equation unchanged."""
    if plain.casefold().rstrip(".:") not in {"if", "otherwise", "else", "when"}:
        return False
    if block.source_lines != 1 or not block.nowrap or not block.no_merge:
        return False
    if block.bbox[2] - block.bbox[0] > 80.0:
        return False
    if not block.keepout_bboxes:
        return True
    return any(
        bbox_share_y_band(block.bbox, keepout)
        and max(keepout[0] - block.bbox[2], block.bbox[0] - keepout[2], 0.0)
        <= max(6.0, block.font_size * 0.75)
        for keepout in block.keepout_bboxes
    )


def _looks_like_fragmented_byline_metadata(
    block: TextBlock,
    plain: str,
    blocks: Sequence[TextBlock],
) -> bool:
    """Recognize author or affiliation fragments split into narrow PDF records."""
    if block.page_index != 0 or block.bbox[1] > 260.0:
        return False
    compact = " ".join(strip_sentinels(plain).split()).strip()
    if not compact:
        return False

    # This helper is for fragmented byline bands, not tall abstract/body
    # columns that happen to mention title-cased model names.  Large author
    # walls are handled by ``looks_like_author_metadata`` before this path.
    if block.bbox[3] - block.bbox[1] > 90.0:
        return False

    byline_name_re = re.compile(
        r"\b(?:[A-Z][A-Za-z'’-]+|[A-Z]\.)"
        r"(?:\s+(?:[A-Z][A-Za-z'’-]+|[A-Z]\.)){1,3}\b"
    )
    affiliation_re = re.compile(
        r"\b(?:univer\w*|institu\w*|depart\w*|school|college|laborator\w*|lab|"
        r"research|technolog\w*)\b",
        re.IGNORECASE,
    )
    if block.font_size <= 12.5 and block.bbox[1] >= 105.0:
        own_names = byline_name_re.findall(compact)
        nearby_names = 0
        own_affiliation = bool(affiliation_re.search(compact))
        own_contact = "@" in compact
        band_has_affiliation = own_affiliation
        band_has_contact = own_contact
        for other in blocks:
            if other.page_index != 0 or other.font_size > 12.5:
                continue
            if other.bbox[1] > 250.0 or other.bbox[3] < 120.0:
                continue
            other_plain = " ".join(strip_sentinels(other.text).split())
            nearby_names += len(byline_name_re.findall(other_plain))
            band_has_affiliation = band_has_affiliation or bool(
                affiliation_re.search(other_plain)
            )
            band_has_contact = band_has_contact or "@" in other_plain
        if (
            own_names
            and nearby_names >= 3
            and (band_has_affiliation or band_has_contact)
        ) or (
            (own_affiliation or own_contact)
            and nearby_names >= 2
            and block.bbox[3] <= 250.0
        ):
            return True

    if re.match(r"^\d+\s*", compact) and re.search(
        r"\b(?:university|institute|department|school|college|laboratory|lab)\b",
        compact,
        re.IGNORECASE,
    ):
        return True

    candidate = compact.lstrip(", ")
    if not re.fullmatch(
        r"[A-Z][A-Za-z-]+(?:\s+[A-Z][A-Za-z-]+){1,3}",
        candidate,
    ):
        return False
    if block.bbox[1] < 105.0 or block.bbox[1] > 190.0:
        return False

    peers = 0
    for other in blocks:
        if other is block or other.page_index != block.page_index:
            continue
        if abs(other.bbox[1] - block.bbox[1]) > 2.5:
            continue
        other_plain = " ".join(strip_sentinels(other.text).split()).strip().lstrip(", ")
        if re.fullmatch(
            r"[A-Z][A-Za-z-]+(?:\s+[A-Z][A-Za-z-]+){1,3}",
            other_plain,
        ):
            peers += 1
    return peers >= 2


def looks_like_academic_structure_heading(block: TextBlock, plain: str) -> bool:
    """Recognize standalone theorem labels and bold procedural step headings.

    Dense vector theorem boxes can be mistaken for figures or equation tables.
    Requiring a bold, normal-size, one-line label keeps diagram annotations and
    compact table cells on the preservation path.
    """
    compact = " ".join(strip_sentinels(plain).split()).strip()
    if (
        not compact
        or len(compact) > 120
        or not block.bold
        or block.source_lines > 2
        or block.font_size < 8.8
    ):
        return False
    return bool(
        _ACADEMIC_LABEL_HEADING_RE.fullmatch(compact)
        or _ACADEMIC_STEP_HEADING_RE.fullmatch(compact)
    )


# Track whether we've seen a "References" heading per page
_bibliography_seen: Dict[int, bool] = {}
_bibliography_heading_size: float = 0.0
_bibliography_ended: bool = False


_CHECKLIST_HEADING_RE = re.compile(
    r"^(?:neurips\s+|icml\s+|iclr\s+)?paper\s+checklist$", re.IGNORECASE
)
_CHECKLIST_PROSE_RE = re.compile(
    r"\b(?:Question|Answer|Justification|Guidelines)\s*:", re.IGNORECASE
)


def _is_structural_bibliography_terminator(
    block: TextBlock,
    text: str,
    bibliography_heading_size: float,
) -> bool:
    """Require structural evidence before leaving a bibliography range."""
    compact = " ".join(text.split()).strip()
    if _CHECKLIST_HEADING_RE.match(compact):
        return True
    if _APPENDIX_HEADING_RE.match(compact) or _POST_BIBLIOGRAPHY_SECTION_RE.fullmatch(
        compact
    ):
        return True
    if not _looks_like_appendix_heading(compact, block.source_lines):
        return False
    if _looks_like_reference_entry_text(compact) or _looks_like_reference_author_line(
        compact
    ):
        return False
    if re.search(r"[,;]|\b(?:editors?|eds?\.)\b", compact, re.IGNORECASE):
        return False
    if block.bold or block.font_size >= max(bibliography_heading_size * 0.92, 10.5):
        return True
    appendix_match = _APPENDIX_LETTER_HEADING_RE.match(compact)
    appendix_words = (
        _PROSE_WORD_RE.findall(appendix_match.group(1)) if appendix_match else []
    )
    return bool(block.source_lines <= 2 and 1 <= len(appendix_words) <= 4)


def _is_bibliography_context(block: TextBlock, all_blocks: List[TextBlock]) -> bool:
    """Check if block is in the bibliography section.

    Bibliography starts after a "References" heading and ends at the next
    appendix/supplement/checklist heading.
    """
    global _bibliography_heading_size, _bibliography_ended
    raw_text = block.text.strip()

    # Check if this block IS the references heading
    if _REFERENCES_HEADING_RE.match(raw_text):
        _bibliography_seen[block.page_index] = True
        _bibliography_heading_size = block.font_size
        _bibliography_ended = False
        return False  # The heading itself is translatable

    # Headings that end the bibliography range must be recognized before the
    # reference-entry shortcut: the checklist heading satisfies the
    # reference-entry heuristics itself. Other termination cues (appendix /
    # bold headings) must NOT fire on reference-entry-looking lines such as
    # "H. Wallach," inside actual bibliography entries.
    if _bibliography_seen:
        if _is_structural_bibliography_terminator(
            block,
            raw_text,
            _bibliography_heading_size,
        ):
            _bibliography_ended = True
        elif not _looks_like_reference_entry_text(raw_text):
            # Fallback: bold section headings also end the range.
            bib_size_threshold = max(_bibliography_heading_size * 0.92, 10.5)
            if block.bold and block.font_size >= bib_size_threshold:
                if _SECTION_NUM_RE.match(raw_text) or len(raw_text) < 60:
                    _bibliography_ended = True

    if _bibliography_ended:
        return False

    # Checklist prose (Question/Answer/Justification structure) is never a
    # reference entry, even when a merged block starts with "5. Open access
    # to data and code" style numbering.
    if _CHECKLIST_PROSE_RE.search(raw_text):
        return False

    explicit_numbered_entries = len(
        re.findall(r"(?:^|\s)\[\d{1,3}\]", raw_text)
    )
    standalone_reference = bool(
        (len(raw_text) <= 520 or explicit_numbered_entries >= 2)
        and (
            re.match(r"^\s*\[\d+\]", raw_text)
            or _REFERENCE_YEAR_RE.search(raw_text)
            or _REFERENCE_FRAGMENT_CUE_RE.search(raw_text)
            or re.search(
                r"\b(?:doi|arxiv|https?://)\b",
                raw_text,
                re.IGNORECASE,
            )
        )
    )
    if _looks_like_reference_entry_text(raw_text) and (
        bool(_bibliography_seen) or standalone_reference
    ):
        return True

    # Check if we've seen references heading on a previous page or earlier on this page
    if _bibliography_seen.get(block.page_index, False):
        return True
    # Check previous pages
    for pi in range(block.page_index):
        if _bibliography_seen.get(pi, False):
            return True
    return False


@dataclass
class _LineRec:
    text: str  # sentinel-annotated line text
    bbox: BBox
    spans: List[dict]  # kept spans (gutter/empty spans removed)
    is_cell: bool = False  # piece of a physical line split at column gaps
    math_bboxes: List[BBox] = field(default_factory=list)
    prose_bboxes: List[BBox] = field(default_factory=list)
    math_run_bboxes: List[BBox] = field(default_factory=list)


@dataclass
class _RawBlockRec:
    lines: List[_LineRec]
    detached_inline_scripts: bool = False
    flow_inline_math: bool = False

    @property
    def bbox(self) -> BBox:
        return union_bbox([line.bbox for line in self.lines])

    def bare_text(self) -> str:
        return strip_sentinels(" ".join(line.text for line in self.lines))

    def compact_length(self) -> int:
        return len("".join(self.bare_text().split()))

    def sentinel_ratio(self) -> float:
        compact = self.compact_length()
        if compact == 0:
            return 1.0
        inside = sum(sentinel_char_count(line.text) for line in self.lines)
        return inside / compact


def _promote_detached_inline_formula_scripts(lines: Sequence[_LineRec]) -> bool:
    """Reattach subscripts emitted as the next physical PDF line.

    TeX can expose ``c^tau_in`` as a math-bearing line ending at ``c^tau``
    followed by a 7pt ordinary-font ``in`` at the start of the next line.
    Treating that fragment as prose splits one paragraph into several tiny
    translation units. Geometry, size, and a trailing math run together make
    this distinguishable from a real wrapped sentence starting with "in".
    """
    promoted = False
    for previous, current in zip(lines, lines[1:]):
        if not previous.math_run_bboxes or not current.spans:
            continue
        candidate = next(
            (
                span
                for span in current.spans
                if normalize_span_text(span.get("text", "")).strip()
            ),
            None,
        )
        if candidate is None or "bbox" not in candidate:
            continue
        candidate_text = normalize_span_text(candidate.get("text", "")).strip()
        if not re.fullmatch(r"[A-Za-z0-9]{1,12}", candidate_text):
            continue
        candidate_bbox = tuple(float(value) for value in candidate["bbox"])
        if candidate_bbox not in current.prose_bboxes:
            continue
        previous_run = previous.math_run_bboxes[-1]
        previous_size = max(
            (
                float(span.get("size", 0.0))
                for span in previous.spans
                if normalize_span_text(span.get("text", "")).strip()
            ),
            default=0.0,
        )
        candidate_size = float(candidate.get("size", previous_size))
        previous_center = (previous_run[1] + previous_run[3]) / 2.0
        candidate_center = (candidate_bbox[1] + candidate_bbox[3]) / 2.0
        horizontal_overlap = min(previous_run[2], candidate_bbox[2]) - max(
            previous_run[0], candidate_bbox[0]
        )
        if (
            previous_size <= 0.0
            or candidate_size >= previous_size * 0.85
            or horizontal_overlap < min(1.0, (candidate_bbox[2] - candidate_bbox[0]) * 0.2)
            or candidate_bbox[0] < previous_run[0] - 1.0
            or candidate_center <= previous_center + max(0.7, previous_size * 0.12)
        ):
            continue

        raw_prefix = normalize_span_text(candidate.get("text", ""))
        prefix_index = current.text.find(raw_prefix)
        if prefix_index < 0 or current.text[:prefix_index].strip():
            continue
        script = _format_script_fragment(candidate_text, "sub")
        previous.text += SENTINEL_OPEN + script + SENTINEL_CLOSE
        previous.spans.append(candidate)
        previous.math_bboxes.append(candidate_bbox)
        previous.math_run_bboxes[-1] = union_bbox(
            [previous.math_run_bboxes[-1], candidate_bbox]
        )
        previous.bbox = union_bbox([previous.bbox, candidate_bbox])

        current.text = current.text[prefix_index + len(raw_prefix) :].lstrip()
        current.spans = [span for span in current.spans if span is not candidate]
        current.prose_bboxes = [
            bbox for bbox in current.prose_bboxes if bbox != candidate_bbox
        ]
        remaining_bboxes = [
            tuple(float(value) for value in span["bbox"])
            for span in current.spans
            if "bbox" in span
        ]
        if remaining_bboxes:
            current.bbox = union_bbox(remaining_bboxes)
        promoted = True
    return promoted


def _span_is_isolated(span: dict, siblings: Sequence[dict]) -> bool:
    """True when no other non-empty span sits horizontally adjacent to `span`.

    Formula sub/superscripts always touch their base glyphs; gutter line
    numbers are standalone text objects with clear air around them."""
    bbox = span.get("bbox")
    if not bbox:
        return True
    x0, y0, x1, y1 = (float(value) for value in bbox)
    for other in siblings:
        if other is span or "bbox" not in other:
            continue
        if not normalize_span_text(other.get("text", "")).strip():
            continue
        ox0, oy0, ox1, oy1 = (float(value) for value in other["bbox"])
        if min(y1, oy1) - max(y0, oy0) < -1.0:
            continue
        gap = max(ox0 - x1, x0 - ox1)
        if gap < LINE_NUMBER_NEIGHBOR_GAP:
            return False
    return True


def _span_horizontal_gap(first: dict, second: dict) -> float:
    if "bbox" not in first or "bbox" not in second:
        return float("inf")
    x0, y0, x1, y1 = (float(value) for value in first["bbox"])
    ox0, oy0, ox1, oy1 = (float(value) for value in second["bbox"])
    if min(y1, oy1) - max(y0, oy0) < -1.0:
        return float("inf")
    return max(ox0 - x1, x0 - ox1)


def _span_is_math_neighbor(span: dict, line_max_size: float) -> bool:
    text = normalize_span_text(span.get("text", ""))
    if not text.strip():
        return False
    flags = int(span.get("flags", 0))
    font = str(span.get("font", ""))
    size = float(span.get("size", line_max_size))
    if is_math_span(font, flags, text, size, line_max_size):
        return True
    if any(char in MATH_SYMBOLS for char in text):
        return True
    return False


def _span_is_adjacent_math_script(
    span_index: int,
    spans: Sequence[dict],
    *,
    line_max_size: float,
) -> bool:
    span = spans[span_index]
    text = normalize_span_text(span.get("text", "")).strip()
    if not text or line_max_size <= 0:
        return False
    size = float(span.get("size", line_max_size))
    if size >= line_max_size * 0.85:
        return False
    # Multi-letter subscripts in papers include "recent", "init", "video",
    # "action"; long prose fragments should not become math.
    if not re.fullmatch(r"[A-Za-z0-9+\-=(),.]{1,12}", text):
        return False
    if not re.search(r"[A-Za-z0-9]", text) and not any(char in MATH_SYMBOLS for char in text):
        return False
    for neighbor_index in (span_index - 1, span_index + 1):
        if neighbor_index < 0 or neighbor_index >= len(spans):
            continue
        neighbor = spans[neighbor_index]
        if _span_horizontal_gap(span, neighbor) > LINE_NUMBER_NEIGHBOR_GAP:
            continue
        if _span_is_math_neighbor(neighbor, line_max_size):
            return True
        neighbor_text = normalize_span_text(neighbor.get("text", "")).strip()
        neighbor_size = float(neighbor.get("size", line_max_size))
        if (
            re.fullmatch(r"[A-Za-z]", neighbor_text)
            and neighbor_size >= line_max_size * 0.85
            and "bbox" in span
            and "bbox" in neighbor
        ):
            span_center = (float(span["bbox"][1]) + float(span["bbox"][3])) / 2.0
            neighbor_center = (
                float(neighbor["bbox"][1]) + float(neighbor["bbox"][3])
            ) / 2.0
            if abs(span_center - neighbor_center) >= max(0.8, line_max_size * 0.08):
                return True
    return False


def _span_is_prose_word_fragment(
    span_index: int,
    spans: Sequence[dict],
    *,
    line_max_size: float,
) -> bool:
    """Keep short italic prose out of formula placeholders.

    TeX PDFs sometimes split the final letter of an italic theorem word into
    its own span (``ga`` + ``p``), which otherwise looks exactly like a
    single-letter math variable. Full-size connector words such as ``as`` are
    also prose even when the theorem font is italic.
    """
    span = spans[span_index]
    text = normalize_span_text(span.get("text", ""))
    stripped = text.strip()
    if not stripped or MATH_FONT_RE.search(str(span.get("font", ""))):
        return False
    size = float(span.get("size", line_max_size))
    if line_max_size > 0 and size < line_max_size * 0.85:
        return False
    fragmented_word = _fragmented_prose_word(span_index, spans, line_max_size)
    if (
        len(fragmented_word) >= 3
        or fragmented_word.casefold() in _SHORT_PROSE_WORDS
    ):
        return True
    if stripped.lower() in _SHORT_PROSE_WORDS and len(stripped) >= 2:
        return True
    if not re.fullmatch(r"[A-Za-z]{1,2}", stripped):
        return False

    for neighbor_index in (span_index - 1, span_index + 1):
        if neighbor_index < 0 or neighbor_index >= len(spans):
            continue
        neighbor = spans[neighbor_index]
        neighbor_text = normalize_span_text(neighbor.get("text", ""))
        if MATH_FONT_RE.search(str(neighbor.get("font", ""))):
            continue
        neighbor_size = float(neighbor.get("size", line_max_size))
        if abs(neighbor_size - size) > max(0.8, line_max_size * 0.12):
            continue
        if _span_horizontal_gap(span, neighbor) > 0.8:
            continue
        if neighbor_index < span_index:
            neighbor_piece = re.search(r"([A-Za-z]{2,})$", neighbor_text)
            joined = (neighbor_piece.group(1) if neighbor_piece else "") + stripped
        else:
            neighbor_piece = re.match(r"([A-Za-z]{2,})", neighbor_text)
            joined = stripped + (neighbor_piece.group(1) if neighbor_piece else "")
        if len(joined) >= 3:
            return True
    return False


def _fragmented_prose_word(
    span_index: int,
    spans: Sequence[dict],
    line_max_size: float,
) -> str:
    """Rejoin a word split into same-style full-size PDF spans."""
    anchor = spans[span_index]
    anchor_font = str(anchor.get("font", ""))
    anchor_size = float(anchor.get("size", line_max_size))
    left = span_index
    right = span_index

    def compatible(first: dict, second: dict) -> bool:
        if str(second.get("font", "")) != anchor_font:
            return False
        second_size = float(second.get("size", line_max_size))
        if abs(second_size - anchor_size) > max(0.8, line_max_size * 0.12):
            return False
        return _span_horizontal_gap(first, second) <= 0.8

    while left > 0:
        current_text = normalize_span_text(spans[left].get("text", ""))
        previous_text = normalize_span_text(spans[left - 1].get("text", ""))
        if current_text[:1].isspace() or previous_text[-1:].isspace():
            break
        if not compatible(spans[left], spans[left - 1]):
            break
        if not re.search(r"[A-Za-z´`^'-]$", previous_text):
            break
        left -= 1
    while right + 1 < len(spans):
        current_text = normalize_span_text(spans[right].get("text", ""))
        following_text = normalize_span_text(spans[right + 1].get("text", ""))
        if current_text[-1:].isspace() or following_text[:1].isspace():
            break
        if not compatible(spans[right], spans[right + 1]):
            break
        if not re.match(r"[A-Za-z´`^'-]", following_text):
            break
        right += 1

    joined = "".join(
        normalize_span_text(span.get("text", "")) for span in spans[left : right + 1]
    ).strip()
    words = _latin_prose_words(joined)
    return "".join(words) if words else ""


def _formula_like_plain_span_text(text: str) -> bool:
    """Return whether a normal-font span is formula syntax rather than prose."""
    stripped = text.strip()
    if not stripped or len(stripped) > 80:
        return False
    short_words = re.findall(r"[A-Za-z]{2,}", stripped)
    if len(short_words) >= 2 and all(
        word.lower() in _SHORT_PROSE_WORDS for word in short_words
    ):
        # Formula expansion walks across adjacent plain-font spans. Without
        # this guard, a connector such as ``to be`` between U_B and sigma is
        # absorbed into one protected math run and can never be translated.
        return False
    wordish = re.sub(r"^[^A-Za-z]+|[^A-Za-z]+$", "", stripped).lower()
    if len(wordish) > 1 and wordish in _SHORT_PROSE_WORDS:
        return False
    words = _PROSE_WORD_RE.findall(stripped)
    if any(len(word) > 2 and word.lower() not in _MATH_WORDS for word in words):
        return False
    if re.fullmatch(r"[\s.,:;(){}\[\]]+", stripped):
        return True
    if re.fullmatch(
        r"(?i)(?:in|at|by|from|see)?\s*"
        r"(?:eqs?|equations?|figs?|figures?|tables?|appendix)\.?\s*"
        r"[A-Za-z0-9.(),\-\s]+",
        stripped,
    ):
        return False
    if re.search(r"[=<>+−±×÷≈≤≥^_\\|/*]", stripped):
        return True
    return bool(
        len(words) <= 1
        and re.fullmatch(r"[A-Za-z0-9\s.,:;(){}\[\]%]+", stripped)
        and re.search(r"[A-Za-z0-9]", stripped)
    )


def _expanded_math_span_indexes(
    spans: Sequence[dict],
    seed_indexes: Sequence[int],
    line_max_size: float,
) -> set[int]:
    """Include adjacent normal-font numeric/operator spans in a formula run."""
    expanded = set(seed_indexes)
    citation_indexes = _plain_numeric_citation_span_indexes(spans, line_max_size)
    for index, span in enumerate(spans):
        if index in expanded or "bbox" not in span:
            continue
        accent = normalize_span_text(span.get("text", "")).strip()
        if accent not in {"ˆ", "˜", "¯", "ˇ", "˙"}:
            continue
        accent_box = span["bbox"]
        accent_width = max(0.01, float(accent_box[2]) - float(accent_box[0]))
        accent_height = max(0.01, float(accent_box[3]) - float(accent_box[1]))
        for math_index in seed_indexes:
            math_span = spans[math_index]
            if "bbox" not in math_span:
                continue
            math_box = math_span["bbox"]
            math_width = max(0.01, float(math_box[2]) - float(math_box[0]))
            math_height = max(0.01, float(math_box[3]) - float(math_box[1]))
            x_overlap = max(
                0.0,
                min(float(accent_box[2]), float(math_box[2]))
                - max(float(accent_box[0]), float(math_box[0])),
            )
            y_overlap = max(
                0.0,
                min(float(accent_box[3]), float(math_box[3]))
                - max(float(accent_box[1]), float(math_box[1])),
            )
            if (
                x_overlap >= min(accent_width, math_width) * 0.35
                and y_overlap >= min(accent_height, math_height) * 0.5
            ):
                expanded.add(index)
                break
    if _citation_superscript_seed_indexes(spans, seed_indexes, line_max_size):
        # Bibliographic footnote markers use the same small math fonts as
        # exponents.  The following punctuation, author names, and years are
        # ordinary caption prose; propagating formula ownership through that
        # chain leaves most of a wrapped caption untranslated and detached.
        return expanded
    for index, span in enumerate(spans[:-1]):
        text = normalize_span_text(span.get("text", ""))
        following = spans[index + 1]
        following_text = normalize_span_text(following.get("text", ""))
        following_size = float(following.get("size", line_max_size))
        if (
            re.fullmatch(r"[A-Za-z]", text.strip())
            and re.fullmatch(r"[A-Za-z0-9]{1,12}", following_text.strip())
            and following_size < line_max_size * 0.85
            and _span_horizontal_gap(span, following) <= LINE_NUMBER_NEIGHBOR_GAP
            and "bbox" in span
            and "bbox" in following
            and abs(
                (float(span["bbox"][1]) + float(span["bbox"][3])) / 2.0
                - (float(following["bbox"][1]) + float(following["bbox"][3])) / 2.0
            )
            >= max(0.8, line_max_size * 0.08)
        ):
            # Bold vector bases such as ``x`` are often set in CMBX while the
            # numeric subscript uses ordinary CMR7, so neither span is a math
            # seed on its own. Their size/adjacency pair is unambiguous.
            expanded.update((index, index + 1))
    for index, span in enumerate(spans):
        text = normalize_span_text(span.get("text", ""))
        if _formula_like_plain_span_text(text) and re.search(
            r"[=<>+−±×÷≈≤≥^_\\|/*]",
            text,
        ):
            expanded.add(index)

    threshold = max(4.0, line_max_size * 0.65)
    changed = True
    while changed:
        changed = False
        for index, span in enumerate(spans):
            if index in expanded:
                continue
            if index in citation_indexes:
                continue
            text = normalize_span_text(span.get("text", ""))
            if not _formula_like_plain_span_text(text):
                continue
            stripped = text.strip()
            if re.fullmatch(r"[a-z]", stripped):
                split_word_neighbor = False
                if index > 0 and not text[:1].isspace():
                    previous = spans[index - 1]
                    previous_text = normalize_span_text(previous.get("text", ""))
                    split_word_neighbor = bool(
                        previous_text[-1:].isalpha()
                        and not _span_is_math_neighbor(previous, line_max_size)
                    )
                if (
                    not split_word_neighbor
                    and index + 1 < len(spans)
                    and not text[-1:].isspace()
                ):
                    following = spans[index + 1]
                    next_text = normalize_span_text(following.get("text", ""))
                    split_word_neighbor = bool(
                        next_text[:1].isalpha()
                        and not _span_is_math_neighbor(following, line_max_size)
                    )
                if split_word_neighbor:
                    continue
            if any(
                _span_horizontal_gap(span, spans[math_index]) <= threshold
                for math_index in expanded
            ):
                expanded.add(index)
                changed = True
    return expanded


def _plain_numeric_citation_span_indexes(
    spans: Sequence[dict],
    line_max_size: float,
) -> set[int]:
    """Find plain-font ``[55]. Next sentence`` citation runs.

    A math-font variable immediately before a citation is a common line-end
    shape. Formula expansion must stop at the citation instead of walking
    through its plain numeric spans and absorbing the following prose.
    """
    citation_indexes: set[int] = set()
    for start, span in enumerate(spans):
        text = normalize_span_text(span.get("text", ""))
        if not text.lstrip().startswith("[") or _span_is_math_neighbor(
            span,
            line_max_size,
        ):
            continue
        joined = ""
        for stop in range(start, min(len(spans), start + 4)):
            joined += normalize_span_text(spans[stop].get("text", ""))
            match = re.match(
                r"^\s*\[\s*\d{1,4}(?:\s*[,;\-]\s*\d{1,4})*\s*\]",
                joined,
            )
            if match is None:
                continue
            tail = joined[match.end() :]
            citation_boundary = not tail.strip() or bool(
                re.match(
                    r"^\s*(?:[.,;:]\s*(?:[A-Z]|$)|"
                    r"(?:is|are|was|were|has|have|shows?|demonstrates?)\b)",
                    tail,
                )
            )
            if citation_boundary:
                citation_indexes.update(range(start, stop + 1))
            break
    return citation_indexes


def _citation_superscript_seed_indexes(
    spans: Sequence[dict],
    seed_indexes: Sequence[int],
    line_max_size: float,
) -> set[int]:
    """Return citation-label seeds without absorbing their author-year text."""
    joined = "".join(normalize_span_text(span.get("text", "")) for span in spans)
    if (
        not re.search(r"\bet\s+al\.", joined, re.IGNORECASE)
        or not re.search(r"\b(?:19|20)\d{2}\b", joined)
        or re.search(r"[=<>+−±×÷≈≤≥^_\\|/*]", joined)
    ):
        return set()
    citation_seeds = {
        index
        for index in seed_indexes
        if re.fullmatch(
            r"[a-z]",
            normalize_span_text(spans[index].get("text", "")).strip(),
            re.IGNORECASE,
        )
        and float(spans[index].get("size", line_max_size))
        < line_max_size * 0.85
    }
    return citation_seeds


def _promote_adjacent_short_formula_lines(lines: Sequence[_LineRec]) -> None:
    """Promote detached vector bases that visually continue an operator row."""
    for line in lines:
        plain = strip_sentinels(line.text).strip()
        if SENTINEL_OPEN in line.text or not re.fullmatch(
            r"[A-Za-z][A-Za-z0-9]{0,2}", plain
        ):
            continue
        nonempty_spans = [
            span
            for span in line.spans
            if normalize_span_text(span.get("text", "")).strip()
        ]
        if not nonempty_spans or not all(
            re.search(r"(?:CMBX|CMMI|Math|STIX)", str(span.get("font", "")), re.IGNORECASE)
            for span in nonempty_spans
        ):
            continue
        line_height = max(1.0, line.bbox[3] - line.bbox[1])
        for candidate in lines:
            if candidate is line or SENTINEL_OPEN not in candidate.text:
                continue
            formula = normalize_protected_formula_fragment(
                strip_sentinels(candidate.text).strip()
            )
            if not re.match(r"^[⊙⊗⊕×⋅·*/=<>≤≥+\-−]", formula):
                continue
            horizontal_gap = candidate.bbox[0] - line.bbox[2]
            vertical_overlap = min(line.bbox[3], candidate.bbox[3]) - max(
                line.bbox[1], candidate.bbox[1]
            )
            if not 0.0 <= horizontal_gap <= max(12.0, line_height * 1.25):
                continue
            if vertical_overlap < -max(1.5, line_height * 0.2):
                continue
            line.text = SENTINEL_OPEN + plain + SENTINEL_CLOSE
            span_bboxes = [
                tuple(float(value) for value in span["bbox"])
                for span in nonempty_spans
                if "bbox" in span
            ]
            if span_bboxes:
                math_bbox = union_bbox(span_bboxes)
                line.math_bboxes = list(dict.fromkeys([*line.math_bboxes, *span_bboxes]))
                line.math_run_bboxes = [math_bbox]
                line.prose_bboxes = [
                    bbox for bbox in line.prose_bboxes if bbox not in span_bboxes
                ]
            break


def _script_position(span: dict, line_bbox: BBox, line_max_size: float) -> str:
    if "bbox" not in span or line_max_size <= 0:
        return "normal"
    _x0, y0, _x1, y1 = (float(value) for value in span["bbox"])
    line_y0, line_y1 = float(line_bbox[1]), float(line_bbox[3])
    line_center = (line_y0 + line_y1) / 2.0
    span_center = (y0 + y1) / 2.0
    if span_center > line_center + max(0.8, line_max_size * 0.06):
        return "sub"
    if span_center < line_center - max(0.8, line_max_size * 0.06):
        return "super"
    return "normal"


def _format_script_fragment(text: str, position: str) -> str:
    stripped = text.strip()
    if not stripped or position == "normal":
        return stripped
    if position == "sub":
        return "_{%s}" % stripped
    return "^{%s}" % stripped


def _normalized_extracted_math_span(span: dict) -> dict:
    """Clamp known MuPDF math-font bbox inflation to the painted glyph row.

    MuPDF 1.25 reports some 10pt CMEX accents/operators with a roughly 31pt
    descent even though their origin and visible glyph occupy one text row.
    That stale descent joins following paragraphs and turns inline formulas
    into oversized layout tokens. CMSY horizontal minus glyphs similarly use
    the font's nearly one-em descent, which can capture ink from the next text
    row when rasterized. WASY section signs are extracted as ``M`` with the
    same phantom descent. Only clamp those unmistakable shapes; legitimate
    tall extension glyphs and all other math fonts keep their extracted boxes.
    """
    bbox = span.get("bbox")
    origin = span.get("origin")
    font = str(span.get("font", ""))
    size = float(span.get("size", 0.0))
    if (
        not bbox
        or len(bbox) != 4
        or not origin
        or len(origin) < 2
        or size <= 0.0
    ):
        return span
    x0, y0, x1, y1 = (float(value) for value in bbox)
    origin_y = float(origin[1])
    font_upper = font.upper()
    normalized_text = normalize_span_text(span.get("text", "")).strip()
    if (
        "WASY" in font_upper
        and normalized_text == "M"
        and y1 - origin_y >= size * 1.3
        and y1 - y0 >= size * 2.0
    ):
        normalized_y1 = min(y1, origin_y + size * 0.25)
        if normalized_y1 > y0 + size * 0.5:
            normalized = dict(span)
            raw_text = normalize_span_text(span.get("text", ""))
            normalized["text"] = raw_text.replace("M", "§")
            normalized["_raw_bbox"] = (x0, y0, x1, y1)
            normalized["bbox"] = (x0, y0, x1, normalized_y1)
            return normalized
    ordinary_cmsy_symbols = set("|∥∇≤≥∈∞−=<>+±×÷")
    if (
        "CMSY" in font_upper
        and normalized_text
        and set(normalized_text) <= ordinary_cmsy_symbols
        and y1 - origin_y >= size * 0.65
        and y1 - y0 >= size * 1.5
    ):
        # A conditional bar is painted only to the row baseline; leave less
        # phantom descent so its keepout cannot carve the following prose row.
        descent_ratio = 0.1 if set(normalized_text) == {"|"} else 0.25
        normalized_y1 = min(y1, origin_y + size * descent_ratio)
        if normalized_y1 > y0 + size * 0.5:
            normalized = dict(span)
            normalized["_raw_bbox"] = (x0, y0, x1, y1)
            normalized["bbox"] = (x0, y0, x1, normalized_y1)
            return normalized
    if "CMEX" not in font_upper:
        return span
    if (
        y1 - y0 <= size * 2.2
        or y1 - origin_y <= size * 1.5
        or origin_y - y0 >= size * 1.2
    ):
        return span
    # Computer Modern extension-font summation/product glyphs extract as
    # ``P``/``X``. Their painted operator legitimately descends about one em
    # below the text origin, unlike the stale three-em MuPDF tail.
    large_operator = normalized_text in {
        "P",
        "X",
    }
    normalized_y1 = min(
        y1,
        origin_y + size * (1.2 if large_operator else 0.2),
    )
    if normalized_y1 <= y0 + size * 0.45:
        return span
    normalized = dict(span)
    normalized["_raw_bbox"] = (x0, y0, x1, y1)
    normalized["bbox"] = (x0, y0, x1, normalized_y1)
    return normalized


def _normalized_math_control_span(span: dict) -> dict:
    """Expose CMEX delimiter glyphs that PDF extractors report as whitespace."""
    text = normalize_span_text(span.get("text", ""))
    if (
        "CMEX" not in str(span.get("font", "")).upper()
        or not text
        or text.strip()
        or any(char not in {" ", "\x0c"} for char in text)
        or "\x0c" not in text
    ):
        return span
    normalized = dict(span)
    normalized["text"] = text.replace(" ", "").replace("\x0c", "|")
    return normalized


def parse_block_lines(
    raw_block: dict,
    page_width: float | None = None,
    known_gutter_bboxes: Sequence[BBox] = (),
) -> Tuple[Optional[_RawBlockRec], List[BBox]]:
    """First pass: clean one raw PyMuPDF block into annotated physical lines.

    Gutter line numbers and prompt-injection lines are dropped here (their
    rects are returned for erasure)."""
    dropped_rects: List[BBox] = []
    lines: List[_LineRec] = []

    for raw_line in raw_block.get("lines", []):
        physical_line_bbox = tuple(
            float(value) for value in raw_line.get("bbox", (0, 0, 0, 0))
        )
        if _line_is_rotated(raw_line):
            # Rotated text is chart furniture: y-axis titles, sideways table
            # headers, watermarks. Reflowing it horizontally paints over the
            # plot and its redaction wipes neighbouring tick labels (BERT
            # p16 lost 78/80/82 off the accuracy axis). Leave the source
            # glyphs untouched: neither translated nor erased.
            continue
        spans = [
            _normalized_math_control_span(_normalized_extracted_math_span(span))
            for span in raw_line.get("spans", [])
        ]
        line_max_size = 0.0
        non_empty_span_indexes: List[int] = []
        for span_index, span in enumerate(spans):
            if normalize_span_text(span.get("text", "")).strip():
                non_empty_span_indexes.append(span_index)
                line_max_size = max(line_max_size, float(span.get("size", 0.0)))
        last_non_empty_span = non_empty_span_indexes[-1] if non_empty_span_indexes else -1

        math_like_indexes = []
        for span_index in non_empty_span_indexes:
            span = spans[span_index]
            span_text = normalize_span_text(span.get("text", ""))
            span_size = float(span.get("size", line_max_size))
            if not _span_is_prose_word_fragment(
                span_index,
                spans,
                line_max_size=line_max_size,
            ) and (
                is_math_span(
                    span.get("font", ""),
                    int(span.get("flags", 0)),
                    span_text,
                    span_size,
                    line_max_size,
                )
                or _span_is_adjacent_math_script(
                    span_index,
                    spans,
                    line_max_size=line_max_size,
                )
            ):
                math_like_indexes.append(span_index)
        expanded_math_indexes = _expanded_math_span_indexes(
            spans,
            math_like_indexes,
            line_max_size,
        )

        fragments: List[Tuple[str, dict]] = []
        normalized_span_bboxes = [
            tuple(float(value) for value in span["bbox"])
            for span in spans
            if "bbox" in span
        ]
        raw_line_bbox = (
            union_bbox(normalized_span_bboxes)
            if normalized_span_bboxes
            else tuple(float(value) for value in raw_line.get("bbox", (0, 0, 0, 0)))
        )
        for span_index, span in enumerate(spans):
            span_text = normalize_span_text(span.get("text", ""))
            if not span_text.strip():
                if fragments and span_index < last_non_empty_span:
                    fragments.append((span_text, span))
                continue
            span_size = float(span.get("size", line_max_size))
            isolated = _span_is_isolated(span, spans)
            # With page geometry available, only erase numeric spans in a real
            # page-edge band. Plot ticks (20, 40, 100, ...) use the same small
            # fonts as review line numbers but sit inside figure/table regions.
            small_number_without_geometry = page_width is None and is_line_number_span(
                span_text,
                span_size,
                line_max_size,
                isolated=isolated,
            )
            span_bbox = tuple(float(value) for value in span.get("bbox", ()))
            known_review_line_number = len(span_bbox) == 4 and any(
                all(abs(value - expected) <= 0.75 for value, expected in zip(span_bbox, bbox))
                for bbox in known_gutter_bboxes
            )
            if (
                known_review_line_number
                or small_number_without_geometry
                or _is_margin_line_number_span(
                    span_text,
                    span,
                    span_size,
                    page_width,
                    isolated,
                )
            ):
                if "bbox" in span:
                    dropped_rects.append(tuple(float(x) for x in span["bbox"]))
                continue
            math_like = span_index in expanded_math_indexes
            if math_like:
                fragment = span_text.strip()
                if span_size < line_max_size * 0.85:
                    fragment = _format_script_fragment(
                        fragment,
                        _script_position(span, raw_line_bbox, line_max_size),
                    )
                fragments.append((SENTINEL_OPEN + fragment + SENTINEL_CLOSE, span))
            else:
                fragments.append((span_text, span))
        if not fragments:
            continue
        full_text = "".join(part for part, _ in fragments).strip()
        if not full_text:
            continue
        if is_injection_text(strip_sentinels(full_text)):
            injection_bboxes = [
                tuple(float(x) for x in span["bbox"])
                for _, span in fragments
                if "bbox" in span
            ]
            if injection_bboxes:
                # A poisoned PDF can map extracted injection text to unrelated
                # visible footer glyphs. Per-glyph redaction then leaves a
                # misleading half-footer; erase the complete physical line.
                dropped_rects.append(
                    physical_line_bbox
                    if len(physical_line_bbox) == 4
                    and physical_line_bbox[2] > physical_line_bbox[0]
                    and physical_line_bbox[3] > physical_line_bbox[1]
                    else union_bbox(injection_bboxes)
                )
            continue
        for group in split_line_cells(fragments, line_max_size):
            text = "".join(part for part, _ in group).strip()
            if not text:
                continue
            group_spans = [span for _, span in group]
            boxes = [
                tuple(float(x) for x in span["bbox"]) for span in group_spans if "bbox" in span
            ]
            if boxes:
                bbox = union_bbox(boxes)
            else:
                bbox = tuple(float(x) for x in raw_line.get("bbox", (0, 0, 0, 0)))
            math_bboxes = [
                tuple(float(value) for value in span["bbox"])
                for part, span in group
                if SENTINEL_OPEN in part and "bbox" in span
            ]
            prose_bboxes = [
                tuple(float(value) for value in span["bbox"])
                for part, span in group
                if SENTINEL_OPEN not in part
                and normalize_span_text(span.get("text", "")).strip()
                and "bbox" in span
            ]
            math_run_bboxes: List[BBox] = []
            current_math_run: List[BBox] = []
            for part, span in group:
                if SENTINEL_OPEN in part and "bbox" in span:
                    current_math_run.append(
                        tuple(float(value) for value in span["bbox"])
                    )
                    continue
                if not part.strip() and current_math_run:
                    continue
                if current_math_run:
                    math_run_bboxes.append(union_bbox(current_math_run))
                    current_math_run = []
            if current_math_run:
                math_run_bboxes.append(union_bbox(current_math_run))
            lines.append(
                _LineRec(
                    text=text,
                    bbox=bbox,
                    spans=group_spans,
                    is_cell=len(group) < len(fragments),
                    math_bboxes=math_bboxes,
                    prose_bboxes=prose_bboxes,
                    math_run_bboxes=math_run_bboxes,
                )
            )

    if not lines:
        return None, dropped_rects
    lines = _coalesce_fragmented_same_baseline_lines(lines)
    _promote_adjacent_short_formula_lines(lines)
    detached_inline_scripts = _promote_detached_inline_formula_scripts(lines)
    return _RawBlockRec(
        lines=lines,
        detached_inline_scripts=detached_inline_scripts,
    ), dropped_rects


def _coalesce_fragmented_same_baseline_lines(lines: Sequence[_LineRec]) -> List[_LineRec]:
    """Join inline-formula rows split into several overlapping line objects.

    TeX may emit one visual row as consecutive objects where every object
    continues the previous formula a few points to the right. Keeping them as
    separate physical lines loses math anchors during paragraph accumulation.
    Restrict joining to math-bearing, strongly co-linear fragments so table
    cells, panel labels, and two-dimensional display equations stay separate.
    """
    def can_join(previous: _LineRec, line: _LineRec) -> bool:
        previous_height = max(1.0, previous.bbox[3] - previous.bbox[1])
        line_height = max(1.0, line.bbox[3] - line.bbox[1])
        vertical_overlap = min(previous.bbox[3], line.bbox[3]) - max(
            previous.bbox[1], line.bbox[1]
        )
        horizontal_gap = line.bbox[0] - previous.bbox[2]
        reference_height = min(previous_height, line_height)
        return bool(
            not previous.is_cell
            and not line.is_cell
            and SENTINEL_OPEN in previous.text
            and SENTINEL_OPEN in line.text
            and vertical_overlap >= reference_height * 0.65
            and line.bbox[0] > previous.bbox[0] + 1.0
            and line.bbox[2] > previous.bbox[2] + 1.0
            and -max(8.0, reference_height * 0.55)
            <= horizontal_gap
            <= max(2.0, reference_height * 0.15)
        )

    def merge(previous: _LineRec, line: _LineRec) -> _LineRec:
        math_runs = [*previous.math_run_bboxes, *line.math_run_bboxes]
        if (
            previous.math_run_bboxes
            and line.math_run_bboxes
            and previous.text.rstrip().endswith(SENTINEL_CLOSE)
            and line.text.lstrip().startswith(SENTINEL_OPEN)
        ):
            math_runs = [
                *previous.math_run_bboxes[:-1],
                union_bbox((previous.math_run_bboxes[-1], line.math_run_bboxes[0])),
                *line.math_run_bboxes[1:],
            ]
        return _LineRec(
            text=previous.text + line.text,
            bbox=union_bbox((previous.bbox, line.bbox)),
            spans=[*previous.spans, *line.spans],
            math_bboxes=[*previous.math_bboxes, *line.math_bboxes],
            prose_bboxes=[*previous.prose_bboxes, *line.prose_bboxes],
            math_run_bboxes=math_runs,
        )

    coalesced: List[_LineRec] = []
    index = 0
    while index < len(lines):
        group = [lines[index]]
        next_index = index + 1
        while next_index < len(lines) and can_join(group[-1], lines[next_index]):
            group.append(lines[next_index])
            next_index += 1
        script_prose_tail = bool(
            len(group) == 2
            and group[1].text.lstrip().startswith(SENTINEL_OPEN)
            and re.search(
                r"\b(?:and|or|where|with|is|are|was|were)\b",
                strip_sentinels(group[1].text),
                re.IGNORECASE,
            )
        )
        if len(group) < 4 and not script_prose_tail:
            coalesced.extend(group)
        else:
            combined = group[0]
            for continuation in group[1:]:
                combined = merge(combined, continuation)
            coalesced.append(combined)
        index = next_index
    return coalesced


# Horizontal span gap (in units of line font size) that separates table cells.
CELL_GAP_FACTOR = 1.6
CELL_GAP_MIN = 8.0


def _line_is_rotated(raw_line: dict) -> bool:
    """True when a text line does not run left-to-right.

    PyMuPDF reports the writing direction as a unit vector; horizontal text
    is (1, 0). Anything with a meaningful vertical component is rotated.
    """
    direction = raw_line.get("dir")
    if not direction or len(direction) < 2:
        return False
    try:
        horizontal, vertical = float(direction[0]), float(direction[1])
    except (TypeError, ValueError):
        return False
    return abs(vertical) > 0.2 or horizontal < 0.8


def _split_column_straddling_record(record: _RawBlockRec) -> List[_RawBlockRec]:
    """Split a raw record whose lines populate two prose columns.

    Sample-comparison tables (InstructGPT appendix: "GPT-3 completion" |
    "InstructGPT completion") arrive as ONE extraction block whose lines
    alternate between the left and right cell in reading order. Keeping
    them together concatenates the two texts and the reflow overprints the
    right cell. Lines are split at a clean vertical gutter that no line
    crosses, provided both sides carry multi-line prose.
    """
    lines = record.lines
    if len(lines) < 4:
        return [record]
    # Text-only bodies only. A record carrying formula ink (sentinel math
    # spans, non-prose rows) or clipped sprite anchors keeps its geometry:
    # the clip and sprite pipelines address rows by their record-relative
    # position, so splitting one would move the anchors out from under them.
    if any(line.math_bboxes or line.math_run_bboxes for line in lines):
        return [record]
    if getattr(record, "detached_inline_scripts", None):
        return [record]
    # Short label rows ("GPT-3 175B completion:") read as non-prose, so the
    # gate is a majority rather than a unanimity: a record dominated by
    # non-prose rows is a formula stack or a label grid, not a text body.
    if sum(1 for line in lines if line_is_prose(line)) < len(lines) * 0.6:
        return [record]
    if record_is_table(record):
        # Numeric grids keep their row structure: the table pipeline
        # translates cell by cell and the preserved-table QA compares the
        # full grid.
        return [record]
    xs = sorted((line.bbox[0], line.bbox[2]) for line in lines)
    left_anchor = min(x0 for x0, _ in xs)
    # Candidate gutter: the largest horizontal gap between the sorted line
    # extents' right and next left edges.
    best_gap = 0.0
    gutter_lo = gutter_hi = None
    ends = sorted(x1 for _, x1 in xs)
    starts = sorted(x0 for x0, _ in xs)
    for end in ends:
        following = [s for s in starts if s >= end + 8.0]
        if not following:
            continue
        gap = following[0] - end
        left = [line for line in lines if line.bbox[2] <= end + 0.5]
        right = [line for line in lines if line.bbox[0] >= following[0] - 0.5]
        if len(left) < 1 or len(right) < 1 or len(left) + len(right) != len(lines):
            continue
        if max(len(left), len(right)) < 2:
            continue
        if gap > best_gap:
            best_gap = gap
            gutter_lo, gutter_hi = end, following[0]
    if gutter_lo is None or best_gap < 8.0:
        return [record]
    left_lines = [line for line in lines if line.bbox[2] <= gutter_lo + 0.5]
    right_lines = [line for line in lines if line.bbox[0] >= gutter_hi - 0.5]
    if min(len(left_lines), len(right_lines)) < 1 or max(
        len(left_lines), len(right_lines)
    ) < 2:
        return [record]
    # Both sides must be prose, not display-math operands. A lone side line
    # (the other column's run-in header swept into this block) re-attaches
    # to its own column downstream through paragraph merging.
    for side in (left_lines, right_lines):
        prose_rows = sum(1 for line in side if line.prose_bboxes)
        if prose_rows < 1 or prose_rows < len(side) * 0.6:
            return [record]
    # A genuine paragraph wraps back to the left anchor; a column pair
    # never does, so demand the right column start well past the left
    # column's anchor (avoids splitting indented block quotes).
    if gutter_hi - left_anchor < 120.0:
        return [record]
    return [
        _RawBlockRec(lines=left_lines),
        _RawBlockRec(lines=right_lines),
    ]


def split_line_cells(
    fragments: Sequence[Tuple[str, dict]], line_max_size: float
) -> List[List[Tuple[str, dict]]]:
    """Split one physical line into cell groups at large horizontal gaps."""
    threshold = max(CELL_GAP_FACTOR * max(line_max_size, 1.0), CELL_GAP_MIN)
    groups: List[List[Tuple[str, dict]]] = []
    current: List[Tuple[str, dict]] = []
    previous_end: Optional[float] = None
    for fragment in fragments:
        bbox = fragment[1].get("bbox")
        start = float(bbox[0]) if bbox else None
        gap = (
            current
            and previous_end is not None
            and start is not None
            and start - previous_end > threshold
        )
        if gap:
            groups.append(current)
            current = []
        current.append(fragment)
        if bbox:
            previous_end = float(bbox[2])
    if current:
        groups.append(current)
    return groups


# Big-operator / oddball glyphs that only occur inside display equations.
_BIG_OPERATOR_CHARS = set(
    "\u2211\u220f\u222b\u221a\u222c\u222d\u22c0\u22c1\u22c2\u22c3\u2a01\u2a02\u2a04\u2a06"
)  # noqa: E501
_ENGLISH_WORD_RE = re.compile(r"[a-z]{3,}")
# Limits for a small block to be absorbed into a neighbouring equation zone.
EQUATION_NEIGHBOR_MAX_CHARS = 60
EQUATION_NEIGHBOR_MAX_LINES = 5
EQUATION_NEIGHBOR_GAP = 9.0
EQUATION_NEIGHBOR_SIDE_GAP = 48.0


def _record_prose_line_count(record: _RawBlockRec) -> int:
    return sum(
        1
        for line in record.lines
        if substantial_prose_word_count(" ".join(strip_sentinels(line.text).split()))
        >= 6
    )


def _line_is_pure_math_fragment(line: _LineRec) -> bool:
    """A non-prose line carrying no real prose words at all.

    Wrapped prose lines whose inline math sits on its own physical line
    ("_{t}_{−}_{1} can be cal-") mix a few lowercase prose words between the
    sentinel fragments; pure math towers ("∥KdC∥^{2") have none. Lowercase
    multi-letter words are the tell: math variables are single letters,
    concatenated symbol runs keep their uppercase, and known math functions
    are excluded via _MATH_WORDS.
    """
    if line_is_prose(line):
        return False
    bare = strip_sentinels(line.text)
    return not any(
        len(word) >= 2 and word.islower() and word.lower() not in _MATH_WORDS
        for word in _PROSE_WORD_RE.findall(bare)
    )


def _record_has_fragile_line_overlap(record: _RawBlockRec) -> bool:
    """Area-intersecting pairs of a prose line and a PURE math fragment.

    Such records carry 2D math typesetting whose glyphs share area with a
    line that would be redacted and re-inserted; line-wise processing cannot
    preserve them, so the record must keep its original rendering.

    A prose line overlapping another prose-mixed line (a wrapped sentence
    whose inline sub/superscripts sit on their own physical line) is normal
    paragraph typesetting that formula keepouts already handle; counting it
    here would condemn whole paragraphs to the equation/table skip path.
    """
    for first, second in zip(record.lines, record.lines[1:]):
        v_overlap = min(first.bbox[3], second.bbox[3]) - max(first.bbox[1], second.bbox[1])
        if v_overlap < 1.5:
            continue
        h_overlap = min(first.bbox[2], second.bbox[2]) - max(first.bbox[0], second.bbox[0])
        if h_overlap <= 0:
            continue
        if line_is_prose(first) and _line_is_pure_math_fragment(second):
            return True
        if line_is_prose(second) and _line_is_pure_math_fragment(first):
            return True
    return False


def _fragile_overlap_overrides_prose_majority(record: _RawBlockRec) -> bool:
    """Whether overlapping math ink is structural rather than an inline script.

    A compact derivation with a superscript tower must stay native.  In long
    TeX paragraphs, however, one subscript continuation can be exposed as a
    separate overlapping physical line; letting that single fragment veto the
    prose majority misclassifies the entire paragraph as an equation/table.
    """
    if not _record_has_fragile_line_overlap(record):
        return False
    prose_lines = _record_prose_line_count(record)
    prose_words = len(_prose_words(strip_sentinels(record.bare_text())))
    long_continuous_prose = bool(
        len(record.lines) >= 16
        and prose_lines / max(len(record.lines), 1) >= 0.5
        and prose_words >= 60
    )
    return not long_continuous_prose


def _record_is_single_line_numbered_display_equation(record: _RawBlockRec) -> bool:
    """Recognize a display formula whose number shares its visual baseline.

    Publishers may emit labels, formula runs, and the equation number as many
    separate PyMuPDF lines even though they occupy one visual row. Math-font
    function names can make that row look like prose, so geometry and math
    density are stronger signals than the PDF's internal line count.
    """
    if not record.lines:
        return False

    def compact_text(line: _LineRec) -> str:
        return "".join(strip_sentinels(line.text).split())

    def formula_candidate(line: _LineRec) -> bool:
        compact = compact_text(line)
        if not compact or not line.math_run_bboxes:
            return False
        math_ratio = sentinel_char_count(line.text) / len(compact)
        return math_ratio >= 0.35 and bool(
            re.search(r"[=<>≤≥≈≃≠∼∝+−*/]", strip_sentinels(line.text))
        )

    if len(record.lines) == 1:
        line = record.lines[0]
        compact = compact_text(line)
        number = EQUATION_NUMBER_RE.search(compact)
        return bool(
            number
            and number.end() == len(compact)
            and formula_candidate(line)
        )

    number_lines = [
        line
        for line in record.lines
        if EQUATION_NUMBER_RE.fullmatch(compact_text(line))
    ]
    if len(number_lines) != 1:
        return False
    number_line = number_lines[0]
    formula_lines = [line for line in record.lines if line is not number_line]
    if not formula_lines or not all(
        lines_share_y_band(line, number_line) for line in formula_lines
    ):
        return False
    return any(formula_candidate(line) for line in formula_lines)


def _record_is_annotated_formula_decoration(record: _RawBlockRec) -> bool:
    """Keep short underbrace/overbrace labels inside a display formula.

    TeX emits the brace, its ``z`` marker, closing delimiter, and label as
    separate overlapping lines. Translating only the label duplicates the
    following explanatory paragraph and lets its 7pt annotation size become
    the paragraph's layout baseline.
    """
    prose_lines = [line for line in record.lines if line_is_prose(line)]
    math_lines = [line for line in record.lines if not line_is_prose(line)]
    if len(prose_lines) != 1 or len(math_lines) < 2:
        return False
    label = prose_lines[0]
    label_text = " ".join(strip_sentinels(label.text).split()).strip()
    if (
        not 1 <= len(_prose_words(label_text)) <= 5
        or sentence_final_text(label_text)
        or not all(sentinel_char_count(line.text) for line in math_lines)
    ):
        return False
    decoration_bbox = union_bbox([line.bbox for line in math_lines])
    label_width = max(1.0, label.bbox[2] - label.bbox[0])
    horizontal_overlap = min(label.bbox[2], decoration_bbox[2]) - max(
        label.bbox[0], decoration_bbox[0]
    )
    vertical_overlap = min(label.bbox[3], decoration_bbox[3]) - max(
        label.bbox[1], decoration_bbox[1]
    )
    formula_size = median_or_default(
        [
            float(span.get("size", 0.0))
            for line in math_lines
            for span in line.spans
            if normalize_span_text(span.get("text", "")).strip()
        ],
        0.0,
    )
    label_size = median_or_default(
        [
            float(span.get("size", 0.0))
            for span in label.spans
            if normalize_span_text(span.get("text", "")).strip()
        ],
        formula_size,
    )
    decoration_text = "".join(strip_sentinels(line.text) for line in math_lines)
    return bool(
        formula_size > 0.0
        and label_size <= formula_size * 0.82
        and horizontal_overlap >= label_width * 0.85
        and vertical_overlap >= 0.5
        and re.search(r"[|{}\[\]\x00-\x1f]", decoration_text)
    )


def block_is_strong_math(record: _RawBlockRec) -> bool:
    """Blocks that are unambiguously display-equation material."""
    if _record_is_single_line_numbered_display_equation(record):
        return True
    # PyMuPDF can merge prose paragraphs and their display equations into one
    # raw block; several full prose lines mean this is a paragraph carrying
    # equations (handled line-wise by formula keepouts), not an equation.
    prose_lines = _record_prose_line_count(record)
    mostly_prose = prose_lines >= 3 or (
        len(record.lines) > 0 and prose_lines / len(record.lines) >= 0.5
    )
    if mostly_prose and _fragile_overlap_overrides_prose_majority(record):
        mostly_prose = False
    if not mostly_prose:
        for line in record.lines:
            compact = "".join(strip_sentinels(line.text).split())
            if compact and EQUATION_NUMBER_RE.fullmatch(compact):
                return True
            if any(ord(char) < 32 or char in _BIG_OPERATOR_CHARS for char in compact):
                return True
    if record.sentinel_ratio() >= 0.5:
        return True
    # Two physical lines overlapping vertically = 2D math layout (sub/sup).
    # Requires real math content: section headings ("3.4" + title) also arrive
    # as two side-by-side "lines" but carry no math-font spans.
    if not mostly_prose and record.sentinel_ratio() >= 0.05:
        for first, second in zip(record.lines, record.lines[1:]):
            overlap = min(first.bbox[3], second.bbox[3]) - max(first.bbox[1], second.bbox[1])
            if overlap >= 1.5:
                return True
    return bool(looks_like_math(record.bare_text()))


def block_is_equation_neighbor(record: _RawBlockRec) -> bool:
    """Small math-ish fragments (LHS, sub/superscript limits) that belong to a
    nearby equation zone but are not strong on their own."""
    if len(record.lines) > EQUATION_NEIGHBOR_MAX_LINES:
        return False
    if record.compact_length() > EQUATION_NEIGHBOR_MAX_CHARS:
        return False
    bare = record.bare_text()
    if record.sentinel_ratio() >= 0.2:
        return True
    words = _ENGLISH_WORD_RE.findall(bare)
    if not words:
        return True
    return any(char in MATH_SYMBOLS for char in bare)


def _zone_adjacent(candidate: BBox, zone: BBox) -> bool:
    horizontal_overlap = min(candidate[2], zone[2]) - max(candidate[0], zone[0])
    vertical_overlap = min(candidate[3], zone[3]) - max(candidate[1], zone[1])
    if horizontal_overlap > 0:
        gap = -vertical_overlap
        return gap <= EQUATION_NEIGHBOR_GAP
    if vertical_overlap > 0:
        # Same line band (e.g. "E(T) =" to the left of a tall sum sign).
        gap = -horizontal_overlap
        return gap <= EQUATION_NEIGHBOR_SIDE_GAP
    return False


def _record_starts_with_caption_prefix(record: _RawBlockRec) -> bool:
    """Whether a record opens with a figure/table caption label.

    Caption records ("Figure 5:" beside a two-line body with math glyphs like
    64×64) can trip the 2D-math heuristics; flagging them as equations drops
    the caption prefix and leaves the caption untranslated.
    """
    for line in record.lines:
        compact = " ".join(strip_sentinels(line.text).split())
        if not compact:
            continue
        return bool(_CAPTION_RE.match(compact))
    return False


def mark_equation_blocks(records: Sequence[_RawBlockRec]) -> List[bool]:
    """Flag raw blocks belonging to display-equation zones.

    Strong math blocks seed the zones; small math-ish neighbours touching a
    zone are absorbed iteratively. Long text paragraphs can never be absorbed.
    """
    caption_guard = [_record_starts_with_caption_prefix(record) for record in records]
    flags = [
        not guarded and block_is_strong_math(record)
        for record, guarded in zip(records, caption_guard)
    ]
    candidates = [
        not guarded and block_is_equation_neighbor(record)
        for record, guarded in zip(records, caption_guard)
    ]
    changed = True
    while changed:
        changed = False
        for index, record in enumerate(records):
            if flags[index] or not candidates[index]:
                continue
            bbox = record.bbox
            for other_index, other in enumerate(records):
                if not flags[other_index] or other_index == index:
                    continue
                if _zone_adjacent(bbox, other.bbox):
                    flags[index] = True
                    changed = True
                    break
    return flags


_PSEUDOCODE_STEP_RE = re.compile(r"^\s*\d{1,2}:\s*\S", re.MULTILINE)
_ALGORITHM_TITLE_RE = re.compile(r"^\s*Algorithm\s+\d+\b", re.IGNORECASE)
_ALGORITHM_PROSE_REFERENCE_RE = re.compile(
    r"^\s*Algorithm\s+\d+\s+(?:implements?|describes?|shows?|presents?|"
    r"summari[sz]es?|outlines?|uses?|provides?|reports?|evaluates?|is|can|will)\b",
    re.IGNORECASE,
)
_ALGORITHM_IO_RE = re.compile(r"\b(?:Require|Ensure|Input|Output)\s*:", re.IGNORECASE)
_ALGORITHM_IO_LINE_RE = re.compile(r"^(?:Require|Ensure|Input|Output)\s*:", re.IGNORECASE)
_PROSE_STOPWORD_RE = re.compile(
    r"\b(?:the|of|to|and|in|that|is|for|we|with|as|are|on|this|by|be|from|it|"
    r"an|which|or|was|were|these|their|also|can|our|not|have|has)\b",
    re.IGNORECASE,
)
_ALGORITHM_STAGE_RE = re.compile(r"^\s*(?:Stage|Phase)\s+\d+\s*:", re.IGNORECASE)
_CODE_FONT_RE = re.compile(
    r"(?:Inconsolata|Courier|Mono|Typewriter|Consolas|Menlo|CMTT|CMRTypewriter)",
    re.IGNORECASE,
)
_CODE_LINE_RE = re.compile(
    r"^\s*(?:@\w+|def\s+\w+\s*\(|class\s+\w+\s*[:(]|return\b|yield\b|"
    r"if\b|elif\b|else\s*:|for\b|while\b|with\b|try\s*:|except\b|finally\s*:|"
    r"import\s+[A-Za-z_]|from\s+[A-Za-z_]|#|[A-Za-z_]\w*\s*(?:=|\+=|-=|:=))"
)


def line_has_code_font(line: _LineRec) -> bool:
    """True when typewriter spans dominate the line.

    Prose paragraphs cite inline code tokens (``P(completion|context)`` in
    GPT-3 style papers) with a few monospace spans; only lines that are
    mostly monospace belong to code listings or pseudocode floats.
    """
    total = 0
    code = 0
    for span in line.spans:
        length = len(str(span.get("text", "")).strip())
        if length <= 0:
            continue
        total += length
        if _CODE_FONT_RE.search(str(span.get("font", ""))):
            code += length
    return total > 0 and code >= max(2, total * 0.5)


def line_is_code_like(line: _LineRec) -> bool:
    compact = " ".join(strip_sentinels(line.text).split()).strip()
    if not compact:
        return False
    if _PSEUDOCODE_STEP_RE.match(compact):
        return True
    if _CODE_LINE_RE.match(compact):
        return True
    if line_has_code_font(line):
        if re.search(r"(?:->|=>|==|!=|<=|>=|\+=|-=|:=|=|\(|\)|\[|\]|:)", compact):
            return True
    return False


def record_is_algorithm(record: _RawBlockRec) -> bool:
    """Algorithm floats (numbered pseudocode) keep their original typesetting:
    reflowing '1: x <- F(y)' statements as prose destroys them."""
    bare = record.bare_text()
    compact = " ".join(bare.split()).strip()
    if _ALGORITHM_TITLE_RE.match(compact):
        io_lines = sum(
            1
            for line in record.lines
            if _ALGORITHM_IO_LINE_RE.match(strip_sentinels(line.text).lstrip())
        )
        steps = len(_PSEUDOCODE_STEP_RE.findall(bare))
        code_lines = [line for line in record.lines if line_is_code_like(line)]
        prose_reference = bool(_ALGORITHM_PROSE_REFERENCE_RE.match(compact)) or (
            len(record.lines) >= 3
            and len(re.findall(r"[.!?](?:\s|$)", compact)) >= 2
            and len(_PROSE_STOPWORD_RE.findall(compact)) >= 8
        )
        if prose_reference and io_lines == 0 and steps == 0 and not code_lines:
            return False
        return True
    if _ALGORITHM_STAGE_RE.match(compact) and (
        len(compact) <= 180 or _PSEUDOCODE_STEP_RE.search(compact)
    ):
        return True
    # Require/Ensure/Input/Output cues must anchor line starts: prose that
    # merely mentions "the output:" would preserve a whole paragraph
    # otherwise (GPT-3 analysis sections). Running prose vetoes the cue.
    io_lines = sum(
        1
        for line in record.lines
        if _ALGORITHM_IO_LINE_RE.match(strip_sentinels(line.text).lstrip())
    )
    if io_lines >= 1 and len(record.lines) <= 12:
        sentence_count = len(re.findall(r"[.!?](?:\s|$)", compact))
        stopwords = len(_PROSE_STOPWORD_RE.findall(compact))
        prose_like = sentence_count >= 2 and stopwords >= 8
        if io_lines >= 2 or not prose_like:
            return True

    steps = len(_PSEUDOCODE_STEP_RE.findall(bare))
    if steps >= 1:
        has_arrow = "\u2190" in bare or "\u27f5" in bare or "\u21d0" in bare
        if has_arrow:
            return True
        if steps >= 3 and _ALGORITHM_IO_RE.search(bare):
            return True

    code_lines = [line for line in record.lines if line_is_code_like(line)]
    if len(code_lines) < 2:
        return False
    code_font_lines = sum(1 for line in code_lines if line_has_code_font(line))
    has_function_signature = any(
        re.match(r"^\s*(?:def|class)\s+\w+", strip_sentinels(line.text))
        for line in code_lines
    )
    return code_font_lines >= 2 or has_function_signature


def _record_has_dense_aligned_column_rows(record: _RawBlockRec) -> bool:
    """Recognize prose-heavy two-column rows in booktabs tables.

    Definition tables often have no vertical rules and most physical lines are
    ordinary prose, so the prose-majority veto in ``record_is_table`` hides
    their stronger geometry. Require at least four rows with a short left cell
    and stable left/right column starts. Ordinary two-column page text is split
    into separate records earlier and inline-equation rows do not sustain this
    repeated pair of prose columns.
    """
    candidates: List[Tuple[float, float]] = []
    record_width = max(record.bbox[2] - record.bbox[0], 1.0)
    for row in group_same_y_lines(record.lines):
        ordered = sorted(row, key=lambda line: line.bbox[0])
        if len(ordered) != 2:
            continue
        left, right = ordered
        if right.bbox[0] - left.bbox[2] < 2.0:
            continue
        left_words = _PROSE_WORD_RE.findall(strip_sentinels(left.text))
        if len(left_words) > 8 or left.bbox[2] - left.bbox[0] > record_width * 0.48:
            continue
        candidates.append((left.bbox[0], right.bbox[0]))
    if len(candidates) < 4:
        return False
    left_anchor = statistics.median(left for left, _ in candidates)
    right_anchor = statistics.median(right for _, right in candidates)
    aligned = sum(
        abs(left - left_anchor) <= 8.0 and abs(right - right_anchor) <= 12.0
        for left, right in candidates
    )
    return aligned >= 4 and aligned / len(candidates) >= 0.7


_MEASUREMENT_CELL_RE = re.compile(
    r"^[\s(\[]*[-−+±]?\d[\d,]*(?:\.\d+)?\s*(?:%|×|x|k|K|M|B|ms|s|pt|px|GB|MB|dB)?"
    r"(?:\s*(?:±|\+/-|\+-)\s*\d[\d,]*(?:\.\d+)?\s*%?)?[\s)\]]*$"
)
_EQUATION_NUMBER_CELL_RE = re.compile(r"^\(\s*[A-Za-z]?\d{1,3}[a-z]?\s*\)$")


def _cell_is_measurement(text: str) -> bool:
    """A numeric result cell: a decimal, percentage, ± interval or unit value.

    Bare small integers are excluded on purpose: table-of-contents page numbers
    and list markers also line up in a column but are not table values.
    """
    compact = " ".join(text.split())
    if not _MEASUREMENT_CELL_RE.match(compact):
        return False
    if _EQUATION_NUMBER_CELL_RE.match(compact):
        return False
    return bool(
        re.search(
            r"\.\d|%|±|\+/-|\d,\d{3}|\d\s*(?:×|x)\s*$|\d\s*(?:ms|s|pt|px|GB|MB|dB|[kKMB])$",
            compact,
        )
    )


def _record_has_aligned_value_column_rows(record: _RawBlockRec) -> bool:
    """Recognize compact booktabs result tables from exact column alignment.

    Small tables such as ``No system prompt | 6.84 ± 0.07`` fail the gap-based
    row test (their inter-column gap is barely wider than a word space) and are
    too short for the dense two-column detector. Typesetting still gives them
    away: every row has the same number of cells, each column keeps one edge
    (left, right or centre) stable within 3pt across all rows, columns are
    separated by a positive gap in every row, one column holds measurements and
    no line is a full sentence.
    """
    rows = [
        sorted(row, key=lambda line: line.bbox[0])
        for row in group_same_y_lines(record.lines)
    ]
    rows = [row for row in rows if len(row) >= 2]
    if len(rows) < 3:
        return False
    cell_count = len(rows[0])
    if cell_count > 4 or any(len(row) != cell_count for row in rows):
        return False
    if _record_prose_line_count(record) > 0:
        return False
    texts = [
        [" ".join(strip_sentinels(line.text).split()) for line in row] for row in rows
    ]
    if any(not text or len(text) > 42 for row in texts for text in row):
        return False
    if any(
        re.search(r"[.!?。！？]\s*$", text) and not _cell_is_measurement(text)
        for row in texts
        for text in row
    ):
        return False
    for column in range(cell_count):
        cells = [row[column] for row in rows]
        edges = (
            [cell.bbox[0] for cell in cells],
            [cell.bbox[2] for cell in cells],
            [(cell.bbox[0] + cell.bbox[2]) / 2.0 for cell in cells],
        )
        if not any(max(edge) - min(edge) <= 3.0 for edge in edges):
            return False
        if column:
            gaps = [
                row[column].bbox[0] - row[column - 1].bbox[2] for row in rows
            ]
            if min(gaps) < 4.0:
                return False
    measurement_columns = sum(
        1
        for column in range(cell_count)
        if sum(_cell_is_measurement(row[column]) for row in texts)
        >= max(2, (2 * len(rows) + 2) // 3)
    )
    return measurement_columns >= 1


def record_is_table(record: _RawBlockRec) -> bool:
    """Table blocks expose cells as separate physical lines sharing a y-band.

    Sequential paragraph lines never overlap vertically; two-line headings
    ("3.4" + title) are excluded by the minimum line count. Some PDFs also split
    a normal prose line into two same-baseline text objects; those have only a
    small horizontal gap and must stay mergeable as paragraph text.

    A paragraph wrapping display equations looks tabular: each equation plus
    its right-aligned number forms a "row" with a wide horizontal gap. Several
    full prose lines mean this is such a paragraph, not a table."""
    lines = record.lines
    if len(lines) < 3:
        return False
    if _record_has_dense_aligned_column_rows(record):
        return True
    if _record_has_aligned_value_column_rows(record):
        return True
    prose_lines = _record_prose_line_count(record)
    if prose_lines >= 3 or prose_lines / len(lines) >= 0.5:
        if not _fragile_overlap_overrides_prose_majority(record):
            return False
    table_rows = 0
    for row in group_same_y_lines(lines):
        if row_has_table_gap(row):
            table_rows += 1
        if table_rows >= 2:
            return True
    return record_is_single_row_table(record)


def record_is_single_row_table(record: _RawBlockRec) -> bool:
    """Single physical table rows are common for headers and summary rows.

    They do not have the two same-y rows required by the stronger table
    detector, so we only accept short, multi-cell rows containing numeric
    values or table-header vocabulary.
    """
    grouped_rows = group_same_y_lines(record.lines)
    for row in grouped_rows:
        if len(row) < 3:
            continue
        texts = [" ".join(strip_sentinels(line.text).split()) for line in row]
        if any(not text or len(text) > 42 for text in texts):
            continue
        joined = " ".join(texts)
        if not re.search(r"[.!?。！？]", normalize_table_formula_text(joined)):
            if _looks_like_table_header_text(joined):
                return True

    rows = [row for row in grouped_rows if row_has_table_gap(row)]
    if len(rows) != 1:
        return False
    row = rows[0]
    if len(row) < 3:
        return False
    texts = [" ".join(strip_sentinels(line.text).split()) for line in row]
    if any(not text for text in texts):
        return False
    if any(len(text) > 42 for text in texts):
        return False
    joined = " ".join(texts)
    sentence_check = normalize_table_formula_text(joined)
    if re.search(
        r"(?<![\d₀₁₂₃₄₅₆₇₈₉])[.!?](?![\d₀₁₂₃₄₅₆₇₈₉])|[。！？]",
        sentence_check,
    ):
        return False
    if _looks_like_table_header_text(joined):
        return True
    if len(row) < 4:
        return False
    numeric_cells = sum(
        1
        for text in texts
        if re.search(r"(?:\d+(?:\.\d+)?\s*%|\d+\s*/\s*\d+|^\d+(?:\.\d+)?$)", text)
    )
    if numeric_cells >= max(2, len(row) // 2):
        return True
    value_cells = sum(
        1
        for text in texts
        if re.search(r"\d|[%×±−=<>]|\ue000|\ue001", text)
    )
    if value_cells >= 2:
        return True
    header_terms = re.compile(
        r"\b(?:task|method|model|dataset|metric|average|avg|ours|baseline|"
        r"attention|frames?|tokens?|window|success|rate|score|accuracy|"
        r"precision|recall|f1|w/o|without|hyperparameter|notation|value|"
        r"reward|expression|weight)\b",
        re.IGNORECASE,
    )
    return bool(header_terms.search(joined))


def normalize_table_formula_text(text: str) -> str:
    """Collapse protected script notation for table heuristics.

    A PDF header such as ``π_0.5`` may arrive as ``π_{0}_{.}_{5}``; the dot is
    a metric decimal point, not sentence punctuation.
    """
    normalized = re.sub(r"[_^]\{([^{}]*)\}", r"\1", text)
    return re.sub(r"\b(avg|ref|sup)\.", r"\1", normalized, flags=re.IGNORECASE)


def group_same_y_lines(lines: Sequence[_LineRec]) -> List[List[_LineRec]]:
    rows: List[List[_LineRec]] = []
    for line in sorted(lines, key=lambda item: ((item.bbox[1] + item.bbox[3]) / 2.0, item.bbox[0])):
        for row in rows:
            if any(lines_share_y_band(line, existing) for existing in row):
                row.append(line)
                break
        else:
            rows.append([line])
    return rows


def lines_share_y_band(first: _LineRec, second: _LineRec) -> bool:
    first_height = first.bbox[3] - first.bbox[1]
    second_height = second.bbox[3] - second.bbox[1]
    min_height = min(first_height, second_height)
    if min_height <= 0:
        return False
    overlap = min(first.bbox[3], second.bbox[3]) - max(first.bbox[1], second.bbox[1])
    return overlap >= 0.5 * min_height


def row_has_table_gap(row: Sequence[_LineRec]) -> bool:
    if len(row) < 2:
        return False
    if any(line.is_cell for line in row):
        return True
    ordered = sorted(row, key=lambda line: line.bbox[0])
    heights = [line.bbox[3] - line.bbox[1] for line in ordered]
    threshold = max(CELL_GAP_MIN, median_or_default(heights, 10.0) * CELL_GAP_FACTOR)
    for previous, current in zip(ordered, ordered[1:]):
        gap = current.bbox[0] - previous.bbox[2]
        if gap >= threshold:
            return True
    return False


# Function names and math keywords that appear as words inside formulas;
# they never make a line prose on their own.
_MATH_WORDS = frozenset(
    "sin cos tan exp log min max arg sup inf lim det diag clip tr kl "
    "softmax argmax argmin var cov std relu prox sgn span rank dim mod".split()
)
_PROSE_WORD_RE = re.compile(r"[A-Za-z]{3,}")
_SHORT_PROSE_WORDS = frozenset(
    (
        "a an and are as at be by for if in is it of on or the to us "
        "was we were when where with he her him his she they their "
        "au aux ce de des du en et il la le les lui ou sa ses son un une"
    ).split()
)
_FORMULA_CONTEXT_WORDS = frozenset(
    "fig figure table panel top bottom left right middle row column".split()
)
_FORMULA_PROSE_FRAGMENT_CUE_RE = re.compile(
    r"(?i)(?:\bproof\b|\bwhere\w*|\bif\w*|\bthen\b|\bhence\b|\btherefore\b|"
    r"\bimplies?\b|\bestablish(?:es|ed)?\b|\bnote\b|\bbelow\b|\bfinally\b|"
    r"\brecall\b|\bdefine[sd]?\b|\bbetween\w*|\brestricted\b|\bpushforward\b|"
    r"\binequality\b|\bby\w*|\bwe\s*(?:have|use)\b|\bhave\w*|\bfor\s*all\w*|"
    r"\bsuch\s*that\b|\bto\s*be\b|\b(?:frames?|tokens?|size|loss|cache)\s+"
    r"(?:is|are|becomes?)\b)"
)
_FORMULA_PREFIX_PROSE_TAIL_RE = re.compile(
    r"(?i)^[\s\.,;:)]+(?:as|hence|therefore|thus|consequently|moreover|then|so)\b"
)


def _text_outside_sentinels(text: str) -> str:
    outside: List[str] = []
    inside = False
    for char in text:
        if char == SENTINEL_OPEN:
            inside = True
        elif char == SENTINEL_CLOSE:
            inside = False
        elif not inside:
            outside.append(char)
    return "".join(outside)


def line_has_translatable_formula_tail(line: _LineRec) -> bool:
    """Math-heavy line that still carries prose outside the formula spans."""
    bare = strip_sentinels(line.text)
    compact = "".join(bare.split())
    if not compact:
        return False
    inside = sentinel_char_count(line.text)
    if inside < 2 or inside / len(compact) >= 0.55:
        return False
    outside = _text_outside_sentinels(line.text)
    words = [
        word
        for word in _PROSE_WORD_RE.findall(outside)
        if word.lower()
        not in _MATH_WORDS | _SHORT_PROSE_WORDS | _FORMULA_CONTEXT_WORDS
    ]
    return len(words) >= 2


def line_has_short_formula_prose_fragment(line: _LineRec) -> bool:
    """Short prose connectors split away from nearby formula spans.

    Math-heavy PDFs often split phrases like ``between T and T' to be`` or
    ``we have`` into their own physical line. They are too short for the normal
    prose detector but must still be translated and redacted with the sentence.
    """
    bare = strip_sentinels(line.text)
    compact = "".join(bare.split())
    if not compact or EQUATION_NUMBER_RE.fullmatch(compact):
        return False
    if any(ord(char) < 32 or char in _BIG_OPERATOR_CHARS for char in compact):
        return False
    if sentinel_char_count(line.text) / len(compact) >= 0.80:
        return False
    words = [word for word in _PROSE_WORD_RE.findall(bare) if word.lower() not in _MATH_WORDS]
    if not words:
        return False
    return bool(_FORMULA_PROSE_FRAGMENT_CUE_RE.search(bare))


def line_formula_prefix_prose_tail(line: _LineRec) -> Optional[_LineRec]:
    """Return the prose tail when a physical line starts with display math.

    Fraction layouts sometimes produce a line such as ``2D >= c. As`` whose
    formula prefix vertically overlaps a neighbouring numerator. Redacting the
    whole line erases the numerator; only the prose tail should be translated.
    """
    prefix_before_formula = line.text.split(SENTINEL_OPEN, 1)[0].strip()
    if len(line.spans) < 2 or re.search(r"[A-Za-z]{2,}", prefix_before_formula):
        return None
    line_width = line.bbox[2] - line.bbox[0]
    if line.bbox[0] < 300.0 or line_width > 140.0:
        return None
    span_sizes = [float(span.get("size", 0.0)) for span in line.spans]
    line_max_size = max(span_sizes) if span_sizes else 0.0
    for index in range(1, len(line.spans)):
        tail_spans = list(line.spans[index:])
        tail_text = "".join(normalize_span_text(span.get("text", "")) for span in tail_spans)
        if not _FORMULA_PREFIX_PROSE_TAIL_RE.search(tail_text):
            continue
        prefix_spans = line.spans[:index]
        prefix_text = "".join(normalize_span_text(span.get("text", "")) for span in prefix_spans)
        prefix_has_math = any(
            is_math_span(
                span.get("font", ""),
                int(span.get("flags", 0)),
                normalize_span_text(span.get("text", "")),
                float(span.get("size", line_max_size)),
                line_max_size,
            )
            for span in prefix_spans
        ) or any(char in MATH_SYMBOLS for char in prefix_text)
        if not prefix_has_math:
            continue
        boxes = [
            tuple(float(value) for value in span["bbox"]) for span in tail_spans if "bbox" in span
        ]
        if not boxes:
            continue
        leading_match = re.match(r"^[\s\.,;:)]+", tail_text)
        cleaned = re.sub(r"^[\s\.,;:)]+", "", tail_text).strip()
        if not cleaned:
            continue
        bbox = union_bbox(boxes)
        if leading_match:
            consumed = len(leading_match.group(0))
            ratio = min(0.75, consumed / max(len(tail_text), 1))
            bbox = (bbox[0] + (bbox[2] - bbox[0]) * ratio, bbox[1], bbox[2], bbox[3])
        return _LineRec(text=cleaned, bbox=bbox, spans=tail_spans)
    return None


_PROSE_VERB_RE = re.compile(
    r"\b(?:is|are|was|were|be|been|has|have|shows?|gives?|"
    r"gets?|knows?|knowing|"
    r"exceeds?|matches?|compares?|between|versus|with|from|toward|"
    # Math-paper prose verbs: formula explanations ("we denote the
    # density at...", "let q be the process...") are sentences too.
    r"denotes?|defines?|lets?|consider|assumes?|supposes?|obtains?|"
    r"recall|notes?|states?|yields?|writes?|chooses?|called|leads?)\b",
    re.IGNORECASE,
)


def _prose_words(text: str) -> List[str]:
    return [word for word in _PROSE_WORD_RE.findall(text) if word.lower() not in _MATH_WORDS]


def _line_is_prose_dominant_sentence(line: _LineRec) -> bool:
    """A complete English sentence that merely carries inline math (≥4 prose
    words plus a verb), as opposed to a display formula with a short prose
    connective ("and q(x1) to be close to p1(x1)")."""
    bare = strip_sentinels(line.text)
    return len(_prose_words(bare)) >= 4 and bool(_PROSE_VERB_RE.search(bare))


_EQUATION_EXPLANATION_VERB_RE = re.compile(
    r"\b(?:train(?:s|ed|ing)?|represent(?:s|ed|ing)?|corresponds?|"
    r"condition(?:s|ed|ing)?)\b",
    re.IGNORECASE,
)


def _line_is_equation_explanation(line: _LineRec) -> bool:
    bare = strip_sentinels(line.text)
    return _line_is_prose_dominant_sentence(line) or (
        len(_prose_words(bare)) >= 5
        and bool(_EQUATION_EXPLANATION_VERB_RE.search(bare))
    ) or (
        sentinel_char_count(line.text) > 0
        # TeX often emits no space between the prose cue and the first
        # math-font variable (``whereA_t``).  The variable explanation verb
        # is the stronger boundary, so accept that extracted shape as well.
        and bool(
            re.match(
                r"\s*(?:where|when|if)(?=\s|(?-i:[A-Z]))",
                bare,
                re.IGNORECASE,
            )
        )
        and bool(
            re.search(
                r"\b(?:is|are|corresponds?|denotes?|represents?|"
                r"initializ(?:e|es|ed|ing))\b",
                bare,
                re.IGNORECASE,
            )
        )
        and len(_prose_words(bare)) >= 2
    )


def _line_is_short_derivation_explanation(line: _LineRec) -> bool:
    """Recognize compact prose cues wrapped around an inline derivation."""
    if not line.math_run_bboxes:
        return False
    bare = " ".join(SENTINEL_RUN_RE.sub(" ", line.text).split())
    return bool(
        re.match(r"^(?:Thus\s+we\s+can\s+get|Knowing\b)", bare, re.IGNORECASE)
        and re.search(r"\b(?:get|obtain|derive)\b", bare, re.IGNORECASE)
    )


def _lines_form_dual_sided_derivation(
    formula_line: _LineRec,
    trailing_cue: _LineRec,
) -> bool:
    """Match ``Thus: <math> Thus we can get ...`` split on one baseline."""
    if not formula_line.math_run_bboxes or trailing_cue.math_run_bboxes:
        return False
    formula_text = " ".join(strip_sentinels(formula_line.text).split())
    cue_text = " ".join(strip_sentinels(trailing_cue.text).split())
    if not re.match(r"^Thus\s*:", formula_text, re.IGNORECASE):
        return False
    if not re.match(
        r"^Thus\s+we\s+(?:can\s+get|have)\b",
        cue_text,
        re.IGNORECASE,
    ):
        return False
    overlap = min(formula_line.bbox[3], trailing_cue.bbox[3]) - max(
        formula_line.bbox[1], trailing_cue.bbox[1]
    )
    min_height = min(
        formula_line.bbox[3] - formula_line.bbox[1],
        trailing_cue.bbox[3] - trailing_cue.bbox[1],
    )
    horizontal_gap = trailing_cue.bbox[0] - formula_line.bbox[2]
    return overlap >= 0.75 * max(1.0, min_height) and -1.0 <= horizontal_gap <= 16.0


def _prose_wrapped_numbered_equation_prefix_count(record: _RawBlockRec) -> int:
    """Count leading explanation lines before a numbered display equation."""
    has_equation_number = any(
        EQUATION_NUMBER_RE.fullmatch("".join(strip_sentinels(line.text).split()))
        for line in record.lines
    )
    math_lines = [
        line
        for line in record.lines
        if sentinel_char_count(line.text) >= 2
        and not _line_is_equation_explanation(line)
    ]
    if (
        not has_equation_number
        or len(math_lines) < 3
        or not any(_line_is_equation_explanation(line) for line in record.lines)
    ):
        return 0

    prefix_count = 0
    for index, line in enumerate(record.lines):
        if _line_is_equation_explanation(line):
            prefix_count += 1
            continue
        next_line = record.lines[index + 1] if index + 1 < len(record.lines) else None
        plain = " ".join(strip_sentinels(line.text).split()).strip()
        short_continuation = bool(
            prefix_count
            and not sentence_final_text(record.lines[index - 1].text)
            and not sentinel_char_count(line.text)
            and 1 <= len(_prose_words(plain)) <= 3
            and next_line is not None
            and sentinel_char_count(next_line.text) >= 2
        )
        if short_continuation:
            prefix_count += 1
            continue
        break
    return prefix_count


def _prose_wrapped_numbered_equation_segments(
    page_index: int,
    record: _RawBlockRec,
) -> Optional[List[TextBlock]]:
    """Split prose above a numbered display equation misdetected as a table."""
    prose_prefix_count = _prose_wrapped_numbered_equation_prefix_count(record)
    if not prose_prefix_count:
        return None

    segments: List[TextBlock] = []
    prose = _SegmentAccumulator()
    for index, line in enumerate(record.lines):
        if index < prose_prefix_count:
            _accumulate_line(prose, line)
            continue
        cell = _SegmentAccumulator()
        _accumulate_line(cell, line)
        block = cell.flush(page_index)
        if block is not None:
            block.block_type = "table"
            block.should_translate = False
            block.nowrap = True
            block.no_merge = True
            segments.append(block)

    prose_block = prose.flush(page_index)
    if prose_block is not None:
        prose_block.block_type = "body"
        prose_block.should_translate = True
        prose_block.no_merge = True
        prose_block.nowrap = False
        segments.insert(0, prose_block)
    return segments


def line_is_prose(line: _LineRec) -> bool:
    """Inside an equation zone, full English sentences (e.g. a Remark line or
    a short connective like 'the forward equation is' that PyMuPDF glued onto
    the equation block) must still be translated."""
    bare = strip_sentinels(line.text)
    if (
        not sentinel_char_count(line.text)
        and re.fullmatch(
            r"\s*(?:Furthermore|Moreover|Therefore|Thus|Hence|Consequently|Additionally)\s*[,;:]\s*",
            bare,
            re.IGNORECASE,
        )
    ):
        return True
    words = _prose_words(bare)
    has_formula_tail = line_has_translatable_formula_tail(line)
    has_short_fragment = line_has_short_formula_prose_fragment(line)
    strong_mixed_prose = len(words) >= 5 and bool(_PROSE_VERB_RE.search(bare))
    comparison_text = re.sub(r"(?<=[A-Za-z])(?=\d)", " ", bare)
    metric_comparison = bool(
        re.search(r"\bis\b.*\bversus\b", comparison_text, re.IGNORECASE)
    )
    protected_metric_comparison = bool(
        sentinel_char_count(line.text)
        and re.search(
            r"\bis\b.*\b(?:planted|random)\b.*\bversus\b",
            comparison_text,
            re.IGNORECASE,
        )
    )
    metric_comparison_prose = metric_comparison and (
        len(words) >= 3 or (len(words) >= 2 and protected_metric_comparison)
    )
    connector_text = re.sub(r"(?<=[a-z])(?=[A-Z])", " ", comparison_text)
    formula_fragments = [
        strip_sentinels(match.group(0)) for match in SENTINEL_RUN_RE.finditer(line.text)
    ]
    short_formula_connector = bool(
        len(formula_fragments) >= 2
        and any(any(char.isalpha() for char in fragment) for fragment in formula_fragments)
        and re.search(
            r"\b(?:with|and|versus|where)\b",
            connector_text,
            re.IGNORECASE,
        )
    )
    if (
        strong_mixed_prose
        or metric_comparison_prose
        or short_formula_connector
    ):
        return True
    if len(words) < 3 and not has_formula_tail:
        return has_short_fragment
    compact = "".join(bare.split())
    if not compact:
        return False
    if sentinel_char_count(line.text) / len(compact) < 0.35:
        return True
    return has_formula_tail or has_short_fragment


def line_is_short_prose_before_formula(line: _LineRec, next_line: _LineRec) -> bool:
    bare = strip_sentinels(line.text).strip()
    if not bare or sentinel_char_count(line.text):
        return False
    if sentence_final_text(bare) or looks_like_math(bare):
        return False
    words = [
        word
        for word in re.findall(r"[A-Za-z]{2,}", bare)
        if word.lower() not in _MATH_WORDS
    ]
    if not 1 <= len(words) <= 4:
        return False
    next_compact = "".join(strip_sentinels(next_line.text).split())
    if not next_compact:
        return False
    return is_display_equation_line(next_line.text) or sentinel_char_count(next_line.text) > 0


def line_is_short_prose_prefix(line: _LineRec, next_line: _LineRec) -> bool:
    """A short prose heading glued to the first sentence inside an equation block."""
    bare = strip_sentinels(line.text).strip()
    if not bare or sentinel_char_count(line.text):
        return False
    if not sentence_final_text(bare):
        return False
    words = [word for word in _PROSE_WORD_RE.findall(bare) if word.lower() not in _MATH_WORDS]
    if not 1 <= len(words) <= 3:
        return False
    if looks_like_math(bare):
        return False
    if not line_is_prose(next_line):
        return False
    return lines_share_y_band(line, next_line)


def line_looks_like_section_heading(line: _LineRec) -> bool:
    """Detect structural heading lines before paragraph merging hides them."""
    compact = " ".join(strip_sentinels(line.text).split()).strip()
    if not compact:
        return False
    if sentinel_char_count(line.text):
        return False
    if len(compact) > 120:
        return False
    if _CAPTION_RE.match(compact):
        return False
    if re.match(r"^\d{1,3}\.\s+", compact):
        seen_bold_run = False
        trailing_regular = ""
        for span in line.spans:
            span_text = normalize_span_text(span.get("text", ""))
            if not span_text.strip():
                continue
            if span_is_bold(span):
                seen_bold_run = True
            elif seen_bold_run:
                trailing_regular += span_text
        if seen_bold_run and re.match(
            r"^\s*[:：]\s*[A-Za-z]",
            trailing_regular,
        ):
            # A numbered list item can use a bold run-in label followed by
            # ordinary sentence text on the same physical line. Title-case
            # words in that sentence must not promote the line to a heading.
            return False

    numbered_match = _NUMBERED_HEADING_LINE_RE.match(compact)
    appendix_match = _APPENDIX_STYLE_HEADING_LINE_RE.match(compact)
    roman_match = _ROMAN_HEADING_LINE_RE.match(compact)
    bare_appendix_match = re.fullmatch(
        r"[A-Z]\s+[A-Z][A-Z\s-]{3,80}",
        compact,
    )
    reference_like = _looks_like_reference_entry_text(compact)
    if reference_like and (
        _REFERENCE_YEAR_RE.search(compact) or _REFERENCE_FRAGMENT_CUE_RE.search(compact)
    ):
        return False
    if reference_like and not (
        numbered_match or appendix_match or roman_match or bare_appendix_match
    ):
        return False

    lower = compact.lower().rstrip(":")
    if lower in _STRUCTURE_HEADING_WORDS:
        return True

    if not (numbered_match or appendix_match or roman_match or bare_appendix_match):
        return False
    words = _PROSE_WORD_RE.findall(compact)
    if not 1 <= len(words) <= 14:
        return False
    if numbered_match:
        prefix = _SECTION_NUM_RE.match(compact)
        tail = compact[prefix.end() :].strip() if prefix else compact
    elif appendix_match:
        prefix = re.match(r"^[A-Z]\.(?:\d+\.?)*\s*", compact)
        tail = compact[prefix.end() :].strip() if prefix else compact
    elif roman_match:
        prefix = re.match(r"^[IVXLCDM]+\.\s*", compact)
        tail = compact[prefix.end() :].strip() if prefix else compact
    elif bare_appendix_match:
        prefix = re.match(r"^[A-Z]\s+", compact)
        tail = compact[prefix.end() :].strip() if prefix else compact
    else:
        tail = compact
    tail_words = re.findall(
        r"[A-Za-z]{3,}(?:-[A-Za-z]{2,})*",
        tail or compact,
    )
    if not tail_words:
        return False
    if re.search(r"[!?。！？]$", compact):
        return False
    significant = [
        word
        for word in tail_words
        if word.lower() not in {"a", "an", "and", "for", "in", "of", "on", "the", "to", "with"}
    ]
    if not significant:
        return False
    return sum(1 for word in significant if word[0].isupper()) >= max(1, len(significant) - 1)


def heading_block_from_line(page_index: int, line: _LineRec) -> Optional[TextBlock]:
    accumulator = _SegmentAccumulator()
    _accumulate_line(accumulator, line)
    block = accumulator.flush(page_index)
    if block is None:
        return None
    plain = " ".join(strip_sentinels(line.text).split()).strip()
    source_span_bold = any(
        span_is_bold(span)
        for span in line.spans
        if normalize_span_text(span.get("text", "")).strip()
    )
    block.block_type = "heading"
    block.should_translate = True
    block.bold = (
        source_span_bold
        if (
            _APPENDIX_STYLE_HEADING_LINE_RE.match(plain)
            or _ROMAN_HEADING_LINE_RE.match(plain)
        )
        else True
    )
    block.no_merge = True
    block.preserve_position = False
    return block


def body_block_from_line(
    page_index: int,
    line: _LineRec,
    *,
    no_merge: bool = False,
) -> Optional[TextBlock]:
    accumulator = _SegmentAccumulator()
    _accumulate_line(accumulator, line)
    block = accumulator.flush(page_index)
    if block is not None:
        block.no_merge = no_merge
    return block


def line_looks_like_summary_leadin(line: _LineRec) -> bool:
    compact = " ".join(strip_sentinels(line.text).split()).strip()
    return bool(re.match(r"^In\s+summary\b", compact, re.IGNORECASE))


def span_is_bold(span: dict) -> bool:
    return bool(int(span.get("flags", 0)) & FLAG_BOLD) or bool(
        _BOLD_FONT_RE.search(str(span.get("font", "")))
    )


def line_looks_like_runin_bold_heading(line: _LineRec, next_line: Optional[_LineRec]) -> bool:
    """Fully-bold short line ending in a period, continued on the same
    baseline by a non-bold line: a run-in paragraph heading that PyMuPDF
    split into two physical lines ("Analysis of Moving Objects." + "In this
    section, ..."). split_bold_leadin_line only fires when both halves share
    one line record, so this catches the two-record shape.
    """
    if next_line is None:
        return False
    compact = " ".join(strip_sentinels(line.text).split()).strip()
    if not compact or not compact.endswith(".") or len(compact) > 80:
        return False
    if sentinel_char_count(line.text):
        return False
    words = _PROSE_WORD_RE.findall(compact)
    if not 2 <= len(words) <= 8:
        return False
    spans = [s for s in line.spans if normalize_span_text(s.get("text", "")).strip()]
    if not spans or not all(span_is_bold(span) for span in spans):
        return False
    next_spans = [s for s in next_line.spans if normalize_span_text(s.get("text", "")).strip()]
    if not next_spans or any(span_is_bold(span) for span in next_spans):
        return False
    # Same baseline band, continuation starts to the right of the heading.
    if abs(next_line.bbox[1] - line.bbox[1]) > 2.0:
        return False
    return next_line.bbox[0] >= line.bbox[2] - 2.0


def accumulator_is_hyphenated_caption(accumulator: "_SegmentAccumulator") -> bool:
    if not accumulator.lines:
        return False
    first = " ".join(strip_sentinels(accumulator.lines[0]).split()).strip()
    last = strip_sentinels(accumulator.lines[-1]).rstrip()
    return bool(_CAPTION_RE.match(first) and last.endswith("-"))


def line_looks_like_list_item(line: _LineRec) -> bool:
    compact = " ".join(strip_sentinels(line.text).split()).strip()
    return bool(re.match(r"^(?:[•◦▪●]|\(?[a-zA-Z0-9]{1,3}\)|[-–])\s+", compact))


def line_continues_list_item(line: _LineRec, current: "_SegmentAccumulator") -> bool:
    if not current.line_bboxes:
        return False
    previous = current.line_bboxes[-1]
    previous_height = max(previous[3] - previous[1], 1.0)
    vertical_gap = line.bbox[1] - previous[3]
    if vertical_gap > max(14.0, previous_height * 1.45):
        return False
    list_left = current.line_bboxes[0][0]
    if not sentence_final_text(current.lines[-1]):
        return True
    if line.bbox[0] <= list_left + 8.0:
        return False
    return list_left - 2.0 <= line.bbox[0] <= list_left + 60.0


def split_bold_leadin_line(line: _LineRec) -> Optional[Tuple[_LineRec, _LineRec]]:
    prefix_spans: List[dict] = []
    tail_spans: List[dict] = []
    seen_text = False
    seen_bold_text = False
    collecting_prefix = True

    for span in line.spans:
        span_text = normalize_span_text(span.get("text", ""))
        if not span_text.strip():
            if seen_text and collecting_prefix:
                prefix_spans.append(span)
            elif seen_text:
                tail_spans.append(span)
            continue
        span_bold = span_is_bold(span)
        if not seen_text:
            if not span_bold and not span_is_leadin_marker(span_text):
                return None
            seen_text = True
        if collecting_prefix and span_bold:
            seen_bold_text = True
            prefix_spans.append(span)
            continue
        if collecting_prefix and not seen_bold_text and span_is_leadin_marker(span_text):
            prefix_spans.append(span)
            continue
        collecting_prefix = False
        tail_spans.append(span)

    if not seen_bold_text or not prefix_spans or not tail_spans:
        return None
    prefix_text = text_from_spans(prefix_spans)
    tail_text = text_from_spans(tail_spans)
    if not looks_like_bold_leadin_text(prefix_text, tail_text):
        return None
    prefix_line = line_from_spans(prefix_spans, fallback_bbox=line.bbox)
    tail_line = line_from_spans(tail_spans, fallback_bbox=line.bbox)
    if prefix_line is None or tail_line is None:
        return None
    if tail_line.text.startswith((": ", ":")) and not prefix_line.text.endswith(":"):
        prefix_line.text = prefix_line.text.rstrip() + ":"
        tail_line.text = tail_line.text[1:].lstrip()
    elif tail_line.text.startswith(("： ", "：")) and not prefix_line.text.endswith("："):
        prefix_line.text = prefix_line.text.rstrip() + "："
        tail_line.text = tail_line.text[1:].lstrip()
    return prefix_line, tail_line


def span_is_leadin_marker(text: str) -> bool:
    compact = " ".join(text.split()).strip()
    return bool(re.fullmatch(r"(?:\d+\)|\([a-zA-Z0-9]{1,3}\)|[•◦▪●])", compact))


def line_starts_with_leadin_marker(line: _LineRec) -> bool:
    compact = " ".join(strip_sentinels(line.text).split()).strip()
    return bool(re.match(r"^(?:\d+\)|\([a-zA-Z0-9]{1,3}\)|[•◦▪●])\s+", compact))


def line_contains_url(line: _LineRec) -> bool:
    return bool(URL_RE.search(strip_sentinels(line.text)))


def looks_like_bold_leadin_text(prefix_text: str, tail_text: str) -> bool:
    prefix = " ".join(strip_sentinels(prefix_text).split()).strip()
    tail = " ".join(strip_sentinels(tail_text).split()).strip()
    if not prefix or not tail:
        return False
    if sentinel_char_count(prefix_text):
        return False
    if _CAPTION_RE.match(prefix):
        return False
    if len(prefix) > 90:
        return False
    words = _PROSE_WORD_RE.findall(prefix)
    if not 1 <= len(words) <= 10:
        return False
    if substantial_prose_word_count(tail) < 2:
        return False
    academic_label = bool(
        _ACADEMIC_FORMULA_STATEMENT_RE.fullmatch(prefix.rstrip(".：:"))
    )
    significant = [
        word
        for word in words
        if word.lower()
        not in {"a", "an", "and", "for", "in", "of", "on", "the", "to", "with"}
    ]
    title_style = bool(
        len(words) >= 2
        and significant
        and all(word[:1].isupper() or word.isupper() for word in significant)
    )
    return (
        academic_label
        or title_style
        or prefix.endswith((".", ":", "："))
        or tail.startswith((": ", ":", "： ", "："))
    )


def text_from_spans(spans: Sequence[dict]) -> str:
    return "".join(normalize_span_text(span.get("text", "")) for span in spans).strip()


def line_from_spans(spans: Sequence[dict], fallback_bbox: BBox) -> Optional[_LineRec]:
    raw_line = {
        "bbox": fallback_bbox,
        "spans": list(spans),
    }
    parsed, _dropped = parse_block_lines(
        {"lines": [raw_line]},
        page_width=max(1000.0, float(fallback_bbox[2]) + 72.0),
    )
    if parsed is None or not parsed.lines:
        return None
    if len(parsed.lines) == 1:
        return parsed.lines[0]
    return _LineRec(
        text="".join(line.text for line in parsed.lines),
        bbox=union_bbox(line.bbox for line in parsed.lines),
        spans=list(spans),
        is_cell=any(line.is_cell for line in parsed.lines),
        math_bboxes=[bbox for line in parsed.lines for bbox in line.math_bboxes],
        prose_bboxes=[bbox for line in parsed.lines for bbox in line.prose_bboxes],
        math_run_bboxes=[
            bbox for line in parsed.lines for bbox in line.math_run_bboxes
        ],
    )


def line_continues_inline_formula_tail(line: _LineRec, current: "_SegmentAccumulator") -> bool:
    """True for same-baseline formula fragments that finish a prose sentence."""
    if not current.bboxes:
        return False
    bare = strip_sentinels(line.text)
    compact = "".join(bare.split())
    previous_line = current.line_bboxes[-1]
    previous_tail = re.sub(
        r"\s+",
        " ",
        strip_sentinels(current.lines[-1]).strip().lower(),
    )
    vertical_gap = line.bbox[1] - previous_line[3]
    vertical_overlap = min(previous_line[3], line.bbox[3]) - max(
        previous_line[1],
        line.bbox[1],
    )
    previous_height = max(1.0, previous_line[3] - previous_line[1])
    completion_blank_tail = bool(
        sentinel_char_count(line.text) > 0
        and re.fullmatch(r"(?:[._…·•—-]*)?(?:→|⇒|->)", compact)
        and re.search(r"\b(?:a|an|the)\s*$", previous_tail)
        and vertical_overlap >= previous_height * 0.35
        and 0.0
        <= line.bbox[0] - previous_line[2]
        <= max(64.0, previous_height * 6.5)
        and line.bbox[2] - line.bbox[0] <= max(40.0, previous_height * 4.0)
    )
    if completion_blank_tail:
        return True
    wrapped_formula_suffix = bool(
        sentinel_char_count(line.text) > 0
        and len(compact) <= 60
        and sentinel_char_count(line.text) / max(len(compact), 1) >= 0.5
        and line.bbox[0] <= previous_line[0] + 8.0
        and -max(14.0, line.bbox[3] - line.bbox[1]) <= vertical_gap
        <= max(5.0, (previous_line[3] - previous_line[1]) * 0.55)
        and re.search(r"\b(?:the|a|an|of|as|with)\s*$", previous_tail)
    )
    if wrapped_formula_suffix:
        return True
    previous = current.bboxes[-1]
    horizontal_gap = line.bbox[0] - previous_line[2]
    neighboring_height = min(
        previous_line[3] - previous_line[1],
        line.bbox[3] - line.bbox[1],
    )
    backtrack_tolerance = max(12.0, neighboring_height * 1.25)
    elevated_inline_formula_tail = bool(
        sentinel_char_count(line.text) > 0
        and not current_expects_preserved_formula_tail(current)
        and len(compact) <= 40
        and sentinel_char_count(line.text) / max(len(compact), 1) >= 0.5
        and -backtrack_tolerance <= horizontal_gap <= 12.0
        and line.bbox[1] <= previous_line[3]
        and line.bbox[3] >= previous_line[1]
    )
    if elevated_inline_formula_tail:
        return True
    overlap = min(previous[3], line.bbox[3]) - max(previous[1], line.bbox[1])
    min_height = min(previous[3] - previous[1], line.bbox[3] - line.bbox[1])
    if min_height <= 0 or overlap < min_height * 0.35:
        return False
    if len(bare) > 120:
        return False
    if EQUATION_NUMBER_RE.fullmatch(compact):
        return False
    outside = _text_outside_sentinels(line.text)
    if re.search(r"[A-Za-z]|[),.;:]", outside):
        return True
    if current_expects_preserved_formula_tail(current):
        return False
    gap = line.bbox[0] - previous[2]
    return (
        sentinel_char_count(line.text) > 0
        and len(compact) <= 40
        and -max(12.0, min_height * 1.25) <= gap <= max(12.0, min_height * 2.5)
    )


def current_expects_preserved_formula_tail(current: "_SegmentAccumulator") -> bool:
    if not current.lines:
        return False
    tail = re.sub(r"\s+", " ", strip_sentinels(current.lines[-1]).strip().lower())
    if not tail:
        return False
    if tail.endswith(("+", "=", ":=", ":", "：", ",")):
        return True
    return bool(
        re.search(
            r"(?:\bto be\b|\bwhere we use\b|\bwe have\b|\bfor all\w*\b|\band)$",
            tail,
        )
    )


def formula_prefix_tail_block(
    page_index: int, tail_line: _LineRec, next_line: _LineRec
) -> Optional[TextBlock]:
    accumulator = _SegmentAccumulator()
    _accumulate_line(accumulator, tail_line)
    _accumulate_line(accumulator, next_line)
    block = accumulator.flush(page_index)
    if block is None:
        return None
    block.bbox = next_line.bbox
    if not block.keepout_bboxes:
        block.redact_bboxes = [tail_line.bbox, next_line.bbox]
    block.no_merge = True
    return block


def equation_table_prose_redact_bbox(line: _LineRec, lines: Sequence[_LineRec]) -> BBox:
    """Keep redaction for equation-table prose from expanding into formula cells."""
    formula_lines = [
        other
        for other in lines
        if other is not line and lines_share_y_band(line, other) and not line_is_prose(other)
    ]
    return trim_redact_bbox_against_formula_lines(line.bbox, formula_lines)


def trim_redact_bbox_against_formula_lines(
    redact_bbox: BBox, formula_lines: Sequence[_LineRec]
) -> BBox:
    x0, y0, x1, y1 = redact_bbox
    for formula_line in formula_lines:
        ox0, oy0, ox1, oy1 = formula_line.bbox
        if bbox_share_y_band(redact_bbox, formula_line.bbox):
            if ox0 >= x1 - 0.6 and ox0 - x1 <= 4.0:
                x1 = min(x1, ox0 - EQUATION_TABLE_REDACT_GAP)
            if ox1 <= x0 + 0.6 and x0 - ox1 <= 4.0:
                x0 = max(x0, ox1 + EQUATION_TABLE_REDACT_GAP)
            # A tall formula on the following physical line can extend into
            # the lower half of this prose glyph box.  Stop the redaction at
            # the formula's top edge; the remaining upper strip still
            # intersects the source text object, so MuPDF removes the prose
            # without touching the formula.
            x_overlap = min(x1, ox1) - max(x0, ox0)
            if x_overlap > 0 and oy0 - y0 >= max(2.0, (y1 - y0) * 0.25):
                y1 = min(y1, oy0 - EQUATION_TABLE_REDACT_GAP)
            continue

        x_overlap = min(x1, ox1) - max(x0, ox0)
        if x_overlap <= 0:
            continue
        near_gap = EQUATION_TABLE_REDACT_GAP + 1.0
        if oy0 >= y0 and oy0 - y1 <= near_gap:
            y1 = min(y1, oy0 - EQUATION_TABLE_REDACT_GAP)
        elif oy1 <= y1 and y0 - oy1 <= near_gap:
            y0 = max(y0, oy1 + EQUATION_TABLE_REDACT_GAP)
    if x1 <= x0 or y1 <= y0:
        return redact_bbox
    return (x0, y0, x1, y1)


def _trim_redacts_against_block_keepouts(blocks: Sequence[TextBlock]) -> None:
    """Keep prose redactions from touching adjacent source formula glyphs."""
    for block in blocks:
        if not block.keepout_bboxes:
            continue
        keepout_lines = [
            _LineRec(text="", bbox=keepout, spans=[])
            for keepout in dict.fromkeys(block.keepout_bboxes)
        ]
        redacts = block.redact_bboxes or [block.bbox]
        safe_redacts: List[BBox] = []
        restore_groups = list(block.redaction_formula_restore_groups)
        restore_overlaps = _formula_prose_uses_atom_restore(block)
        for redact in redacts:
            restored_full_prose = False
            segments = [redact]
            for keepout in block.keepout_bboxes:
                next_segments: List[BBox] = []
                for segment in segments:
                    matching_atom_groups = [
                        group
                        for group in block.keepout_formula_atom_groups
                        if group
                        and bbox_intersection_area(union_bbox(group), keepout)
                        / max(bbox_area(union_bbox(group)), 0.1)
                        >= 0.9
                    ]
                    original_prose_bbox = next(
                        (
                            source_bbox
                            for source_bbox in block.source_prose_bboxes
                            if abs(source_bbox[0] - segment[0]) <= 0.8
                            and abs(source_bbox[1] - segment[1]) <= 0.8
                            and abs(source_bbox[2] - segment[2]) <= 0.8
                            and source_bbox[3] >= segment[3] + 0.5
                            and source_bbox[3] >= keepout[1] + 0.5
                            and -0.5
                            <= keepout[1] - segment[3]
                            <= EQUATION_TABLE_REDACT_GAP + 0.5
                            and min(source_bbox[2], keepout[2])
                            - max(source_bbox[0], keepout[0])
                            > 0.0
                            and any(
                                union_bbox(group)[0] >= source_bbox[0] - 0.5
                                and union_bbox(group)[2] <= source_bbox[2] + 0.5
                                and min(source_bbox[3], union_bbox(group)[3])
                                - max(source_bbox[1], union_bbox(group)[1])
                                >= 0.5
                                for group in matching_atom_groups
                            )
                        ),
                        None,
                    )
                    if original_prose_bbox is not None and matching_atom_groups:
                        # Some PDFs delete a prose text object only when its
                        # entire glyph bbox is covered. Restore that full bbox
                        # and repaint the formula atoms crossed in its descent
                        # band after redaction.
                        next_segments.append(original_prose_bbox)
                        restore_groups.extend(matching_atom_groups)
                        restored_full_prose = True
                        continue
                    vertical_overlap = min(segment[3], keepout[3]) - max(
                        segment[1], keepout[1]
                    )
                    horizontal_overlap = min(segment[2], keepout[2]) - max(
                        segment[0], keepout[0]
                    )
                    tall_cross_line_formula = bool(
                        vertical_overlap > 0.0
                        and horizontal_overlap > 0.0
                        and keepout[3] - keepout[1]
                        >= (segment[3] - segment[1]) * 1.5
                    )
                    if not tall_cross_line_formula:
                        next_segments.append(segment)
                        continue
                    segment_height = max(segment[3] - segment[1], 0.1)
                    stale_delete_boundary = bool(
                        matching_atom_groups
                        and any(
                            keepout[3] - union_bbox(group)[3]
                            >= max(
                                4.0,
                                (union_bbox(group)[3] - union_bbox(group)[1])
                                * 0.5,
                            )
                            for group in matching_atom_groups
                        )
                    )
                    visible_atoms_are_vertically_disjoint = bool(
                        matching_atom_groups
                        and not stale_delete_boundary
                        and all(
                            union_bbox(group)[3] <= segment[1]
                            or union_bbox(group)[1] >= segment[3]
                            for group in matching_atom_groups
                        )
                    )
                    if visible_atoms_are_vertically_disjoint:
                        # A source font's delete bbox can extend beyond its
                        # painted formula atoms and cross the neighboring prose
                        # row without being a genuinely stale CMEX boundary.
                        # Preserve the full prose width here; the vertical trim
                        # below clears the modest overhang without a text island.
                        next_segments.append(segment)
                        continue
                    if restore_overlaps and matching_atom_groups:
                        next_segments.append(segment)
                        restore_groups.extend(matching_atom_groups)
                        continue
                    stale_font_descent = bool(
                        matching_atom_groups
                        and (
                            stale_delete_boundary
                            or segment[1] - keepout[1] >= segment_height * 1.75
                        )
                    )
                    if stale_font_descent:
                        next_segments.append(segment)
                        restore_groups.extend(matching_atom_groups)
                        continue
                    left = (
                        segment[0],
                        segment[1],
                        min(segment[2], keepout[0] - EQUATION_TABLE_REDACT_GAP),
                        segment[3],
                    )
                    right = (
                        max(segment[0], keepout[2] + EQUATION_TABLE_REDACT_GAP),
                        segment[1],
                        segment[2],
                        segment[3],
                    )
                    next_segments.extend(
                        candidate
                        for candidate in (left, right)
                        if candidate[2] - candidate[0] >= 1.0
                    )
                segments = next_segments
            if restore_overlaps or restored_full_prose:
                safe_redacts.extend(segments)
            else:
                safe_redacts.extend(
                    trim_redact_bbox_against_formula_lines(segment, keepout_lines)
                    for segment in segments
                )
        block.redact_bboxes = safe_redacts or list(redacts)
        block.redaction_formula_restore_groups = tuple(
            dict.fromkeys(restore_groups)
        )


def _formula_prose_uses_atom_restore(block: TextBlock) -> bool:
    """Whether prose redaction may cross formula ink restored from source atoms."""
    return bool(
        block.block_type == "formula_prose"
        and block.flow_inline_math
        and block.nowrap
        and block.preserve_position
        and not block.source_math_bboxes
    )


def bbox_share_y_band(first: BBox, second: BBox) -> bool:
    first_height = first[3] - first[1]
    second_height = second[3] - second[1]
    min_height = min(first_height, second_height)
    if min_height <= 0:
        return False
    overlap = min(first[3], second[3]) - max(first[1], second[1])
    return overlap >= 0.5 * min_height


def _record_is_inline_formula_sentence_bridge(record: _RawBlockRec) -> bool:
    """Recognize prose wrapped around one long, multi-span inline formula."""
    if len(record.lines) < 3 or record_is_table(record):
        return False
    if any(
        EQUATION_NUMBER_RE.fullmatch("".join(strip_sentinels(line.text).split()))
        for line in record.lines
    ):
        return False

    prefix_index = next(
        (
            index
            for index, line in enumerate(record.lines[:-1])
            if line.prose_bboxes
            and line.math_run_bboxes
            and len(_prose_words(_text_outside_sentinels(line.text))) >= 1
            and max(bbox[2] for bbox in line.prose_bboxes)
            <= min(bbox[0] for bbox in line.math_run_bboxes) + 1.0
        ),
        None,
    )
    if prefix_index is None:
        return False
    prefix = record.lines[prefix_index]
    suffix_index = next(
        (
            index
            for index in range(prefix_index + 1, len(record.lines))
            for line in [record.lines[index]]
            if line.prose_bboxes
            and line.math_run_bboxes
            and len(_prose_words(_text_outside_sentinels(line.text))) >= 5
            and max(bbox[2] for bbox in line.math_run_bboxes)
            <= min(bbox[0] for bbox in line.prose_bboxes) + 1.0
            and lines_share_y_band(prefix, line)
        ),
        None,
    )
    if suffix_index is None or suffix_index + 1 >= len(record.lines):
        return False
    trailing = record.lines[suffix_index + 1]
    trailing_plain = " ".join(_text_outside_sentinels(trailing.text).split())
    if (
        trailing.math_run_bboxes
        or not trailing.prose_bboxes
        or not 1 <= len(_prose_words(trailing_plain)) <= 3
        or sentence_final_text(record.lines[suffix_index].text)
        or trailing.bbox[0] > record.bbox[0] + 12.0
        or trailing.bbox[1]
        - max(bbox[3] for bbox in record.lines[suffix_index].prose_bboxes)
        > 16.0
    ):
        return False
    formula_rows = [
        line
        for line in record.lines[prefix_index : suffix_index + 1]
        if line.math_run_bboxes
    ]
    plain = strip_sentinels(record.bare_text())
    return bool(
        len(formula_rows) >= 3
        and len(_prose_words(plain)) >= 8
        and not any(line_looks_like_section_heading(line) for line in record.lines)
    )


def _record_is_flowing_inline_formula_paragraph(record: _RawBlockRec) -> bool:
    """Recognize ordinary prose fragmented by several inline math objects."""
    if len(record.lines) < 3:
        return False
    if _record_is_inline_formula_sentence_bridge(record):
        return True
    prose_lines = [line for line in record.lines if line_is_prose(line)]
    math_lines = [line for line in record.lines if not line_is_prose(line)]
    formula_bearing_prose_lines = [
        line for line in prose_lines if line.math_run_bboxes
    ]
    formula_run_count = sum(
        len(line.math_run_bboxes) for line in formula_bearing_prose_lines
    )
    record_width = max(1.0, record.bbox[2] - record.bbox[0])
    narrow_inline_formula_runs = bool(
        formula_bearing_prose_lines
        and all(
            math_bbox[2] - math_bbox[0] <= record_width * 0.45
            for line in formula_bearing_prose_lines
            for math_bbox in line.math_run_bboxes
        )
    )
    inline_formula_evidence = bool(
        len(formula_bearing_prose_lines) >= 2
        and formula_run_count >= 3
        and narrow_inline_formula_runs
    )
    plain = strip_sentinels(record.bare_text())
    first_plain = " ".join(strip_sentinels(record.lines[0].text).split()).strip()
    starts_with_run_in_label = bool(
        len(record.lines) >= 2
        and first_plain.endswith((":", "."))
        and 1 <= len(_prose_words(first_plain)) <= 5
        and record.lines[0].spans
        and all(
            span_is_bold(span)
            for span in record.lines[0].spans
            if normalize_span_text(span.get("text", "")).strip()
        )
        and lines_share_y_band(record.lines[0], record.lines[1])
        and -2.0 <= record.lines[1].bbox[0] - record.lines[0].bbox[2] <= 18.0
    )
    compact_detached_paragraph = bool(
        len(record.lines) == 3
        and record.detached_inline_scripts
        and len(prose_lines) == len(record.lines)
        and inline_formula_evidence
    )
    compact_detached_inline = bool(
        record.detached_inline_scripts
        and len(record.lines) >= 4
        and len(prose_lines) >= 2
        and len(math_lines) >= 2
        and len(_prose_words(plain)) >= 8
        and sum(plain.count(mark) for mark in ".!?") >= 1
        and any(line.math_run_bboxes for line in prose_lines)
    )
    return bool(
        prose_lines
        and (
            record.lines[0] is prose_lines[0]
            or starts_with_run_in_label
        )
        and (len(prose_lines) >= 3 or compact_detached_inline)
        and len(prose_lines) / len(record.lines)
        >= (
            0.25
            if compact_detached_inline and starts_with_run_in_label
            else 0.3
            if record.detached_inline_scripts
            else 0.6
        )
        and (len(math_lines) >= 2 or inline_formula_evidence)
        and len(_prose_words(plain))
        >= (
            8
            if compact_detached_inline
            else 12
            if compact_detached_paragraph
            else 20
        )
        and sum(plain.count(mark) for mark in ".!?") >= 1
        and not record_is_table(record)
        and not any(
            line_looks_like_section_heading(line) for line in record.lines
        )
        and not any(
            EQUATION_NUMBER_RE.fullmatch(
                "".join(strip_sentinels(line.text).split())
            )
            for line in record.lines
        )
    )


def segments_from_formula_tail_prose(
    page_index: int, record: _RawBlockRec
) -> Optional[List[TextBlock]]:
    """Split prose that starts after an inline fraction without redacting it.

    Some PDFs typeset ``lambda = 1/(2 sigma^2) where sigma^2 is ...`` as
    overlapping physical lines. That can look like a table to the extractor,
    and the ``where`` clause may otherwise be preserved as formula material.
    We translate the clause in the following prose line's rectangle while only
    redacting the English clause spans, leaving the fraction itself intact.
    """
    lines = record.lines
    if len(lines) < 4:
        return None
    flowing_record = _record_is_flowing_inline_formula_paragraph(record)
    if flowing_record:
        # A complete prose paragraph owns every inline formula run.  Splitting
        # a right-side ``where`` cue here would demote the preceding 2-D formula
        # to a keepout and remove it from the paragraph's semantic token stream.
        return None

    def complete_source_line_count(segments: List[TextBlock]) -> List[TextBlock]:
        if flowing_record and segments:
            missing_lines = len(lines) - sum(block.source_lines for block in segments)
            if missing_lines > 0:
                segments[-1].source_lines += missing_lines
        return segments

    prose_lefts = [
        line.bbox[0]
        for line in lines
        if line_is_prose(line) and (line.bbox[2] - line.bbox[0]) >= 80.0
    ]
    if not prose_lefts:
        return None
    body_left = min(prose_lefts)

    for where_index, line in enumerate(lines[:-1]):
        line_text_lower = line.text.lower()
        cue_matches = [
            (offset, cue)
            for cue in ("to be", "where")
            for offset in (line_text_lower.find(cue),)
            if offset >= 0
        ]
        if not cue_matches:
            continue
        cue_offset, cue = min(cue_matches)
        if cue_offset < 0:
            continue
        # Normal prose lines starting at the paragraph left should translate as
        # ordinary text. This path is only for right-side formula tails.
        if line.bbox[0] <= body_left + 80.0:
            continue

        prose_start = None
        for candidate in range(where_index + 1, len(lines)):
            candidate_line = lines[candidate]
            if line_is_prose(candidate_line) and candidate_line.bbox[0] <= body_left + 30.0:
                prose_start = candidate
                break
        if prose_start is None:
            continue

        segments: List[TextBlock] = []
        prefix = _SegmentAccumulator()
        for prefix_line in lines[:where_index]:
            if prefix_line.bbox[0] <= body_left + 60.0:
                _accumulate_line(prefix, prefix_line)
        prefix_block = prefix.flush(page_index)
        if prefix_block is not None:
            cue_bbox = line_tail_bbox_from_cue(line, cue)
            cue_x0 = cue_bbox[0] if cue_bbox is not None else line.bbox[0]
            prefix_math = [
                bbox
                for prefix_line in lines[: where_index + 1]
                for bbox in prefix_line.math_run_bboxes
                if bbox[0] < cue_x0
            ]
            if prefix_math:
                prefix_block.keepout_bboxes = list(
                    dict.fromkeys([*(prefix_block.keepout_bboxes or []), *prefix_math])
                )
            segments.append(prefix_block)

        clause_parts = [line.text[cue_offset:]]
        clause_parts.extend(tail_line.text for tail_line in lines[where_index + 1 :])
        clause_text = normalize_formula_tail_clause(join_lines(clause_parts))
        if not clause_text:
            return None

        insertion = _SegmentAccumulator()
        for prose_line in lines[prose_start:]:
            _accumulate_line(insertion, prose_line)
        clause_block = insertion.flush(page_index)
        if clause_block is None:
            return None

        redact_bboxes: List[BBox] = []
        cue_bbox = line_tail_bbox_from_cue(line, cue)
        if cue_bbox is not None:
            redact_bboxes.append(cue_bbox)
        redact_bboxes.extend(tail_line.bbox for tail_line in lines[where_index + 1 :])
        cue_x0 = cue_bbox[0] if cue_bbox is not None else line.bbox[0]
        fixed_prefix_math = [
            bbox
            for bbox in line.math_run_bboxes
            if bbox[2] <= cue_x0 + 0.8
        ]
        split_side_cue = bool(
            cue_bbox is not None
            and prose_start == where_index + 1
            and len(lines[prose_start:]) >= 2
        )
        if split_side_cue:
            cue_math = tuple(
                dict.fromkeys(
                    bbox for bbox in line.math_run_bboxes if bbox[2] > cue_x0
                )
            )
            cue_atoms = tuple(
                dict.fromkeys(bbox for bbox in line.math_bboxes if bbox[2] > cue_x0)
            )
            cue_prose = tuple(
                dict.fromkeys(
                    bbox
                    for bbox in line.prose_bboxes
                    if bbox_intersection_area(bbox, cue_bbox) > 0.0
                )
            )
            cue_block = TextBlock(
                page_index=page_index,
                bbox=cue_bbox,
                text=normalize_formula_tail_clause(line.text[cue_offset:]),
                font_size=clause_block.font_size,
                color=clause_block.color,
                source_lines=1,
                nowrap=True,
                no_merge=True,
                redact_bboxes=[cue_bbox],
                keepout_bboxes=fixed_prefix_math or None,
                block_type="formula_prose",
                preserve_position=True,
                flow_inline_math=True,
                source_line_bboxes=(cue_bbox,),
                source_prose_bboxes=cue_prose,
                source_math_bboxes=cue_math,
                source_math_atom_bboxes=cue_atoms,
                source_math_atom_groups=_group_math_atoms_by_run(
                    cue_math,
                    cue_atoms,
                ),
            )
            clause_block.text = normalize_formula_tail_clause(
                join_lines(tail_line.text for tail_line in lines[prose_start:])
            )
            clause_block.block_type = "body"
            clause_block.flow_inline_math = True
            clause_block.no_merge = True
            segments.extend((cue_block, clause_block))
            return complete_source_line_count(segments)

        clause_block.text = clause_text
        clause_block.redact_bboxes = redact_bboxes
        if cue_bbox is not None:
            clause_block.source_line_bboxes = tuple(
                dict.fromkeys([cue_bbox, *clause_block.source_line_bboxes])
            )
        if fixed_prefix_math:
            clause_block.keepout_bboxes = list(
                dict.fromkeys(
                    [*(clause_block.keepout_bboxes or []), *fixed_prefix_math]
                )
            )
            prefix_atom_groups = _group_math_atoms_by_run(
                fixed_prefix_math,
                line.math_bboxes,
            )
            clause_block.keepout_formula_atom_groups = tuple(
                dict.fromkeys(
                    [
                        *clause_block.keepout_formula_atom_groups,
                        *(group for group in prefix_atom_groups if group),
                    ]
                )
            )
        clause_block.source_math_bboxes = tuple(
            dict.fromkeys(
                [
                    bbox
                    for bbox in line.math_run_bboxes
                    if bbox[2] > cue_x0
                ]
                + [
                    bbox
                    for tail_line in lines[where_index + 1 :]
                    for bbox in tail_line.math_run_bboxes
                ]
            )
        )
        clause_block.source_math_atom_bboxes = tuple(
            dict.fromkeys(
                [
                    bbox
                    for bbox in line.math_bboxes
                    if bbox[2] > cue_x0
                ]
                + [
                    bbox
                    for tail_line in lines[where_index + 1 :]
                    for bbox in tail_line.math_bboxes
                ]
            )
        )
        clause_block.source_math_atom_groups = _group_math_atoms_by_run(
            clause_block.source_math_bboxes,
            clause_block.source_math_atom_bboxes,
        )
        clause_block.no_merge = True
        segments.append(clause_block)
        return complete_source_line_count(segments)

    return None


def _has_right_side_formula_tail_cue(record: _RawBlockRec) -> bool:
    """Whether a flowing paragraph contains a prose cue beside fixed math."""
    prose_lefts = [
        line.bbox[0]
        for line in record.lines
        if line_is_prose(line) and (line.bbox[2] - line.bbox[0]) >= 80.0
    ]
    if not prose_lefts:
        return False
    body_left = min(prose_lefts)
    for index, line in enumerate(record.lines[:-1]):
        lowered = line.text.lower()
        cue_offsets = [
            offset
            for cue in ("to be", "where")
            for offset in (lowered.find(cue),)
            if offset >= 0
        ]
        if not cue_offsets or line.bbox[0] <= body_left + 80.0:
            continue
        cue_bbox = line_tail_bbox_from_cue(
            line,
            "to be" if lowered.find("to be") == min(cue_offsets) else "where",
        )
        cue_x0 = cue_bbox[0] if cue_bbox is not None else line.bbox[0]
        if not any(math[2] <= cue_x0 + 0.8 for math in line.math_run_bboxes):
            continue
        if any(
            line_is_prose(candidate)
            and candidate.bbox[0] <= body_left + 30.0
            for candidate in record.lines[index + 1 :]
        ):
            return True
    return False


def normalize_formula_tail_clause(text: str) -> str:
    text = " ".join(text.split())
    return re.sub(r"\b(where|when|if)(?=\S)", r"\1 ", text, flags=re.IGNORECASE)


def line_tail_bbox_from_cue(line: _LineRec, cue: str) -> Optional[BBox]:
    bboxes: List[BBox] = []
    collecting = False
    for span in line.spans:
        span_text = normalize_span_text(span.get("text", ""))
        if not collecting and cue in span_text.lower():
            collecting = True
        if collecting and "bbox" in span:
            bboxes.append(tuple(float(value) for value in span["bbox"]))
    return union_bbox(bboxes) if bboxes else None


def _line_has_same_baseline_word_neighbors(
    record: "_RawBlockRec", line_index: int
) -> bool:
    """Whether other short fragments share this line's baseline band.

    Heavily justified prose makes PyMuPDF report every word as its own
    "line"; a word that happens to be a heading keyword ("experiments")
    must not split the paragraph as a structural heading.
    """
    line = record.lines[line_index]
    neighbors = 0
    for other_index, other in enumerate(record.lines):
        if other_index == line_index:
            continue
        if abs(other.bbox[1] - line.bbox[1]) <= 2.0:
            neighbors += 1
    return neighbors >= 2


def _prose_line_shares_math_row(record: "_RawBlockRec", line_index: int) -> bool:
    """Whether a prose line vertically overlaps a TALLER non-prose line of the
    same equation record — i.e. it sits on the display equation's visual row
    ("where U(a,b) = {...}" beside "min <C,P> −εH(P), (1)", whose subscript
    towers make the math line ~1.5x taller than the prose). Extracting it
    for reflow would tear it out of the equation and overprint the formula.
    Inline-height formula fragments sharing a prose baseline are normal
    text and must not trigger this.
    """
    line = record.lines[line_index]
    line_height = max(1.0, line.bbox[3] - line.bbox[1])
    line_center = (line.bbox[1] + line.bbox[3]) / 2.0
    for other_index, other in enumerate(record.lines):
        if other_index == line_index or line_is_prose(other):
            continue
        overlap = min(line.bbox[3], other.bbox[3]) - max(line.bbox[1], other.bbox[1])
        if overlap < 1.5:
            continue
        other_height = other.bbox[3] - other.bbox[1]
        other_center = (other.bbox[1] + other.bbox[3]) / 2.0
        baseline_tolerance = max(2.0, min(line_height, other_height) * 0.45)
        if abs(other_center - line_center) > baseline_tolerance:
            continue
        compact_other = "".join(strip_sentinels(other.text).split())
        is_numbered_equation = bool(
            compact_other and EQUATION_NUMBER_RE.fullmatch(compact_other)
        )
        if other_height >= line_height * 1.5 or is_numbered_equation:
            return True
    return False


def _math_line_prose_fragments(line: _LineRec) -> List[_LineRec]:
    """Extract normal-font prose runs embedded in a math-dominant line.

    Display equations are sometimes emitted as one physical line whose final
    span starts a sentence, or whose next line begins with a prose word before
    another inline formula. Only those prose spans are redacted and translated;
    all intervening math remains at its source position.
    """
    prose_bboxes = set(line.prose_bboxes)
    if not prose_bboxes or not line.math_bboxes:
        return []

    groups: List[List[dict]] = []
    current: List[dict] = []
    for span_index, span in enumerate(line.spans):
        bbox = (
            tuple(float(value) for value in span["bbox"])
            if "bbox" in span
            else None
        )
        span_text = normalize_span_text(span.get("text", ""))
        prose_span = bbox in prose_bboxes and bool(span_text.strip())
        if (
            prose_span
            and re.search(r"[A-Za-z]", span_text)
        ):
            current.append(span)
            continue
        if current and prose_span:
            has_following_prose_word = any(
                "bbox" in following
                and tuple(float(value) for value in following["bbox"])
                in prose_bboxes
                and re.search(
                    r"[A-Za-z]",
                    normalize_span_text(following.get("text", "")),
                )
                for following in line.spans[span_index + 1 :]
            )
            if has_following_prose_word:
                current.append(span)
                continue
        if current:
            groups.append(current)
            current = []
    if current:
        groups.append(current)

    fragments: List[_LineRec] = []
    for spans in groups:
        text = "".join(normalize_span_text(span.get("text", "")) for span in spans)
        prose_words = [
            word
            for word in re.findall(r"[A-Za-z]{2,}", text)
            if word.lower() not in _MATH_WORDS
        ]
        significant = [
            word
            for word in prose_words
            if word.lower() not in _MATH_WORDS | _FORMULA_CONTEXT_WORDS
        ]
        compact_fragment = " ".join(text.split())
        first_word = significant[0].lower() if significant else ""
        connector = significant and first_word in {
            "and",
            "as",
            "for",
            "if",
            "where",
            "with",
        }
        # Short relational prose is routinely emitted as its own normal-font
        # span between math runs.  Require either an intrinsically verbal cue
        # (``satisfy``) or sentence punctuation so upright formula labels such
        # as ``value`` remain untouched.
        sentence_connector = bool(
            len(prose_words) == 1
            and (
                first_word == "satisfy"
                or (
                    first_word == "let"
                    and re.match(r"^[.;:]\s*let\b", compact_fragment, re.IGNORECASE)
                )
                or (
                    first_word == "from"
                    and re.match(r"^from\s*[,;:]", compact_fragment, re.IGNORECASE)
                )
                or (
                    first_word == "term"
                    and re.search(r"\bterm\s*[,;:]$", compact_fragment, re.IGNORECASE)
                )
            )
        )
        if not significant or (
            len(prose_words) == 1
            and len(significant[0]) < 8
            and not connector
            and not sentence_connector
        ):
            continue
        boxes = [
            tuple(float(value) for value in span["bbox"])
            for span in spans
            if "bbox" in span
        ]
        if not boxes:
            continue
        fragments.append(
            _LineRec(
                text=text.strip(),
                bbox=union_bbox(boxes),
                spans=list(spans),
                prose_bboxes=boxes,
            )
        )
    return fragments


_FORMULA_PROSE_SUFFIX_CUE_RE = re.compile(
    r"^[\s\.,;:)]*(?:as|where|when|if|hence|therefore|thus|then|to\s+be)\b",
    re.IGNORECASE,
)


def _math_line_formula_prose_suffix(line: _LineRec) -> Optional[_LineRec]:
    """Return a sentence suffix interleaved with inline math.

    A display formula can end with ``. As <math>, <math> approaches ...`` or
    ``, where <math> is ...``. Translating each normal-font run separately
    produces one-word requests and lets broad repair redactions erase the
    preceding formula. Reparse only the suffix so its formulas become normal
    placeholders while the formula prefix remains fixed source ink.
    """
    if not line.math_bboxes or not line.prose_bboxes or len(line.spans) < 2:
        return None
    prose_bboxes = set(line.prose_bboxes)
    first_span = line.spans[0]
    first_bbox = (
        tuple(float(value) for value in first_span["bbox"])
        if "bbox" in first_span
        else None
    )
    if first_bbox in prose_bboxes and _line_is_equation_explanation(line):
        return None
    for span_index, span in enumerate(line.spans):
        bbox = (
            tuple(float(value) for value in span["bbox"])
            if "bbox" in span
            else None
        )
        if bbox not in prose_bboxes:
            continue
        tail_spans = list(line.spans[span_index:])
        tail_text = "".join(
            normalize_span_text(candidate.get("text", "")) for candidate in tail_spans
        )
        cue_match = _FORMULA_PROSE_SUFFIX_CUE_RE.search(tail_text)
        prose_words = [
            word
            for word in re.findall(r"[A-Za-z]{2,}", tail_text)
            if word.lower() not in _MATH_WORDS
        ]
        prefix_has_math = any(
            math_bbox[2] <= (bbox[0] if bbox is not None else line.bbox[0]) + 0.8
            for math_bbox in line.math_bboxes
        )
        prefix_prose_bboxes = set(line.prose_bboxes)
        prefix_has_prose_words = any(
            tuple(float(value) for value in candidate["bbox"]) in prefix_prose_bboxes
            and bool(re.search(r"[A-Za-z]{2,}", normalize_span_text(candidate.get("text", ""))))
            for candidate in line.spans[:span_index]
            if "bbox" in candidate
        )
        tail_has_math = any(
            candidate_bbox in set(line.math_bboxes)
            for candidate in tail_spans
            if "bbox" in candidate
            for candidate_bbox in [tuple(float(value) for value in candidate["bbox"])]
        )
        cue_suffix = (
            prefix_has_math
            and not prefix_has_prose_words
            and cue_match is not None
            and len(prose_words) >= 2
            and tail_has_math
        )
        sentence_after_formula = (
            prefix_has_math
            and not prefix_has_prose_words
            and len(prose_words) >= 3
            and bool(re.match(r"^\s*[.;]\s+[A-Z]", tail_text))
        )
        if not cue_suffix and not sentence_after_formula:
            continue
        tail_boxes = [
            tuple(float(value) for value in candidate["bbox"])
            for candidate in tail_spans
            if "bbox" in candidate
        ]
        if not tail_boxes:
            continue
        tail_bbox = union_bbox(tail_boxes)
        parsed, _ = parse_block_lines(
            {"lines": [{"bbox": tail_bbox, "spans": tail_spans}]},
            page_width=max(2000.0, line.bbox[2] + 1000.0),
        )
        if parsed is not None and len(parsed.lines) == 1:
            return parsed.lines[0]
    return None


def _line_continues_hyphenated_formula_prose(
    line: _LineRec,
    current: "_SegmentAccumulator",
) -> bool:
    if not current.lines or not strip_sentinels(current.lines[-1]).rstrip().endswith("-"):
        return False
    bare = strip_sentinels(line.text).lstrip()
    if not re.match(r"[a-z]{3,}", bare) or not line.prose_bboxes:
        return False
    previous_bbox = current.line_bboxes[-1]
    gap = line.bbox[1] - previous_bbox[3]
    return -2.0 <= gap <= max(16.0, (previous_bbox[3] - previous_bbox[1]) * 1.8)


_WRAPPED_PROSE_CONNECTOR_RE = re.compile(
    r"^(?:and|are|be|being|for|from|is|or|that|then|to|was|were|where|which|with)$",
    re.IGNORECASE,
)


def _line_continues_wrapped_prose_connector(
    line: _LineRec,
    current: "_SegmentAccumulator",
) -> bool:
    """Keep a grammatical tail split from formula-bearing running prose."""
    if not current.lines or sentinel_char_count(line.text):
        return False
    plain = " ".join(strip_sentinels(line.text).split()).strip()
    if not _WRAPPED_PROSE_CONNECTOR_RE.fullmatch(plain):
        return False
    if sentence_final_text(current.lines[-1]):
        return False
    previous = current.line_bboxes[-1]
    vertical_gap = line.bbox[1] - previous[3]
    line_height = max(1.0, line.bbox[3] - line.bbox[1])
    return (
        -2.0 <= vertical_gap <= max(16.0, line_height * 1.8)
        and line.bbox[0] <= previous[0] + max(12.0, line_height * 1.3)
    )


_INTERLEAVED_FORMULA_SENTENCE_LEAD_RE = re.compile(
    r"^(?:Given|Letting|Setting|Taking|Using|With|Writing)\b",
    re.IGNORECASE,
)


def _interleaved_formula_sentence_block(
    page_index: int,
    record: _RawBlockRec,
    start_index: int,
) -> Optional[Tuple[TextBlock, int]]:
    """Rejoin a prose sentence fragmented into alternating TeX formula rows."""
    first = record.lines[start_index]
    first_plain = " ".join(_text_outside_sentinels(first.text).split()).strip()
    if (
        not first.math_run_bboxes
        or not first.prose_bboxes
        or not _INTERLEAVED_FORMULA_SENTENCE_LEAD_RE.match(first_plain)
    ):
        return None

    sentence_lines = [first]
    previous = first
    end_index = start_index
    for candidate_index in range(start_index + 1, len(record.lines)):
        candidate = record.lines[candidate_index]
        vertical_gap = candidate.bbox[1] - previous.bbox[3]
        vertical_overlap = min(previous.bbox[3], candidate.bbox[3]) - max(
            previous.bbox[1], candidate.bbox[1]
        )
        shorter_height = max(
            1.0,
            min(
                previous.bbox[3] - previous.bbox[1],
                candidate.bbox[3] - candidate.bbox[1],
            ),
        )
        if vertical_overlap < shorter_height * 0.35 and not -2.0 <= vertical_gap <= 16.0:
            break
        sentence_lines.append(candidate)
        end_index = candidate_index
        previous = candidate
        if sentence_final_text(candidate.text):
            break

    joined_plain = " ".join(
        _text_outside_sentinels(line.text).strip() for line in sentence_lines
    )
    ends_at_display_formula_lead = bool(
        end_index == len(record.lines) - 1
        and re.search(r"\b(?:are|be|equals?|is)\s*$", joined_plain, re.IGNORECASE)
    )
    if (
        end_index == start_index
        or len(_prose_words(joined_plain)) < 6
        or sum(len(line.math_run_bboxes) for line in sentence_lines) < 2
        or not (
            sentence_final_text(sentence_lines[-1].text)
            or ends_at_display_formula_lead
        )
    ):
        return None

    accumulator = _SegmentAccumulator()
    for sentence_line in sentence_lines:
        _accumulate_line(accumulator, sentence_line)
    block = accumulator.flush(page_index)
    if block is None:
        return None
    block.block_type = "formula_prose"
    block.flow_inline_math = True
    block.no_merge = True
    block.nowrap = False
    return block, end_index


def _line_is_display_formula_cluster_member(
    record: _RawBlockRec,
    line_index: int,
) -> bool:
    line = record.lines[line_index]
    for other_index, other in enumerate(record.lines):
        if other_index == line_index or line_is_prose(other):
            continue
        x_overlap = min(line.bbox[2], other.bbox[2]) - max(line.bbox[0], other.bbox[0])
        y_overlap = min(line.bbox[3], other.bbox[3]) - max(line.bbox[1], other.bbox[1])
        if x_overlap > 0.5 and y_overlap > 0.5:
            return True
    return False


def _line_is_inline_2d_formula_cluster_member(
    record: _RawBlockRec,
    line_index: int,
) -> bool:
    """Keep fragmented fractions, roots, and exponents as native PDF ink.

    TeX can split one inline two-dimensional formula across several physical
    lines. Moving only the first fragment detaches the denominator or exponent.
    A tiny plain numeric fragment inside a connected group of at least three
    math lines distinguishes these towers from ordinary inline symbols.
    """
    line = record.lines[line_index]
    if line_is_prose(line):
        return False

    cluster = [line]
    pending = [line]
    while pending:
        current = pending.pop()
        current_height = max(1.0, current.bbox[3] - current.bbox[1])
        for candidate in record.lines:
            if candidate in cluster or line_is_prose(candidate):
                continue
            candidate_height = max(1.0, candidate.bbox[3] - candidate.bbox[1])
            vertical_overlap = min(current.bbox[3], candidate.bbox[3]) - max(
                current.bbox[1], candidate.bbox[1]
            )
            horizontal_gap = max(
                current.bbox[0] - candidate.bbox[2],
                candidate.bbox[0] - current.bbox[2],
                0.0,
            )
            if (
                vertical_overlap >= -1.0
                and horizontal_gap
                <= max(12.0, min(current_height, candidate_height))
            ):
                cluster.append(candidate)
                pending.append(candidate)

    return bool(
        len(cluster) >= 3
        and sum(bool(sentinel_char_count(candidate.text)) for candidate in cluster)
        >= 2
        and any(
            not sentinel_char_count(candidate.text)
            and len("".join(strip_sentinels(candidate.text).split())) <= 3
            for candidate in cluster
        )
    )


def _fragmented_inline_math_paragraph_block(
    page_index: int,
    record: _RawBlockRec,
    equation_record: bool,
) -> Optional[TextBlock]:
    """Recover prose paragraphs misclassified as display-equation records.

    Narrow columns with dense inline subscripts can be split into alternating
    prose and tiny math-only lines. Preserving those tiny lines tears words
    such as ``approximation`` apart and leaves English behind. A real display
    equation normally has a numbered or wide math row, so require neither and
    keep the whole paragraph as one placeholder-protected translation unit.
    """
    if record_is_table(record) and not record.flow_inline_math:
        return None
    opener = " ".join(strip_sentinels(record.lines[0].text).split())
    academic_formula_statement = bool(
        re.match(
            r"^\s*(?:Theorem|Lemma|Proposition|Corollary|Definition|Assumption)\s+[A-Z0-9]",
            opener,
            re.IGNORECASE,
        )
    )
    if (
        any(split_bold_leadin_line(line) is not None for line in record.lines)
        and not academic_formula_statement
    ):
        return None
    trailing_display_start = _academic_statement_trailing_display_start(record)
    if trailing_display_start is None:
        trailing_display_start = _prose_trailing_display_start(record)
    if trailing_display_start is not None:
        record = _RawBlockRec(
            lines=list(record.lines[:trailing_display_start]),
            detached_inline_scripts=record.detached_inline_scripts,
            flow_inline_math=record.flow_inline_math,
        )
    if len(record.lines) < 3:
        return None

    prose_lines = [line for line in record.lines if line_is_prose(line)]
    math_fragments = [line for line in record.lines if not line_is_prose(line)]
    formula_bearing_lines = [line for line in record.lines if line.math_run_bboxes]
    plain = strip_sentinels(record.bare_text())
    ordinary_flowing_inline = _record_is_flowing_inline_formula_paragraph(record)
    inline_formula_sentence_bridge = _record_is_inline_formula_sentence_bridge(
        record
    )
    ordinary_inline_sentence = bool(
        len(record.lines) >= 3
        and len(prose_lines) >= 3
        and len(formula_bearing_lines) >= 2
        and len(_prose_words(plain)) >= 20
        and sum(plain.count(mark) for mark in ".!?") >= 1
        and any(
            not line_is_prose(line)
            and len(line.math_run_bboxes) >= 2
            and len(_prose_words(_text_outside_sentinels(line.text))) >= 5
            and re.search(
                r"\b(?:train(?:s|ed|ing)?|represent(?:s|ed|ing)?|corresponds?)\b",
                _text_outside_sentinels(line.text),
                re.IGNORECASE,
            )
            for line in record.lines
        )
        and not any(
            EQUATION_NUMBER_RE.fullmatch(
                "".join(strip_sentinels(line.text).split())
            )
            for line in record.lines
        )
    )
    formula_explanation_fragment = bool(
        equation_record
        and re.match(r"^\s*(?:Here|Where)\b", " ".join(plain.split()), re.IGNORECASE)
        and len(prose_lines) >= 2
        and len(formula_bearing_lines) >= 2
        and len(_prose_words(plain)) >= 7
        and not any(
            EQUATION_NUMBER_RE.fullmatch(
                "".join(strip_sentinels(line.text).split())
            )
            for line in record.lines
        )
    )
    short_derivation = bool(
        re.match(
            r"^\s*(?:This result can be obtained|Thus we can get|Knowing)\b",
            " ".join(plain.split()),
            re.IGNORECASE,
        )
    )
    long_prose_majority = bool(
        len(record.lines) >= 12
        and len(prose_lines) / len(record.lines) >= 0.65
        and len(_prose_words(plain)) >= 50
        and not any(line_looks_like_section_heading(line) for line in record.lines)
    )
    prose_bearing_lines = [
        line
        for line in record.lines
        if len(_prose_words(_text_outside_sentinels(line.text))) >= 2
    ]
    prose_bottom = max((line.bbox[3] for line in prose_lines), default=record.bbox[1])
    typical_prose_height = (
        statistics.median(
            [max(1.0, line.bbox[3] - line.bbox[1]) for line in prose_lines]
        )
        if prose_lines
        else 1.0
    )
    detached_display_math = any(
        line.bbox[1] - prose_bottom > max(12.0, typical_prose_height * 1.5)
        for line in math_fragments
    )
    prose_rich_equation_record = bool(
        equation_record
        and len(_prose_words(plain)) >= 12
        and len(prose_bearing_lines) >= 2
        and not detached_display_math
        and not any(
            EQUATION_NUMBER_RE.fullmatch(
                "".join(strip_sentinels(line.text).split())
            )
            for line in record.lines
        )
    )
    explicit_inline_sentence = record.flow_inline_math
    if (
        not equation_record
        and not record.detached_inline_scripts
        and not long_prose_majority
        and not academic_formula_statement
        and not ordinary_flowing_inline
        and not ordinary_inline_sentence
    ):
        return None
    if (
        (
            len(prose_lines) < (1 if short_derivation else 2)
            and not prose_rich_equation_record
            and not formula_explanation_fragment
            and not inline_formula_sentence_bridge
            and not explicit_inline_sentence
        )
        or (not short_derivation and not explicit_inline_sentence and (
            sum(
                line_is_prose(line)
                or (
                    academic_formula_statement
                    and len(_prose_words(_text_outside_sentinels(line.text))) >= 3
                )
                or (
                    prose_rich_equation_record
                    and len(_prose_words(_text_outside_sentinels(line.text))) >= 2
                )
                or (
                    inline_formula_sentence_bridge
                    and bool(line.prose_bboxes)
                )
                for line in record.lines
            )
            / len(record.lines)
            < 0.3
        ))
        or (
            not math_fragments
            and not ordinary_inline_sentence
            and not ordinary_flowing_inline
        )
    ):
        return None

    minimum_prose_words = (
        6
        if short_derivation
        else 8
        if inline_formula_sentence_bridge
        else 5
        if explicit_inline_sentence
        else 8
        if ordinary_flowing_inline and record.detached_inline_scripts
        else 7
        if formula_explanation_fragment
        else 12
        if prose_rich_equation_record or ordinary_flowing_inline
        else 20
    )
    if len(_prose_words(plain)) < minimum_prose_words:
        return None
    if (
        not record.detached_inline_scripts
        and not formula_explanation_fragment
        and not inline_formula_sentence_bridge
        and sum(plain.count(mark) for mark in ".!?") < 1
    ):
        return None
    if any(
        EQUATION_NUMBER_RE.fullmatch("".join(strip_sentinels(line.text).split()))
        for line in record.lines
    ):
        return None

    record_width = max(1.0, record.bbox[2] - record.bbox[0])
    wide_structural_math = any(
        (line.bbox[2] - line.bbox[0]) / record_width > 0.75
        and not (
            (
                long_prose_majority
                or academic_formula_statement
                or prose_rich_equation_record
                or ordinary_inline_sentence
                or explicit_inline_sentence
            )
            and sentinel_char_count(line.text) > 0
            and len(_prose_words(_text_outside_sentinels(line.text))) >= 3
        )
        for line in math_fragments
    )
    if wide_structural_math:
        return None

    paragraph = _SegmentAccumulator()
    for line in record.lines:
        _accumulate_line(paragraph, line)
    block = paragraph.flush(page_index)
    if block is None:
        return None
    block.block_type = (
        "formula_prose"
        if (
            formula_explanation_fragment
            or inline_formula_sentence_bridge
            or explicit_inline_sentence
        )
        else "body"
    )
    block.no_merge = bool(
        explicit_inline_sentence
        or (
            not record.detached_inline_scripts
            and not (
                prose_rich_equation_record
                and not sentence_final_text(record.lines[-1].text)
            )
        )
    )
    block.nowrap = False
    if (
        record.detached_inline_scripts
        or long_prose_majority
        or academic_formula_statement
        or prose_rich_equation_record
        or ordinary_flowing_inline
        or ordinary_inline_sentence
        or formula_explanation_fragment
        or explicit_inline_sentence
    ):
        block.flow_inline_math = True
    return block


def _prose_trailing_display_start(record: _RawBlockRec) -> Optional[int]:
    """Find a 2-D display formula fused after a prose lead at record end."""
    if len(record.lines) < 4:
        return None
    for index in range(1, len(record.lines)):
        previous = record.lines[index - 1]
        trailing = record.lines[index:]
        previous_plain = " ".join(_text_outside_sentinels(previous.text).split())
        ordinary_display_lead = re.search(
            r"\b(?:(?:defined|expressed|given|written|computed)\s+as|"
            r"(?:is|are|equals?))[,;:]?\s*$",
            previous_plain,
            re.IGNORECASE,
        )
        bridge_display_lead = bool(
            _record_is_inline_formula_sentence_bridge(record)
            and re.search(r"\bhave[,;:]?\s*$", previous_plain, re.IGNORECASE)
        )
        if ordinary_display_lead is None and not bridge_display_lead:
            continue
        if any(line_is_prose(line) for line in trailing):
            continue
        single_display_seed = bool(
            len(trailing) == 1
            and bridge_display_lead
            and trailing[0].math_bboxes
            and len("".join(strip_sentinels(trailing[0].text).split())) <= 3
            and trailing[0].bbox[0] >= record.bbox[0] + 48.0
        )
        if (
            sum(bool(line.math_bboxes) for line in trailing) < 2
            and not single_display_seed
        ):
            continue
        return index
    return None


def _academic_statement_trailing_display_start(
    record: _RawBlockRec,
) -> Optional[int]:
    """Find a centered display formula fused after a completed statement."""
    if len(record.lines) < 3:
        return None
    opener = " ".join(strip_sentinels(record.lines[0].text).split())
    if not _ACADEMIC_FORMULA_STATEMENT_RE.match(opener):
        return None

    prose_lines = [line for line in record.lines if line.prose_bboxes]
    if not prose_lines:
        return None
    prose_left = min(line.bbox[0] for line in prose_lines)
    prose_right = max(line.bbox[2] for line in prose_lines)
    prose_width = max(1.0, prose_right - prose_left)
    prose_center = (prose_left + prose_right) / 2.0

    for index in range(1, len(record.lines)):
        previous = record.lines[index - 1]
        candidate = record.lines[index]
        candidate_width = max(1.0, candidate.bbox[2] - candidate.bbox[0])
        candidate_center = (candidate.bbox[0] + candidate.bbox[2]) / 2.0
        previous_center_y = (previous.bbox[1] + previous.bbox[3]) / 2.0
        candidate_center_y = (candidate.bbox[1] + candidate.bbox[3]) / 2.0
        if (
            not sentence_final_text(previous.text)
            or candidate.prose_bboxes
            or not candidate.math_bboxes
            or not is_display_equation_line(candidate.text)
            or candidate_width > prose_width * 0.4
            or abs(candidate_center - prose_center) > prose_width * 0.16
            or candidate_center_y <= previous_center_y + 2.0
        ):
            continue
        return index
    return None


def _same_row_formula_suffix_reflow_y0(
    line: _LineRec,
    preserved_math_bboxes: Sequence[BBox],
) -> Optional[float]:
    """Move a translatable equation suffix below a wide fixed formula row.

    TeX often emits ``defined as <formula> where ...`` as several physical
    lines sharing one baseline.  The short English suffix fits to the right of
    the formula, while its Chinese translation generally does not.  Reflowing
    that suffix from the column's left edge would therefore paint over the
    preserved formula.  Keep the source redaction where it is, but start the
    translated flow immediately below the fixed math row.
    """
    plain = _text_outside_sentinels(line.text).lstrip()
    if not line.prose_bboxes or not _FORMULA_PROSE_SUFFIX_CUE_RE.match(plain):
        return None
    line_height = max(1.0, line.bbox[3] - line.bbox[1])
    candidates = [
        bbox
        for bbox in preserved_math_bboxes
        if bbox[2] <= line.bbox[0] + 1.0
        and line.bbox[0] - bbox[2] <= max(12.0, line_height * 1.25)
        and min(line.bbox[3], bbox[3]) - max(line.bbox[1], bbox[1])
        >= min(line_height, bbox[3] - bbox[1]) * 0.2
    ]
    if not candidates:
        return None
    formula_width = max(bbox[2] for bbox in candidates) - min(
        bbox[0] for bbox in candidates
    )
    if formula_width < max(36.0, line_height * 4.0):
        return None
    return max(bbox[3] for bbox in candidates) + max(1.0, line_height * 0.1)


def _trailing_table_prose_start(record: _RawBlockRec) -> Optional[int]:
    """Find a full-width paragraph accidentally fused after compact table rows."""
    record_width = max(1.0, record.bbox[2] - record.bbox[0])
    for index, line in enumerate(record.lines):
        if index < 4:
            continue
        same_row = [
            candidate
            for candidate in record.lines[index:]
            if lines_share_y_band(line, candidate)
        ]
        combined = _LineRec(
            text=" ".join(candidate.text.strip() for candidate in same_row),
            bbox=union_bbox([candidate.bbox for candidate in same_row]),
            spans=[span for candidate in same_row for span in candidate.spans],
            prose_bboxes=[
                bbox for candidate in same_row for bbox in candidate.prose_bboxes
            ],
            math_bboxes=[
                bbox for candidate in same_row for bbox in candidate.math_bboxes
            ],
            math_run_bboxes=[
                bbox for candidate in same_row for bbox in candidate.math_run_bboxes
            ],
        )
        if not line_looks_like_section_heading(combined):
            continue
        if _record_has_dense_aligned_column_rows(
            _RawBlockRec(lines=list(record.lines[:index]))
        ):
            return index
    for index, line in enumerate(record.lines):
        if index < 4 or not _line_is_prose_dominant_sentence(line):
            continue
        preceding = record.lines[:index]
        trailing = record.lines[index:]
        if sum(not line_is_prose(candidate) for candidate in preceding) < 4:
            continue
        if not all(line_is_prose(candidate) for candidate in trailing):
            continue
        if line.bbox[0] > record.bbox[0] + 4.0:
            continue
        if line.bbox[2] - line.bbox[0] < record_width * 0.75:
            continue
        previous_bottom = max(candidate.bbox[3] for candidate in preceding)
        vertical_gap = line.bbox[1] - previous_bottom
        if not -1.0 <= vertical_gap <= 24.0:
            continue
        return index
    return None


def _trailing_caption_prose_start(record: _RawBlockRec) -> Optional[int]:
    """Split full-width body prose fused after a narrow float caption."""
    if len(record.lines) < 2:
        return None
    opener = " ".join(strip_sentinels(record.lines[0].text).split())
    if not _CAPTION_RE.match(opener):
        return None
    for index in range(1, len(record.lines)):
        line = record.lines[index]
        preceding = record.lines[:index]
        preceding_text = join_lines(
            [" ".join(strip_sentinels(candidate.text).split()) for candidate in preceding]
        )
        if not sentence_final_text(preceding_text):
            continue
        caption_bbox = union_bbox([candidate.bbox for candidate in preceding])
        caption_width = max(1.0, caption_bbox[2] - caption_bbox[0])
        line_width = max(1.0, line.bbox[2] - line.bbox[0])
        left_shift = caption_bbox[0] - line.bbox[0]
        vertical_gap = line.bbox[1] - caption_bbox[3]
        if left_shift < max(24.0, caption_width * 0.25):
            continue
        if line_width < caption_width * 1.5:
            continue
        if not -1.0 <= vertical_gap <= 24.0:
            continue
        if substantial_prose_word_count(strip_sentinels(line.text)) < 5:
            continue
        return index
    return None


def _equation_flagged_small_caps_heading_block(
    page_index: int,
    record: _RawBlockRec,
    equation_record: bool,
) -> Optional[TextBlock]:
    """Recover appendix headings misclassified by small-caps font geometry."""
    if not equation_record or not 1 <= len(record.lines) <= 3:
        return None
    compact = " ".join(strip_sentinels(record.bare_text()).split()).strip()
    small_caps_heading = bool(
        re.fullmatch(
            r"(?:(?:[IVXLCDM]+)\.|[A-Z](?:\.\d+)?)\s+[A-Z][A-Z\s,-]{3,80}",
            compact,
        )
    )
    numbered_formula_heading = bool(
        re.fullmatch(
            r"(?:\d+(?:\.\d+)+|[A-Z]\.\d+)\s+[A-Z].{3,100}",
            compact,
        )
        and len(_prose_words(compact)) <= 12
    )
    if not small_caps_heading and not numbered_formula_heading:
        return None
    if small_caps_heading and any(
        sentinel_char_count(line.text) for line in record.lines
    ):
        return None
    first = record.lines[0]
    if any(not lines_share_y_band(first, line) for line in record.lines[1:]):
        return None
    combined = _LineRec(
        text=" ".join(line.text.strip() for line in record.lines),
        bbox=record.bbox,
        spans=[span for line in record.lines for span in line.spans],
        prose_bboxes=[bbox for line in record.lines for bbox in line.prose_bboxes],
        math_bboxes=[bbox for line in record.lines for bbox in line.math_bboxes],
        math_run_bboxes=[
            bbox for line in record.lines for bbox in line.math_run_bboxes
        ],
    )
    heading = heading_block_from_line(page_index, combined)
    if heading is not None:
        heading.no_merge = True
    return heading


def _can_be_shown_formula_bridge_blocks(
    page_index: int,
    record: _RawBlockRec,
) -> Optional[List[TextBlock]]:
    """Translate prose slots around a fixed ``can be shown`` formula tower.

    Complex multi-record formulas should keep their exact source position.
    The short English clauses around them have compact Chinese equivalents,
    so translating each prose slot in place preserves both the formula and
    the original paragraph geometry.
    """
    if (
        record.flow_inline_math
        or not record.detached_inline_scripts
        or len(record.lines) < 4
    ):
        return None
    first = record.lines[0]
    first_outside = " ".join(_text_outside_sentinels(first.text).split())
    last = record.lines[-1]
    last_outside = " ".join(_text_outside_sentinels(last.text).split())
    if (
        not first_outside.lower().endswith("can be")
        or not re.match(r"^and\b", last_outside, re.IGNORECASE)
        or not re.search(r"\bThen\b", last_outside, re.IGNORECASE)
        or len(last.math_run_bboxes) < 2
    ):
        return None

    first_prose_fragments = _math_line_prose_fragments(first)
    if len(first_prose_fragments) != 2:
        return None

    lead_slots: List[TextBlock] = []
    for fragment in first_prose_fragments:
        accumulator = _SegmentAccumulator()
        _accumulate_line(accumulator, fragment)
        slot = accumulator.flush(page_index)
        if slot is None or slot.source_math_bboxes:
            return None
        slot.block_type = "formula_prose"
        slot.no_merge = True
        slot.nowrap = True
        slot.preserve_position = True
        slot.flow_inline_math = True
        slot.redact_bboxes = list(fragment.prose_bboxes or [fragment.bbox])
        slot.keepout_bboxes = list(first.math_run_bboxes) or None
        lead_slots.append(slot)

    shown_accumulator = _SegmentAccumulator()
    _accumulate_line(shown_accumulator, record.lines[1])
    shown = shown_accumulator.flush(page_index)
    if shown is None:
        return None
    shown.block_type = "formula_prose"
    shown.no_merge = True
    shown.nowrap = True
    shown.preserve_position = True
    shown.flow_inline_math = True

    suffixes: List[TextBlock] = []
    for prose_bbox in last.prose_bboxes:
        spans = [
            span
            for span in last.spans
            if "bbox" in span
            and bbox_intersection_area(
                tuple(float(value) for value in span["bbox"]),
                prose_bbox,
            )
            / max(bbox_area(prose_bbox), 0.1)
            >= 0.8
        ]
        text = text_from_spans(spans)
        if not re.search(r"[A-Za-z]{2,}", text):
            continue
        sizes = [float(span.get("size", 0.0)) for span in spans]
        colors = [int_to_rgb(int(span.get("color", 0))) for span in spans]
        suffixes.append(
            TextBlock(
                page_index=page_index,
                bbox=prose_bbox,
                text=text,
                font_size=median_or_default(sizes, lead_slots[0].font_size),
                color=dominant_color(colors),
                source_lines=1,
                nowrap=True,
                no_merge=True,
                redact_bboxes=[prose_bbox],
                block_type="formula_prose",
                should_translate=True,
                preserve_position=True,
                flow_inline_math=True,
                source_line_bboxes=(prose_bbox,),
                source_prose_bboxes=(prose_bbox,),
            )
        )
    if len(suffixes) < 2:
        return None
    return [*lead_slots, shown, *suffixes]


def _equation_inline_prose_slot_blocks(
    page_index: int,
    record: _RawBlockRec,
) -> Optional[List[TextBlock]]:
    """Recover prose slots that share a row with a detached formula tower.

    TeX radicals and stacked operators can make MuPDF classify the complete
    inline sentence as an equation record.  Translating only the normal-font
    slots keeps every formula glyph at its source coordinates and avoids
    dropping the sentence altogether.
    """
    if len(record.lines) < 2:
        return None
    formula_lines = [line for line in record.lines if not line_is_prose(line)]
    if not formula_lines:
        return None

    for line in record.lines:
        fragments = _math_line_prose_fragments(line)
        if len(fragments) < 2 or not _line_is_prose_dominant_sentence(line):
            continue
        line_height = max(1.0, line.bbox[3] - line.bbox[1])
        detached_towers = [
            candidate
            for candidate in formula_lines
            if candidate is not line
            and candidate.bbox[3] - candidate.bbox[1] >= line_height * 1.5
            and candidate.bbox[0] >= line.bbox[2] - 2.0
            and candidate.bbox[0] - line.bbox[2] <= line_height * 1.25
            and min(candidate.bbox[3], line.bbox[3])
            - max(candidate.bbox[1], line.bbox[1])
            >= line_height * 0.4
        ]
        if not detached_towers:
            continue

        math_keepouts = list(
            dict.fromkeys(
                bbox
                for candidate in record.lines
                for bbox in (candidate.math_run_bboxes or candidate.math_bboxes)
            )
        )
        blocks: List[TextBlock] = []
        for fragment in fragments:
            accumulator = _SegmentAccumulator()
            _accumulate_line(accumulator, fragment)
            block = accumulator.flush(page_index)
            if block is None:
                continue
            block.block_type = "formula_prose"
            block.no_merge = True
            block.nowrap = True
            block.preserve_position = True
            block.redact_bboxes = list(fragment.prose_bboxes)
            block.keepout_bboxes = math_keepouts or None
            block.source_line_bboxes = tuple(fragment.prose_bboxes)
            blocks.append(block)
        if len(blocks) == len(fragments):
            return blocks
    return None


def _equation_record_is_formula_only(record: _RawBlockRec) -> bool:
    """Keep semantic labels inside a compact display equation immutable."""
    compact = " ".join(strip_sentinels(record.bare_text()).split())
    if any(_line_is_prose_dominant_sentence(line) for line in record.lines):
        return False
    prose_fragments = [
        " ".join(strip_sentinels(fragment.text).split()).strip()
        for line in record.lines
        for fragment in _math_line_prose_fragments(line)
    ]
    if any(
        re.match(
            r"^[.;:]?\s*(?:and|for|from|let|satisfy|term|then|to|where|with)\b",
            fragment,
            re.IGNORECASE,
        )
        for fragment in prose_fragments
    ):
        return False
    prose_words = _prose_words(compact)
    if len(prose_words) > 6:
        return False
    if re.search(
        r"\b(?:where|denotes?|represents?|means?|we|therefore|thus|hence)\b",
        compact,
        re.IGNORECASE,
    ):
        return False
    relation_count = len(re.findall(r"(?:=|≤|≥|<|>|∈|∨|∧|¬|\||\\)", compact))
    if relation_count < 1:
        return False
    math_chars = sentinel_char_count(record.bare_text())
    numbered = any(
        EQUATION_NUMBER_RE.fullmatch("".join(strip_sentinels(line.text).split()))
        for line in record.lines
    )
    return numbered or relation_count >= 2 or math_chars >= 8


def _compact_display_formula_prose_slot(
    page_index: int,
    record: _RawBlockRec,
    line_index: int,
) -> Optional[TextBlock]:
    line = record.lines[line_index]
    if any(
        EQUATION_NUMBER_RE.fullmatch(
            "".join(strip_sentinels(other.text).split())
        )
        for other in record.lines
    ):
        return None
    outside = " ".join(_text_outside_sentinels(line.text).split())
    standalone_connector = bool(
        not line.math_bboxes
        and re.fullmatch(
            r"(?:and|for|given|if|when|where|with)\s*[:,]?",
            outside,
            re.IGNORECASE,
        )
        and any(
            other_index != line_index
            and not line_is_prose(other)
            and min(line.bbox[3], other.bbox[3])
            - max(line.bbox[1], other.bbox[1])
            >= min(
                line.bbox[3] - line.bbox[1],
                other.bbox[3] - other.bbox[1],
            )
            * 0.65
            for other_index, other in enumerate(record.lines)
        )
    )
    if not (
        _prose_line_shares_math_row(record, line_index)
        or standalone_connector
    ):
        return None
    if (
        not re.search(r"[A-Za-z]{2,}", outside)
        or len(_prose_words(outside)) > 12
    ):
        return None
    slot = _SegmentAccumulator()
    _accumulate_line(slot, line)
    block = slot.flush(page_index)
    if block is None:
        return None
    block.block_type = "formula_prose"
    block.no_merge = True
    block.nowrap = True
    block.preserve_position = True
    block.redact_bboxes = list(line.prose_bboxes or [line.bbox])
    block.keepout_bboxes = list(line.math_run_bboxes) or None
    return block


def _detached_equation_connector_block(
    page_index: int,
    record: _RawBlockRec,
) -> Optional[TextBlock]:
    """Recover a connector emitted as its own display-equation record."""
    if any(
        EQUATION_NUMBER_RE.fullmatch(
            "".join(strip_sentinels(candidate.text).split())
        )
        for candidate in record.lines
    ):
        return None
    connector_lines = []
    for line_index, candidate in enumerate(record.lines):
        outside = " ".join(_text_outside_sentinels(candidate.text).split())
        if (
            not candidate.math_bboxes
            and re.fullmatch(
                r"(?:and|for|given|if|when|where|with)\s*[:,]?",
                outside,
                re.IGNORECASE,
            )
        ):
            connector_lines.append((line_index, candidate))
    if len(connector_lines) != 1:
        return None
    connector_index, line = connector_lines[0]
    formula_lines = [
        candidate
        for line_index, candidate in enumerate(record.lines)
        if line_index != connector_index
    ]
    if any(line_is_prose(candidate) for candidate in formula_lines):
        return None
    line_height = max(1.0, line.bbox[3] - line.bbox[1])
    if formula_lines and min(
        max(
            candidate.bbox[1] - line.bbox[3],
            line.bbox[1] - candidate.bbox[3],
            0.0,
        )
        for candidate in formula_lines
    ) > line_height * 1.5:
        return None
    accumulator = _SegmentAccumulator()
    _accumulate_line(accumulator, line)
    block = accumulator.flush(page_index)
    if block is None:
        return None
    x0, y0, x1, y1 = block.bbox
    source_bbox = line.bbox
    shares_formula_row = any(
        min(line.bbox[3], candidate.bbox[3])
        - max(line.bbox[1], candidate.bbox[1])
        > 0.0
        for candidate in formula_lines
    )
    block.bbox = (
        x0,
        y0,
        x1 if shares_formula_row else max(x1, x0 + block.font_size * 2.4),
        y1,
    )
    connector = " ".join(_text_outside_sentinels(line.text).split()).rstrip(":,").casefold()
    block.block_type = (
        "body" if shares_formula_row and connector == "and" else "formula_prose"
    )
    block.no_merge = True
    block.nowrap = True
    block.preserve_position = True
    block.redact_bboxes = list(line.prose_bboxes or [source_bbox])
    block.source_line_bboxes = (source_bbox,)
    block.source_prose_bboxes = (source_bbox,)
    return block


_TASK_LIST_MARKER_RE = re.compile(r"^\(([A-Z])(\d{1,2})\)\s+")


def _structured_task_list_block(
    page_index: int,
    record: _RawBlockRec,
) -> Optional[TextBlock]:
    """Keep a multi-item task specification in one reading-order unit."""
    markers: List[Tuple[int, str, int]] = []
    for line_index, line in enumerate(record.lines):
        plain = " ".join(strip_sentinels(line.text).split()).strip()
        match = _TASK_LIST_MARKER_RE.match(plain)
        if match is not None:
            markers.append((line_index, match.group(1), int(match.group(2))))
    if len(markers) < 3:
        return None
    prefixes = {prefix for _, prefix, _ in markers}
    numbers = [number for _, _, number in markers]
    if len(prefixes) != 1 or numbers != list(
        range(numbers[0], numbers[0] + len(numbers))
    ):
        return None
    if markers[-1][0] - markers[0][0] < len(markers) - 1:
        return None
    plain_record = " ".join(strip_sentinels(record.bare_text()).split())
    if len(_prose_words(plain_record)) < max(30, len(markers) * 8):
        return None

    accumulator = _SegmentAccumulator()
    for line in record.lines:
        _accumulate_line(accumulator, line)
    block = accumulator.flush(page_index)
    if block is None:
        return None
    block.block_type = "body"
    block.no_merge = True
    block.nowrap = False
    block.preserve_position = False
    return block


def segments_from_record(
    page_index: int, record: _RawBlockRec, equation_record: bool = False
) -> List[TextBlock]:
    """Second pass: build translatable segments from one raw block.

    For equation zones only full prose lines are extracted (the formula
    typesetting is preserved); for normal blocks a residual display-equation
    line still splits the segment and keeps its original rendering."""
    if equation_record and _record_is_single_line_numbered_display_equation(record):
        return []
    if equation_record and _record_is_annotated_formula_decoration(record):
        return []
    if equation_record:
        detached_connector = _detached_equation_connector_block(page_index, record)
        if detached_connector is not None:
            return [detached_connector]
    if equation_record and _equation_record_is_formula_only(record):
        return [
            slot
            for line_index in range(len(record.lines))
            if (
                slot := _compact_display_formula_prose_slot(
                    page_index,
                    record,
                    line_index,
                )
            )
            is not None
        ]

    if not equation_record:
        task_list = _structured_task_list_block(page_index, record)
        if task_list is not None:
            return [task_list]

    formula_bridge_blocks = _can_be_shown_formula_bridge_blocks(page_index, record)
    if formula_bridge_blocks is not None:
        return formula_bridge_blocks

    if equation_record:
        inline_prose_slots = _equation_inline_prose_slot_blocks(page_index, record)
        if inline_prose_slots is not None:
            return inline_prose_slots

    formula_tail_segments = segments_from_formula_tail_prose(page_index, record)
    if formula_tail_segments is not None:
        return formula_tail_segments

    small_caps_heading = _equation_flagged_small_caps_heading_block(
        page_index,
        record,
        equation_record,
    )
    if small_caps_heading is not None:
        return [small_caps_heading]

    academic_start = next(
        (
            index
            for index, line in enumerate(record.lines)
            if _ACADEMIC_FORMULA_STATEMENT_RE.match(
                " ".join(strip_sentinels(line.text).split())
            )
        ),
        None,
    )
    if academic_start is not None and academic_start > 0:
        academic_record = _RawBlockRec(
            lines=list(record.lines[academic_start:]),
            detached_inline_scripts=record.detached_inline_scripts,
        )
        prefix_record = _RawBlockRec(
            lines=list(record.lines[:academic_start]),
            detached_inline_scripts=record.detached_inline_scripts,
        )
        prefix_block = _fragmented_inline_math_paragraph_block(
            page_index,
            prefix_record,
            False,
        )
        academic_block = _fragmented_inline_math_paragraph_block(
            page_index,
            academic_record,
            False,
        )
        prefix_segments = (
            [prefix_block]
            if prefix_block is not None
            else segments_from_record(
                page_index,
                prefix_record,
                equation_record=False,
            )
        )
        academic_segments = (
            [academic_block]
            if academic_block is not None
            else segments_from_record(
                page_index,
                academic_record,
                equation_record=False,
            )
        )
        if prefix_segments and academic_segments:
            for block in academic_segments:
                block.no_merge = True
            return [*prefix_segments, *academic_segments]

    segments: List[TextBlock] = []
    table_record = record_is_table(record)
    caption_record = bool(
        _CAPTION_RE.match(" ".join(strip_sentinels(record.bare_text()).split()).lstrip())
    )
    trailing_caption_prose_start = (
        _trailing_caption_prose_start(record) if caption_record else None
    )
    if trailing_caption_prose_start is not None:
        caption = _SegmentAccumulator()
        for line in record.lines[:trailing_caption_prose_start]:
            _accumulate_line(caption, line)
        caption_block = caption.flush(page_index)
        paragraph = _SegmentAccumulator()
        for line in record.lines[trailing_caption_prose_start:]:
            _accumulate_line(paragraph, line)
        paragraph_block = paragraph.flush(page_index)
        split_blocks: List[TextBlock] = []
        if caption_block is not None:
            caption_block.block_type = "caption"
            caption_block.no_merge = True
            split_blocks.append(caption_block)
        if paragraph_block is not None:
            paragraph_block.block_type = "body"
            paragraph_block.nowrap = False
            split_blocks.append(paragraph_block)
        return split_blocks
    if caption_record and not table_record:
        # A caption is one reading-order unit even when TeX emits citation
        # superscripts or inline formula spans as separate physical rows.
        # Keeping the source record whole preserves every wrapped caption line
        # and gives inline tokens a single owner during reflow.
        caption = _SegmentAccumulator()
        for line in record.lines:
            _accumulate_line(caption, line)
        caption_block = caption.flush(page_index)
        if caption_block is not None:
            caption_block.block_type = "caption"
            caption_block.no_merge = True
            caption_block.nowrap = False
            return [caption_block]
    if table_record:
        prose_equation_segments = _prose_wrapped_numbered_equation_segments(
            page_index,
            record,
        )
        if prose_equation_segments is not None:
            return prose_equation_segments
    fragmented_paragraph = _fragmented_inline_math_paragraph_block(
        page_index,
        record,
        equation_record,
    )
    if fragmented_paragraph is not None:
        return [fragmented_paragraph]
    if equation_record and table_record:
        for line in record.lines:
            if not line_is_prose(line):
                continue
            cell = _SegmentAccumulator()
            _accumulate_line(cell, line)
            block = cell.flush(page_index)
            if block is not None:
                block.nowrap = True
                block.no_merge = True
                if _line_is_prose_dominant_sentence(line):
                    # Full sentences wedged between formula rows ("This leads
                    # to the Static SB problem:") are translatable; the redact
                    # bbox stays trimmed against neighbouring formula cells.
                    block.block_type = "body"
                else:
                    block.block_type = "table"
                block.redact_bboxes = [equation_table_prose_redact_bbox(line, record.lines)]
                segments.append(block)
        return segments

    if not equation_record and table_record:
        trailing_prose_start = _trailing_table_prose_start(record)
        table_lines = (
            record.lines
            if trailing_prose_start is None
            else record.lines[:trailing_prose_start]
        )
        for line in table_lines:
            cell = _SegmentAccumulator()
            _accumulate_line(cell, line)
            block = cell.flush(page_index)
            if block is not None:
                block.nowrap = True
                block.no_merge = True
                block.block_type = "table"
                segments.append(block)
        if trailing_prose_start is not None:
            trailing_lines = list(record.lines[trailing_prose_start:])
            first = trailing_lines[0]
            heading_lines = [
                line for line in trailing_lines if lines_share_y_band(first, line)
            ]
            combined_heading = _LineRec(
                text=" ".join(line.text.strip() for line in heading_lines),
                bbox=union_bbox([line.bbox for line in heading_lines]),
                spans=[span for line in heading_lines for span in line.spans],
                prose_bboxes=[
                    bbox for line in heading_lines for bbox in line.prose_bboxes
                ],
                math_bboxes=[
                    bbox for line in heading_lines for bbox in line.math_bboxes
                ],
                math_run_bboxes=[
                    bbox for line in heading_lines for bbox in line.math_run_bboxes
                ],
            )
            if line_looks_like_section_heading(combined_heading):
                heading = heading_block_from_line(page_index, combined_heading)
                if heading is not None:
                    segments.append(heading)
                trailing_lines = trailing_lines[len(heading_lines) :]

            paragraph = _SegmentAccumulator()
            for line in trailing_lines:
                _accumulate_line(paragraph, line)
            block = paragraph.flush(page_index)
            if block is not None:
                block.block_type = "body"
                block.nowrap = False
                block.no_merge = True
                segments.append(block)
        return segments

    current = _SegmentAccumulator()
    current_has_inline_tail = False
    current_no_merge = False
    current_min_y0: Optional[float] = None
    current_inline_prefix_right: Optional[float] = None
    current_reflowed_inline_formula = False
    preserved_line_bboxes: List[BBox] = []

    def flush_current() -> None:
        nonlocal current, current_has_inline_tail, current_no_merge, current_min_y0
        nonlocal current_inline_prefix_right, current_reflowed_inline_formula
        block = current.flush(page_index)
        if block is not None:
            if current_has_inline_tail and not block.keepout_bboxes:
                # Keep the redaction tied to physical text spans. A single
                # union rectangle can erase nearby display-equation glyphs when
                # PyMuPDF vertically overlaps a prose tail and the next formula.
                block.redact_bboxes = list(current.line_bboxes)
            single_tail_after_prefix = (
                current_inline_prefix_right is not None
                and len(current.line_bboxes) == 1
                and current.line_bboxes[0][0] >= current_inline_prefix_right - 0.5
            )
            if (
                current_min_y0 is not None
                and block.bbox[1] < current_min_y0
                and not single_tail_after_prefix
            ):
                original_height = max(block.bbox[3] - block.bbox[1], block.font_size * 1.2)
                y0 = current_min_y0
                y1 = block.bbox[3]
                if y1 <= y0:
                    y1 = y0 + original_height
                block.bbox = (block.bbox[0], y0, block.bbox[2], y1)
                if not block.keepout_bboxes:
                    block.redact_bboxes = list(current.line_bboxes)
            if current_no_merge:
                block.no_merge = True
            if (
                current_reflowed_inline_formula
                and segments
                and segments[-1].block_type == "run_in_heading"
                and strip_sentinels(segments[-1].text).rstrip().endswith((".", ":"))
                and _looks_like_inline_heading_pair(segments[-1], block)
            ):
                segments[-1] = merge_two_blocks(segments[-1], block)
            else:
                segments.append(block)
        current = _SegmentAccumulator()
        current_has_inline_tail = False
        current_no_merge = False
        current_min_y0 = None
        current_inline_prefix_right = None
        current_reflowed_inline_formula = False

    def append_math_line_prose_fragments(
        source_line: _LineRec,
        fragments: Sequence[_LineRec],
    ) -> None:
        flush_current()
        math_keepouts = list(source_line.math_run_bboxes or source_line.math_bboxes)
        preserved_line_bboxes.extend(math_keepouts)
        for fragment in fragments:
            fragment_accumulator = _SegmentAccumulator()
            _accumulate_line(fragment_accumulator, fragment)
            block = fragment_accumulator.flush(page_index)
            if block is None:
                continue
            block.block_type = "formula_prose"
            block.no_merge = True
            block.nowrap = True
            block.redact_bboxes = list(fragment.prose_bboxes)
            block.keepout_bboxes = list(math_keepouts) or None
            block.source_line_bboxes = tuple(fragment.prose_bboxes)
            segments.append(block)

    skip_line_indexes: set[int] = set()
    for line_index, line in enumerate(record.lines):
        if line_index in skip_line_indexes:
            continue
        if not equation_record:
            heading_parts = [line]
            for candidate_index in range(
                line_index + 1,
                min(len(record.lines), line_index + 4),
            ):
                candidate = record.lines[candidate_index]
                previous_part = heading_parts[-1]
                horizontal_gap = candidate.bbox[0] - previous_part.bbox[2]
                if (
                    abs(candidate.bbox[1] - line.bbox[1]) > 2.0
                    or horizontal_gap < -1.0
                    or horizontal_gap > 42.0
                ):
                    break
                heading_parts.append(candidate)
                combined = _LineRec(
                    text=" ".join(part.text.strip() for part in heading_parts),
                    bbox=union_bbox([part.bbox for part in heading_parts]),
                    spans=[span for part in heading_parts for span in part.spans],
                    prose_bboxes=[
                        bbox for part in heading_parts for bbox in part.prose_bboxes
                    ],
                    math_bboxes=[
                        bbox for part in heading_parts for bbox in part.math_bboxes
                    ],
                    math_run_bboxes=[
                        bbox for part in heading_parts for bbox in part.math_run_bboxes
                    ],
                )
                if line_looks_like_section_heading(combined):
                    line = combined
                    skip_line_indexes.update(
                        range(line_index + 1, candidate_index + 1)
                    )
                    break
        word_fragment = _line_has_same_baseline_word_neighbors(record, line_index)
        if (
            not equation_record
            and _line_is_inline_2d_formula_cluster_member(record, line_index)
        ):
            flush_current()
            preserved_line_bboxes.append(line.bbox)
            continue
        if not equation_record and not word_fragment and line_looks_like_section_heading(line):
            flush_current()
            heading = heading_block_from_line(page_index, line)
            if heading is not None:
                segments.append(heading)
                continue
        next_physical_line = (
            record.lines[line_index + 1] if line_index + 1 < len(record.lines) else None
        )
        if not current.lines:
            suffix_reflow_y0 = _same_row_formula_suffix_reflow_y0(
                line,
                preserved_line_bboxes,
            )
            if suffix_reflow_y0 is not None:
                current_min_y0 = max(
                    current_min_y0 or float("-inf"),
                    suffix_reflow_y0,
                )
        if (
            not equation_record
            and not word_fragment
            and line_looks_like_runin_bold_heading(line, next_physical_line)
        ):
            flush_current()
            heading = heading_block_from_line(page_index, line)
            if heading is not None:
                segments.append(heading)
                current_min_y0 = max(
                    current_min_y0 or float("-inf"),
                    heading.bbox[3] + max(1.0, heading.font_size * 0.12),
                )
                current_inline_prefix_right = heading.bbox[2]
                continue
        if not equation_record and line_looks_like_summary_leadin(line):
            flush_current()
            summary = heading_block_from_line(page_index, line)
            if summary is not None:
                segments.append(summary)
                continue
        if not equation_record and accumulator_is_hyphenated_caption(current):
            _accumulate_line(current, line)
            continue
        if not equation_record and current.lines:
            # A caption opener fused into a record that begins with figure
            # labels must start its own segment; otherwise the translated
            # caption anchors at the labels' bbox and overprints the figure
            # (oc p4 Figure 4: labels + caption in one raw block).
            compact_line = " ".join(strip_sentinels(line.text).split()).strip()
            if _CAPTION_RE.match(compact_line):
                flush_current()
        if not equation_record and not caption_record:
            split = split_bold_leadin_line(line)
            if split is not None:
                flush_current()
                leadin, tail = split
                if line_contains_url(tail):
                    url_block = body_block_from_line(page_index, line, no_merge=True)
                    if url_block is not None:
                        url_block.nowrap = True
                        segments.append(url_block)
                    continue
                heading = heading_block_from_line(page_index, leadin)
                if heading is not None:
                    heading.block_type = "run_in_heading"
                    heading.preserve_position = True
                    segments.append(heading)
                    current_min_y0 = max(
                        current_min_y0 or float("-inf"),
                        heading.bbox[3] + max(1.0, heading.font_size * 0.12),
                    )
                    current_inline_prefix_right = heading.bbox[2]
                if line_starts_with_leadin_marker(leadin):
                    current_no_merge = True
                line = tail
        if not equation_record and next_physical_line is not None:
            continuation_probe = _SegmentAccumulator()
            _accumulate_line(continuation_probe, line)
            if _line_continues_hyphenated_formula_prose(
                next_physical_line,
                continuation_probe,
            ):
                _accumulate_line(current, line)
                current_has_inline_tail = True
                continue
        if not equation_record:
            interleaved_sentence = _interleaved_formula_sentence_block(
                page_index,
                record,
                line_index,
            )
            if interleaved_sentence is not None:
                flush_current()
                sentence_block, sentence_end = interleaved_sentence
                segments.append(sentence_block)
                skip_line_indexes.update(range(line_index + 1, sentence_end + 1))
                continue
        if _line_continues_hyphenated_formula_prose(line, current):
            _accumulate_line(current, line)
            current_has_inline_tail = True
            continue
        if (
            equation_record
            and next_physical_line is not None
            and _lines_form_dual_sided_derivation(line, next_physical_line)
        ):
            flush_current()
            combined = _LineRec(
                text=f"{line.text} {next_physical_line.text}",
                bbox=union_bbox([line.bbox, next_physical_line.bbox]),
                spans=[*line.spans, *next_physical_line.spans],
                prose_bboxes=[*line.prose_bboxes, *next_physical_line.prose_bboxes],
                math_bboxes=[*line.math_bboxes, *next_physical_line.math_bboxes],
                math_run_bboxes=[
                    *line.math_run_bboxes,
                    *next_physical_line.math_run_bboxes,
                ],
            )
            explanation = body_block_from_line(page_index, combined, no_merge=True)
            if explanation is not None:
                explanation.block_type = "formula_prose"
                explanation.nowrap = False
                segments.append(explanation)
                skip_line_indexes.add(line_index + 1)
            continue
        if (
            equation_record
            and line.math_run_bboxes
            and _line_is_short_derivation_explanation(line)
        ):
            flush_current()
            explanation = body_block_from_line(page_index, line, no_merge=True)
            if explanation is not None:
                explanation.block_type = "formula_prose"
                explanation.nowrap = False
                segments.append(explanation)
            continue
        formula_prose_suffix = _math_line_formula_prose_suffix(line)
        if formula_prose_suffix is not None:
            flush_current()
            sentence = _SegmentAccumulator()
            _accumulate_line(sentence, formula_prose_suffix)
            continuation_index = line_index + 1
            while (
                continuation_index < len(record.lines)
                and not sentence_final_text(sentence.lines[-1])
            ):
                next_line = record.lines[continuation_index]
                next_plain = strip_sentinels(next_line.text).lstrip()
                vertical_gap = next_line.bbox[1] - sentence.line_bboxes[-1][3]
                if (
                    next_line.prose_bboxes
                    and re.match(r"[a-z]", next_plain)
                    and -2.0 <= vertical_gap <= 16.0
                ):
                    _accumulate_line(sentence, next_line)
                    skip_line_indexes.add(continuation_index)
                    continuation_index += 1
                    continue
                break
            block = sentence.flush(page_index)
            if block is not None:
                prefix_keepouts = [
                    bbox
                    for bbox in line.math_run_bboxes
                    if bbox[2] <= formula_prose_suffix.bbox[0] + 0.8
                ]
                block.block_type = "formula_prose"
                block.no_merge = True
                block.nowrap = False
                block.keepout_bboxes = prefix_keepouts or None
                if prefix_keepouts and block.redact_bboxes:
                    prefix_lines = [
                        _LineRec(text="", bbox=keepout, spans=[])
                        for keepout in prefix_keepouts
                    ]
                    block.redact_bboxes = [
                        trim_redact_bbox_against_formula_lines(redact, prefix_lines)
                        for redact in block.redact_bboxes
                    ]
                segments.append(block)
                preserved_line_bboxes.extend(prefix_keepouts)
            continue
        prose_fragments = _math_line_prose_fragments(line)
        compact_length = len("".join(strip_sentinels(line.text).split()))
        math_ratio = (
            sentinel_char_count(line.text) / compact_length
            if compact_length
            else 0.0
        )
        formula_prefix_with_prose_suffix = bool(
            prose_fragments
            and line.text.lstrip().startswith(SENTINEL_OPEN)
            and line.math_run_bboxes
            and all(
                fragment.bbox[0]
                >= max(math_bbox[2] for math_bbox in line.math_run_bboxes) - 0.8
                for fragment in prose_fragments
            )
        )
        interleaved_formula_prose_row = bool(
            prose_fragments
            and line.text.lstrip().startswith(SENTINEL_OPEN)
            and len(line.math_run_bboxes) >= 2
            and substantial_prose_word_count(strip_sentinels(line.text)) >= 4
            and (
                sentence_final_text(line.text)
                or (
                    current.lines
                    and not sentence_final_text(current.lines[-1])
                )
            )
        )
        record_content_left = min(
            (
                candidate.bbox[0]
                for candidate in record.lines
                if candidate.prose_bboxes
            ),
            default=line.bbox[0],
        )
        reflowable_formula_prefix = bool(
            (formula_prefix_with_prose_suffix or interleaved_formula_prose_row)
            and min(math_bbox[0] for math_bbox in line.math_run_bboxes)
            <= record_content_left + 4.0
        )
        if not equation_record and reflowable_formula_prefix:
            if (
                interleaved_formula_prose_row
                and current.lines
                and not sentence_final_text(current.lines[-1])
            ):
                _accumulate_line(current, line)
                current_has_inline_tail = True
                current_reflowed_inline_formula = True
                continuation_index = line_index + 1
                previous_line = line
                while continuation_index < len(record.lines):
                    next_line = record.lines[continuation_index]
                    vertical_gap = next_line.bbox[1] - previous_line.bbox[3]
                    vertical_overlap = min(
                        previous_line.bbox[3], next_line.bbox[3]
                    ) - max(previous_line.bbox[1], next_line.bbox[1])
                    shorter_height = max(
                        1.0,
                        min(
                            previous_line.bbox[3] - previous_line.bbox[1],
                            next_line.bbox[3] - next_line.bbox[1],
                        ),
                    )
                    same_visual_row = vertical_overlap >= shorter_height * 0.45
                    if (
                        not line_is_prose(next_line)
                        or not (same_visual_row or -2.0 <= vertical_gap <= 16.0)
                    ):
                        break
                    _accumulate_line(current, next_line)
                    current_has_inline_tail = True
                    skip_line_indexes.add(continuation_index)
                    previous_line = next_line
                    continuation_index += 1
                    if sentence_final_text(next_line.text):
                        break
                continue
            flush_current()
            formula_sentence = _SegmentAccumulator()
            _accumulate_line(formula_sentence, line)
            continuation_index = line_index + 1
            while (
                continuation_index < len(record.lines)
                and not sentence_final_text(formula_sentence.lines[-1])
            ):
                next_line = record.lines[continuation_index]
                vertical_gap = next_line.bbox[1] - formula_sentence.line_bboxes[-1][3]
                if not line_is_prose(next_line) or not -2.0 <= vertical_gap <= 16.0:
                    break
                _accumulate_line(formula_sentence, next_line)
                skip_line_indexes.add(continuation_index)
                continuation_index += 1
            block = formula_sentence.flush(page_index)
            if block is not None:
                block.block_type = "formula_prose"
                block.no_merge = True
                block.nowrap = False
                block.keepout_bboxes = None
                segments.append(block)
            continue
        if (
            not equation_record
            and prose_fragments
            and not _line_is_equation_explanation(line)
            and (
                not line_is_prose(line)
                or (
                    line.text.lstrip().startswith(SENTINEL_OPEN)
                    and (
                        math_ratio >= 0.30
                        or formula_prefix_with_prose_suffix
                    )
                )
            )
        ):
            append_math_line_prose_fragments(line, prose_fragments)
            continue
        continues_existing_formula = bool(
            current.lines
            and any(SENTINEL_OPEN in current_line for current_line in current.lines)
            and line_continues_inline_formula_tail(line, current)
        )
        prose_tail = None if continues_existing_formula else line_formula_prefix_prose_tail(line)
        if prose_tail is not None:
            next_line = (
                record.lines[line_index + 1] if line_index + 1 < len(record.lines) else None
            )
            if next_line is not None and line_is_prose(next_line):
                flush_current()
                block = formula_prefix_tail_block(page_index, prose_tail, next_line)
                if block is not None:
                    segments.append(block)
                    skip_line_indexes.add(line_index + 1)
                    continue
            line = prose_tail
        if equation_record:
            math_dominant = bool(
                compact_length
                and math_ratio >= 0.55
            )
            if (
                prose_fragments
                and (math_dominant or formula_prefix_with_prose_suffix)
                and not _line_is_equation_explanation(line)
            ):
                append_math_line_prose_fragments(line, prose_fragments)
                continue
            if not line_is_prose(line):
                next_line = (
                    record.lines[line_index + 1]
                    if line_index + 1 < len(record.lines)
                    else None
                )
                if next_line is not None and line_is_short_prose_prefix(line, next_line):
                    _accumulate_line(current, line)
                    continue
                if next_line is not None and line_is_short_prose_before_formula(line, next_line):
                    _accumulate_line(current, line)
                    current_has_inline_tail = True
                    continue
                if _line_continues_wrapped_prose_connector(line, current):
                    _accumulate_line(current, line)
                    continue
                previous_tail = (
                    strip_sentinels(current.lines[-1]).strip().lower()
                    if current.lines
                    else ""
                )
                if (
                    previous_tail == "as"
                    and _line_is_display_formula_cluster_member(record, line_index)
                ):
                    flush_current()
                    preserved_line_bboxes.append(line.bbox)
                    continue
                if line_continues_inline_formula_tail(line, current):
                    _accumulate_line(current, line)
                    current_has_inline_tail = True
                    continue
                if prose_fragments:
                    append_math_line_prose_fragments(line, prose_fragments)
                    continue
                flush_current()
                preserved_line_bboxes.append(line.bbox)
                continue
            slot_block = _compact_display_formula_prose_slot(
                page_index,
                record,
                line_index,
            )
            if (
                slot_block is not None
                or _prose_line_shares_math_row(record, line_index)
            ):
                # The prose sits on the display equation's own visual row
                # (the "where U(a,b) = {...}" clause beside "min ... (1)");
                # Long prose stays fixed, but compact natural-language slots
                # such as "where" or "given x. Since x is available as" can
                # be translated inside their own source span without moving
                # the surrounding display formula.
                flush_current()
                if slot_block is not None:
                    segments.append(slot_block)
                    continue
                preserved_line_bboxes.append(line.bbox)
                continue
        elif line_continues_inline_formula_tail(line, current):
            _accumulate_line(current, line)
            current_has_inline_tail = True
            continue
        elif is_display_equation_line(line.text) and not _line_is_equation_explanation(line):
            # A full English sentence stays translatable even when its inline
            # math makes it look like a display equation — the math is
            # placeholder-protected anyway ("where Π(p0,p1) ⊂ P is the subset
            # of joint distributions..." on IPMF p3).
            continues_prose_with_inline_formula = bool(
                current.lines
                and prose_fragments
                and line_is_prose(line)
                and not sentence_final_text(current.lines[-1])
                and line.bbox[0] <= current.line_bboxes[-1][0] + 8.0
                and -3.0
                <= line.bbox[1] - current.line_bboxes[-1][3]
                <= 16.0
            )
            if continues_prose_with_inline_formula:
                _accumulate_line(current, line)
                current_has_inline_tail = True
                current_reflowed_inline_formula = True
                continue
            flush_current()
            preserved_line_bboxes.append(line.bbox)
            continue
        if line.is_cell:
            # Table cell: its own single-line block anchored at the cell bbox.
            flush_current()
            cell = _SegmentAccumulator()
            _accumulate_line(cell, line)
            block = cell.flush(page_index)
            if block is not None:
                block.nowrap = True
                segments.append(block)
            continue
        if not equation_record and line_looks_like_list_item(line):
            flush_current()
            current_no_merge = True
        elif current_no_merge and current.lines and not line_continues_list_item(line, current):
            flush_current()
        _accumulate_line(current, line)

    flush_current()
    if preserved_line_bboxes:
        # Attach with a one-line tolerance: a preserved equation line often
        # sits in the gap between two segment bboxes, yet the reflowed text
        # must avoid it and QA must know the line stays verbatim.
        for block in segments:
            reach = expand_bbox(block.bbox, 8.0)
            plain = " ".join(strip_sentinels(block.text).split()).strip()
            inline_formula_leadin = bool(
                re.search(
                    r"(?:\b(?:as|is|are|be|ratio|equals?|gives?)|[:=])\s*$",
                    plain,
                    re.IGNORECASE,
                )
            )
            hits = [
                bbox
                for bbox in preserved_line_bboxes
                if bboxes_intersect(bbox, reach)
                or (
                    inline_formula_leadin
                    and bbox_share_y_band(block.bbox, bbox)
                    and 0.0 <= bbox[0] - block.bbox[2] <= max(16.0, block.font_size * 1.6)
                )
            ]
            if hits:
                block.keepout_bboxes = (block.keepout_bboxes or []) + hits
    return segments


def _accumulate_line(accumulator: "_SegmentAccumulator", line: _LineRec) -> None:
    accumulator.lines.append(line.text)
    accumulator.line_bboxes.append(line.bbox)
    accumulator.prose_bboxes.extend(line.prose_bboxes)
    accumulator.math_bboxes.extend(line.math_bboxes)
    accumulator.math_run_bboxes.extend(line.math_run_bboxes)
    prose_bboxes = set(line.prose_bboxes)
    for span in line.spans:
        span_bbox = (
            tuple(float(x) for x in span["bbox"])
            if "bbox" in span
            else None
        )
        if span_bbox is not None:
            accumulator.bboxes.append(span_bbox)
        if "size" in span:
            span_size = float(span["size"])
            accumulator.font_sizes.append(span_size)
            if span_bbox in prose_bboxes:
                accumulator.prose_font_sizes.append(span_size)
        if "color" in span:
            accumulator.colors.append(int_to_rgb(span["color"]))
        span_chars = len(normalize_span_text(span.get("text", "")).strip())
        span_is_prose = span_bbox is None or span_bbox in prose_bboxes
        if not span_is_prose:
            continue
        span_bold = span_is_bold(span)
        if span_chars and not accumulator.seen_text:
            accumulator.starts_bold = span_bold
            accumulator.seen_text = True
        accumulator.total_chars += span_chars
        if span_bold:
            accumulator.bold_chars += span_chars
            fragment = strip_sentinels(normalize_span_text(span.get("text", ""))).strip()
            if fragment:
                accumulator.bold_fragments.append(fragment)


@dataclass
class _SegmentAccumulator:
    lines: List[str] = field(default_factory=list)
    line_bboxes: List[BBox] = field(default_factory=list)
    bboxes: List[BBox] = field(default_factory=list)
    font_sizes: List[float] = field(default_factory=list)
    prose_font_sizes: List[float] = field(default_factory=list)
    colors: List[Color] = field(default_factory=list)
    bold_chars: int = 0
    total_chars: int = 0
    starts_bold: bool = False
    seen_text: bool = False
    bold_fragments: List[str] = field(default_factory=list)
    prose_bboxes: List[BBox] = field(default_factory=list)
    math_bboxes: List[BBox] = field(default_factory=list)
    math_run_bboxes: List[BBox] = field(default_factory=list)

    def flush(self, page_index: int) -> Optional[TextBlock]:
        text = join_lines(self.lines)
        if not text or not self.bboxes:
            return None
        bold = self.total_chars > 0 and self.bold_chars / self.total_chars >= BLOCK_BOLD_RATIO
        bold_terms = extract_bold_terms(self.bold_fragments, text)
        if self.math_bboxes and self.prose_bboxes:
            redact_bboxes: Optional[List[BBox]] = list(
                dict.fromkeys([*self.prose_bboxes, *self.math_bboxes])
            )
        else:
            redact_bboxes = list(self.line_bboxes) if len(self.line_bboxes) > 1 else None
        return TextBlock(
            page_index=page_index,
            bbox=union_bbox(self.bboxes),
            text=text,
            font_size=median_or_default(
                self.prose_font_sizes or self.font_sizes,
                9.0,
            ),
            color=dominant_color(self.colors),
            bold=bold,
            starts_bold=self.starts_bold,
            source_lines=len(self.lines),
            redact_bboxes=redact_bboxes,
            source_line_bboxes=tuple(dict.fromkeys(self.line_bboxes)),
            source_prose_bboxes=tuple(dict.fromkeys(self.prose_bboxes)),
            source_math_bboxes=tuple(self.math_run_bboxes),
            source_math_atom_bboxes=tuple(self.math_bboxes),
            source_math_atom_groups=_group_math_atoms_by_run(
                self.math_run_bboxes,
                self.math_bboxes,
            ),
            bold_terms=bold_terms,
            bold_prefix=self.starts_bold and bool(bold_terms) and not bold,
        )


def _group_math_atoms_by_run(
    run_bboxes: Sequence[BBox],
    atom_bboxes: Sequence[BBox],
) -> Tuple[Tuple[BBox, ...], ...]:
    """Assign each math span to the most specific enclosing formula run."""
    groups: List[List[BBox]] = [[] for _ in run_bboxes]
    for atom in atom_bboxes:
        atom_area = max(0.1, bbox_area(atom))
        candidates = [
            (index, bbox_intersection_area(atom, run) / atom_area)
            for index, run in enumerate(run_bboxes)
            if bbox_intersection_area(atom, run) / atom_area >= 0.55
        ]
        if not candidates:
            continue
        # Tall radicals and summations make neighboring run hulls overlap.
        # Prefer the run that actually contains most of this atom. Only when
        # coverage is equal is the smaller hull the more specific formula.
        # Choosing by hull area alone can attach atoms fully owned by the next
        # physical row to a smaller preceding run whose tall CMSY bbox merely
        # overlaps them.
        owner = min(
            candidates,
            key=lambda candidate: (
                -candidate[1],
                bbox_area(run_bboxes[candidate[0]]),
            ),
        )[0]
        groups[owner].append(atom)
    return tuple(tuple(dict.fromkeys(group)) for group in groups)


def extract_bold_terms(fragments: Sequence[str], block_text: str) -> Tuple[str, ...]:
    terms: List[str] = []
    seen: set[str] = set()
    plain = " ".join(strip_sentinels(block_text).split())
    for fragment in fragments:
        term = " ".join(strip_sentinels(fragment).split()).strip()
        term = term.strip(" \t\r\n.,;:：。")
        if not term or len(term) > 90:
            continue
        if sentinel_char_count(fragment):
            continue
        method_match = re.search(
            r"(?:^|\s)(?:\d+\)|\([A-Za-z0-9]{1,3}\))\s*"
            r"([A-Za-z][A-Za-z0-9_-]{2,24})(?=\s*\()",
            term,
        )
        candidates = [method_match.group(1)] if method_match else [term]
        for candidate in candidates:
            if not re.search(r"[A-Za-z0-9]", candidate):
                continue
            if re.match(
                r"^(?:et\s+al\.?|(?:19|20)\d{2})\b",
                candidate,
                re.IGNORECASE,
            ):
                continue
            key = candidate.lower()
            if key in seen:
                continue
            # Single common words are noisy; short enumerated method names
            # (Real, ZKW, pns, lemon) are explicit local bold hints.
            words = _PROSE_WORD_RE.findall(candidate)
            leading_colon_label = bool(
                re.match(
                    rf"^{re.escape(candidate)}\s*[:：]",
                    plain,
                    re.IGNORECASE,
                )
            )
            if (
                len(words) == 1
                and len(candidate) < 6
                and "-" not in candidate
                and method_match is None
                and not leading_colon_label
            ):
                continue
            if candidate not in plain:
                continue
            seen.add(key)
            terms.append(candidate)
    return tuple(terms)


def is_display_equation_line(line_text: str) -> bool:
    """A physical line whose content is dominated by math-font spans (or that
    is symbol-dense / a bare equation number) is a display-equation line."""
    bare = strip_sentinels(line_text).strip()
    compact = "".join(bare.split())
    if not compact:
        return bool(line_text.strip())
    if EQUATION_NUMBER_RE.fullmatch(compact):
        return True
    inside = sentinel_char_count(line_text)
    if inside and compact and inside / len(compact) >= EQUATION_LINE_MATH_RATIO:
        return True
    return looks_like_math(bare)


def sentinel_char_count(text: str) -> int:
    count = 0
    inside = False
    for char in text:
        if char == SENTINEL_OPEN:
            inside = True
        elif char == SENTINEL_CLOSE:
            inside = False
        elif inside and not char.isspace():
            count += 1
    return count


def is_injection_text(text: str) -> bool:
    """Detect prompt-injection lines targeting LLM readers/reviewers."""
    compact = " ".join(text.split())
    return any(pattern.search(compact) for pattern in INJECTION_PATTERNS)


def is_math_span(
    font: str, flags: int, text: str, size: float = 0.0, line_max_size: float = 0.0
) -> bool:
    """Spans the translator must never alter: math fonts, superscripts,
    single-letter italic variables.

    The superscript bit alone is only trusted for genuinely small spans:
    MuPDF marks whole continuation lines as superscript when they start with
    a subscript glyph, and those are normal prose."""
    if MATH_FONT_RE.search(font or ""):
        return True
    stripped = text.strip()
    if flags & 1:  # superscript bit
        if (
            stripped.lower() in _SHORT_PROSE_WORDS
            and size > 0
            and line_max_size > 0
            and size >= line_max_size * 0.85
        ):
            return False
        if size <= 0 or line_max_size <= 0 or size < line_max_size * 0.85:
            return True
        if len(stripped) <= 3:
            return True
        return False
    if (flags & 2) and len(stripped) <= 2 and stripped.isalpha():
        return True
    return False


def strip_sentinels(text: str) -> str:
    return text.replace(SENTINEL_OPEN, "").replace(SENTINEL_CLOSE, "")


def _translation_repeats_source(block: TextBlock, translated_text: str) -> bool:
    """Whether the translator handed the source back verbatim.

    Whitespace is ignored so a wrapped source and a single-line answer still
    compare equal; any CJK character means the text was actually translated.
    """
    source = "".join(strip_sentinels(block.text).split())
    target = "".join(strip_sentinels(translated_text).split())
    if not source or source != target:
        return False
    return not any(is_cjk_char(char) for char in target)


def protect_text(text: str) -> Tuple[str, Dict[int, str]]:
    """Replace math/citation/URL fragments with ⟦n⟧ placeholders.

    Returns the protected text plus the mapping used to restore fragments
    after translation.
    """
    mapping: Dict[int, str] = {}

    def stash(fragment: str) -> str:
        index = len(mapping)
        mapping[index] = fragment
        return "\u27e6%d\u27e7" % index

    def stash_sentinel_run(match: re.Match) -> str:
        cleaned = normalize_protected_formula_fragment(strip_sentinels(match.group(0)).strip())
        if not cleaned:
            return " "
        return stash(cleaned)

    def stash_url(match: re.Match) -> str:
        fragment = match.group(0)
        trail = ""
        while fragment and fragment[-1] in URL_TRAILING_PUNCT:
            trail = fragment[-1] + trail
            fragment = fragment[:-1]
        if not fragment:
            return match.group(0)
        return stash(fragment) + trail

    def stash_math_token(match: re.Match) -> str:
        token = match.group(0)
        # Never re-stash text containing existing placeholders.
        if "\u27e6" in token or "\u27e7" in token:
            return token
        attached_prose = _ATTACHED_MATH_PROSE_SUFFIX_RE.fullmatch(token)
        if attached_prose is not None:
            formula = attached_prose.group("formula")
            prose = attached_prose.group("prose")
            trailing = attached_prose.group("trailing")
            return f"{stash(formula)} {prose}{trailing}"
        return stash(token)

    protected = SENTINEL_RUN_RE.sub(stash_sentinel_run, text)
    protected = URL_RE.sub(stash_url, protected)
    protected = CITATION_RE.sub(lambda m: stash(m.group(0)), protected)
    prompt_spans = _structured_prompt_list_spans(protected)
    replacements: List[Tuple[int, int, str]] = []
    for start, end in prompt_spans:
        fragment = protected[start:end]
        if "\u27e6" in fragment or "\u27e7" in fragment:
            continue
        replacements.append((start, end, stash(fragment)))
    for start, end, placeholder in reversed(replacements):
        protected = protected[:start] + placeholder + protected[end:]
    protected = _protect_contribution_names(protected, stash)
    protected = MATH_TOKEN_RE.sub(stash_math_token, protected)
    return protected, mapping


_CONTRIBUTION_ROLE_RE = re.compile(
    r"^\s*(?:Data and operations|Evaluation experiments|Model design|"
    r"Post-training|Pre-training|Robot hardware|Robot software|"
    r"Training infrastructure|Writing and illustration)\s*:\s*",
    re.IGNORECASE,
)
_PERSON_NAME_RE = re.compile(
    r"(?<![A-Za-z])(?:[A-Z][A-Za-z'’-]+|[A-Z]\.)(?:\s+|-)"
    r"(?:[A-Z][A-Za-z'’-]+|[A-Z]\.)(?![A-Za-z])"
)


def _protect_contribution_names(text: str, stash: Callable[[str], str]) -> str:
    """Keep author names stable in appendix contribution lists.

    Transliteration plus an English gloss can more than double these dense
    list rows.  The role label and conjunctions remain translatable; only the
    proper names are replaced with the same placeholders used for formulas.
    """
    role = _CONTRIBUTION_ROLE_RE.match(text)
    if role is None:
        return text
    suffix = text[role.end() :]
    names = list(_PERSON_NAME_RE.finditer(suffix))
    if len(names) < 3:
        return text
    pieces = [text[: role.end()]]
    cursor = 0
    for match in names:
        pieces.append(suffix[cursor : match.start()])
        pieces.append(stash(match.group(0)))
        cursor = match.end()
    pieces.append(suffix[cursor:])
    return "".join(pieces)


def _structured_prompt_list_spans(text: str) -> List[Tuple[int, int]]:
    """Return balanced code-list spans from robotics prompt examples."""
    if not _STRUCTURED_PROMPT_CUE_RE.search(strip_sentinels(text)):
        return []
    spans: List[Tuple[int, int]] = []
    depth = 0
    start = -1
    for index, char in enumerate(text):
        if char == "[":
            if depth == 0:
                start = index
            depth += 1
        elif char == "]" and depth:
            depth -= 1
            if depth == 0 and start >= 0:
                fragment = text[start : index + 1]
                if _SINGLE_QUOTED_LITERAL_RE.search(fragment):
                    spans.append((start, index + 1))
                start = -1
    return spans


def _without_structured_prompt_lists(text: str) -> str:
    """Remove preserved prompt code before untranslated-prose scoring."""
    spans = _structured_prompt_list_spans(text)
    if not spans:
        return text
    pieces: List[str] = []
    cursor = 0
    for start, end in spans:
        pieces.append(text[cursor:start])
        pieces.append(" ")
        cursor = end
    pieces.append(text[cursor:])
    return "".join(pieces)


def normalize_protected_formula_fragment(fragment: str) -> str:
    """Make extracted math-script runs renderable in ordinary PDF fonts.

    Small adjacent math spans arrive as separate sentinels, sometimes with a
    physical-line space between base/sup/sub spans. Keep a plain ASCII formula
    representation rather than Unicode subscript/superscript variants because
    common CJK fonts lack glyphs such as ᵛ/ₜ and render them as boxes.
    """
    cleaned = re.sub(r"\s+([_^])", r"\1", fragment)
    cleaned = re.sub(r"([_^])\s+\{", r"\1{", cleaned)
    cleaned = re.sub(r"\}\s+([_^])", r"}\1", cleaned)
    cleaned = re.sub(r"\s+([,.;:，。；：)\]])", r"\1", cleaned)
    return cleaned.strip()


def restore_text(
    translated: str,
    mapping: Dict[int, str],
    *,
    preserve_indices: Sequence[int] = (),
) -> Tuple[str, List[int]]:
    """Swap ⟦n⟧ placeholders back to the original fragments.

    Placeholders the translator dropped are appended at the end so no
    formula content is ever lost; their indices are reported for warnings.
    """
    seen: set = set()
    preserved = set(preserve_indices)

    def restored_fragment(index: int) -> str:
        fragment = mapping[index]
        if index in preserved:
            return SENTINEL_OPEN + fragment + SENTINEL_CLOSE
        return fragment

    def swap(match: re.Match) -> str:
        index = int(match.group(1))
        if index in mapping:
            seen.add(index)
            return restored_fragment(index)
        return ""

    restored = PLACEHOLDER_RE.sub(swap, translated)
    for _ in range(len(mapping)):
        if not PLACEHOLDER_RE.search(restored):
            break
        expanded = PLACEHOLDER_RE.sub(swap, restored)
        if expanded == restored:
            break
        restored = expanded
    missing = [index for index in mapping if index not in seen]
    if missing:
        tail = " ".join(restored_fragment(index) for index in missing)
        restored = restored.rstrip() + " " + tail
    return restored, missing


CJK_CHAR_RE = r"\u2e80-\u9fff\uf900-\ufaff\u3000-\u303f"
_SPACE_BEFORE_FULLWIDTH_RE = re.compile(  # noqa: E501
    r"\s+([\u3001\u3002\uff0c\uff1b\uff1a\uff1f\uff01\uff09\u3009\u300b\u300d\u3011\u2019\u201d])"
)
_SPACE_AFTER_FULLWIDTH_RE = re.compile(r"([\uff08\u3008\u300a\u300c\u3010\u2018\u201c])\s+")
_CJK_THEN_LATIN_RE = re.compile(r"([%s])([A-Za-z0-9$(\[\u2200-\u22ff\u0370-\u03ff])" % CJK_CHAR_RE)
_LATIN_THEN_CJK_RE = re.compile(r"([A-Za-z0-9%%)\]\u2200-\u22ff\u0370-\u03ff])([%s])" % CJK_CHAR_RE)
_FULLWIDTH_PUNCT = (  # noqa: E501
    "\u3001\u3002\uff0c\uff1b\uff1a\uff1f\uff01\uff08\uff09\u300a\u300b\u300c\u300d\u3010\u3011"
)


def clean_translation(text: str) -> str:
    """Normalise spacing of inserted Chinese text (盘古之白 + punctuation)."""
    cleaned = re.sub(r"[ \t]{2,}", " ", text)
    cleaned = cleaned.replace("\u27e8", "\u3008").replace("\u27e9", "\u3009")
    cleaned = cleaned.replace(").）", "）")
    cleaned = cleaned.replace(").，", "），")
    cleaned = _SPACE_BEFORE_FULLWIDTH_RE.sub(r"\1", cleaned)
    cleaned = _SPACE_AFTER_FULLWIDTH_RE.sub(r"\1", cleaned)
    # Thin breathing space between CJK and Latin/digits/math, both directions.
    cleaned = _CJK_THEN_LATIN_RE.sub(r"\1 \2", cleaned)
    cleaned = _LATIN_THEN_CJK_RE.sub(r"\1 \2", cleaned)
    cleaned = cleaned.replace("\u3008 ", "\u3008").replace(" \u3009", "\u3009")
    # No space between fullwidth punctuation and anything.
    cleaned = re.sub(r"([%s]) +" % _FULLWIDTH_PUNCT, r"\1", cleaned)
    cleaned = re.sub(r" +([%s])" % _FULLWIDTH_PUNCT, r"\1", cleaned)
    cleaned = re.sub(r"[ \t]{2,}", " ", cleaned)
    return cleaned.strip()


def is_line_number_span(
    text: str, size: float, line_max_size: float, isolated: bool = True
) -> bool:
    """Margin line numbers: short pure-digit spans much smaller than body text.

    Gutter numbers are isolated PDF text objects. A small digit span glued to
    neighbouring spans on the same line is a sub/superscript inside a formula
    (e.g. the 0 in X_0 set in CMR7) and must never be dropped."""
    stripped = text.strip()
    if not stripped.isdigit() or len(stripped) > 3:
        return False
    if len(stripped) == 1:
        return False
    if not isolated:
        return False
    if size <= LINE_NUMBER_MAX_SIZE:
        return True
    return bool(line_max_size) and size <= line_max_size * LINE_NUMBER_SIZE_RATIO


def _is_margin_line_number_span(
    text: str,
    span: dict,
    size: float,
    page_width: float | None,
    isolated: bool,
) -> bool:
    stripped = text.strip()
    if not isolated or not stripped.isdigit() or len(stripped) > 4:
        return False
    if page_width is None or page_width <= 0 or "bbox" not in span:
        return False
    if size > MARGIN_LINE_NUMBER_MAX_SIZE:
        return False
    x0, _y0, x1, _y1 = (float(value) for value in span["bbox"])
    center_x = (x0 + x1) / 2.0
    edge_band = max(24.0, page_width * MARGIN_LINE_NUMBER_EDGE_RATIO)
    return center_x <= edge_band or center_x >= page_width - edge_band


def _review_line_number_bboxes(page_dict: dict) -> List[BBox]:
    """Detect indented review line numbers as a page-level sequence.

    NeurIPS review templates place line numbers beside the text column rather
    than at the physical page edge. A candidate must be smaller than a prose
    line in the same raw block, share its baseline, sit just outside it, and
    belong to a sequence containing at least three consecutive increments.
    """
    candidates: List[Tuple[float, int, BBox]] = []
    numeric_spans: List[Tuple[float, int, BBox]] = []
    for raw_block in page_dict.get("blocks", []):
        if raw_block.get("type") != 0:
            continue
        line_records: List[Tuple[BBox, str, float, List[dict]]] = []
        for raw_line in raw_block.get("lines", []):
            spans = [
                span
                for span in raw_line.get("spans", [])
                if normalize_span_text(span.get("text", "")).strip()
            ]
            bbox = raw_line.get("bbox")
            if not spans or not bbox:
                continue
            text = "".join(normalize_span_text(span.get("text", "")) for span in spans)
            max_size = max(float(span.get("size", 0.0)) for span in spans)
            line_records.append((tuple(float(value) for value in bbox), text, max_size, spans))

            stripped = text.strip()
            # str.isdigit accepts superscripts ("284²" in figure dimension
            # labels) that int() rejects; line numbers are plain ASCII.
            if (
                len(spans) == 1
                and stripped.isascii()
                and stripped.isdigit()
                and len(stripped) <= 4
                and max_size <= MARGIN_LINE_NUMBER_MAX_SIZE
                and "bbox" in spans[0]
            ):
                span_bbox = tuple(float(value) for value in spans[0]["bbox"])
                numeric_spans.append(
                    ((span_bbox[0] + span_bbox[2]) / 2.0, int(stripped), span_bbox)
                )

        for bbox, text, size, spans in line_records:
            stripped = text.strip()
            if (
                len(spans) != 1
                or not stripped.isascii()
                or not stripped.isdigit()
                or len(stripped) > 4
            ):
                continue
            if size > MARGIN_LINE_NUMBER_MAX_SIZE or "bbox" not in spans[0]:
                continue
            matched_prose = False
            for other_bbox, other_text, other_size, _ in line_records:
                if other_bbox == bbox:
                    continue
                if other_size < size * 1.25 or other_bbox[2] - other_bbox[0] < 45.0:
                    continue
                if len(_ASCII_WORD_DETECT_RE.findall(other_text)) < 2:
                    continue
                vertical_overlap = max(
                    0.0,
                    min(bbox[3], other_bbox[3]) - max(bbox[1], other_bbox[1]),
                )
                min_height = max(
                    1.0,
                    min(bbox[3] - bbox[1], other_bbox[3] - other_bbox[1]),
                )
                if vertical_overlap / min_height < 0.5:
                    continue
                left_gap = other_bbox[0] - bbox[2]
                right_gap = bbox[0] - other_bbox[2]
                if 2.0 <= left_gap <= 72.0 or 2.0 <= right_gap <= 72.0:
                    matched_prose = True
                    break
            if matched_prose:
                span_bbox = tuple(float(value) for value in spans[0]["bbox"])
                candidates.append(((span_bbox[0] + span_bbox[2]) / 2.0, int(stripped), span_bbox))

    clusters: List[List[Tuple[float, int, BBox]]] = []
    for candidate in sorted(candidates, key=lambda item: item[0]):
        for cluster in clusters:
            cluster_center = sum(item[0] for item in cluster) / len(cluster)
            if abs(candidate[0] - cluster_center) <= 4.0:
                cluster.append(candidate)
                break
        else:
            clusters.append([candidate])

    output: List[BBox] = []
    for cluster in clusters:
        ordered = sorted(cluster, key=lambda item: (item[2][1], item[1]))
        if len(ordered) < 4:
            continue
        increments = [right[1] - left[1] for left, right in zip(ordered, ordered[1:])]
        if sum(increment == 1 for increment in increments) < 3:
            continue
        if sum(increment > 0 for increment in increments) < max(3, len(increments) // 2):
            continue
        cluster_center = sum(item[0] for item in ordered) / len(ordered)
        min_value = min(item[1] for item in ordered)
        max_value = max(item[1] for item in ordered)
        output.extend(
            bbox
            for center, value, bbox in numeric_spans
            if abs(center - cluster_center) <= 4.0
            and min_value - 2 <= value <= max_value + 2
        )
    return list(dict.fromkeys(output))


def join_lines(lines: Sequence[str]) -> str:
    """Join physical lines into flowing text, mending hyphenated words."""
    output = ""
    for line in lines:
        if not output:
            output = line
        elif output.endswith("-") and line[:1].islower():
            if _line_break_hyphen_belongs_to_term(output, line):
                output += line
            else:
                output = output[:-1] + line
        else:
            separator = (
                "  "
                if output.rstrip().endswith(SENTINEL_CLOSE)
                and line.lstrip().startswith(SENTINEL_OPEN)
                else " "
            )
            output += separator + line
    return output.strip()


def _line_break_hyphen_belongs_to_term(previous: str, following: str) -> bool:
    left_match = re.search(r"([A-Za-z]+)-$", previous)
    right_match = re.match(r"([a-z]+)", following)
    if not left_match or not right_match:
        return False
    left_context = previous[-120:]
    context = (left_context + following[:120]).lower()
    join_offset = len(left_context)
    try:
        from pdf_zh_translator.corpus import get_relevant_terms

        terms = get_relevant_terms([context])
    except Exception:
        return False
    for term in terms:
        term_lower = term.lower()
        start = context.find(term_lower)
        while start >= 0:
            if start < join_offset < start + len(term_lower):
                return True
            start = context.find(term_lower, start + 1)
    return False


def merge_paragraph_blocks(
    blocks: Sequence[TextBlock],
    graphic_regions_by_page: Optional[Dict[int, List[BBox]]] = None,
) -> List[TextBlock]:
    """Merge consecutive blocks that geometrically belong to one paragraph.

    Blocks arrive in document (reading) order. Two neighbours merge when they
    sit on the same page, have similar font sizes, overlap horizontally, and
    the vertical gap matches line spacing rather than paragraph spacing.
    """
    merged: List[TextBlock] = []
    for block in blocks:
        previous = merged[-1] if merged else None
        regions = (
            graphic_regions_by_page.get(block.page_index, []) if graphic_regions_by_page else []
        )
        if previous is not None and can_merge_blocks(previous, block, regions):
            joined = merge_two_blocks(previous, block)
            if _looks_like_float_wrap_boundary(previous, block) and (
                _float_wrap_region_beside(previous, regions) is not None
            ):
                # The reflow around the side float abandons the source line
                # grid, so anchored-in-place math cannot align any more:
                # flow the formulas as inline clips and let redaction remove
                # the source glyphs.
                joined = replace(joined, flow_inline_math=True)
            merged[-1] = joined
        else:
            merged.append(block)
        while len(merged) >= 2:
            earlier, joined = merged[-2:]
            joined_regions = (
                graphic_regions_by_page.get(joined.page_index, [])
                if graphic_regions_by_page
                else []
            )
            if not _looks_like_formula_split_source_continuation(
                earlier,
                joined,
                joined_regions,
            ):
                break
            merged[-2:] = [merge_two_blocks(earlier, joined)]
    return merged


def _has_parallel_header_cell_lines(block: TextBlock) -> bool:
    """Whether a PDF text block contains side-by-side table header cells."""
    line_boxes = block.source_line_bboxes
    for index, first in enumerate(line_boxes):
        first_height = max(1.0, first[3] - first[1])
        for second in line_boxes[index + 1 :]:
            second_height = max(1.0, second[3] - second[1])
            vertical_overlap = min(first[3], second[3]) - max(first[1], second[1])
            if vertical_overlap < min(first_height, second_height) * 0.55:
                continue
            horizontal_gap = max(second[0] - first[2], first[0] - second[2], 0.0)
            if horizontal_gap >= max(8.0, block.font_size * 0.8):
                return True
    return False


def _is_multiline_formula_only_block(block: TextBlock) -> bool:
    return bool(
        block.source_lines >= 2
        and len(re.findall(r"[A-Za-z]{2,}", _text_outside_sentinels(block.text))) <= 1
        and sentinel_char_count(block.text) >= 2
    )


def _ends_with_centered_formula_statement(block: TextBlock) -> bool:
    """Whether a prose statement ends on a separate centered formula row."""
    if (
        block.source_lines < 2
        or not block.source_math_bboxes
        or not block.text.rstrip().endswith(SENTINEL_CLOSE)
        or len(_prose_words(_text_outside_sentinels(block.text))) < 4
        or not block.source_line_bboxes
    ):
        return False
    last_line = max(
        block.source_line_bboxes,
        key=lambda bbox: ((bbox[1] + bbox[3]) / 2.0, bbox[0]),
    )
    block_width = max(1.0, block.bbox[2] - block.bbox[0])
    line_width = max(1.0, last_line[2] - last_line[0])
    centered_offset = abs(
        (last_line[0] + last_line[2]) / 2.0
        - (block.bbox[0] + block.bbox[2]) / 2.0
    )
    return bool(
        line_width <= block_width * 0.72
        and centered_offset <= block_width * 0.16
        and any(bbox_share_y_band(last_line, math) for math in block.source_math_bboxes)
    )


def _looks_like_formula_split_source_continuation(
    prev: TextBlock,
    nxt: TextBlock,
    graphic_regions: Sequence[BBox] = (),
) -> bool:
    """Rejoin prose records split at a tall inline-formula source boundary."""
    if prev.page_index != nxt.page_index:
        return False
    if prev.block_type != "body" or nxt.block_type not in {"body", "formula_prose"}:
        return False
    if (
        prev.nowrap
        or nxt.nowrap
        or prev.preserve_position
        or nxt.preserve_position
        or prev.bold
        or nxt.bold
        or prev.starts_bold
        or nxt.starts_bold
        or nxt.bold_prefix
    ):
        return False
    if not (prev.no_merge or nxt.no_merge):
        return False
    if not (prev.keepout_bboxes or nxt.keepout_bboxes):
        return False
    if prev.source_lines < 2 or nxt.source_lines < 2:
        return False
    if sentence_final_text(prev.text):
        return False
    if abs(prev.font_size - nxt.font_size) > PARAGRAPH_SIZE_TOLERANCE:
        return False

    previous_plain = " ".join(strip_sentinels(prev.text).split())
    following_plain = " ".join(strip_sentinels(nxt.text).split())
    if (
        len(_prose_words(previous_plain)) < 8
        or len(_prose_words(following_plain)) < 4
        or not re.search(r"[A-Za-z]$", previous_plain)
        or not re.match(r"[^A-Za-z0-9]*[A-Za-z]", following_plain)
        or _CAPTION_RE.match(previous_plain)
        or _CAPTION_RE.match(following_plain)
        or looks_like_action_skeleton_sequence(following_plain)
        or _ends_with_centered_formula_statement(prev)
    ):
        return False

    reference = max(prev.font_size, nxt.font_size, 1.0)
    gap = nxt.bbox[1] - prev.bbox[3]
    if gap > reference * 0.25 or gap < -reference * 1.3:
        return False
    overlap = min(prev.bbox[2], nxt.bbox[2]) - max(prev.bbox[0], nxt.bbox[0])
    narrower = min(prev.bbox[2] - prev.bbox[0], nxt.bbox[2] - nxt.bbox[0])
    if narrower <= 0.0 or overlap / narrower < 0.9:
        return False
    if graphic_regions and bbox_crosses_graphic_region(
        union_bbox([prev.bbox, nxt.bbox]),
        graphic_regions,
    ):
        return False
    return True


def can_merge_blocks(
    prev: TextBlock,
    nxt: TextBlock,
    graphic_regions: Sequence[BBox] = (),
) -> bool:
    if "run_in_heading" in {prev.block_type, nxt.block_type}:
        previous_plain = " ".join(strip_sentinels(prev.text).split())
        structured_statement = bool(
            re.match(
                r"^(?:Definition|Proposition|Theorem|Lemma|Corollary|Remark)\s+\d",
                previous_plain,
                re.IGNORECASE,
            )
        )
        if (
            prev.block_type == "run_in_heading"
            and not structured_statement
            and len(SENTINEL_RUN_RE.findall(nxt.text)) <= 1
            and _looks_like_inline_heading_pair(prev, nxt)
        ):
            if graphic_regions and bbox_crosses_graphic_region(
                union_bbox([prev.bbox, nxt.bbox]),
                graphic_regions,
            ):
                return False
            return True
        return False
    if (
        prev.block_type == "formula_prose"
        and nxt.block_type == "formula_prose"
        and prev.flow_inline_math
        and nxt.flow_inline_math
        and prev.no_merge
        and nxt.no_merge
        and (prev.preserve_position or nxt.preserve_position)
    ):
        return False
    if (
        prev.block_type == "formula_prose"
        and nxt.block_type == "body"
        and prev.flow_inline_math
        and nxt.flow_inline_math
        and prev.no_merge
        and nxt.no_merge
        and prev.preserve_position
        and prev.source_lines == 1
        and nxt.source_lines >= 2
    ):
        return False
    if _looks_like_formula_split_source_continuation(
        prev,
        nxt,
        graphic_regions,
    ):
        return True
    if _looks_like_academic_formula_statement_pair(prev, nxt):
        return True
    if prev.no_merge and prev.source_lines > 1 and prev.keepout_bboxes:
        # A short prose lead may merge into the sentence immediately before
        # its fixed display formula. Once consumed, its keepout is a hard
        # paragraph boundary: chaining the following prose would reflow text
        # beside the display formula instead of below it.
        return False
    next_plain = " ".join(strip_sentinels(nxt.text).split())
    if re.match(r"^[\u2022*-]?\s*Action\s+Skeleton\s*:", next_plain, re.IGNORECASE):
        # A natural-language Goal record immediately above the pseudocode is
        # independently translatable. Joining both would protect and skip the
        # goal together with the immutable action calls.
        return False
    if _looks_like_piecewise_formula_condition(
        prev,
        " ".join(strip_sentinels(prev.text).split()),
    ) or _looks_like_piecewise_formula_condition(
        nxt,
        next_plain,
    ):
        return False
    if _is_multiline_formula_only_block(nxt) and (
        sentence_final_text(prev.text)
        or (prev.block_type == "formula_prose" and prev.no_merge)
    ):
        return False
    following_outside = _text_outside_sentinels(nxt.text).lstrip()
    if (
        _ends_with_centered_formula_statement(prev)
        and len(_prose_words(following_outside)) >= 3
        and re.match(r"^[\s\.,;:)]*[A-Z]", following_outside)
    ):
        return False
    if (
        _is_multiline_formula_only_block(prev)
        and len(re.findall(r"[A-Za-z]{2,}", following_outside)) >= 3
        and re.match(r"^[\s\.,;:)]*[A-Z]", following_outside)
    ):
        return False
    if _looks_like_formula_row_suffix_pair(prev, nxt):
        return True
    if nxt.bold_prefix:
        # A run-in heading starts a new structural unit. Formula-continuation
        # heuristics must not pull it backward into the preceding paragraph.
        return False
    float_wrap_merge = _looks_like_float_wrap_boundary(prev, nxt) and (
        _float_wrap_region_beside(prev, graphic_regions) is not None
    )
    previous_plain = " ".join(strip_sentinels(prev.text).split())
    if (
        _TABLE_CAPTION_RE.match(previous_plain)
        and _has_parallel_header_cell_lines(nxt)
    ):
        return False
    if _looks_like_caption_continuation_pair(prev, nxt):
        return True
    if _CAPTION_RE.match(strip_sentinels(nxt.text).lstrip()) and not float_wrap_merge:
        # A caption opener belongs to the float below the preceding table
        # rows, never to those rows. It may still absorb its own continuation
        # on the next iteration through _looks_like_caption_continuation_pair.
        # A wrap continuation that happens to resume at an inline figure
        # citation ("... as shown in | Fig. 5. In Shell Game ...") is prose,
        # not a caption.
        return False
    if _looks_like_inline_heading_pair(prev, nxt):
        if (
            not float_wrap_merge
            and graphic_regions
            and bbox_crosses_graphic_region(
                union_bbox([prev.bbox, nxt.bbox]),
                graphic_regions,
            )
        ):
            return False
        return True
    if _looks_like_same_line_formula_split(prev, nxt):
        caption_split = bool(_CAPTION_RE.match(strip_sentinels(prev.text).lstrip()))
        if (
            not caption_split
            and not float_wrap_merge
            and graphic_regions
            and bbox_crosses_graphic_region(
                union_bbox([prev.bbox, nxt.bbox]),
                graphic_regions,
            )
        ):
            return False
        return True
    if _looks_like_formula_gap_bridge_pair(prev, nxt):
        if (
            not float_wrap_merge
            and graphic_regions
            and bbox_crosses_graphic_region(
                union_bbox([prev.bbox, nxt.bbox]),
                graphic_regions,
            )
        ):
            return False
        return True
    if _looks_like_formula_rich_continuation_pair(prev, nxt):
        if (
            not float_wrap_merge
            and graphic_regions
            and bbox_crosses_graphic_region(
                union_bbox([prev.bbox, nxt.bbox]),
                graphic_regions,
            )
        ):
            return False
        return True
    if prev.nowrap or nxt.nowrap:
        return can_merge_fixed_width_prose_blocks(prev, nxt, graphic_regions)
    if prev.no_merge or nxt.no_merge:
        return False
    if sentence_final_text(prev.text) and nxt.starts_bold:
        return False
    if prev.page_index != nxt.page_index:
        return False
    if sentence_final_text(prev.text) and len(nxt.source_line_bboxes) >= 2:
        first_line_x = nxt.source_line_bboxes[0][0]
        continuation_x = min(
            bbox[0] for bbox in nxt.source_line_bboxes[1:4]
        )
        if first_line_x - continuation_x >= max(5.0, nxt.font_size * 0.55):
            return False
    if abs(prev.font_size - nxt.font_size) > PARAGRAPH_SIZE_TOLERANCE:
        return False
    reference = max(prev.font_size, nxt.font_size, 1.0)
    gap = nxt.bbox[1] - prev.bbox[3]
    if sentence_final_text(prev.text) and gap > reference * 0.5:
        return False
    if gap > reference * PARAGRAPH_GAP_FACTOR:
        return False
    if gap < -reference and not _looks_like_overlapping_formula_tail_continuation(
        prev, nxt, gap, reference
    ):
        return False
    if _looks_like_float_wrap_boundary(prev, nxt):
        if not float_wrap_merge:
            return False
        # The narrow fragment is explained by a side float: keep the wrapped
        # paragraph as one unit. Downstream the float clip / keepout slots
        # re-wrap the translation around the float, so the merged envelope
        # crossing the graphic region is intended here.
        overlap = min(prev.bbox[2], nxt.bbox[2]) - max(prev.bbox[0], nxt.bbox[0])
        narrower = min(prev.bbox[2] - prev.bbox[0], nxt.bbox[2] - nxt.bbox[0])
        return narrower > 0 and overlap / narrower >= PARAGRAPH_MIN_X_OVERLAP
    overlap = min(prev.bbox[2], nxt.bbox[2]) - max(prev.bbox[0], nxt.bbox[0])
    narrower = min(prev.bbox[2] - prev.bbox[0], nxt.bbox[2] - nxt.bbox[0])
    if narrower <= 0 or overlap / narrower < PARAGRAPH_MIN_X_OVERLAP:
        return False
    if graphic_regions and bbox_crosses_graphic_region(
        union_bbox([prev.bbox, nxt.bbox]),
        graphic_regions,
    ):
        return False
    return True


_ACADEMIC_FORMULA_STATEMENT_RE = re.compile(
    r"^(?:Definition|Proposition|Theorem|Lemma|Corollary|Remark)\s+\d",
    re.IGNORECASE,
)


def _looks_like_academic_formula_statement_pair(
    prev: TextBlock,
    nxt: TextBlock,
) -> bool:
    """Join a boxed theorem split around a tall display-style fraction."""
    if prev.page_index != nxt.page_index or sentence_final_text(prev.text):
        return False
    previous = " ".join(strip_sentinels(prev.text).split())
    following = " ".join(strip_sentinels(nxt.text).split())
    if not _ACADEMIC_FORMULA_STATEMENT_RE.match(previous):
        return False
    hyphenated_continuation = previous.endswith("-")
    if not re.match(r"^[a-z]", following) or (
        len(_prose_words(following)) < 4 and not hyphenated_continuation
    ):
        return False
    if not (prev.keepout_bboxes and nxt.keepout_bboxes):
        return False
    if abs(prev.font_size - nxt.font_size) > 1.5:
        return False
    reference = max(prev.font_size, nxt.font_size, 1.0)
    gap = nxt.bbox[1] - prev.bbox[3]
    if gap > reference or gap < -reference * 1.5:
        return False
    overlap = min(prev.bbox[2], nxt.bbox[2]) - max(prev.bbox[0], nxt.bbox[0])
    narrower = min(prev.bbox[2] - prev.bbox[0], nxt.bbox[2] - nxt.bbox[0])
    return narrower > 0 and overlap / narrower >= 0.7


def _looks_like_caption_continuation_pair(prev: TextBlock, nxt: TextBlock) -> bool:
    """Join caption records split by inline formulas at a figure boundary."""
    if prev.page_index != nxt.page_index:
        return False
    if not _CAPTION_RE.match(strip_sentinels(prev.text).lstrip()):
        return False
    if nxt.block_type in {"algorithm", "bibliography", "equation", "figure_label", "table"}:
        return False
    if abs(prev.font_size - nxt.font_size) > 2.0:
        return False
    next_plain = strip_sentinels(nxt.text).lstrip()
    if sentence_final_text(prev.text) and not re.match(r"^\([a-z0-9]+\)\s*", next_plain):
        return False
    reference = max(prev.font_size, nxt.font_size, 1.0)
    gap = nxt.bbox[1] - prev.bbox[3]
    if gap > reference * 1.2 or gap < -reference * 1.5:
        return False
    overlap = min(prev.bbox[2], nxt.bbox[2]) - max(prev.bbox[0], nxt.bbox[0])
    narrower = min(prev.bbox[2] - prev.bbox[0], nxt.bbox[2] - nxt.bbox[0])
    return narrower > 0.0 and overlap / narrower >= 0.5


def _looks_like_inline_heading_pair(prev: TextBlock, nxt: TextBlock) -> bool:
    """Detect a bold run-in label followed by prose on the same source line."""
    if prev.page_index != nxt.page_index:
        return False
    if not prev.bold or prev.source_lines != 1:
        return False
    if nxt.block_type != "body" or nxt.bold:
        return False
    if looks_like_action_skeleton_sequence(strip_sentinels(nxt.text)):
        return False
    if abs(prev.font_size - nxt.font_size) > 2.0:
        return False
    heading = " ".join(strip_sentinels(prev.text).split())
    prose = " ".join(strip_sentinels(nxt.text).split())
    if not heading or len(heading) > 80 or len(_PROSE_WORD_RE.findall(prose)) < 3:
        return False

    if _looks_like_same_line_formula_split(prev, nxt):
        return True

    if nxt.source_line_bboxes:
        first_source_line = nxt.source_line_bboxes[0]
        horizontal_gap = first_source_line[0] - prev.bbox[2]
        vertical_overlap = max(
            0.0,
            min(prev.bbox[3], first_source_line[3])
            - max(prev.bbox[1], first_source_line[1]),
        )
        shorter_height = min(
            prev.bbox[3] - prev.bbox[1],
            first_source_line[3] - first_source_line[1],
        )
        if (
            -3.0 <= horizontal_gap <= max(12.0, nxt.font_size * 1.5)
            and shorter_height > 0.0
            and vertical_overlap / shorter_height >= 0.6
        ):
            return True

    if nxt.source_lines != 1:
        return False

    horizontal_gap = nxt.bbox[0] - prev.bbox[2]
    if not (-3.0 <= horizontal_gap <= max(12.0, nxt.font_size * 1.5)):
        return False
    vertical_overlap = max(
        0.0,
        min(prev.bbox[3], nxt.bbox[3]) - max(prev.bbox[1], nxt.bbox[1]),
    )
    shorter_height = min(prev.bbox[3] - prev.bbox[1], nxt.bbox[3] - nxt.bbox[1])
    return shorter_height > 0.0 and vertical_overlap / shorter_height >= 0.6


def _looks_like_same_line_formula_split(prev: TextBlock, nxt: TextBlock) -> bool:
    """Join prose fragments separated by a standalone inline-math record."""
    if prev.page_index != nxt.page_index:
        return False
    if prev.block_type in {"algorithm", "bibliography", "equation", "figure_label", "table"}:
        return False
    if nxt.block_type in {"algorithm", "bibliography", "equation", "figure_label", "table"}:
        return False
    if abs(prev.font_size - nxt.font_size) > 2.0:
        return False
    if sentence_final_text(prev.text):
        return False
    if not prev.text.rstrip().endswith(SENTINEL_CLOSE):
        return False
    next_text = nxt.text.lstrip()
    formula_offset = next_text.find(SENTINEL_OPEN)
    formula_prefix = next_text[:formula_offset].strip() if formula_offset >= 0 else ""
    starts_formula_tail = next_text.startswith(SENTINEL_OPEN) or bool(
        formula_offset > 0
        and re.fullmatch(
            r"\d+\s+(?:is|are|was|were|be)",
            formula_prefix,
            re.IGNORECASE,
        )
    )
    if not starts_formula_tail:
        return False
    previous_word_count = len(_PROSE_WORD_RE.findall(strip_sentinels(prev.text)))
    next_word_count = len(_PROSE_WORD_RE.findall(strip_sentinels(nxt.text)))
    next_compact = "".join(strip_sentinels(nxt.text).split())
    short_formula_continuation = (
        next_text.startswith(SENTINEL_OPEN)
        and sentinel_char_count(next_text) >= 2
        and len(next_compact) <= 80
        and next_word_count <= 2
    )
    previous_outside_math = " ".join(
        _text_outside_sentinels(prev.text).split()
    ).casefold()
    short_formula_lead = previous_outside_math in {"let", "where", "with"}
    if previous_word_count < 3 and not short_formula_lead:
        return False
    if next_word_count < 2 and not short_formula_continuation:
        return False

    prev_lines = prev.source_line_bboxes or tuple(prev.redact_bboxes or [prev.bbox])
    next_lines = nxt.source_line_bboxes or tuple(nxt.redact_bboxes or [nxt.bbox])
    reference = max(prev.font_size, nxt.font_size, 1.0)
    for prev_line in prev_lines:
        for next_line in next_lines:
            vertical_overlap = max(
                0.0,
                min(prev_line[3], next_line[3]) - max(prev_line[1], next_line[1]),
            )
            min_height = max(
                1.0,
                min(prev_line[3] - prev_line[1], next_line[3] - next_line[1]),
            )
            if vertical_overlap / min_height < 0.5:
                continue
            horizontal_gap = next_line[0] - prev_line[2]
            if -max(12.0, reference * 1.25) <= horizontal_gap <= max(
                16.0, reference * 2.0
            ):
                return True
    return False


def _looks_like_formula_gap_bridge_pair(prev: TextBlock, nxt: TextBlock) -> bool:
    """Join prose fragments separated horizontally by preserved inline math."""
    if prev.page_index != nxt.page_index or sentence_final_text(prev.text):
        return False
    prose_types = {"body", "formula_prose"}
    if prev.block_type not in prose_types or nxt.block_type not in prose_types:
        return False
    if abs(prev.font_size - nxt.font_size) > 2.0:
        return False

    following = strip_sentinels(nxt.text).lstrip()
    if not re.match(r"^[a-z]", following) or len(_PROSE_WORD_RE.findall(following)) < 3:
        return False

    previous_lines = prev.source_line_bboxes[-2:] or (prev.bbox,)
    next_lines = nxt.source_line_bboxes[:2] or (nxt.bbox,)
    formula_bboxes = tuple(
        dict.fromkeys(
            [
                *(prev.keepout_bboxes or []),
                *(nxt.keepout_bboxes or []),
                *prev.source_math_bboxes,
                *nxt.source_math_bboxes,
            ]
        )
    )
    if not formula_bboxes:
        return False

    reference = max(prev.font_size, nxt.font_size, 1.0)
    for previous_line in previous_lines:
        for next_line in next_lines:
            vertical_overlap = min(previous_line[3], next_line[3]) - max(
                previous_line[1], next_line[1]
            )
            min_height = max(
                1.0,
                min(
                    previous_line[3] - previous_line[1],
                    next_line[3] - next_line[1],
                ),
            )
            if vertical_overlap / min_height < 0.55:
                continue
            horizontal_gap = next_line[0] - previous_line[2]
            if not (1.0 <= horizontal_gap <= max(144.0, reference * 14.0)):
                continue
            for formula_bbox in formula_bboxes:
                formula_y_overlap = min(
                    max(previous_line[3], next_line[3]), formula_bbox[3]
                ) - max(min(previous_line[1], next_line[1]), formula_bbox[1])
                if formula_y_overlap <= 0.0:
                    continue
                gap_overlap = min(next_line[0], formula_bbox[2]) - max(
                    previous_line[2], formula_bbox[0]
                )
                if gap_overlap >= min(horizontal_gap * 0.5, reference * 2.0):
                    return True
    return False


def _looks_like_formula_rich_continuation_pair(prev: TextBlock, nxt: TextBlock) -> bool:
    """Join wrapped prose fragments split around inline math source records."""
    if _block_is_short_derivation_explanation(prev) or _block_is_short_derivation_explanation(
        nxt
    ):
        return False
    if prev.bold and prev.source_lines == 1 and not _looks_like_inline_heading_pair(
        prev, nxt
    ):
        # Formula-bearing prose below a standalone heading is not a continuation
        # of that heading. Merging here makes the whole paragraph inherit the
        # heading's font size before semantic classification runs.
        return False
    if prev.page_index != nxt.page_index:
        return False
    prose_types = {"body", "formula_prose"}
    if prev.block_type not in prose_types or nxt.block_type not in prose_types:
        return False
    if not (
        SENTINEL_OPEN in prev.text
        or SENTINEL_OPEN in nxt.text
        or prev.source_math_bboxes
        or nxt.source_math_bboxes
    ):
        return False
    if _is_multiline_formula_only_block(nxt):
        # A multi-line formula row following completed/formula prose is an
        # independent fixed object, not an inline continuation. Absorbing it
        # makes the next paragraph inherit a display-equation hull (Adam p4/5).
        return False
    if abs(prev.font_size - nxt.font_size) > 4.0:
        return False
    reference = max(prev.font_size, nxt.font_size, 1.0)
    gap = nxt.bbox[1] - prev.bbox[3]
    next_plain = strip_sentinels(nxt.text).lstrip()
    starts_formula_tail = nxt.text.lstrip().startswith(SENTINEL_OPEN)
    starts_continuation = bool(re.match(r"^(?:[a-z]|\d+\s+(?:is|since|and)\b)", next_plain))
    previous_plain = strip_sentinels(prev.text).rstrip()
    deep_formula_bridge = (
        starts_formula_tail
        and gap >= -reference * 2.4
        and (
            prev.text.rstrip().endswith(SENTINEL_CLOSE)
            or bool(
                re.search(
                    r"(?:\b(?:with|approximately|as|of|to)|[=≈≤≥])\s*$",
                    previous_plain,
                    re.IGNORECASE,
                )
            )
        )
    )
    if gap > reference * 0.85 or (
        gap < -reference * 1.55 and not deep_formula_bridge
    ):
        return False
    if sentence_final_text(prev.text) and not (starts_formula_tail or starts_continuation):
        return False

    overlap = min(prev.bbox[2], nxt.bbox[2]) - max(prev.bbox[0], nxt.bbox[0])
    narrower = min(prev.bbox[2] - prev.bbox[0], nxt.bbox[2] - nxt.bbox[0])
    overlap_ratio = overlap / max(narrower, 1.0)
    wraps_to_left = (
        nxt.bbox[0] + max(36.0, reference * 3.5) < prev.bbox[0]
        and nxt.bbox[2] <= prev.bbox[0] + max(24.0, reference * 2.5)
    )
    aligned_left = abs(prev.bbox[0] - nxt.bbox[0]) <= max(18.0, reference * 1.8)
    return overlap_ratio >= 0.25 or wraps_to_left or aligned_left


def _looks_like_formula_row_suffix_pair(prev: TextBlock, nxt: TextBlock) -> bool:
    """Join prose suffixes split from a paragraph by a long inline formula."""
    if prev.page_index != nxt.page_index:
        return False
    if prev.block_type not in {"body", "formula_prose"}:
        return False
    if nxt.block_type not in {"body", "formula_prose"}:
        return False
    if not prev.source_math_bboxes or nxt.source_math_bboxes:
        return False
    if not prev.text.rstrip().endswith(SENTINEL_CLOSE):
        return False
    suffix = strip_sentinels(nxt.text).lstrip()
    if not re.match(r"^[.,;:)]\s*[A-Z]", suffix):
        return False
    if len(_PROSE_WORD_RE.findall(suffix)) < 4:
        return False

    reference = max(prev.font_size, nxt.font_size, 1.0)
    previous_lines = prev.source_line_bboxes[-2:] or (prev.bbox,)
    next_lines = nxt.source_line_bboxes[:2] or (nxt.bbox,)
    for previous_line in previous_lines:
        for next_line in next_lines:
            vertical_overlap = min(previous_line[3], next_line[3]) - max(
                previous_line[1], next_line[1]
            )
            min_height = max(
                1.0,
                min(
                    previous_line[3] - previous_line[1],
                    next_line[3] - next_line[1],
                ),
            )
            horizontal_gap = next_line[0] - previous_line[2]
            if (
                vertical_overlap / min_height >= 0.55
                and -reference * 1.5 <= horizontal_gap <= max(120.0, reference * 12.0)
            ):
                return True
    return False


def _looks_like_overlapping_formula_tail_continuation(
    prev: TextBlock, nxt: TextBlock, gap: float, reference: float
) -> bool:
    """Merge prose split by a same-line formula tail with overlapping bboxes."""
    if gap < -reference * 1.35:
        return False
    if sentence_final_text(prev.text):
        return False
    if not nxt.text.lstrip().startswith(SENTINEL_OPEN):
        return False
    bare = strip_sentinels(nxt.text).lstrip()
    if not re.match(r"^(?:[<>=≤≥+\-−]\s*)?\d*(?:\.\d+)?\s*(?:be|is|are)\b", bare):
        return False
    words = _PROSE_WORD_RE.findall(bare)
    return len(words) >= 5


def _float_wrap_region_beside(
    prev: TextBlock,
    graphic_regions: Sequence[BBox],
) -> Optional[BBox]:
    """The graphic region that explains a narrow wrap fragment, if any.

    A paragraph wrapping a side float is extracted as a narrow fragment whose
    right edge hugs the float's left edge for most of its height.
    """
    x0, y0, x1, y1 = prev.bbox
    height = max(1.0, y1 - y0)
    for region in graphic_regions or ():
        rx0 = region[0]
        vertical_overlap = min(y1, region[3]) - max(y0, region[1])
        if vertical_overlap < height * 0.5:
            continue
        # Detected graphic envelopes run generous margins, so the region may
        # overlap the fragment's right edge by a few tens of points; it just
        # must not swallow the fragment's text column itself.
        if x1 - 40.0 <= rx0 <= x1 + 42.0 and rx0 > x0 + 60.0:
            return region
    return None


def _looks_like_float_wrap_boundary(prev: TextBlock, nxt: TextBlock) -> bool:
    """Stop merging when a paragraph leaves a side float and resumes full width."""
    if prev.source_lines < 4:
        return False
    if prev.block_type != "body" or nxt.block_type != "body":
        return False
    if sentence_final_text(prev.text):
        return False
    prev_width = prev.bbox[2] - prev.bbox[0]
    nxt_width = nxt.bbox[2] - nxt.bbox[0]
    if prev_width > 260.0 or nxt_width < 320.0:
        return False
    if abs(prev.bbox[0] - nxt.bbox[0]) > 12.0:
        return False
    right_growth = nxt.bbox[2] - prev.bbox[2]
    return right_growth >= max(120.0, prev_width * 0.55) and nxt_width >= prev_width * 1.45


def can_merge_fixed_width_prose_blocks(
    prev: TextBlock,
    nxt: TextBlock,
    graphic_regions: Sequence[BBox] = (),
) -> bool:
    if prev.no_merge or nxt.no_merge:
        return False
    if prev.page_index != nxt.page_index:
        return False
    if abs(prev.font_size - nxt.font_size) > PARAGRAPH_SIZE_TOLERANCE:
        return False
    if not _looks_like_fixed_width_prose_fragment(prev):
        return False
    if not _looks_like_fixed_width_prose_fragment(nxt):
        return False

    reference = max(prev.font_size, nxt.font_size, 1.0)
    gap = nxt.bbox[1] - prev.bbox[3]
    if gap > reference * 0.85 or gap < -reference * 0.2:
        return False

    prev_width = prev.bbox[2] - prev.bbox[0]
    nxt_width = nxt.bbox[2] - nxt.bbox[0]
    narrower = min(prev_width, nxt_width)
    if narrower < 150.0:
        return False
    overlap = min(prev.bbox[2], nxt.bbox[2]) - max(prev.bbox[0], nxt.bbox[0])
    if overlap <= 0 or overlap / narrower < 0.72:
        return False
    left_delta = abs(prev.bbox[0] - nxt.bbox[0])
    right_delta = abs(prev.bbox[2] - nxt.bbox[2])
    if left_delta > 28.0 and right_delta > 14.0:
        return False
    if graphic_regions and bbox_crosses_graphic_region(
        union_bbox([prev.bbox, nxt.bbox]),
        graphic_regions,
    ):
        return False
    return True


def _looks_like_fixed_width_prose_fragment(block: TextBlock) -> bool:
    if block.block_type != "body":
        return False
    if block.bold or block.starts_bold:
        return False
    if block.nowrap:
        if block.source_lines != 1:
            return False
    elif block.source_lines <= 1:
        return False

    plain = strip_sentinels(block.text).strip()
    if len(plain) < 35:
        return False
    if block.bbox[2] - block.bbox[0] < 150.0:
        return False
    words = _PROSE_WORD_RE.findall(plain)
    if len(words) < 5:
        return False
    if _looks_like_code_or_symbolic_text(plain) or looks_like_math(plain):
        return False
    return True


def sentence_final_text(text: str) -> bool:
    return strip_sentinels(text).rstrip().endswith((".", "?", "!", "。", "？", "！"))


def _merged_paragraph_font_size(
    prev: TextBlock,
    nxt: TextBlock,
    *,
    inline_heading: bool,
) -> float:
    """Choose the prose scale rather than a leading formula fragment's scale.

    TeX may expose a denominator digit or an underbrace label as a one-line
    text block immediately before the real paragraph.  Formula-continuation
    recovery deliberately merges that fragment back into the paragraph, but
    inheriting its 5--7pt annotation size crushes every following CJK line.
    A multi-line continuation is stronger evidence of the paragraph's body
    scale; ordinary same-size merges and run-in headings keep their existing
    behavior.
    """
    if inline_heading:
        return nxt.font_size
    if (
        prev.block_type in {"body", "formula_prose"}
        and nxt.block_type in {"body", "formula_prose"}
        and prev.source_lines == 1
        and nxt.source_lines >= 2
        and prev.font_size < nxt.font_size * 0.85
    ):
        return nxt.font_size
    return prev.font_size


def merge_two_blocks(prev: TextBlock, nxt: TextBlock) -> TextBlock:
    inline_heading = _looks_like_inline_heading_pair(prev, nxt)
    previous_plain = " ".join(strip_sentinels(prev.text).split()).casefold()
    narrow_formula_connector = bool(
        previous_plain in {"and", "or", "where", "with"}
        and prev.source_lines == 1
        and prev.keepout_bboxes
        and prev.bbox[2] - prev.bbox[0] <= max(32.0, prev.font_size * 3.2)
        and nxt.bbox[2] - nxt.bbox[0]
        >= (prev.bbox[2] - prev.bbox[0]) * 8.0
        and nxt.bbox[0] < prev.bbox[0] - max(36.0, prev.font_size * 3.5)
        and 0.0 <= nxt.bbox[1] - prev.bbox[3] <= prev.font_size * 1.1
    )
    redact_bboxes: List[BBox] = []
    redact_bboxes.extend(prev.redact_bboxes or [prev.bbox])
    redact_bboxes.extend(nxt.redact_bboxes or [nxt.bbox])
    keepout_bboxes = [*(prev.keepout_bboxes or []), *(nxt.keepout_bboxes or [])]
    bold_terms = tuple(dict.fromkeys([*prev.bold_terms, *nxt.bold_terms]))
    return TextBlock(
        page_index=prev.page_index,
        # A connector extracted from the middle of a display equation is
        # part of the same translation sentence, but it is not a viable text
        # origin. Starting the merged CJK at that narrow formula-row bbox
        # moves every following inline formula upward over the display math.
        # Keep the connector in the redaction list while typesetting from the
        # full-width prose continuation below it.
        bbox=nxt.bbox if narrow_formula_connector else union_bbox([prev.bbox, nxt.bbox]),
        text=join_lines([prev.text, nxt.text]),
        font_size=_merged_paragraph_font_size(
            prev,
            nxt,
            inline_heading=inline_heading,
        ),
        color=prev.color,
        bold=prev.bold and nxt.bold,
        starts_bold=prev.starts_bold,
        source_lines=(
            max(prev.source_lines, nxt.source_lines)
            if inline_heading and prev.block_type == "run_in_heading"
            else prev.source_lines + nxt.source_lines
        ),
        no_merge=bool(
            (prev.no_merge and not inline_heading)
            or (
                nxt.no_merge
                and nxt.block_type == "formula_prose"
                and nxt.keepout_bboxes
            )
        ),
        redact_bboxes=redact_bboxes,
        keepout_bboxes=keepout_bboxes or None,
        bold_terms=bold_terms,
        bold_prefix=prev.bold_prefix or inline_heading,
        preserved_math_placeholders=tuple(
            range(len(SENTINEL_RUN_RE.findall(join_lines([prev.text, nxt.text]))))
        ),
        source_line_bboxes=tuple(
            dict.fromkeys([*prev.source_line_bboxes, *nxt.source_line_bboxes])
        ),
        source_prose_bboxes=tuple(
            dict.fromkeys([*prev.source_prose_bboxes, *nxt.source_prose_bboxes])
        ),
        source_math_bboxes=tuple(
            [*prev.source_math_bboxes, *nxt.source_math_bboxes]
        ),
        source_math_atom_bboxes=tuple(
            [*prev.source_math_atom_bboxes, *nxt.source_math_atom_bboxes]
        ),
        source_math_atom_groups=tuple(
            [*prev.source_math_atom_groups, *nxt.source_math_atom_groups]
        ),
        keepout_formula_atom_groups=tuple(
            [
                *prev.keepout_formula_atom_groups,
                *nxt.keepout_formula_atom_groups,
            ]
        ),
        redaction_formula_restore_groups=tuple(
            [
                *prev.redaction_formula_restore_groups,
                *nxt.redaction_formula_restore_groups,
            ]
        ),
        formula_anchors=tuple([*prev.formula_anchors, *nxt.formula_anchors]),
        flow_inline_math=prev.flow_inline_math or nxt.flow_inline_math,
    )


def redact_original_text(
    page: object,
    blocks: Sequence[TextBlock],
    margin: float,
    extra_rects: Sequence[BBox] = (),
    *,
    protected_regions: Sequence[BBox] = (),
) -> None:
    try:
        import fitz
    except ImportError as exc:
        raise RuntimeError("PyMuPDF is required. Install with: pip install -e .") from exc

    background = render_background(page)
    # Thin wide horizontal rules (table top/mid/bottom rules). The redaction
    # fill paints background over everything inside its rect; when a rect
    # edge (grown by `margin` or by glyph-box overshoot) grazes a rule, the
    # fill wipes the rule's middle and leaves stub lines beside the
    # translated text. Pull such edges back. Rules deep inside a rect belong
    # to text that genuinely straddles them; those stay and the preserved-
    # region restore handles the damage.
    protected_rules: List[Tuple[float, float, float, float]] = []
    for drawing in _page_drawings(page):
        drawing_rect = drawing.get("rect")
        if (
            drawing_rect is None
            or float(drawing_rect.width) < 40.0
            or float(drawing_rect.height) > 2.5
        ):
            continue
        protected_rules.append(
            (
                float(drawing_rect.y0),
                float(drawing_rect.y1),
                float(drawing_rect.x0),
                float(drawing_rect.x1),
            )
        )

    def _pull_edges_off_rules(rect: "fitz.Rect") -> "fitz.Rect":
        edge_band = margin + 1.4
        for rule_y0, rule_y1, rule_x0, rule_x1 in protected_rules:
            if rect.x1 <= rule_x0 + 1.0 or rect.x0 >= rule_x1 - 1.0:
                continue
            band_top = rule_y0 - 0.9
            band_bottom = rule_y1 + 0.9
            # The rect edge must be compared against the rule's whole band:
            # an edge landing inside the band (grazing the rule's lower or
            # upper half) erases it just as surely as one crossing rule_y0.
            intrusion_limit = edge_band + (rule_y1 - rule_y0)
            if rect.y0 >= band_bottom or rect.y1 <= band_top:
                continue
            top_overlap = band_bottom - rect.y0
            bottom_overlap = rect.y1 - band_top
            if bottom_overlap <= top_overlap and bottom_overlap <= intrusion_limit:
                rect.y1 = max(rect.y0, band_top)
            elif top_overlap < bottom_overlap and top_overlap <= intrusion_limit:
                rect.y0 = min(rect.y1, band_bottom)
        return rect

    def _pull_edges_off_protected(
        rect: "fitz.Rect",
        source_bbox: BBox,
    ) -> "fitz.Rect":
        source_x0, source_y0, source_x1, source_y1 = source_bbox
        edge_band = margin + 1.0
        for region in protected_regions:
            rx0, ry0, rx1, ry1 = region
            if source_x1 <= rx0 + 0.2 or source_x0 >= rx1 - 0.2:
                continue
            # PDF glyph boxes from a figure label can overlap the following
            # caption by a fraction of a point. The caption still intersects
            # a redaction that starts just after the protected glyph, while
            # the label retains both its visible ink and selectable text.
            if (
                ry0 < source_y0
                and source_y0 < ry1 <= source_y0 + edge_band
                and rect.y0 < ry1
            ):
                rect.y0 = min(rect.y1, ry1 + 0.1)
            elif (
                source_y1 - edge_band <= ry0 < source_y1
                and ry1 > source_y1
                and rect.y1 > ry0
            ):
                rect.y1 = max(rect.y0, ry0 - 0.1)
        return rect

    for block in blocks:
        preserve_source_math = _uses_fixed_source_math(block)
        source_math_redacts = (
            block.source_math_atom_bboxes or block.source_math_bboxes
        )
        fixed_math_carveouts = tuple(
            union_bbox(group)
            for group in block.source_math_atom_groups
            if group
        ) or tuple(source_math_redacts)
        restored_keepouts = tuple(
            union_bbox(group)
            for group in block.redaction_formula_restore_groups
            if group
        )
        for bbox in block.redact_bboxes or [block.bbox]:
            if preserve_source_math and _bbox_is_source_math_redact(
                bbox,
                source_math_redacts,
            ):
                continue
            redact_pieces = (
                _split_mixed_redact_around_fixed_math(
                    bbox,
                    fixed_math_carveouts,
                    margin,
                )
                if preserve_source_math
                else [bbox]
            )
            for redact_piece in redact_pieces:
                x0, y0, x1, y1 = redact_piece
                for keepout in block.keepout_bboxes or []:
                    keepout_area = max(bbox_area(keepout), 0.1)
                    if any(
                        bbox_intersection_area(keepout, restored) / keepout_area
                        >= 0.9
                        for restored in restored_keepouts
                    ):
                        continue
                    if not bbox_share_y_band((x0, y0, x1, y1), keepout):
                        continue
                    kx0, _, kx1, _ = keepout
                    if x1 <= kx0 + 0.6 and kx0 - x1 <= 4.0:
                        x1 = min(x1, kx0 - margin - 0.2)
                    elif x0 >= kx1 - 0.6 and x0 - kx1 <= 4.0:
                        x0 = max(x0, kx1 + margin + 0.2)
                safe_bbox = (
                    (x0, y0, x1, y1)
                    if x1 > x0 and y1 > y0
                    else redact_piece
                )
                rect = _pull_edges_off_protected(
                    _pull_edges_off_rules(expand_rect(fitz.Rect(safe_bbox), margin)),
                    safe_bbox,
                )
                fill = sample_background_color(background, safe_bbox, margin)
                page.add_redact_annot(rect, fill=fill)
    for bbox in extra_rects:
        rect = _pull_edges_off_protected(
            _pull_edges_off_rules(expand_rect(fitz.Rect(bbox), margin)),
            bbox,
        )
        fill = sample_background_color(background, bbox, margin)
        page.add_redact_annot(rect, fill=fill)

    kwargs = {}
    if hasattr(fitz, "PDF_REDACT_IMAGE_NONE"):
        kwargs["images"] = fitz.PDF_REDACT_IMAGE_NONE
    if hasattr(fitz, "PDF_REDACT_LINE_ART_NONE"):
        kwargs["graphics"] = fitz.PDF_REDACT_LINE_ART_NONE
    try:
        page.apply_redactions(**kwargs)
    except TypeError:
        page.apply_redactions()


def _restore_redaction_damaged_preserved_regions(
    page: object,
    source_document: object,
    page_index: int,
    preserved_regions: Sequence[BBox],
    translated_blocks: Sequence[TextBlock],
    margin: float,
) -> int:
    """Restore protected source clips deleted as a side effect of redaction.

    MuPDF can rewrite a nested Form XObject when a nearby caption is redacted.
    On some conference figures that removes unrelated vector labels elsewhere
    in the same Form. Repainting only the affected protected atoms as raster
    clips preserves their visible ink without importing page-wide text operators.
    """
    if not preserved_regions:
        return 0
    import fitz

    source_page = source_document[page_index]
    source_entries = _text_entries_from_blocks(
        source_page.get_text("dict").get("blocks", [])
    )
    translated_entries = _text_entries_from_blocks(
        page.get_text("dict").get("blocks", [])
    )
    redaction_regions = [
        expand_bbox(bbox, margin)
        for block in translated_blocks
        for bbox in (block.redact_bboxes or [block.bbox])
    ]
    restored = 0
    for region in _preserved_text_qa_regions(preserved_regions):
        region_area = max(1.0, bbox_area(region))
        if any(
            bbox_intersection_area(region, redaction) / region_area >= 0.02
            for redaction in redaction_regions
        ):
            continue
        source_text = _text_overlapping_region(source_entries, region)
        if not source_text:
            continue
        current_text = _text_overlapping_region(translated_entries, region)
        if not preserved_region_text_changed(source_text, current_text):
            continue
        clip = fitz.Rect(region)
        _insert_source_region_raster(
            page,
            source_document,
            page_index,
            clip,
            clip,
        )
        restored += 1
    return restored


def _expanded_radical_restore_atoms(
    source_page: object,
    atom_bboxes: Sequence[BBox],
) -> Tuple[BBox, ...]:
    """Expand restore masks for CMEX operators whose ink exceeds their row.

    TeX's CMEX root glyph is extracted as ``p`` with only its advance-width
    bbox even though the painted overbar extends across the radicand. When a
    nearby prose redaction removes that text object, repainting the reported
    atom alone restores the hook but clips the bar. Extend only to contiguous
    right-hand spans on the radicand row; the normalized root bottom keeps a
    stale font descent from reopening the following prose line.

    Large summation/product glyphs are encoded as ``X``/``P`` and have a
    legitimate lower half inside the raw font bbox.  Their layout bbox is
    clamped to one row, but a redaction repair must repaint the raw glyph or
    the operator loses its bottom stroke.
    """
    atoms = tuple(atom_bboxes)
    if not atoms:
        return atoms
    page_spans = [
        span
        for block in source_page.get_text("dict").get("blocks", [])
        if block.get("type") == 0
        for line in block.get("lines", [])
        for span in line.get("spans", [])
        if len(span.get("bbox", ())) == 4
    ]
    expanded_atoms = list(atoms)
    expanded_large_operator = False
    for span in page_spans:
        if (
            "CMEX" not in str(span.get("font", "")).upper()
            or str(span.get("text", "")).strip() not in {"P", "X"}
        ):
            continue
        normalized_span = _normalized_extracted_math_span(span)
        normalized_bbox = tuple(
            float(value) for value in normalized_span.get("bbox", ())
        )
        raw_bbox = tuple(
            float(value)
            for value in normalized_span.get(
                "_raw_bbox",
                span.get("bbox", ()),
            )
        )
        if len(normalized_bbox) != 4 or len(raw_bbox) != 4 or raw_bbox == normalized_bbox:
            continue
        normalized_area = max(0.1, bbox_area(normalized_bbox))
        for atom_index, atom in enumerate(expanded_atoms):
            if (
                bbox_intersection_area(atom, normalized_bbox) / normalized_area
                < 0.8
            ):
                continue
            expanded_atoms[atom_index] = raw_bbox
            expanded_large_operator = True
            break
    if expanded_large_operator:
        return tuple(expanded_atoms)

    radical_span: Optional[dict] = None
    radical_bbox: Optional[BBox] = None
    for span in page_spans:
        if (
            "CMEX" not in str(span.get("font", "")).upper()
            or str(span.get("text", "")).strip() != "p"
        ):
            continue
        normalized = _normalized_extracted_math_span(span)
        bbox = tuple(float(value) for value in normalized["bbox"])
        area = max(0.1, bbox_area(bbox))
        if any(
            bbox_intersection_area(bbox, atom) / area >= 0.8
            for atom in atoms
        ):
            radical_span = span
            radical_bbox = bbox
            break
    if radical_span is None or radical_bbox is None:
        return atoms

    raw_bbox = tuple(float(value) for value in radical_span["bbox"])
    origin = radical_span.get("origin")
    origin_y = (
        float(origin[1])
        if origin is not None and len(origin) >= 2
        else (radical_bbox[1] + radical_bbox[3]) / 2.0
    )
    size = max(1.0, float(radical_span.get("size", 0.0)))
    radicand_center_limit = min(raw_bbox[3], origin_y + size * 1.25)
    cursor = raw_bbox[2]
    radicand_atoms: List[BBox] = []
    candidates = sorted(
        page_spans,
        key=lambda span: (
            float(span["bbox"][0]),
            float(span["bbox"][1]),
        ),
    )
    for span in candidates:
        if span is radical_span or not str(span.get("text", "")).strip():
            continue
        bbox = tuple(
            float(value)
            for value in _normalized_extracted_math_span(span)["bbox"]
        )
        if bbox[0] < raw_bbox[2] - 0.2:
            continue
        center_y = (bbox[1] + bbox[3]) / 2.0
        if (
            center_y < origin_y - size * 0.15
            or center_y > radicand_center_limit
            or min(raw_bbox[3], bbox[3]) - max(raw_bbox[1], bbox[1]) <= 0.0
        ):
            continue
        if bbox[0] - cursor > max(2.5, size * 0.35):
            if radicand_atoms:
                break
            continue
        radicand_atoms.append(bbox)
        cursor = max(cursor, bbox[2])
    if not radicand_atoms:
        return atoms
    return (union_bbox([radical_bbox, *radicand_atoms]),)


def _restore_redacted_formula_atoms(
    page: object,
    source_document: object,
    page_index: int,
    blocks: Sequence[TextBlock],
    *,
    margin: float = 0.8,
    font_pack: Optional[FontPack] = None,
) -> int:
    """Repaint formula atoms crossed by prose redaction with one semantic copy."""
    exclusions_by_group: Dict[Tuple[BBox, ...], List[BBox]] = {}
    redactions_by_group: Dict[Tuple[BBox, ...], List[BBox]] = {}
    for block in blocks:
        for group in block.redaction_formula_restore_groups:
            if not group:
                continue
            group_bbox = union_bbox(group)
            group_area = max(bbox_area(group_bbox), 0.1)
            owned_atoms = {
                atom
                for atom_group in block.source_math_atom_groups
                for atom in atom_group
            }
            every_atom_owned = all(atom in owned_atoms for atom in group)
            inline_formula_owns_group = bool(
                block.flow_inline_math
                and len(SENTINEL_RUN_RE.findall(block.text))
                == len(block.formula_anchors)
                and (
                    every_atom_owned
                    or any(
                        bbox_intersection_area(group_bbox, owned)
                        / max(bbox_area(group_bbox), 0.1)
                        >= 0.9
                        for owned in block.source_math_bboxes
                    )
                )
            )
            if inline_formula_owns_group:
                continue
            exclusions_by_group.setdefault(group, []).extend(
                block.source_prose_bboxes
            )
            delete_boundaries = [
                keepout
                for keepout in block.keepout_bboxes or ()
                if bbox_intersection_area(group_bbox, keepout) / group_area
                >= 0.9
            ]
            damage_bbox = (
                union_bbox([group_bbox, *delete_boundaries])
                if delete_boundaries
                else group_bbox
            )
            redactions = [
                expand_bbox(redact, margin)
                for redact in (block.redact_bboxes or [block.bbox])
                if bboxes_intersect(expand_bbox(redact, margin), damage_bbox)
            ]
            if not redactions:
                continue
            redactions_by_group.setdefault(group, []).extend(redactions)
    restored = 0
    for group, redactions in redactions_by_group.items():
        exclusions = exclusions_by_group.get(group, [])
        paint_atoms = _expanded_radical_restore_atoms(
            source_document[page_index],
            group,
        )
        source_rect = expand_bbox(union_bbox(paint_atoms), 0.5)
        _insert_source_formula_raster(
            page,
            source_document,
            page_index,
            source_rect,
            paint_atoms,
            source_rect,
            exclude_bboxes=tuple(dict.fromkeys(exclusions)),
        )
        if font_pack is not None:
            _insert_redacted_formula_semantic_spans(
                page,
                source_document[page_index],
                group,
                tuple(dict.fromkeys(redactions)),
                font_pack,
            )
        restored += 1
    return restored


def _insert_redacted_formula_semantic_spans(
    page: object,
    source_page: object,
    atom_bboxes: Sequence[BBox],
    redaction_bboxes: Sequence[BBox],
    font_pack: FontPack,
) -> int:
    """Restore selectable text only for source formula spans redaction removed."""
    candidates: List[dict] = []
    group_spans: List[dict] = []
    seen: set[Tuple[BBox, str]] = set()
    for block in source_page.get_text("dict").get("blocks", []):
        if block.get("type") != 0:
            continue
        for line in block.get("lines", []):
            for span in line.get("spans", []):
                text = str(span.get("text", ""))
                bbox_values = span.get("bbox", ())
                if not text.strip() or len(bbox_values) != 4:
                    continue
                bbox = tuple(float(value) for value in bbox_values)
                area = max(0.1, bbox_area(bbox))
                if not any(
                    bbox_intersection_area(bbox, atom) / area >= 0.5
                    for atom in atom_bboxes
                ):
                    continue
                group_spans.append(span)
                if not any(
                    bbox_intersection_area(bbox, redact) / area >= 0.15
                    for redact in redaction_bboxes
                ):
                    continue
                key = (bbox, text)
                if key in seen:
                    continue
                seen.add(key)
                candidates.append(span)

    fonts = font_pack.fonts_for(False)
    row_sizes = [
        float(span.get("size", 0.0))
        for span in group_spans
        if float(span.get("size", 0.0)) > 0.0
    ]
    row_baselines = [
        float(span["origin"][1])
        for span in group_spans
        if span.get("origin") is not None and len(span["origin"]) >= 2
    ]
    inserted = 0
    for span in candidates:
        text = _normalize_formula_accessibility_text(str(span.get("text", "")))
        if (
            "CMEX" in str(span.get("font", "")).upper()
            and text.strip() == "P"
        ):
            text = "∑"
        if not text:
            continue
        bbox = tuple(float(value) for value in span["bbox"])
        source_size = max(1.0, float(span.get("size", 0.0)) or bbox[3] - bbox[1])
        semantic_size = max(
            source_size * 0.7,
            min([source_size, *row_sizes]),
        )
        natural_width = sum(char_width(char, fonts, semantic_size) for char in text)
        available_width = max(0.5, bbox[2] - bbox[0])
        hidden_size = min(
            semantic_size,
            semantic_size * available_width / max(natural_width, 0.5),
        )
        origin = span.get("origin")
        baseline = (
            max(row_baselines)
            if row_baselines
            else float(origin[1])
            if origin is not None and len(origin) >= 2
            else bbox[3] - hidden_size * 0.2
        )
        x = bbox[0]
        for char in text:
            alias = pick_font_alias(char, fonts)
            page.insert_text(
                (x, baseline),
                char,
                fontname=alias,
                fontsize=hidden_size,
                render_mode=3,
            )
            x += char_width(char, fonts, hidden_size)
        inserted += 1
    return inserted


# --- Centered-block detection -------------------------------------------------


def detect_centered_blocks(blocks: Sequence[TextBlock], page_width: float) -> List[bool]:
    """Title / author / heading blocks that were centred in the source stay
    centred. Body paragraphs (full column width or many lines) never match;
    flush-left blocks (bibliography entries, paragraph tails) are excluded by
    the column-left indent requirement."""
    if not blocks:
        return []
    widths = [block.bbox[2] - block.bbox[0] for block in blocks]
    reference = max(widths)
    if reference < page_width * 0.5:
        reference = page_width * 0.78
    # Column left edge: median x0 of body-like blocks (footers/page numbers
    # sit outside the column and would skew a plain minimum).
    body_lefts = [
        block.bbox[0] for block in blocks if block.source_lines >= 2 or len(block.text) > 60
    ]
    column_left = (
        statistics.median(body_lefts) if body_lefts else min(block.bbox[0] for block in blocks)
    )
    tolerance = max(6.0, page_width * 0.012)
    flags: List[bool] = []
    for block, width in zip(blocks, widths):
        if block.nowrap:
            flags.append(False)
            continue
        if block.block_type == "title":
            line_boxes = block.source_line_bboxes or (block.bbox,)
            flags.append(
                all(
                    abs((bbox[0] + bbox[2]) / 2.0 - page_width / 2.0)
                    <= max(tolerance, page_width * 0.025)
                    for bbox in line_boxes
                )
            )
            continue
        center = (block.bbox[0] + block.bbox[2]) / 2.0
        delta = abs(center - page_width / 2.0)
        narrow = width <= reference * 0.86
        short = block.source_lines <= 2 or len(block.text) <= 80
        indented = block.bbox[0] >= column_left + 18.0
        flags.append(delta <= tolerance and narrow and short and indented)
    return flags


def caption_should_center(block: TextBlock, page_width: float) -> bool:
    if block.block_type != "caption" or block.nowrap or block.source_lines > 2:
        return False
    x0, _, x1, _ = block.bbox
    width = x1 - x0
    if width < page_width * 0.25 or width > page_width * 0.90:
        return False
    center = (x0 + x1) / 2.0
    return abs(center - page_width / 2.0) <= max(12.0, page_width * 0.02)


def center_caption_bbox(block: TextBlock, page_width: float) -> TextBlock:
    if block.block_type != "caption":
        return block
    x0, y0, x1, y1 = block.bbox
    width = x1 - x0
    if width <= 0:
        return block
    new_x0 = max(0.0, min(page_width - width, page_width / 2.0 - width / 2.0))
    redacts = block.redact_bboxes or [block.bbox]
    return replace(block, bbox=(new_x0, y0, new_x0 + width, y1), redact_bboxes=redacts)


def requested_translation_font_size(
    block: TextBlock,
    min_font_size: float,
    font_scale: float,
) -> float:
    base_size = max(min_font_size, block.font_size * font_scale)
    plain = " ".join(strip_sentinels(block.text).split()).strip()
    source_weight_lettered_heading = bool(
        block.block_type == "heading"
        and not block.bold
        and (
            _APPENDIX_STYLE_HEADING_LINE_RE.match(plain)
            or _ROMAN_HEADING_LINE_RE.match(plain)
        )
    )
    if block.block_type == "heading" and not source_weight_lettered_heading:
        return max(base_size, block.font_size * 1.12)
    return base_size


def expand_heading_bbox(block: TextBlock) -> TextBlock:
    if block.block_type not in {"title", "heading", "run_in_heading"}:
        return block
    x0, y0, x1, y1 = block.bbox
    if block.block_type == "title":
        pad_y = max(1.5, block.font_size * 0.18)
        redacts = block.redact_bboxes or [block.bbox]
        return replace(
            block,
            bbox=(x0, max(0.0, y0 - pad_y), x1, y1 + pad_y),
            redact_bboxes=redacts,
        )
    pad_y = (
        max(0.5, block.font_size * 0.06)
        if block.block_type == "run_in_heading"
        else max(1.0, block.font_size * 0.18)
    )
    pad_x = max(2.0, block.font_size * 0.35)
    redacts = block.redact_bboxes or [block.bbox]
    return replace(
        block,
        bbox=(x0, y0 - pad_y, x1 + pad_x, y1 + pad_y),
        redact_bboxes=redacts,
    )


def _expand_header_bbox_upward(block: TextBlock) -> TextBlock:
    """Give a translated running header CJK ascent room above its rule."""
    if block.block_type != "header":
        return block
    x0, y0, x1, y1 = block.bbox
    redacts = block.redact_bboxes or [block.bbox]
    return replace(
        block,
        bbox=(x0, max(0.0, y0 - max(2.5, block.font_size * 0.32)), x1, y1),
        redact_bboxes=list(redacts),
    )


def _expand_standalone_heading_to_column(
    block: TextBlock,
    page_columns: Sequence[Tuple[float, float]],
    page_width: float,
    page_blocks: Sequence[TextBlock] = (),
) -> TextBlock:
    """Give a standalone translated heading the width of its source column."""
    if (
        block.block_type != "heading"
        or block.nowrap
        or not page_columns
    ):
        return block
    x0, y0, x1, y1 = block.bbox
    containing = [
        column
        for column in page_columns
        if column[0] - 4.0 <= x0 <= column[0] + column[1] + 4.0
    ]
    if not containing:
        return block
    column_left, column_width = min(
        containing,
        key=lambda column: abs(x0 - column[0]),
    )
    column_right = min(float(page_width), column_left + column_width)
    nearby_wide_bodies = [
        candidate
        for candidate in page_blocks
        if candidate is not block
        and candidate.block_type in {"body", "formula_prose"}
        and abs(candidate.bbox[0] - x0) <= 4.0
        and 0.0 <= candidate.bbox[1] - y1 <= 36.0
        and candidate.bbox[2] >= x1 + max(24.0, (x1 - x0) * 0.35)
    ]
    if nearby_wide_bodies:
        column_right = max(
            column_right,
            min(float(page_width), max(candidate.bbox[2] for candidate in nearby_wide_bodies)),
        )
    elif block.preserve_position:
        # A source-anchored heading may sit over a figure, so do not widen it
        # from column inference alone. A nearby full-width body block is the
        # positive ownership signal that the extra horizontal room belongs to
        # this heading rather than to adjacent visual content.
        return block
    if column_right <= x1 + 1.0:
        return block
    redacts = block.redact_bboxes or [block.bbox]
    return replace(
        block,
        bbox=(x0, y0, column_right, y1),
        redact_bboxes=list(redacts),
        fixed_translation_font_size=(
            block.fixed_translation_font_size or block.font_size
        ),
    )


def _combine_inline_style_translation_items(
    items: Sequence[Tuple[TextBlock, str]],
) -> List[Tuple[TextBlock, str]]:
    """Flow a source run-in heading and its same-baseline body as one block."""

    def same_row_with_optional_math_bridge(
        heading: TextBlock,
        body: TextBlock,
        heading_line: BBox,
        body_line: BBox,
    ) -> bool:
        vertical_overlap = min(body_line[3], heading_line[3]) - max(
            body_line[1], heading_line[1]
        )
        if vertical_overlap < min(
            body_line[3] - body_line[1],
            heading_line[3] - heading_line[1],
        ) * 0.65:
            return False
        if -1.0 <= body_line[0] - heading_line[2] <= 4.0:
            return True
        for keepout in dict.fromkeys(
            [*(heading.keepout_bboxes or []), *(body.keepout_bboxes or [])]
        ):
            keepout_height = max(1.0, keepout[3] - keepout[1])
            heading_overlap = min(heading_line[3], keepout[3]) - max(
                heading_line[1], keepout[1]
            )
            body_overlap = min(body_line[3], keepout[3]) - max(
                body_line[1], keepout[1]
            )
            if (
                -1.0 <= keepout[0] - heading_line[2] <= 4.0
                and -1.0 <= body_line[0] - keepout[2] <= 4.0
                and heading_overlap >= min(heading_line[3] - heading_line[1], keepout_height) * 0.5
                and body_overlap >= min(body_line[3] - body_line[1], keepout_height) * 0.5
            ):
                return True
        return False

    combined_items: List[Tuple[TextBlock, str]] = []
    index = 0
    while index < len(items):
        heading, heading_translation = items[index]
        if index + 1 >= len(items):
            combined_items.append((heading, heading_translation))
            break
        body, body_translation = items[index + 1]
        heading_line = (
            heading.source_line_bboxes[0]
            if heading.source_line_bboxes
            else heading.bbox
        )
        matching_body_line = next(
            (
                line_bbox
                for line_bbox in body.source_line_bboxes
                if same_row_with_optional_math_bridge(
                    heading,
                    body,
                    heading_line,
                    line_bbox,
                )
            ),
            None,
        )
        if (
            heading.block_type != "run_in_heading"
            or not heading.bold
            or body.block_type not in {"body", "formula_prose"}
            or matching_body_line is None
        ):
            combined_items.append((heading, heading_translation))
            index += 1
            continue

        prefix = heading_translation.rstrip()
        suffix = body_translation.lstrip()
        translated = f"{prefix} {suffix}" if suffix else prefix
        source_text = f"{heading.text.rstrip()} {body.text.lstrip()}"
        source_lines = tuple(
            dict.fromkeys([*heading.source_line_bboxes, *body.source_line_bboxes])
        )
        heading_baseline = heading_line[3] - heading.font_size * 0.18
        body_baseline = matching_body_line[3] - body.font_size * 0.18
        merged = TextBlock(
            page_index=body.page_index,
            bbox=union_bbox([heading.bbox, body.bbox]),
            text=source_text,
            font_size=body.font_size,
            color=body.color,
            bold=False,
            starts_bold=True,
            source_lines=max(1, len(source_lines)),
            nowrap=False,
            no_merge=True,
            redact_bboxes=list(
                dict.fromkeys(
                    [
                        *(heading.redact_bboxes or [heading.bbox]),
                        *(body.redact_bboxes or [body.bbox]),
                    ]
                )
            ),
            keepout_bboxes=list(
                dict.fromkeys(
                    [
                        *(heading.keepout_bboxes or []),
                        *(body.keepout_bboxes or []),
                    ]
                )
            )
            or None,
            block_type=body.block_type,
            should_translate=True,
            preserve_position=False,
            bold_terms=tuple(dict.fromkeys([*heading.bold_terms, *body.bold_terms])),
            bold_prefix=True,
            source_style_runs=(
                SourceStyleRun(
                    role="heading_prefix",
                    bbox=heading.bbox,
                    baseline=heading_baseline,
                    font_size=heading.font_size,
                    bold=True,
                ),
                SourceStyleRun(
                    role="body",
                    bbox=body.bbox,
                    baseline=body_baseline,
                    font_size=body.font_size,
                    bold=False,
                ),
            ),
            translated_bold_prefix_chars=len(prefix),
            flow_inline_math=True,
            preserved_math_placeholders=tuple(
                range(len(SENTINEL_RUN_RE.findall(source_text)))
            ),
            source_line_bboxes=source_lines,
            source_prose_bboxes=tuple(
                dict.fromkeys(
                    [*heading.source_prose_bboxes, *body.source_prose_bboxes]
                )
            ),
            source_math_bboxes=tuple(
                [*heading.source_math_bboxes, *body.source_math_bboxes]
            ),
            source_math_atom_bboxes=tuple(
                [
                    *heading.source_math_atom_bboxes,
                    *body.source_math_atom_bboxes,
                ]
            ),
            source_math_atom_groups=tuple(
                [
                    *heading.source_math_atom_groups,
                    *body.source_math_atom_groups,
                ]
            ),
            keepout_formula_atom_groups=tuple(
                [
                    *heading.keepout_formula_atom_groups,
                    *body.keepout_formula_atom_groups,
                ]
            ),
            redaction_formula_restore_groups=tuple(
                [
                    *heading.redaction_formula_restore_groups,
                    *body.redaction_formula_restore_groups,
                ]
            ),
            formula_anchors=tuple(
                [*heading.formula_anchors, *body.formula_anchors]
            ),
        )
        combined_items.append((merged, translated))
        index += 2
    return combined_items


_FORMULA_CONTINUATION_CONNECTORS = frozenset(
    {"and", "or", "where", "with", "thus", "thus,"}
)


def _combine_academic_formula_statement_translation_items(
    items: Sequence[Tuple[TextBlock, str]],
) -> List[Tuple[TextBlock, str]]:
    """Join side-by-side theorem fragments into one fixed-formula flow.

    TeX frequently emits ``Lemma ... Let <fraction>. For <condition> ...`` as
    several neighboring text objects. They do not overlap horizontally, so
    the generic continuation merger correctly leaves ordinary paragraphs
    alone but also leaves each theorem fragment fighting for its own CJK box.
    The academic lead is a strong semantic anchor: absorb only compact
    formula-prose fragments in the same two-line band and keep every source
    formula anchor fixed inside the resulting statement.
    """
    combined: List[Tuple[TextBlock, str]] = []
    index = 0
    while index < len(items):
        block, translated = items[index]
        plain = " ".join(strip_sentinels(block.text).split()).strip()
        if not (
            _ACADEMIC_FORMULA_STATEMENT_RE.match(plain)
            and block.formula_anchors
        ):
            combined.append((block, translated))
            index += 1
            continue

        statement = block
        statement_translation = translated
        cursor = index + 1
        max_bottom = block.bbox[3] + max(16.0, block.font_size * 1.7)
        while cursor < len(items) and cursor <= index + 4:
            following, following_translation = items[cursor]
            following_plain = " ".join(
                strip_sentinels(following.text).split()
            ).strip()
            if (
                following.page_index != block.page_index
                or following.block_type != "formula_prose"
                or following.source_lines != 1
                or following.bbox[1] > max_bottom
                or re.match(
                    r"^(?:Proof|Theorem|Lemma|Proposition|Corollary)\b",
                    following_plain,
                    re.I,
                )
            ):
                break
            statement = merge_two_blocks(statement, following)
            statement_translation = join_lines(
                [statement_translation, following_translation]
            )
            cursor += 1

        combined.append(
            (
                replace(
                    statement,
                    block_type=block.block_type,
                    no_merge=True,
                    preserve_position=False,
                    nowrap=False,
                    bold_prefix=block.bold_prefix,
                    flow_inline_math=False,
                ),
                statement_translation,
            )
        )
        index = cursor
    return combined


def _combine_formula_continuation_translation_items(
    items: Sequence[Tuple[TextBlock, str]],
) -> List[Tuple[TextBlock, str]]:
    """Join formula-bearing prose fragments before typesetting.

    TeX commonly emits one semantic paragraph as several text objects whose
    bbox hulls overlap because a fraction or summation spans multiple rows.
    Rendering each object independently guarantees overprint even when every
    object's internal line layout is valid. Join only geometrically adjacent,
    sentence-open continuations; completed statements and structural headings
    remain separate.
    """

    def compact_connector(block: TextBlock) -> bool:
        plain = " ".join(strip_sentinels(block.text).split()).strip().casefold()
        return bool(
            plain in _FORMULA_CONTINUATION_CONNECTORS
            and block.bbox[2] - block.bbox[0]
            <= max(34.0, block.font_size * 4.0)
        )

    def can_append(previous: TextBlock, following: TextBlock) -> bool:
        following_plain = " ".join(strip_sentinels(following.text).split()).strip()
        vertical_overlap = min(previous.bbox[3], following.bbox[3]) - max(
            previous.bbox[1], following.bbox[1]
        )
        shorter_height = max(
            1.0,
            min(
                previous.bbox[3] - previous.bbox[1],
                following.bbox[3] - following.bbox[1],
            ),
        )
        overlapping_inline_math_followup = bool(
            not previous.flow_inline_math
            and following.flow_inline_math
            and previous.formula_anchors
            and following.formula_anchors
            and previous.source_lines >= 2
            and following.source_lines >= 2
            and vertical_overlap >= shorter_height * 0.55
            and abs(previous.bbox[0] - following.bbox[0])
            <= max(4.0, min(previous.font_size, following.font_size) * 0.5)
            and re.match(r"^[a-z]", following_plain)
        )
        embedded_following_connector = bool(
            compact_connector(following)
            and following.bbox[2]
            <= previous.bbox[2] - max(10.0, following.font_size)
        )
        keepout_continuation = bool(
            following.block_type == "formula_prose"
            and following.preserve_position
            and following.keepout_bboxes
            and re.match(r"^[,.;:]", following_plain)
        )
        fixed_prefix_continuation = bool(
            previous.block_type == "formula_prose"
            and previous.preserve_position
            and previous.source_lines >= 2
            and previous.keepout_bboxes
            and following.block_type == "body"
            and any(
                keepout[2]
                <= previous.bbox[0] + max(60.0, previous.font_size * 6.0)
                for keepout in previous.keepout_bboxes
            )
        )
        previous_width = max(1.0, previous.bbox[2] - previous.bbox[0])
        bridge_regions = [
            *previous.formula_anchors,
            *(previous.keepout_bboxes or []),
            *(following.keepout_bboxes or []),
        ]
        bridge_right = max(
            (region[2] for region in bridge_regions),
            default=previous.bbox[2],
        )
        detached_formula_suffix = bool(
            previous.formula_anchors
            and following.block_type == "formula_prose"
            and following.source_lines == 1
            and not following.formula_anchors
            and following.keepout_bboxes
            and following.bbox[0] >= previous.bbox[0] + previous_width * 0.6
            and following.bbox[0] - bridge_right
            <= max(5.0, following.font_size * 2.0)
            and min(previous.bbox[3], following.bbox[3])
            - max(previous.bbox[1], following.bbox[1])
            > 0.0
            and re.match(r"^[a-z]", following_plain)
            and len(_PROSE_WORD_RE.findall(following_plain)) <= 4
            and not compact_connector(following)
        )
        if (
            previous.page_index != following.page_index
            or previous.block_type not in {"body", "formula_prose"}
            or following.block_type not in {"body", "formula_prose"}
            or previous.nowrap
            or (
                following.nowrap
                and not embedded_following_connector
                and not detached_formula_suffix
            )
            # A leading bold label starts a new semantic field (for example,
            # ``Task:`` after ``Filename:``). A formula in that field must
            # not pull the preceding field into one style range.
            or following.bold_prefix
            or (
                (previous.flow_inline_math or following.flow_inline_math)
                and not overlapping_inline_math_followup
            )
            or (
                previous.preserve_position
                and previous.block_type != "formula_prose"
                and not compact_connector(previous)
            )
            or (
                following.preserve_position
                and following.block_type != "formula_prose"
                and not compact_connector(following)
            )
            or not (
                previous.formula_anchors
                or following.formula_anchors
                or keepout_continuation
                or fixed_prefix_continuation
            )
            or following.bbox[1] < previous.bbox[1] - 1.0
        ):
            return False
        vertical_gap = following.bbox[1] - previous.bbox[3]
        if vertical_gap > max(
            4.0,
            min(previous.font_size, following.font_size) * 0.5,
        ):
            return False
        overlap = min(previous.bbox[2], following.bbox[2]) - max(
            previous.bbox[0], following.bbox[0]
        )
        narrower_width = min(
            previous.bbox[2] - previous.bbox[0],
            following.bbox[2] - following.bbox[0],
        )
        if not detached_formula_suffix and overlap < narrower_width * 0.65:
            return False
        previous_plain = " ".join(strip_sentinels(previous.text).split()).strip()
        if sentence_final_text(previous_plain):
            return False
        if re.match(
            r"^(?:Theorem|Lemma|Proposition|Corollary|Definition|Assumption)\s+[A-Z0-9]",
            following_plain,
            re.IGNORECASE,
        ):
            return False
        return True

    combined: List[Tuple[TextBlock, str]] = []
    index = 0
    while index < len(items):
        block, translated = items[index]
        cursor = index + 1
        combined_formula_flow = block.flow_inline_math
        while cursor < len(items) and can_append(block, items[cursor][0]):
            following, following_translation = items[cursor]
            merged = merge_two_blocks(block, following)
            combined_formula_flow = bool(
                combined_formula_flow
                or following.flow_inline_math
                or merged.formula_anchors
                or merged.keepout_formula_atom_groups
            )
            block = replace(
                merged,
                block_type=block.block_type,
                no_merge=True,
                preserve_position=False,
                # Keep the original value while the continuation chain is
                # still open. The guard in ``can_append`` deliberately
                # rejects pre-existing flow blocks, but must not truncate a
                # chain that this pass itself just assembled.
                flow_inline_math=block.flow_inline_math,
                bold_prefix=block.bold_prefix,
                translated_bold_prefix_chars=block.translated_bold_prefix_chars,
                source_style_runs=tuple(
                    [*block.source_style_runs, *following.source_style_runs]
                ),
            )
            translated = join_lines([translated, following_translation])
            cursor += 1
        if cursor > index + 1:
            block = replace(block, flow_inline_math=combined_formula_flow)
        combined.append((block, translated))
        index = cursor
    return combined


_SIBLING_LIST_MARKER_RE = re.compile(
    r"^\s*(?:[•◦▪●·‣]|\(?\d{1,2}[).]|\(?[a-zA-Z][).](?![A-Za-z])|[-–—*])\s*\S"
)


def _combine_list_continuation_translation_items(
    items: Sequence[Tuple[TextBlock, str]],
) -> List[Tuple[TextBlock, str]]:
    """Typeset a wrapped list item as one flow instead of stacked line boxes."""

    def can_append(
        list_lead: TextBlock,
        previous: TextBlock,
        continuation: TextBlock,
    ) -> bool:
        lead_plain = " ".join(strip_sentinels(list_lead.text).split()).strip()
        previous_plain = " ".join(strip_sentinels(previous.text).split()).strip()
        continuation_plain = " ".join(
            strip_sentinels(continuation.text).split()
        ).strip()
        if (
            list_lead.page_index != continuation.page_index
            or list_lead.block_type != "body"
            or previous.block_type != "body"
            or continuation.block_type != "body"
            or list_lead.nowrap
            or previous.nowrap
            or continuation.nowrap
            or list_lead.preserve_position
            or previous.preserve_position
            or continuation.preserve_position
            # List leads are deliberately no_merge during source paragraph
            # assembly. Here their marker and continuation geometry provide
            # the stronger evidence needed to build one typesetting flow.
            or (previous is not list_lead and previous.no_merge)
            or continuation.no_merge
            or list_lead.keepout_bboxes
            or previous.keepout_bboxes
            or continuation.keepout_bboxes
            or list_lead.source_math_bboxes
            or previous.source_math_bboxes
            or continuation.source_math_bboxes
            or list_lead.formula_anchors
            or previous.formula_anchors
            or continuation.formula_anchors
            or not _SIBLING_LIST_MARKER_RE.match(lead_plain)
            or _SIBLING_LIST_MARKER_RE.match(continuation_plain)
            or re.search(r"[.!?;:\u3002\uff01\uff1f\uff1b\uff1a]\s*$", previous_plain)
            or abs(list_lead.font_size - continuation.font_size) > 0.75
        ):
            return False
        vertical_gap = continuation.bbox[1] - previous.bbox[3]
        continuation_indent = continuation.bbox[0] - list_lead.bbox[0]
        horizontal_overlap = min(previous.bbox[2], continuation.bbox[2]) - max(
            previous.bbox[0], continuation.bbox[0]
        )
        narrower_width = min(
            previous.bbox[2] - previous.bbox[0],
            continuation.bbox[2] - continuation.bbox[0],
        )
        return bool(
            -1.5 <= vertical_gap <= max(4.0, list_lead.font_size * 0.5)
            and -2.0
            <= continuation_indent
            <= max(18.0, list_lead.font_size * 2.0)
            and horizontal_overlap >= narrower_width * 0.65
        )

    combined: List[Tuple[TextBlock, str]] = []
    index = 0
    while index < len(items):
        lead, lead_translation = items[index]
        if index + 1 >= len(items) or not can_append(
            lead,
            lead,
            items[index + 1][0],
        ):
            combined.append((lead, lead_translation))
            index += 1
            continue

        blocks = [lead]
        translations = [lead_translation]
        cursor = index + 1
        while cursor < len(items) and can_append(
            lead,
            blocks[-1],
            items[cursor][0],
        ):
            continuation, continuation_translation = items[cursor]
            blocks.append(continuation)
            translations.append(continuation_translation)
            cursor += 1

        source_text = join_lines([block.text for block in blocks])
        merged = replace(
            lead,
            bbox=union_bbox([block.bbox for block in blocks]),
            text=source_text,
            source_lines=sum(max(1, block.source_lines) for block in blocks),
            no_merge=True,
            redact_bboxes=list(
                dict.fromkeys(
                    bbox
                    for block in blocks
                    for bbox in (block.redact_bboxes or [block.bbox])
                )
            ),
            bold_terms=tuple(
                dict.fromkeys(term for block in blocks for term in block.bold_terms)
            ),
            source_style_runs=tuple(
                run for block in blocks for run in block.source_style_runs
            ),
            source_line_bboxes=tuple(
                dict.fromkeys(
                    bbox for block in blocks for bbox in block.source_line_bboxes
                )
            ),
            preserved_math_placeholders=tuple(
                range(len(SENTINEL_RUN_RE.findall(source_text)))
            ),
        )
        translated = " ".join(
            translation.strip() for translation in translations if translation.strip()
        )
        combined.append((merged, translated))
        index = cursor
    return combined


def _sibling_group_item_height(
    block: TextBlock,
    translated_text: str,
    font_pack: FontPack,
    size: float,
    margin: float,
) -> Optional[float]:
    """Height the general typesetting branch needs for `block` at `size`.

    Mirrors insert_translated_text's general path (break_lines + best
    leading). Returns None for blocks routed to special branches whose
    height this estimate would not represent.
    """
    import fitz

    if (
        block.nowrap
        or (block.preserve_position and block.block_type != "formula_prose")
        or _uses_fixed_source_math(block)
    ):
        return None
    rect = shrink_rect(fitz.Rect(block.bbox), margin)
    if rect.width <= 1:
        return None
    if _block_keepouts(block, rect):
        return None
    fonts = font_pack.fonts_for(block.bold)
    bold_fonts = font_pack.fonts_for(True)
    render_text = _translation_text_for_render(translated_text)
    tokens = _tokenize_translation_with_formula_clips(translated_text, block)
    apply_inline_bold(tokens, block, render_text)
    if not tokens:
        return None
    lines = break_lines(
        tokens,
        fonts,
        size,
        rect.width,
        prefer_space_break=False,
        bold_fonts=bold_fonts,
    )
    heights = [
        line_block_height(lines, size, leading, fonts, bold_fonts)
        for leading in leading_options(block)
    ]
    return min(heights) if heights else None


def _expand_caption_bbox_upward(
    block: TextBlock,
    translated_text: str,
    candidates: Sequence[TextBlock],
    font_pack: FontPack,
    requested_size: float,
    margin: float,
    obstacles: Sequence[BBox] = (),
) -> TextBlock:
    """Grow a position-anchored caption upward by its height deficit.

    Table captions anchor above their table (preserve_position=True), so the
    growth passes skip them; when the Chinese needs one more wrapped line
    than the English, the fitter crushes the font instead. The whitespace
    above a caption is almost always free, so grow y0 by exactly the missing
    height (the render then fills back down to the anchored bottom edge)
    while respecting neighbouring ink.
    """
    if block.block_type != "caption" or not block.preserve_position:
        return block
    if block.nowrap or _uses_fixed_source_math(block):
        return block
    x0, y0, x1, y1 = block.bbox
    needed = _sibling_group_item_height(
        replace(block, preserve_position=False),
        translated_text,
        font_pack,
        requested_size,
        margin,
    )
    if needed is None:
        return block
    current = y1 - y0
    deficit = needed + margin * 2.0 - current
    if deficit <= 0.5 or deficit > requested_size * 1.6 * 3:
        return block
    ceiling = 36.0
    for candidate in candidates:
        if candidate is block:
            continue
        cx0, cy0, cx1, cy1 = candidate.bbox
        if min(x1, cx1) - max(x0, cx0) <= 0.0:
            continue
        if cy1 <= y0 + 0.5 and cy1 > ceiling:
            ceiling = cy1
    for region in obstacles:
        rx0, ry0, rx1, ry1 = region
        if min(x1, rx1) - max(x0, rx0) <= 0.0:
            continue
        if ry1 <= y0 + 0.5 and ry1 > ceiling:
            ceiling = ry1
    new_y0 = max(y0 - deficit, ceiling + 2.0)
    if new_y0 >= y0 - 0.5:
        return block
    return replace(block, bbox=(x0, new_y0, x1, y1))


def _is_sibling_list_item(block: TextBlock, translated_text: str) -> bool:
    if block.block_type not in {"body", "formula_prose"}:
        return False
    if block.nowrap or (
        block.preserve_position and block.block_type != "formula_prose"
    ):
        return False
    # Run-in styled records (bold label + body flowed as one block) have a
    # dedicated reflow path; the group pass must not re-stack them.
    if (
        block.bold_prefix
        or block.translated_bold_prefix_chars
        or block.flow_inline_math
    ):
        return False
    plain = " ".join(strip_sentinels(block.text).split()).strip()
    translated_plain = " ".join(strip_sentinels(translated_text).split()).strip()
    return bool(
        _SIBLING_LIST_MARKER_RE.match(plain)
        or _SIBLING_LIST_MARKER_RE.match(translated_plain)
    )


def _sibling_group_floor(
    group: Sequence[int],
    page_items: Sequence[Tuple[TextBlock, str]],
    obstacles: Sequence[BBox],
    page_height: float,
) -> float:
    """Lowest y the group may grow to before hitting the next content."""
    blocks = [page_items[i][0] for i in group]
    last = blocks[-1]
    x0 = min(block.bbox[0] for block in blocks)
    x1 = max(block.bbox[2] for block in blocks)
    floor = page_height - 30.0
    group_set = set(group)
    for index, (other, _text) in enumerate(page_items):
        if index in group_set:
            continue
        ox0, oy0, ox1, _oy1 = other.bbox
        if ox1 <= x0 + 2.0 or ox0 >= x1 - 2.0:
            continue
        if oy0 >= last.bbox[3] - 1.0:
            floor = min(floor, oy0)
    for ox0, oy0, ox1, _oy1 in obstacles:
        if ox1 <= x0 + 2.0 or ox0 >= x1 - 2.0:
            continue
        if oy0 >= last.bbox[3] - 1.0:
            floor = min(floor, oy0)
    return floor


def _harmonize_sibling_list_items(
    page_items: List[Tuple[TextBlock, str]],
    centered_flags: Sequence[bool],
    font_pack: FontPack,
    min_font_size: float,
    font_scale: float,
    margin: float,
    page_height: float = 792.0,
    obstacles: Sequence[BBox] = (),
) -> List[Tuple[TextBlock, str]]:
    """Re-typeset consecutive sibling list items at one shared font size.

    Chinese line stacks are taller than the source English ones, so items
    fitted independently against their own source bbox shrink by different
    amounts (contribution bullets at 9.2/7.4/6.4pt on one page). Siblings are
    laid out again as one group: the union region may grow downward into
    free whitespace (up to the next item/obstacle) so the shared size stays
    close to the page's body scale.
    """
    groups: List[List[int]] = []
    current: List[int] = []
    for index, (block, translated_text) in enumerate(page_items):
        eligible = (
            _is_sibling_list_item(block, translated_text)
            and not centered_flags[index]
        )
        if eligible and current:
            prev_block = page_items[current[-1]][0]
            # List entries naturally end at very different x coordinates;
            # their common left edge identifies the column. Requiring similar
            # right edges splits short and long siblings into different font
            # groups even when their markers and baselines form one sequence.
            same_column = abs(block.bbox[0] - prev_block.bbox[0]) <= 6.0
            same_size = abs(block.font_size - prev_block.font_size) <= 0.5
            gap = block.bbox[1] - prev_block.bbox[3]
            adjacent = -4.0 <= gap <= max(10.0, block.font_size * 1.6)
            if not (same_column and same_size and adjacent):
                if len(current) >= 2:
                    groups.append(current)
                current = []
        if eligible:
            current.append(index)
        else:
            if len(current) >= 2:
                groups.append(current)
            current = []
    if len(current) >= 2:
        groups.append(current)

    for group in groups:
        blocks = [page_items[i][0] for i in group]
        texts = [page_items[i][1] for i in group]
        union_y0 = blocks[0].bbox[1]
        union_y1 = blocks[-1].bbox[3]
        union_height = union_y1 - union_y0
        if union_height <= 4.0:
            continue
        floor_y = _sibling_group_floor(group, page_items, obstacles, page_height)
        allowed_height = max(union_height, floor_y - 2.0 - union_y0)
        gaps = [
            max(0.6, blocks[i + 1].bbox[1] - blocks[i].bbox[3])
            for i in range(len(blocks) - 1)
        ]
        requested = min(
            requested_translation_font_size(block, min_font_size, font_scale)
            for block in blocks
        )
        group_min = max(
            effective_min_font_size(block, min_font_size) for block in blocks
        )
        chosen: Optional[Tuple[float, List[float]]] = None
        size = requested
        while size >= group_min - 1e-6:
            heights = [
                _sibling_group_item_height(block, text, font_pack, size, margin)
                for block, text in zip(blocks, texts)
            ]
            if any(height is None for height in heights):
                chosen = None
                break
            padded = [height + 2.0 * margin + 0.6 for height in heights]
            if sum(padded) + sum(gaps) <= allowed_height + 0.5:
                chosen = (size, padded)
                break
            size -= 0.25
        if chosen is None:
            continue
        size, padded = chosen
        y_cursor = union_y0
        for offset, (index, height) in enumerate(zip(group, padded)):
            block, translated_text = page_items[index]
            redacts = block.redact_bboxes or [block.bbox]
            page_items[index] = (
                replace(
                    block,
                    bbox=(block.bbox[0], y_cursor, block.bbox[2], y_cursor + height),
                    redact_bboxes=list(redacts),
                    fixed_translation_font_size=size,
                ),
                translated_text,
            )
            y_cursor += height
            if offset < len(gaps):
                y_cursor += gaps[offset]
    return page_items


_CASCADE_EXPANDABLE_TYPES = frozenset(
    {"body", "formula_prose", "list", "heading", "caption"}
)
_CASCADE_MOVABLE_TYPES = frozenset(
    {"body", "formula_prose", "list", "heading", "run_in_heading"}
)
_FORMULA_CASCADE_EXPAND_MAX_LINES = 3.25


def _cascade_same_column(first: TextBlock, second: TextBlock) -> bool:
    first_width = max(1.0, first.bbox[2] - first.bbox[0])
    second_width = max(1.0, second.bbox[2] - second.bbox[0])
    width_ratio = min(first_width, second_width) / max(first_width, second_width)
    overlap = min(first.bbox[2], second.bbox[2]) - max(
        first.bbox[0], second.bbox[0]
    )
    narrower_width = min(first_width, second_width)
    if width_ratio >= 0.55 and overlap >= narrower_width * 0.65:
        return True

    first_plain = " ".join(strip_sentinels(first.text).split()).strip()
    second_plain = " ".join(strip_sentinels(second.text).split()).strip()
    continuation_indent = second.bbox[0] - first.bbox[0]
    body_roles = {"body", "formula_prose"}
    if (
        first.block_type in body_roles
        and second.block_type in body_roles
        and abs(continuation_indent)
        <= max(4.0, min(first.font_size, second.font_size) * 0.4)
        and overlap >= narrower_width * 0.9
    ):
        # A short final sentence in a dense full-width stack can be much
        # narrower than the paragraph above it. Equal left edges still make
        # the column ownership unambiguous, so it must follow cascade shifts.
        return True
    if (
        first.block_type == "body"
        and second.block_type == "body"
        and _SIBLING_LIST_MARKER_RE.match(first_plain)
        and not _SIBLING_LIST_MARKER_RE.match(second_plain)
        and -2.0 <= continuation_indent <= max(18.0, first.font_size * 2.0)
        and overlap >= narrower_width * 0.65
    ):
        return True

    heading_roles = {"heading", "run_in_heading"}
    if first.block_type not in heading_roles and second.block_type not in heading_roles:
        return False
    if overlap < narrower_width * 0.65:
        return False

    # A short checklist/appendix heading can be one third the width of the
    # paragraph below it.  They still share a text stream when their left
    # edges align, but a page-wide heading must not capture the right column.
    left_edge_delta = abs(first.bbox[0] - second.bbox[0])
    return left_edge_delta <= max(40.0, narrower_width * 0.35)


def _cascade_formula_regions(block: TextBlock) -> Tuple[BBox, ...]:
    """Formula ink regions whose layout ownership belongs to ``block``."""
    return tuple(
        dict.fromkeys(
            [
                *block.formula_anchors,
                *block.source_math_bboxes,
            ]
        )
    )


def _cascade_obstacle_is_owned_formula(block: TextBlock, obstacle: BBox) -> bool:
    obstacle_area = max(1.0, bbox_area(obstacle))
    for formula_region in _cascade_formula_regions(block):
        formula_area = max(1.0, bbox_area(formula_region))
        overlap = bbox_intersection_area(obstacle, formula_region)
        if overlap / min(obstacle_area, formula_area) >= 0.55:
            return True
    return False


def _cascade_item_movable(block: TextBlock) -> bool:
    return bool(
        block.block_type in _CASCADE_MOVABLE_TYPES
        and not block.nowrap
        # Section headings are source-anchored under normal rendering, but
        # must travel with the prose column when an earlier translated block
        # grows. Otherwise every heading becomes a hard wall and dense pages
        # can only respond by crushing the preceding CJK font. Captions and
        # other preserved content remain fixed because they are not in the
        # movable type set.
        and (
            not block.preserve_position
            or block.block_type in {"heading", "run_in_heading"}
        )
        and not _uses_fixed_source_math(block)
    )


def _cascade_item_expandable(block: TextBlock) -> bool:
    """Whether an item's bottom may grow while its source top stays fixed."""
    return bool(
        block.block_type in _CASCADE_EXPANDABLE_TYPES
        and not block.nowrap
        and (
            not block.preserve_position
            # Formula-leading prose preserves its source top so the formula
            # keepout stays anchored, but the translated prose rectangle may
            # still borrow whitespace below it.  The cascade only changes y1
            # and retains the original redaction boxes / formula coordinates.
            or block.block_type in {"caption", "formula_prose"}
        )
    )


def _cascade_extension_limit(block: TextBlock, requested: float) -> float:
    """Return how far a translated block may borrow space from its column."""
    max_lines = (
        _FORMULA_CASCADE_EXPAND_MAX_LINES
        if block.source_math_bboxes and block.keepout_bboxes
        else _MULTILINE_EXPAND_MAX_LINES
    )
    return max_lines * requested * 1.3


def _cascade_min_gap(previous: TextBlock, following: TextBlock) -> float:
    """Minimum readable gap while propagated overflow consumes source whitespace."""
    reference = min(previous.font_size, following.font_size)
    if following.block_type in {"heading", "run_in_heading"}:
        return max(3.0, min(5.0, reference * 0.35))
    if previous.block_type in {"heading", "run_in_heading"}:
        return max(2.0, min(4.0, reference * 0.24))
    return max(1.5, min(3.0, reference * 0.18))


def _cascade_follower_shifts(
    page_items: Sequence[Tuple[TextBlock, str]],
    block_index: int,
    follower_indices: Sequence[int],
    deficit: float,
) -> Dict[int, float]:
    """Propagate an expansion only until a later source gap absorbs it."""
    block = page_items[block_index][0]
    previous = replace(
        block,
        bbox=(block.bbox[0], block.bbox[1], block.bbox[2], block.bbox[3] + deficit),
    )
    shifts: Dict[int, float] = {}
    for other_index in sorted(
        follower_indices,
        key=lambda index: (
            page_items[index][0].bbox[1],
            page_items[index][0].bbox[0],
        ),
    ):
        other = page_items[other_index][0]
        required_y0 = previous.bbox[3] + _cascade_min_gap(previous, other)
        shift = max(0.0, required_y0 - other.bbox[1])
        if shift <= 0.0:
            break
        shifts[other_index] = shift
        previous = replace(
            other,
            bbox=(
                other.bbox[0],
                other.bbox[1] + shift,
                other.bbox[2],
                other.bbox[3] + shift,
            ),
        )
    return shifts


def _cascade_required_height(
    block: TextBlock,
    translated_text: str,
    *,
    font_pack: FontPack,
    min_font_size: float,
    requested: float,
    margin: float,
) -> Optional[float]:
    needed = _sibling_group_item_height(
        block,
        translated_text,
        font_pack,
        requested,
        margin,
    )
    if needed is not None:
        return needed + margin * 2.0 + 0.6

    # Formula keepouts make the generic line-height estimate invalid. Probe
    # the real fitter while growing only the target bottom; this keeps every
    # absolute keepout in place and finds the smallest body-scale rectangle.
    if not block.keepout_bboxes:
        return None
    current = block.bbox[3] - block.bbox[1]
    maximum = current + _cascade_extension_limit(block, requested)

    def fits(height: float) -> bool:
        trial = replace(
            block,
            bbox=(
                block.bbox[0],
                block.bbox[1],
                block.bbox[2],
                block.bbox[1] + height,
            ),
        )
        return translated_text_fits(
            block=trial,
            text=translated_text,
            font_pack=font_pack,
            font_size=requested,
            min_font_size=max(min_font_size, requested * 0.995),
            margin=margin,
            centered=False,
        )

    if fits(current):
        return current
    if not fits(maximum):
        return None
    low = current
    high = maximum
    for _ in range(6):
        if high - low <= 0.5:
            break
        middle = (low + high) / 2.0
        if fits(middle):
            high = middle
        else:
            low = middle
    return high


def _cascade_expand_page_items(
    page_items: List[Tuple[TextBlock, str]],
    *,
    font_pack: FontPack,
    min_font_size: float,
    font_scale: float,
    margin: float,
    page_height: float,
    obstacles: Sequence[BBox] = (),
    float_obstacles: Sequence[BBox] = (),
) -> List[Tuple[TextBlock, str]]:
    """Grow prose at body scale and carry the deficit down its text column.

    The local growth passes stop at the next source block. In a dense column
    that leaves no usable gap, even when several following prose blocks could
    move together into whitespace near the bottom of the column. This pass
    propagates a required height increase through movable followers, stopping
    at fixed floats, equations, captions, preserved blocks, or the page foot.
    """
    updated = list(page_items)
    float_obstacle_set = set(float_obstacles)
    order = sorted(
        range(len(updated)),
        key=lambda index: (
            updated[index][0].bbox[1],
            updated[index][0].bbox[0],
        ),
    )
    page_floor = page_height - _PAGE_BOTTOM_KEEPOUT

    # A theorem-like statement can start immediately after a long paragraph
    # whose source bbox includes a blank tail. The source rectangles overlap,
    # but the translated predecessor is top-aligned and may provably finish
    # earlier. Reclaim only that measured tail so dense inline formulas do not
    # force the statement label below its body-role size.
    for index in order:
        block, translated_text = updated[index]
        plain = " ".join(strip_sentinels(block.text).split()).strip()
        if not (
            block.flow_inline_math
            and not block.nowrap
            and not block.preserve_position
            and _ACADEMIC_FORMULA_STATEMENT_RE.match(plain)
        ):
            continue
        requested = (
            block.fixed_translation_font_size
            or requested_translation_font_size(block, min_font_size, font_scale)
        )
        role_floor = max(min_font_size, requested * 0.85)
        if translated_text_fits(
            block=block,
            text=translated_text,
            font_pack=font_pack,
            font_size=role_floor,
            min_font_size=role_floor,
            margin=margin,
        ):
            continue
        predecessors = [
            other_index
            for other_index, (other, _other_text) in enumerate(updated)
            if other_index != index
            and _cascade_same_column(block, other)
            and other.block_type in {"body", "formula_prose", "list"}
            and not other.nowrap
            and not other.preserve_position
            and other.bbox[1] < block.bbox[1]
            and other.bbox[3] <= block.bbox[1] + 1.0
            and block.bbox[1] - other.bbox[3]
            <= max(12.0, block.font_size * 1.3)
        ]
        if not predecessors:
            continue
        predecessor_index = max(
            predecessors,
            key=lambda other_index: updated[other_index][0].bbox[3],
        )
        predecessor, predecessor_text = updated[predecessor_index]
        predecessor_requested = (
            predecessor.fixed_translation_font_size
            or requested_translation_font_size(
                predecessor,
                min_font_size,
                font_scale,
            )
        )
        predecessor_height = _cascade_required_height(
            predecessor,
            predecessor_text,
            font_pack=font_pack,
            min_font_size=min_font_size,
            requested=predecessor_requested,
            margin=margin,
        )
        if predecessor_height is None:
            continue
        predecessor_safe_bottom = (
            predecessor.bbox[1] + predecessor_height + max(1.5, margin * 2.0)
        )
        max_borrow = block.bbox[1] - predecessor_safe_bottom
        if max_borrow < 0.5:
            continue
        borrow = 0.5
        while borrow <= max_borrow + 1e-6:
            candidate = replace(
                block,
                bbox=(
                    block.bbox[0],
                    block.bbox[1] - borrow,
                    block.bbox[2],
                    block.bbox[3],
                ),
                redact_bboxes=list(block.redact_bboxes or [block.bbox]),
            )
            borrowed_band = (
                block.bbox[0],
                candidate.bbox[1],
                block.bbox[2],
                block.bbox[1],
            )
            if any(
                bbox_intersection_area(borrowed_band, obstacle) > 0.5
                for obstacle in obstacles
            ):
                borrow += 0.5
                continue
            if translated_text_fits(
                block=candidate,
                text=translated_text,
                font_pack=font_pack,
                font_size=role_floor,
                min_font_size=role_floor,
                margin=margin,
            ):
                updated[index] = (candidate, translated_text)
                break
            borrow += 0.5

    for index in order:
        block, translated_text = updated[index]
        if (
            block.block_type not in _CASCADE_EXPANDABLE_TYPES
            or not _cascade_item_expandable(block)
        ):
            continue
        requested = (
            block.fixed_translation_font_size
            or requested_translation_font_size(block, min_font_size, font_scale)
        )
        extension_limit = _cascade_extension_limit(block, requested)
        side_float_keepouts: List[BBox] = []
        for obstacle in float_obstacles:
            horizontal_overlap = min(block.bbox[2], obstacle[2]) - max(
                block.bbox[0], obstacle[0]
            )
            free_side = max(
                obstacle[0] - block.bbox[0],
                block.bbox[2] - obstacle[2],
            )
            if (
                horizontal_overlap > 0.0
                and free_side >= 120.0
                and obstacle[1] < block.bbox[3] + extension_limit + 2.0
                and obstacle[3] > block.bbox[1]
            ):
                side_float_keepouts.append(expand_bbox(obstacle, 2.0))
        if side_float_keepouts:
            block = replace(
                block,
                keepout_bboxes=list(
                    dict.fromkeys(
                        [*(block.keepout_bboxes or []), *side_float_keepouts]
                    )
                ),
            )
        target_height = _cascade_required_height(
            block,
            translated_text,
            font_pack=font_pack,
            min_font_size=min_font_size,
            requested=requested,
            margin=margin,
        )
        if target_height is None:
            continue
        current_height = block.bbox[3] - block.bbox[1]
        deficit = target_height - current_height
        if deficit <= 0.6:
            continue
        deficit = min(deficit, extension_limit)

        floor = page_floor
        followers: List[int] = []
        for other_index, (other, _other_text) in enumerate(updated):
            if other_index == index or not _cascade_same_column(block, other):
                continue
            source_overlap = block.bbox[3] - other.bbox[1]
            overlapping_formula_flow = bool(
                block.flow_inline_math
                and other.flow_inline_math
                and _cascade_item_movable(other)
                and other.bbox[1] > block.bbox[1] + 1.0
                and 0.0 < source_overlap
                <= max(6.0, min(block.font_size, other.font_size) * 0.65)
            )
            if (
                other.bbox[1] < block.bbox[3] - 1.0
                and not overlapping_formula_flow
            ):
                continue
            if _cascade_item_movable(other):
                followers.append(other_index)
            else:
                floor = min(floor, other.bbox[1] - 2.0)
        for obstacle in obstacles:
            overlap = min(block.bbox[2], obstacle[2]) - max(
                block.bbox[0], obstacle[0]
            )
            if overlap <= min(
                block.bbox[2] - block.bbox[0],
                obstacle[2] - obstacle[0],
            ) * 0.35:
                continue
            if _cascade_obstacle_is_owned_formula(block, obstacle) or any(
                _cascade_obstacle_is_owned_formula(
                    updated[other_index][0],
                    obstacle,
                )
                for other_index in followers
            ):
                continue
            target_reaches_obstacle = (
                obstacle[1] < block.bbox[3] + deficit + 2.0
            )
            vertically_relevant_followers = [
                updated[other_index][0]
                for other_index in followers
                if min(updated[other_index][0].bbox[3], obstacle[3])
                - max(updated[other_index][0].bbox[1], obstacle[1])
                > 0.0
            ]
            followers_are_horizontally_clear = bool(
                vertically_relevant_followers
            ) and all(
                min(follower.bbox[2], obstacle[2])
                - max(follower.bbox[0], obstacle[0])
                <= 0.0
                for follower in vertically_relevant_followers
            )
            if not target_reaches_obstacle and followers_are_horizontally_clear:
                continue
            if obstacle in float_obstacle_set:
                free_side = max(
                    obstacle[0] - block.bbox[0],
                    block.bbox[2] - obstacle[2],
                )
                follower_uses_free_side = False
                for other_index in followers:
                    follower = updated[other_index][0]
                    vertical_overlap = min(follower.bbox[3], obstacle[3]) - max(
                        follower.bbox[1], obstacle[1]
                    )
                    if vertical_overlap <= 0.0:
                        continue
                    horizontal_overlap = min(follower.bbox[2], obstacle[2]) - max(
                        follower.bbox[0], obstacle[0]
                    )
                    follower_free_side = max(
                        obstacle[0] - follower.bbox[0],
                        follower.bbox[2] - obstacle[2],
                    )
                    if horizontal_overlap <= 0.0 or follower_free_side >= 120.0:
                        follower_uses_free_side = True
                        break
                if (
                    free_side >= 120.0
                    and (
                        target_reaches_obstacle
                        or follower_uses_free_side
                    )
                ):
                    continue
            if obstacle[1] >= block.bbox[3] - 1.0:
                floor = min(floor, obstacle[1] - 2.0)

        followers = [
            other_index
            for other_index in followers
            if updated[other_index][0].bbox[1] < floor
        ]
        follower_shifts = _cascade_follower_shifts(
            updated,
            index,
            followers,
            deficit,
        )
        final_bottom = max(
            [block.bbox[3] + deficit]
            + [
                updated[other_index][0].bbox[3] + shift
                for other_index, shift in follower_shifts.items()
            ]
        )
        if final_bottom > floor + 0.2:
            continue

        redacts = block.redact_bboxes or [block.bbox]
        updated[index] = (
            replace(
                block,
                bbox=(
                    block.bbox[0],
                    block.bbox[1],
                    block.bbox[2],
                    block.bbox[3] + deficit,
                ),
                redact_bboxes=list(redacts),
            ),
            translated_text,
        )
        for other_index, shift in follower_shifts.items():
            other, other_text = updated[other_index]
            redacts = other.redact_bboxes or [other.bbox]
            updated[other_index] = (
                replace(
                    other,
                    bbox=(
                        other.bbox[0],
                        other.bbox[1] + shift,
                        other.bbox[2],
                        other.bbox[3] + shift,
                    ),
                    redact_bboxes=list(redacts),
                ),
                other_text,
            )
    return updated


def _expand_single_line_list_bbox(
    block: TextBlock,
    translated_text: str,
    page_blocks: Sequence[TextBlock],
    font_pack: FontPack,
    font_size: float,
    margin: float,
) -> TextBlock:
    """Use the source row's whitespace as the translated list line box."""
    plain = " ".join(strip_sentinels(block.text).split()).strip()
    if (
        block.source_lines != 1
        or block.nowrap
        or not re.match(r"^(?:[•◦▪●]|\(?[a-zA-Z0-9]{1,3}\)|[-–])\s+", plain)
    ):
        return block

    fonts = font_pack.fonts_for(block.bold)
    bold_fonts = font_pack.fonts_for(True)
    render_text = _translation_text_for_render(translated_text)
    tokens = _tokenize_translation_with_formula_clips(translated_text, block)
    apply_inline_bold(tokens, block, render_text)
    if not tokens:
        return block
    ascent, descent = _line_vertical_metrics(tokens, font_size, fonts, bold_fonts)
    desired_height = ascent + descent + margin * 2.0
    x0, y0, x1, y1 = block.bbox
    if desired_height <= y1 - y0 + 0.1:
        return block

    center_y = (y0 + y1) / 2.0
    top_limit = 0.0
    bottom_limit = float("inf")
    for other in page_blocks:
        if other is block or other.page_index != block.page_index:
            continue
        horizontal_overlap = min(x1, other.bbox[2]) - max(x0, other.bbox[0])
        if horizontal_overlap <= 0.0:
            continue
        if other.bbox[3] <= center_y:
            top_limit = max(top_limit, other.bbox[3] + 0.4)
        elif other.bbox[1] >= center_y:
            bottom_limit = min(bottom_limit, other.bbox[1] - 0.4)

    new_y0 = center_y - desired_height / 2.0
    new_y1 = center_y + desired_height / 2.0
    if new_y0 < top_limit:
        new_y1 += top_limit - new_y0
        new_y0 = top_limit
    if new_y1 > bottom_limit:
        new_y0 -= new_y1 - bottom_limit
        new_y1 = bottom_limit
    if new_y0 < top_limit or new_y1 - new_y0 < desired_height - 0.1:
        return block
    return replace(block, bbox=(x0, new_y0, x1, new_y1))


_MULTILINE_EXPAND_MAX_LINES = 2.2
_PAGE_BOTTOM_KEEPOUT = 30.0


def _expand_multiline_block_bbox(
    block: TextBlock,
    translated_text: str,
    page_blocks: Sequence[TextBlock],
    font_pack: FontPack,
    font_size: float,
    margin: float,
    page_height: float,
    *,
    obstacles: Sequence[BBox] = (),
) -> TextBlock:
    """Grow a multi-line paragraph into adjacent whitespace before shrinking.

    Translated Chinese carries first-occurrence English glosses, so body
    paragraphs regularly need one extra wrapped line. With a fixed source
    bbox the fitting loop must drop whole font-size steps to squeeze that
    line in (9.2pt prose ends up at 6.4-8.2pt). When the inter-paragraph
    gap below is genuinely free, use it first: extend the bbox bottom just
    enough for the natural line count, bounded by neighbouring blocks,
    floats/keepouts, the page bottom margin, and a hard extension cap.
    Downward space is preferred. When a formula or fixed float immediately
    below closes that path, the block may also borrow the bounded whitespace
    above it without moving or redacting the preceding item.
    """
    if (
        block.block_type not in {"body", "formula_prose", "list"}
        or block.source_lines < 2
        or block.nowrap
        or block.preserve_position
    ):
        return block

    fonts = font_pack.fonts_for(block.bold)
    bold_fonts = font_pack.fonts_for(True)
    render_text = _translation_text_for_render(translated_text)
    tokens = _tokenize_translation_with_formula_clips(translated_text, block)
    apply_inline_bold(tokens, block, render_text)
    if not tokens:
        return block

    x0, y0, x1, y1 = block.bbox

    def preceding_clearance_limit(candidate: BBox, clearance: float) -> Optional[float]:
        if candidate[1] >= y0 - 0.5:
            return None
        if candidate[3] > y0 + max(1.0, font_size * 0.75):
            return None
        return min(y0, candidate[3] + clearance)

    usable_width = max(1.0, x1 - x0 - margin * 2.0)
    lines = break_lines(
        tokens,
        fonts,
        font_size,
        usable_width,
        prefer_space_break=False,
        bold_fonts=bold_fonts,
    )
    needed_height = (
        min(
            line_block_height(lines, font_size, leading, fonts, bold_fonts)
            for leading in leading_options(block)
        )
        + margin * 2.0
    )
    height = y1 - y0
    unresolved_keepouts = _unresolved_formula_keepouts(block)
    needs_keepout_expansion = bool(
        (block.formula_anchors or block.keepout_formula_atom_groups)
        and unresolved_keepouts
        and not translated_text_fits(
            block=block,
            text=translated_text,
            font_pack=font_pack,
            font_size=font_size,
            min_font_size=font_size,
            margin=margin,
        )
    )
    if needed_height <= height + 0.1:
        if needs_keepout_expansion:
            # The first baseline can graze a tall formula that belongs to the
            # following physical row. A sub-line upward nudge often restores
            # the full body size; shrinking an entire paragraph by 1pt is a
            # much larger visual change. Bound the nudge by real neighbors and
            # keep the source redaction boxes fixed.
            top_limit = 0.0
            for other in page_blocks:
                if other is block or other.page_index != block.page_index:
                    continue
                horizontal_overlap = min(x1, other.bbox[2]) - max(
                    x0, other.bbox[0]
                )
                candidate_limit = preceding_clearance_limit(other.bbox, 0.8)
                if horizontal_overlap > 0.0 and candidate_limit is not None:
                    top_limit = max(top_limit, candidate_limit)
            for obstacle in obstacles:
                horizontal_overlap = min(x1, obstacle[2]) - max(x0, obstacle[0])
                candidate_limit = preceding_clearance_limit(obstacle, 0.8)
                if horizontal_overlap > 0.0 and candidate_limit is not None:
                    top_limit = max(top_limit, candidate_limit)
            max_shift = min(
                max(0.0, y0 - top_limit),
                max(0.0, font_size * 0.35),
            )
            shift = 0.25
            while shift <= max_shift + 1e-6:
                shifted = replace(
                    block,
                    bbox=(x0, y0 - shift, x1, y1 - shift),
                )
                if translated_text_fits(
                    block=shifted,
                    text=translated_text,
                    font_pack=font_pack,
                    font_size=font_size,
                    min_font_size=font_size,
                    margin=margin,
                ):
                    return shifted
                shift += 0.25
        else:
            return block
        needed_height = height + 0.25

    # Any lower neighbour bounds the extension, including neighbours whose
    # bbox interleaves ours by a few points (ascender/descender overlap in
    # the source): the limit never drops below the current bottom, so an
    # interleaved neighbour simply means "no room to grow".
    bottom_limit = page_height - _PAGE_BOTTOM_KEEPOUT
    if y1 > bottom_limit:
        # Some templates use the nominal bottom margin for body text and put
        # page numbers in the header. Do not shrink such a source box back to
        # the generic 30pt floor; allow one protected baseline near the edge.
        bottom_limit = page_height - max(8.0, font_size)
    for other in page_blocks:
        if other is block or other.page_index != block.page_index:
            continue
        horizontal_overlap = min(x1, other.bbox[2]) - max(x0, other.bbox[0])
        if horizontal_overlap <= 0.0:
            continue
        if other.bbox[1] > y0 + 1.0:
            bottom_limit = min(bottom_limit, max(other.bbox[1] - 2.0, y1))
    following_keepouts = [
        keepout
        for keepout in (block.keepout_bboxes or ())
        if min(x1, keepout[2]) - max(x0, keepout[0]) > 0.0
        and keepout[1] > y0 + 1.0
    ]
    entered_boundary_formula = False
    if following_keepouts:
        first_keepout_top = min(keepout[1] for keepout in following_keepouts)
        first_row_keepouts = [
            keepout
            for keepout in following_keepouts
            if keepout[1]
            <= first_keepout_top + max(2.0, block.font_size * 0.35)
        ]
        row_hull_width = max(keepout[2] for keepout in first_row_keepouts) - min(
            keepout[0] for keepout in first_row_keepouts
        )
        formula_group_atoms = {
            atom
            for group in block.keepout_formula_atom_groups
            for atom in group
        }
        boundary_formula_group = bool(
            any(keepout in formula_group_atoms for keepout in first_row_keepouts)
            and first_keepout_top
            >= y1 - max(3.0, block.font_size * 0.35)
            and max(keepout[3] for keepout in first_row_keepouts)
            > y1 + max(2.0, block.font_size * 0.20)
        )
        formula_clearance = 0.6
        # The rendered rect is inset by ``margin``. Let the outer bbox use
        # that inset, while keeping its actual text ink clear of the formula.
        # A tall formula atom crossing the source block's lower boundary is
        # also a hard row boundary even when the extracted atom itself is
        # narrow (for example, the radical of a wider display equation).
        # Borrow free space above instead of extending translated prose into
        # that formula and forcing the renderer to shrink the whole paragraph.
        if row_hull_width >= (x1 - x0) * 0.25 or boundary_formula_group:
            bottom_limit = min(
                bottom_limit,
                max(y1, first_keepout_top + margin - formula_clearance),
            )
            entered_boundary_formula = boundary_formula_group
    # Floats that leave a usable side column are flowed around instead of
    # capping the extension: the paragraph grows past the float's top and
    # the keepout slot layout wraps the overflow lines beside it (matching
    # how the source page wraps the following paragraphs).
    float_keepouts: List[BBox] = []
    for obstacle in obstacles:
        horizontal_overlap = min(x1, obstacle[2]) - max(x0, obstacle[0])
        if horizontal_overlap <= 0.0:
            continue
        if obstacle[1] > y0 + 1.0:
            free_side = max(obstacle[0] - x0, x1 - obstacle[2])
            if free_side >= 120.0:
                float_keepouts.append(
                    (
                        float(obstacle[0]),
                        float(obstacle[1]),
                        float(obstacle[2]),
                        float(obstacle[3]),
                    )
                )
            else:
                bottom_limit = min(bottom_limit, max(obstacle[1] - 2.0, y1))

    max_extension = _MULTILINE_EXPAND_MAX_LINES * font_size * 1.3
    new_y1 = min(y0 + needed_height, y1 + max_extension, bottom_limit)
    new_y0 = y0
    remaining = max(0.0, needed_height - (new_y1 - new_y0))
    top_limit = 0.0
    if remaining > 0.6 or needs_keepout_expansion:
        for other in page_blocks:
            if other is block or other.page_index != block.page_index:
                continue
            horizontal_overlap = min(x1, other.bbox[2]) - max(x0, other.bbox[0])
            candidate_limit = preceding_clearance_limit(other.bbox, 2.0)
            if horizontal_overlap > 0.0 and candidate_limit is not None:
                top_limit = max(top_limit, candidate_limit)
        for obstacle in obstacles:
            horizontal_overlap = min(x1, obstacle[2]) - max(x0, obstacle[0])
            candidate_limit = preceding_clearance_limit(obstacle, 2.0)
            if horizontal_overlap > 0.0 and candidate_limit is not None:
                top_limit = max(top_limit, candidate_limit)
    if remaining > 0.6:
        used_down = max(0.0, new_y1 - y1)
        upward_capacity = max(0.0, min(y0 - top_limit, max_extension - used_down))
        new_y0 = y0 - min(remaining, upward_capacity)

    needs_keepout_expansion = needs_keepout_expansion or entered_boundary_formula
    if needs_keepout_expansion:
        available_down = max(0.0, bottom_limit - y1)
        available_up = max(0.0, y0 - top_limit)
        extension_limit = min(max_extension, available_down + available_up)
        extension = max(0.25, (new_y1 - y1) + (y0 - new_y0))
        keepout_fit_found = False
        while extension <= extension_limit + 1e-6:
            down = min(extension, available_down)
            up = min(max(0.0, extension - down), available_up)
            candidate = replace(
                block,
                bbox=(x0, y0 - up, x1, y1 + down),
            )
            if translated_text_fits(
                block=candidate,
                text=translated_text,
                font_pack=font_pack,
                font_size=font_size,
                min_font_size=font_size,
                margin=margin,
            ):
                new_y0 = y0 - up
                new_y1 = y1 + down
                keepout_fit_found = True
                break
            extension += 0.25
        if not keepout_fit_found:
            return block

    if new_y1 <= y1 + 0.6 and new_y0 >= y0 - 0.6:
        return block
    entered_floats = [
        keepout for keepout in float_keepouts if keepout[1] < new_y1 + 2.0
    ]
    redact_bboxes = block.redact_bboxes
    if new_y0 < y0 - 0.1 and redact_bboxes is None:
        redact_bboxes = [block.bbox]
    if entered_floats:
        return replace(
            block,
            bbox=(x0, new_y0, x1, new_y1),
            redact_bboxes=redact_bboxes,
            keepout_bboxes=list(
                dict.fromkeys([*(block.keepout_bboxes or []), *entered_floats])
            ),
        )
    return replace(
        block,
        bbox=(x0, new_y0, x1, new_y1),
        redact_bboxes=redact_bboxes,
    )


def _expand_single_line_body_bbox(
    block: TextBlock,
    translated_text: str,
    page_blocks: Sequence[TextBlock],
    font_pack: FontPack,
    font_size: float,
    margin: float,
    page_width: float,
    *,
    obstacles: Sequence[BBox] = (),
    frame_rules: Tuple[Sequence[BBox], Sequence[BBox]] = ((), ()),
    page_columns: Sequence[Tuple[float, float]] = (),
) -> TextBlock:
    """Give short prose and inline-style runs enough room to keep body size.

    Widening stops at the nearest vertical frame rule and never runs more than
    1.5em past the right edge of the text column the block sits in; a boxed
    prompt or a framed note must keep its translation inside the frame.
    """
    inline_style_flow = block.flow_inline_math and block.source_lines <= 2
    compact_two_line_body = bool(
        block.source_lines == 2
        and not block.flow_inline_math
        and not block.formula_anchors
        and block.bbox[2] - block.bbox[0] >= page_width * 0.55
    )
    if (
        block.block_type not in {"body", "formula_prose"}
        or (
            block.source_lines != 1
            and not inline_style_flow
            and not compact_two_line_body
        )
        or block.nowrap
        or block.preserve_position
    ):
        return block

    fonts = font_pack.fonts_for(block.bold)
    bold_fonts = font_pack.fonts_for(True)
    render_text = _translation_text_for_render(translated_text)
    tokens = _tokenize_translation_with_formula_clips(translated_text, block)
    apply_inline_bold(tokens, block, render_text)
    if not tokens:
        return block
    for token in tokens:
        token.width = token_width(token, fonts, font_size, bold_fonts)
    x0, y0, x1, y1 = block.bbox
    block_width = max(1.0, x1 - x0)
    embedded_in_equation_row = any(
        obstacle[0] <= x0 + 0.8
        and obstacle[2] >= x1 - 0.8
        and obstacle[2] - obstacle[0] >= block_width + 4.0
        and min(y1, obstacle[3]) - max(y0, obstacle[1])
        >= min(y1 - y0, obstacle[3] - obstacle[1]) * 0.6
        for obstacle in obstacles
    )
    row_right = page_width - max(0.5, margin)
    center_y = (y0 + y1) / 2.0
    for other in page_blocks:
        if other is block or other.page_index != block.page_index:
            continue
        vertical_overlap = min(y1, other.bbox[3]) - max(y0, other.bbox[1])
        if vertical_overlap <= 0.0 or other.bbox[0] < x1 - 0.5:
            continue
        row_right = min(row_right, other.bbox[0] - 0.8)
    horizontal_rules, vertical_rules = frame_rules
    frame_right = _frame_right_limit(
        block.bbox,
        vertical_rules,
        inset=max(1.5, margin + 1.0),
    )
    if frame_right is not None:
        row_right = min(row_right, max(x1, frame_right))
    containing_columns = [
        column
        for column in page_columns
        if column[0] - 4.0 <= x0 <= column[0] + column[1] + 4.0
    ]
    if containing_columns:
        column_left, column_width = min(
            containing_columns,
            key=lambda column: abs(x0 - column[0]),
        )
        row_right = min(
            row_right,
            max(x1, column_left + column_width + font_size * 1.5),
        )
    if inline_style_flow:
        same_column_rights = [
            other.bbox[2]
            for other in page_blocks
            if other is not block
            and other.page_index == block.page_index
            and other.block_type in {"body", "formula_prose", "list"}
            and not other.nowrap
            and not other.preserve_position
            and abs(other.bbox[0] - x0) <= max(4.0, font_size * 0.6)
            and other.bbox[2] >= x1 + max(12.0, font_size * 1.2)
        ]
        if same_column_rights:
            row_right = min(row_right, max(same_column_rights))
    if inline_style_flow:
        flow_width = max(1.0, row_right - x0)
        lines = break_lines(
            tokens,
            fonts,
            font_size,
            max(1.0, flow_width - margin * 2.0),
            prefer_space_break=False,
            bold_fonts=bold_fonts,
        )
        desired_width = flow_width
        desired_height = (
            min(
                line_block_height(lines, font_size, leading, fonts, bold_fonts)
                for leading in leading_options(block)
            )
            + margin * 2.0
        )
    else:
        desired_width = sum(token.width for token in tokens) + margin * 2.0
        ascent, descent = _line_vertical_metrics(tokens, font_size, fonts, bold_fonts)
        desired_height = ascent + descent + margin * 2.0

    new_x1 = (
        x1
        if embedded_in_equation_row
        else min(row_right, max(x1, x0 + desired_width))
    )
    if compact_two_line_body:
        if (
            desired_width <= row_right - x0 + 0.1
            and desired_height <= y1 - y0 + 0.1
        ):
            # Some TeX notes occupy two physical source rows only because a
            # formula starts immediately below them. Their shorter Chinese
            # text fits one row at body size when the unused right margin is
            # borrowed. Keep the existing vertical box so the adjacent formula
            # remains a hard boundary; only widen the prose line.
            return replace(block, bbox=(x0, y0, new_x1, y1))
        # Still two lines after widening: keep the source box. Widening a
        # wrapped paragraph only pushes its first line past the frame or into
        # the margin without saving a line.
        return block

    top_limit = 0.0
    bottom_limit = float("inf")
    for other in page_blocks:
        if other is block or other.page_index != block.page_index:
            continue
        horizontal_overlap = min(new_x1, other.bbox[2]) - max(x0, other.bbox[0])
        if horizontal_overlap <= 0.0:
            continue
        if other.bbox[3] <= center_y:
            top_limit = max(top_limit, other.bbox[3] + 0.4)
        elif other.bbox[1] >= center_y:
            bottom_limit = min(bottom_limit, other.bbox[1] - 0.4)
    for rule in horizontal_rules:
        horizontal_overlap = min(new_x1, rule[2]) - max(x0, rule[0])
        if horizontal_overlap <= 0.0:
            continue
        if rule[3] <= center_y:
            top_limit = max(top_limit, rule[3] + 0.8)
        elif rule[1] >= center_y:
            bottom_limit = min(bottom_limit, rule[1] - 0.8)
    for keepout in _unresolved_formula_keepouts(block):
        horizontal_overlap = min(new_x1, keepout[2]) - max(x0, keepout[0])
        if horizontal_overlap <= 0.0:
            continue
        if keepout[3] <= center_y:
            top_limit = max(top_limit, keepout[3] + 0.4)
        elif keepout[1] >= center_y:
            bottom_limit = min(bottom_limit, keepout[1] - 0.4)
    if inline_style_flow:
        for obstacle in obstacles:
            horizontal_overlap = min(new_x1, obstacle[2]) - max(x0, obstacle[0])
            if horizontal_overlap <= 0.0:
                continue
            if obstacle[3] <= center_y:
                top_limit = max(top_limit, obstacle[3] + 0.4)
            elif obstacle[1] >= center_y:
                bottom_limit = min(bottom_limit, obstacle[1] - 0.4)

    if inline_style_flow:
        # Preserve the source first-line anchor and consume the free gap below
        # before shifting upward. This keeps the run-in prefix on its original
        # baseline while allowing the Chinese paragraph to retain body size.
        new_y0 = y0
        new_y1 = max(y1, y0 + desired_height)
    else:
        new_y0 = min(y0, center_y - desired_height / 2.0)
        new_y1 = max(y1, center_y + desired_height / 2.0)
    if new_y0 < top_limit:
        new_y1 += top_limit - new_y0
        new_y0 = top_limit
    if new_y1 > bottom_limit:
        new_y0 -= new_y1 - bottom_limit
        new_y1 = bottom_limit
    if new_x1 <= x0 or new_y0 < top_limit or new_y1 <= new_y0:
        return block
    return replace(block, bbox=(x0, new_y0, new_x1, new_y1))


def relax_caption_boxes(
    page: object,
    items: Sequence[Tuple[TextBlock, str]],
    *,
    obstacles: Sequence[BBox] = (),
) -> None:
    """Give translated captions a little extra vertical room when it is free."""
    if not items:
        return
    page_bottom = float(page.rect.height) - 18.0
    blocks = [block for block, _ in items]
    for block in blocks:
        if block.block_type != "caption":
            continue
        # Nowrap captions render a single line at their original anchor;
        # growing the box downward only recentres that line into whatever
        # sits below (a table's first row on MCF p16/p17).
        if block.nowrap:
            continue
        x0, y0, x1, y1 = block.bbox
        next_y = page_bottom
        for other in blocks:
            if other is block or other.page_index != block.page_index:
                continue
            ox0, oy0, ox1, _ = other.bbox
            if oy0 <= y1:
                continue
            overlap = min(x1, ox1) - max(x0, ox0)
            if overlap <= min(x1 - x0, ox1 - ox0) * 0.2:
                continue
            next_y = min(next_y, oy0 - 3.0)
        for ox0, oy0, ox1, _oy1 in obstacles:
            if oy0 <= y1:
                continue
            overlap = min(x1, ox1) - max(x0, ox0)
            if overlap <= min(x1 - x0, ox1 - ox0) * 0.2:
                continue
            next_y = min(next_y, oy0 - 3.0)
        relaxed_y1 = min(y1 + _CAPTION_EXTRA_HEIGHT, next_y, page_bottom)
        if relaxed_y1 > y1 + 2.0:
            if block.redact_bboxes is None:
                block.redact_bboxes = [block.bbox]
            block.bbox = (x0, y0, x1, relaxed_y1)


def _clear_table_caption_rules(
    page: object,
    items: Sequence[Tuple[TextBlock, str]],
    *,
    font_pack: FontPack,
    min_font_size: float,
    font_scale: float,
    margin: float,
    centered_flags: Sequence[bool],
) -> None:
    """Keep the final translated caption ink clear of the table's first rule."""
    horizontal_rules: List[Tuple[float, float, float]] = []
    for drawing in _page_drawings(page):
        rect = drawing.get("rect")
        if rect is None or float(rect.width) < 80.0 or float(rect.height) > 2.5:
            continue
        horizontal_rules.append((float(rect.y0), float(rect.x0), float(rect.x1)))
    if not horizontal_rules:
        return

    for (block, translated_text), centered in zip(items, centered_flags):
        plain = " ".join(strip_sentinels(block.text).split()).strip()
        if block.block_type != "caption" or not re.match(r"^Table\s+\w+\s*[:.]", plain, re.I):
            continue
        x0, y0, x1, y1 = block.bbox
        rendered_bottom = _caption_rendered_bottom(
            block,
            translated_text,
            font_pack=font_pack,
            font_size=requested_translation_font_size(
                block,
                min_font_size,
                font_scale,
            ),
            min_font_size=min_font_size,
            margin=margin,
            centered=centered,
        )
        candidates = [
            rule_y
            for rule_y, rule_x0, rule_x1 in horizontal_rules
            if y0 < rule_y <= max(y1, rendered_bottom) + 8.0
            and min(x1, rule_x1) - max(x0, rule_x0) >= min(x1 - x0, rule_x1 - rule_x0) * 0.45
        ]
        if not candidates:
            continue
        first_rule_y = min(candidates)
        # The redact fill rect (expanded by `margin`) paints background over
        # the table's top rule when the caption glyph box crosses it, leaving
        # stub rules beside the caption. Stop the caption redaction above the
        # rule: character removal is intersection-based, so every source
        # caption glyph still intersects the clipped rect, while the fill no
        # longer covers the rule.
        redacts = list(block.redact_bboxes or [(x0, y0, x1, y1)])
        safe_redact_y1 = first_rule_y - margin - 0.9
        if safe_redact_y1 > y0 + 2.0:
            block.redact_bboxes = [
                (rx0, ry0, rx1, min(ry1, safe_redact_y1))
                for rx0, ry0, rx1, ry1 in redacts
            ]
        required_gap = 3.1
        current_gap = first_rule_y - rendered_bottom
        if current_gap >= required_gap:
            continue
        shift = required_gap - current_gap
        block.bbox = (x0, max(0.0, y0 - shift), x1, max(0.0, y1 - shift))


def _caption_rendered_bottom(
    block: TextBlock,
    text: str,
    *,
    font_pack: FontPack,
    font_size: float,
    min_font_size: float,
    margin: float,
    centered: bool,
) -> float:
    """Predict caption ink bottom using the same tokens and fitting as rendering."""
    import fitz

    rect = shrink_rect(fitz.Rect(block.bbox), margin)
    fonts = font_pack.fonts_for(block.bold)
    bold_fonts = font_pack.fonts_for(True)
    min_size = effective_min_font_size(block, min_font_size)
    render_text = _translation_text_for_render(text)
    tokens = _tokenize_translation_with_formula_clips(text, block)
    apply_inline_bold(tokens, block, render_text)
    if not tokens:
        return float(rect.y0)

    if block.nowrap:
        size = font_size
        for token in tokens:
            token.width = token_width(token, fonts, size, bold_fonts)
        width = sum(token.width for token in tokens)
        if width > rect.width and width > 0:
            size = max(min_size * 0.8, size * rect.width / width)
        ascent, layout_descent = _line_vertical_metrics(
            tokens,
            size,
            fonts,
            bold_fonts,
        )
        ink_descent = _line_font_descent(tokens, size, fonts, bold_fonts)
        baseline = rect.y0 + (rect.height + ascent - layout_descent) / 2.0
        if ascent + layout_descent <= rect.height:
            baseline = max(rect.y0 + ascent, baseline)
            baseline = min(rect.y1 - layout_descent, baseline)
        return float(baseline + ink_descent)

    chosen: Optional[Tuple[float, float, List[List[_Token]]]] = None
    size = font_size
    while size >= min_size - 1e-6:
        lines = break_lines(
            tokens,
            fonts,
            size,
            rect.width,
            prefer_space_break=centered,
            bold_fonts=bold_fonts,
        )
        for leading in leading_options(block):
            height = line_block_height(
                lines,
                size,
                leading,
                fonts,
                bold_fonts,
            )
            available = rect.height
            if block.block_type == "caption" and len(lines) == 1:
                # Mirror insert_translated_text's single-line caption gate so
                # the rule-clearance shift sees the size that actually
                # renders.
                ascent, descent = _line_vertical_metrics(
                    lines[0], size, fonts, bold_fonts
                )
                height = min(ascent, size * 0.88) + min(descent, size * 0.14)
                available = max(rect.height, block.bbox[3] - block.bbox[1] - 1.0)
            if height <= available:
                chosen = (size, leading, lines)
                break
        if chosen is not None:
            break
        size -= 0.25
    if chosen is None:
        chosen = choose_compressed_layout(
            tokens,
            fonts,
            rect.width,
            rect.height,
            min_size,
            centered,
            bold_fonts,
        )

    size, leading, lines = chosen
    if len(lines) == 1:
        # Report the glyph-box bottom: the caption clearance contract is
        # measured against rendered span boxes, not bare ink.
        ascent, box_descent = _line_vertical_metrics(
            lines[0],
            size,
            fonts,
            bold_fonts,
        )
        descent = _line_font_descent(lines[0], size, fonts, bold_fonts)
        return float(rect.y0 + ascent + max(descent, box_descent))
    baselines = _line_baselines(
        lines,
        size,
        leading,
        float(rect.y0),
        fonts,
        bold_fonts,
    )
    return float(
        baselines[-1]
        + _line_font_descent(lines[-1], size, fonts, bold_fonts)
    )


def _line_font_descent(
    line: Sequence[_Token],
    size: float,
    fonts: Sequence[Tuple[object, str]],
    bold_fonts: Sequence[Tuple[object, str]],
) -> float:
    """Return the largest PDF font descent used by a rendered token line."""
    descent = _line_vertical_metrics(line, size, fonts, bold_fonts)[1]
    for token in line:
        if token.kind in {"space", "formula"}:
            continue
        active_fonts = token_fonts(token, fonts, bold_fonts)
        for char in token.text:
            selected = next(
                (
                    font
                    for font, _ in _fonts_for_char(char, active_fonts)
                    if font.has_glyph(ord(char))
                ),
                active_fonts[0][0],
            )
            descent = max(descent, abs(float(selected.descender)) * size)
    return descent


# --- CJK typesetting engine ---------------------------------------------------


@dataclass
class _Token:
    kind: str  # "cjk" | "word" | "space" | "formula"
    text: str
    width: float = 0.0
    bold: bool = False
    source_bbox: Optional[BBox] = None
    source_atom_bboxes: Tuple[BBox, ...] = ()
    source_exclusion_bboxes: Tuple[BBox, ...] = ()
    source_page: int = 0
    source_size: float = 0.0
    source_baseline_ratio: float = 0.82


def is_cjk_char(char: str) -> bool:
    code = ord(char)
    if 0x2E80 <= code <= 0x9FFF or 0xF900 <= code <= 0xFAFF:
        return True
    if 0xFE30 <= code <= 0xFE4F or 0xFF00 <= code <= 0xFFEF:
        return True
    if 0x20000 <= code <= 0x2FA1F:
        return True
    return char in "…—–·‘’“”"


def tokenize_text(text: str) -> List[_Token]:
    tokens: List[_Token] = []
    word: List[str] = []

    def flush_word() -> None:
        if word:
            tokens.append(_Token("word", "".join(word)))
            word.clear()

    for char in text:
        if char.isspace():
            flush_word()
            if tokens and tokens[-1].kind == "space":
                continue
            tokens.append(_Token("space", " "))
        elif is_cjk_char(char):
            flush_word()
            tokens.append(_Token("cjk", char))
        else:
            word.append(char)
    flush_word()
    while tokens and tokens[0].kind == "space":
        tokens.pop(0)
    while tokens and tokens[-1].kind == "space":
        tokens.pop()
    return tokens


def _formula_source_indexes_in_translation_order(
    text: str,
    block: TextBlock,
) -> Tuple[int, ...]:
    """Map reordered translated formula markers back to their source runs."""
    count = len(block.formula_anchors)
    positional = tuple(range(count))
    translated_markers = _formula_markers_for_anchor_count(text, count)
    source_markers = _formula_markers_for_anchor_count(block.text, count)
    if len(translated_markers) != count or len(source_markers) != count:
        return positional

    def key(marker: re.Match[str]) -> str:
        return re.sub(r"\s+", "", strip_sentinels(marker.group(0)))

    source_indexes: Dict[str, List[int]] = {}
    for index, marker in enumerate(source_markers):
        source_indexes.setdefault(key(marker), []).append(index)

    reordered: List[int] = []
    for marker in translated_markers:
        candidates = source_indexes.get(key(marker))
        if not candidates:
            return positional
        reordered.append(candidates.pop(0))
    if len(set(reordered)) != count:
        return positional
    return tuple(reordered)


def _formula_markers_for_anchor_count(
    text: str,
    anchor_count: int,
) -> List[re.Match[str]]:
    """Keep formula anchors stable when translation normalizes whitespace.

    Extraction intentionally combines adjacent sentinel groups into one
    translation placeholder. Separate source placeholders can nevertheless
    become adjacent after a translator changes two spaces to one. In that
    case the run regex loses the placeholder boundary, while the individual
    sentinel groups still provide an exact one-to-one mapping.
    """
    run_markers = list(SENTINEL_RUN_RE.finditer(text))
    if len(run_markers) == anchor_count:
        return run_markers
    group_markers = list(SENTINEL_GROUP_RE.finditer(text))
    if len(group_markers) == anchor_count:
        return group_markers
    return run_markers


def _formula_source_baseline_ratio(block: TextBlock, source_bbox: BBox) -> float:
    """Estimate the source formula baseline inside its visible run bbox."""
    height = max(0.1, source_bbox[3] - source_bbox[1])
    center_y = (source_bbox[1] + source_bbox[3]) / 2.0
    candidates: List[Tuple[float, float, float]] = []
    for prose_bbox in block.source_prose_bboxes:
        overlap = min(source_bbox[3], prose_bbox[3]) - max(
            source_bbox[1], prose_bbox[1]
        )
        if overlap <= 0.0:
            continue
        baseline = prose_bbox[3] - block.font_size * 0.18
        if not (
            source_bbox[1] - block.font_size * 0.2
            <= baseline
            <= source_bbox[3] + block.font_size * 0.2
        ):
            continue
        baseline_ratio = (baseline - source_bbox[1]) / height
        if not 0.2 <= baseline_ratio <= 0.9:
            # A tiny bbox intersection with the preceding/following physical
            # row is not baseline evidence. Clamping that foreign baseline to
            # the formula edge makes an inline token reserve almost all of its
            # height as descent and unnecessarily shrinks the whole paragraph.
            continue
        candidates.append((overlap, -abs(baseline - center_y), baseline))
    if not candidates:
        return 0.82
    baseline = max(candidates)[2]
    return max(0.2, min(0.9, (baseline - source_bbox[1]) / height))


def _tokenize_translation_with_formula_clips(text: str, block: TextBlock) -> List[_Token]:
    markers = _formula_markers_for_anchor_count(text, len(block.formula_anchors))
    if not markers or len(markers) != len(block.formula_anchors):
        return tokenize_text(clean_translation(strip_sentinels(text)))

    tokens: List[_Token] = []
    atom_groups = block.source_math_atom_groups
    if len(atom_groups) != len(block.formula_anchors):
        atom_groups = _group_math_atoms_by_run(
            block.formula_anchors,
            block.source_math_atom_bboxes,
        )
    source_indexes = _formula_source_indexes_in_translation_order(text, block)
    formula_anchors = tuple(block.formula_anchors[index] for index in source_indexes)
    atom_groups = tuple(atom_groups[index] for index in source_indexes)
    related_atom_groups = [
        group for group in block.keepout_formula_atom_groups if group
    ]
    for keepout in block.keepout_bboxes or ():
        keepout_area = max(0.1, bbox_area(keepout))
        if any(
            bbox_intersection_area(keepout, union_bbox(group)) / keepout_area
            >= 0.8
            for group in related_atom_groups
        ):
            continue
        related_atom_groups.append((keepout,))
    if related_atom_groups:
        atom_groups = tuple(
            tuple(
                dict.fromkeys(
                    [
                        *group,
                        *(
                            atom
                            for related_group in related_atom_groups
                            if bbox_intersection_area(
                                union_bbox(related_group),
                                anchor,
                            )
                            / max(0.1, bbox_area(union_bbox(related_group)))
                            >= 0.8
                            for atom in related_group
                        ),
                    ]
                )
            )
            for anchor, group in zip(formula_anchors, atom_groups)
        )

    def append_segment(segment: str) -> None:
        if not segment:
            return
        leading_space = segment[:1].isspace()
        trailing_space = segment[-1:].isspace()
        if leading_space and tokens and tokens[-1].kind != "space":
            tokens.append(_Token("space", " "))
        tokens.extend(tokenize_text(segment))
        if trailing_space and tokens and tokens[-1].kind != "space":
            tokens.append(_Token("space", " "))

    marker_groups: List[Tuple[int, int]] = []
    group_start = 0
    for index in range(1, len(markers)):
        separator = text[markers[index - 1].end() : markers[index].start()]
        if _formula_markers_form_atom(
            formula_anchors[index - 1],
            formula_anchors[index],
            separator,
        ):
            continue
        marker_groups.append((group_start, index))
        group_start = index
    marker_groups.append((group_start, len(markers)))

    cursor = 0
    for start, stop in marker_groups:
        first_marker = markers[start]
        last_marker = markers[stop - 1]
        append_segment(text[cursor : first_marker.start()])
        source_bbox = union_bbox(formula_anchors[start:stop])
        formula_text = re.sub(
            r"\s+",
            " ",
            strip_sentinels(text[first_marker.start() : last_marker.end()]),
        ).strip()
        semantic_formula = _semantic_inline_formula_text(formula_text)
        tokens.append(
            _Token(
                "formula",
                semantic_formula or formula_text,
                source_bbox=source_bbox,
                source_atom_bboxes=tuple(
                    atom
                    for group in atom_groups[start:stop]
                    for atom in group
                ),
                source_exclusion_bboxes=block.source_prose_bboxes,
                source_page=block.page_index,
                source_size=max(block.font_size, 1.0),
                source_baseline_ratio=_formula_source_baseline_ratio(
                    block,
                    source_bbox,
                ),
            )
        )
        cursor = last_marker.end()
    append_segment(text[cursor:])
    while tokens and tokens[0].kind == "space":
        tokens.pop(0)
    while tokens and tokens[-1].kind == "space":
        tokens.pop()
    return tokens


def _semantic_inline_formula_text(text: str) -> Optional[str]:
    """Recover simple dimension formulas from custom TeX font encodings.

    Some TeX subsets expose ``in`` and multiplication glyphs as arrows in
    extracted text. Reusing their rectangular source clips also captures ink
    from adjacent lines when the font bboxes overlap. Dimension declarations
    have an unambiguous shape, so render them as selectable math text instead.
    Complex formulas continue through the original vector-stamp path.
    """
    compact = "".join(text.split())
    if re.fullmatch(r"\d{1,3}↑\d{1,3}", compact):
        return compact.replace("↑", "×")

    empirical_measure = re.fullmatch(
        r"(?P<measure>[αβ])=P\^\{(?P<count>[A-Za-z])\}"
        r"_\{(?P<index>[A-Za-z])\}_\{=1\}"
        r"(?P<tail>.+)",
        compact,
    )
    if empirical_measure:
        index = empirical_measure.group("index")
        tail = empirical_measure.group("tail")
        tail_match = re.fullmatch(
            rf"(?P<weight>[A-Za-z])(?:_\{{{index}\}}|{index})"
            rf"δ(?:_\{{v\}}|v)_\{{{index}\}}",
            tail,
        )
        if not tail_match:
            return None
        return (
            f"{empirical_measure.group('measure')}=∑"
            f"^{{{empirical_measure.group('count')}}}_{{{index}=1}}"
            f"{tail_match.group('weight')}_{{{index}}}δ_{{v}}_{{{index}}}"
        )

    match = re.fullmatch(
        r"(?P<prefix>[^{}→]{0,12})→R(?P<dimensions>(?:\^\{[^{}]+\}){3,11})",
        compact,
    )
    if not match:
        return None
    dimensions = re.findall(r"\^\{([^{}]+)\}", match.group("dimensions"))
    if len(dimensions) < 3:
        return None
    trailing_subscript: Optional[str] = None
    dimension_parts = dimensions
    if len(dimensions) % 2 == 0:
        trailing_subscript = dimensions[-1]
        dimension_parts = dimensions[:-1]
    if any(part != "→" for part in dimension_parts[1::2]):
        return None
    axes = dimension_parts[::2]
    if not all(re.fullmatch(r"[A-Za-z0-9]{1,4}", axis) for axis in axes) or (
        trailing_subscript is not None
        and not re.fullmatch(r"[A-Za-z0-9]{1,4}", trailing_subscript)
    ):
        return None
    rendered_axes = "×".join(axes)
    if trailing_subscript is not None:
        rendered_axes = f"{rendered_axes}_{{{trailing_subscript}}}"
    return f"{match.group('prefix')}∈R^{{{rendered_axes}}}"


def _formula_markers_form_atom(first: BBox, second: BBox, separator: str) -> bool:
    """Return whether adjacent markers are pieces of one inline formula."""
    compact_separator = "".join(separator.split())
    if compact_separator and not re.fullmatch(r"[¯‾]+", compact_separator):
        return False
    first_height = max(1.0, first[3] - first[1])
    second_height = max(1.0, second[3] - second[1])
    reference = max(first_height, second_height)
    horizontal_gap = second[0] - first[2]
    vertical_overlap = min(first[3], second[3]) - max(first[1], second[1])
    vertical_gap = max(first[1] - second[3], second[1] - first[3], 0.0)
    first_center_x = (first[0] + first[2]) / 2.0
    second_center_x = (second[0] + second[2]) / 2.0
    first_width = max(1.0, first[2] - first[0])
    second_width = max(1.0, second[2] - second[0])
    horizontal_overlap = min(first[2], second[2]) - max(first[0], second[0])
    # TeX can emit a complete fraction base and its numerator / denominator
    # as separate text spans whose hulls strongly overlap. They are one
    # visual atom even when their centres are far apart because one hull
    # contains most of the narrower span (DDPM's reverse-variance fraction).
    if (
        horizontal_overlap
        >= min(first_width, second_width) * 0.55
        and vertical_overlap >= min(first_height, second_height) * 0.45
    ):
        return True
    radical_overbar_stack = bool(
        horizontal_overlap >= min(first_width, second_width) * 0.65
        and vertical_gap <= max(1.5, reference * 0.15)
        and first[0] <= second[0] + 1.0
        and first[2] >= second[2] - 1.0
    )
    if radical_overbar_stack:
        return True
    advancing_radical_radicand = bool(
        horizontal_overlap >= min(first_width, second_width) * 0.45
        and vertical_gap <= max(1.5, reference * 0.15)
        and first[0] + 1.0 < second[0]
        and first[2] + 1.0 < second[2]
        and first[1] < second[1]
        and first[3] < second[3]
        and 0.0 < second_center_x - first_center_x <= max(12.0, reference * 1.1)
    )
    if advancing_radical_radicand:
        return True
    stacked_script = bool(
        vertical_gap <= 1.5
        and abs(first_center_x - second_center_x) <= max(8.0, reference * 0.8)
        and min(first_height, second_height) <= reference * 0.72
    )
    if stacked_script:
        return True
    if horizontal_gap < -max(2.0, reference * 0.25):
        return (
            horizontal_gap >= -max(2.0, min(first_width, second_width) * 0.85)
            and vertical_overlap
            >= min(first_height, second_height) * 0.45
        )
    return (
        -max(2.0, reference * 0.25)
        <= horizontal_gap
        <= max(4.0, reference * 0.45)
        and vertical_overlap >= -1.0
    )


def _bold_prefix_limit(text: str) -> int:
    stripped = text.lstrip()
    offset = len(text) - len(stripped)
    if not stripped:
        return 0
    body_cue = re.search(
        r"(?:对于(?:式|方程|问题)\s*[\d（(]|"
        r"(?:我们|本文)(?:首先|提出|使用|采用|将|通过)|"
        r"在图\s*[0-9一二三四五六七八九十]|"
        r"(?:具体而言|首先|其次|其中)[，,])",
        stripped,
    )
    if body_cue is not None and 2 <= body_cue.start() <= 64:
        prefix = stripped[: body_cue.start()].rstrip()
        if prefix:
            return offset + len(prefix)
    colon_positions = [pos for pos in (stripped.find(":"), stripped.find("：")) if pos >= 0]
    if colon_positions:
        first_colon = min(colon_positions)
        if first_colon <= 18:
            sentence_after_colon = stripped.find("。", first_colon + 1)
            if 0 <= sentence_after_colon <= 64:
                return offset + sentence_after_colon + 1
            return offset + first_colon + 1
    sentence_marks = [pos for pos in (stripped.find("。"), stripped.find(".")) if pos >= 0]
    if sentence_marks:
        first_mark = min(sentence_marks)
        if first_mark <= 64:
            return offset + first_mark + 1
    return min(len(text), offset + 18)


def _normalize_bold_match_text(text: str) -> str:
    return re.sub(r"^[\s\"'“”‘’([{（【]+|[\s\"'“”‘’)\]}）】,.;:：。]+$", "", text).lower()


def apply_inline_bold(
    tokens: List[_Token],
    block: TextBlock,
    text: str,
    *,
    char_offset: int = 0,
) -> None:
    if block.bold:
        for token in tokens:
            token.bold = True
        return

    char_index = 0
    prefix_limit = (
        block.translated_bold_prefix_chars
        if block.translated_bold_prefix_chars > 0
        else _bold_prefix_limit(text) if block.bold_prefix else 0
    )
    terms = {_normalize_bold_match_text(term) for term in block.bold_terms}
    terms = {term for term in terms if term}
    for token in tokens:
        start = char_offset + char_index
        char_index += len(token.text)
        if token.kind == "space":
            continue
        normalized = _normalize_bold_match_text(token.text)
        in_prefix = prefix_limit > 0 and start < prefix_limit
        if in_prefix or normalized in terms or any(term in normalized for term in terms):
            token.bold = True


# CJK faces draw these math delimiters slanted (⫽-like); Latin fallback fonts
# keep them upright, matching the source math typography.
_UPRIGHT_MATH_CHARS = frozenset((0x2016, 0x2225))  # ‖ ∥


def _fonts_for_char(char: str, fonts: Sequence[Tuple[object, str]]) -> Sequence[Tuple[object, str]]:
    if ord(char) in _UPRIGHT_MATH_CHARS:
        preferred = [item for item in fonts if item[1] == "zhfall"]
        if preferred:
            return preferred + [item for item in fonts if item[1] != "zhfall"]
    return fonts


def char_width(char: str, fonts: Sequence[Tuple[object, str]], size: float) -> float:
    for font, _ in _fonts_for_char(char, fonts):
        if font.has_glyph(ord(char)):
            return font.glyph_advance(ord(char)) * size
    return fonts[0][0].glyph_advance(ord(char)) * size


def token_fonts(
    token: _Token,
    fonts: Sequence[Tuple[object, str]],
    bold_fonts: Optional[Sequence[Tuple[object, str]]] = None,
) -> Sequence[Tuple[object, str]]:
    if token.bold and bold_fonts is not None:
        return bold_fonts
    return fonts


def token_width(
    token: _Token,
    fonts: Sequence[Tuple[object, str]],
    size: float,
    bold_fonts: Optional[Sequence[Tuple[object, str]]] = None,
) -> float:
    formula_guard = size * _INLINE_FORMULA_GUARD_EM if token.kind == "formula" else 0.0
    if token.kind == "formula" and token.source_bbox is not None:
        source_width = max(0.1, token.source_bbox[2] - token.source_bbox[0])
        return (
            source_width
            * _formula_clip_scale(token.source_bbox, size, token.source_size)
            + formula_guard * 2.0
        )
    active_fonts = token_fonts(token, fonts, bold_fonts)
    width = 0.0
    for role, text in iter_scripted_text(token.text):
        segment_size, _ = script_segment_metrics(role, size, 0.0)
        width += sum(char_width(char, active_fonts, segment_size) for char in text)
    return width + formula_guard * 2.0


_INLINE_FORMULA_GUARD_EM = 0.32
# Ordinary TeX inline math with a superscript/subscript commonly reports a
# 1.8-2.0em span bbox even though it still belongs on one text row.  A 1.6em
# cap made those formulas visibly smaller than the surrounding translated
# prose.  Keep source-relative scale through 2em; only actual fraction/radical
# towers taller than that are constrained.
_FORMULA_CLIP_MAX_HEIGHT_EM = 2.0
_FORMULA_CLIP_FOREIGN_GAP = 0.2


def _formula_clip_scale(source_bbox: BBox, size: float, source_size: float) -> float:
    """Scale a source formula consistently for width measurement and drawing."""
    source_height = max(0.1, source_bbox[3] - source_bbox[1])
    nominal = size / max(source_size, 1.0)
    height_limited = size * _FORMULA_CLIP_MAX_HEIGHT_EM / source_height
    return min(nominal, height_limited)


SCRIPT_NOTATION_RE = re.compile(r"[\^_]\{[^{}]+\}")


def has_script_notation(text: str) -> bool:
    return bool(SCRIPT_NOTATION_RE.search(text))


def iter_scripted_text(text: str) -> Iterator[Tuple[str, str]]:
    """Yield normal/super/sub text spans from ASCII math script notation.

    Translation placeholders keep inline math renderable as ``C^{v}_{t}``.
    At drawing time we turn that notation back into raised/lowered smaller
    text so formulas remain visually formula-like without relying on rare
    Unicode superscript/subscript glyphs.
    """
    normal: List[str] = []
    index = 0

    def flush_normal() -> Iterator[Tuple[str, str]]:
        if normal:
            yield ("normal", "".join(normal))
            normal.clear()

    while index < len(text):
        marker = text[index]
        if marker in {"^", "_"} and index + 1 < len(text) and text[index + 1] == "{":
            close = text.find("}", index + 2)
            if close > index + 2:
                yield from flush_normal()
                role = "super" if marker == "^" else "sub"
                yield (role, text[index + 2 : close])
                index = close + 1
                continue
        normal.append(marker)
        index += 1
    yield from flush_normal()


def script_segment_metrics(role: str, size: float, baseline: float) -> Tuple[float, float]:
    if role == "super":
        return size * 0.72, baseline - size * 0.36
    if role == "sub":
        return size * 0.72, baseline + size * 0.22
    return size, baseline


def split_long_word(
    token: _Token,
    fonts: Sequence[Tuple[object, str]],
    size: float,
    max_width: float,
    bold_fonts: Optional[Sequence[Tuple[object, str]]] = None,
) -> List[_Token]:
    """Hard-split a word wider than the line (URLs, hashes)."""
    pieces: List[_Token] = []
    chunk: List[str] = []
    width = 0.0
    for char in token.text:
        advance = char_width(char, token_fonts(token, fonts, bold_fonts), size)
        if chunk and width + advance > max_width:
            pieces.append(_Token("word", "".join(chunk), bold=token.bold))
            chunk = [char]
            width = advance
        else:
            chunk.append(char)
            width += advance
    if chunk:
        pieces.append(_Token("word", "".join(chunk), bold=token.bold))
    return pieces


def break_lines(
    tokens: List[_Token],
    fonts: Sequence[Tuple[object, str]],
    size: float,
    max_width: float,
    prefer_space_break: bool = False,
    bold_fonts: Optional[Sequence[Tuple[object, str]]] = None,
    line_widths: Optional[Sequence[float]] = None,
) -> List[List[_Token]]:
    """Greedy line breaking with kinsoku adjustment.

    ``line_widths`` optionally narrows individual lines (keepout-aware flow
    around preserved formula glyphs); lines beyond the list use ``max_width``.
    """
    for token in tokens:
        token.width = token_width(token, fonts, size, bold_fonts)

    def width_for(line_index: int) -> float:
        if line_widths and line_index < len(line_widths):
            return line_widths[line_index]
        return max_width

    split_width = min(line_widths) if line_widths else max_width
    expanded: List[_Token] = []
    for token in tokens:
        if token.kind == "word" and token.width > split_width:
            expanded.extend(split_long_word(token, fonts, size, split_width, bold_fonts))
        else:
            expanded.append(token)
    for token in expanded:
        token.width = token_width(token, fonts, size, bold_fonts)

    lines: List[List[_Token]] = []
    current: List[_Token] = []
    current_width = 0.0

    def open_line(token: _Token) -> None:
        nonlocal current, current_width
        lines.append(current)
        current = [] if token.kind == "space" else [token]
        current_width = 0.0 if token.kind == "space" else token.width

    for token in expanded:
        limit = width_for(len(lines))
        if not current and token.kind == "space":
            continue
        if current_width + token.width <= limit + 0.5 or not current:
            current.append(token)
            current_width += token.width
            continue
        # Token overflows: it starts the next line, with kinsoku fixes.
        if token.kind == "cjk" and token.text in NO_LINE_START and len(current) >= 2:
            pulled = current.pop()
            current_width -= pulled.width
            while current and current[-1].kind == "space":
                current_width -= current[-1].width
                current.pop()
            lines.append(current)
            current = [pulled, token]
            current_width = pulled.width + token.width
            continue
        while current and current[-1].kind == "space":
            current_width -= current[-1].width
            current.pop()
        if current and current[-1].kind == "cjk" and current[-1].text in NO_LINE_END:
            opener = current.pop()
            lines.append(current)
            current = [opener, token]
            current_width = opener.width + token.width
            continue
        if prefer_space_break:
            space_index = max(
                (i for i, item in enumerate(current) if item.kind == "space"),
                default=None,
            )
            if space_index is not None and space_index >= 1:
                width_before = sum(item.width for item in current[:space_index])
                if width_before >= 0.45 * limit:
                    moved = current[space_index + 1 :]
                    lines.append(current[:space_index])
                    current = moved + [token]
                    current_width = sum(item.width for item in current)
                    continue
        open_line(token)
    if current:
        lines.append(current)
    return [line for line in lines if line]


def balance_centered_title_lines(
    lines: Sequence[Sequence[_Token]],
    max_width: float,
) -> List[List[_Token]]:
    """Balance a centered title without changing its line count or tokens."""
    balanced = [list(line) for line in lines]
    if len(balanced) < 2:
        return balanced

    def trimmed(tokens: Sequence[_Token]) -> List[_Token]:
        start = 0
        end = len(tokens)
        while start < end and tokens[start].kind == "space":
            start += 1
        while end > start and tokens[end - 1].kind == "space":
            end -= 1
        return list(tokens[start:end])

    def natural_width(tokens: Sequence[_Token]) -> float:
        return sum(token.width for token in tokens)

    for index in range(len(balanced) - 1, 0, -1):
        previous = trimmed(balanced[index - 1])
        current = trimmed(balanced[index])
        combined = [*previous, *current]
        if len(combined) < 2:
            continue
        original_delta = abs(natural_width(previous) - natural_width(current))
        best: Optional[Tuple[float, List[_Token], List[_Token]]] = None
        for split_at in range(1, len(combined)):
            left = trimmed(combined[:split_at])
            right = trimmed(combined[split_at:])
            if not left or not right:
                continue
            if left[-1].kind == "cjk" and left[-1].text in NO_LINE_END:
                continue
            if right[0].kind == "cjk" and right[0].text in NO_LINE_START:
                continue
            left_width = natural_width(left)
            right_width = natural_width(right)
            if left_width > max_width + 0.5 or right_width > max_width + 0.5:
                continue
            candidate = (abs(left_width - right_width), left, right)
            if best is None or candidate[0] < best[0]:
                best = candidate
        if best is not None and best[0] + 0.5 < original_delta:
            balanced[index - 1] = best[1]
            balanced[index] = best[2]
    return balanced


def stretchable_gaps(line: Sequence[_Token]) -> List[int]:
    """Indices i such that the gap AFTER token i can stretch for justification."""
    gaps: List[int] = []
    for index in range(len(line) - 1):
        left, right = line[index], line[index + 1]
        if left.kind == "space" or right.kind == "space":
            gaps.append(index)
        elif left.kind == "cjk" or right.kind == "cjk":
            gaps.append(index)
    return gaps


def effective_min_font_size(block: TextBlock, min_font_size: float) -> float:
    if block.block_type == "caption":
        return min(min_font_size, _CAPTION_MIN_FONT_SIZE)
    return min_font_size


def leading_options(block: TextBlock) -> Tuple[float, ...]:
    if block.block_type == "caption":
        return (1.18, 1.08, _CAPTION_TIGHT_LEADING)
    return (DEFAULT_LEADING, 1.26, 1.15)


def choose_compressed_layout(
    tokens: List[_Token],
    fonts: Sequence[Tuple[object, str]],
    width: float,
    height: float,
    min_size: float,
    centered: bool,
    bold_fonts: Optional[Sequence[Tuple[object, str]]] = None,
) -> Tuple[float, float, List[List[_Token]]]:
    """Last-resort layout that still keeps text inside its rectangle."""
    size = min_size
    best: Tuple[float, float, List[List[_Token]]] | None = None
    while size >= _ABSOLUTE_MIN_FONT_SIZE - 1e-6:
        lines = break_lines(
            tokens, fonts, size, width, prefer_space_break=centered, bold_fonts=bold_fonts
        )
        for leading in (1.08, 1.0, 0.94):
            best = (size, leading, lines)
            if line_block_height(
                lines,
                size,
                leading,
                fonts,
                bold_fonts,
            ) <= height:
                return best
        size -= 0.2
    assert best is not None
    return best


_KEEPOUT_PAD = 1.2
_KEEPOUT_MIN_SEGMENT = 40.0
_FIXED_MATH_MIN_FONT_SCALE = 0.88


def _uses_fixed_source_math(block: TextBlock) -> bool:
    """Keep formulas fixed for academic statements with structural math rows."""
    if block.flow_inline_math:
        return False
    marker_count = len(SENTINEL_RUN_RE.findall(block.text))
    if (
        marker_count <= 0
        or marker_count != len(block.formula_anchors)
        or not block.source_line_bboxes
    ):
        return False
    plain = " ".join(strip_sentinels(block.text).split()).strip()
    academic_statement = bool(
        re.match(
            r"^(?:Theorem|Lemma|Proposition|Corollary|Definition|Assumption)\s+[A-Z0-9]",
            plain,
            re.I,
        )
    )
    return academic_statement


def _block_is_short_derivation_explanation(block: TextBlock) -> bool:
    if not block.no_merge or not block.source_math_bboxes:
        return False
    outside = " ".join(SENTINEL_RUN_RE.sub(" ", block.text).split())
    return bool(
        re.match(
            r"^(?:Thus\s+we\s+can\s+get|Knowing\b)",
            outside,
            re.IGNORECASE,
        )
        and re.search(r"\b(?:get|obtain|derive)\b", outside, re.IGNORECASE)
    )


def _unresolved_formula_keepouts(block: TextBlock) -> List[BBox]:
    """Keepouts not already represented by a source-math anchor."""

    def covered_area(target: BBox, covers: Sequence[BBox]) -> float:
        clipped = [
            intersection
            for cover in dict.fromkeys(covers)
            for intersection in [_bbox_intersection_rect(target, cover)]
            if intersection is not None
        ]
        y_edges = sorted({edge for rect in clipped for edge in (rect[1], rect[3])})
        area = 0.0
        for y0, y1 in zip(y_edges, y_edges[1:]):
            if y1 <= y0:
                continue
            intervals = sorted(
                (rect[0], rect[2])
                for rect in clipped
                if rect[1] < y1 and rect[3] > y0
            )
            if not intervals:
                continue
            start, end = intervals[0]
            width = 0.0
            for next_start, next_end in intervals[1:]:
                if next_start <= end:
                    end = max(end, next_end)
                else:
                    width += max(0.0, end - start)
                    start, end = next_start, next_end
            width += max(0.0, end - start)
            area += width * (y1 - y0)
        return area

    unresolved: List[BBox] = []
    for keepout in dict.fromkeys(block.keepout_bboxes or []):
        keepout_center_y = (keepout[1] + keepout[3]) / 2.0
        if not block.bbox[1] <= keepout_center_y <= block.bbox[3]:
            vertical_overlap = min(block.bbox[3], keepout[3]) - max(
                block.bbox[1], keepout[1]
            )
            boundary_crossing_formula = bool(
                keepout[1] < block.bbox[3] < keepout[3]
                and keepout[3] - block.bbox[3]
                >= max(
                    2.0,
                    min(
                        block.bbox[3] - block.bbox[1],
                        keepout[3] - keepout[1],
                    )
                    * 0.20,
                )
                and vertical_overlap
                >= max(
                    2.0,
                    min(
                        block.bbox[3] - block.bbox[1],
                        keepout[3] - keepout[1],
                    )
                    * 0.25,
                )
            )
            compact_boundary_fragment = bool(
                keepout[3] - keepout[1] <= block.font_size * 1.25
                and keepout[3] >= block.bbox[1] - block.font_size * 0.2
                and keepout[1] <= block.bbox[3] + block.font_size * 0.2
            )
            if not compact_boundary_fragment and not boundary_crossing_formula:
                continue
        keepout_area = max(1.0, bbox_area(keepout))
        represented = any(
            bbox_intersection_area(keepout, source_bbox) / keepout_area >= threshold
            for source_bbox, threshold in (
                *((bbox, 0.7) for bbox in block.source_math_bboxes),
                *((bbox, 0.9) for bbox in block.source_line_bboxes),
            )
        )
        if (
            not represented
            and block.flow_inline_math
            and block.source_math_bboxes
            and covered_area(keepout, block.source_math_bboxes) / keepout_area >= 0.85
        ):
            represented = True
        if not represented:
            unresolved.append(keepout)
    return unresolved


def _bbox_is_source_math_redact(bbox: BBox, math_bboxes: Sequence[BBox]) -> bool:
    area = max(1.0, bbox_area(bbox))
    return any(
        bbox_intersection_area(bbox, math_bbox) / area >= 0.72
        for math_bbox in math_bboxes
    )


def _split_mixed_redact_around_fixed_math(
    bbox: BBox,
    math_bboxes: Sequence[BBox],
    margin: float,
) -> List[BBox]:
    """Carve fixed inline formula runs out of a broad mixed-line redaction."""
    pieces = [bbox]
    padding = max(0.2, margin + 0.1)
    for math_bbox in math_bboxes:
        next_pieces: List[BBox] = []
        for piece in pieces:
            overlap_y = min(piece[3], math_bbox[3]) - max(piece[1], math_bbox[1])
            min_height = min(piece[3] - piece[1], math_bbox[3] - math_bbox[1])
            expanded_overlap_x = min(
                piece[2] + padding,
                math_bbox[2],
            ) - max(
                piece[0] - padding,
                math_bbox[0],
            )
            if (
                expanded_overlap_x <= 0.0
                or overlap_y < max(0.5, min_height * 0.55)
            ):
                next_pieces.append(piece)
                continue
            left = (piece[0], piece[1], math_bbox[0] - padding, piece[3])
            right = (math_bbox[2] + padding, piece[1], piece[2], piece[3])
            next_pieces.extend(
                candidate
                for candidate in (left, right)
                if candidate[2] - candidate[0] >= 0.5
            )
        pieces = next_pieces
    return pieces


def _block_keepouts(block: TextBlock, rect: object) -> List[BBox]:
    rect_bbox = (rect.x0, rect.y0, rect.x1, rect.y1)
    keepouts = _unresolved_formula_keepouts(block)
    if _uses_fixed_source_math(block):
        keepouts.extend(block.source_math_bboxes)
    return [
        bbox
        for bbox in dict.fromkeys(keepouts)
        if bboxes_intersect(bbox, rect_bbox)
    ]


def keepout_line_slots(
    rect: object,
    size: float,
    leading: float,
    ascent: float,
    keepouts: Sequence[BBox],
    *,
    descent: float = 0.24,
) -> List[Tuple[float, float, float]]:
    """Baseline slots ``(baseline, x0, x1)`` that flow around keepout bboxes.

    Bands blocked across most of their width are skipped entirely; bands with
    a usable free interval beside the keepout shrink to that interval, which
    mirrors how the source typesetting wraps prose around tall inline math.
    """
    slots: List[Tuple[float, float, float]] = []
    ascent_ratio = max(ascent, 0.82)
    descent_ratio = max(descent, 0.24)
    baseline = rect.y0 + size * ascent_ratio
    advance = max(
        size * leading,
        size * (ascent_ratio + descent_ratio + 0.06),
    )
    bottom_limit = rect.y1 - size * descent_ratio
    min_free = max(_KEEPOUT_MIN_SEGMENT, 0.25 * rect.width)
    guard = 0
    while baseline <= bottom_limit and guard < 400:
        guard += 1
        band_top = baseline - size * ascent_ratio
        band_bottom = baseline + size * descent_ratio
        blockers = [
            k
            for k in keepouts
            if k[1] - _KEEPOUT_PAD < band_bottom and k[3] + _KEEPOUT_PAD > band_top
        ]
        if not blockers:
            slots.append((baseline, rect.x0, rect.x1))
            baseline += advance
            continue
        # Free x intervals in this band after removing blocker spans.
        spans = sorted((k[0] - _KEEPOUT_PAD, k[2] + _KEEPOUT_PAD) for k in blockers)
        free: List[Tuple[float, float]] = []
        cursor = rect.x0
        for span_x0, span_x1 in spans:
            if span_x0 > cursor:
                free.append((cursor, min(span_x0, rect.x1)))
            cursor = max(cursor, span_x1)
        if cursor < rect.x1:
            free.append((cursor, rect.x1))
        usable = [interval for interval in free if interval[1] - interval[0] >= min_free]
        if usable:
            slots.extend((baseline, x0, x1) for x0, x1 in usable)
            baseline += advance
            continue
        # Whole band blocked: restart right below the lowest blocker.
        blockers_bottom = max(k[3] for k in blockers)
        baseline = blockers_bottom + _KEEPOUT_PAD + size * ascent_ratio
    return slots


def _formula_aware_slot_baselines(
    lines: Sequence[Sequence[_Token]],
    slots: Sequence[Tuple[float, float, float]],
    size: float,
    rect: object,
    keepouts: Sequence[BBox],
    fonts: Sequence[Tuple[object, str]],
    bold_fonts: Sequence[Tuple[object, str]],
) -> Optional[List[Tuple[float, float, float]]]:
    """Rebase keepout slots using the visible metrics of their assigned tokens."""
    if len(lines) > len(slots):
        return None
    assigned = list(zip(lines, slots[: len(lines)]))
    adjusted: List[Tuple[float, float, float]] = []
    previous_baseline: Optional[float] = None
    previous_descent = 0.0
    index = 0
    while index < len(assigned):
        source_baseline = assigned[index][1][0]
        group_end = index + 1
        while (
            group_end < len(assigned)
            and abs(assigned[group_end][1][0] - source_baseline) <= 0.5
        ):
            group_end += 1
        group = assigned[index:group_end]
        metrics = [
            _line_vertical_metrics(line, size, fonts, bold_fonts)
            for line, _slot in group
        ]
        ascent = max((item[0] for item in metrics), default=size * 0.82)
        descent = max((item[1] for item in metrics), default=size * 0.24)
        baseline = max(float(source_baseline), float(rect.y0) + ascent)
        if previous_baseline is not None:
            baseline = max(
                baseline,
                previous_baseline + previous_descent + ascent + size * 0.06,
            )
        if baseline + descent > float(rect.y1) + 0.1:
            return None
        band_top = baseline - ascent
        band_bottom = baseline + descent
        for _line, (_slot_baseline, slot_x0, slot_x1) in group:
            if any(
                keepout[1] - _KEEPOUT_PAD < band_bottom
                and keepout[3] + _KEEPOUT_PAD > band_top
                and min(slot_x1, keepout[2] + _KEEPOUT_PAD)
                - max(slot_x0, keepout[0] - _KEEPOUT_PAD)
                > 0.5
                for keepout in keepouts
            ):
                return None
            adjusted.append((baseline, slot_x0, slot_x1))
        previous_baseline = baseline
        previous_descent = descent
        index = group_end
    return adjusted


def _translation_text_for_render(text: str) -> str:
    """Remove markers whose original formula glyphs remain on the source page."""
    return clean_translation(SENTINEL_RUN_RE.sub(" ", text))


def _formula_anchored_layout(
    block: TextBlock,
    text: str,
    rect: object,
    fonts: Sequence[Tuple[object, str]],
    bold_fonts: Sequence[Tuple[object, str]],
    font_size: float,
    min_size: float,
    centered: bool,
) -> Optional[
    Tuple[
        float,
        bool,
        List[Tuple[List[List[_Token]], List[Tuple[float, float, float]]]],
    ]
]:
    """Lay translated prose into source-line slots around preserved formulas."""
    markers = list(SENTINEL_RUN_RE.finditer(text))
    if not markers or len(markers) != len(block.formula_anchors):
        return None
    segments: List[str] = []
    segment_offsets: List[int] = []
    cursor = 0
    for marker in markers:
        segment_offsets.append(cursor)
        segments.append(clean_translation(text[cursor : marker.start()]))
        cursor = marker.end()
    segment_offsets.append(cursor)
    segments.append(clean_translation(text[cursor:]))

    size = font_size
    absolute_min = min(min_size, _ABSOLUTE_MIN_FONT_SIZE)
    while size >= absolute_min - 1e-6:
        slots_by_segment = _formula_segment_slots(block, rect, size)
        if len(slots_by_segment) != len(segments):
            return None
        segment_layouts: List[
            Tuple[List[List[_Token]], List[Tuple[float, float, float]]]
        ] = []
        all_fit = True
        for segment, segment_offset, slots in zip(
            segments,
            segment_offsets,
            slots_by_segment,
        ):
            tokens = tokenize_text(segment)
            apply_inline_bold(
                tokens,
                block,
                segment,
                char_offset=segment_offset,
            )
            if not tokens:
                segment_layouts.append(([], slots))
                continue
            if not slots:
                all_fit = False
                break
            widths = [slot_x1 - slot_x0 for _, slot_x0, slot_x1 in slots]
            lines = break_lines(
                tokens,
                fonts,
                size,
                rect.width,
                prefer_space_break=centered,
                bold_fonts=bold_fonts,
                line_widths=widths,
            )
            if len(lines) > len(slots):
                all_fit = False
                break
            segment_layouts.append((lines, slots))
        if all_fit:
            return size, size >= min_size - 1e-6, segment_layouts
        size -= 0.2
    return None


def _formula_segment_slots(
    block: TextBlock,
    rect: object,
    size: float,
) -> List[List[Tuple[float, float, float]]]:
    line_bboxes = _coalesce_source_line_bboxes(block.source_line_bboxes)
    anchors = list(block.formula_anchors)
    if not line_bboxes or not anchors:
        return []

    anchor_line_indexes = [
        min(
            range(len(line_bboxes)),
            key=lambda index: _formula_line_distance(anchor, line_bboxes[index]),
        )
        for anchor in anchors
    ]
    indexed_anchors = sorted(
        enumerate(anchors),
        key=lambda item: (
            anchor_line_indexes[item[0]],
            item[1][0],
        ),
    )
    if [index for index, _ in indexed_anchors] != list(range(len(anchors))):
        return []

    slots_by_segment: List[List[Tuple[float, float, float]]] = [
        [] for _ in range(len(anchors) + 1)
    ]
    segment_index = 0
    anchors_by_line: Dict[int, List[BBox]] = {}
    for anchor_index, anchor in indexed_anchors:
        anchors_by_line.setdefault(anchor_line_indexes[anchor_index], []).append(anchor)

    for line_index, line_bbox in enumerate(line_bboxes):
        line_y0 = max(float(rect.y0), line_bbox[1])
        line_y1 = min(float(rect.y1), line_bbox[3])
        if line_y1 <= line_y0:
            segment_index += len(anchors_by_line.get(line_index, []))
            continue
        baseline = min(line_y1 - size * 0.05, line_y0 + size * 0.82)
        text_band_top = baseline - size * 0.82
        text_band_bottom = baseline + size * 0.24
        blockers = [
            bbox
            for bbox in (block.keepout_bboxes or [])
            if bbox_share_y_band(line_bbox, bbox)
        ]
        blockers.extend(
            anchor
            for anchor_index, anchor in enumerate(anchors)
            if anchor_line_indexes[anchor_index] != line_index
            and min(anchor[3], text_band_bottom)
            - max(anchor[1], text_band_top)
            >= max(
                0.5,
                min(
                    anchor[3] - anchor[1],
                    text_band_bottom - text_band_top,
                )
                * 0.15,
            )
        )
        cursor_x = float(rect.x0)
        for anchor in anchors_by_line.get(line_index, []):
            interval_end = min(float(rect.x1), anchor[0] - _KEEPOUT_PAD)
            slots_by_segment[segment_index].extend(
                _free_formula_intervals(
                    baseline,
                    cursor_x,
                    interval_end,
                    blockers,
                    size,
                )
            )
            segment_index += 1
            cursor_x = max(cursor_x, anchor[2] + _KEEPOUT_PAD)
        slots_by_segment[segment_index].extend(
            _free_formula_intervals(
                baseline,
                cursor_x,
                float(rect.x1),
                blockers,
                size,
            )
        )
    return slots_by_segment


def _coalesce_source_line_bboxes(bboxes: Sequence[BBox]) -> List[BBox]:
    lines: List[BBox] = []
    for bbox in sorted(bboxes, key=lambda item: ((item[1] + item[3]) / 2.0, item[0])):
        if lines and abs(
            (lines[-1][1] + lines[-1][3]) / 2.0
            - (bbox[1] + bbox[3]) / 2.0
        ) <= 2.0:
            lines[-1] = union_bbox([lines[-1], bbox])
        else:
            lines.append(bbox)
    return lines


def _formula_line_distance(anchor: BBox, line_bbox: BBox) -> float:
    vertical_overlap = min(anchor[3], line_bbox[3]) - max(anchor[1], line_bbox[1])
    anchor_center = (anchor[1] + anchor[3]) / 2.0
    line_center = (line_bbox[1] + line_bbox[3]) / 2.0
    return abs(anchor_center - line_center) - max(0.0, vertical_overlap) * 10.0


def _free_formula_intervals(
    baseline: float,
    x0: float,
    x1: float,
    blockers: Sequence[BBox],
    size: float,
) -> List[Tuple[float, float, float]]:
    if x1 <= x0:
        return []
    spans = sorted(
        (
            max(x0, blocker[0] - _KEEPOUT_PAD),
            min(x1, blocker[2] + _KEEPOUT_PAD),
        )
        for blocker in blockers
        if blocker[2] > x0 and blocker[0] < x1
    )
    output: List[Tuple[float, float, float]] = []
    cursor = x0
    min_width = max(8.0, size * 1.25)
    for span_x0, span_x1 in spans:
        if span_x0 - cursor >= min_width:
            output.append((baseline, cursor, span_x0))
        cursor = max(cursor, span_x1)
    if x1 - cursor >= min_width:
        output.append((baseline, cursor, x1))
    return output


def _demote_unanchorable_math_blocks(
    page_items: List[Tuple[TextBlock, str]],
    centered_flags: Sequence[bool],
    *,
    font_pack: FontPack,
    min_font_size: float,
    font_scale: float,
    margin: float,
) -> List[Tuple[TextBlock, str]]:
    """Flow formulas as inline clips when in-place anchoring cannot work.

    Anchored math keeps the source glyphs and threads the translation
    between them on the original line grid. When that layout is infeasible
    the renderer would fall back to squeezing the formula as styled text
    next to the surviving source glyphs. Deciding before redaction lets the
    demoted block erase its source math and render sprite clips instead.
    """
    try:
        import fitz
    except ImportError as exc:
        raise RuntimeError("PyMuPDF is required. Install with: pip install -e .") from exc

    updated: List[Tuple[TextBlock, str]] = []
    for index, (block, text) in enumerate(page_items):
        if not _uses_fixed_source_math(block):
            updated.append((block, text))
            continue
        rect = shrink_rect(fitz.Rect(block.bbox), margin)
        if rect.width <= 1 or rect.height <= 1:
            updated.append((block, text))
            continue
        fonts = font_pack.fonts_for(block.bold)
        bold_fonts = font_pack.fonts_for(True)
        min_size = effective_min_font_size(block, min_font_size)
        requested = requested_translation_font_size(
            block,
            min_font_size,
            font_scale,
        )
        centered = bool(centered_flags[index]) if index < len(centered_flags) else False
        anchored = _formula_anchored_layout(
            block,
            text,
            rect,
            fonts,
            bold_fonts,
            requested,
            min_size,
            centered,
        )
        if anchored is None or anchored[0] < requested * _FIXED_MATH_MIN_FONT_SCALE:
            block = replace(block, flow_inline_math=True)
        updated.append((block, text))
    return updated


def translated_text_fits(
    block: TextBlock,
    text: str,
    font_pack: FontPack,
    font_size: float,
    min_font_size: float,
    margin: float,
    centered: bool = False,
) -> bool:
    try:
        import fitz
    except ImportError as exc:
        raise RuntimeError("PyMuPDF is required. Install with: pip install -e .") from exc

    rect = shrink_rect(fitz.Rect(block.bbox), margin)
    if rect.width <= 1 or rect.height <= 1:
        return False
    fonts = font_pack.fonts_for(block.bold)
    bold_fonts = font_pack.fonts_for(True)
    min_size = effective_min_font_size(block, min_font_size)
    render_text = _translation_text_for_render(text)
    preserve_source_math = _uses_fixed_source_math(block)
    if preserve_source_math:
        anchored = _formula_anchored_layout(
            block,
            text,
            rect,
            fonts,
            bold_fonts,
            font_size,
            min_size,
            centered,
        )
        if (
            anchored is not None
            and anchored[0] >= font_size * _FIXED_MATH_MIN_FONT_SCALE
        ):
            return anchored[1]
        tokens = tokenize_text(render_text)
    else:
        tokens = _tokenize_translation_with_formula_clips(text, block)
    apply_inline_bold(tokens, block, render_text)
    if not tokens:
        return True

    if block.nowrap:
        width = sum(token_width(token, fonts, font_size, bold_fonts) for token in tokens)
        if width <= rect.width or width <= 0:
            return True
        scaled_size = font_size * rect.width / width
        return scaled_size >= min_size * 0.8

    keepouts = _block_keepouts(block, rect)
    layout_fonts = [font for font, _ in [*fonts, *bold_fonts]]
    ascent = max(
        (max(0.0, float(font.ascender)) for font in layout_fonts),
        default=0.82,
    )
    descent = max(
        (abs(min(0.0, float(font.descender))) for font in layout_fonts),
        default=0.24,
    )
    size = font_size
    while size >= min_size - 1e-6:
        if keepouts:
            for leading in leading_options(block):
                slots = keepout_line_slots(
                    rect,
                    size,
                    leading,
                    ascent,
                    keepouts,
                    descent=descent,
                )
                if not slots:
                    continue
                widths = [x1 - x0 for (_, x0, x1) in slots]
                lines = break_lines(
                    tokens,
                    fonts,
                    size,
                    rect.width,
                    prefer_space_break=centered and block.block_type != "caption",
                    bold_fonts=bold_fonts,
                    line_widths=widths,
                )
                if block.block_type == "title":
                    lines = balance_centered_title_lines(lines, rect.width)
                adjusted_slots = _formula_aware_slot_baselines(
                    lines,
                    slots,
                    size,
                    rect,
                    keepouts,
                    fonts,
                    bold_fonts,
                )
                if adjusted_slots is not None:
                    return True
            size -= _FONT_SIZE_SEARCH_STEP
            continue
        hanging_indent = 0.0 if centered else _list_hanging_indent(block, rect.width)
        lines = break_lines(
            tokens,
            fonts,
            size,
            rect.width - hanging_indent,
            prefer_space_break=centered and block.block_type != "caption",
            bold_fonts=bold_fonts,
            line_widths=[rect.width] if hanging_indent else None,
        )
        if block.block_type == "title":
            lines = balance_centered_title_lines(lines, rect.width)
        for leading in leading_options(block):
            if line_block_height(
                lines,
                size,
                leading,
                fonts,
                bold_fonts,
            ) <= rect.height:
                return True
        size -= _FONT_SIZE_SEARCH_STEP
    return False


def insert_translated_text(
    page: object,
    block: TextBlock,
    text: str,
    font_pack: FontPack,
    font_size: float,
    min_font_size: float,
    margin: float,
    centered: bool = False,
    source_document: Optional[object] = None,
) -> bool:
    """Typeset `text` into the block's bbox with the CJK engine.

    Returns True when the text fits the bbox at >= min_font_size.
    """
    try:
        import fitz
    except ImportError as exc:
        raise RuntimeError("PyMuPDF is required. Install with: pip install -e .") from exc

    rect = shrink_rect(fitz.Rect(block.bbox), margin)
    if rect.width <= 1 or rect.height <= 1:
        return False
    fonts = font_pack.fonts_for(block.bold)
    bold_fonts = font_pack.fonts_for(True)
    min_size = effective_min_font_size(block, min_font_size)
    render_text = _translation_text_for_render(text)
    preserve_source_math = _uses_fixed_source_math(block)
    if preserve_source_math:
        anchored = _formula_anchored_layout(
            block,
            text,
            rect,
            fonts,
            bold_fonts,
            font_size,
            min_size,
            centered,
        )
        if (
            anchored is not None
            and anchored[0] >= font_size * _FIXED_MATH_MIN_FONT_SCALE
        ):
            size, fitted, segment_layouts = anchored
            for lines, slots in segment_layouts:
                for index, line in enumerate(lines):
                    baseline, slot_x0, slot_x1 = slots[index]
                    line_rect = fitz.Rect(slot_x0, rect.y0, slot_x1, rect.y1)
                    render_line(
                        page,
                        line,
                        line_rect,
                        fonts,
                        size,
                        block.color,
                        baseline,
                        centered,
                        False,
                        bold_fonts,
                    )
            return fitted
        tokens = tokenize_text(render_text)
    else:
        tokens = _tokenize_translation_with_formula_clips(text, block)
    apply_inline_bold(tokens, block, render_text)
    if not tokens:
        return True

    if block.nowrap:
        # Table cell: one line at the original anchor, shrunk to the cell width.
        for token in tokens:
            token.width = token_width(token, fonts, font_size, bold_fonts)
        render_single_line(
            page,
            tokens,
            rect,
            fonts,
            font_size,
            block.color,
            False,
            min_size,
            bold_fonts,
            source_document=source_document,
        )
        return True

    layout_fonts = [font for font, _ in [*fonts, *bold_fonts]]
    ascent = max(
        (max(0.0, float(font.ascender)) for font in layout_fonts),
        default=0.82,
    )
    descent = max(
        (abs(min(0.0, float(font.descender))) for font in layout_fonts),
        default=0.24,
    )
    keepouts = _block_keepouts(block, rect)
    slot_layout: Optional[Tuple[float, List[List[_Token]], List[Tuple[float, float, float]]]] = None
    if keepouts:
        size = font_size
        while size >= min_size - 1e-6 and slot_layout is None:
            for leading in leading_options(block):
                slots = keepout_line_slots(
                    rect,
                    size,
                    leading,
                    ascent,
                    keepouts,
                    descent=descent,
                )
                if not slots:
                    continue
                widths = [x1 - x0 for (_, x0, x1) in slots]
                lines = break_lines(
                    tokens,
                    fonts,
                    size,
                    rect.width,
                    prefer_space_break=centered and block.block_type != "caption",
                    bold_fonts=bold_fonts,
                    line_widths=widths,
                )
                adjusted_slots = _formula_aware_slot_baselines(
                    lines,
                    slots,
                    size,
                    rect,
                    keepouts,
                    fonts,
                    bold_fonts,
                )
                if adjusted_slots is not None:
                    slot_layout = (size, lines, adjusted_slots)
                    break
            size -= _FONT_SIZE_SEARCH_STEP
    if slot_layout is not None:
        size, lines, slots = slot_layout
        for index, line in enumerate(lines):
            slot_baseline, slot_x0, slot_x1 = slots[index]
            line_rect = fitz.Rect(slot_x0, rect.y0, slot_x1, rect.y1)
            is_last = index == len(lines) - 1
            justify = not centered and not is_last
            render_line(
                page,
                line,
                line_rect,
                fonts,
                size,
                block.color,
                slot_baseline,
                centered,
                justify,
                bold_fonts,
                source_document,
            )
        return True

    hanging_indent = 0.0 if centered else _list_hanging_indent(block, rect.width)
    chosen: Optional[Tuple[float, float, List[List[_Token]]]] = None
    size = font_size
    while size >= min_size - 1e-6:
        lines = break_lines(
            tokens,
            fonts,
            size,
            rect.width - hanging_indent,
            prefer_space_break=centered and block.block_type != "caption",
            bold_fonts=bold_fonts,
            line_widths=[rect.width] if hanging_indent else None,
        )
        for leading in leading_options(block):
            height = line_block_height(
                lines,
                size,
                leading,
                fonts,
                bold_fonts,
            )
            available = rect.height
            if block.block_type == "caption" and len(lines) == 1:
                # A single caption line renders top-aligned inside the source
                # caption row; only its CJK ink needs to fit (~0.88em ascent
                # plus ~0.12em descent, not the 1.2-1.4em glyph box), and the
                # caption row keeps its own clearance to the rule below, so
                # gate on the unshrunk row height. Otherwise the Chinese
                # caption drops far below caption scale (observed 5.7pt
                # against a 10pt source row).
                ascent, descent = _line_vertical_metrics(
                    lines[0], size, fonts, bold_fonts
                )
                height = min(ascent, size * 0.88) + min(descent, size * 0.14)
                available = max(rect.height, block.bbox[3] - block.bbox[1] - 1.0)
            if height <= available:
                chosen = (size, leading, lines)
                break
        if chosen:
            break
        size -= _FONT_SIZE_SEARCH_STEP

    fitted = chosen is not None
    if chosen is None:
        # The compressed fallback packs the full rect width on every line.
        hanging_indent = 0.0
        chosen = choose_compressed_layout(
            tokens,
            fonts,
            rect.width,
            rect.height,
            min_size,
            centered,
            bold_fonts,
        )

    size, leading, lines = chosen
    if block.block_type == "title":
        lines = balance_centered_title_lines(lines, rect.width)

    if len(lines) == 1:
        render_single_line(
            page,
            lines[0],
            rect,
            fonts,
            size,
            block.color,
            centered,
            min_size,
            bold_fonts,
            top_aligned=block.block_type == "caption",
            source_document=source_document,
        )
        return fitted

    baselines = _line_baselines(
        lines,
        size,
        leading,
        rect.y0,
        fonts,
        bold_fonts,
    )
    continuation_rect = (
        fitz.Rect(rect.x0 + hanging_indent, rect.y0, rect.x1, rect.y1)
        if hanging_indent
        else rect
    )
    for index, (line, baseline) in enumerate(zip(lines, baselines)):
        is_last = index == len(lines) - 1
        justify = not centered and not is_last
        render_line(
            page,
            line,
            rect if index == 0 else continuation_rect,
            fonts,
            size,
            block.color,
            baseline,
            centered,
            justify,
            bold_fonts,
            source_document,
        )
    return fitted


_LIST_MARKER_LEAD_RE = re.compile(
    r"^(?:[•◦▪●▫■□‣⁃–—-]|\(?(?:\d{1,3}|[a-zA-Z]|[ivxIVX]{1,4})[.)\]]|\[\d{1,3}\])\s+"
)


def _list_hanging_indent(block: TextBlock, rect_width: float) -> float:
    """Continuation indent a list item carried in the source PDF.

    A bulleted or numbered item wraps its second and later lines under the
    item text, not under the marker. The source line boxes expose that offset
    directly; reuse it so the translated item keeps the same hanging shape
    instead of returning to the marker column.
    """
    if block.nowrap or block.block_type not in {"body", "list", "formula_prose"}:
        return 0.0
    plain = " ".join(strip_sentinels(block.text).split()).lstrip()
    if not _LIST_MARKER_LEAD_RE.match(plain):
        return 0.0
    line_boxes = [
        box
        for box in (block.source_line_bboxes or ())
        if box[2] - box[0] > 0.0
    ]
    if len(line_boxes) < 2:
        return 0.0
    rows = sorted(line_boxes, key=lambda box: (box[1], box[0]))
    first_left = rows[0][0]
    continuation_lefts = [box[0] for box in rows[1:] if box[1] >= rows[0][3] - 1.0]
    if not continuation_lefts:
        return 0.0
    indent = statistics.median(continuation_lefts) - first_left
    if indent < 3.0 or indent > max(24.0, block.font_size * 3.0):
        return 0.0
    if indent > rect_width * 0.4:
        return 0.0
    return float(indent)


def line_block_height(
    lines: Sequence[Sequence[_Token]],
    size: float,
    leading: float,
    fonts: Optional[Sequence[Tuple[object, str]]] = None,
    bold_fonts: Optional[Sequence[Tuple[object, str]]] = None,
) -> float:
    if not lines:
        return 0.0
    baselines = _line_baselines(
        lines,
        size,
        leading,
        0.0,
        fonts,
        bold_fonts,
    )
    _, final_descent = _line_vertical_metrics(
        lines[-1],
        size,
        fonts,
        bold_fonts,
    )
    return baselines[-1] + final_descent


# Noto CJK font files carry extreme vertical metrics (ascender 1.15em,
# descender 0.29em) sized for kana/hangul coverage; CJK ink actually spans
# about [-0.12, 0.88]em. Feeding the raw file metrics into line stacking
# forces a 1.5em pitch floor, so two Chinese lines need 2.86x the font size
# and can never fit an English-sized bbox at body scale (MemoryWAM p3 body
# shrank to 6.9pt). Cap the per-glyph contribution at typographic bounds;
# Latin fonts sit below these caps already, and formula tokens keep their
# measured source ink.
_LINE_METRIC_ASCENT_CAP = 0.92
_LINE_METRIC_DESCENT_CAP = 0.25


def _line_vertical_metrics(
    line: Sequence[_Token],
    size: float,
    fonts: Optional[Sequence[Tuple[object, str]]] = None,
    bold_fonts: Optional[Sequence[Tuple[object, str]]] = None,
) -> Tuple[float, float]:
    """Return font-backed ascent/descent, including stamped source formulas."""
    ascent = size * 0.82
    descent = size * 0.24
    for token in line:
        if token.kind == "formula" and token.source_bbox is not None:
            source_height = max(0.1, token.source_bbox[3] - token.source_bbox[1])
            target_height = source_height * _formula_clip_scale(
                token.source_bbox,
                size,
                token.source_size,
            )
            baseline_ratio = token.source_baseline_ratio
            ascent = max(ascent, target_height * baseline_ratio)
            descent = max(descent, target_height * (1.0 - baseline_ratio))
            continue
        if token.kind == "space" or not fonts:
            continue
        active_fonts = token_fonts(token, fonts, bold_fonts)
        for char in token.text:
            selected = next(
                (
                    font
                    for font, _ in _fonts_for_char(char, active_fonts)
                    if font.has_glyph(ord(char))
                ),
                active_fonts[0][0],
            )
            char_ascent = min(
                max(0.0, float(selected.ascender)), _LINE_METRIC_ASCENT_CAP
            )
            char_descent = min(
                abs(min(0.0, float(selected.descender))), _LINE_METRIC_DESCENT_CAP
            )
            ascent = max(ascent, char_ascent * size)
            descent = max(descent, char_descent * size)
    return ascent, descent


def _line_baselines(
    lines: Sequence[Sequence[_Token]],
    size: float,
    leading: float,
    top: float,
    fonts: Optional[Sequence[Tuple[object, str]]] = None,
    bold_fonts: Optional[Sequence[Tuple[object, str]]] = None,
) -> List[float]:
    if not lines:
        return []
    metrics = [
        _line_vertical_metrics(line, size, fonts, bold_fonts)
        for line in lines
    ]
    baselines = [top + metrics[0][0]]
    for index in range(1, len(lines)):
        _previous_ascent, previous_descent = metrics[index - 1]
        current_ascent, _ = metrics[index]
        baselines.append(
            max(
                baselines[-1] + size * leading,
                baselines[-1] + previous_descent + current_ascent + size * 0.06,
            )
        )
    return baselines


def render_single_line(
    page: object,
    line: Sequence[_Token],
    rect: object,
    fonts: Sequence[Tuple[object, str]],
    size: float,
    color: Color,
    centered: bool,
    min_font_size: float,
    bold_fonts: Optional[Sequence[Tuple[object, str]]] = None,
    top_aligned: bool = False,
    source_document: Optional[object] = None,
) -> None:
    """Single-line blocks (headings, footers, captions cells): vertically
    centred; shrinks to the rect width when necessary."""
    width = sum(token.width for token in line)
    if width > rect.width and width > 0:
        scale = rect.width / width
        size = max(min_font_size * 0.8, size * scale)
        for token in line:
            token.width = token_width(token, fonts, size, bold_fonts)
        width = sum(token.width for token in line)
    visual_ascent, visual_descent = _line_vertical_metrics(
        line,
        size,
        fonts,
        bold_fonts,
    )
    if top_aligned:
        baseline = rect.y0 + visual_ascent
    else:
        baseline = rect.y0 + (rect.height + visual_ascent - visual_descent) / 2.0
        if visual_ascent + visual_descent <= rect.height:
            baseline = max(rect.y0 + visual_ascent, baseline)
            baseline = min(rect.y1 - visual_descent, baseline)
    x_start = rect.x0 + max(0.0, (rect.width - width) / 2.0) if centered else rect.x0
    emit_tokens(
        page,
        line,
        fonts,
        size,
        color,
        x_start,
        baseline,
        {},
        bold_fonts,
        source_document,
    )


def render_line(
    page: object,
    line: Sequence[_Token],
    rect: object,
    fonts: Sequence[Tuple[object, str]],
    size: float,
    color: Color,
    baseline: float,
    centered: bool,
    justify: bool,
    bold_fonts: Optional[Sequence[Tuple[object, str]]] = None,
    source_document: Optional[object] = None,
) -> None:
    natural = sum(token.width for token in line)
    increments: Dict[int, float] = {}
    x_start = rect.x0
    if centered:
        x_start = rect.x0 + max(0.0, (rect.width - natural) / 2.0)
    elif justify and natural < rect.width:
        gaps = stretchable_gaps(line)
        if gaps:
            extra = rect.width - natural
            per_gap = extra / len(gaps)
            if per_gap <= size * MAX_JUSTIFY_GAP_EM:
                increments = {index: per_gap for index in gaps}
    emit_tokens(
        page,
        line,
        fonts,
        size,
        color,
        x_start,
        baseline,
        increments,
        bold_fonts,
        source_document,
    )


def _trim_formula_clip_against_foreign_ink(
    document: object,
    page_index: int,
    clip: BBox,
    *,
    max_trim_ratio: float = 0.43,
) -> BBox:
    """Shrink a formula stamp clip so neighboring-line glyphs are excluded.

    Inline-formula spans (e.g. a CMSY bullet) can be much taller than their
    visible ink. Stamping with the raw span bbox copies ascenders/descenders
    of adjacent source lines into the output ("y g" residue). Trim the clip
    edge past intruding spans that are mostly outside the clip, bounded so a
    genuine tall formula is never cut by more than ``max_trim_ratio``.
    """
    try:
        # Cache spans on the document itself: module-level id()-keyed caches
        # collide once CPython reuses object ids across documents.
        cache: Dict[int, List[BBox]] = getattr(document, "_pdfzh_span_cache", None)
        if cache is None:
            cache = {}
            document._pdfzh_span_cache = cache
        spans = cache.get(page_index)
        if spans is None:
            spans = [
                tuple(float(value) for value in span["bbox"])
                for block in document[page_index].get_text("dict").get("blocks", [])
                if block.get("type") == 0
                for line in block.get("lines", [])
                for span in line.get("spans", [])
            ]
            cache[page_index] = spans

        x0, y0, x1, y1 = clip
        width = x1 - x0
        height = y1 - y0
        if width <= 0 or height <= 0:
            return clip
        max_trim_x = width * max_trim_ratio
        max_trim_y = height * max_trim_ratio
        foreign_spans: List[BBox] = []
        for sx0, sy0, sx1, sy1 in spans:
            if sx1 <= x0 or sx0 >= x1:
                continue
            span_area = max(0.1, (sx1 - sx0) * (sy1 - sy0))
            inside = bbox_intersection_area((sx0, sy0, sx1, sy1), clip)
            if inside / span_area >= 0.7:
                continue  # part of the formula itself
            foreign_spans.append((sx0, sy0, sx1, sy1))

        # Resolve line-above / line-below intrusions first. A lower prose line
        # can cross the raw clip's left edge while its ink disappears entirely
        # once the vertical clip is tightened; using it for horizontal trim
        # first would erase the formula prefix.
        new_y0, new_y1 = y0, y1
        for _sx0, sy0, _sx1, sy1 in foreign_spans:
            if sy0 < y0 < sy1 and sy1 - y0 <= max_trim_y:
                new_y0 = max(new_y0, sy1 + _FORMULA_CLIP_FOREIGN_GAP)
            elif sy0 < y1 < sy1 and y1 - sy0 <= max_trim_y:
                new_y1 = min(new_y1, sy0 - _FORMULA_CLIP_FOREIGN_GAP)

        # Span bboxes carry ascent/descent headroom, so cramped source lines
        # interleave: trimming to a straddling span's bbox edge routinely
        # slices the formula's own sub/superscripts (2026-08-11 production
        # review: decapitated Sigma limits). Whenever a vertical trim moves
        # into the clip, relocate the cut to the nearest whitespace gap in
        # the actual ink profile; only the bbox-based edge is trusted when
        # no clean gap exists.
        if new_y0 > y0 + 0.05 or new_y1 < y1 - 0.05:
            profile = _clip_row_ink_profile(document, page_index, clip)
            if profile:
                if new_y0 > y0 + 0.05:
                    gap_edge = _ink_gap_edge_below(profile, y0, new_y0)
                    if gap_edge is None:
                        # Tight leading may leave no fully white raster row.
                        # Cut at the thinnest row instead of the font bbox,
                        # which otherwise retains a hairline of foreign ink.
                        gap_edge = _least_ink_row_edge(profile, y0, new_y0)
                    if gap_edge is not None:
                        new_y0 = gap_edge
                if new_y1 < y1 - 0.05:
                    gap_edge = _ink_gap_edge_above(profile, y1, new_y1)
                    if gap_edge is None:
                        gap_edge = _least_ink_row_edge(profile, new_y1, y1)
                    if gap_edge is not None:
                        new_y1 = gap_edge

        if new_y1 - new_y0 <= 0:
            return clip

        new_x0, new_x1 = x0, x1
        trimmed_height = new_y1 - new_y0
        for sx0, sy0, sx1, sy1 in foreign_spans:
            vertical_overlap = min(new_y1, sy1) - max(new_y0, sy0)
            if vertical_overlap >= min(trimmed_height, sy1 - sy0) * 0.35:
                if sx0 < x0 < sx1 and sx1 - x0 <= max_trim_x:
                    new_x0 = max(new_x0, sx1 + _FORMULA_CLIP_FOREIGN_GAP)
                elif sx0 < x1 < sx1 and x1 - sx0 <= max_trim_x:
                    new_x1 = min(new_x1, sx0 - _FORMULA_CLIP_FOREIGN_GAP)
        if new_x1 - new_x0 <= 0 or new_y1 - new_y0 <= 0:
            return clip
        return (new_x0, new_y0, new_x1, new_y1)
    except Exception:
        return clip


def _source_region_has_visible_ink(
    document: object,
    page_index: int,
    clip: BBox,
) -> bool:
    """Verify that a candidate formula stamp contains painted source ink."""
    try:
        import fitz

        rect = fitz.Rect(clip) & document[page_index].rect
        if rect.width <= 0.2 or rect.height <= 0.2:
            return False
        pixmap = document[page_index].get_pixmap(
            matrix=fitz.Matrix(4.0, 4.0),
            clip=rect,
            colorspace=fitz.csGRAY,
            alpha=True,
            annots=False,
        )
        alpha = pixmap.samples[1::2]
        return sum(value >= 24 for value in alpha) >= 2
    except Exception:
        return False


def _select_formula_source_rect(
    document: object,
    page_index: int,
    core_rect: BBox,
    padded_rect: BBox,
) -> BBox:
    """Choose a trimmed formula clip only when it still contains visible ink."""
    trimmed = _trim_formula_clip_against_foreign_ink(
        document,
        page_index,
        padded_rect,
    )
    for candidate in (trimmed, padded_rect, core_rect):
        if _source_region_has_visible_ink(document, page_index, candidate):
            return candidate
    raise ValueError("formula source region has no visible ink")


_CLIP_PROFILE_ZOOM = 6.0
_CLIP_PROFILE_INK_THRESHOLD = 0.008
_CLIP_PROFILE_MIN_GAP_ROWS = 3


def _clip_row_ink_profile(
    document: object,
    page_index: int,
    clip: BBox,
) -> List[Tuple[float, float]]:
    """(y, ink_ratio) per rendered row of the clip, top to bottom."""
    try:
        import fitz

        rect = fitz.Rect(clip) & document[page_index].rect
        if rect.width <= 0.5 or rect.height <= 0.5:
            return []
        pixmap = document[page_index].get_pixmap(
            matrix=fitz.Matrix(_CLIP_PROFILE_ZOOM, _CLIP_PROFILE_ZOOM),
            clip=rect,
            colorspace=fitz.csGRAY,
            alpha=False,
        )
        width = pixmap.width
        if not width:
            return []
        profile: List[Tuple[float, float]] = []
        for row_index in range(pixmap.height):
            row = pixmap.samples[row_index * width : (row_index + 1) * width]
            ink = sum(1 for sample in row if sample < 205) / width
            profile.append((rect.y0 + row_index / _CLIP_PROFILE_ZOOM, ink))
        return profile
    except Exception:
        return []


def _ink_whitespace_gaps(
    profile: Sequence[Tuple[float, float]],
) -> List[Tuple[float, float]]:
    gaps: List[Tuple[float, float]] = []
    start: Optional[float] = None
    clean_rows = 0
    for y, ink in profile:
        if ink < _CLIP_PROFILE_INK_THRESHOLD:
            if start is None:
                start = y
            clean_rows += 1
        else:
            if start is not None and clean_rows >= _CLIP_PROFILE_MIN_GAP_ROWS:
                gaps.append((start, y))
            start = None
            clean_rows = 0
    if start is not None and clean_rows >= _CLIP_PROFILE_MIN_GAP_ROWS:
        gaps.append((start, profile[-1][0]))
    return gaps


def _least_ink_row_edge(
    profile: Sequence[Tuple[float, float]],
    lo: float,
    hi: float,
) -> Optional[float]:
    """Return the least-damaging raster cut inside a tight ink band."""
    window = [(y, ink) for y, ink in profile if lo <= y <= hi]
    if not window:
        return None
    return min(window, key=lambda item: item[1])[0]


def _ink_gap_edge_below(
    profile: Sequence[Tuple[float, float]],
    clip_top: float,
    proposed: float,
) -> Optional[float]:
    """Whitespace midpoint nearest the proposed (lowered) top edge."""
    candidates = [
        (top + bottom) / 2.0
        for top, bottom in _ink_whitespace_gaps(profile)
        if bottom > clip_top
    ]
    if not candidates:
        return None
    return min(candidates, key=lambda midpoint: abs(midpoint - proposed))


def _ink_gap_edge_above(
    profile: Sequence[Tuple[float, float]],
    clip_bottom: float,
    proposed: float,
) -> Optional[float]:
    """Whitespace midpoint nearest the proposed (raised) bottom edge."""
    candidates = [
        (top + bottom) / 2.0
        for top, bottom in _ink_whitespace_gaps(profile)
        if top < clip_bottom
    ]
    if not candidates:
        return None
    return min(candidates, key=lambda midpoint: abs(midpoint - proposed))


def _insert_source_region_raster(
    page: object,
    source_document: object,
    source_page_index: int,
    source_rect: object,
    target_rect: object,
) -> None:
    """Paint one source region without importing its page-wide text layer."""
    import fitz

    source_rect = fitz.Rect(source_rect)
    target_rect = fitz.Rect(target_rect)
    source_width = max(0.1, source_rect.width)
    source_height = max(0.1, source_rect.height)
    target_scale = max(
        target_rect.width / source_width,
        target_rect.height / source_height,
    )
    # Five device pixels per output point retains formula scripts at 360 dpi.
    # Bound source zoom to avoid pathological memory use on malformed clips.
    zoom = min(8.0, max(3.0, target_scale * 5.0))
    pixmap = source_document[source_page_index].get_pixmap(
        matrix=fitz.Matrix(zoom, zoom),
        clip=source_rect,
        alpha=True,
        annots=False,
    )
    # Add transparent device pixels after all source-side trimming. Expanding
    # the source clip here would reintroduce neighbouring text; padding the
    # RGBA sprite instead preserves the exact visible formula and guarantees
    # a clean alpha margin for ascenders, descenders, and QA edge checks.
    pad_pixels = max(3, round(zoom * 0.8))
    padded = fitz.Pixmap(
        pixmap.colorspace,
        fitz.IRect(
            0,
            0,
            pixmap.width + pad_pixels * 2,
            pixmap.height + pad_pixels * 2,
        ),
        True,
    )
    padded.clear_with(0)
    padded.set_alpha(bytes(padded.width * padded.height))
    # Pixmap.copy uses absolute pixmap coordinates. A clipped source pixmap
    # retains its page-space origin (often hundreds of device pixels away),
    # so copying into a zero-origin destination without rebasing silently
    # produces a fully transparent image.
    pixmap.set_origin(pad_pixels, pad_pixels)
    padded.copy(pixmap, pixmap.irect)
    pad_x = pad_pixels * target_rect.width / max(1, pixmap.width)
    pad_y = pad_pixels * target_rect.height / max(1, pixmap.height)
    padded_target = fitz.Rect(
        target_rect.x0 - pad_x,
        target_rect.y0 - pad_y,
        target_rect.x1 + pad_x,
        target_rect.y1 + pad_y,
    )
    page.insert_image(
        padded_target,
        pixmap=padded,
        keep_proportion=False,
        overlay=True,
    )


def _formula_atom_masked_pixmap(
    source_document: object,
    source_page_index: int,
    source_rect: object,
    atom_bboxes: Sequence[BBox],
    zoom: float,
    exclude_bboxes: Sequence[BBox] = (),
) -> object:
    """Render one formula hull while making all non-math source ink transparent."""
    import fitz

    source_page = source_document[source_page_index]
    source_rect = fitz.Rect(source_rect) & source_page.rect
    if source_rect.width <= 0.1 or source_rect.height <= 0.1:
        raise ValueError("formula source region is empty")
    pixmap = source_page.get_pixmap(
        matrix=fitz.Matrix(zoom, zoom),
        clip=source_rect,
        alpha=True,
        annots=False,
    )
    if not pixmap.alpha:
        raise ValueError("formula source raster has no alpha channel")

    source_alpha = pixmap.samples[pixmap.n - 1 :: pixmap.n]
    masked_alpha = bytearray(len(source_alpha))
    # Span boxes already describe individual math glyphs. A sub-point margin
    # retains antialiasing at their edges without reopening the neighbouring
    # prose bands enclosed by a tall fraction or radical hull.
    atom_margin = 0.35
    for bbox in atom_bboxes:
        atom = fitz.Rect(
            bbox[0] - atom_margin,
            bbox[1] - atom_margin,
            bbox[2] + atom_margin,
            bbox[3] + atom_margin,
        ) & source_rect
        if atom.width <= 0.0 or atom.height <= 0.0:
            continue
        x0 = max(0, math.floor(atom.x0 * zoom) - pixmap.x)
        y0 = max(0, math.floor(atom.y0 * zoom) - pixmap.y)
        x1 = min(pixmap.width, math.ceil(atom.x1 * zoom) - pixmap.x)
        y1 = min(pixmap.height, math.ceil(atom.y1 * zoom) - pixmap.y)
        for row in range(y0, y1):
            start = row * pixmap.width + x0
            stop = row * pixmap.width + x1
            masked_alpha[start:stop] = source_alpha[start:stop]
    # Oversized TeX math-font boxes can enclose an adjacent prose row. Those
    # pixels belong to known prose spans and must never hitchhike in a formula
    # sprite, even though they lie inside the formula glyph's reported bbox.
    owned_atoms: List[object] = []
    for bbox in exclude_bboxes:
        exclusion = fitz.Rect(bbox) & source_rect
        if exclusion.width <= 0.0 or exclusion.height <= 0.0:
            continue
        for atom_bbox in atom_bboxes:
            atom = fitz.Rect(atom_bbox) & source_rect
            atom_area = max(0.1, atom.width * atom.height)
            overlap = atom & exclusion
            if overlap.width * overlap.height >= atom_area * 0.5:
                owned_atoms.append(atom)
        x0 = max(0, math.floor(exclusion.x0 * zoom) - pixmap.x)
        y0 = max(0, math.floor(exclusion.y0 * zoom) - pixmap.y)
        x1 = min(pixmap.width, math.ceil(exclusion.x1 * zoom) - pixmap.x)
        y1 = min(pixmap.height, math.ceil(exclusion.y1 * zoom) - pixmap.y)
        for row in range(y0, y1):
            start = row * pixmap.width + x0
            stop = row * pixmap.width + x1
            masked_alpha[start:stop] = b"\x00" * (stop - start)
    # A prose span and a math span can share most of the same font box even
    # when they describe different glyphs on one baseline. In that case the
    # math span is the authoritative owner; otherwise exclusions erase Greek
    # atoms while leaving only their accents or relation signs visible.
    for atom in owned_atoms:
        protected = fitz.Rect(
            atom.x0 - atom_margin,
            atom.y0 - atom_margin,
            atom.x1 + atom_margin,
            atom.y1 + atom_margin,
        ) & source_rect
        x0 = max(0, math.floor(protected.x0 * zoom) - pixmap.x)
        y0 = max(0, math.floor(protected.y0 * zoom) - pixmap.y)
        x1 = min(pixmap.width, math.ceil(protected.x1 * zoom) - pixmap.x)
        y1 = min(pixmap.height, math.ceil(protected.y1 * zoom) - pixmap.y)
        for row in range(y0, y1):
            start = row * pixmap.width + x0
            stop = row * pixmap.width + x1
            masked_alpha[start:stop] = source_alpha[start:stop]
    if not any(masked_alpha):
        raise ValueError("formula atom mask contains no visible ink")
    pixmap.set_alpha(bytes(masked_alpha), premultiply=1)
    return pixmap


def _insert_source_formula_raster(
    page: object,
    source_document: object,
    source_page_index: int,
    source_rect: object,
    atom_bboxes: Sequence[BBox],
    target_rect: object,
    exclude_bboxes: Sequence[BBox] = (),
) -> None:
    """Paint all math atoms as one masked sprite, preserving their geometry."""
    import fitz

    source_rect = fitz.Rect(source_rect)
    target_rect = fitz.Rect(target_rect)
    source_width = max(0.1, source_rect.width)
    source_height = max(0.1, source_rect.height)
    target_scale = max(
        target_rect.width / source_width,
        target_rect.height / source_height,
    )
    zoom = min(8.0, max(3.0, target_scale * 5.0))
    pixmap = _formula_atom_masked_pixmap(
        source_document,
        source_page_index,
        source_rect,
        atom_bboxes,
        zoom,
        exclude_bboxes,
    )

    pad_pixels = max(3, round(zoom * 0.8))
    padded = fitz.Pixmap(
        pixmap.colorspace,
        fitz.IRect(
            0,
            0,
            pixmap.width + pad_pixels * 2,
            pixmap.height + pad_pixels * 2,
        ),
        True,
    )
    padded.clear_with(0)
    padded.set_alpha(bytes(padded.width * padded.height))
    pixmap.set_origin(pad_pixels, pad_pixels)
    padded.copy(pixmap, pixmap.irect)
    pad_x = pad_pixels * target_rect.width / max(1, pixmap.width)
    pad_y = pad_pixels * target_rect.height / max(1, pixmap.height)
    padded_target = fitz.Rect(
        target_rect.x0 - pad_x,
        target_rect.y0 - pad_y,
        target_rect.x1 + pad_x,
        target_rect.y1 + pad_y,
    )
    page.insert_image(
        padded_target,
        pixmap=padded,
        keep_proportion=False,
        overlay=True,
    )


def emit_tokens(
    page: object,
    line: Sequence[_Token],
    fonts: Sequence[Tuple[object, str]],
    size: float,
    color: Color,
    x_start: float,
    baseline: float,
    increments: Dict[int, float],
    bold_fonts: Optional[Sequence[Tuple[object, str]]] = None,
    source_document: Optional[object] = None,
) -> None:
    """Write one typeset line, batching runs that share font and need no
    positional adjustment."""
    x = x_start
    run_chars: List[str] = []
    run_font: Optional[str] = None
    run_size = size
    run_baseline = baseline
    run_x = x

    def flush_run() -> None:
        nonlocal run_chars, run_font
        if run_chars and run_font is not None:
            page.insert_text(
                (run_x, run_baseline),
                "".join(run_chars),
                fontname=run_font,
                fontsize=run_size,
                color=color,
            )
        run_chars = []
        run_font = None

    def emit_hidden_copy_text(
        text: str,
        x_pos: float,
        max_width: Optional[float] = None,
    ) -> None:
        text = _normalize_formula_accessibility_text(text)
        natural_width = sum(char_width(char, fonts, size) for char in text)
        hidden_size = size
        if max_width is not None and natural_width > max_width > 0.0:
            hidden_size = max(size * 0.35, size * max_width / natural_width)
        hidden_x = x_pos
        for char in text:
            alias = pick_font_alias(char, fonts)
            page.insert_text(
                (hidden_x, baseline),
                char,
                fontname=alias,
                fontsize=hidden_size,
                color=color,
                render_mode=3,
            )
            hidden_x += char_width(char, fonts, hidden_size)

    for index, token in enumerate(line):
        gap_after = increments.get(index, 0.0)
        if token.kind == "space":
            flush_run()
            x += token.width + gap_after
            run_x = x
            continue
        formula_guard = size * _INLINE_FORMULA_GUARD_EM if token.kind == "formula" else 0.0
        if formula_guard:
            flush_run()
            x += formula_guard
            run_x = x
        if token.kind == "formula" and token.source_bbox is not None and source_document:
            flush_run()
            try:
                import fitz

                core_rect = fitz.Rect(token.source_bbox)
                formula_width = max(0.1, token.width - formula_guard * 2.0)
                if token.source_atom_bboxes:
                    # A run hull can overlap the prose line above/below even
                    # though every math span is clean (AdaGrad's tall radical
                    # on p5 encloses parts of two English lines). Render the
                    # hull once and alpha-mask it to the math spans. One sprite
                    # retains cross-glyph geometry and cannot develop seams.
                    scale = _formula_clip_scale(
                        token.source_bbox,
                        size,
                        token.source_size,
                    )
                    core_height = max(0.1, core_rect.height) * scale
                    pad_x = 0.25
                    pad_y = max(0.8, token.source_size * 0.12)
                    source_rect = fitz.Rect(
                        core_rect.x0 - pad_x,
                        core_rect.y0 - pad_y,
                        core_rect.x1 + pad_x,
                        core_rect.y1 + pad_y,
                    )
                    target_rect = fitz.Rect(
                        x - pad_x * scale,
                        baseline
                        - core_height * token.source_baseline_ratio
                        - pad_y * scale,
                        x + formula_width + pad_x * scale,
                        baseline
                        + core_height * (1.0 - token.source_baseline_ratio)
                        + pad_y * scale,
                    )
                    _insert_source_formula_raster(
                        page,
                        source_document,
                        token.source_page,
                        source_rect,
                        token.source_atom_bboxes,
                        target_rect,
                        token.source_exclusion_bboxes,
                    )
                    emit_hidden_copy_text(token.text, x, formula_width)
                    x += formula_width + formula_guard
                    if gap_after:
                        x += gap_after
                    run_x = x
                    continue
                # Math glyphs paint past their span bbox (Sigma limits, tall
                # ascenders); a quarter-point margin decapitates them. Pad
                # vertically in proportion to the source size and let the
                # foreign-ink trim below take back neighbour-line bleed. The
                # stamped pixmap has an alpha channel, so surviving padding
                # is transparent and cannot overpaint adjacent lines.
                pad_y = max(0.8, token.source_size * 0.12)
                padded_source_rect = fitz.Rect(
                    core_rect.x0 - 0.25,
                    core_rect.y0 - pad_y,
                    core_rect.x1 + 0.25,
                    core_rect.y1 + pad_y,
                )
                source_rect = fitz.Rect(
                    _select_formula_source_rect(
                        source_document,
                        token.source_page,
                        tuple(core_rect),
                        tuple(padded_source_rect),
                    )
                )
                core_y0 = max(core_rect.y0, source_rect.y0)
                core_y1 = min(core_rect.y1, source_rect.y1)
                # Scale from the core bbox so padding cannot shrink tall
                # formulas through the max-height clamp, and anchor the core
                # on the baseline exactly as before; the padding extends the
                # stamp box symmetrically around it.
                scale = _formula_clip_scale(
                    (source_rect.x0, core_y0, source_rect.x1, core_y1),
                    size,
                    token.source_size,
                )
                pad_top = max(0.0, core_y0 - source_rect.y0)
                pad_bottom = max(0.0, source_rect.y1 - core_y1)
                core_height = max(0.1, core_y1 - core_y0) * scale
                target_rect = fitz.Rect(
                    x,
                    baseline
                    - core_height * token.source_baseline_ratio
                    - pad_top * scale,
                    x + formula_width,
                    baseline
                    + core_height * (1.0 - token.source_baseline_ratio)
                    + pad_bottom * scale,
                )
                _insert_source_region_raster(
                    page,
                    source_document,
                    token.source_page,
                    source_rect,
                    target_rect,
                )
                emit_hidden_copy_text(token.text, x, target_rect.width)
                x += max(0.1, token.width - formula_guard * 2.0) + formula_guard
                if gap_after:
                    x += gap_after
                run_x = x
                continue
            except Exception:
                run_x = x
        active_fonts = token_fonts(token, fonts, bold_fonts)
        if has_script_notation(token.text):
            flush_run()
            emit_hidden_copy_text(token.text, x)
            run_x = x
        for role, text in iter_scripted_text(token.text):
            segment_size, segment_baseline = script_segment_metrics(role, size, baseline)
            for char in text:
                alias = pick_font_alias(char, active_fonts)
                if run_font is None:
                    run_font = alias
                    run_size = segment_size
                    run_baseline = segment_baseline
                    run_x = x
                elif (
                    alias != run_font
                    or abs(segment_size - run_size) > 1e-6
                    or abs(segment_baseline - run_baseline) > 1e-6
                ):
                    flush_run()
                    run_font = alias
                    run_size = segment_size
                    run_baseline = segment_baseline
                    run_x = x
                run_chars.append(char)
                x += char_width(char, active_fonts, segment_size)
        if formula_guard:
            flush_run()
            x += formula_guard
            run_x = x
        if gap_after:
            flush_run()
            x += gap_after
            run_x = x
    flush_run()


def pick_font_alias(char: str, fonts: Sequence[Tuple[object, str]]) -> str:
    for font, alias in _fonts_for_char(char, fonts):
        if font.has_glyph(ord(char)):
            return alias
    return fonts[0][1]


def is_translatable(text: str) -> bool:
    stripped = text.strip()
    if len(stripped) < 2:
        return False
    if not any("A" <= char <= "Z" or "a" <= char <= "z" for char in stripped):
        return False
    if looks_like_math(stripped):
        return False
    return True


# Symbols that only appear in real mathematics. ASCII slash/star/etc. are
# excluded: bibliography lines ("3(2/3/4):265-291, doi:10.1504/...") are full
# of them and must never look like equations.
STRONG_MATH_SYMBOLS = MATH_SYMBOLS - set("/*^_|\\<>~+")


def looks_like_math(text: str) -> bool:
    """Heuristic for display equations: dense math symbols, few plain words."""
    compact = "".join(text.split())
    if len(compact) < 4:
        return False
    greek = sum(1 for char in compact if "\u0370" <= char <= "\u03ff")
    mathsym = sum(
        1
        for char in compact
        if char in STRONG_MATH_SYMBOLS
        or "\u2190" <= char <= "\u22ff"
        or "\u27c0" <= char <= "\u2bff"
        or "\U0001d400" <= char <= "\U0001d7ff"
    )
    score = greek + mathsym
    if score < 2:
        return False
    digits = sum(1 for char in compact if char.isdigit())
    brackets = sum(1 for char in compact if char in "()[]{}")
    ascii_letters = sum(1 for char in compact if char.isascii() and char.isalpha())
    symbolish = score + digits + brackets
    return symbolish / len(compact) >= 0.25 and ascii_letters / len(compact) <= 0.45


def normalize_span_text(text: str) -> str:
    return text.replace("\u00a0", " ")


def union_bbox(bboxes: Iterable[BBox]) -> BBox:
    boxes = list(bboxes)
    return (
        min(box[0] for box in boxes),
        min(box[1] for box in boxes),
        max(box[2] for box in boxes),
        max(box[3] for box in boxes),
    )


def bbox_area(bbox: BBox) -> float:
    return max(0.0, bbox[2] - bbox[0]) * max(0.0, bbox[3] - bbox[1])


def bbox_intersection_area(first: BBox, second: BBox) -> float:
    x0 = max(first[0], second[0])
    y0 = max(first[1], second[1])
    x1 = min(first[2], second[2])
    y1 = min(first[3], second[3])
    return max(0.0, x1 - x0) * max(0.0, y1 - y0)


def bboxes_intersect(first: BBox, second: BBox) -> bool:
    return (
        min(first[2], second[2]) > max(first[0], second[0])
        and min(first[3], second[3]) > max(first[1], second[1])
    )


def bbox_contains_point(bbox: BBox, x: float, y: float) -> bool:
    return bbox[0] <= x <= bbox[2] and bbox[1] <= y <= bbox[3]


def expand_bbox(bbox: BBox, amount: float) -> BBox:
    if amount <= 0:
        return bbox
    return (bbox[0] - amount, bbox[1] - amount, bbox[2] + amount, bbox[3] + amount)


def expand_bbox_to_page(bbox: BBox, amount: float, page_rect: object) -> BBox:
    expanded = expand_bbox(bbox, amount)
    return (
        max(float(page_rect.x0), expanded[0]),
        max(float(page_rect.y0), expanded[1]),
        min(float(page_rect.x1), expanded[2]),
        min(float(page_rect.y1), expanded[3]),
    )


def median_or_default(values: Sequence[float], default: float) -> float:
    if not values:
        return default
    return float(statistics.median(values))


def dominant_color(colors: Sequence[Color]) -> Color:
    if not colors:
        return (0, 0, 0)
    rounded = [(round(r, 2), round(g, 2), round(b, 2)) for r, g, b in colors]
    return max(set(rounded), key=rounded.count)


def int_to_rgb(color: int) -> Color:
    red = ((color >> 16) & 255) / 255.0
    green = ((color >> 8) & 255) / 255.0
    blue = (color & 255) / 255.0
    return (red, green, blue)


def expand_rect(rect: object, amount: float) -> object:
    if amount <= 0:
        return rect
    rect.x0 -= amount
    rect.y0 -= amount
    rect.x1 += amount
    rect.y1 += amount
    return rect


def shrink_rect(rect: object, amount: float) -> object:
    if amount <= 0:
        return rect
    if rect.width > amount * 2:
        rect.x0 += amount
        rect.x1 -= amount
    if rect.height > amount * 2:
        rect.y0 += amount
        rect.y1 -= amount
    return rect


def compact_bbox(bbox: BBox) -> str:
    return "(%.1f, %.1f, %.1f, %.1f)" % bbox


@dataclass
class RenderedBackground:
    samples: bytes
    width: int
    height: int
    channels: int
    scale: float


def render_background(page: object, scale: float = 1.5) -> RenderedBackground:
    try:
        import fitz
    except ImportError as exc:
        raise RuntimeError("PyMuPDF is required. Install with: pip install -e .") from exc

    pixmap = page.get_pixmap(matrix=fitz.Matrix(scale, scale), alpha=False)
    return RenderedBackground(
        samples=pixmap.samples,
        width=pixmap.width,
        height=pixmap.height,
        channels=pixmap.n,
        scale=scale,
    )


def sample_background_color(
    background: RenderedBackground,
    bbox: BBox,
    margin: float,
) -> Color:
    x0, y0, x1, y1 = bbox
    x0 -= margin
    y0 -= margin
    x1 += margin
    y1 += margin
    points = edge_sample_points(x0, y0, x1, y1)
    colors = [sample_pixel(background, x, y) for x, y in points]
    colors = [color for color in colors if color is not None]
    if not colors:
        return (1, 1, 1)
    return median_color(colors)


def edge_sample_points(x0: float, y0: float, x1: float, y1: float) -> List[Tuple[float, float]]:
    points: List[Tuple[float, float]] = []
    fractions = (0.08, 0.25, 0.5, 0.75, 0.92)
    for fraction in fractions:
        x = x0 + (x1 - x0) * fraction
        y = y0 + (y1 - y0) * fraction
        points.append((x, y0))
        points.append((x, y1))
        points.append((x0, y))
        points.append((x1, y))
    points.extend(
        [
            (x0, y0),
            (x1, y0),
            (x0, y1),
            (x1, y1),
        ]
    )
    return points


def sample_pixel(background: RenderedBackground, x: float, y: float) -> Optional[Color]:
    px = int(round(x * background.scale))
    py = int(round(y * background.scale))
    if px < 0 or py < 0 or px >= background.width or py >= background.height:
        return None
    offset = (py * background.width + px) * background.channels
    if offset + 2 >= len(background.samples):
        return None
    return (
        background.samples[offset] / 255.0,
        background.samples[offset + 1] / 255.0,
        background.samples[offset + 2] / 255.0,
    )


def median_color(colors: Sequence[Color]) -> Color:
    reds = sorted(color[0] for color in colors)
    greens = sorted(color[1] for color in colors)
    blues = sorted(color[2] for color in colors)
    middle = len(colors) // 2
    return (reds[middle], greens[middle], blues[middle])
